## 2.  Full source (single file, ready to run)

> **NOTE** – This example uses Flask’s built‑in development server (`debug=True`).  
> For production replace it with a real WSGI server (Gunicorn, uWSGI…) and turn off debug mode.

```python
# app.py
import os
import threading
import uuid
from collections import deque
from pathlib import Path
from typing import Dict

from flask import (
    Flask,
    Response,
    jsonify,
    render_template,
    request,
    send_from_directory,
    session,
    url_for,
)
from werkzeug.utils import secure_filename

# ----------------------------------------------------------------------
# CONFIGURATION
# ----------------------------------------------------------------------
BASE_DIR = Path(__file__).parent.resolve()
UPLOAD_ROOT = BASE_DIR / "static" / "img"          # where we store chunks / final files
UPLOAD_ROOT.mkdir(parents=True, exist_ok=True)

# A *very* small secret – you would normally load this from env
SECRET_KEY = os.urandom(24)

# ----------------------------------------------------------------------
# GLOBAL STATE (in‑memory – replace with Redis/RQ in prod)
# ----------------------------------------------------------------------
app = Flask(__name__)
app.secret_key = SECRET_KEY

# Only one upload may be active at a time
upload_lock = threading.Lock()

# FIFO queue of waiting users (store a random token per user)
queue: deque[str] = deque()

# Map upload token → metadata (filename, original name, size …)
# In a real app this would be a DB table.
UPLOADS: Dict[str, Dict] = {}

# ----------------------------------------------------------------------
# HELPERS
# ----------------------------------------------------------------------
def get_user_token() -> str:
    """
    Return a stable per‑browser token that identifies a participating user.
    If the user does not have one yet we create a random UUID.
    """
    if "upload_token" not in session:
        session["upload_token"] = str(uuid.uuid4())
    return session["upload_token"]

def is_lock_owner(token: str) -> bool:
    """Only the user that created the lock may release it."""
    return upload_lock.locked() and token == session.get("lock_owner")

def allowed_file(filename: str) -> bool:
    """Simple whitelist – extend as needed."""
    # Only allow a limited set of extensions (prevent accidental execution)
    ALLOWED = {".png", ".jpg", ".jpeg", ".gif", ".pdf", ".txt", ".zip"}
    return Path(filename).suffix.lower() in ALLOWED


# ----------------------------------------------------------------------
# ROUTES
# ----------------------------------------------------------------------
@app.get("/")
def index():
    # The template knows the current queue position and lock state.
    token = get_user_token()
    position = (
        list(queue).index(token) + 1 if token in queue else None
    )
    lock_owner = session.get("lock_owner")
    return render_template(
        "index.html",
        in_queue=token in queue,
        position=position,
        lock_owner=lock_owner,
        have_lock=token == lock_owner,
    )


# ----------------------------------------------------------------------
# Queue handling
# ----------------------------------------------------------------------
@app.post("/queue/join")
def queue_join():
    """User asks to be placed at the end of the queue."""
    token = get_user_token()
    if token not in queue and not is_lock_owner(token):
        queue.append(token)
        return jsonify({"msg": "Added to queue", "position": len(queue)}), 202
    # Already waiting or already own the lock
    return jsonify({"msg": "Already in queue or own lock"}), 200


@app.post("/queue/start")
def queue_start():
    """
    Called when the user presses the *Start upload* button.
    If the lock is free and the user is first in line we grant it.
    """
    token = get_user_token()
    if not queue or queue[0] != token:
        return jsonify({"error": "You are not first in line"}), 403

    # Acquire the exclusive lock
    locked = upload_lock.acquire(blocking=False)
    if not locked:
        return jsonify({"error": "Unable to acquire lock"}), 409

    # Remove from queue and become the *owner*
    queue.popleft()
    session["lock_owner"] = token
    return jsonify({"msg": "Lock granted – you may start uploading"}), 200


@app.post("/queue/finish")
def queue_finish():
    """
    Called when the user presses the *Finish upload* button.
    Releases the global lock so the next person can start.
    """
    token = get_user_token()
    if not is_lock_owner(token):
        return jsonify({"error": "You don't own the lock"}), 403

    # Release the lock safely
    if upload_lock.locked():
        upload_lock.release()
    session.pop("lock_owner", None)
    return jsonify({"msg": "Lock released – next user may start"}), 200


# ----------------------------------------------------------------------
# Chunked upload endpoint (unchanged except for lock check)
# ----------------------------------------------------------------------
@app.post("/upload")
def upload_chunk():
    token = get_user_token()
    if not is_lock_owner(token):
        # The user is not allowed to upload right now.
        return jsonify({"error": "You are not the active uploader"}), 423  # 423 Locked

    # ------------------------------------------------------------------
    # Validate request fields (Dropzone always sends these)
    # ------------------------------------------------------------------
    try:
        file = request.files["file"]
        file_uuid = request.form["dzuuid"]
        current_chunk = int(request.form["dzchunkindex"])
        chunk_offset = int(request.form["dzchunkbyteoffset"])
        total_chunks = int(request.form["dztotalchunkcount"])
        total_size = int(request.form["dztotalfilesize"])
    except (KeyError, ValueError) as exc:
        return jsonify({"error": f"Invalid request: {exc}"}), 400

    # --------------------------------------------------------------
    # Build a *safe* filename.  The final stored name is prefixed
    # with the first 8 chars of the Dropzone UUID to guarantee uniqueness.
    # --------------------------------------------------------------
    orig_name = secure_filename(file.filename)
    if not allowed_file(orig_name):
        return jsonify({"error": "File type not allowed"}), 415

    stored_name = f"{file_uuid[:8]}_{orig_name}"
    save_path = UPLOAD_ROOT / stored_name

    # --------------------------------------------------------------
    # Append the chunk (Open in binary append mode – we also seek
    # to the correct offset to guard against corrupted chunks).
    # --------------------------------------------------------------
    try:
        with open(save_path, "ab") as f:
            f.seek(chunk_offset)
            f.write(file.stream.read())
    except OSError as exc:
        return jsonify({"error": f"Filesystem error: {exc}"}), 500

    # --------------------------------------------------------------
    # If this was the last chunk, verify total size and register the
    # file in the in‑memory DB (or a real DB in production).
    # --------------------------------------------------------------
    if current_chunk + 1 == total_chunks:
        real_size = os.path.getsize(save_path)
        if real_size != total_size:
            # Clean up the possibly partial file.
            save_path.unlink(missing_ok=True)
            return jsonify({"error": "Size mismatch after final chunk"}), 500

        # Register file – the key is the per‑session token so we can
        # restrict downloads later.
        UPLOADS[token] = {
            "filename": stored_name,
            "original_name": orig_name,
            "size": real_size,
        }

    return jsonify({"msg": "Chunk saved"}), 200


# ----------------------------------------------------------------------
# List uploaded files (per‑user)
# ----------------------------------------------------------------------
@app.get("/files")
def list_files():
    token = get_user_token()
    meta = UPLOADS.get(token)
    if not meta:
        return jsonify({"files": []})
    # We only have at most one file per user in this demo.
    return jsonify(
        {
            "files": [
                {
                    "original_name": meta["original_name"],
                    "size": meta["size"],
                    "download_url": url_for("download_file", token=token, _external=False),
                }
            ]
        }
    )


# ----------------------------------------------------------------------
# Secure download endpoint
# ----------------------------------------------------------------------
@app.get("/download/<token>")
def download_file(token: str):
    """
    Serve the file *only* if the token belongs to the current session.
    """
    # Prevent enumeration – the token must match the session token.
    if token != session.get("upload_token"):
        return jsonify({"error": "Unauthorized"}), 403

    meta = UPLOADS.get(token)
    if not meta:
        return jsonify({"error": "File not found"}), 404

    # Flask's send_from_directory protects against path traversal.
    return send_from_directory(
        directory=UPLOAD_ROOT,
        path=meta["filename"],
        as_attachment=True,
        download_name=meta["original_name"],
    )


# ----------------------------------------------------------------------
# Run
# ----------------------------------------------------------------------
if __name__ == "__main__":
    # In production use gunicorn/uwsgi + a real secret key!
    app.run(debug=True, host="0.0.0.0", port=5000)
```

