        plot:      document.getElementById('draft-plot').value,
        style:     document.getElementById('style-input').value.trim()
    };
    const resp = await postJSON('/write_chapter', data);
    if (resp.error) { alert(resp.error); return; }
    document.getElementById('chapter-output').textContent = resp.chapter;
    document.getElementById('step3').classList.remove('hidden');
});

/* ---------- Step 3: Regenerate with feedback ---------- */
document.getElementById('btn-regenerate').addEventListener('click', async () => {
    const feedback = document.getElementById('feedback').value.trim();
    const payload = {
        outline:   document.getElementById('draft-outline').value,
        character: document.getElementById('draft-char').value,
        plot:      document.getElementById('draft-plot').value,
        style:     document.getElementById('style-input').value.trim(),
        feedback
    };
    const resp = await postJSON('/write_chapter', payload);
    if (resp.error) { alert(resp.error); return; }
    document.getElementById('chapter-output').textContent = resp.chapter;
    document.getElementById('feedback').value = '';
});

/* ---------- Step 3: Accept & download ---------- */
document.getElementById('btn-accept').addEventListener('click', async () => {
    const data = {
        outline:   document.getElementById('draft-outline').value,
        character: document.getElementById('draft-char').value,
        plot:      document.getElementById('draft-plot').value,
        style:     document.getElementById('style-input').value.trim(),
        chapter:   document.getElementById('chapter-output').textContent
    };
    const resp = await postJSON('/save_chapter', data);
    if (resp.error) { alert(resp.error); return; }

    // Trigger download
    const blob = new Blob([resp.content], {type: 'text/plain;charset=utf-8'});
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = resp.filename;
    a.click();
    URL.revokeObjectURL(url);
});
</script>
</body>
</html>
```

> **What the UI does**
> 1. **Step 1** – collect *keywords* and ask the server to **expand** them to a full outline, character sheet, and plot.  
> 2. **Step 2** – let the user edit any of the generated sections, optionally **regenerate** a single part, pick a language style, and click **开始写章节**.  
> 3. **Step 3** – the server returns a **chapter**. The user can add feedback and ask for a **regeneration**, or **accept** the chapter and download it as a `.txt` file.  
> 4. When the user wants to write the *next* chapter they simply edit the **情节** textarea (or add a new plot point) and click **开始写章节** again – the previous outline/character data are kept automatically.

---

## 3. Back‑end – `app.py`

```python
import os
import json
import datetime
from flask import Flask, request, jsonify, send_file, send_from_directory
from flask_cors import CORS
import openai
from pathlib import Path

# -------------------------------------------------
# 1️⃣  Flask + CORS (for local dev; lock down in prod)
# -------------------------------------------------
app = Flask(__name__, static_folder='static')
CORS(app)                     # Allow JS to call the API on same host/port

# -------------------------------------------------
# 2️⃣  Load OpenAI key (never commit it!)
# -------------------------------------------------
OPENAI_API_KEY = os.getenv("OPENAI_API_KEY")
if not OPENAI_API_KEY:
    raise RuntimeError("请在环境变量中设置 OPENAI_API_KEY")
openai.api_key = OPENAI_API_KEY

# -------------------------------------------------
# 3️⃣  Helper to talk to ChatGPT‑4
# -------------------------------------------------
def chat_completion(messages, temperature=0.8, max_tokens=1500):
    """Wrap OpenAI ChatCompletion with basic error handling."""
    try:
        response = openai.ChatCompletion.create(
            model="gpt-4o-mini",          # or "gpt-4" if you have access
            messages=messages,
            temperature=temperature,
            max_tokens=max_tokens,
            n=1,
        )
        return response.choices[0].message["content"].strip()
    except openai.error.OpenAIError as e:
        raise RuntimeError(f"OpenAI API error: {e}")

# -------------------------------------------------
# 4️⃣  Prompt templates (feel free to fine‑tune)
# -------------------------------------------------
TEMPLATE_EXPAND = """下面给出三个关键词（大纲、人物、情节），请把它们分别扩写为完整的叙事文本，要求结构清晰、语言流畅、适合用于网络小说的写作。

关键词:
- 大纲: {outline_kw}
- 人物: {char_kw}
- 情节: {plot_kw}

请分别输出:
【大纲】（约300字）  
【人物】（约200字）  
【情节】（约250字）"""

TEMPLATE_REGEN_SECTION = """依据已有的三段文本（大纲、人物、情节），请重新写**{kind}**这段内容，使其更完整、更具吸引力，保持其它两段不变。

当前文本:
【大纲】{outline}
【人物】{character}
【情节】{plot}

请只返回重新写好的 **{kind}** 部分（不需要标记标题）。"""

TEMPLATE_WRITE_CHAPTER = """你是一个专业的网络小说作者。请依据下面提供的资料写出 **一章**（约 1200‑1500 字）的正文，要求：
1. 文风使用 **{style}**（如果未提供，则默认现代轻小说风格）；
2. 明确体现人物设定和当前情节走向；
3. 结构完整，有起承转合；  
4. 若用户提供了**feedback**，请在写作时参考它进行改写，否则直接创作。

提供的资料：
【大纲】{outline}
【人物】{character}
【情节】{plot}
{feedback_block}
请直接给出章节正文，不要出现额外的说明或标题。"""

# -------------------------------------------------
# 5️⃣  Routes
# -------------------------------------------------
@app.route('/')
def home():
    """Serve the HTML page."""
    return send_from_directory(app.static_folder, 'index.html')

@app.route('/expand', methods=['POST'])
def expand():
    data = request.json
    outline_kw = data.get('outline', '')
    char_kw    = data.get('character', '')
    plot_kw    = data.get('plot', '')

    prompt = TEMPLATE_EXPAND.format(
        outline_kw=outline_kw or "未提供",
        char_kw=char_kw or "未提供",
        plot_kw=plot_kw or "未提供"
    )
    try:
        result = chat_completion([{"role":"system","content":"你是一个写作助手。"},
                                  {"role":"user","content":prompt}])
        # The model will likely output the three sections separated by headers.
        # We'll split heuristically.
        sections = {"outline": "", "character": "", "plot": ""}
        for line in result.splitlines():
            line = line.strip()
            if line.startswith('【大纲】'):
                sections["outline"] = line[len('【大纲】'):].strip()
            elif line.startswith('【人物】'):
                sections["character"] = line[len('【人物】'):].strip()
            elif line.startswith('【情节】'):
                sections["plot"] = line[len('【情节】'):].strip()
            else:
                # continuation lines – append to last non‑empty section
                if sections["plot"]:
                    sections["plot"] += "\n" + line
                elif sections["character"]:
                    sections["character"] += "\n" + line
                elif sections["outline"]:
                    sections["outline"] += "\n" + line

        return jsonify(sections)
    except Exception as e:
        return jsonify({"error": str(e)}), 500

@app.route('/regenerate_section', methods=['POST'])
def regenerate_section():
    data = request.json
    kind = data.get('kind')
    outline   = data.get('outline', '')
    character = data.get('character', '')
    plot      = data.get('plot', '')

    prompt = TEMPLATE_REGEN_SECTION.format(
        kind=kind,
        outline=outline,
        character=character,
        plot=plot
    )
    try:
        new_text = chat_completion([{"role":"system","content":"你是一个写作助手。"},
                                    {"role":"user","content":prompt}])
        # Return the whole set, but replace only the requested part.
        if kind == 'outline':
            outline = new_text
        elif kind == 'character':
            character = new_text
        elif kind == 'plot':
            plot = new_text
        return jsonify({"outline": outline, "character": character, "plot": plot})
    except Exception as e:
        return jsonify({"error": str(e)}), 500

@app.route('/write_chapter', methods=['POST'])
def write_chapter():
    data = request.json
    outline = data.get('outline', '')
    character = data.get('character', '')
    plot = data.get('plot', '')
    style = data.get('style', '')
    feedback = data.get('feedback', '').strip()

    feedback_block = f"【用户反馈】{feedback}" if feedback else ""

    prompt = TEMPLATE_WRITE_CHAPTER.format(
        outline=outline,
        character=character,
        plot=plot,
        style=style if style else "现代轻小说",
        feedback_block=feedback_block
    )
    try:
        chapter = chat_completion([{"role":"system","content":"你是一个专业小说作者。"},
                                    {"role":"user","content":prompt}],
                                   temperature=0.85,
                                   max_tokens=1800)
        return jsonify({"chapter": chapter})
    except Exception as e:
        return jsonify({"error": str(e)}), 500

@app.route('/save_chapter', methods=['POST'])
def save_chapter():
    data = request.json
    chapter = data.get('chapter', '')
    # 确保章节不为空
    if not chapter.strip():
        return jsonify({"error": "章节为空，无法保存"}), 400

    # 生成文件名：章节_时间戳.txt
    timestamp = datetime.datetime.now().strftime("%Y%m%d_%H%M%S")
    filename = f"chapter_{timestamp}.txt"
    out_path = Path("saved_chapters")
    out_path.mkdir(exist_ok=True)
    file_path = out_path / filename
    file_path.write_text(chapter, encoding="utf-8")

    # 返回内容讓前端觸發下載
    return jsonify({
        "filename": filename,
        "content": chapter
    })

# -------------------------------------------------
# 6️⃣  Run (development only)
# -------------------------------------------------
if __name__ == '__main__':
    # In production, use gunicorn / uWSGI + HTTPS + proper domain
    app.run(host='0.0.0.0', port=5000, debug=True)
```

