## 📟 Код прошивки для **Arduino Pro Mini**  
**Что делает скетч**

1. Считывает температуру с датчика **DS18B20** (можно заменить на любой One‑Wire термометр).  
2. Считывает состояние **одного цифрового входа** (можно использовать любую кнопку/датчик).  
3. Формирует пакет данных и передаёт его **модулем HC‑12** (UART‑порт,‑9600 бит/с).  
4. Пакет содержит **идентификатор контроллера**, температуру (°C) и значение цифрового входа (0/1).  

> **Важно:**  
> * Пакет делается простым, чтобы на Orange Pi Zero его было легко парсить (CSV‑строка).  
> * При необходимости добавьте проверку CRC, шифрование или подпись — это уже будет задачей «безопасности».  

---

### 📦 Библиотеки, которые понадобятся  

| Библиотека | Описание | Как установить |
|------------|----------|----------------|
| `SoftwareSerial` | Позволяет использовать любой цифровой пин для UART‑соединения с HC‑12 (Arduino Pro Mini имеет один «hardware» UART, занятый USB‑загрузчиком). | Встроена в Arduino‑IDE. |
| `OneWire` | Доступ к шине One‑Wire (датчики DS18B20). | Менеджер библиотек → “OneWire”. |
| `DallasTemperature` | Высоко‑уровневый драйвер для DS18B20. | Менеджер библиотек → “DallasTemperature”. |

---

## 🧩 Полный скетч с подробными комментариями (русский)

```cpp
/* ---------------------------------------------------------------
 *  Arduino Pro Mini → HC‑12 → Orange Pi Zero
 *  Считывание температуры (DS18B20) + состояние цифрового входа
 *  ---------------------------------------------------------------
 *  Автор:  <Ваше имя>
 *  Дата:   2024‑06‑03
 *  Версия: 1.0
 * --------------------------------------------------------------- */

#include <SoftwareSerial.h>      // Слой для работы с «вторым» UART (HC‑12)
#include <OneWire.h>             // Базовый драйвер OneWire
#include <DallasTemperature.h>  // Высоко‑уровневый драйвер DS18B20

/* --------------------------- ПИНЫ --------------------------- */
// Пины HC‑12 (TX – к RX Arduino, RX – к TX Arduino)
const uint8_t HC12_TX_PIN = 2;    // Arduino → HC‑12 RX
const uint8_t HC12_RX_PIN = 3;    // Arduino ← HC‑12 TX

// Пин датчика температуры (OneWire шина)
const uint8_t ONE_WIRE_BUS = 4;  // любой цифровой пин

// Пин цифрового входа (включить подтягивание, если нужен "pull‑up")
const uint8_t DIGITAL_IN_PIN = 5;

/* --------------------------- НАСТРОЙКИ --------------------------- */
// Уникальный номер данного Arduino (чем больше, тем лучше)
const uint8_t DEVICE_ID = 1;   // <‑‑ поменяйте для каждого контроллера

// Период измерения (мс)
const unsigned long SAMPLE_INTERVAL = 5000; // 5 сек.


// -------------------------- Объекты --------------------------
SoftwareSerial hc12Serial(HC12_TX_PIN, HC12_RX_PIN); // (TX, RX)
OneWire oneWire(ONE_WIRE_BUS);                     // шина OneWire
DallasTemperature sensors(&oneWire);               // драйвер DS18B20

// Время последнего измерения
unsigned long lastSampleTime = 0;

// -------------------------- Функции --------------------------

/**
 * @brief Формирует строку пакета и отправляет её по HC‑12.
 *
 * Формат пакета (CSV):  ID,TEMP,DIGITAL
 * Пример:  "01,23.56,1\n"
 *
 * @param temperature float   – температура в градусах Цельсия
 * @param digital     uint8_t – состояние цифрового входа (0/1)
 */
void sendPacket(float temperature, uint8_t digital) {
  // Приводим ID к 2‑символьному виду (00‑99). Если понадобится >99,
  // используйте строковое представление (sprintf с %d).
  char buffer[32];
  snprintf(buffer, sizeof(buffer), "%02d,%.2f,%d\n",
           DEVICE_ID, temperature, digital);
  hc12Serial.print(buffer);      // Отправляем строку без лишних задержек
}

/**
 * @brief Читает температуру из DS18B20.
 *
 * @return float – температура в °C, если датчик не найден – возвращает NAN.
 */
float readTemperature() {
  sensors.requestTemperatures();          // Инициируем измерение
  // Предполагаем, что на шине только один датчик.
  // Если их несколько – используйте getAddress() и loop по массиву.
  float tempC = sensors.getTempCByIndex(0);
  return tempC; // может быть DEVICE_DISCONNECTED_C (–127) -> проверим позже
}

/**
 * @brief Читает состояние цифрового входа.
 *
 * @return uint8_t – 0 или 1
 */
uint8_t readDigitalIn() {
  // Если вход подтянут к Vcc через резистор, используем INPUT_PULLUP
  // (тогда логика инвертируется). Поставьте нужный resistor в схеме.
  return digitalRead(DIGITAL_IN_PIN);
}

/* -------------------------- Setup -------------------------- */
void setup() {
  // 1. Последовательный порт для отладки (по желанию)
  Serial.begin(9600);
  while (!Serial) { ; } // Ждём, если на USB‑Serial (не обязателен)

  // 2. HC‑12 – обычно работает 9600 бит/с, 8‑N‑1
  hc12Serial.begin(9600);
  Serial.println(F("HC‑12 init OK"));

  // 3. Приводим пины к нужному режиму
  pinMode(DIGITAL_IN_PIN, INPUT); // или INPUT_PULLUP при необходимости
  // (OneWire и датчик температуры инициализируются в объекте)

  // 4. Инициализируем драйвер датчика температуры
  sensors.begin();
  Serial.println(F("DS18B20 init OK"));
}

/* -------------------------- Loop -------------------------- */
void loop() {
  // Выполняем измерения только раз в SAMPLE_INTERVAL
  unsigned long now = millis();
  if (now - lastSampleTime >= SAMPLE_INTERVAL) {
    lastSampleTime = now;

    // 1️⃣ Считываем температуру
    float temp = readTemperature();
    // Если датчик отключен или ошибка – возвращаем NAN
    if (temp == DEVICE_DISCONNECTED_C) {
      Serial.println(F("Error: DS18B20 not connected!"));
      temp = NAN; // Можно передать как 0.0 или отдельный код ошибки
    }

    // 2️⃣ Считываем цифровой вход
    uint8_t dig = readDigitalIn();

    // 3️⃣ Формируем и отправляем пакет
    sendPacket(temp, dig);

    // 4️⃣ Выводим в Serial для отладки
    Serial.print(F("Sent: ID="));
    Serial.print(DEVICE_ID);
    Serial.print(F(", T="));
    Serial.print(temp);
    Serial.print(F("°C, D="));
    Serial.println(dig);
  }

  // При желании можно добавить обработку входящих команд от HC‑12
  // (например, запрос текущего порога температуры).
  if (hc12Serial.available()) {
    // Пример простого «эхо» – читаем и отсылаем обратно
    char c = hc12Serial.read();
    hc12Serial.write(c);   // (необязательно)
  }

  // Не задерживаем цикл, а только проверяем таймер
}
```

