## 4️⃣ Mẹo viết **server‑side** JavaScript (Node.js) an toàn

| Thực tiễn | Lý do | Cách thực hiện |
|-----------|-------|----------------|
| **Sử dụng HTTPS/TLS** | Ngăn sniffing & MITM | Cấu hình `https.createServer({key, cert}, app)` hoặc dùng reverse proxy (NGINX). |
| **Helmet** | Đặt header bảo mật (CSP, HSTS, X‑Frame‑Options…) | `app.use(require('helmet')());` |
| **Rate limiting** | Ngăn brute‑force, credential stuffing | `express-rate-limit` hoặc `rate-limiter-flexible`. |
| **Input validation** | Ngăn injection, malformed payloads | `Joi`, `Zod`, `express-validator`. |
| **Output encoding** | Ngăn XSS khi trả JSON/HTML | `res.json(sanitize(data))` hoặc dùng templating engine tự escape (e.g., Pug). |
| **Disable `x-powered-by`** | Ẩn công nghệ server tránh lộ điểm yếu | `app.disable('x-powered-by');` |
| **Secure cookie flags** | Ngăn CSRF & theft | `res.cookie('session', token, { httpOnly: true, secure: true, sameSite: 'strict' });` |
| **Không sử dụng `eval`/`Function`** | Rủi ro code injection | Loại bỏ toàn bộ; dùng **template engines** hoặc **sandbox** nếu cần. |
| **Cập nhật dependencies** | Fix CVE mới | `npm audit`, `npm outdated`, `npm install <pkg>@latest`. |
| **Node.js process isolation** | Chặn rủi ro khi một worker bị tấn công | Sử dụng **cluster** hoặc **worker_threads** để tách context. |

### 4.1. Ví dụ “Secure Express route”:

```js
const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const {body, validationResult} = require('express-validator');
const DOMPurify = require('isomorphic-dompurify');

const app = express();

app.use(helmet());                // Header bảo mật
app.use(express.json());          // Body parser
app.use(express.urlencoded({extended: false}));

// Rate limiting: 100 yêu cầu / 15 phút mỗi IP
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 100,
  standardHeaders: true,
});
app.use(limiter);

// Đăng ký người dùng – validation + sanitization
app.post(
  '/api/register',
  [
    body('username')
      .isAlphanumeric().withMessage('Chỉ cho phép ký tự A‑Z,0‑9')
      .isLength({min: 3, max: 20}).trim().escape(),
    body('email')
      .isEmail().normalizeEmail(),
    body('password')
      .isStrongPassword().trim(),
  ],
  (req, res) => {
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      return res.status(400).json({errors: errors.array()});
    }

    // Ví dụ: lưu vào DB (hash mật khẩu, v.v.)
    const {username, email, password} = req.body;
    // ... lưu user ...

    res.status(201).json({message: 'Tài khoản đã tạo'});
  }
);

// Trả về HTML do người dùng nhập (sử dụng DOMPurify)
app.post('/api/comment', (req, res) => {
  const raw = req.body.comment || '';
  const clean = DOMPurify.sanitize(raw);   // Loại bỏ script, on* attributes…
  res.send(`<p>${clean}</p>`);
});

app.listen(3000, () => console.log('🚀 Server chạy trên port 3000'));
```

