#### `app.py`（后端）

```python
from flask import Flask, jsonify
import subprocess
import sys
import os

app = Flask(__name__)

@app.route('/run_kdj')
def run_kdj():
    script_path = os.path.join(os.path.dirname(__file__), 'stockkdj.py')
    # 用 sys.executable 确保使用当前运行的 Python 解释器
    try:
        result = subprocess.check_output([sys.executable, script_path],
                                         universal_newlines=True,
                                         stderr=subprocess.STDOUT)
        return jsonify({'code': 0, 'msg': result.strip()})
    except subprocess.CalledProcessError as e:
        return jsonify({'code': 1, 'msg': e.output}), 500

if __name__ == '__main__':
    # 仅在本地调试，生产请使用 gunicorn/uwsgi + Nginx
    app.run(host='127.0.0.1', port=5000, debug=True)
```

#### `index.html`（前端）

```html
<!DOCTYPE html>
<html lang="zh-CN">
<head>
    <meta charset="UTF-8">
    <title>调用 stockkdj.py</title>
</head>
<body>
