### 2.1 `getUserInfo` – 获取或创建用户记录

**路径**：`cloudfunctions/getUserInfo/index.js`

```js
// 云函数入口文件
const cloud = require('wx-server-sdk')
cloud.init()
const db = cloud.database()
const USERS = db.collection('users')

exports.main = async (event, context) => {
  const { OPENID } = cloud.getWXContext()
  // 先查询是否已有记录
  const { data } = await USERS.where({ openid: OPENID }).limit(1).get()
  if (data.length > 0) {
    // 已有用户，直接返回
    return { success: true, user: data[0] }
  }

  // 没有则创建默认记录（积分 1000 为示例，可自行调节）
  const newUser = {
    openid: OPENID,
    nickname: event.nickname || '匿名',
    avatarUrl: event.avatarUrl || '',
    points: 1000,
    createTime: db.serverDate()
  }
  const res = await USERS.add({ data: newUser })
  newUser._id = res._id
  return { success: true, user: newUser }
}
```

> **安全点**：  
> - 通过 `cloud.getWXContext()` 获得的 `OPENID` 是由微信后台直接签发，前端无法篡改。  
> - 不接受前端传入的 `openid`，所有查询都使用服务端获取的 `OPENID`。

