### 2.2 `transferPoints` – 积分转账（核心业务）

**路径**：`cloudfunctions/transferPoints/index.js`

```js
const cloud = require('wx-server-sdk')
cloud.init()
const db = cloud.database()
const USERS = db.collection('users')
const TRANSACTIONS = db.collection('transactions')

// 最大单笔转账额度（示例 5000）
const MAX_TRANSFER = 5000

exports.main = async (event, context) => {
  const { OPENID: fromOpenid } = cloud.getWXContext()
  const { toOpenid, amount } = event

  // 参数基本校验
  if (!toOpenid || typeof amount !== 'number' || amount <= 0) {
    return { success: false, errMsg: '参数错误' }
  }
  if (amount > MAX_TRANSFER) {
    return { success: false, errMsg: `单笔转账不能超过 ${MAX_TRANSFER} 积分` }
  }
  if (fromOpenid === toOpenid) {
    return { success: false, errMsg: '不能转给自己' }
  }

  // 使用事务保证原子性（防止并发导致负数或重复扣款）
  const res = await db.runTransaction(async (transaction) => {
    // 1. 读取双方最新积分
    const [fromSnap, toSnap] = await Promise.all([
      transaction.collection('users').where({ openid: fromOpenid }).limit(1).get(),
      transaction.collection('users').where({ openid: toOpenid }).limit(1).get()
    ])

    if (fromSnap.data.length === 0) {
      throw new Error('付款方不存在')
    }
    if (toSnap.data.length === 0) {
      throw new Error('收款方不存在')
    }
    const fromUser = fromSnap.data[0]
    const toUser = toSnap.data[0]

    // 2. 检查余额是否足够
    if (fromUser.points < amount) {
      throw new Error('余额不足')
    }

    // 3. 更新双方积分
    transaction.collection('users').doc(fromUser._id).update({
      data: { points: db.command.inc(-amount) }
    })
    transaction.collection('users').doc(toUser._id).update({
      data: { points: db.command.inc(amount) }
    })

    // 4. 写入交易流水（可供审计）
    transaction.collection('transactions').add({
      data: {
        fromOpenid,
        toOpenid,
        amount,
        status: 'SUCCESS',
        createTime: db.serverDate()
      }
    })

    // 返回更新后的积分（可直接返回给前端刷新 UI）
    return {
      fromPoints: fromUser.points - amount,
      toPoints: toUser.points + amount
    }
  }).catch(err => {
    // 事务失败，记录一条失败流水（可选）
    TRANSACTIONS.add({
      data: {
        fromOpenid,
        toOpenid,
        amount,
        status: 'FAILED',
        errMsg: err.message,
        createTime: db.serverDate()
      }
    })
    return { error: err }
  })

  if (res && res.error) {
    return { success: false, errMsg: res.error.message }
  }
  return { success: true, data: res }
}
```

#### 关键安全点

| 步骤 | 说明 |
|------|------|
| **使用事务** (`db.runTransaction`) | 同时读写两条记录，确保在并发情况下“扣款‑加款”是原子操作，避免负数或重复转账。 |
| **服务端校验 `fromOpenid`** | 前端不能伪造付款方，全部用 `cloud.getWXContext()` 获得的 `OPENID`。 |
| **金额上限 & 余额检查** | 防止一次性转走全部积分或恶意刷分。 |
| **记录交易流水** | 每笔转账都写入 `transactions`，包括失败原因，便于事后审计。 |
| **异常捕获** | 任何异常都会回滚事务，并返回友好错误信息。 |

