cloud.init()
const db = cloud.database()
const FRIENDSHIP = db.collection('friendships')
const USERS = db.collection('users')

exports.main = async (event, context) => {
  const { OPENID } = cloud.getWXContext()
  // 读取所有以当前用户为 owner 的好友记录
  const { data: friendLinks } = await FRIENDSHIP.where({ ownerOpenid: OPENID }).get()
  const friendOpenids = friendLinks.map(item => item.friendOpenid)

  // 批量获取好友基本信息（昵称、头像、积分）
  const { data: friends } = await USERS.where({
    openid: db.command.in(friendOpenids)
  }).field({
    nickname: true,
    avatarUrl: true,
    points: true,
    openid: true
  }).get()

  return { success: true, friends }
}
```

> **安全要点**：所有查询均使用 `OPENID` 过滤，防止任意用户偷看他人好友。

