constexpr std::size_t MAX_BUF   = 1024;
constexpr std::size_t MIN_BUF   = 8;
constexpr std::size_t MAGIC_NUM = 0x5A5A5A5A;

struct Token {
    uint32_t magic;     // must be MAGIC_NUM
    uint16_t size;      // payload size (bytes)
    uint8_t  payload[1]; // variable length (size bytes follow)
};

/**
 * @brief Checks a raw token buffer for integrity and extracts the payload.
 *
 * @param raw   Pointer to the start of the token.
 * @param raw_len   Length of the whole buffer (must include header + payload).
 *
 * @return std::vector<uint8_t> extracted payload.
 *
 * @throws std::invalid_argument on any integrity failure.
 */
std::vector<uint8_t> parse_token(const uint8_t* raw, std::size_t raw_len)
{
    // 1️⃣  Null‑pointer guard
    if (!raw) {
        throw std::invalid_argument("null pointer");
    }

    // 2️⃣  Minimum size guard (header = magic(4) + size(2))
    if (raw_len < sizeof(Token) - 1) {
        throw std::invalid_argument("buffer too short for header");
    }

    // 3️⃣  Extract fields (no alignment assumptions)
    const Token* t = reinterpret_cast<const Token*>(raw);
    if (t->magic != MAGIC_NUM) {
        throw std::invalid_argument("bad magic");
    }

    // 4️⃣  Payload length sanity
    if (t->size < MIN_BUF || t->size > MAX_BUF) {
        throw std::invalid_argument("payload size out of bounds");
    }

    // 5️⃣  Whole‑buffer size verification
    if (raw_len < sizeof(Token) - 1 + t->size) {
        throw std::invalid_argument("buffer truncated");
    }

    // 6️⃣  (optional) content‑specific check – e.g. no null bytes in payload
    const uint8_t* p = t->payload;
    for (std::size_t i = 0; i < t->size; ++i) {
        if (p[i] == 0) {
            throw std::invalid_argument("null byte in payload");
        }
    }

    // 7️⃣  All good → copy payload out
    return std::vector<uint8_t>(p, p + t->size);
}
