// Tiny builder that returns a raw byte vector representing a token.
// All fields are set to “good” values; each individual test can then tweak one.
std::vector<uint8_t> build_token(std::size_t payload_len = MIN_BUF,
                                 uint32_t magic = MAGIC_NUM,
                                 bool fill_with_nonzero = true)
{
    // Guard against absurd size, just for sanity.
    if (payload_len > MAX_BUF) payload_len = MAX_BUF;

    // Compute total size: header (magic+size) + payload
    std::size_t total = sizeof(uint32_t)       // magic
                      + sizeof(uint16_t)       // size
                      + payload_len;           // payload

    std::vector<uint8_t> buf(total, 0);

    // Insert magic (little‑endian)
    uint32_t* p_magic = reinterpret_cast<uint32_t*>(buf.data());
    *p_magic = magic;

    // Insert payload size
    uint16_t* p_size = reinterpret_cast<uint16_t*>(buf.data() + sizeof(uint32_t));
    *p_size = static_cast<uint16_t>(payload_len);

    // Fill payload
    uint8_t* p_payload = buf.data() + sizeof(uint32_t) + sizeof(uint16_t);
    for (std::size_t i = 0; i < payload_len; ++i) {
        // Non‑zero filler (0xAA) unless we explicitly want a zero byte.
        p_payload[i] = fill_with_nonzero ? 0xAA : 0x00;
    }

    return buf;
