#include <stdio.h>
#include <stdlib.h>

#define MAXN 200000   // enough for n + dummy

/* ---------- min‑heap for integers (times) ---------- */
typedef struct {
    int *a;          // 1‑based array
    int  size;
    int  capacity;
} MinHeap;

MinHeap* heapCreate(int cap)
{
    MinHeap *h = (MinHeap*)malloc(sizeof(MinHeap));
    h->a = (int*)malloc((cap+2)*sizeof(int));
    h->size = 0;
    h->capacity = cap;
    return h;
}

/* swap two elements */
static inline void swap(int *x, int *y)
{
    int t = *x; *x = *y; *y = t;
}

/* push value */
void heapPush(MinHeap *h, int val)
{
    if (h->size == h->capacity) return;          // never happens in this problem
    int i = ++h->size;
    h->a[i] = val;
    while (i > 1 && h->a[i] < h->a[i/2]) {
        swap(&h->a[i], &h->a[i/2]);
        i /= 2;
    }
}

/* pop minimum, assumes heap not empty */
int heapPop(MinHeap *h)
{
    int ret = h->a[1];
    h->a[1] = h->a[h->size--];
    int i = 1;
    while (1) {
        int l = i*2, r = i*2+1, smallest = i;
        if (l <= h->size && h->a[l] < h->a[smallest]) smallest = l;
        if (r <= h->size && h->a[r] < h->a[smallest]) smallest = r;
        if (smallest == i) break;
        swap(&h->a[i], &h->a[smallest]);
        i = smallest;
    }
    return ret;
}

/* ---------- main ---------- */

typedef struct {
    int d;   // depth
    int t;   // time
} Station;

/* comparator for qsort (ascending depth) */
int cmpStation(const void *p, const void *q)
{
    const Station *a = (const Station*)p;
    const Station *b = (const Station*)q;
    return a->d - b->d;
}

