        st[i].d = depth[i];
        st[i].t = time[i];
    }
    free(depth); free(time);

    qsort(st, n, sizeof(Station), cmpStation);

    /* dummy for the destination (depth D, time 0) */
    st[n].d = (int)D;
    st[n].t = 0;
    int totalStations = n + 1;

    MinHeap *heap = heapCreate(n+2);

    long long curDepth = 0;
    long long oxygen   = O;
    long long answer   = 0;

    for (int i = 0; i < totalStations; ++i) {
        long long need = (long long)st[i].d - curDepth;   // distance to next point

