**Solution Overview**

We have to implement a tiny “controller” in pure C that

* receives **6 binary input variables** (buttons – 0 = open, 1 = closed)  
* maintains **6 binary output variables** (relays – 0 = off, 1 = on)  
* builds a **mapping** “button → one‑or‑more relays” from a JSON description that the user draws in the UI.  
* starts processing only when a **button event** occurs (rising edge 0→1).  
* executes the chain **in the order** defined in the JSON (e.g., `button1 → relay1 → relay3`).  

The JSON is parsed with the tiny **mjson** library (https://github.com/cesanta/mjson).  
All data are kept in RAM – no OS, no threads, only a single “engine” function that can be called repeatedly from the main loop.

Below you will find:

1. **Data structures** describing the mapping.  
2. **Helper functions** for JSON parsing, edge detection and relay handling.  
3. **The main processing function** `controller_tick()` that must be called each iteration of the user’s main loop.  
4. **Security‑oriented notes** (input validation, memory safety, static analysis recommendations).  

---

## 1. Data Model

```c
/* --------------------------------------------------------------
 * Constants (fixed by the task)
 * -------------------------------------------------------------- */
#define INPUT_COUNT   6   /* buttons 0..5   */
#define OUTPUT_COUNT  6   /* relays  0..5   */

/* --------------------------------------------------------------
 * Mapping entry – one button may control N relays (0 ≤ N ≤ OUTPUT_COUNT)
 * -------------------------------------------------------------- */
typedef struct {
    uint8_t relays[OUTPUT_COUNT];   /* Boolean list – 1 = relay belongs to mapping */
    uint8_t order[OUTPUT_COUNT];    /* Execution order, 0 = not used, 1..N = step */
    uint8_t count;                  /* How many relays are attached to this button */
} button_map_t;

/* --------------------------------------------------------------
 * Whole configuration – one map per button
 * -------------------------------------------------------------- */
typedef struct {
    button_map_t map[INPUT_COUNT];
} controller_cfg_t;

/* --------------------------------------------------------------
 * Runtime state – needed for edge detection
 * -------------------------------------------------------------- */
typedef struct {
    uint8_t inputs[INPUT_COUNT];   /* last known input level (0/1)               */
    uint8_t outputs[OUTPUT_COUNT];/* current output level (0/1)                */
    controller_cfg_t cfg;         /* mapping built from the JSON description   */
} controller_t;
```

*The `order[]` array is required only because the UI can describe chains such as “button 1 → relay 2 → relay 3”. The numbers 1,2,… define in which sequence the relays must be toggled.*

---

## 2. JSON Format Expected from the UI

The UI will hand a JSON **array of objects**; each object describes the mapping for **one button**.

```json
[
    {
        "button": 0,                 // index 0‑5
        "chain": [1, 4, 2]           // list of relay indices (0‑5) in execution order
    },
    {
        "button": 3,
        "chain": [5]
    }
    // … optional entries for the remaining buttons
]
```

*If a button is missing from the JSON, it will have an empty chain (does nothing).*

---

## 3. Parsing JSON with **mjson**

`mjson` is a single‑header, zero‑allocation JSON parser.  
The following function reads the JSON string, validates it, and fills `controller_t.cfg`.

```c
#include "mjson.h"
#include <stddef.h>
#include <string.h>
#include <stdio.h>
#include <stdbool.h>

static bool parse_controller_json(const char *json, controller_t *ctrl)
{
    /* Reset configuration first */
    memset(&ctrl->cfg, 0, sizeof(ctrl->cfg));

    /* Helper – called for each element of the top‑level array */
    int index = 0;
    int rc = mjson_find(json, NULL, "{", NULL, 0);   /* skip leading spaces */
    rc = mjson_find(json, NULL, "[", NULL, 0);       /* locate the array   */
    if (rc < 0) {
        fprintf(stderr, "JSON must start with an array\n");
        return false;
    }

    /* Walk through each object in the array */
    const char *p = json + rc;
    int obj_ofs = 0;
    while ((obj_ofs = mjson_find(p, NULL, "{", NULL, 0)) >= 0) {
        const char *obj = p + obj_ofs;               /* start of object */

        /* ---- read "button" field --------------------------------- */
        int btn = -1;
        if (mjson_get_number(obj, "button", &btn) != 0 ||
            btn < 0 || btn >= INPUT_COUNT) {
            fprintf(stderr, "Invalid or missing button index\n");
            return false;
        }

        /* ---- read "chain" array ---------------------------------- */
        const char *chain = NULL;
        int chain_len = mjson_get_array(obj, "chain", &chain);
        if (chain_len < 0) {
            /* Empty chain is legal – just leave it zeroed */
            continue;
        }

        /* parse chain elements – they must be integers 0‑5 */
        int pos = 0, step = 1;
        while ((pos = mjson_get_number_at(chain, NULL, step - 1, &pos)) >= 0) {
            int relay = pos;
            if (relay < 0 || relay >= OUTPUT_COUNT) {
                fprintf(stderr, "Relay index out of range (%d)\n", relay);
                return false;
            }
            button_map_t *bm = &ctrl->cfg.map[btn];
            if (bm->count >= OUTPUT_COUNT) {
                fprintf(stderr, "Too many relays for button %d\n", btn);
                return false;
            }
            /* store in both tables */
            bm->relays[relay] = 1;
            bm->order[relay] = step;   /* execution step (1‑based) */
            bm->count++;
            step++;
        }

        /* move pointer to the next object */
        p = obj + mjson_calc_strlen(obj);
    }

    return true;
}
```

**Explanation**

* The function **zero‑initialises** the whole configuration – an absent button remains with `count == 0`.
* `mjson_get_number` extracts the integer value of `"button"`.
* `mjson_get_array` returns a pointer to the raw array data; we then walk it using `mjson_get_number_at`.
* The mapping is stored in `controller_cfg_t`:
  * `relays[]` – Boolean (0/1) indicating that the relay belongs to the button.
  * `order[]` – step number (used later for deterministic execution order).
  * `count` – how many relays are attached (quick‑check for overflow).

> **Security note** – all numeric values are validated against the allowed ranges (`0…5`). Any malformed input aborts parsing and leaves the controller in its previous safe state.

---

## 4. Edge‑Detection (Button Press)

A button press is considered **the moment the input changes from 0 → 1** (rising edge).  
The controller stores the previous level for each button and compares it on every tick.

```c
static inline bool is_rising_edge(controller_t *c, int btn, uint8_t cur)
{
    bool prev = c->inputs[btn];
    c->inputs[btn] = cur;                  /* update stored state */
    return (!prev && cur);                 /* true only on 0→1 transition */
}
```

---

## 5. Relay Activation Logic

When a button event is detected, we fetch its map and toggle the associated relays **in the defined order**.

```c
static void execute_chain(controller_t *c, int btn)
{
    const button_map_t *bm = &c->cfg.map[btn];
    if (bm->count == 0) return;            /* nothing to do */

    /* Create a temporary array with (relay, step) pairs for sorting */
    struct {
        uint8_t relay;
        uint8_t step;
    } work[OUTPUT_COUNT];

    int w = 0;
    for (int r = 0; r < OUTPUT_COUNT; ++r) {
        if (bm->relays[r]) {
            work[w].relay = r;
            work[w].step  = bm->order[r];
            ++w;
        }
    }

    /* Simple bubble‑sort – output count is ≤6, the cost is negligible */
    for (int i = 0; i < w - 1; ++i) {
        for (int j = i + 1; j < w; ++j) {
            if (work[i].step > work[j].step) {
                typeof(work[0]) tmp = work[i];
                work[i] = work[j];
                work[j] = tmp;
            }
        }
    }

    /* Apply the actions – here we simply turn the relay ON.
       (If you need toggle/off you can add a policy field). */
    for (int i = 0; i < w; ++i) {
        uint8_t relay = work[i].relay;
        c->outputs[relay] = 1;                /* set to ON */
        /* In a real embedded board you would now write to the GPIO:
         * gpio_write(RELAY_PIN[relay], 1);
         */
    }
}
```

*The function is deliberately **pure**, it never touches the input side again, thus eliminating race conditions.*

If you need a **toggle** (e.g., “press button → invert relay state”), replace the assignment with:

```c
c->outputs[relay] ^= 1;   /* XOR‑flip */
```

