## 6. The Public API

```c
/* --------------------------------------------------------------
 * Initialise controller – all inputs/outputs are forced to 0.
 * The caller must provide a JSON string that describes the mapping.
 * Returns true on success, false on malformed JSON.
 * -------------------------------------------------------------- */
bool controller_init(controller_t *c, const char *json_cfg)
{
    memset(c, 0, sizeof(*c));               /* zero all state */
    return parse_controller_json(json_cfg, c);
}

/* --------------------------------------------------------------
 * Tick – must be called each iteration of the main loop.
 * `inputs` points to an array of 6 uint8_t (0/1) containing the
 * current button levels read from hardware.
 * -------------------------------------------------------------- */
void controller_tick(controller_t *c, const uint8_t inputs[INPUT_COUNT])
{
    for (int btn = 0; btn < INPUT_COUNT; ++btn) {
        if (is_rising_edge(c, btn, inputs[btn])) {
            execute_chain(c, btn);
        }
    }
}

/* --------------------------------------------------------------
 * Helper – read current output state for testing or for GPIO write.
 * -------------------------------------------------------------- */
uint8_t controller_get_output(const controller_t *c, int relay)
{
    if (relay < 0 || relay >= OUTPUT_COUNT) return 0;
    return c->outputs[relay];
}
```

