/***********************************************************************
 *  Banker's Algorithm + Round‑Robin Scheduler (demo)
 *  -------------------------------------------------
 *  - 3 resource types: A(10), B(15), C(8)
 *  - up to 5 concurrent processes (p1‑p5)
 *  - each process is represented by a PCB
 *  - random resource request each time slice
 *  - deadlock‑free via Banker's safety check
 *  - after finishing a process releases resources & a new process is
 *    created randomly.
 *
 *  编译:  gcc -Wall -Wextra -O2 banker_sim.c -o banker_sim
 *  运行:  ./banker_sim
 *
 *  这个实现主要用于教学/演示，**不要在生产系统中直接使用**。
 ***********************************************************************/

#define _POSIX_C_SOURCE 200809L   // for getline()
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <stdbool.h>

/* --------------------------- 常量定义 --------------------------- */
#define N_RES   3               // 资源种类数
#define MAX_PROC 5              // 系统最大并发进程数
#define TIME_SLICE 1            // 时间片长度（抽象为一次调度）

/* 资源名称，仅用于输出 */
static const char *res_name[N_RES] = {"A", "B", "C"};

/* 系统总资源向量 */
static const int TOTAL_RES[N_RES] = {10, 15, 8};

/* --------------------------- 数据结构 --------------------------- */

/* 进程状态 */
typedef enum { W = 0, R, B, F } ProcState;
static const char *state_str[] = {"W", "R", "B", "F"};

/* 进程控制块（PCB） */
typedef struct {
    char name[8];               // 进程名 p1~p5
    int max[N_RES];             // 需求上限
    int alloc[N_RES];           // 已分配
    int need[N_RES];            // 仍需
    ProcState state;            // 当前状态
    bool valid;                 // PCB 是否已被占用（删除后可复用）
} PCB;

/* 环形队列：用于就绪、阻塞、完成三个列表 */
typedef struct {
    int data[MAX_PROC];
    int head, tail, cnt;
} Queue;

/* --------------------------- 全局变量 --------------------------- */
static PCB pcb[MAX_PROC];               // 进程表（固定大小，最多5个活跃）
static int available[N_RES];            // 系统当前可用资源向量

static Queue ready_q, block_q, finish_q;

/* --------------------------- 队列操作 --------------------------- */
static void q_init(Queue *q) { q->head = q->tail = q->cnt = 0; }
static bool q_empty(const Queue *q) { return q->cnt == 0; }
static bool q_full(const Queue *q) { return q->cnt == MAX_PROC; }

static void q_push(Queue *q, int pid) {
    if (q_full(q)) { fprintf(stderr, "Queue overflow!\n"); exit(EXIT_FAILURE); }
    q->data[q->tail] = pid;
    q->tail = (q->tail + 1) % MAX_PROC;
    q->cnt++;
}
static int q_pop(Queue *q) {
    if (q_empty(q)) { fprintf(stderr, "Queue underflow!\n"); exit(EXIT_FAILURE); }
    int pid = q->data[q->head];
    q->head = (q->head + 1) % MAX_PROC;
    q->cnt--;
    return pid;
}

/* 直接遍历队列，用于打印或遍历 */
static void q_foreach(const Queue *q, void (*func)(int pid, void *arg), void *arg) {
    for (int i = 0, idx = q->head; i < q->cnt; ++i) {
        func(q->data[idx], arg);
        idx = (idx + 1) % MAX_PROC;
    }
}

/* --------------------------- 辅助函数 --------------------------- */

/* 复制向量 */
static void vec_copy(int dst[N_RES], const int src[N_RES]) {
    for (int i = 0; i < N_RES; ++i) dst[i] = src[i];
}

/* 向量相等比较 */
static bool vec_eq(const int a[N_RES], const int b[N_RES]) {
    for (int i = 0; i < N_RES; ++i)
        if (a[i] != b[i]) return false;
    return true;
}

/* 向量是否 <= */
static bool vec_le(const int a[N_RES], const int b[N_RES]) {
    for (int i = 0; i < N_RES; ++i)
        if (a[i] > b[i]) return false;
    return true;
}

/* 向量加 / 减 */
static void vec_add(int a[N_RES], const int b[N_RES]) {
    for (int i = 0; i < N_RES; ++i) a[i] += b[i];
}
static void vec_sub(int a[N_RES], const int b[N_RES]) {
    for (int i = 0; i < N_RES; ++i) a[i] -= b[i];
}

/* 随机产生 0..max 的整数（含 max） */
static int rand_range(int max) {
    return (max <= 0) ? 0 : (rand() % (max + 1));
}

/* --------------------------- 安全性检查（银行家） --------------------------- */
static bool is_safe(void) {
    int work[N_RES];
    bool finish[MAX_PROC] = {0};

    vec_copy(work, available);

    /* 简单的安全性检测循环 */
    bool made_progress;
    do {
        made_progress = false;
        for (int pid = 0; pid < MAX_PROC; ++pid) {
            if (!pcb[pid].valid) continue;
            if (finish[pid]) continue;
            if (pcb[pid].state == F) {                     // 已完成的进程直接标记完成
                finish[pid] = true;
                made_progress = true;
                continue;
            }
            if (vec_le(pcb[pid].need, work)) {
                /* 假设该进程一次性得到所需资源并完成 */
                vec_add(work, pcb[pid].alloc);
                finish[pid] = true;
                made_progress = true;
            }
        }
    } while (made_progress);

    /* 若所有活跃进程都标记完成，则系统安全 */
    for (int pid = 0; pid < MAX_PROC; ++pid) {
        if (!pcb[pid].valid) continue;
        if (!finish[pid]) return false;
    }
    return true;
}

/* --------------------------- 资源请求 --------------------------- */
static void request_resources(int pid) {
    PCB *p = &pcb[pid];
    if (p->state != R) return;   // 只对运行状态的进程发起请求

    /* 随机产生一次请求，范围在 need 范围之内 */
    int request[N_RES];
    bool any = false;
    for (int i = 0; i < N_RES; ++i) {
        request[i] = rand_range(p->need[i]);
        if (request[i] > 0) any = true;
    }
    if (!any) return;   // 本次时间片没有实际请求

    /* 检查需求是否超过可用资源 */
    if (!vec_le(request, available)) {
        /* 资源不足，直接进入阻塞 */
        p->state = B;
        q_push(&block_q, pid);
        printf("  %s 请求资源失败(不足)，进入阻塞 B\n", p->name);
        return;
    }

    /* 暂时分配，随后安全性检查 */
    vec_sub(available, request);
    vec_add(p->alloc, request);
    vec_sub(p->need, request);

    printf("  %s 发起请求: ", p->name);
    for (int i = 0; i < N_RES; ++i) printf("%s=%d ", res_name[i], request[i]);
    printf("\n");

    if (!is_safe()) {
        /* 不安全——回滚并阻塞 */
        vec_add(available, request);
        vec_sub(p->alloc, request);
        vec_add(p->need, request);
        p->state = B;
        q_push(&block_q, pid);
        printf("  请求后系统不安全，%s 进入阻塞 B\n", p->name);
    } else {
        printf("  请求被批准，系统保持安全。\n");
    }
}

/* --------------------------- 资源释放（进程完成） --------------------------- */
static void release_resources(int pid) {
    PCB *p = &pcb[pid];
    printf("  %s 完成，释放资源: ", p->name);
    for (int i = 0; i < N_RES; ++i) {
        if (p->alloc[i] > 0)
            printf("%s=%d ", res_name[i], p->alloc[i]);
        available[i] += p->alloc[i];
        p->alloc[i] = 0;
        p->need[i] = 0;
    }
    printf("\n");

    p->state = F;
    q_push(&finish_q, pid);
}

/* --------------------------- 进程唤醒 --------------------------- */
static void try_wakeup(void) {
    // 逐个检查阻塞队列的进程，看是否可以满足全部需求
    int size = block_q.cnt;
    for (int i = 0; i < size; ++i) {
        int pid = q_pop(&block_q);
        PCB *p = &pcb[pid];
        if (p->state != B) {   // safety, shouldn't happen
            continue;
        }
        if (vec_le(p->need, available)) {
            // 这里不必再次安全性检查，因为当我们进入阻塞时已经保证系统安全；
            // 只要资源足够，就一定可以安全分配。
            vec_sub(available, p->need);
            vec_add(p->alloc, p->need);
            for (int k = 0; k < N_RES; ++k) p->need[k] = 0;
            p->state = R;   // 直接进入就绪（下一轮调度会执行）
            q_push(&ready_q, pid);
            printf("  %s 被唤醒并放入就绪队列 R\n", p->name);
        } else {
            // 仍然阻塞，保留在队列尾部
            q_push(&block_q, pid);
        }
    }
}

/* --------------------------- 进程创建 --------------------------- */
static void create_process(void) {
    // 寻找一个空闲 PCB 槽
    int pid = -1;
    for (int i = 0; i < MAX_PROC; ++i) {
        if (!pcb[i].valid) { pid = i; break; }
    }
    if (pid == -1) return;   // 已经达到系统上限

    PCB *p = &pcb[pid];
    p->valid = true;
    snprintf(p->name, sizeof(p->name), "p%d", pid + 1);
    p->state = R;

    // 随机生成 max 需求，必须不超过系统总资源的上限
    for (int i = 0; i < N_RES; ++i) {
        int upper = TOTAL_RES[i];   // 简单做法：不考虑当前已分配，只要不超过硬上限即可
        p->max[i] = rand_range(upper);
        p->alloc[i] = 0;
        p->need[i] = p->max[i];
    }

    // 让进程直接进入就绪队列
    q_push(&ready_q, pid);

    printf("=== 新进程 %s 创建 ===\n", p->name);
}

/* --------------------------- 打印帮助函数 --------------------------- */
static void print_pcb(int pid, void *arg) {
    PCB *p = &pcb[pid];
    printf("  %-4s  状态:%s  Max:", p->name, state_str[p->state]);
    for (int i = 0; i < N_RES; ++i) printf("%s=%d ", res_name[i], p->max[i]);
    printf(" Alloc:");
    for (int i = 0; i < N_RES; ++i) printf("%s=%d ", res_name[i], p->alloc[i]);
    printf(" Need:");
    for (int i = 0; i < N_RES; ++i) printf("%s=%d ", res_name[i], p->need[i]);
    printf("\n");
}

static void print_queue(const char *title, const Queue *q) {
    printf("%s[", title);
    if (!q_empty(q)) {
        for (int i = 0, idx = q->head; i < q->cnt; ++i) {
            int pid = q->data[idx];
            printf("%s", pcb[pid].name);
            if (i != q->cnt - 1) printf(", ");
            idx = (idx + 1) % MAX_PROC;
        }
    }
    printf("]\n");
}

/* --------------------------- 调度器（时间片轮转） --------------------------- */
static void schedule_one_tick(void) {
    if (q_empty(&ready_q)) {
        printf("== 没有就绪进程，系统空闲 ==\n");
        return;
    }

    // 取出就绪队列头部进程执行一个时间片
    int pid = q_pop(&ready_q);
    PCB *p = &pcb[pid];
    p->state = R;
    printf("\n--- 调度: %s 进入运行状态 R ---\n", p->name);

    // 1. 随机产生资源请求（若已满足需求则直接完成）
    if (vec_eq(p->need, (int[N_RES]){0,0,0})) {
        // 已经得到全部资源，直接完成
        release_resources(pid);
    } else {
        request_resources(pid);
        // 如果仍然在运行状态（未被阻塞），则视为执行完本时间片
        if (p->state == R) {
            // 时间片结束后，仍维持在就绪队列尾部
            p->state = W;     // 暂时标记为等待（下一次调度再进入 R）
            q_push(&ready_q, pid);
            printf("  %s 时间片结束，返回就绪队列 W\n", p->name);
        }
    }

    // 2. 检查是否有进程已经完成（在 request 里已经完成或在上面手动完成）
    //    完成后会自动释放资源，随后尝试唤醒阻塞进程
    try_wakeup();   // 在每一次调度后都尝试一次唤醒

    // 3. 打印当前系统状态
    printf("\n=== 系统状态快照 ===\n");
    // 正在运行的进程（本轮只有一个）
    printf("Running: %s\n", (p->state == R) ? p->name : "None");
    print_queue("Ready :", &ready_q);
    print_queue("Block :", &block_q);
    print_queue("Finish:", &finish_q);
    printf("Available resources: ");
    for (int i = 0; i < N_RES; ++i) printf("%s=%d ", res_name[i], available[i]);
    printf("\n");
    printf("\n--- 所有 PCB ---\n");
    for (int i = 0; i < MAX_PROC; ++i) {
        if (pcb[i].valid) print_pcb(i, NULL);
    }
    printf("\n");
}

/* --------------------------- 主函数 --------------------------- */
int main(void) {
    srand((unsigned)time(NULL));

    // 初始化资源、队列、PCB表
    vec_copy((int *)available, (int *)TOTAL_RES);
    q_init(&ready_q);
    q_init(&block_q);
    q_init(&finish_q);
    for (int i = 0; i < MAX_PROC; ++i) pcb[i].valid = false;

    // 初始生成若干进程（不超过 5）
    int init_proc = rand_range(MAX_PROC - 1) + 1;   // 至少 1 个
    for (int i = 0; i < init_proc; ++i) create_process();

    // 主循环：只要还有活跃进程，就一直调度下去
    while (!q_empty(&ready_q) || !q_empty(&block_q)) {
        schedule_one_tick();

        // 若系统中活跃进程数量 < MAX_PROC 并且阻塞/就绪都为空，随机创建新进程
        int alive_cnt = 0;
        for (int i = 0; i < MAX_PROC; ++i) if (pcb[i].valid && pcb[i].state != F) ++alive_cnt;
        if (alive_cnt < MAX_PROC && q_empty(&ready_q) && q_empty(&block_q)) {
            create_process();
        }
    }

    printf("\n=== 所有进程已完成，模拟结束 ===\n");
    return 0;
}
```

