/* todo.h – public API for the todo list */
#ifndef TODO_H
#define TODO_H

#include <stddef.h>
#include <stdbool.h>

/* Maximum length of a single todo entry (including terminating NUL) */
#define TODO_MAX_LEN 256

/* One todo item */
typedef struct {
    char text[TODO_MAX_LEN];
    bool done;                /* optional flag – not used in the CLI but handy */
} TodoItem;

/* Opaque handle for the todo database */
typedef struct TodoDB TodoDB;

/* Load (or create) a todo DB from the given path.
 * Returns NULL on fatal error.
 * The `key` and `key_len` arguments are used for optional encryption.
 * Pass key_len == 0 for plain‑text storage.
 */
TodoDB *todo_load(const char *path,
                  const unsigned char *key,
                  size_t key_len);

/* Persist the DB back to disk (atomic – writes to a temp file then rename). */
bool todo_save(TodoDB *db);

/* Append a new entry. Returns true on success. */
bool todo_add(TodoDB *db, const char *text);

/* Delete an entry by zero‑based index. Returns true on success. */
bool todo_del(TodoDB *db, size_t idx);

/* List all entries – caller supplies a callback to avoid leaking
 * implementation details (e.g., if you later switch to SQLite). */
typedef void (*todo_list_cb)(size_t idx, const TodoItem *item, void *user);
void todo_list(const TodoDB *db, todo_list_cb cb, void *user);

/* Release resources */
void todo_free(TodoDB *db);

#endif /* TODO_H */
```

