### `todo.c`

```c
/* todo.c – core todo implementation (no UI) */
#define _POSIX_C_SOURCE 200809L   /* for strdup, fchmod, etc. */
#include "todo.h"
#include "crypto.h"

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/stat.h>
#include <errno.h>
#include <unistd.h>

/* Simple dynamic array */
struct TodoDB {
    TodoItem *items;
    size_t    count;
    size_t    cap;
    char     *path;      /* full path of the db file */
    unsigned char key[32];
    size_t        key_len;
};

/* internal helpers ---------------------------------------------------------- */
static bool ensure_capacity(TodoDB *db, size_t need)
{
    if (db->cap >= need) return true;
    size_t newcap = db->cap ? db->cap * 2 : 8;
    while (newcap < need) newcap *= 2;
    TodoItem *tmp = realloc(db->items, newcap * sizeof(*tmp));
    if (!tmp) return false;
    db->items = tmp;
    db->cap   = newcap;
    return true;
}

/* -------------------------------------------------------------------------- */
TodoDB *todo_load(const char *path,
                  const unsigned char *key,
                  size_t key_len)
{
    TodoDB *db = calloc(1, sizeof(*db));
    if (!db) return NULL;
    db->path = strdup(path);
    if (!db->path) { free(db); return NULL; }

    if (key_len) {
        memcpy(db->key, key, key_len > sizeof(db->key) ? sizeof(db->key) : key_len);
        db->key_len = key_len;
    }

    /* Try to open the file (may not exist yet). */
    FILE *fp = fopen(path, "rb");
    if (!fp) {
        if (errno == ENOENT) {
            /* No file – start with empty DB */
            return db;
        }
        perror("fopen");
        goto fail;
    }

    /* Read whole file into memory (small DB – fine). */
    fseek(fp, 0, SEEK_END);
    long fsize = ftell(fp);
    if (fsize < 0) { perror("ftell"); fclose(fp); goto fail; }
    rewind(fp);

    if (fsize == 0) { /* empty file */
        fclose(fp);
        return db;
    }

    unsigned char *buf = malloc(fsize);
    if (!buf) { fclose(fp); goto fail; }

    if (fread(buf, 1, fsize, fp) != (size_t)fsize) {
        perror("fread");
        free(buf); fclose(fp); goto fail;
    }
    fclose(fp);

    /* Decrypt if needed */
    if (db->key_len) {
        xor_crypt(buf, fsize, db->key, db->key_len);
    }

    /* Parse entries: each entry is stored as:
     *   uint32_t len (including NUL)   <-- little‑endian
     *   char text[len]
     *   uint8_t done flag (0/1)
     */
    size_t offset = 0;
    while (offset + sizeof(uint32_t) + 1 <= (size_t)fsize) {
        uint32_t txt_len;
        memcpy(&txt_len, buf + offset, sizeof(txt_len));
        offset += sizeof(uint32_t);
        if (txt_len == 0 || txt_len > TODO_MAX_LEN) { /* sanity check */
            fprintf(stderr, "Corrupt db (bad length %u)\n", txt_len);
            free(buf);
            goto fail;
        }
        if (offset + txt_len + 1 > (size_t)fsize) {
            fprintf(stderr, "Corrupt db (truncated entry)\n");
            free(buf);
            goto fail;
        }
        if (!ensure_capacity(db, db->count + 1)) {
            free(buf);
            goto fail;
        }
        TodoItem *it = &db->items[db->count];
        memcpy(it->text, buf + offset, txt_len);
        it->text[TODO_MAX_LEN-1] = '\0'; /* safety */
        offset += txt_len;
        it->done = buf[offset++];
        db->count++;
    }

    /* zero the temporary buffer */
    explicit_bzero(buf, fsize);
    free(buf);
    return db;

fail:
    free(db->path);
    free(db->items);
    free(db);
    return NULL;
}

/* -------------------------------------------------------------------------- */
bool todo_save(TodoDB *db)
{
    /* Serialize to a memory buffer first */
    size_t needed = 0;
    for (size_t i = 0; i < db->count; ++i) {
        size_t txt_len = strnlen(db->items[i].text, TODO_MAX_LEN) + 1; /* include NUL */
        needed += sizeof(uint32_t) + txt_len + 1; /* len + text + done */
    }

    unsigned char *buf = malloc(needed);
    if (!buf) return false;

    size_t off = 0;
    for (size_t i = 0; i < db->count; ++i) {
        uint32_t txt_len = (uint32_t)strnlen(db->items[i].text, TODO_MAX_LEN) + 1;
        memcpy(buf + off, &txt_len, sizeof(txt_len));
        off += sizeof(uint32_t);
        memcpy(buf + off, db->items[i].text, txt_len);
        off += txt_len;
        buf[off++] = db->items[i].done ? 1 : 0;
    }

    /* Encrypt in‑place if a key is set */
    if (db->key_len) {
        xor_crypt(buf, needed, db->key, db->key_len);
    }

    /* Write to a temporary file in the same directory */
    char tmp_path[PATH_MAX];
    snprintf(tmp_path, sizeof(tmp_path), "%s.tmp.XXXXXX", db->path);
    int fd = mkstemp(tmp_path);
    if (fd == -1) {
        perror("mkstemp");
        explicit_bzero(buf, needed);
        free(buf);
        return false;
    }

    /* Set permissions to 0600 before writing */
    if (fchmod(fd, S_IRUSR | S_IWUSR) == -1) {
        perror("fchmod");
        close(fd);
        unlink(tmp_path);
        explicit_bzero(buf, needed);
        free(buf);
        return false;
    }

    FILE *fp = fdopen(fd, "wb");
    if (!fp) {
        perror("fdopen");
        close(fd);
        unlink(tmp_path);
        explicit_bzero(buf, needed);
        free(buf);
        return false;
    }

    if (fwrite(buf, 1, needed, fp) != needed) {
        perror("fwrite");
        fclose(fp);
        unlink(tmp_path);
        explicit_bzero(buf, needed);
        free(buf);
        return false;
    }
    fclose(fp);
    explicit_bzero(buf, needed);
    free(buf);

    /* Atomically replace the old file */
    if (rename(tmp_path, db->path) != 0) {
        perror("rename");
        unlink(tmp_path);
        return false;
    }
    return true;
}

/* -------------------------------------------------------------------------- */
bool todo_add(TodoDB *db, const char *text)
{
    if (!ensure_capacity(db, db->count + 1))
        return false;
    TodoItem *it = &db->items[db->count];
    strncpy(it->text, text, TODO_MAX_LEN - 1);
    it->text[TODO_MAX_LEN - 1] = '\0';
    it->done = false;
    db->count++;
    return true;
}

/* -------------------------------------------------------------------------- */
bool todo_del(TodoDB *db, size_t idx)
{
    if (idx >= db->count) return false;
    /* Shift everything left */
    for (size_t i = idx; i + 1 < db->count; ++i)
        db->items[i] = db->items[i + 1];
    db->count--;
    return true;
}

/* -------------------------------------------------------------------------- */
void todo_list(const TodoDB *db, todo_list_cb cb, void *user)
{
    for (size_t i = 0; i < db->count; ++i)
        cb(i, &db->items[i], user);
}

/* -------------------------------------------------------------------------- */
void todo_free(TodoDB *db)
{
    if (!db) return;
    /* Zero out any secrets */
    explicit_bzero(db->items, db->cap * sizeof(TodoItem));
    free(db->items);
    free(db->path);
    explicit_bzero(db->key, sizeof(db->key));
    free(db);
}
```

