#include "crypto.h"

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <pwd.h>
#include <sys/types.h>
#include <errno.h>
#include <termios.h>

/* --------------------------------------------------------------
 * Helper: securely read a passphrase (no echo).  Returns a heap
 * allocated buffer that must be freed by the caller.  On error
 * returns NULL.
 * -------------------------------------------------------------- */
static char *read_passphrase(const char *prompt)
{
    struct termios old, new;
    if (tcgetattr(STDIN_FILENO, &old) != 0) return NULL;
    new = old;
    new.c_lflag &= ~ECHO;
    if (tcsetattr(STDIN_FILENO, TCSAFLUSH, &new) != 0) return NULL;
    fprintf(stderr, "%s", prompt);
    fflush(stderr);

    char *buf = NULL;
    size_t cap = 0;
    ssize_t len = getline(&buf, &cap, stdin);
    tcsetattr(STDIN_FILENO, TCSAFLUSH, &old);
    fprintf(stderr, "\n");
    if (len <= 0) {
        free(buf);
        return NULL;
    }
    /* strip trailing newline */
    if (buf[len-1] == '\n')
        buf[len-1] = '\0';
    return buf;
}

/* --------------------------------------------------------------
 * Print usage
 * -------------------------------------------------------------- */
static void usage(const char *prog)
{
    fprintf(stderr,
            "Usage: %s [options] <command> [args]\n"
            "\n"
            "Commands:\n"
            "  add <text>          Add a new todo item\n"
            "  list                List all items (numbered)\n"
            "  del <index>         Delete the item at <index>\n"
            "  clear               Remove *all* items (dangerous!)\n"
            "\n"
            "Options:\n"
