     * ----------------------------------------------------------------- */
    unsigned char keybuf[32] = {0};
    size_t key_len = 0;
    if (encrypt) {
        char *pw = read_passphrase("Enter encryption passphrase: ");
        if (!pw) {
            fprintf(stderr, "Failed to read passphrase.\n");
            return EXIT_FAILURE;
        }
        /* Derive a simple 256‑bit key by repeating the passphrase.
         * **Do NOT** use this in production – use a proper KDF (e.g. Argon2). */
        size_t pw_len = strlen(pw);
        for (size_t i = 0; i < sizeof(keybuf); ++i)
            keybuf[i] = (unsigned char)pw[i % pw_len];
        key_len = sizeof(keybuf);
        explicit_bzero(pw, pw_len);
        free(pw);
    }

    /* -----------------------------------------------------------------
     * Load database
     * ----------------------------------------------------------------- */
    char *path = db_path();
    if (!path) return EXIT_FAILURE;

    TodoDB *db = todo_load(path, keybuf, key_len);
    if (!db) {
        fprintf(stderr, "Failed to load todo DB.\n");
        free(path);
        return EXIT_FAILURE;
    }

    int rc = EXIT_SUCCESS;

    /* -----------------------------------------------------------------
     * Dispatch commands
     * ----------------------------------------------------------------- */
    if (strcmp(cmd, "add") == 0) {
        if (optind + 1 >= argc) {
            fprintf(stderr, "Error: 'add' needs a todo string.\n");
            rc = EXIT_FAILURE;
            goto out;
        }
        const char *text = argv[optind + 1];
        if (!todo_add(db, text)) {
            fprintf(stderr, "Failed to add entry.\n");
            rc = EXIT_FAILURE;
            goto out;
        }
        if (!todo_save(db)) {
            fprintf(stderr, "Failed to write DB.\n");
            rc = EXIT_FAILURE;
        }
    }
    else if (strcmp(cmd, "list") == 0) {
        todo_list(db, list_cb, NULL);
    }
    else if (strcmp(cmd, "del") == 0) {
        if (optind + 1 >= argc) {
            fprintf(stderr, "Error: 'del' needs an index.\n");
            rc = EXIT_FAILURE;
            goto out;
        }
        char *endptr;
        long idx = strtol(argv[optind + 1], &endptr, 10);
        if (*endptr || idx < 0) {
            fprintf(stderr, "Invalid index.\n");
            rc = EXIT_FAILURE;
            goto out;
        }
        if (!todo_del(db, (size_t)idx)) {
            fprintf(stderr, "No such entry.\n");
            rc = EXIT_FAILURE;
            goto out;
        }
        if (!todo_save(db)) {
            fprintf(stderr, "Failed to write DB.\n");
            rc = EXIT_FAILURE;
        }
    }
    else if (strcmp(cmd, "clear") == 0) {
        /* Very destructive – ask for confirmation */
        char answer[4];
        printf("Delete *all* todo items? [y/N] ");
        if (!fgets(answer, sizeof(answer), stdin) || answer[0] != 'y') {
            printf("Aborted.\n");
            rc = EXIT_FAILURE;
            goto out;
        }
        /* Re‑initialize the DB struct (free old items) */
        free(db->items);
        db->items = NULL;
        db->count = db->cap = 0;
        if (!todo_save(db)) {
            fprintf(stderr, "Failed to write empty DB.\n");
            rc = EXIT_FAILURE;
        }
    }
    else {
        fprintf(stderr, "Unknown command: %s\n", cmd);
        usage(argv[0]);
        rc = EXIT_FAILURE;
    }

out:
    todo_free(db);
    free(path);
    /* clear the key from memory */
    explicit_bzero(keybuf, sizeof(keybuf));
    return rc;
}
