#define _POSIX_C_SOURCE 200809L
#include "todo.h"
#include "crypto.h"
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/stat.h>
#include <unistd.h>
struct TodoDB {
    TodoItem *items;
    size_t count, cap;
    char *path;
    unsigned char key[32];
    size_t key_len;
};
static bool ensure(TodoDB *db,size_t n){
    if(db->cap>=n)return true;
    size_t c=db->cap?db->cap*2:8;
    while(c<n)c*=2;
    TodoItem *tmp=realloc(db->items,c*sizeof(*tmp));
    if(!tmp)return false;
    db->items=tmp;db->cap=c;return true;
}
TodoDB*todo_load(const char*path,const unsigned char*key,size_t klen){
    TodoDB*db=calloc(1,sizeof(*db));
    db->path=strdup(path);
    if(klen){memcpy(db->key,key,sizeof(db->key));db->key_len=klen;}
    FILE*fp=fopen(path,"rb");
    if(!fp){if(errno==ENOENT)return db;perror("fopen");goto fail;}
    fseek(fp,0,SEEK_END);
    long sz=ftell(fp);rewind(fp);
    if(sz<=0){fclose(fp);return db;}
    unsigned char*buf=malloc(sz);
    fread(buf,1,sz,fp);
    fclose(fp);
    if(db->key_len)xor_crypt(buf,sz,db->key,db->key_len);
    size_t off=0;
    while(off+4<= (size_t)sz){
        uint32_t l;memcpy(&l,buf+off,4);off+=4;
        if(off+l+1> (size_t)sz)break;
        if(!ensure(db,db->count+1))break;
        TodoItem*i=&db->items[db->count++];
        memcpy(i->text,buf+off,l);
        i->text[TODO_MAX_LEN-1]=0;
        off+=l;
        i->done=buf[off++];
    }
    explicit_bzero(buf,sz);free(buf);
    return db;
fail:
    free(db->path);free(db);return NULL;
}
bool todo_save(TodoDB*db){
    size_t needed=0;
    for(size_t i=0;i<db->count;i++){
        size_t l=strnlen(db->items[i].text,TODO_MAX_LEN)+1;
        needed+=4+l+1;
    }
    unsigned char*buf=malloc(needed);
    size_t off=0;
    for(size_t i=0;i<db->count;i++){
        uint32_t l=strnlen(db->items[i].text,TODO_MAX_LEN)+1;
        memcpy(buf+off,&l,4);off+=4;
        memcpy(buf+off,db->items[i].text,l);off+=l;
        buf[off++]=db->items[i].done;
    }
    if(db->key_len)xor_crypt(buf,needed,db->key,db->key_len);
    char tmp[PATH_MAX];
    snprintf(tmp,sizeof(tmp),"%s.tmp.XXXXXX",db->path);
    int fd=mkstemp(tmp);
    fchmod(fd,0600);
    FILE*fp=fdopen(fd,"wb");
    fwrite(buf,1,needed,fp);
    fclose(fp);
    explicit_bzero(buf,needed);free(buf);
    rename(tmp,db->path);
    return true;
}
bool todo_add(TodoDB*db,const char*txt){
    if(!ensure(db,db->count+1))return false;
    TodoItem*i=&db->items[db->count++];
    strncpy(i->text,txt,TODO_MAX_LEN-1);
    i->done=0;return true;
}
bool todo_del(TodoDB*db,size_t idx){
    if(idx>=db->count)return false;
    for(size_t i=idx;i+1<db->count;i++)db->items[i]=db->items[i+1];
    db->count--;return true;
}
void todo_list(const TodoDB*db,todo_list_cb cb,void*u){
    for(size_t i=0;i<db->count;i++)cb(i,&db->items[i],u);
}
void todo_free(TodoDB*db){
    explicit_bzero(db->items,db->cap*sizeof(*db->items));
    free(db->items);free(db->path);free(db);
}
