const int MAX_FILA     = 5;   /* tamanho máximo da fila de espera            */
const int DISPONIVEL   = 1;   /* 1 = disponível, 0 = emprestado              */
const int EMPRESTADO   = 0;

/* ---------- Estruturas ---------- */
