void limparTela(void);
void pausa(void);
void menu(void);

void inserirLivro(void);
int  buscarLivroPorCodigo(int codigo);
int  buscarLivroPorNome(const char *nome);
void listarLivros(void);
void buscarDisponibilidade(void);
void atualizarDisponibilidade(int codigo, int novoStatus);
