    system("cls");
#else
    system("clear");
#endif
}

/* Pausa aguardando tecla ENTER */
void pausa(void){
    printf("\nPressione <Enter> para continuar...");
    getchar();
}

/* ---------- Implementação das rotinas ---------- */

/* 1 – Inserir um novo livro no vetor */
