        printf("\n>>> Vetor de livros está cheio! <<<\n");
        return;
    }

    Livro l;
    printf("\n--- Inserir Livro ---\n");
    printf("Código do livro: ");
    scanf("%d", &l.codigo);
    getchar(); /* consumir '\n' */
    /* Verifica se já existe um livro com esse código */
    if (buscarLivroPorCodigo(l.codigo) != -1){
        printf("Já existe um livro com esse código.\n");
        return;
    }

    printf("Nome do livro: ");
    fgets(l.nome, sizeof(l.nome), stdin);
    l.nome[strcspn(l.nome, "\n")] = '\0';   /* remover '\n' */

    l.disponivel = DISPONIVEL;  /* ao inserir, o livro começa disponível */

    livros[qtdLivros++] = l;
