    return -1;
}

/* 3 – Busca linear por nome – devolve posição ou -1 */
int buscarLivroPorNome(const char *nome){
    for (int i = 0; i < qtdLivros; i++){
        if (strcasecmp(livros[i].nome, nome) == 0)
            return i;
