    int pos = buscarLivroPorCodigo(codigo);
    if (pos == -1){
        printf("Livro não encontrado.\n");
        return;
    }

    printf("Livro: %s\n", livros[pos].nome);
    if (livros[pos].disponivel == DISPONIVEL){
        printf("Situação: DISPONÍVEL\n");
    }else{
        printf("Situação: EMPRESTADO\n");
        printf("\nDeseja entrar na fila de espera? (s/n) ");
        char resp = getchar();
        getchar(); /* consumir ENTER */
        if (resp == 's' || resp == 'S'){
            inserirPessoaFila();
