    Pedido p;
    printf("\n--- Inserir Pessoa na Fila de Espera ---\n");
    printf("Nome da pessoa: ");
    fgets(p.nomePessoa, sizeof(p.nomePessoa), stdin);
    p.nomePessoa[strcspn(p.nomePessoa, "\n")] = '\0';

    printf("Telefone para contato: ");
    fgets(p.telefone, sizeof(p.telefone), stdin);
    p.telefone[strcspn(p.telefone, "\n")] = '\0';

    /* Como a função que chamará este procedimento já conhece o código
       do livro (veio da consulta), pedimos que o usuário informe novamente
       o código ou nome do livro desejado.  */
    printf("Código do livro desejado: ");
    scanf("%d", &p.codigoLivro);
    getchar(); /* consumir '\n' */

    int posLivro = buscarLivroPorCodigo(p.codigoLivro);
    if (posLivro == -1){
        printf("Livro não encontrado. Pedido não inserido.\n");
        return;
    }
    strcpy(p.nomeLivro, livros[posLivro].nome);

    fila[qtdFila++] = p;
    printf("Pessoa inserida na fila de espera com sucesso.\n");
}

/* 8 – Listar a fila de espera (na ordem de entrada) */
void listarFila(void){
    printf("\n--- Fila de Espera ---\n");
    if (qtdFila == 0){
        printf("Não há pedidos na fila.\n");
        return;
    }

    printf("%-5s  %-30s  %-15s  %-20s\n",
           "Cod", "Livro", "Pessoa", "Telefone");
    for (int i = 0; i < qtdFila; i++){
        printf("%-5d  %-30s  %-15s  %-20s\n",
               fila[i].codigoLivro,
               fila[i].nomeLivro,
               fila[i].nomePessoa,
               fila[i].telefone);
    }
}

/* 9 – Remover um elemento da fila (por índice) – desloca o restante */
void removerDaFila(int indice){
    if (indice < 0 || indice >= qtdFila) return;
    for (int i = indice; i < qtdFila - 1; i++){
        fila[i] = fila[i+1];
    }
    qtdFila--;
}

/* 10 – Quando um livro volta a ficar disponível, atender o primeiro
        da fila que está esperando por ele */
void atenderProximoDaFila(int codigoLivro){
    for (int i = 0; i < qtdFila; i++){
        if (fila[i].codigoLivro == codigoLivro){
            /* Encontrado – simula o empréstimo ao usuário da fila */
            printf("\n--- Atendimento da fila ---\n");
            printf("Livro \"%s\" está disponível.\n", fila[i].nomeLivro);
            printf("Atendendo: %s (Telefone: %s)\n",
                   fila[i].nomePessoa, fila[i].telefone);
            /* O livro passa a estar emprestado novamente */
            atualizarDisponibilidade(codigoLivro, EMPRESTADO);
            /* Remove o registro da fila */
            removerDaFila(i);
            return;
        }
    }
    /* Se não houver ninguém esperando, apenas deixa o livro como disponível */
    atualizarDisponibilidade(codigoLivro, DISPONIVEL);
}

/* ---------- Menu principal ---------- */
void menu(void){
    int opcao;
    do{
        limparTela();
        printf("=== SISTEMA DE BIBLIOTECA - FILA DE ESPERA ===\n");
        printf("1  - Inserir livro\n");
        printf("2  - Consultar disponibilidade (e entrar na fila)\n");
        printf("3  - Listar livros cadastrados\n");
        printf("4  - Listar fila de espera\n");
        printf("5  - Devolver livro (atualiza disponibilidade)\n");
        printf("6  - Remover pessoa da fila (caso queira cancelar)\n");
        printf("0  - Sair\n");
        printf("\nEscolha uma opção: ");
        scanf("%d", &opcao);
        getchar(); /* consumir '\n' */

        switch(opcao){
            case 1:
                inserirLivro();
                pausa(); break;
            case 2:
                buscarDisponibilidade();
                pausa(); break;
            case 3:
                listarLivros();
                pausa(); break;
            case 4:
                listarFila();
                pausa(); break;
            case 5: {
                int cod;
                printf("\n--- Devolução de Livro ---\n");
                printf("Informe o código do livro que está sendo devolvido: ");
                scanf("%d", &cod);
                getchar();
                int pos = buscarLivroPorCodigo(cod);
                if (pos == -1){
                    printf("Livro não encontrado.\n");
                }else{
                    /* Primeiro tenta atender a fila, caso exista alguém */
                    atenderProximoDaFila(cod);
                    printf("Devolução processada.\n");
                }
                pausa();
                break;
            }
            case 6: {
                if (qtdFila == 0){
                    printf("\nFila vazia.\n");
                    pausa();
                    break;
                }
                int indice;
                listarFila();
                printf("\nInforme a posição (0..%d) que deseja remover: ", qtdFila-1);
                scanf("%d", &indice);
                getchar();
                if (indice < 0 || indice >= qtdFila){
                    printf("Posição inválida.\n");
                }else{
                    printf("Removendo \"%s\" da fila.\n", fila[indice].nomePessoa);
                    removerDaFila(indice);
                }
                pausa();
                break;
            }
            case 0:
                printf("\nEncerrando o programa...\n");
                break;
            default:
                printf("\nOpção inválida!\n");
                pausa();
        }
    }while(opcao != 0);
}

/* ---------- Função principal ---------- */
int main(void){
    menu();
    return 0;
}
