 *
 *  Description:
 *      Reads a sequence of integers from stdin and reports how many distinct
 *      values appear more than once (repetitious numbers) and how many total
 *      extra occurrences there are.
 *
 *  Compile (gcc):
 *      gcc -Wall -Wextra -O2 -o repeat_counter repeat_counter.c
 *
 *  Usage (example):
 *      ./repeat_counter < numbers.txt
 *
 *  Input format:
 *      Any whitespace‑separated list of integers, e.g.
 *          5 2 7 5 3 2 2 9
 *
 *  Output (example for the above input):
 *      Repetitious distinct values : 2   // (5 and 2)
 *      Total extra repetitions      : 3   // (5 appears twice → 1 extra,
 *                                               2 appears three times → 2 extra)
 *
 *  The algorithm runs in O(n log n) time because of the sort, and uses
 *  O(n) memory.
 */

#include <stdio.h>
#include <stdlib.h>
#include <errno.h>
#include <string.h>

#define INITIAL_CAPACITY 64   /* start size for the dynamic array */

/* --------------------------------------------------------------- */
/* Helper: read all integers from stdin into a dynamically‑grown array */
static int *read_numbers(size_t *out_count)
{
    size_t capacity = INITIAL_CAPACITY;
    size_t count    = 0;
    int   *data     = malloc(capacity * sizeof(int));
    if (!data) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }

    /* Read ints until EOF or error */
    while (1) {
        int value;
        int rc = scanf("%d", &value);
        if (rc == EOF) break;
        if (rc != 1) {
            fprintf(stderr, "Invalid input encountered (non‑integer)\n");
            free(data);
            exit(EXIT_FAILURE);
        }

        /* Resize if needed */
        if (count == capacity) {
            capacity *= 2;
            int *tmp = realloc(data, capacity * sizeof(int));
            if (!tmp) {
                fprintf(stderr, "Memory reallocation failed\n");
                free(data);
                exit(EXIT_FAILURE);
            }
            data = tmp;
        }

        data[count++] = value;
    }

    *out_count = count;
    return data;
}

/* --------------------------------------------------------------- */
/* Comparison function for qsort (ascending order) */
static int cmp_int(const void *a, const void *b)
{
    int ia = *(const int *)a;
    int ib = *(const int *)b;
    return (ia > ib) - (ia < ib);
}

/* --------------------------------------------------------------- */
int main(void)
{
    size_t n;
    int *numbers = read_numbers(&n);

    if (n == 0) {
        printf("No numbers were provided.\n");
        free(numbers);
        return 0;
    }

    /* Sort the array – this groups equal values together */
    qsort(numbers, n, sizeof(int), cmp_int);

    size_t distinct_repetitious = 0;   /* how many *different* values repeat   */
    size_t total_extra        = 0;    /* sum of (occurrences‑1) for each repeat */

    size_t i = 0;
    while (i < n) {
        size_t run_len = 1;               /* length of the current equal run */
        while (i + run_len < n && numbers[i + run_len] == numbers[i])
            ++run_len;

        if (run_len > 1) {
            ++distinct_repetitious;
            total_extra += (run_len - 1);
        }
        i += run_len;
    }

    printf("Repetitious distinct values : %zu\n", distinct_repetitious);
    printf("Total extra repetitions      : %zu\n", total_extra);

    free(numbers);
    return 0;
}
```

### How It Works

1. **Reading Input**  
   - `read_numbers()` repeatedly calls `scanf("%d", …)` to fetch integers.  
   - The array grows by doubling its capacity whenever it becomes full.  
   - If the input contains a non‑numeric token, the program aborts with an error message.

2. **Sorting**  
   - `qsort()` arranges the numbers in non‑decreasing order.  
   - After sorting, equal numbers appear in contiguous blocks (a *run*).

3. **Scanning for Repetitions**  
   - A simple linear scan walks through the sorted array, measuring the length of each run.  
   - If a run length > 1, that value is **repetitious**.  
   - `distinct_repetitious` counts how many different values have a run length > 1.  
   - `total_extra` accumulates the “extra” occurrences, i.e., `run_len‑1` for each such run.

