/* Helper: swap two integers (inline for performance and clarity).       */
static inline void swap_int(int *x, int *y)
{
    int tmp = *x;
    *x = *y;
    *y = tmp;
}

/* --------------------------------------------------------------------- */
/* Reverse the contents of an integer array in place.                     */
/* Parameters:                                                            */
/*   arr  – pointer to first element (must be non‑NULL)                    */
/*   n    – number of elements in the array (size_t)                      */
/* Returns: 0 on success, non‑zero on error (e.g., NULL pointer).        */
