### 2.4  `enqueue(int value)`  

```c
void enqueue(int value) {
    struct node *ptr;
    ptr = (struct node *) malloc(sizeof(struct node));   // ① allocate
    ptr->data = value;                                   // ② store payload
    ptr->next = NULL;                                    // ③ last node -> NULL

    if ((front == NULL) && (rear == NULL)) {            // ④ empty queue?
        front = rear = ptr;                              //    both become the new node
    } else {
        rear->next = ptr;                                // ⑤ link after current rear
        rear = ptr;                                      //    move rear pointer forward
    }
    printf("Node is Inserted\n\n");                      // ⑥ user feedback
