## 5️⃣  Recommendations – Hardening the Code  

Below is a **refactored version skeleton** with comments highlighting security‑focused changes. You can copy‑paste the changes directly into the original source.

```c
/* --------------- Secure Queue Implementation --------------- */
#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>
#include <errno.h>

/* --- Node definition --------------------------------------------------- */
typedef struct node {
    int data;
    struct node *next;
} node_t;

/* --- Global queue pointers (encapsulate in a struct if multithreaded) -- */
static node_t *front = NULL;
static node_t *rear  = NULL;

/* --- Helper: reset queue to empty (clears both pointers) -------------- */
static void reset_queue(void) {
    front = rear = NULL;
}

/* --- Enqueue ------------------------------------------------------------- */
static bool enqueue(int value) {
    node_t *ptr = malloc(sizeof(*ptr));
    if (!ptr) {                         // ① check allocation
        fprintf(stderr, "ENOMEM: unable to allocate node\n");
        return false;
    }

    ptr->data = value;
    ptr->next = NULL;

    if (front == NULL) {                // queue empty => both pointers become ptr
        front = rear = ptr;
    } else {
        rear->next = ptr;               // safe: rear is non‑NULL when queue not empty
        rear = ptr;
    }
    puts("Node is Inserted");
    return true;
}

/* --- Dequeue ------------------------------------------------------------- */
static bool dequeue(int *out) {
    if (front == NULL) {                // empty queue
        fputs("Underflow\n", stderr);
        return false;
    }

    node_t *temp = front;
    *out = temp->data;
    front = front->next;
    free(temp);

    if (front == NULL)                  // queue became empty => clear rear too
        rear = NULL;                    // ◀️  fixes the invariant bug

    return true;
}

/* --- Display ------------------------------------------------------------- */
static void display(void) {
    if (front == NULL) {                // empty queue (rear is guaranteed NULL)
        puts("\nQueue is Empty");
        return;
    }

    puts("The queue is:");
    for (node_t *cur = front; cur != NULL; cur = cur->next)
        printf("%d -> ", cur->data);
    puts("NULL");
}

/* --- Clean‑up all remaining nodes (called on exit) ---------------------- */
static void free_queue(void) {
    while (front) {
        node_t *next = front->next;
        free(front);
        front = next;
    }
    rear = NULL;
}

/* --- Main menu loop ------------------------------------------------------ */
int main(void) {
    int choice = 0;                     // ← initialized
    int value;

    puts("\nImplementation of Queue using Linked List");

    while (true) {
        puts("\n1. Enqueue\n2. Dequeue\n3. Display\n4. Exit");
        if (scanf("%d", &choice) != 1) {   // ← validate input
            fprintf(stderr, "Invalid input. Please enter a number.\n");
            /* discard bad input */
            int c; while ((c = getchar()) != '\n' && c != EOF);
            continue;
        }

        switch (choice) {
        case 1:
            printf("Enter value to insert: ");
            if (scanf("%d", &value) != 1) {
                fprintf(stderr, "Bad value.\n");
                while ((c = getchar()) != '\n' && c != EOF);
                continue;
            }
            if (!enqueue(value)) {
                /* Allocation failed; decide whether to exit or continue */
                exit(EXIT_FAILURE);
            }
            break;

        case 2:
            if (dequeue(&value))
                printf("Deleted value = %d\n", value);
            break;

        case 3:
            display();
            break;

        case 4:
            puts("Exiting...");
            free_queue();               // clean up any remaining nodes
            return EXIT_SUCCESS;

        default:
            puts("Invalid choice!");
            break;
        }
    }
}
```

### Security‑oriented changes explained

| Change | Why it matters |
|--------|----------------|
| **`malloc` return check** (`if (!ptr)`) | Prevents NULL‑dereference → avoids immediate crash/DoS. |
| **Update `rear` to `NULL` when queue becomes empty** (`if (front == NULL) rear = NULL;`) | Restores the invariant, eliminating use‑after‑free. |
| **Return `bool` + output argument for `dequeue`** | Separates error signalling from valid data (`-1` no longer ambiguous). |
| **Initialize `choice` before the loop** | Removes undefined behaviour. |
| **Validate `scanf` return values** | Stops infinite loops on malformed input, prevents stale variable reuse. |
| **Discard leftover characters after a bad `scanf`** | Stops the “input stuck” problem. |
| **Dedicated `free_queue()` at exit** | Guarantees no memory leaks in long‑running contexts. |
| **Encapsulation (`static` global pointers)** | Reduces accidental external tampering; easier to add a mutex if you later make the queue multithreaded. |
| **Error messages go to `stderr`** | Keeps user‑visible output clean and assists debugging/monitoring. |
| **Explicit `exit(EXIT_FAILURE)` on allocation failure** | Fails fast instead of continuing in an undefined state. |

