# uniq_board_id.sh  –  генерирует «уникальный номер платы» для Orange Pi Zero LTS
# Требует: coreutils (cat, awk, grep, cut), ip, sha256sum

set -euo pipefail

# -------------------------------------------------------------------------
# Функция: собрать «сырой» набор уникальных полей
# -------------------------------------------------------------------------
collect_raw_data() {
