    # 1) Serial из /proc/cpuinfo (обычно присутствует)
    if [[ -r /proc/cpuinfo ]]; then
        local serial
        serial=$(awk -F': ' '/Serial/ {print $2}' /proc/cpuinfo | tr -d '[:space:]')
        [[ -n $serial ]] && data+="${serial}"
    fi

    # 2) serial-number из DT (может отсутствовать)
    if [[ -r /sys/firmware/devicetree/base/serial-number ]]; then
        local dtserial
        dtserial=$(tr -d '\0' </sys/firmware/devicetree/base/serial-number)
        [[ -n $dtserial ]] && data+="${dtserial}"
    fi

    # 3) MAC‑address первого сетевого интерфейса (eth0/wlan0)
    #    ip link выводит MAC в виде: link/ether aa:bb:cc:dd:ee:ff
    local mac
    mac=$(ip link show | awk '/link\/ether/ {print $2; exit}')
    [[ -n $mac ]] && data+="${mac}"

    # 4) Если ни одного из выше не удалось получить – используем
    #    случайный UUID (но он будет разный каждый запуск!)
    if [[ -z $data ]]; then
        data=$(cat /proc/sys/kernel/random/uuid)
    fi

    printf '%s' "$data"
}

