#define _POSIX_C_SOURCE 200809L   // для getline()
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <openssl/evp.h>          // SHA‑256

#define MAX_BUF 256

/* -----------------------------------------------------------------
 * Чтение строки из файла (без \n). Возвращает выделенную строку,
 * которую обязано освободить вызывающий код.
 * ----------------------------------------------------------------- */
static char *read_file_line(const char *path, const char *search_key)
{
    FILE *fp = fopen(path, "r");
    if (!fp) return NULL;

    char *line = NULL;
    size_t len = 0;
    char *result = NULL;

    while (getline(&line, &len, fp) != -1) {
        if (search_key) {
            if (strstr(line, search_key) == NULL) continue;
        }
        /* Убираем перевод строки */
        line[strcspn(line, "\r\n")] = '\0';
        result = strdup(line);
        break;
    }

    free(line);
    fclose(fp);
    return result;
}

/* -----------------------------------------------------------------
 * 1) Serial из /proc/cpuinfo
 * ----------------------------------------------------------------- */
static char *get_cpu_serial(void)
{
    char *line = read_file_line("/proc/cpuinfo", "Serial");
    if (!line) return NULL;

    /* Формат: "Serial\t\t: 0123456789abcdef" */
    char *p = strchr(line, ':');
    if (!p) { free(line); return NULL; }
    p++;                       // пропускаем ':'
    while (*p && isspace((unsigned char)*p)) p++;

    char *serial = strdup(p);
    free(line);
    return serial;
}

/* -----------------------------------------------------------------
 * 2) DT‑serial (если присутствует)
 * ----------------------------------------------------------------- */
static char *get_dt_serial(void)
{
    FILE *fp = fopen("/sys/firmware/devicetree/base/serial-number", "r");
    if (!fp) return NULL;

    char buf[MAX_BUF] = {0};
    size_t n = fread(buf, 1, sizeof(buf) - 1, fp);
    fclose(fp);

    if (n == 0) return NULL;
    /* В DT‑файлах могут быть NUL‑символы, отрежем их */
    buf[n] = '\0';
    return strdup(buf);
}

/* -----------------------------------------------------------------
 * 3) MAC‑address первого сетевого интерфейса (ip link)
 *    Мы читаем /sys/class/net/*/address – это проще и не требует
 *    запуска внешних команд.
 * ----------------------------------------------------------------- */
static char *get_first_mac(void)
{
    FILE *dp = fopen("/proc/net/dev", "r");
    if (!dp) return NULL;

    char line[256];
    while (fgets(line, sizeof(line), dp)) {
        /* Пропускаем заголовки */
        if (strchr(line, ':') == NULL) continue;

        /* Выделяем имя интерфейса */
        char iface[64];
        if (sscanf(line, " %63[^:]:", iface) != 1) continue;

        /* Пропускаем loopback */
        if (strcmp(iface, "lo") == 0) continue;

        /* Формируем путь к файлу MAC */
        char mac_path[128];
        snprintf(mac_path, sizeof(mac_path),
                 "/sys/class/net/%s/address", iface);

        char *mac = read_file_line(mac_path, NULL);
        if (mac) {
            fclose(dp);
            return mac;   // например, "aa:bb:cc:dd:ee:ff"
        }
    }
    fclose(dp);
    return NULL;
}

/* -----------------------------------------------------------------
 * 4) Если ни одного из выше не удалось – случайный UUID
 * ----------------------------------------------------------------- */
static char *get_random_uuid(void)
{
    FILE *fp = fopen("/proc/sys/kernel/random/uuid", "r");
    if (!fp) return NULL;

    char buf[64] = {0};
    if (fgets(buf, sizeof(buf), fp) == NULL) {
        fclose(fp);
        return NULL;
    }
    fclose(fp);
    buf[strcspn(buf, "\r\n")] = '\0';
    return strdup(buf);
}

/* -----------------------------------------------------------------
 * Вычисление SHA‑256 и вывод в виде 64‑символного hex‑стринга
 * ----------------------------------------------------------------- */
static void sha256_hex(const char *data, unsigned char out[32])
{
    EVP_MD_CTX *ctx = EVP_MD_CTX_new();
    EVP_DigestInit_ex(ctx, EVP_sha256(), NULL);
    EVP_DigestUpdate(ctx, data, strlen(data));
    EVP_DigestFinal_ex(ctx, out, NULL);
    EVP_MD_CTX_free(ctx);
}

/* -----------------------------------------------------------------
 * Главная функция
 * ----------------------------------------------------------------- */
int main(void)
{
    char *parts[4] = { NULL, NULL, NULL, NULL };
    size_t parts_cnt = 0;

    parts[parts_cnt++] = get_cpu_serial();
    parts[parts_cnt++] = get_dt_serial();
    parts[parts_cnt++] = get_first_mac();

    /* Если ничего не удалось собрать – берём случайный UUID */
    if (!parts[0] && !parts[1] && !parts[2]) {
        parts[parts_cnt++] = get_random_uuid();
    }

    /* Сконкатенировать все найденные кусочки (неважно, есть один
       или несколько – результат будет детерминированным) */
    size_t total_len = 0;
    for (size_t i = 0; i < parts_cnt; ++i) {
        if (parts[i]) total_len += strlen(parts[i]);
    }

    char *raw = malloc(total_len + 1);
    if (!raw) {
        perror("malloc");
        return 1;
    }
    raw[0] = '\0';
    for (size_t i = 0; i < parts_cnt; ++i) {
        if (parts[i]) strcat(raw, parts[i]);
    }

    unsigned char hash[32];
    sha256_hex(raw, hash);
    free(raw);

    /* Печать в HEX */
    printf("Board ID: ");
    for (int i = 0; i < 32; ++i) {
        printf("%02x", hash[i]);
    }
    printf("\n");

    /* Освобождаем память */
    for (size_t i = 0; i < parts_cnt; ++i) {
        free(parts[i]);
    }

    return 0;
}
