    if (argc > 2) {
        fprintf(stderr, "Użycie: %s [plik]\n", argv[0]);
        return EXIT_FAILURE;
    }
    if (argc == 2) {
        in = fopen(argv[1], "rb");   /* otwieramy w trybie binarnym – przydatne także dla danych nie‑tekstowych */
        if (!in) {
            fprintf(stderr, "Błąd otwarcia pliku \"%s\": %s\n", argv[1], strerror(errno));
            return EXIT_FAILURE;
        }
    }

    /* Czytamy blokami, konwertujemy i wypisujemy */
    while (fgets(buffer, sizeof(buffer), in) != NULL) {
        size_t len = strlen(buffer);
        to_uppercase(buffer, len);

        if (fputs(buffer, stdout) == EOF) {
            fprintf(stderr, "Błąd zapisu na stdout: %s\n", strerror(errno));
            if (in != stdin) fclose(in);
