/***********************************************************************
 *  Kruskal 最小生成树实现（适配题目要求的输入/输出格式）
 *  作者 : ChatGPT（安全研究员视角）
 *  说明 :
 *    - 输入：n e   (顶点数、边数)   // e 只用于兼容题目，实际不使用
 *    - 接下来 n 行，每行 n 个整数，表示带权有向图的邻接矩阵
 *      若两个顶点之间没有边，用 32767 表示“∞”。对角线为 0；
 *      题目中要求把“0” 当作 “∞” 处理（除对角线外）。
 *    - 输出：先打印 "Krusal:"，随后每行输出 MST 中的一条边：
 *            (i,j):w   (i、j 为顶点编号，w 为权值)
 *      采用 0‑based 编号，输出顺序即为 Kruskal 选取的顺序。
 ***********************************************************************/

#include <stdio.h>
#include <stdlib.h>

#define INF 32767

/*---------------------------------------------------------------*/
/*  图的结构体（邻接矩阵）                                         */
typedef struct {
    int n;          /* 顶点数 */
    int **edges;    /* n×n 的权值矩阵 */
} MGraph;

/*---------------------------------------------------------------*/
/*  并查集（Union‑Find）实现                                      */
typedef struct {
    int *parent;
    int *rank;
} UnionFind;

/* 初始化并查集 */
static UnionFind *uf_create(int n)
{
    UnionFind *uf = (UnionFind *)malloc(sizeof(UnionFind));
    if (!uf) exit(1);
    uf->parent = (int *)malloc(n * sizeof(int));
    uf->rank   = (int *)malloc(n * sizeof(int));
    if (!uf->parent || !uf->rank) exit(1);
    for (int i = 0; i < n; ++i) {
        uf->parent[i] = i;
        uf->rank[i]   = 0;
    }
    return uf;
}

/* 查找根（路径压缩） */
static int uf_find(UnionFind *uf, int x)
{
    if (uf->parent[x] != x)
        uf->parent[x] = uf_find(uf, uf->parent[x]);
    return uf->parent[x];
}

/* 合并两个集合，返回是否成功（即两集合原本不同） */
static int uf_union(UnionFind *uf, int x, int y)
{
    int rx = uf_find(uf, x);
    int ry = uf_find(uf, y);
    if (rx == ry) return 0;            /* 已在同一集合，加入会产生环 */
    /* 按秩合并 */
    if (uf->rank[rx] < uf->rank[ry]) {
        uf->parent[rx] = ry;
    } else if (uf->rank[rx] > uf->rank[ry]) {
        uf->parent[ry] = rx;
    } else {
        uf->parent[ry] = rx;
        uf->rank[rx]++;
    }
    return 1;
}

/* 释放并查集 */
static void uf_destroy(UnionFind *uf)
{
    free(uf->parent);
    free(uf->rank);
    free(uf);
}

/*---------------------------------------------------------------*/
/*  边的结构体（用于排序）                                        */
typedef struct {
    int u, v;   /* 顶点编号 */
    int w;      /* 权值 */
} Edge;

/* 比较函数：按权值升序 */
static int edge_cmp(const void *a, const void *b)
{
    const Edge *ea = (const Edge *)a;
    const Edge *eb = (const Edge *)b;
    return ea->w - eb->w;
}

/*---------------------------------------------------------------*/
/*  Kruskal 主过程                                                 */
static void Kruskal(const MGraph *g)
{
    int n = g->n;
    /* 1️⃣ 统计所有合法的无向边（只保留 i<j，避免重复） */
    int maxEdges = n * (n - 1) / 2;
    Edge *edges = (Edge *)malloc(maxEdges * sizeof(Edge));
    if (!edges) exit(1);
    int edgeCnt = 0;

    for (int i = 0; i < n; ++i) {
        for (int j = i + 1; j < n; ++j) {
            int w = g->edges[i][j];
            if (w != INF) {                      /* 有效边 */
                edges[edgeCnt].u = i;
                edges[edgeCnt].v = j;
                edges[edgeCnt].w = w;
                edgeCnt++;
            }
        }
    }

    /* 2️⃣ 按权值排序 */
    qsort(edges, edgeCnt, sizeof(Edge), edge_cmp);

    /* 3️⃣ 并查集 + 逐条挑选 */
    UnionFind *uf = uf_create(n);
    int selected = 0;                 /* 已加入 MST 的边数 */
    for (int i = 0; i < edgeCnt && selected < n - 1; ++i) {
        Edge e = edges[i];
        if (uf_union(uf, e.u, e.v)) {  /* 两端不在同一集合，加入 */
            printf("(%d,%d):%d\n", e.u, e.v, e.w);
            selected++;
        }
    }

    /* 释放资源 */
    uf_destroy(uf);
    free(edges);
}

/*---------------------------------------------------------------*/
/*  主函数：读取输入、构造图、调用 Kruskal                         */
int main(void)
{
    int n, e;
    if (scanf("%d %d", &n, &e) != 2) return 0;   /* 读取顶点数、边数（e 仅兼容） */

    /* 为图分配结构体本身 */
    MGraph *g = (MGraph *)malloc(sizeof(MGraph));
    if (!g) exit(1);
    g->n = n;

    /* 分配邻接矩阵 */
    g->edges = (int **)malloc(n * sizeof(int *));
    if (!g->edges) exit(1);
    for (int i = 0; i < n; ++i) {
        g->edges[i] = (int *)malloc(n * sizeof(int));
        if (!g->edges[i]) exit(1);
    }

    /* 读取矩阵 */
    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < n; ++j) {
            int val;
            scanf("%d", &val);
            /* 题目说明：0 表示“无边”，除对角线外需转为 INF */
            if (i != j && val == 0)
                g->edges[i][j] = INF;
            else
                g->edges[i][j] = val;
        }
    }

    printf("Krusal:\n");
    Kruskal(g);

    /* 释放图的内存 */
    for (int i = 0; i < n; ++i) free(g->edges[i]);
    free(g->edges);
    free(g);
    return 0;
}
```

### 说明

1. **输入**  
   - 第一行 `n e`，`e` 在本实现里不参与计算，只是为了兼容题目描述。  
   - 接下来 `n` 行每行 `n` 个整数，表示邻接矩阵。若位置 `i≠j` 为 `0`，我们把它视为 **不存在的边**，用 `32767`（`INF`）代替。对角线本来就是 `0`（自环），直接保留 `0` 即可（不会被加入 MST）。

2. **输出**  
   - 程序首先打印 `Krusal:`（包含冒号和换行），随后每行打印一条被选入最小生成树的边，格式恰好是 `(i,j):w`，其中 `i`、`j` 为 **0‑based** 顶点编号，`w` 为权值。  
   - 边的顺序就是 Kruskal 在排序后依次尝试加入且成功的顺序，这和样例输出保持一致。

3. **复杂度**  
   - 收集所有边的时间 `O(n²)`，排序 `O(E log E)`（`E ≤ n·(n‑1)/2`），并查集的几乎常数时间操作，总体满足常规的 Kruskal 复杂度。

4. **安全性（安全研究员视角）**  
   - 所有 `malloc` 均检查返回值，防止内存分配失败导致未定义行为。  
   - 输入只使用 `scanf` 读取整数，不进行额外的字符串处理，避免缓冲区溢出。  
   - 使用 `int` 保存权值，题目给出的 “∞” 为 `32767`，不会产生溢出。  
   - 程序不依赖全局或未初始化的变量，行为可预测。

