/* add_two_numbers.c
 *
 * Reads two integers from stdin, adds them and prints the result.
 * All input is validated to avoid undefined behaviour.
 */

#include <stdio.h>
#include <stdlib.h>
#include <errno.h>
#include <limits.h>

static int read_int(const char *prompt, long *out)
{
    char line[64];
    char *endptr;
    long val;

    printf("%s", prompt);
    if (fgets(line, sizeof(line), stdin) == NULL) {
        fprintf(stderr, "Error reading input.\n");
        return -1;
    }

    errno = 0;
    val = strtol(line, &endptr, 10);
    if (errno != 0 || endptr == line || *endptr != '\n') {
        fprintf(stderr, "Invalid integer.\n");
        return -1;
    }
    if (val < INT_MIN || val > INT_MAX) {
        fprintf(stderr, "Integer out of range.\n");
        return -1;
    }

    *out = val;
    return 0;
}

int main(void)
{
    long a, b;

    if (read_int("Enter first integer: ", &a) ||
        read_int("Enter second integer: ", &b)) {
        return EXIT_FAILURE;
    }

    long sum = a + b;
    printf("Sum = %ld\n", sum);
    return EXIT_SUCCESS;
}
