#include <stdio.h>
#include <stdlib.h>
#include <errno.h>
#include <limits.h>

static int read_double(const char *prompt, double *out)
{
    char line[128];
    char *endptr;
    double val;

    printf("%s", prompt);
    if (fgets(line, sizeof(line), stdin) == NULL) {
        fprintf(stderr, "Error reading input.\n");
        return -1;
    }

    errno = 0;
    val = strtod(line, &endptr);
    if (errno != 0 || endptr == line || (*endptr != '\n' && *endptr != '\0')) {
        fprintf(stderr, "Invalid number.\n");
        return -1;
    }

    *out = val;
    return 0;
}

static int read_operator(char *op)
{
    char line[16];
    printf("Enter operator (+ - * /): ");
    if (fgets(line, sizeof(line), stdin) == NULL) {
        fprintf(stderr, "Error reading input.\n");
        return -1;
    }

    /* Accept only the first non‑whitespace character */
    for (size_t i = 0; line[i] != '\0'; ++i) {
        if (line[i] != ' ' && line[i] != '\t' && line[i] != '\n') {
            *op = line[i];
            return (line[i] == '+' || line[i] == '-' ||
                    line[i] == '*' || line[i] == '/')
                       ? 0 : -1;
        }
    }
    return -1;
}

int main(void)
{
    double a, b, result;
    char op;

    if (read_double("Enter first number: ", &a) ||
        read_double("Enter second number: ", &b) ||
        read_operator(&op)) {
        fprintf(stderr, "Invalid input – aborting.\n");
        return EXIT_FAILURE;
    }

    switch (op) {
        case '+': result = a + b; break;
        case '-': result = a - b; break;
        case '*': result = a * b; break;
        case '/':
            if (b == 0.0) {
                fprintf(stderr, "Error: Division by zero.\n");
                return EXIT_FAILURE;
            }
            result = a / b;
            break;
        default:
            fprintf(stderr, "Unsupported operator.\n");
            return EXIT_FAILURE;
    }

    printf("Result: %.6g\n", result);
    return EXIT_SUCCESS;
}
```

**Security considerations**

* **Numeric parsing** – `strtod` with error checking prevents injection of non‑numeric text.  
* **Operator whitelist** – only the four permitted symbols are accepted; any other character yields an error.  
* **Division‑by‑zero check** – avoids undefined behaviour and possible program crash.  



