/* factorial_u64.c
 * Compute n! using 64‑bit unsigned integers.
 * Works correctly for 0 ≤ n ≤ 20.
 */

#include <stdio.h>
#include <stdlib.h>
#include <errno.h>

int main(void) {
    unsigned long long n, i, result = 1ULL;
    char line[64];

    printf("Enter n (0‑20): ");
    if (!fgets(line, sizeof(line), stdin)) {
        perror("fgets");
        return EXIT_FAILURE;
    }

    errno = 0;
    n = strtoull(line, NULL, 10);
    if (errno != 0) {
        perror("strtoull");
        return EXIT_FAILURE;
    }
    if (n > 20) {
        fprintf(stderr, "Error: %llu is too large for 64‑bit factorial.\n", n);
        return EXIT_FAILURE;
    }

    for (i = 2; i <= n; ++i)
        result *= i;

    printf("%llu! = %llu\n", n, result);
    return EXIT_SUCCESS;
}
