/* factorial_gmp.c
 * Compute n! using GNU MP (gmp) arbitrary‑precision integers.
 * Works for any n that fits in memory.
 */

#include <stdio.h>
#include <stdlib.h>
#include <gmp.h>

int main(void) {
    mpz_t n, i, result;
    char line[256];

    mpz_init_set_ui(n, 0);      /* n = 0 */
    mpz_init_set_ui(i, 2);      /* loop counter i = 2 */
    mpz_init_set_ui(result, 1);/* result = 1 */

    printf("Enter n (non‑negative integer): ");
    if (!fgets(line, sizeof(line), stdin)) {
        perror("fgets");
        goto clean;
    }

    if (mpz_set_str(n, line, 10) != 0) {
        fprintf(stderr, "Invalid integer input.\n");
        goto clean;
    }
    if (mpz_sgn(n) < 0) {
        fprintf(stderr, "n must be non‑negative.\n");
        goto clean;
    }

    /* result = 1; for i = 2 .. n: result *= i; */
    for (; mpz_cmp(i, n) <= 0; mpz_add_ui(i, i, 1)) {
        mpz_mul(result, result, i);
    }

    gmp_printf("%Zd! = %Zd\n", n, result);

clean:
    mpz_clear(n);
    mpz_clear(i);
    mpz_clear(result);
    return 0;
}
```

