/*
 * Simple DMA‐engine memory‑to‑memory test for Linux 4.19
 *
 *  Author:  <your name>
 *  Contact: <your e‑mail>
 *
 *  Build:
 *      make -C /lib/modules/$(uname -r)/build M=$(pwd) modules
 *
 *  Load:
 *      sudo insmod dma_test.ko
 *      echo 1 > /sys/kernel/dma_test/run    # start test
 *      cat /sys/kernel/dma_test/status      # 0=PASS, 1=FAIL, 2=ERROR
 *
 *  Unload:
 *      sudo rmmod dma_test
 *
 *  NOTE: This module requires CONFIG_DMADEVICES=y and a DMA engine
 *        driver that supports MEM‑TO‑MEM (e.g., "generic" or a platform DMA).
 */

#include <linux/module.h>
#include <linux/init.h>
#include <linux/dmaengine.h>
#include <linux/dma-mapping.h>
#include <linux/platform_device.h>
#include <linux/of_dma.h>
#include <linux/of.h>
#include <linux/slab.h>
#include <linux/kobject.h>
#include <linux/sysfs.h>
#include <linux/completion.h>
#include <linux/err.h>
#include <linux/printk.h>

#define DMA_BUF_SIZE   (64 * 1024)   /* 64 KiB test buffer               */
#define PATTERN_BYTE   0xAA          /* Fill source buffer with 0xAA... */

/* -------------------------------------------------------------------------
 * Global state
 * ------------------------------------------------------------------------- */
static struct dma_chan *chan;
static void *src_buf;               /* CPU‑visible source buffer          */
static void *dst_buf;               /* CPU‑visible destination buffer     */
static dma_addr_t src_dma;          /* Bus address of src_buf              */
static dma_addr_t dst_dma;          /* Bus address of dst_buf              */
static struct completion dma_done;
static int test_result = -1;        /* -1 = not run, 0 = PASS, 1 = FAIL   */

/* -------------------------------------------------------------------------
 * Helper: simple pattern fill / verify
 * ------------------------------------------------------------------------- */
static void fill_pattern(void *buf, size_t size)
{
        memset(buf, PATTERN_BYTE, size);
}

static bool verify_pattern(void *buf, size_t size)
{
        size_t i;
        u8 *p = buf;
        for (i = 0; i < size; i++) {
                if (p[i] != PATTERN_BYTE)
                        return false;
        }
        return true;
}

/* -------------------------------------------------------------------------
 * DMA callback
 * ------------------------------------------------------------------------- */
static void dma_test_cb(void *completion)
{
        complete(completion);
}

/* -------------------------------------------------------------------------
 * Run the actual DMA test
 * ------------------------------------------------------------------------- */
static int run_dma_test(void)
{
        struct dma_device *dma_dev;
        struct dma_async_tx_descriptor *tx;
        dma_cookie_t cookie;
        enum dma_status status;
        int ret = 0;

        if (!chan) {
                pr_err("dma_test: No DMA channel available\n");
                return -ENODEV;
        }

        dma_dev = chan->device;
        pr_info("dma_test: Using DMA device %s\n", dma_dev->dev->of_node->full_name);

        /* Allocate coherent buffers (CPU + device view) */
        src_buf = dma_alloc_coherent(dma_dev->dev, DMA_BUF_SIZE, &src_dma, GFP_KERNEL);
        if (!src_buf) {
                pr_err("dma_test: src buffer allocation failed\n");
                return -ENOMEM;
        }
        dst_buf = dma_alloc_coherent(dma_dev->dev, DMA_BUF_SIZE, &dst_dma, GFP_KERNEL);
        if (!dst_buf) {
                pr_err("dma_test: dst buffer allocation failed\n");
                ret = -ENOMEM;
                goto free_src;
        }

        /* Initialise source, zero destination */
        fill_pattern(src_buf, DMA_BUF_SIZE);
        memset(dst_buf, 0x00, DMA_BUF_SIZE);

        /* Prepare a MEM‑TO‑MEM transaction */
        tx = dmaengine_prep_dma_memcpy(chan,
                                      dst_dma,    /* dest */
                                      src_dma,    /* src */
                                      DMA_BUF_SIZE,
                                      DMA_PREP_INTERRUPT | DMA_CTRL_ACK);
        if (!tx) {
                pr_err("dma_test: prep_dma_memcpy() failed\n");
                ret = -EIO;
                goto free_bufs;
