        if (verify_pattern(dst_buf, DMA_BUF_SIZE))
                test_result = 0;   /* PASS */
        else
                test_result = 1;   /* FAIL */

        pr_info("dma_test: %s (src=%pad dst=%pad)\n",
                test_result ? "FAIL" : "PASS",
                &src_dma, &dst_dma);

free_bufs:
        dma_free_coherent(dma_dev->dev, DMA_BUF_SIZE, dst_buf, dst_dma);
        dma_free_coherent(dma_dev->dev, DMA_BUF_SIZE, src_buf, src_dma);
free_src:
        src_buf = NULL;
        dst_buf = NULL;
        return ret;
