 * Sysfs interface (expose "run" and "status")
 * ------------------------------------------------------------------------- */
static ssize_t run_store(struct kobject *kobj,
                         struct kobj_attribute *attr,
                         const char *buf, size_t count)
{
        unsigned long val;
        int err;

        err = kstrtoul(buf, 0, &val);
        if (err)
