 *  - reçoit les messages sur le même port
 *  - si le message reçu == argument, stocke (IP, port) dans un tableau partagé
 *  - le père affiche le tableau toutes les 30 secondes
 *
 *  Compile :  gcc -Wall -O2 -o udp_broadcast_shared udp_broadcast_shared.c -lrt
 * ------------------------------------------------------------- */

#define _POSIX_C_SOURCE 200809L   /* for pselect, clock_gettime, etc. */
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <errno.h>
#include <signal.h>

#include <sys/types.h>
#include <sys/socket.h>
#include <sys/mman.h>
#include <sys/stat.h>        /* For mode constants */
#include <fcntl.h>           /* For O_* constants */
#include <netinet/in.h>
#include <arpa/inet.h>
#include <time.h>

/* ---------- paramètres ---------- */
#define PORT            2346
#define BROADCAST_IP    "255.255.255.255"
#define MAX_TB_ENTRIES  256          /* taille maximale du tableau partagé   */
#define SHM_NAME        "/udp_tb_shm"/* nom du segment de mémoire partagée    */
#define DISPLAY_PERIOD  30          /* secondes entre deux affichages       */

/* ---------- structure stockant une entrée du tableau ---------- */
typedef struct {
    struct in_addr ip;   /* adresse IPv4 */
    in_port_t      port; /* port réseau (big‑endian) */
    int            valid;/* 0 = libre, 1 = occupe */
} tb_entry_t;

/* ---------- segment partagé ---------- */
typedef struct {
    tb_entry_t entries[MAX_TB_ENTRIES];
} shared_tb_t;

/* -------------------------------------------------------------
 * Helper : affichage du tableau partagé (appelé par le père)
 * ------------------------------------------------------------- */
static void display_tb(const shared_tb_t *tb)
{
    printf("\n--- Table des expéditeurs %ld ---\n", time(NULL));
    int found = 0;
    for (size_t i = 0; i < MAX_TB_ENTRIES; ++i) {
        if (tb->entries[i].valid) {
            char ip_str[INET_ADDRSTRLEN];
            inet_ntop(AF_INET, &(tb->entries[i].ip), ip_str, sizeof(ip_str));
            printf("[%zu] %s:%u\n", i, ip_str,
                   ntohs(tb->entries[i].port));
            ++found;
        }
    }
    if (!found)
        puts("(vide)");
    puts("-------------------------------\n");
}

/* -------------------------------------------------------------
 * Insert a (ip,port) pair in the shared table, avoiding duplicates
 * ------------------------------------------------------------- */
static void insert_entry(shared_tb_t *tb, struct in_addr ip, in_port_t port)
{
    /* évite les doublons */
    for (size_t i = 0; i < MAX_TB_ENTRIES; ++i) {
        if (tb->entries[i].valid &&
            tb->entries[i].ip.s_addr == ip.s_addr &&
            tb->entries[i].port == port)
            return;                     /* déjà présent */
    }

    /* cherche la première case libre */
    for (size_t i = 0; i < MAX_TB_ENTRIES; ++i) {
        if (!tb->entries[i].valid) {
            tb->entries[i].ip   = ip;
            tb->entries[i].port = port;
            tb->entries[i].valid = 1;
            return;
        }
    }
    /* tableau plein → on ignore la nouvelle entrée */
}

/* -------------------------------------------------------------
 * Création et map d'un segment partagé
 * ------------------------------------------------------------- */
static shared_tb_t *create_shared_table(void)
{
    int fd = shm_open(SHM_NAME, O_CREAT | O_RDWR, 0600);
    if (fd == -1) {
        perror("shm_open");
        exit(EXIT_FAILURE);
    }

    size_t sz = sizeof(shared_tb_t);
    if (ftruncate(fd, sz) == -1) {
        perror("ftruncate");
        exit(EXIT_FAILURE);
    }

    void *addr = mmap(NULL, sz, PROT_READ | PROT_WRITE,
                      MAP_SHARED, fd, 0);
    if (addr == MAP_FAILED) {
        perror("mmap");
        exit(EXIT_FAILURE);
    }
    close(fd);               /* fd non nécessaire après mmap */

    /* Initialise à zéro (valeur « vide ») */
    memset(addr, 0, sz);
    return (shared_tb_t *)addr;
}

/* -------------------------------------------------------------
 * Nettoyage du segment partagé (appelé à la fin du père)
 * ------------------------------------------------------------- */
static void destroy_shared_table(void)
{
    shm_unlink(SHM_NAME);
}

/* -------------------------------------------------------------
 * Fonction d’envoi broadcast (exécutée par le père)
 * ------------------------------------------------------------- */
static void sender_process(const char *msg, shared_tb_t *tb)
{
    (void)tb;      /* le père n’utilise pas le tableau pour l’envoi */

    /* création du socket UDP */
    int s = socket(AF_INET, SOCK_DGRAM, 0);
    if (s == -1) {
        perror("socket (sender)");
        exit(EXIT_FAILURE);
    }

    /* autoriser les broadcasts */
    int opt = 1;
    if (setsockopt(s, SOL_SOCKET, SO_BROADCAST, &opt, sizeof(opt)) == -1) {
        perror("setsockopt SO_BROADCAST");
        close(s);
        exit(EXIT_FAILURE);
    }

    struct sockaddr_in dst;
    memset(&dst, 0, sizeof(dst));
    dst.sin_family = AF_INET;
    dst.sin_port   = htons(PORT);
    if (inet_pton(AF_INET, BROADCAST_IP, &dst.sin_addr) != 1) {
        fprintf(stderr, "inet_pton error for broadcast address\n");
        close(s);
        exit(EXIT_FAILURE);
    }

    /* Boucle d’envoi */
    unsigned int sec_counter = 0;
    while (1) {
        ssize_t n = sendto(s, msg, strlen(msg), 0,
                           (struct sockaddr *)&dst, sizeof(dst));
        if (n == -1) {
            perror("sendto");
            /* On ne quitte pas – on continue les envois ultérieurs */
        }

        ++sec_counter;
        if (sec_counter % DISPLAY_PERIOD == 0) {
            display_tb(tb);
        }

        sleep(1);
    }

    /* unreachable */
    close(s);
}

/* -------------------------------------------------------------
 * Fonction de réception (exécutée par le fils)
 * ------------------------------------------------------------- */
static void receiver_process(const char *msg, shared_tb_t *tb)
{
    /* création du socket UDP */
    int s = socket(AF_INET, SOCK_DGRAM, 0);
    if (s == -1) {
        perror("socket (receiver)");
        exit(EXIT_FAILURE);
    }

    /* bind sur toutes les interfaces, port 2346 */
    struct sockaddr_in local;
    memset(&local, 0, sizeof(local));
    local.sin_family = AF_INET;
    local.sin_addr.s_addr = htonl(INADDR_ANY);
    local.sin_port = htons(PORT);
    if (bind(s, (struct sockaddr *)&local, sizeof(local)) == -1) {
        perror("bind");
        close(s);
        exit(EXIT_FAILURE);
    }

    char buf[1500];
    while (1) {
        struct sockaddr_in src;
        socklen_t srclen = sizeof(src);
        ssize_t n = recvfrom(s, buf, sizeof(buf) - 1, 0,
                             (struct sockaddr *)&src, &srclen);
        if (n == -1) {
            perror("recvfrom");
            continue;               /* on ne quitte pas, on continue d’écouter */
        }

        buf[n] = '\0';               /* terminaison pour les fonctions string */

        /* comparaison stricte (exacte, case‑sensible) */
        if (strcmp(buf, msg) == 0) {
            insert_entry(tb, src.sin_addr, src.sin_port);
        }
    }

    /* unreachable */
    close(s);
}

/* -------------------------------------------------------------
 * Main
 * ------------------------------------------------------------- */
int main(int argc, char *argv[])
{
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <message>\n", argv[0]);
        exit(EXIT_FAILURE);
    }

    const char *msg = argv[1];
    if (strlen(msg) == 0) {
        fprintf(stderr, "Le message ne doit pas être vide.\n");
        exit(EXIT_FAILURE);
    }

    /* créer le segment partagé */
    shared_tb_t *tb = create_shared_table();

    pid_t pid = fork();
    if (pid == -1) {
        perror("fork");
        destroy_shared_table();
        exit(EXIT_FAILURE);
    }

    if (pid == 0) {
        /* ---- Fils : réception ---- */
        receiver_process(msg, tb);
        /* never returns */
    } else {
        /* ---- Père : envoi + affichage ---- */
        sender_process(msg, tb);
        /* never returns (ctrl‑C interrompt) */
    }

    /* Cleanup – normalement jamais atteint */
    destroy_shared_table();
    return 0;
}
```

