#include <Windows.h>
#include <d3d11.h>
#include <dxgi.h>
#include <dxgi1_2.h>
#include <cstdint>
#include <cstdio>

// ----- MinHook -----
#include "MinHook.h"

// ----- ImGui -----
#include "imgui.h"
#include "backends/imgui_impl_dx11.h"
#include "backends/imgui_impl_win32.h"

// ---------------------------------------------------------------
// Global state (kept simple for the demo)
// ---------------------------------------------------------------
static IDXGISwapChain*          g_pSwapChain   = nullptr;
static ID3D11Device*            g_pDevice      = nullptr;
static ID3D11DeviceContext*     g_pContext     = nullptr;
static ID3D11RenderTargetView*  g_pRTV         = nullptr;

static bool                     g_ImGuiInitialized = false;
static bool                     g_ShowMenu = true;       // toggled with INSERT
static bool                     g_InitializedOnce = false;

// Original function pointers
using PresentFn  = HRESULT (__stdcall*)(IDXGISwapChain* pSwapChain, UINT SyncInterval, UINT Flags);
using ResizeBuffersFn = HRESULT (__stdcall*)(IDXGISwapChain* pSwapChain,
                                            UINT BufferCount,
                                            UINT Width,
                                            UINT Height,
                                            DXGI_FORMAT NewFormat,
                                            UINT SwapChainFlags);

static PresentFn       oPresent       = nullptr;
static ResizeBuffersFn oResizeBuffers = nullptr;

// ---------------------------------------------------------------
// Forward declarations
// ---------------------------------------------------------------
LRESULT CALLBACK WndProc(HWND hWnd, UINT msg, WPARAM wParam, LPARAM lParam);
void InitImGui(IDXGISwapChain* pSwapChain);
void CleanupImGui();
void RenderImGui();

// ---------------------------------------------------------------
// Helper: create a temporary dummy swap chain to grab the vtable
// ---------------------------------------------------------------
static void* GetVTableFunction(void* pInstance, size_t index)
{
    void** vtable = *reinterpret_cast<void***>(pInstance);
    return vtable[index];
}

// ---------------------------------------------------------------
// Our hooked Present
// ---------------------------------------------------------------
HRESULT __stdcall hkPresent(IDXGISwapChain* pSwapChain, UINT SyncInterval, UINT Flags)
{
    if (!g_ImGuiInitialized) {
        // First time we hit Present – initialise everything.
        InitImGui(pSwapChain);
        g_ImGuiInitialized = true;
    }

    // -----------------------------------------------------------------
    // Start a new ImGui frame (handles Win32 messages internally)
    // -----------------------------------------------------------------
    ImGui_ImplDX11_NewFrame();
    ImGui_ImplWin32_NewFrame();
    ImGui::NewFrame();

    // -----------------------------------------------------------------
    // Example menu – press INSERT to hide/show
    // -----------------------------------------------------------------
    if (GetAsyncKeyState(VK_INSERT) & 1)         // toggle on key press
        g_ShowMenu = !g_ShowMenu;

    if (g_ShowMenu) {
        ImGui::Begin("DX11 Hook Demo", &g_ShowMenu, ImGuiWindowFlags_AlwaysAutoResize);
        ImGui::Text("Hello from ImGui!");
        ImGui::Separator();

        // ---- demo controls -------------------------------------------------
        static float fValue = 0.5f;
        ImGui::SliderFloat("Some value", &fValue, 0.0f, 1.0f);

        static bool bCheck = false;
        ImGui::Checkbox("Check me", &bCheck);

        static int iCombo = 0;
        const char* items[] = {"One", "Two", "Three"};
        ImGui::Combo("Combo", &iCombo, items, IM_ARRAYSIZE(items));

        ImGui::End();
    }

    // -----------------------------------------------------------------
    // Rendering
    // -----------------------------------------------------------------
    ImGui::Render();
    g_pContext->OMSetRenderTargets(1, &g_pRTV, nullptr);
    ImGui_ImplDX11_RenderDrawData(ImGui::GetDrawData());

    // Finally call the original Present
    return oPresent(pSwapChain, SyncInterval, Flags);
}

// ---------------------------------------------------------------
// Hook for ResizeBuffers – we need to rebuild the RTV when the swap chain changes
// ---------------------------------------------------------------
HRESULT __stdcall hkResizeBuffers(IDXGISwapChain* pSwapChain,
                                 UINT BufferCount,
                                 UINT Width,
                                 UINT Height,
                                 DXGI_FORMAT NewFormat,
                                 UINT SwapChainFlags)
{
    // Release the old RTV before the resize
    if (g_pRTV) { g_pRTV->Release(); g_pRTV = nullptr; }

    // Call original ResizeBuffers
    HRESULT hr = oResizeBuffers(pSwapChain, BufferCount, Width, Height, NewFormat, SwapChainFlags);
    if (FAILED(hr)) return hr;

    // Re‑create RTV for the new back‑buffer
    ID3D11Texture2D* pBackBuffer = nullptr;
    pSwapChain->GetBuffer(0, __uuidof(ID3D11Texture2D), (void**)&pBackBuffer);
    if (pBackBuffer) {
        g_pDevice->CreateRenderTargetView(pBackBuffer, nullptr, &g_pRTV);
        pBackBuffer->Release();
    }

    // Let ImGui know about the new render target size
    ImGuiIO& io = ImGui::GetIO();
    io.DisplaySize = ImVec2((float)Width, (float)Height);

    return hr;
}

// ---------------------------------------------------------------
// Initialise ImGui once we have a valid SwapChain/Device/Context
// ---------------------------------------------------------------
void InitImGui(IDXGISwapChain* pSwapChain)
{
    // -----------------------------------------------------------------
    // Grab device, context and back‑buffer RTV
    // -----------------------------------------------------------------
    pSwapChain->GetDevice(__uuidof(ID3D11Device), (void**)&g_pDevice);
    g_pDevice->GetImmediateContext(&g_pContext);
    g_pSwapChain = pSwapChain;

    ID3D11Texture2D* pBackBuffer = nullptr;
    pSwapChain->GetBuffer(0, __uuidof(ID3D11Texture2D), (void**)&pBackBuffer);
    g_pDevice->CreateRenderTargetView(pBackBuffer, nullptr, &g_pRTV);
    pBackBuffer->Release();

    // -----------------------------------------------------------------
    // ImGui context creation
    // -----------------------------------------------------------------
    IMGUI_CHECKVERSION();
    ImGui::CreateContext();
    ImGuiIO& io = ImGui::GetIO();
    io.ConfigFlags |= ImGuiConfigFlags_NavEnableKeyboard; // optional

    // -----------------------------------------------------------------
    // Win32 + DX11 backends
    // -----------------------------------------------------------------
    // Find the HWND associated with the swap chain. Usually the swap chain is created
    // for the game window, so we can query it using IDXGISwapChain::GetDesc.
    DXGI_SWAP_CHAIN_DESC desc;
    pSwapChain->GetDesc(&desc);
    HWND hWnd = desc.OutputWindow;

    ImGui_ImplWin32_Init(hWnd);
    ImGui_ImplDX11_Init(g_pDevice, g_pContext);

    // Set a nice style (optional)
    ImGui::StyleColorsDark();
}

// ---------------------------------------------------------------
// Cleanup ImGui & COM objects
// ---------------------------------------------------------------
void CleanupImGui()
{
    ImGui_ImplDX11_Shutdown();
    ImGui_ImplWin32_Shutdown();
    ImGui::DestroyContext();

    if (g_pRTV) { g_pRTV->Release(); g_pRTV = nullptr; }
    if (g_pContext) { g_pContext->Release(); g_pContext = nullptr; }
    if (g_pDevice) { g_pDevice->Release(); g_pDevice = nullptr; }
    // Do NOT release g_pSwapChain – the host application owns it.
}

// ---------------------------------------------------------------
// Helper: simple Win32 message pump for ImGui (required for mouse/keyboard)
// ---------------------------------------------------------------
LRESULT CALLBACK WndProc(HWND hWnd, UINT msg, WPARAM wParam, LPARAM lParam)
{
    if (g_ImGuiInitialized) {
        ImGui_ImplWin32_WndProcHandler(hWnd, msg, wParam, lParam);
        // Let ImGui consume the message if it wants to
        // (you can also return true/false based on ImGui logic)
    }
    return DefWindowProcW(hWnd, msg, wParam, lParam);
}

// ---------------------------------------------------------------
// DllMain – entry point where we set everything up
// ---------------------------------------------------------------
BOOL APIENTRY DllMain(HMODULE hModule,
                      DWORD  ul_reason_for_call,
                      LPVOID lpReserved)
{
    switch (ul_reason_for_call)
    {
    case DLL_PROCESS_ATTACH:
    {
        DisableThreadLibraryCalls(hModule); // optimisation

        // -----------------------------------------------------------------
        // 1️⃣ Initialise MinHook
        // -----------------------------------------------------------------
        if (MH_Initialize() != MH_OK) {
            MessageBoxW(nullptr, L"MinHook initialise failed", L"Error", MB_ICONERROR);
            return FALSE;
        }

        // -----------------------------------------------------------------
        // 2️⃣ Create a *temporary* DXGI swap chain so we can read the vtable.
        //    This works even if the target process hasn't created its own swap chain yet.
        // -----------------------------------------------------------------
        // NOTE: we deliberately use a *dummy* device+swapchain created in the context
        //       of the current process (our DLL). The function pointers we obtain are
        //       identical for all processes because they are taken from the COM vtable.
        // -----------------------------------------------------------------
        DXGI_SWAP_CHAIN_DESC dummyDesc = {};
        dummyDesc.BufferCount = 2;
        dummyDesc.BufferDesc.Format = DXGI_FORMAT_R8G8B8A8_UNORM;
        dummyDesc.BufferDesc.Width = 100;
        dummyDesc.BufferDesc.Height = 100;
        dummyDesc.BufferUsage = DXGI_USAGE_RENDER_TARGET_OUTPUT;
        dummyDesc.OutputWindow = GetForegroundWindow(); // any valid HWND
        dummyDesc.SampleDesc.Count = 1;
        dummyDesc.Windowed = TRUE;
        dummyDesc.SwapEffect = DXGI_SWAP_EFFECT_DISCARD;

        IDXGISwapChain* pDummySwap = nullptr;
        ID3D11Device* pDummyDevice = nullptr;
        ID3D11DeviceContext* pDummyCtx = nullptr;

        // Create device+swapchain using the default adapter
        if (FAILED(D3D11CreateDeviceAndSwapChain(
                nullptr,
                D3D_DRIVER_TYPE_HARDWARE,
                nullptr,
                0,
                nullptr,
                0,
                D3D11_SDK_VERSION,
                &dummyDesc,
                &pDummySwap,
                &pDummyDevice,
                nullptr,
                &pDummyCtx))) {
            MessageBoxW(nullptr, L"Failed to create dummy device/swapchain", L"Error", MB_ICONERROR);
            MH_Uninitialize();
            return FALSE;
        }

        // -----------------------------------------------------------------
        // 3️⃣ Resolve the original function addresses.
        //    Present is at index 8 in IDXGISwapChain vtable, ResizeBuffers at 13.
        // -----------------------------------------------------------------
        void* pPresentAddr = GetVTableFunction(pDummySwap, 8);
        void* pResizeBuffersAddr = GetVTableFunction(pDummySwap, 13);

        // Release dummy objects – we only needed them for the pointers.
        pDummySwap->Release();
        pDummyDevice->Release();
        pDummyCtx->Release();

        // -----------------------------------------------------------------
        // 4️⃣ Create the hooks.
        // -----------------------------------------------------------------
        if (MH_CreateHook(pPresentAddr, &hkPresent, reinterpret_cast<LPVOID*>(&oPresent)) != MH_OK ||
            MH_CreateHook(pResizeBuffersAddr, &hkResizeBuffers, reinterpret_cast<LPVOID*>(&oResizeBuffers)) != MH_OK) {
            MessageBoxW(nullptr, L"Failed to create hooks", L"Error", MB_ICONERROR);
            MH_Uninitialize();
            return FALSE;
        }

        // Enable all hooks (you could enable individually if you like)
        if (MH_EnableHook(MH_ALL_HOOKS) != MH_OK) {
            MessageBoxW(nullptr, L"Failed to enable hooks", L"Error", MB_ICONERROR);
            MH_Uninitialize();
            return FALSE;
        }

        // Optional: you can output the addresses to a log for debugging.
        wchar_t buf[512];
        wsprintfW(buf, L"Hook installed:\nPresent = %p\nResizeBuffers = %p", pPresentAddr, pResizeBuffersAddr);
        OutputDebugStringW(buf);
    }
    break;

    case DLL_PROCESS_DETACH:
    {
        // -----------------------------------------------------------------
        // 5️⃣ Cleanup – disable hooks, shutdown ImGui, free MinHook.
        // -----------------------------------------------------------------
        if (g_ImGuiInitialized)
            CleanupImGui();

        MH_DisableHook(MH_ALL_HOOKS);
        MH_Uninitialize();

        // (If you have any other allocated resources, free them here.)
    }
    break;
    }
    return TRUE;
}
