// Injector.cpp  (compile as a normal 64‑bit EXE)
#include <windows.h>
#include <tlhelp32.h>
#include <iostream>

DWORD FindProcessId(const wchar_t* procName)
{
    DWORD pid = 0;
    PROCESSENTRY32W entry = { sizeof(entry) };
    HANDLE snap = CreateToolhelp32Snapshot(TH32CS_SNAPPROCESS, 0);
    if (snap == INVALID_HANDLE_VALUE) return 0;
    if (Process32FirstW(snap, &entry)) {
        do {
            if (!_wcsicmp(entry.szExeFile, procName))
                pid = entry.th32ProcessID;
        } while (!pid && Process32NextW(snap, &entry));
    }
    CloseHandle(snap);
    return pid;
}

int wmain(int argc, wchar_t* argv[])
{
    if (argc != 3) {
        std::wcout << L"Usage: Injector.exe <process_name.exe> <full_path_to_dll>\n";
        return 1;
    }

    DWORD pid = FindProcessId(argv[1]);
    if (!pid) {
        std::wcout << L"Process not found.\n";
        return 1;
    }

    HANDLE hProc = OpenProcess(PROCESS_ALL_ACCESS, FALSE, pid);
    if (!hProc) {
        std::wcout << L"OpenProcess failed (" << GetLastError() << L").\n";
        return 1;
    }

    size_t dllPathSize = (wcslen(argv[2]) + 1) * sizeof(wchar_t);
    LPVOID pRemotePath = VirtualAllocEx(hProc, nullptr, dllPathSize,
                                        MEM_COMMIT | MEM_RESERVE, PAGE_READWRITE);
    if (!pRemotePath) {
        std::wcout << L"VirtualAllocEx failed.\n";
        CloseHandle(hProc);
        return 1;
    }

    WriteProcessMemory(hProc, pRemotePath, argv[2], dllPathSize, nullptr);
    HMODULE hKernel32 = GetModuleHandleW(L"kernel32.dll");
    FARPROC pLoadLibraryW = GetProcAddress(hKernel32, "LoadLibraryW");

    HANDLE hThread = CreateRemoteThread(hProc, nullptr, 0,
                                        (LPTHREAD_START_ROUTINE)pLoadLibraryW,
                                        pRemotePath, 0, nullptr);
    if (!hThread) {
        std::wcout << L"CreateRemoteThread failed.\n";
        VirtualFreeEx(hProc, pRemotePath, 0, MEM_RELEASE);
        CloseHandle(hProc);
        return 1;
    }

    WaitForSingleObject(hThread, INFINITE);
    std::wcout << L"Injection complete.\n";

    VirtualFreeEx(hProc, pRemotePath, 0, MEM_RELEASE);
    CloseHandle(hThread);
    CloseHandle(hProc);
    return 0;
}
