/*
 *  symmetric_average.c
 *
 *  Compute the average of all "symmetric" (palindromic) numbers in a
 *  user‑provided list of n integers.
 *
 *  Security‑focused notes:
 *   • Input length is bounded (MAX_COUNT) to avoid DoS through huge allocations.
 *   • All scanf() calls are checked for successful conversion.
 *   • Sum is kept in a 64‑bit signed integer and overflow is detected.
 *   • No unsafe string functions are used.
 *
 *  Build: gcc -std=c11 -Wall -Wextra -O2 symmetric_average.c -o symmetric_average
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>
#include <limits.h>
#include <errno.h>

/* ---------------------------------------------------------------------- */
/* Configuration ---------------------------------------------------------- */
#define MAX_COUNT 1000000      /* Upper bound on n to prevent huge memory use */

/* ---------------------------------------------------------------------- */
/* Helper: test if a decimal integer is a palindrome (symmetric) --------- */
static bool is_palindrome(long long x)
{
    /* Negative numbers are considered palindromic if the absolute part is.
       The minus sign is ignored because it is not a digit. */
    if (x < 0) x = -x;

    long long original = x;
    long long reversed = 0;

    while (x > 0) {
        int digit = x % 10;
        /* Detect overflow while building reversed (reversed*10 + digit). */
        if (reversed > (LLONG_MAX - digit) / 10) {
            /* Overflow would make the test unreliable → treat as non‑palindromic. */
            return false;
        }
        reversed = reversed * 10 + digit;
        x /= 10;
    }
    return original == reversed;
}

/* ---------------------------------------------------------------------- */
/* Helper: safe addition with overflow detection (GCC/Clang builtin) ----- */
#if defined(__GNUC__) || defined(__clang__)
static bool safe_add_ll(long long a, long long b, long long *out)
{
    return !__builtin_saddll_overflow(a, b, out);
}
#else
/* Portable fallback – manual check (may be less efficient). */
static bool safe_add_ll(long long a, long long b, long long *out)
{
    if ((b > 0 && a > LLONG_MAX - b) ||
        (b < 0 && a < LLONG_MIN - b)) {
        return false;               /* overflow/underflow */
    }
    *out = a + b;
    return true;
}
#endif

/* ---------------------------------------------------------------------- */
int main(void)
{
    long long n = 0;

    printf("Enter the amount of numbers (n, 0 < n ≤ %d): ", MAX_COUNT);
    if (scanf("%lld", &n) != 1) {
        fprintf(stderr, "Error: Invalid input for n.\n");
        return EXIT_FAILURE;
    }

    if (n <= 0 || n > MAX_COUNT) {
        fprintf(stderr, "Error: n must be between 1 and %d.\n", MAX_COUNT);
        return EXIT_FAILURE;
    }

    long long sum = 0;          /* accumulator for symmetric numbers */
    long long count = 0;        /* how many symmetric numbers found */

    printf("Enter %lld integer(s), one per line or separated by spaces:\n", n);
    for (long long i = 0; i < n; ++i) {
        long long value;
        if (scanf("%lld", &value) != 1) {
            fprintf(stderr, "\nError: Failed to read integer #%lld.\n", i + 1);
            return EXIT_FAILURE;
        }

        if (is_palindrome(value)) {
            long long new_sum;
            if (!safe_add_ll(sum, value, &new_sum)) {
                fprintf(stderr,
                        "\nError: Sum overflow when adding value %lld.\n", value);
                return EXIT_FAILURE;
            }
            sum = new_sum;
            ++count;
        }
    }

    if (count == 0) {
        printf("\nNo symmetric (palindromic) numbers were entered.\n");
    } else {
        double average = (double)sum / (double)count;
        printf("\nFound %lld symmetric number(s).\n", count);
        printf("Average of these numbers = %.6f\n", average);
    }

    return EXIT_SUCCESS;
}
```

### How the Program Works

1. **Prompt for `n`** – the number of integers that follow.  
   - The program refuses negative, zero, or excessively large `n` (capped by `MAX_COUNT`).  

2. **Read each integer** using `scanf("%lld", …)`.  
   - If any conversion fails, the program aborts with a clear error message.  

3. **Check symmetry** via `is_palindrome()`.  
   - The function removes the sign, reverses the decimal digits, and compares with the original magnitude.  
   - It also guards against overflow while reversing (the reversed number could exceed `LLONG_MAX`).  

4. **Accumulate safely** – `safe_add_ll()` detects overflow before updating the running sum.  

5. **Compute the average** only if at least one symmetric number was found; otherwise a helpful message is printed.  

### Compilation & Execution

