static inline uint8_t ct_is_all_ff(const uint8_t *buf, size_t len)
{
    uint64_t accum = 0;                     // 累计异或结果
    const uint64_t *p64 = (const uint64_t *)buf;
    size_t words = len / sizeof(uint64_t);

    for (size_t i = 0; i < words; ++i) {
        accum |= p64[i] ^ 0xFFFFFFFFFFFFFFFFULL;
    }

    /* 处理剩余的 0‑7 字节 */
    const uint8_t *tail = buf + words * sizeof(uint64_t);
    for (size_t i = 0; i < len % sizeof(uint64_t); ++i) {
        accum |= tail[i] ^ 0xFF;
    }

    /* 如果全部为 0xFF，accum 必须为 0；否则为非零 */
    /* 下面的技巧把非零压缩到最低位，最后返回 1/0 */
    accum = (accum - 1) >> 63;   // 0 → 0,  non‑zero → 1
    return (uint8_t)(accum ^ 1); // 1 表示全 0xFF
