## 3️⃣ `magazzino.c` – Implementazione con **secure coding practices**

```c
/*=====================================================================
 * magazzino.c
 *   Implementazione delle funzioni di magazzino (vedi magazzino.h)
 *====================================================================*/
#define _POSIX_C_SOURCE 200809L   /* per getline() su piattaforme POSIX */

#include "magazzino.h"
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <inttypes.h>
#include <ctype.h>

/* ------------------------------------------------------------------ */
/* Utility: stampa errore in modo sicuro                               */
/* ------------------------------------------------------------------ */
static void err_msg(const char *msg)
{
    fprintf(stderr, "ERROR: %s\n", msg);
}

/* ------------------------------------------------------------------ */
/* 1. Lettura del file di magazzino                                    */
/* ------------------------------------------------------------------ */
int leggi_magazzino(FILE *fp, Prodotto catalogo[], int *n)
{
    if (!fp || !catalogo || !n) {
        err_msg("Parametri NULL in leggi_magazzino()");
        return -1;
    }

    char line[256];
    int cnt = 0;

    while (fgets(line, sizeof(line), fp) != NULL) {
        if (cnt >= MAX_PRODOTTI) {
            err_msg("Superato il numero massimo di prodotti consentiti");
            break;
        }

        /* Rimuovi eventuale newline */
        line[strcspn(line, "\r\n")] = '\0';

        /* Tokenizza: codice prezzo quantita */
        char codice[CODICE_MAX_LEN + 1];
        long prezzo_long;   /* in centesimi */
        long quantita_long;

        int scanned = sscanf(line, "%31s %ld %ld",
                             codice, &prezzo_long, &quantita_long);
        if (scanned != 3) {
            err_msg("Formato riga non valido nel file di magazzino");
            continue;   /* Salta riga errata, ma continua a leggere */
        }

        /* Validazioni di sicurezza ----------------------------------- */
        if (strlen(codice) == 0) {
            err_msg("Codice prodotto vuoto, riga ignorata");
            continue;
        }
        if (prezzo_long < 0) {
            err_msg("Prezzo negativo, riga ignorata");
            continue;
        }
        if (quantita_long < 0 || quantita_long > QUANTITA_MAX) {
            err_msg("Quantità fuori range, riga ignorata");
            continue;
        }

        /* Copia sicura del codice (strncpy garantisce terminatore) */
        strncpy(catalogo[cnt].codice, codice, CODICE_MAX_LEN);
        catalogo[cnt].codice[CODICE_MAX_LEN] = '\0';

        catalogo[cnt].prezzo_cents = (int64_t)prezzo_long;
        catalogo[cnt].quantita     = (int)quantita_long;

        ++cnt;
    }

    *n = cnt;
    return 0;
}

/* ------------------------------------------------------------------ */
/* 2. Controllo variazione prodotto                                     */
/* ------------------------------------------------------------------ */
int controlla_variazione(const Prodotto catalogo[], int n,
                         const char *codice, int var)
{
    if (!codice) return -1;

    for (int i = 0; i < n; ++i) {
        if (strcmp(catalogo[i].codice, codice) == 0) {
            int nuova_q = catalogo[i].quantita + var;

            if (nuova_q < 0)                     /* decremento > disponibile */
                return -2;
            if (nuova_q > QUANTITA_MAX)          /* superamento soglia massima */
                return -2;

            /* OK – stampa la variazione (solo a scopo informativo) */
            printf("Variazione valida per \"%s\": %d → %d\n",
                   codice, catalogo[i].quantita, nuova_q);
            return 1;
        }
    }
    return -1;   /* prodotto non presente */
}

/* ------------------------------------------------------------------ */
/* 3. Aggiorna magazzino e stampa valore totale (prima/dopo)          */
/* ------------------------------------------------------------------ */
static int64_t calcola_valore_totale(const Prodotto catalogo[], int n)
{
    int64_t totale = 0;
    for (int i = 0; i < n; ++i) {
        /* Usare 128‑bit temporaneo per evitare overflow su 64‑bit */
        __int128 prod = (__int128)catalogo[i].prezzo_cents * catalogo[i].quantita;
        if (prod > INT64_MAX) {
            err_msg("Overflow calcolando il valore totale (capped)");
            prod = INT64_MAX;
        }
        totale += (int64_t)prod;
    }
    return totale;
}

int aggiorna_e_stampa(Prodotto catalogo[], int n,
                     const char *codice, int var)
{
    if (!codice) return -1;

    int idx = -1;
    for (int i = 0; i < n; ++i) {
        if (strcmp(catalogo[i].codice, codice) == 0) {
            idx = i;
            break;
        }
    }
    if (idx == -1) return -1;   /* non dovrebbe succedere */

    int64_t valore_prima = calcola_valore_totale(catalogo, n);

    catalogo[idx].quantita += var;   /* var è già stato validato */

    int64_t valore_dopo = calcola_valore_totale(catalogo, n);

    printf("Valore magazzino prima della modifica: €%lld.%02lld\n",
           (long long)(valore_prima / 100),
           (long long)(valore_prima % 100));
    printf("Valore magazzino dopo  della modifica: €%lld.%02lld\n",
           (long long)(valore_dopo / 100),
           (long long)(valore_dopo % 100));

    return 0;
}

/* ------------------------------------------------------------------ */
/* 4. Ordinamento e stampa su file                                     */
/* ------------------------------------------------------------------ */
static int confronto_valore(const void *a, const void *b)
{
    const Prodotto *pa = a;
    const Prodotto *pb = b;

    /* valore = prezzo * quantita (int64_t), ordinamento decrescente */
    __int128 va = (__int128)pa->prezzo_cents * pa->quantita;
    __int128 vb = (__int128)pb->prezzo_cents * pb->quantita;

    if (va < vb) return  1;
    if (va > vb) return -1;
    return 0;
}

int ordina_e_svuota(FILE *fp, Prodotto catalogo[], int n)
{
    if (!fp || !catalogo) {
        err_msg("Parametri NULL in ordina_e_svuota()");
        return -1;
    }

    qsort(catalogo, (size_t)n, sizeof(Prodotto), confronto_valore);

    for (int i = 0; i < n; ++i) {
        /* Formato di stampa: codice prezzo_cents quantita */
        /* Per il file si usa il prezzo in centesimi per evitare errori di arrotondamento */
        if (fprintf(fp, "%s %lld %d\n",
                    catalogo[i].codice,
                    (long long)catalogo[i].prezzo_cents,
                    catalogo[i].quantita) < 0) {
            err_msg("Scrittura su file fallita");
            return -2;
        }
    }
    return 0;
}
