        return EXIT_FAILURE;
    }

    const char *in_path  = argv[1];
    const char *out_path = argv[2];

    /* --- Apertura file di input ------------------------------------ */
    FILE *fp_in = fopen(in_path, "r");
    if (!fp_in) {
        perror("Apertura file di input fallita");
        return EXIT_FAILURE;
    }

    /* --- Lettura catalogo ------------------------------------------ */
    Prodotto catalogo[MAX_PRODOTTI];
    int n_prodotti = 0;

    if (leggi_magazzino(fp_in, catalogo, &n_prodotti) != 0) {
        fclose(fp_in);
        return EXIT_FAILURE;
    }
    fclose(fp_in);

    /* --- Loop di comando da tastiera ------------------------------- */
    char *line = NULL;
    size_t len = 0;

    printf("Caricati %d prodotti. Inserisci comandi (CODICE VARIAZIONE), "
           "termina con \"XXXXXX\":\n", n_prodotti);

    while (1) {
        printf("> ");
        fflush(stdout);

        ssize_t nread = getline(&line, &len, stdin);
        if (nread == -1) {                 /* EOF o errore */
            if (feof(stdin)) break;
            perror("Errore lettura da stdin");
            free(line);
            return EXIT_FAILURE;
        }

        /* Rimuove newline */
        line[strcspn(line, "\r\n")] = '\0';

        /* Ignora righe vuote */
        if (strlen(line) == 0) continue;

        char codice[CODICE_MAX_LEN + 1];
        long var_long;
        int scanned = sscanf(line, "%31s %ld", codice, &var_long);
        if (scanned != 2) {
            fprintf(stderr, "Formato comando non valido, riprova.\n");
            continue;
        }

        /* Caso di terminazione */
        if (strcmp(codice, "XXXXXX") == 0)
            break;

        /* Validazione della variazione (limiti di int) */
        if (var_long < INT_MIN || var_long > INT_MAX) {
            fprintf(stderr, "Variazione fuori range di un int.\n");
            continue;
        }
        int var = (int)var_long;

        /* Controllo preliminare */
        int rc = controlla_variazione(catalogo, n_prodotti, codice, var);
        if (rc == 1) {
            /* Variazione valida → aggiorna e stampa valore totale */
            if (aggiorna_e_stampa(catalogo, n_prodotti, codice, var) != 0) {
                fprintf(stderr, "Errore durante l'aggiornamento.\n");
            }
        } else if (rc == -1) {
            fprintf(stderr, "Prodotto \"%s\" non trovato. Ignoro.\n", codice);
        } else if (rc == -2) {
            fprintf(stderr,
                    "Variazione non realizzabile per \"%s\" (under/overflow). Ignoro.\n",
                    codice);
        }
    }

    free(line);   /* libera buffer allocato da getline() */

    /* --- Scrittura file di output (ordinato) ------------------------ */
    FILE *fp_out = fopen(out_path, "w");
    if (!fp_out) {
        perror("Apertura file di output fallita");
        return EXIT_FAILURE;
    }

    if (ordina_e_svuota(fp_out, catalogo, n_prodotti) != 0) {
        fclose(fp_out);
        return EXIT_FAILURE;
    }
    fclose(fp_out);

    printf("Magazzino salvato in \"%s\" (ordinato per valore decrescente).\n",
           out_path);
    return EXIT_SUCCESS;
}
```

