 * ------------------------------------------------------------------ */
typedef enum {
    ACTION_LOOK = 1,
    ACTION_MOVE,
    ACTION_QUIT,
    ACTION_SEARCH
} menu_action_t;

/* ------------------------------------------------------------------
 *  MAIN GAME LOOP (playGame)
 * ------------------------------------------------------------------ */
void playGame(void)
{
    printf("Welcome to the adventure!\n");
    game *g = createGame();

    printRoomDescription(g->player->currentRoom);

    bool quit = false;
    while (!quit) {
        int rawChoice = getMenuChoice();
        menu_action_t choice = (menu_action_t)rawChoice;

        switch (choice) {
            case ACTION_LOOK:
                printRoomDescription(g->player->currentRoom);
                break;
            case ACTION_MOVE: {
                int roomChoice = getRoomChoice(g->player->currentRoom);
                movePlayer(g->player, roomChoice);
                break;
            }
            case ACTION_SEARCH:
                searchRoom(g->player);
                break;
            case ACTION_QUIT:
                quit = true;
                break;
            default:
                /* Should never happen because of validation, but keep it defensive */
                fprintf(stderr, "Internal error: unknown menu choice %d\n", rawChoice);
                quit = true;
                break;
        }
    }

    /* TODO: free all allocated memory (rooms, connections, strings, etc.) */
}
```

*Security note:* The `default` branch is defensive – if the validation were ever bypassed (e.g., by a memory‑corruption exploit), we abort gracefully instead of executing undefined code.

