/*********************************************************************
 *  Dijkstra 最短路径实现（基于邻接矩阵）
 *  适用于顶点数 ≤ MAX_V 的无向/有向加权图，权值必须为非负整数。
 *
 *  关键步骤：
 *   1) 初始化：邻接矩阵、最短路径数组 D[i]、前驱数组 prev[i]、访问标记 visited[i]
 *   2) 寻找未访问的最小 D[k]，并标记该顶点已访问
 *   3) 用 D[k] 来松弛 (Relax) 与 k 相邻的所有顶点，更新 D[i] 与 prev[i]
 *   4) 重复 2、3，直至所有顶点均被访问
 *
 *  本代码可直接编译运行：   gcc -Wall -Wextra -O2 dijkstra.c -o dijkstra
 *********************************************************************/

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <limits.h>

#define MAX_V   100                 // 最大顶点数（可自行修改）
#define INF     (INT_MAX/4)        // 表示“无穷大”，防止溢出（INT_MAX/4 足够大且安全）

/*----------------------  数据结构声明 ----------------------*/
typedef struct {
    int n;                         // 实际顶点数
    int w[MAX_V][MAX_V];           // 邻接矩阵，w[i][j] 为 (Vi,Vj) 的权值，若无边则为 INF
} Graph;

/*----------------------  辅助函数 ----------------------*/
/* 打印从 src 到每个顶点的最短距离及路径 */
void print_result(int src, int dist[MAX_V], int prev[MAX_V], int n) {
    printf("\n=== Dijkstra 最短路径结果 (src = V%d) ===\n", src);
    for (int v = 0; v < n; ++v) {
        if (dist[v] == INF) {
            printf("V%d : 不可达\n", v);
            continue;
        }

        printf("V%d : 最短距离 = %d   路径 = V%d", v, dist[v], src);
        // 逆向追踪前驱数组，得到完整路径
        int path[MAX_V];
        int cnt = 0;
        for (int u = v; u != src && u != -1; u = prev[u]) {
            path[cnt++] = u;
        }
        // 打印路径（从 src 到 v）
        for (int i = cnt - 1; i >= 0; --i) {
            printf(" -> V%d", path[i]);
        }
        printf("\n");
    }
}

/*----------------------  Dijkstra 主函数 ----------------------*/
void dijkstra(const Graph *g, int src) {
    int n = g->n;
    int dist[MAX_V];        // D[i]：当前求得的最短距离
    int visited[MAX_V];     // visited[i]：0=未访问，1=已确定最短路径
    int prev[MAX_V];        // prev[i]：记录前驱顶点，用于还原路径

    /* 1) 初始化 ------------------------------------------------*/
    for (int i = 0; i < n; ++i) {
        dist[i]    = (i == src) ? 0 : INF;   // src 距离为 0，其他为 INF
        visited[i] = 0;                      // 全部标记为未访问
        prev[i]    = -1;                     // 前驱初始化为 -1（未知）
    }

    /* 2) 主循环：循环 n 次，每次选出一个最近的未访问顶点 --------*/
    for (int iter = 0; iter < n; ++iter) {
        /* ---- 2) 求最小 ---- */
        int minDist = INF;
        int k = -1;                          // 待选顶点
        for (int i = 0; i < n; ++i) {
            if (!visited[i] && dist[i] < minDist) {
                minDist = dist[i];
                k = i;
            }
        }

        if (k == -1) {                       // 所有剩余顶点均不可达
            break;
        }
        visited[k] = 1;                      // 标记 Vk 已访问（最短路径确定）

        /* ---- 3) 更新（Relax） ---- */
        for (int i = 0; i < n; ++i) {
            if (!visited[i] && g->w[k][i] != INF) {
                // 防止 dist[k] + w[k][i] 产生整数溢出
                if (dist[k] > INF - g->w[k][i]) continue;
                int cand = dist[k] + g->w[k][i];
                if (cand < dist[i]) {
                    dist[i] = cand;
                    prev[i] = k;              // 记录前驱，以便后续恢复路径
                }
            }
        }
    }

    /* 4) 输出结果 ------------------------------------------------*/
    print_result(src, dist, prev, n);
}

/*----------------------  示例：手动构造图 ----------------------*/
int main(void) {
    Graph g;
