    // 边 (V1, V2) 权值 10
    g.w[1][2] = g.w[2][1] = 10;
    // 边 (V1, V3) 权值 15
    g.w[1][3] = g.w[3][1] = 15;
    // 边 (V2, V3) 权值 11
    g.w[2][3] = g.w[3][2] = 11;
    // 边 (V2, V5) 权值 2
    g.w[2][5] = g.w[5][2] = 2;
    // 边 (V3, V4) 权值 6
    g.w[3][4] = g.w[4][3] = 6;
    // 边 (V4, V5) 权值 9
    g.w[4][5] = g.w[5][4] = 9;

    /*--- 调用 Dijkstra，源点为 V0（下标 0）---*/
    dijkstra(&g, 0);

    return 0;
}
```

