### 1.  Full source (C99)

```c
/*  SPDX‑License-Identifier: MIT
 *
 *  Example: ANSI X9.63 KDF -> AES‑128 key + HMAC‑SHA‑512 key
 *
 *  Build (Linux/macOS):
 *      gcc -Wall -Wextra -O2 -o kdf_x9_63_example kdf_x9_63_example.c \
 *          $(pkg-config --cflags --libs openssl)
 *
 *  Requires OpenSSL ≥ 3.0 (or 1.1.1 with the legacy provider loaded).
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <openssl/evp.h>
#include <openssl/kdf.h>
#include <openssl/err.h>

#define AES128_KEYLEN   16   /* 128‑bit */
#define HMAC512_KEYLEN  64   /* 512‑bit */
#define TOTAL_KEYLEN   (AES128_KEYLEN + HMAC512_KEYLEN)

/* Helper: print buffer as hex */
static void hexprint(const char *label, const unsigned char *buf, size_t len)
{
    printf("%s (%zu bytes): ", label, len);
    for (size_t i = 0; i < len; ++i)
        printf("%02X", buf[i]);
    printf("\n");
}

/* ---------------------------------------------------------------------- */
/*  Derive `out_len` bytes from secret || otherInfo using KDF X9.63 (SHA‑512)*/
/* ---------------------------------------------------------------------- */
static int kdf_x9_63_derive(const unsigned char *secret, size_t secret_len,
                           const unsigned char *info,   size_t info_len,
                           unsigned char *out,          size_t out_len)
{
    int ret = 0;
    EVP_KDF *kdf = NULL;
    EVP_KDF_CTX *kctx = NULL;
    OSSL_PARAM params[5];
    const char *md_name = "SHA512";

    /* 1.  Fetch the X9.63 KDF implementation  */
    kdf = EVP_KDF_fetch(NULL, "X963", NULL);
    if (kdf == NULL) {
        fprintf(stderr, "EVP_KDF_fetch() failed\n");
        ERR_print_errors_fp(stderr);
        goto cleanup;
    }

    kctx = EVP_KDF_CTX_new(kdf);
    if (kctx == NULL) {
        fprintf(stderr, "EVP_KDF_CTX_new() failed\n");
        ERR_print_errors_fp(stderr);
        goto cleanup;
    }

    /* 2.  Set the KDF parameters */
    params[0] = OSSL_PARAM_construct_utf8_string("digest", (char *)md_name, 0);
    params[1] = OSSL_PARAM_construct_octet_string("secret", (void *)secret,
                                                  secret_len);
    params[2] = OSSL_PARAM_construct_octet_string("info", (void *)info,
                                                  info_len);
    params[3] = OSSL_PARAM_construct_size_t("keylen", &out_len);
    params[4] = OSSL_PARAM_construct_end();

    if (EVP_KDF_CTX_set_params(kctx, params) <= 0) {
        fprintf(stderr, "EVP_KDF_CTX_set_params() failed\n");
        ERR_print_errors_fp(stderr);
        goto cleanup;
    }

    /* 3.  Perform the derivation */
    if (EVP_KDF_derive(kctx, out, out_len) <= 0) {
        fprintf(stderr, "EVP_KDF_derive() failed\n");
        ERR_print_errors_fp(stderr);
        goto cleanup;
    }

    ret = 1;          /* success */

cleanup:
    EVP_KDF_CTX_free(kctx);
    EVP_KDF_free(kdf);
    return ret;
}

/* ---------------------------------------------------------------------- */
int main(void)
{
    /* ------------------------------------------------------------------
       1️⃣  Dummy inputs – replace with your real values
          --------------------------------------------------------------- */
    /* Example: a 256‑bit “shared secret” (e.g. ECDH output) */
    unsigned char Z[32] = {
        0x3A,0xB7,0x1F,0xD4,0x52,0x8E,0xC1,0x66,
        0x99,0x7D,0xE0,0x2B,0x5A,0xC3,0x11,0x44,
        0xC9,0x5F,0x23,0x6A,0x8D,0xAF,0x1E,0x7C,
        0xB2,0x09,0x33,0xE5,0x71,0xDA,0xF6,0x0B
    };
    size_t Z_len = sizeof(Z);

    /* OtherInfo for the two derived keys – could be algorithm IDs,
       usage counters, etc.  The X9.63 spec treats it as an opaque
       byte string that is concatenated to the secret before hashing. */
    const unsigned char otherInfoAES[]   = "AES-128-KEY";
    const unsigned char otherInfoHMAC[]  = "HMAC-SHA512-KEY";

    /* ------------------------------------------------------------------
       2️⃣  Derive the two keys (concatenated output → split) */
       ------------------------------------------------------------------ */
    unsigned char derived[TOTAL_KEYLEN];
    unsigned char *aes_key   = derived;                 /* first 16 bytes   */
    unsigned char *hmac_key  = derived + AES128_KEYLEN; /* next 64 bytes    */

    /* Derive AES‑128 key */
    if (!kdf_x9_63_derive(Z, Z_len,
                         otherInfoAES, sizeof(otherInfoAES)-1,
                         aes_key, AES128_KEYLEN)) {
        fprintf(stderr, "Failed to derive AES‑128 key\n");
        return EXIT_FAILURE;
    }

    /* Derive HMAC‑SHA‑512 key (different OtherInfo → independent sub‑key) */
    if (!kdf_x9_63_derive(Z, Z_len,
                         otherInfoHMAC, sizeof(otherInfoHMAC)-1,
                         hmac_key, HMAC512_KEYLEN)) {
        fprintf(stderr, "Failed to derive HMAC‑SHA‑512 key\n");
        return EXIT_FAILURE;
    }

    /* ------------------------------------------------------------------
       3️⃣  Show the results */
       ------------------------------------------------------------------ */
    hexprint("Derived AES‑128 key", aes_key, AES128_KEYLEN);
    hexprint("Derived HMAC‑SHA‑512 key", hmac_key, HMAC512_KEYLEN);

    /* ------------------------------------------------------------------
       4️⃣  (Optional) Quick sanity test – encrypt a block with the AES key
           and compute an HMAC tag just to prove the keys are usable.
           --------------------------------------------------------------- */
    {
        /* AES‑128‑CBC (IV = all‑zero for demo) */
        unsigned char iv[16] = {0};
        unsigned char plaintext[16] = "OpenSSL‑Demo!!";
        unsigned char ciphertext[16];
        unsigned char decrypted[16];
        int outlen = 0, tmplen = 0;
        EVP_CIPHER_CTX *cctx = EVP_CIPHER_CTX_new();

        EVP_EncryptInit_ex(cctx, EVP_aes_128_cbc(), NULL, aes_key, iv);
        EVP_EncryptUpdate(cctx, ciphertext, &outlen, plaintext, sizeof(plaintext));
        EVP_EncryptFinal_ex(cctx, ciphertext + outlen, &tmplen);
        outlen += tmplen;
        EVP_CIPHER_CTX_free(cctx);

        /* HMAC‑SHA‑512 */
        unsigned char tag[EVP_MAX_MD_SIZE];
        unsigned int taglen = 0;
        EVP_MAC *mac = EVP_MAC_fetch(NULL, "HMAC", NULL);
        EVP_MAC_CTX *mctx = EVP_MAC_CTX_new(mac);
        OSSL_PARAM mac_params[2] = {
            OSSL_PARAM_construct_utf8_string("digest", "SHA512", 0),
            OSSL_PARAM_construct_end()
        };
        EVP_MAC_init(mctx, hmac_key, HMAC512_KEYLEN, mac_params);
        EVP_MAC_update(mctx, ciphertext, outlen);
        EVP_MAC_final(mctx, tag, &taglen, sizeof(tag));
        EVP_MAC_CTX_free(mctx);
        EVP_MAC_free(mac);

        hexprint("Ciphertext (AES‑128‑CBC)", ciphertext, outlen);
        hexprint("HMAC‑SHA‑512 tag", tag, taglen);
    }

    return EXIT_SUCCESS;
}
```

---

### 2.  What the code does (step‑by‑step)

| Step | What happens | Why it matters |
|------|--------------|----------------|
| **Input data** | `Z` (the shared secret) + two different *OtherInfo* strings (`"AES-128-KEY"` and `"HMAC-SHA512-KEY"`). | X9.63 KDF uses `Z || OtherInfo` as the seed for the hash‑based expansion, guaranteeing cryptographic separation between the two derived keys. |
