 * 本程序遵循安全编码最佳实践：
 *   1. 使用 fgets + strtol 读取并解析整数，避免 scanf 的格式串攻击。
 *   2. 对 strtol 的错误进行完整检查（溢出、无效字符、范围）。
 *   3. 采用常量大小的局部数组，避免动态内存分配导致的泄漏/双释放。
 *   4. 所有路径均返回明确的退出码（0 = 正常，1 = 输入错误，2 = 其它错误）。
 */

#include <stdio.h>
#include <stdlib.h>
#include <errno.h>
#include <limits.h>
#include <string.h>

#define ARRAY_SIZE 10
#define INPUT_BUF_SIZE 64   /* 足够容纳 64 位整数的十进制表示 + 换行符 */

int main(void)
{
    /* 1. 初始化数组（这里用示例数据） */
    int a[ARRAY_SIZE] = { 5, 12, -3, 0, 7, 9, 15, 22, -8, 4 };

    /* 2. 从键盘读取一行文字 */
    char buf[INPUT_BUF_SIZE];
    if (fgets(buf, sizeof(buf), stdin) == NULL) {
        fprintf(stderr, "错误：读取输入失败。\n");
        return 1;
    }

    /* 3. 去掉可能的换行符 */
    buf[strcspn(buf, "\r\n")] = '\0';

    /* 4. 使用 strtol 将字符串转换为 long（随后检查是否在 int 范围内） */
    char *endptr = NULL;
    errno = 0;                     /* 清除 errno，便于后续检测 */
    long val = strtol(buf, &endptr, 10);

    /* 4.1 错误检测 */
    if (errno == ERANGE || val < INT_MIN || val > INT_MAX) {
        fprintf(stderr, "错误：输入的数字超出 int 可表示的范围 (%d ~ %d)。\n", INT_MIN, INT_MAX);
