    /* 5. 线性搜索（时间复杂度 O(N)，数组很小，足够使用） */
    int found = 0;                 /* 标记是否找到 */
    for (size_t i = 0; i < ARRAY_SIZE; ++i) {
        if (a[i] == target) {
            found = 1;
            break;
        }
