## 完整代码（C99／C11）

```c
/*
 * 计算两个整数的 GCD（最大公约数）和 LCM（最小公倍数）
 * 采用安全的输入解析、防溢出检查以及错误处理。
 *
 * 编译示例（Linux/macOS）:
 *   gcc -std=c11 -Wall -Wextra -O2 -o gcd_lcm gcd_lcm.c
 *
 * 运行示例:
 *   $ ./gcd_lcm
 *   输入两个整数: 48 180
 *   GCD = 12
 *   LCM = 720
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <inttypes.h>
#include <errno.h>
#include <ctype.h>
#include <limits.h>

/* ---------- 安全的整数读取 ---------- */
static int read_int64(const char *prompt, int64_t *out)
{
    char *line = NULL;
    size_t len = 0;
    ssize_t nread;

    printf("%s", prompt);
    fflush(stdout);

    nread = getline(&line, &len, stdin);
    if (nread == -1) {
        free(line);
        return -1;          // 读取错误或 EOF
    }

    /* 去掉行尾换行 */
    if (nread > 0 && line[nread - 1] == '\n')
        line[nread - 1] = '\0';

    /* 逐字符检查，只允许空格、制表符以及数字符号 */
    const char *p = line;
    while (isspace((unsigned char)*p)) p++;   // 跳过前导空格

    if (*p == '\0') {      // 全是空格
        free(line);
        return -1;
    }

    char *endptr;
    errno = 0;
    int64_t val = strtoll(p, &endptr, 10);
    if (errno == ERANGE) {
        free(line);
        return -1;        // 超出 int64 范围
    }

    /* 确保后面没有非法字符（只允许空格） */
    while (isspace((unsigned char)*endptr)) endptr++;
    if (*endptr != '\0') {
        free(line);
        return -1;        // 包含非法字符
    }

    *out = val;
    free(line);
    return 0;
}

/* ---------- 计算 GCD ---------- */
static int64_t gcd_int64(int64_t a, int64_t b)
{
    /* 让 a、b 为非负数，避免负数取模的实现差异 */
    if (a < 0) a = -a;
    if (b < 0) b = -b;

    while (b != 0) {
        int64_t r = a % b;
        a = b;
        b = r;
    }
    return a;
}

/* ---------- 检查乘法是否溢出 ---------- */
static int mul_will_overflow(int64_t a, int64_t b, int64_t *out)
{
    /* 当 a 或 b 为 0 时一定安全 */
    if (a == 0 || b == 0) {
        *out = 0;
        return 0;
    }

    /* 绝对值大于 INT64_MAX / |other| 必然溢出 */
    if (a > 0) {
        if (b > 0) {
            if (a > INT64_MAX / b) return 1;
        } else { // b < 0
            if (b < INT64_MIN / a) return 1;
        }
    } else { // a < 0
        if (b > 0) {
            if (a < INT64_MIN / b) return 1;
        } else { // b < 0
            if (a < INT64_MAX / b) return 1;
        }
    }

    *out = a * b;
    return 0;
}

/* ---------- 计算 LCM ---------- */
static int64_t lcm_int64(int64_t a, int64_t b, int *overflow)
{
    if (a == 0 || b == 0) {
        *overflow = 0;
        return 0;
    }

    int64_t g = gcd_int64(a, b);
    /* 先除后乘，避免 (a*b) 直接溢出 */
    int64_t a_div_g = a / g;

    int64_t lcm;
    if (mul_will_overflow(a_div_g, b, &lcm)) {
        *overflow = 1;
        return 0;
    }

    /* LCM 总是非负 */
    if (lcm < 0) lcm = -lcm;
    *overflow = 0;
    return lcm;
}

/* ---------- 主函数 ---------- */
int main(void)
{
    int64_t x, y;
    if (read_int64("请输入第一个整数: ", &x) != 0) {
        fprintf(stderr, "输入错误，请确保只输入合法整数。\n");
        return EXIT_FAILURE;
    }

    if (read_int64("请输入第二个整数: ", &y) != 0) {
        fprintf(stderr, "输入错误，请确保只输入合法整数。\n");
        return EXIT_FAILURE;
    }

    int64_t g = gcd_int64(x, y);
    int overflow = 0;
    int64_t l = lcm_int64(x, y, &overflow);

    printf("GCD = %" PRId64 "\n", g);
    if (overflow) {
        printf("LCM 计算结果溢出（超过 int64 范围），无法安全给出数值。\n");
    } else {
        printf("LCM = %" PRId64 "\n", l);
