 *      a1 a2 a3 ... aN // space‑ or newline‑separated signed integers
 *
 *  Example:
 *      $ echo -e "9\n3 1 4 1 5 9 2 6 5" | ./lis
 *      LIS length: 5
 *      LIS: 1 4 5 6 9
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <inttypes.h>
#include <errno.h>
#include <string.h>

/*---------------------------------------------------------------*/
/*                     Utility & error handling                  */
/*---------------------------------------------------------------*/
static void panic(const char *msg) __attribute__((noreturn));
static void panic(const char *msg) {
    fprintf(stderr, "Fatal error: %s\n", msg);
    exit(EXIT_FAILURE);
}

/* safe multiplication for size_t (detect overflow) */
static size_t safe_mul(size_t a, size_t b) {
    if (a == 0 || b == 0) return 0;
    if (a > SIZE_MAX / b) {
        panic("size_t multiplication overflow");
    }
    return a * b;
}

/*---------------------------------------------------------------*/
/*                Parsing the integer sequence                     */
/*---------------------------------------------------------------*/
static int32_t *read_input(size_t *out_len) {
    /* First token: N */
    long N_long;
    char *endptr = NULL;
    errno = 0;
    N_long = strtol(fgets(NULL, 0, stdin), &endptr, 10);   // dummy, will be replaced
    /* Actually we cannot use fgets(NULL...), so we read manually */
    if (scanf("%ld", &N_long) != 1) {
        panic("Failed to read number of elements");
    }
    if (errno == ERANGE || N_long < 0 || N_long > 1000000L) {
        panic("Invalid N (out of allowed range 0‑1e6)");
    }
    size_t N = (size_t)N_long;
    *out_len = N;

    if (N == 0) {
        return NULL;   // empty sequence
    }

    int32_t *arr = malloc(safe_mul(N, sizeof(int32_t)));
    if (!arr) panic("malloc failed for input array");

    for (size_t i = 0; i < N; ++i) {
        long val_long;
        if (scanf("%ld", &val_long) != 1) {
            free(arr);
            panic("Failed to read integer element");
        }
        if (errno == ERANGE || val_long < INT32_MIN || val_long > INT32_MAX) {
            free(arr);
            panic("Input integer out of int32_t range");
        }
        arr[i] = (int32_t)val_long;
    }
    return arr;
}

/*---------------------------------------------------------------*/
/*                LIS core algorithm (O(N log N))                */
/*---------------------------------------------------------------*/
/* Helper: binary search for the first element >= target */
static size_t lower_bound(const int32_t *seq, size_t len, int32_t target) {
    size_t lo = 0, hi = len;
    while (lo < hi) {
        size_t mid = lo + (hi - lo) / 2;
        if (seq[mid] < target)
            lo = mid + 1;
        else
            hi = mid;
    }
    return lo;
}

/* Result container */
typedef struct {
    size_t length;          // length of LIS
    int32_t *subseq;        // the subsequence itself (allocated)
} lis_result_t;

/* Main function that computes LIS */
static lis_result_t compute_lis(const int32_t *a, size_t n) {
    if (n == 0) {
        lis_result_t empty = {0, NULL};
        return empty;
    }

    /* tails[i] = minimal possible tail value of an increasing subsequence of length i+1 */
    int32_t *tails = malloc(safe_mul(n, sizeof(int32_t)));
    /* pos[i] = index in original array where tails[i] was taken from (for reconstruction) */
    size_t *pos   = malloc(safe_mul(n, sizeof(size_t)));
    /* prev[j] = previous element index of a[j] in the LIS ending at a[j] */
    size_t *prev  = malloc(safe_mul(n, sizeof(size_t)));

    if (!tails || !pos || !prev) {
        free(tails); free(pos); free(prev);
        panic("malloc failed for LIS auxiliary arrays");
    }

    size_t length = 0;   // current length of LIS

    for (size_t i = 0; i < n; ++i) {
        int32_t x = a[i];
        size_t idx = lower_bound(tails, length, x);   // first >= x

        tails[idx] = x;
        pos[idx] = i;
        prev[i] = (idx == 0) ? SIZE_MAX : pos[idx - 1];

        if (idx == length) {
            ++length;
        }
    }

    /* Reconstruct one LIS (from back to front) */
    int32_t *seq = malloc(safe_mul(length, sizeof(int32_t)));
    if (!seq) {
        free(tails); free(pos); free(prev);
        panic("malloc failed for result subsequence");
    }

    size_t k = pos[length - 1];   // index of last element in LIS
    for (size_t i = length; i-- > 0;) {
        seq[i] = a[k];
        k = prev[k];
    }

    free(tails);
    free(pos);
    free(prev);

    lis_result_t res = {length, seq};
    return res;
}

/*---------------------------------------------------------------*/
/*                            main                                 */
/*---------------------------------------------------------------*/
int main(void) {
    /* 1️⃣ Read input safely */
    size_t n = 0;
    int32_t *input = read_input(&n);

    /* 2️⃣ Compute LIS */
    lis_result_t result = compute_lis(input, n);

    /* 3️⃣ Output */
    printf("LIS length: %zu\n", result.length);
    if (result.length > 0) {
        printf("LIS: ");
        for (size_t i = 0; i < result.length; ++i) {
            printf("%" PRId32, result.subseq[i]);
            if (i + 1 != result.length) putchar(' ');
        }
        putchar('\n');
    }

    /* 4️⃣ Clean up */
    free(input);
    free(result.subseq);
    return EXIT_SUCCESS;
}
