#include <stdio.h>
#include <stdlib.h>
#include <limits.h>
#include <stdbool.h>

/* ---- 安全的整数读取函数 ---- */
bool safe_read_int(const char *prompt, int *out, int min, int max) {
    printf("%s", prompt);
    /* 限定宽度，防止用户输入超长导致缓冲区溢出 */
    if (scanf("%9d", out) != 1) {
        /* 清空残余输入 */
        int c; while ((c = getchar()) != '\n' && c != EOF);
        return false;
    }
    if (*out < min || *out > max) return false;
    return true;
}

/* ---- 闰年判定 ---- */
bool is_leap(int year) {
    return (year % 4 == 0 && year % 100 != 0) || (year % 400 == 0);
}

/* ---- 主函数 ---- */
int main(void) {
    int year, month, day;

    /* 读取并校验年份、月份、日期 */
    if (!safe_read_int("请输入年份 (1~9999): ", &year, 1, 9999)) {
        fprintf(stderr, "年份非法！\n");
        return EXIT_FAILURE;
    }
    if (!safe_read_int("请输入月份 (1~12): ", &month, 1, 12)) {
        fprintf(stderr, "月份非法！\n");
        return EXIT_FAILURE;
    }
    if (!safe_read_int("请输入日期 (1~31): ", &day, 1, 31)) {
        fprintf(stderr, "日期非法！\n");
        return EXIT_FAILURE;
    }

    /* 月份天数表（平年） */
    static const int month_days[12] = {
        31,28,31,30,31,30,31,31,30,31,30,31
    };

    /* 检查 day 是否超过该月的最大天数 */
    int max_day = month_days[month - 1];
    if (month == 2 && is_leap(year)) max_day = 29;
    if (day > max_day) {
        fprintf(stderr, "日期超过该月最大天数！\n");
        return EXIT_FAILURE;
    }

    /* 计算当年的第几天 */
    int day_of_year = day;
    for (int i = 0; i < month - 1; ++i) {
        day_of_year += month_days[i];
        if (i == 1 && is_leap(year)) ++day_of_year;   // 二月闰年多一天
    }

    int total_days = is_leap(year) ? 366 : 365;
    int days_left = total_days - day_of_year;   // 不包括当天

    printf("%d-%02d-%02d 到当年年底还有 %d 天。\n",
           year, month, day, days_left);
    return EXIT_SUCCESS;
}
