#!/usr/bin/env python3
# -*- coding: utf-8 -*-

import sys

def is_leap(year: int) -> bool:
    """闰年判定"""
    return (year % 4 == 0 and year % 100 != 0) or (year % 400 == 0)

def validate_date(y: int, m: int, d: int) -> bool:
    """检查日期合法性，返回 True/False"""
    if not (1 <= y <= 9999):
        return False
    if not (1 <= m <= 12):
        return False
    # 每月天数（平年）
    month_days = [31,28,31,30,31,30,31,31,30,31,30,31]
    max_day = month_days[m-1]
    if m == 2 and is_leap(y):
        max_day = 29
    return 1 <= d <= max_day

def days_to_year_end(y: int, m: int, d: int) -> int:
    """核心计算：返回距离当年 12-31 的天数（不含当天）"""
    month_days = [31,28,31,30,31,30,31,31,30,31,30,31]
    if is_leap(y):
        month_days[1] = 29          # 二月改为 29 天

    # 累计天数（从 1 Jan 开始计数）
    day_of_year = sum(month_days[:m-1]) + d
    total = 366 if is_leap(y) else 365
    return total - day_of_year

def main():
    try:
        # 从标准输入读取三个整数，支持空格或换行分隔
        raw = input("请输入 年 月 日（空格分隔）: ").strip()
        year, month, day = map(int, raw.split())
    except (ValueError, EOFError):
        sys.stderr.write("输入格式错误，请输入三个整数！\n")
        sys.exit(1)

    if not validate_date(year, month, day):
        sys.stderr.write("非法日期！请检查年、月、日是否在合法范围内。\n")
        sys.exit(1)

    left = days_to_year_end(year, month, day)
    print(f"{year}-{month:02d}-{day:02d} 到当年年底还有 {left} 天。")

if __name__ == "__main__":
    main()
```

#### Python 安全点
- **异常捕获**：`try/except` 捕获 `ValueError`、`EOFError`，防止程序因非法输入崩溃。
- **严格类型转换**：使用 `map(int, ...)`，若出现非数字直接抛异常。
- **输入范围校验**：`validate_date` 中对年、月、日分别做上下限检查。
- **不依赖系统时间库**：手动维护月份天数，消除跨时区、夏令时等隐蔽错误。

