/*
 * quicksort.c
 *
 * Example Quick‑Sort implementation with a random‑array generator.
 * Intended for educational / testing purposes – not a production‑grade
 * library.  See the security notes above for hardening suggestions.
 *
 * Compile: gcc -Wall -Wextra -O2 -std=c11 quicksort.c -o quicksort
 */

#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <stdint.h>
#include <errno.h>

/* --------------------------------------------------------------------------- *
 *  Secure random number generation (optional)
 * --------------------------------------------------------------------------- */
#ifdef USE_SECURE_RNG
#include <unistd.h>
#include <sys/random.h>

/* Fill buffer with cryptographically‑secure random bytes.
 * Returns 0 on success, -1 on failure (errno set). */
static int secure_random(void *buf, size_t len)
{
    ssize_t r = getrandom(buf, len, 0);
    if (r < 0) return -1;
    if ((size_t)r != len) {
        errno = EIO;
        return -1;
    }
    return 0;
}
#endif /* USE_SECURE_RNG */

/* --------------------------------------------------------------------------- *
 *  Helper: swap two array elements
 * --------------------------------------------------------------------------- */
static void swap(int *a, int *b)
{
    int tmp = *a;
    *a = *b;
    *b = tmp;
}

/* --------------------------------------------------------------------------- *
 *  Partition routine (Lomuto scheme)
 *  Returns the final pivot index.
 * --------------------------------------------------------------------------- */
static size_t partition(int *arr, size_t low, size_t high)
{
    /* Choose the last element as pivot – simple but works for demo. */
    int pivot = arr[high];
    size_t i = low;          /* Index of smaller element */

    for (size_t j = low; j < high; ++j) {
        if (arr[j] <= pivot) {
            swap(&arr[i], &arr[j]);
            ++i;
        }
    }
    swap(&arr[i], &arr[high]);  /* Place pivot in correct position */
    return i;
}

/* --------------------------------------------------------------------------- *
 *  Quick‑Sort (recursive).  Depth limit to avoid stack overflow.
 * --------------------------------------------------------------------------- */
#define QUICK_SORT_MAX_RECURSION  64  /* safe for most platforms */

static void quicksort_rec(int *arr, size_t low, size_t high,
                          unsigned depth)
{
    if (low < high) {
        /* Guard recursion depth */
        if (depth > QUICK_SORT_MAX_RECURSION) {
            /* Fallback to insertion sort for the remaining segment */
            for (size_t i = low + 1; i <= high; ++i) {
                int key = arr[i];
                size_t j = i;
                while (j > low && arr[j - 1] > key) {
                    arr[j] = arr[j - 1];
                    --j;
                }
                arr[j] = key;
            }
            return;
        }

        size_t p = partition(arr, low, high);
        if (p > 0)  /* avoid underflow */
            quicksort_rec(arr, low, p - 1, depth + 1);
        quicksort_rec(arr, p + 1, high, depth + 1);
    }
}

/* --------------------------------------------------------------------------- *
 *  Public API: quicksort()
 * --------------------------------------------------------------------------- */
void quicksort(int *arr, size_t n)
{
    if (arr == NULL || n < 2) return;
    quicksort_rec(arr, 0, n - 1, 0);
}

/* --------------------------------------------------------------------------- *
 *  Random array generator
 *  Returns pointer to a newly allocated array of `n` ints, or NULL on error.
 *  The caller MUST free() the returned pointer.
 * --------------------------------------------------------------------------- */
int *generate_random_array(size_t n)
{
    if (n == 0) return NULL;

    int *arr = malloc(n * sizeof(int));
    if (!arr) return NULL;   /* malloc failed */

#ifdef USE_SECURE_RNG
    /* Fill with cryptographically‑secure randomness (modulo INT_MAX+1). */
    for (size_t i = 0; i < n; ++i) {
        uint32_t rnd;
        if (secure_random(&rnd, sizeof(rnd)) != 0) {
            free(arr);
            return NULL;
        }
        arr[i] = (int)(rnd % (INT_MAX + 1ULL));
    }
#else
    /* Simple PRNG – good enough for testing, but predictable. */
    srand((unsigned)time(NULL));  /* seed once per process */
    for (size_t i = 0; i < n; ++i) {
        arr[i] = rand();          /* 0 .. RAND_MAX */
    }
#endif

    return arr;
}

/* --------------------------------------------------------------------------- *
 *  Demo driver (not part of the library)
 * --------------------------------------------------------------------------- */
int main(int argc, char *argv[])
{
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <array-size>\n", argv[0]);
        return EXIT_FAILURE;
    }

    char *endptr = NULL;
    errno = 0;
    unsigned long ul = strtoul(argv[1], &endptr, 10);
    if (errno || *endptr != '\0' || ul == 0) {
        fprintf(stderr, "Invalid size: %s\n", argv[1]);
        return EXIT_FAILURE;
