 * Secure BST level‑order traversal (C99)
 * ------------------------------------------------------------- */
#include <stdio.h>
#include <stdlib.h>
#include <stddef.h>

/* ---------- BST definition ---------- */
typedef struct BstNode {
    int                data;
    struct BstNode    *lchild;
    struct BstNode    *rchild;
} BstNode;

/* Allocate a new node */
static BstNode *GetNewNode(int data)
{
    BstNode *n = malloc(sizeof *n);
    if (!n) {
        perror("malloc");
        exit(EXIT_FAILURE);
    }
    n->data = data;
    n->lchild = n->rchild = NULL;
    return n;
}

/* Insert value – returns the (possibly new) subtree root */
static BstNode *Insert(BstNode *root, int data)
{
    if (root == NULL)
        return GetNewNode(data);

    if (data < root->data)
