    else if (data > root->data)
        root->rchild = Insert(root->rchild, data);
    /* else: duplicate – ignore */
    return root;
}

/* Free the whole tree */
static void FreeTree(BstNode *root)
{
    if (!root) return;
    FreeTree(root->lchild);
    FreeTree(root->rchild);
    free(root);
