        exit(EXIT_FAILURE);
    }
    n->data = node;
    n->next = NULL;
    q->tail->next = n;
    q->tail = n;
    ++q->size;
}

static BstNode *Pop(BiTQueue *q)
{
    if (q->size == 0)
        return NULL;
    QNode *first = q->head->next;          /* first real element */
    BstNode *value = first->data;
    q->head->next = first->next;
    if (q->tail == first)                  /* popped last element */
        q->tail = q->head;
    free(first);
    --q->size;
    return value;
}

static void DestroyQueue(BiTQueue *q)
{
    while (q->size)
        Pop(q);
    free(q->head);
    free(q);
}

/* ---------- Level‑order traversal (print a single level) ---------- */
static void LevelOrderPrint(BstNode *root, int targetLevel)
{
    if (!root) return;
    BiTQueue *q = InitQueue();
    Push(q, root);
    int currentLevel = 0;

    while (q->size) {
        size_t nodesInLevel = q->size;      /* nodes belonging to this depth */
        for (size_t i = 0; i < nodesInLevel; ++i) {
            BstNode *node = Pop(q);
            if (currentLevel == targetLevel)
