            if (node->lchild) Push(q, node->lchild);
            if (node->rchild) Push(q, node->rchild);
        }
        if (currentLevel == targetLevel) {
            printf("\n");
            break;          /* we have printed the requested level */
        }
        ++currentLevel;
    }
    DestroyQueue(q);
}

/* ---------- Main ---------- */
int main(void)
{
    BstNode *root = NULL;
    int cnt, level;

    if (scanf("%d", &cnt) != 1 || cnt < 0) {
