#define _GNU_SOURCE
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <openssl/sha.h>

#define MAX_LINE 256
#define UID_BUF_SIZE (SHA256_DIGEST_LENGTH * 2 + 1)

/* ------------------------------------------------------------------ */
/* 1) Чтение строки из файла, возвращает динамически выделенную строку   */
static char *read_file_line(const char *path, const char *prefix)
{
    FILE *f = fopen(path, "r");
    if (!f) {
        //fprintf(stderr, "Cannot open %s: %s\n", path, strerror(errno));
        return NULL;
    }

    char *result = NULL;
    char line[MAX_LINE];

    while (fgets(line, sizeof(line), f)) {
        if (prefix && strncmp(line, prefix, strlen(prefix)) == 0) {
            /* Отрезаем перевод строки и всё после ':' */
            char *p = strchr(line, ':');
            if (!p) continue;
            p++; /* за ':' */
            while (*p && (*p == ' ' || *p == '\t')) p++; /* пропуск пробелов */
            char *end = p + strlen(p);
            while (end > p && (end[-1] == '\n' || end[-1] == '\r')) end--;
            *end = '\0';
            result = strdup(p);
            break;
        }
    }

    fclose(f);
    return result;   /* NULL, если ничего не найдено */
}

/* ------------------------------------------------------------------ */
/* 2) Получение MAC‑адреса первого найденного сетевого интерфейса     */
static char *get_first_mac(void)
{
    /* Список типовых интерфейсов – можно расширить */
    const char *iface_names[] = { "eth0", "wlan0", "usb0", NULL };
    char path[128];
    char *mac = NULL;

    for (int i = 0; iface_names[i]; ++i) {
        snprintf(path, sizeof(path),
                 "/sys/class/net/%s/address", iface_names[i]);
        mac = read_file_line(path, NULL);
        if (mac && strlen(mac) == 17)   /* типичный формат xx:xx:xx:xx:xx:xx */
            break;
        free(mac);
        mac = NULL;
    }
    return mac;   /* NULL, если нет доступных интерфейсов */
}

/* ------------------------------------------------------------------ */
/* 3) Хеширование SHA‑256 и перевод в строку HEX                        */
static void sha256_hex(const unsigned char *data, size_t len, char out[UID_BUF_SIZE])
{
    unsigned char hash[SHA256_DIGEST_LENGTH];
    SHA256(data, len, hash);
    for (int i = 0; i < SHA256_DIGEST_LENGTH; ++i)
        sprintf(out + i * 2, "%02x", hash[i]);
    out[UID_BUF_SIZE - 1] = '\0';
}

/* ------------------------------------------------------------------ */
int main(void)
{
