    char *mac_addr = get_first_mac();

    /* 3) (Опционально) можно добавить ещё параметры, напр. UUID файловой системы */

    /* Формируем входную строку для хеширования */
    size_t buf_len = 0;
    if (cpu_serial) buf_len += strlen(cpu_serial);
    if (mac_addr)   buf_len += strlen(mac_addr);
    // можно добавить разделитель, но SHA‑256 уже устойчив к коллизиям при разных длинах

    unsigned char *buffer = malloc(buf_len + 1);
    if (!buffer) {
        perror("malloc");
        free(cpu_serial);
        free(mac_addr);
        return EXIT_FAILURE;
    }

    size_t pos = 0;
    if (cpu_serial) {
        memcpy(buffer + pos, cpu_serial, strlen(cpu_serial));
        pos += strlen(cpu_serial);
    }
    if (mac_addr) {
