**Secure C‑implementation of the linear system**

The task is to solve  

```
a·x + b·y = c
x – y     = d
```

for the four signed 64‑bit integers `a, b, c, d` that the user supplies.  
Below is a **security‑oriented** reference implementation written in pure C (C99).  

---

## 1.  What can go wrong?  (Security checklist)

| Threat | Why it matters | How we mitigate it |
|--------|----------------|--------------------|
| **Buffer overflow** when reading from stdin | Classic root‑cause of arbitrary code execution | Use `fgets()` + `strtoll()` – never `gets()` or unchecked `scanf("%d")`. |
| **Integer overflow** while computing `c + b*d` or `a + b` | Overflow can corrupt the result and, in some contexts, be exploited to bypass checks | Use `int64_t` and the GCC/Clang built‑ins `__builtin_mul_overflow` / `__builtin_add_overflow`. |
| **Division‑by‑zero** | Leads to undefined behaviour → crash → possible denial‑of‑service | Explicitly test denominator (`a+b`) before dividing. |
| **Invalid input format** | `strtoll()` may stop early, leaving garbage in the buffer | Verify the whole line is consumed and that the conversion succeeded. |
| **Information leakage** (e.g. printing internal error codes) | May help an attacker to infer the program state | Keep messages terse and user‑oriented; log details only to a protected debug channel. |
| **Unchecked return values** | Ignoring errors can propagate garbage values | Every system call / library call is checked. |

---

## 2.  Data structures

```c
/* Result of the system */
typedef enum {
    SOLV_SUCCESS,          /* unique solution */
    SOLV_NO_SOLUTION,      /* contradictory equations */
    SOLV_INFINITE,         /* infinitely many solutions */
    SOLV_ERROR_INPUT,      /* malformed user input */
    SOLV_ERROR_OVERFLOW    /* arithmetic overflow detected */
} sol_status_t;

typedef struct {
    double x;          /* solution value (valid when status == SOLV_SUCCESS) */
    double y;
    sol_status_t status;
} solution_t;
```

We return a `solution_t`.  Using `double` for `x`/`y` lets us represent fractional results without losing precision when the exact rational value is not an integer.  The status field tells the caller exactly what happened.

---

## 3.  Core solver (pure arithmetic, no I/O)

```c
#include <stdint.h>
#include <stdbool.h>
#include <stddef.h>
#include <math.h>

/* Helper: safe multiplication with overflow detection */
static bool safe_mul_int64(int64_t a, int64_t b, int64_t *out)
{
    return !__builtin_mul_overflow(a, b, out);
}

/* Helper: safe addition with overflow detection */
static bool safe_add_int64(int64_t a, int64_t b, int64_t *out)
{
    return !__builtin_add_overflow(a, b, out);
}

/* ------------------------------------------------------- */
/*  solve_system() – pure function, no side‑effects          */
/* ------------------------------------------------------- */
solution_t solve_system(int64_t a, int64_t b,
                        int64_t c, int64_t d)
{
    solution_t res = {0.0, 0.0, SOLV_ERROR_INPUT};

    /* 1. Compute denominator (a + b) safely */
    int64_t denom;                 /* = a + b */
    if (!safe_add_int64(a, b, &denom)) {
        res.status = SOLV_ERROR_OVERFLOW;
        return res;
    }

    /* 2. Special case: denominator == 0 */
    if (denom == 0) {
        /* Equation reduces to:  -b*d = c */
        int64_t left;
        if (!safe_mul_int64(-b, d, &left)) {
            res.status = SOLV_ERROR_OVERFLOW;
            return res;
        }
        if (left == c) {
            /* Any (x, y) that satisfies x - y = d works → infinite solutions */
            res.status = SOLV_INFINITE;
        } else {
            res.status = SOLV_NO_SOLUTION;
        }
        return res;
    }

    /* 3. Compute numerator = c + b*d safely */
    int64_t bd;
    if (!safe_mul_int64(b, d, &bd)) {
        res.status = SOLV_ERROR_OVERFLOW;
        return res;
    }
    int64_t numer;
    if (!safe_add_int64(c, bd, &numer)) {
        res.status = SOLV_ERROR_OVERFLOW;
        return res;
    }

    /* 4. Unique solution (use double division to keep fractional part) */
    res.x = (double)numer / (double)denom;   /* x = (c + b·d)/(a + b) */
    res.y = res.x - (double)d;               /* y = x - d   (from second equation) */
    res.status = SOLV_SUCCESS;
    return res;
}
```

*All arithmetic that could overflow is wrapped in the `safe_*` helpers.*  
If an overflow is detected we abort the computation and return `SOLV_ERROR_OVERFLOW`.

---

## 4.  Secure I/O wrapper

```c
#include <stdio.h>
#include <stdlib.h>
#include <inttypes.h>
#include <errno.h>
#include <string.h>

#define LINE_MAX 128   /* enough for four 64‑bit numbers and whitespace */

/* Prompt the user and read a single 64‑bit signed integer.
   Returns true on success, false on any error (including overflow). */
static bool read_int64(const char *prompt, int64_t *out)
{
    char line[LINE_MAX];
    char *endptr;

    while (1) {
        printf("%s", prompt);
        fflush(stdout);               /* make sure prompt appears immediately */

        if (!fgets(line, sizeof(line), stdin)) {
            fprintf(stderr, "Input error (EOF or read failure).\n");
            return false;
        }

        /* Strip trailing newline */
        line[strcspn(line, "\n")] = '\0';

        errno = 0;
        *out = strtoll(line, &endptr, 10);

        /* Validate conversion */
        if (errno == ERANGE) {
            fprintf(stderr, "Number out of range for 64‑bit signed integer.\n");
            continue;
        }
        if (endptr == line || *endptr != '\0') {
            fprintf(stderr, "Invalid number – please enter a decimal integer.\n");
            continue;
        }
        /* Success */
        return true;
    }
}

/* ------------------------------------------------------- */
/*  main() – orchestrates safe input → solver → output     */
/* ------------------------------------------------------- */
int main(void)
{
    int64_t a, b, c, d;

    if (!read_int64("Enter a: ", &a)) return EXIT_FAILURE;
    if (!read_int64("Enter b: ", &b)) return EXIT_FAILURE;
    if (!read_int64("Enter c: ", &c)) return EXIT_FAILURE;
    if (!read_int64("Enter d: ", &d)) return EXIT_FAILURE;

    solution_t sol = solve_system(a, b, c, d);

    switch (sol.status) {
        case SOLV_SUCCESS:
            printf("Unique solution:\n");
            printf("   x = %.12g\n", sol.x);
            printf("   y = %.12g\n", sol.y);
            break;
        case SOLV_INFINITE:
            printf("The system has infinitely many solutions (any (x,y) with x‑y = %"
                   PRId64 ").\n", d);
            break;
        case SOLV_NO_SOLUTION:
            printf("The system is inconsistent – no solution exists.\n");
            break;
        case SOLV_ERROR_OVERFLOW:
            printf("Arithmetic overflow detected while processing the input.\n");
            break;
        case SOLV_ERROR_INPUT:
        default:
            /* Should never happen because we validate input before calling solver */
            printf("Unexpected error.\n");
            break;
    }

    return EXIT_SUCCESS;
}
```

### Why this I/O is “secure”

* **No `scanf("%lld")`** – `scanf` stops at the first malformed character and can leave the rest of the line in the input buffer, leading to surprising behaviour.  
* **`fgets` + `strtoll`** – guarantees we never write past the buffer; `strtoll` gives us precise overflow detection via `errno == ERANGE`.  
* **Explicit limits** – `LINE_MAX` prevents a maliciously long line from overflowing the stack.  
* **All return values are checked** – any failure aborts the program gracefully with an explanatory message, avoiding undefined behaviour.

---

## 5.  Compilation & testing

