## 4）完整可编译代码（汇总）

```cpp
#include <iostream>
#include <cstring>
using namespace std;

/*=============================================================
   基类 CGoods
==============================================================*/
class CGoods
{
protected:
    long   no;
    char  *p_name;
    double price;
    static int count;                 // 商品总数

public:
    CGoods(long no_val, const char *p_val, double price_val)
        : no(no_val), price(price_val)
    {
        size_t len = strlen(p_val) + 1;
        p_name = new char[len];
        strcpy(p_name, p_val);
        ++count;
    }

    CGoods(const CGoods &g)
        : no(g.no), price(g.price)
    {
        size_t len = strlen(g.p_name) + 1;
        p_name = new char[len];
        strcpy(p_name, g.p_name);
        ++count;
    }

    virtual ~CGoods()
    {
        delete [] p_name;
        --count;
    }

    virtual void print() const
    {
        cout << "No   = " << no << endl
             << "Name = " << p_name << endl
             << "Price= " << price << endl;
    }

    static int getCount() { return count; }

    friend void getName(const CGoods &g);

    bool operator<(const CGoods &rhs) const  { return price <  rhs.price; }
    bool operator>=(const CGoods &rhs) const { return price >= rhs.price; }

    virtual void usedFor() const = 0;   // 纯虚，强制派生类实现
};

int CGoods::count = 0;

void getName(const CGoods &g)
{
    cout << "商品名称: " << g.p_name << endl;
}

/*=============================================================
   派生类 CClothes（服装）
==============================================================*/
class CClothes : public CGoods
{
private:
    char *p_brand;
public:
    CClothes(long no_val, const char *p_val, double price_val,
             const char *brand_val)
        : CGoods(no_val, p_val, price_val)
    {
        size_t len = strlen(brand_val) + 1;
        p_brand = new char[len];
        strcpy(p_brand, brand_val);
    }

    CClothes(const CClothes &c)
        : CGoods(c)
    {
        size_t len = strlen(c.p_brand) + 1;
        p_brand = new char[len];
        strcpy(p_brand, c.p_brand);
    }

    ~CClothes() override
    {
        delete [] p_brand;
    }

    void print() const override
    {
        CGoods::print();
        cout << "Brand= " << p_brand << endl;
    }

    void usedFor() const override
    {
        cout << "这是服装，用于穿戴、保暖或时尚展示。" << endl;
    }
};

/*=============================================================
   派生类 CFood（食品）
==============================================================*/
class CFood : public CGoods
{
private:
    char *p_brand;
public:
    CFood(long no_val, const char *p_val, double price_val,
          const char *brand_val)
        : CGoods(no_val, p_val, price_val)
    {
        size_t len = strlen(brand_val) + 1;
        p_brand = new char[len];
        strcpy(p_brand, brand_val);
    }

    CFood(const CFood &f)
        : CGoods(f)
    {
        size_t len = strlen(f.p_brand) + 1;
        p_brand = new char[len];
        strcpy(p_brand, f.p_brand);
    }

    ~CFood() override
    {
        delete [] p_brand;
    }

    void print() const override
    {
        CGoods::print();
        cout << "Brand= " << p_brand << endl;
    }

    void usedFor() const override
    {
        cout << "这是食品，用于日常摄入营养、补充能量。" << endl;
    }
};

/*=============================================================
   主函数：演示所有功能
==============================================================*/
int main()
{
    CGoods *g1 = new CClothes(1001, "长袖衬衫", 199.9, "优衣库");
    CGoods *g2 = new CFood   (2001, "牛奶",      45.5, "伊利");

    cout << "=== 打印商品信息 ===\n";
    g1->print();
    cout << endl;
    g2->print();
    cout << endl;

    cout << "=== 商品总数 === " << CGoods::getCount() << endl << endl;

    cout << "=== 友元函数获取名称 ===\n";
    getName(*g1);
    getName(*g2);
    cout << endl;

    cout << "=== 运算符比较（按价格） ===\n";
    if (*g1 < *g2)  cout << "g1 的价格低于 g2\n";
    else            cout << "g1 的价格不低于 g2\n";
    cout << endl;

    cout << "=== 多态调用 usedFor() ===\n";
    g1->usedFor();
    g2->usedFor();
    cout << endl;

    /* 复制构造（深拷贝）验证 */
    CClothes copyCloth(*static_cast<CClothes*>(g1));
    cout << "=== 复制构造后打印（深拷贝） ===\n";
    copyCloth.print();
    cout << endl;

    delete g1;
    delete g2;

    cout << "=== 删除后商品总数 === " << CGoods::getCount() << endl;
    return 0;
}
```

**要点回顾**

1. **深拷贝**：所有 `char*` 成员在构造、复制构造里都使用 `new[]` 与 `strcpy`，避免悬挂指针/双重释放。  
2. **Rule of Three**（或 Rule of Five）已在每个类实现：构造、拷贝构造、析构。  
3. **静态计数** `count` 通过构造/析构自动维护，实现第 2 步的 “商品总数”。  
4. **友元函数** `getName` 能直接访问私有字段 `p_name`。  
5. **运算符重载** 使用 `price` 进行比较。  
6. **多态**：基类声明 `virtual void usedFor() const = 0;`（纯虚），并把析构函数设为 `virtual`，保证 `CGoods*` 删除时调用派生类析构。  
7. **主函数** 通过 `CGoods*`（基类指针）调用 `print()`、`usedFor()`，完美展示 **运行时多态**。

这样，全部 5 项需求均已在代码中得到完整实现，且符合现代 C++（C++11 及以后）安全与资源管理的最佳实践。祝编码愉快！

