### 4.1. Utilitários de fila (uso interno)

```c
static int filaCheia(const Livro *l) {
    return l->qtd == MAX_FILA;
}

static int filaVazia(const Livro *l) {
    return l->qtd == 0;
}

/* Insere na fila (FIFO). */
static void enfileirar(Livro *l, const char *nome, const char *tel) {
    if (filaCheia(l)) {
        printf(">>> ERRO: fila de espera do livro \"%s\" está cheia!\n", l->nome);
        return;
    }
    strncpy(l->fila[l->tras].pessoa, nome, TAM_NOME-1);
    strncpy(l->fila[l->tras].telefone, tel, TAM_TELEFONE-1);
    l->tras = (l->tras + 1) % MAX_FILA;
    l->qtd++;
}

/* Remove o primeiro da fila e devolve os dados. */
static void desenfileirar(Livro *l, char *nome, char *tel) {
    if (filaVazia(l)) {
        nome[0] = '\0';
        tel[0]  = '\0';
        return;
    }
    strncpy(nome, l->fila[l->frente].pessoa, TAM_NOME-1);
    strncpy(tel,  l->fila[l->frente].telefone, TAM_TELEFONE-1);
    l->frente = (l->frente + 1) % MAX_FILA;
    l->qtd--;
}
```

