        printf(">>> O livro \"%s\" já está marcado como disponível.\n", acervo[idx].nome);
        return;
    }

    /* Marca como disponível */
    acervo[idx].disponivel = 1;
    printf("Livro \"%s\" devolvido com sucesso.\n", acervo[idx].nome);

    /* Se houver alguém na fila, empresta imediatamente ao 1.º */
    if (!filaVazia(&acervo[idx])) {
