 *  over‑flows and reports errors with a clear exit status.
 ********************************************************************/

#define _POSIX_C_SOURCE 200809L   /* for getline() etc. */
#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <errno.h>

typedef struct {
    int min_req;
    int incr;
} Station;

/* ---------- comparator helpers ---------- */

/* Ascending by min_req (used for positive‑increment stations) */
static int cmp_min_req_asc(const void *a, const void *b)
{
    const Station *sa = (const Station *)a;
    const Station *sb = (const Station *)b;
    return (sa->min_req > sb->min_req) - (sa->min_req < sb->min_req);
}

/* Descending by min_req (used for negative‑increment stations) */
static int cmp_min_req_desc(const void *a, const void *b)
{
    const Station *sa = (const Station *)a;
    const Station *sb = (const Station *)b;
    return (sb->min_req > sa->min_req) - (sb->min_req < sa->min_req);
}

/* ---------- core algorithm ---------- */
static bool can_survive(const Station *pos, size_t pos_cnt,
                        const Station *neg, size_t neg_cnt,
                        int64_t init_oxygen)
{
    int64_t oxygen = init_oxygen;

    /* Positive stations – ascending min_req */
    for (size_t i = 0; i < pos_cnt; ++i) {
        if (oxygen < pos[i].min_req) {
            return false;               /* cannot enter this station */
        }
        oxygen += pos[i].incr;           /* incr >= 0, no overflow risk */
    }

    /* Negative stations – descending min_req */
    for (size_t i = 0; i < neg_cnt; ++i) {
        if (oxygen < neg[i].min_req) {
            return false;
        }
        oxygen += neg[i].incr;           /* incr < 0, could drop below 0 */
        if (oxygen < 0) {
            return false;               /* you ran out of oxygen */
        }
    }
    return true;
}

/* ---------- safe input helpers ---------- */
static bool read_int(int *out)
{
    int r = scanf("%d", out);
    if (r != 1) {
        return false;
    }
    return true;
}

/* ---------- main ---------- */
int main(void)
{
    int n = 0;
    int init_oxygen = 0;

    /* -------------------------------------------------
       1. Validate the two initial numbers.
          We impose an arbitrary but reasonable ceiling
          on n (e.g. 1 000 000) to keep memory bounded.
       ------------------------------------------------- */
    if (!read_int(&n) || !read_int(&init_oxygen)) {
        fprintf(stderr, "Invalid input (expected two integers).\n");
        return EXIT_FAILURE;
    }
    if (n < 0) {
        fprintf(stderr, "Number of stations cannot be negative.\n");
        return EXIT_FAILURE;
    }
    const int MAX_N = 1000000;
    if (n > MAX_N) {
        fprintf(stderr, "Station count exceeds safe limit (%d).\n", MAX_N);
        return EXIT_FAILURE;
    }

    /* -------------------------------------------------
       2. Allocate the three arrays (min_req, incr, stations)
          using malloc.  All allocations are checked.
       ------------------------------------------------- */
    int *min_req = calloc((size_t)n, sizeof(int));
    int *incr    = calloc((size_t)n, sizeof(int));
    if (!min_req || !incr) {
        perror("calloc");
        free(min_req);
        free(incr);
        return EXIT_FAILURE;
    }

    for (int i = 0; i < n; ++i) {
        if (!read_int(&min_req[i])) {
            fprintf(stderr, "Failed reading min_req[%d]\n", i);
            goto cleanup;
        }
    }
    for (int i = 0; i < n; ++i) {
        if (!read_int(&incr[i])) {
            fprintf(stderr, "Failed reading incr[%d]\n", i);
            goto cleanup;
        }
    }

    /* -------------------------------------------------
       3. Partition into positive / negative lists.
          We allocate two buffers sized to n (worst case)
          and keep a running count for each.
       ------------------------------------------------- */
    Station *pos = malloc((size_t)n * sizeof(Station));
    Station *neg = malloc((size_t)n * sizeof(Station));
    if (!pos || !neg) {
        perror("malloc");
        goto cleanup;
    }
    size_t pos_cnt = 0, neg_cnt = 0;

    for (int i = 0; i < n; ++i) {
        if (incr[i] >= 0) {
            pos[pos_cnt].min_req = min_req[i];
            pos[pos_cnt].incr    = incr[i];
            ++pos_cnt;
        } else {
            neg[neg_cnt].min_req = min_req[i];
            neg[neg_cnt].incr    = incr[i];
            ++neg_cnt;
        }
    }

    /* -------------------------------------------------
       4. Sort with the correct comparators.
       ------------------------------------------------- */
    qsort(pos, pos_cnt, sizeof(Station), cmp_min_req_asc);
    qsort(neg, neg_cnt, sizeof(Station), cmp_min_req_desc);

    /* -------------------------------------------------
       5. Run the greedy simulation.
       ------------------------------------------------- */
    bool ok = can_survive(pos, pos_cnt, neg, neg_cnt, (int64_t)init_oxygen);
    puts(ok ? "YES" : "NO");

    /* -------------------------------------------------
       6. Clean up.
       ------------------------------------------------- */
    free(pos);
    free(neg);
cleanup:
    free(min_req);
    free(incr);
    return EXIT_SUCCESS;
}
```

### What changed?

| Change | Why it matters (security) |
|--------|----------------------------|
| **Separate comparators** (`cmp_min_req_asc` / `cmp_min_req_desc`) | Guarantees the ordering you actually need: `min_req` ascending for positives, descending for negatives. |
| **Dynamic allocation (`malloc`/`calloc`)** | Removes the VLA‑on‑stack problem; the program will now fail cleanly with `ENOMEM` instead of crashing the process. |
| **Input validation & limits (`MAX_N`)** | Prevents a maliciously large `n` from exhausting memory or stack space. |
| **`int64_t` for oxygen arithmetic** | Shields the computation from 32‑bit overflow; a wrap‑around can no longer be used to bypass “NO”. |
| **Error handling (`fprintf(stderr, …)`)** | Gives the operator a clear diagnostic instead of silently producing wrong results. |
| **Encapsulated `can_survive` function** | Easier to test under fuzzing / unit tests, reduces the chance of future bugs leaking into the main flow. |

