/*********************************************************************
 *  pull_cache.c   –   Pull‑based cache invalidation simulation
 *  -------------------------------------------------------------
 *  Author:  <your name>   (adapted for the question)
 *  Date  :  2024‑06
 *
 *  Requires:  CSIM‑20 (csim.c / csim.h)
 *
 *  Description
 *  -----------
 *  Implements the scheme described in the question (and in
 *  G. Cao, "A Scalable Low‑Latency Cache Invalidation Strategy for
 *  Mobile Environments", MOBICOM 2000).  A single server holds
 *  a database of DB_SIZE items.  Five clients each have a local
 *  LRU cache (CACHE_SIZE items).  Queries are generated according
 *  to an exponential distribution with mean T_query seconds.
 *  Server updates arrive with mean T_update seconds.
 *
 *  The experiment:
 *      * warm‑up period   = WARMUP_TIME   (30 min)
 *      * measurement time = MEASURE_TIME (30 min)
 *      * For each (T_query, T_update) the simulation is run once.
 *      * Statistics recorded: cache hit ratio and average query delay.
 *
 *  The program prints CSV lines that can be plotted later.
 *
 *********************************************************************/

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <math.h>
/* CSIM‑20 header – the simulator core */
#include "csim.h"

/* --------------------------------------------------------------
 *  Simulation parameters (constants) – you may change them.
 * -------------------------------------------------------------- */
#define NUM_CLIENTS      5
#define DB_SIZE          500          /* total items in the master DB   */
#define ITEM_SIZE_BITS   (1024 * 8)   /* each item is 1024 bytes = 8192 bits */
#define LINK_BW_BITSPS   10000        /* bandwidth of client–server link */
#define CACHE_SIZE       100          /* LRU cache capacity per client   */
#define HOT_START_ID     1
#define HOT_END_ID       50           /* items 1‑50 are hot                */
#define HOT_ACCESS_PROB  0.8          /* probability that a query hits hot  */
#define HOT_UPDATE_PROB  0.33         /* prob. that an update targets hot   */

#define WARMUP_TIME      (30*60.0)    /* 30 minutes in seconds              */
#define MEASURE_TIME     (30*60.0)    /* 30 minutes in seconds              */

/* Vectors of T_query and T_update values to sweep */
static const double T_query_vals[]  = {5, 10, 25, 50, 100};
static const double T_update_vals[] = {5, 10, 20, 100, 200};

/* --------------------------------------------------------------
 *  Data structures
 * -------------------------------------------------------------- */

/* --------------------------------------------------------------------
 *  LRU cache implementation (per client)
 * -------------------------------------------------------------------- */
typedef struct cache_entry {
    int  item_id;               /* database item identifier (1…DB_SIZE) */
    int  valid;                 /* 1 = up‑to‑date, 0 = stale              */
    struct cache_entry *prev;   /* doubly‑linked list for LRU ordering  */
    struct cache_entry *next;
} cache_entry_t;

typedef struct {
    cache_entry_t *head;        /* most‑recently used */
    cache_entry_t *tail;        /* least‑recently used  */
    int            count;       /* current number of items */
} lru_cache_t;

/* --------------------------------------------------------------------
 *  Global statistics (aggregated over all clients)
 * -------------------------------------------------------------------- */
static long   g_total_queries      = 0;
static long   g_cache_hits         = 0;
static double g_total_delay        = 0.0;   /* sum of (response – request) */

/* --------------------------------------------------------------------
 *  Event handles (used for tracing – optional)
 * -------------------------------------------------------------------- */
static Facility *fac_server;   /* the single server */
static Facility *fac_client[NUM_CLIENTS];

/* --------------------------------------------------------------------
 *  Helper functions for LRU cache
 * -------------------------------------------------------------------- */
static void lru_init(lru_cache_t *c)
{
    c->head = c->tail = NULL;
    c->count = 0;
}

/* move entry to head (most‑recently used) */
static void lru_move_to_head(lru_cache_t *c, cache_entry_t *e)
{
    if (c->head == e) return;               /* already at front */

    /* unlink */
    if (e->prev) e->prev->next = e->next;
    if (e->next) e->next->prev = e->prev;
    if (c->tail == e) c->tail = e->prev;

    /* insert at head */
    e->prev = NULL;
    e->next = c->head;
    if (c->head) c->head->prev = e;
    c->head = e;
    if (c->tail == NULL) c->tail = e;
}

/* find entry – linear search because cache is tiny (100) */
static cache_entry_t *lru_find(lru_cache_t *c, int item_id)
{
    cache_entry_t *cur = c->head;
    while (cur) {
        if (cur->item_id == item_id) return cur;
        cur = cur->next;
    }
    return NULL;
}

/* evict LRU (tail) if needed */
static void lru_evict_if_needed(lru_cache_t *c)
{
    if (c->count < CACHE_SIZE) return;
    /* remove tail */
    cache_entry_t *old = c->tail;
    if (old->prev) old->prev->next = NULL;
    c->tail = old->prev;
    if (c->tail == NULL) c->head = NULL;
    free(old);
    c->count--;
}

/* insert a fresh entry (assumed not present) */
static void lru_insert(lru_cache_t *c, int item_id, int valid)
{
    lru_evict_if_needed(c);
    cache_entry_t *e = (cache_entry_t*)malloc(sizeof(cache_entry_t));
    e->item_id = item_id;
    e->valid   = valid;
    e->prev = NULL;
    e->next = c->head;
    if (c->head) c->head->prev = e;
    c->head = e;
    if (c->tail == NULL) c->tail = e;
    c->count++;
}

/* --------------------------------------------------------------------
 *  Random utilities – CSIM already provides exponential()
 * -------------------------------------------------------------------- */
static int pick_item()
{
    double p = random();          /* uniform 0…1 (CSIM's random double) */
    if (p < HOT_ACCESS_PROB) {
        /* hot items */
        return HOT_START_ID + (int)(random() * (HOT_END_ID - HOT_START_ID + 1));
    } else {
        /* cold items */
        return HOT_END_ID + 1 + (int)(random() *
                 (DB_SIZE - HOT_END_ID));
    }
}

/* --------------------------------------------------------------------
 *  Server process
 * -------------------------------------------------------------------- */
static void server_process()
{
    for (;;) {
        /* wait for a request from any client */
        int client_id = request(fac_server);
        int msg_type = (int) getmsg();   /* 0 = REQ, 1 = CHECK */
        int item_id = (int) getmsg();   /* data item id                */

        /* simulate transmission time of the reply */
        double tx_time = (double)ITEM_SIZE_BITS / LINK_BW_BITSPS;
        delay(tx_time);

        if (msg_type == 0) {               /* REQ – always send DATA */
            /* Reply DATA */
            reply(fac_server, client_id, (double)0, (void*)1);   /* 1 = DATA */
        } else {                           /* CHECK – maybe confirm   */
            /* Find out whether the item has been updated since the client cached it.
               In our model we keep a global version number per item. */
            int stale = (int)getmsg();    /* version mismatch flag passed via msg */
            if (stale) {
                reply(fac_server, client_id, (double)0, (void*)1);   /* DATA */
            } else {
                reply(fac_server, client_id, (double)0, (void*)2);   /* CONFIRM */
            }
        }
    }
}

/* --------------------------------------------------------------------
 *  Global data structures to keep the *latest* version number of each item.
 *  version 0 = initial version, incremented on each update.
 * -------------------------------------------------------------------- */
static int g_item_version[DB_SIZE + 1];   /* index 1..DB_SIZE */

/* --------------------------------------------------------------------
 *  Update generator (runs at the server)
 * -------------------------------------------------------------------- */
static void update_generator()
{
    for (;;) {
        delay(exponential(T_update_current));   /* T_update_current is set by outer loop */
        /* pick an item to update */
        int item = pick_item();                 /* same hot/cold probability as queries */
        g_item_version[item]++;                 /* bump version – all caches become stale */
    }
}

/* --------------------------------------------------------------------
 *  Client process – one per client
 * -------------------------------------------------------------------- */
static void client_process(int client_id)
{
    lru_cache_t cache;
    lru_init(&cache);

    for (;;) {
        /* -------------------------------------------------
         *  1) generate a query
         * ------------------------------------------------- */
        delay(exponential(T_query_current));    /* inter‑arrival time */
        double query_start = simtime;           /* time we issue the request */
        int item = pick_item();

        /* -------------------------------------------------
         *  2) See whether the item is in cache
         * ------------------------------------------------- */
        cache_entry_t *e = lru_find(&cache, item);
        int msg_type;           /* 0 = REQ, 1 = CHECK */
        if (e == NULL) {
            /* MISS – send REQ */
            msg_type = 0;
        } else {
            /* HIT – send CHECK */
            msg_type = 1;
        }

        /* -------------------------------------------------
         *  3) Build the message to the server
         * ------------------------------------------------- */
        request(fac_client[client_id]);               /* acquire the client facility */
        putmsg((double)msg_type);
        putmsg((double)item);
        if (msg_type == 1) {
            /* For CHECK we also give the server the version we have.
               The server will compare with its global version and set
               stale flag in the reply (see server_process()). */
            putmsg((double) e->valid ? 0 : 1);       /* 0 = up‑to‑date, 1 = stale */
        }
        /* send request and wait for reply */
        int server_reply = (int) wait(fac_server);
        release(fac_client[client_id]);               /* free the client facility */

        double query_end = simtime;          /* time of receiving the answer */
        double delay_this = query_end - query_start;

        /* -------------------------------------------------
         *  4) Process the reply
         * ------------------------------------------------- */
        if (msg_type == 0) {                 /* REQ – we definitely received DATA */
            /* Insert/replace entry in cache (now fresh) */
            if (e) {
                e->valid = 1;
                lru_move_to_head(&cache, e);
            } else {
                lru_insert(&cache, item, 1);
            }
            g_cache_hits++;                 /* REQ counts as a *miss* → do NOT increment hit */
        } else {
            /* CHECK – reply can be CONFIRM (2) or DATA (1) */
            if (server_reply == 2) {        /* CONFIRM – cache entry stays valid */
                g_cache_hits++;             /* this query was satisfied from cache */
                e->valid = 1;               /* still fresh */
                lru_move_to_head(&cache, e);
            } else {                         /* DATA – server sent the updated item */
                /* Replace entry with fresh data */
                e->valid = 1;
                lru_move_to_head(&cache, e);
            }
        }

        /* -------------------------------------------------
         *  5) Update global statistics
         * ------------------------------------------------- */
        g_total_queries++;
        g_total_delay += delay_this;
    }
}

/* --------------------------------------------------------------------
 *  Main driver – runs the matrix of experiments
 * -------------------------------------------------------------------- */
int main(void)
{
    /* ----- (optional) set a deterministic seed for reproducibility ----- */
    set_random_seed(12345);

    /* Prepare the server facility (single server) */
    fac_server = FACILITY("SERVER", 1, 0);
    for (int i = 0; i < NUM_CLIENTS; ++i)
        fac_client[i] = FACILITY("CLIENT", 1, 0);   /* each client is a separate facility */

    /* Initialize all item versions to 0 */
    for (int i = 1; i <= DB_SIZE; ++i) g_item_version[i] = 0;

    /* Print CSV header */
    printf("T_query,T_update,CacheHitRatio,AvgDelay\n");
    fflush(stdout);

    /* Loop over all parameter pairs */
    for (size_t iq = 0; iq < sizeof(T_query_vals)/sizeof(T_query_vals[0]); ++iq) {
        for (size_t iu = 0; iu < sizeof(T_update_vals)/sizeof(T_update_vals[0]); ++iu) {
            /* ---------------------------------------------------------
             *  Set the *current* mean values that the processes will read
             * --------------------------------------------------------- */
            T_query_current  = T_query_vals[iq];
            T_update_current = T_update_vals[iu];

            /* Reset global statistics */
            g_total_queries = 0;
            g_cache_hits    = 0;
            g_total_delay   = 0.0;

            /* ---------------------------------------------------------
             *  (Re)‑initialize the version array – no historic updates
             * --------------------------------------------------------- */
            for (int i = 1; i <= DB_SIZE; ++i) g_item_version[i] = 0;

            /* ---------------------------------------------------------
             *  Create processes
             * --------------------------------------------------------- */
            PROCESS *proc_server = CREATE("Server", server_process);
            PROCESS *proc_upd    = CREATE("Updater", update_generator);
            for (int c = 0; c < NUM_CLIENTS; ++c) {
                CREATE("Client", client_process, c);
            }

            /* ---------------------------------------------------------
             *  Run warm‑up phase (no statistics recorded)
             * --------------------------------------------------------- */
            run(WARMUP_TIME);
            /* Reset counters again – now we start measuring */
            g_total_queries = 0;
            g_cache_hits    = 0;
            g_total_delay   = 0.0;
            /* ---------------------------------------------------------
             *  Run measurement phase
             * --------------------------------------------------------- */
            run(MEASURE_TIME);

            /* ---------------------------------------------------------
             *  Stop all processes (CSIM does not provide a direct kill;
             *  we just let the simulator finish – the processes are in
             *  infinite loops but the simulation stops after the time
             *  limit, so they are harmless.)
             * --------------------------------------------------------- */

            /* ---------------------------------------------------------
             *  Compute results for this parameter pair
             * --------------------------------------------------------- */
            double hit_ratio = (g_total_queries > 0) ?
                               ((double)g_cache_hits / (double)g_total_queries) :
                               0.0;
            double avg_delay = (g_total_queries > 0) ?
                               (g_total_delay / (double)g_total_queries) :
                               0.0;

            printf("%.0f,%.0f,%.5f,%.5f\n",
                   T_query_current, T_update_current,
                   hit_ratio, avg_delay);
            fflush(stdout);
        }
    }
    return 0;
}

/* --------------------------------------------------------------------
 *  Global variables used by the processes – set by the outer loop.
 * -------------------------------------------------------------------- */
static double T_query_current  = 5.0;   /* mean query inter‑arrival time (seconds)   */
static double T_update_current = 5.0;   /* mean update inter‑arrival time (seconds)   */

