        scanf("%d", &row[j]);
}

/* Проверка, образует ли столбец j неубывающую последовательность */
int column_is_nondecreasing(int **a, int rows, int col)
{
    for (int i = 0; i < rows - 1; ++i)
        if (a[i][col] > a[i + 1][col])
            return 0;               // найдено нарушение
    return 1;                       // всё в порядке
}

/* Вывод результирующего массива.
   selected[] – индексы столбцов, которые попали в результат,
   sel_cnt   – их число.
*/
void print_result(int **a, int rows, int *selected, int sel_cnt)
{
    for (int k = 0; k < sel_cnt; ++k)               // по каждому выбранному столбцу
    {
        int col = selected[k];
        for (int i = 0; i < rows; ++i)              // выводим элементы столбца как строку
        {
