    int *first_row = (int *)malloc(m * sizeof(int));
    if (!first_row) return EXIT_FAILURE;

    read_row(first_row, m);

    int max_abs = 0;
    for (int j = 0; j < m; ++j) {
        int cur = abs(first_row[j]);
        if (cur > max_abs) max_abs = cur;
    }
    int rows = (max_abs == 0) ? 1 : max_abs;         // минимум – одна строка

    /* ---- выделяем память под весь двумерный массив ---- */
    int **a = (int **)malloc(rows * sizeof(int *));
    if (!a) { free(first_row); return EXIT_FAILURE; }

    for (int i = 0; i < rows; ++i)
        a[i] = (int *)malloc(m * sizeof(int));

    /* первая строка уже известна */
    for (int j = 0; j < m; ++j)
        a[0][j] = first_row[j];
