 * Для простоты поддерживаем: u, U, l, L, ul, UL, ll, LL, llu, LLU и т.п.
 */
static int is_hex_suffix_char(char c)
{
    return (c == 'u' || c == 'U' ||
            c == 'l' || c == 'L');
}

/* Возвращает 1, если в строке, начиная с *p, находится шестнадцатеричная
 * константа, и записывает её длину в *len. Иначе – 0. */
static int detect_hex_constant(const char *p, size_t *len)
{
    const char *start = p;

    /* 0x или 0X обязательны */
    if (p[0] != '0' || (p[1] != 'x' && p[1] != 'X'))
        return 0;
    p += 2;                                 /* пропускаем 0x */

