## 2. Common constants & helper utilities (both files include `common.h`)

```c
/* common.h – shared between client & server */
#ifndef COMMON_H
#define COMMON_H

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/ipc.h>
#include <sys/shm.h>
#include <sys/sem.h>
#include <errno.h>
#include <limits.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <pthread.h>

/* ----- IPC identifiers -------------------------------------------------- */
#define SERVER_KEY_PATH   "./server.key"   /* must exist, readable only by owner */
#define SERVER_PROJ_ID    1                /* ftok projection */
#define REPLY_PROJ_ID     2                /* second key for reply shm */

/* ----- Sizes ------------------------------------------------------------ */
#define MAX_CMD   1024      /* whole command line */
#define MAX_PATH  256       /* filename (no path traversal) */
#define MAX_DATA  4096      /* data part for a write request */
#define SHM_SIZE  (MAX_CMD) /* command segment is just a command string */

/* ----- Semaphore numbers (within a single semaphore set) ---------------- */
#define SEM_MUTEX     0   /* binary: protect command shm */
#define SEM_REQUEST   1   /* counting: client -> server (new request) */
#define SEM_RESPONSE  2   /* binary: server -> client (reply shm key ready) */
#define SEM_COUNT     3   /* total number of semaphores in the set */

/* ----- Convenient macros ------------------------------------------------- */
#define CHECK(x, msg)                     \
    do {                                  \
        if ((x) == -1) {                  \
            perror(msg);                 \
            exit(EXIT_FAILURE);          \
        }                                 \
    } while (0)

static inline int is_valid_filename(const char *name)
{
    /* reject absolute paths, "..", and excessively long names */
    if (strlen(name) == 0 || strlen(name) > MAX_PATH) return 0;
    if (strchr(name, '/')) return 0;                     /* no '/' allowed */
    if (strstr(name, "..")) return 0;                    /* no traversal */
    return 1;
}

/* Semaphore operation helpers */
static inline void sem_op(int semid, unsigned short sem_num, short delta)
{
    struct sembuf sb = { .sem_num = sem_num, .sem_op = delta, .sem_flg = 0 };
    CHECK(semop(semid, &sb, 1), "semop");
}

/* Wait (P) and Signal (V) wrappers */
static inline void sem_wait(int semid, unsigned short sem_num) { sem_op(semid, sem_num, -1); }
static inline void sem_signal(int semid, unsigned short sem_num){ sem_op(semid, sem_num,  1); }

#endif /* COMMON_H */
```

*Why do we keep the filename validation **in both processes**?*  
Even if a malicious client tries to bypass the check, the **server** still validates before touching the file system.

