## 3. Server (`server.c`)

```c
/*
 * server.c – command listener + worker threads.
 *
 * Build:   gcc -Wall -Wextra -pthread server.c -o server
 * Run:     ./server   (runs forever, ctrl‑C to stop)
 */

#define _XOPEN_SOURCE 700          /* for ftok */
#include "common.h"

static int shm_cmd_id = -1;   /* command segment */
static int sem_id     = -1;   /* semaphore set */
static char *shm_cmd   = NULL;/* attached address */
static volatile int keep_running = 1;

/* ---------- cleanup & signal handling ---------------------------------- */
static void cleanup(void)
{
    if (shm_cmd) {
        shmdt(shm_cmd);
        shm_cmd = NULL;
    }
    if (shm_cmd_id != -1) {
        shmctl(shm_cmd_id, IPC_RMID, NULL);
        shm_cmd_id = -1;
    }
    if (sem_id != -1) {
        semctl(sem_id, 0, IPC_RMID);
        sem_id = -1;
    }
    printf("\n[SERVER] Cleaned up IPC objects.\n");
}

static void sig_handler(int signo)
{
    (void)signo;
    keep_running = 0;
}

/* ---------- worker thread – handles a single READ request --------------- */
struct read_job {
    char filename[MAX_PATH];
    key_t reply_key;          /* the key that will be written back to client */
};

static void *read_worker(void *arg)
{
    struct read_job *job = arg;
    int fd = -1;
    int shmid_reply = -1;
    char *shm_reply = NULL;
    ssize_t nread;
    struct stat st;

    /* 1) open the file (inside ./data) */
    char path[PATH_MAX];
    snprintf(path, sizeof(path), "./data/%s", job->filename);

    fd = open(path, O_RDONLY);
    if (fd == -1) {
        perror("[SERVER][READ] open");
        goto out;
    }

    /* 2) create a *private* reply shared memory segment (size = file size) */
    if (fstat(fd, &st) == -1) {
        perror("[SERVER][READ] fstat");
        goto out;
    }
    if (st.st_size > MAX_DATA) {
        fprintf(stderr, "[SERVER][READ] file too large (> %d bytes)\n", MAX_DATA);
        goto out;
    }

    shmid_reply = shmget(job->reply_key, (size_t)st.st_size, IPC_CREAT | IPC_EXCL | 0600);
    if (shmid_reply == -1) {
        perror("[SERVER][READ] shmget(reply)");
        goto out;
    }

    shm_reply = shmat(shmid_reply, NULL, 0);
    if (shm_reply == (void*)-1) {
        perror("[SERVER][READ] shmat(reply)");
        goto out;
    }

    /* 3) copy file data into the reply shm */
    nread = read(fd, shm_reply, (size_t)st.st_size);
    if (nread != st.st_size) {
        perror("[SERVER][READ] read");
        goto out;
    }

    /* 4) signal client that reply shm key is ready (via old command seg) */
    /*   we reuse the command shm to write the integer key, then raise SEM_RESPONSE */
    snprintf(shm_cmd, SHM_SIZE, "%d", job->reply_key);
    sem_signal(sem_id, SEM_RESPONSE);

    printf("[SERVER][READ] Served file '%s' (size %zd) via key %d\n",
           job->filename, nread, job->reply_key);

out:
    if (fd != -1) close(fd);
    if (shm_reply && shm_reply != (void*)-1) shmdt(shm_reply);
    free(job);
    return NULL;
}

/* ---------- main server loop ------------------------------------------- */
int main(void)
{
    /* ---- 1) create the command shared memory -------------------------------- */
    key_t cmd_key = ftok(SERVER_KEY_PATH, SERVER_PROJ_ID);
    if (cmd_key == -1) {
        perror("ftok (server key)");
        exit(EXIT_FAILURE);
    }

    /* 0600 = owner read/write only – essential for security */
    shm_cmd_id = shmget(cmd_key, SHM_SIZE, IPC_CREAT | IPC_EXCL | 0600);
    CHECK(shm_cmd_id, "shmget (command)");

    shm_cmd = shmat(shm_cmd_id, NULL, 0);
    CHECK((intptr_t)shm_cmd, "shmat (command)");

    /* ---- 2) create the semaphore set ---------------------------------------- */
    sem_id = semget(cmd_key, SEM_COUNT, IPC_CREAT | IPC_EXCL | 0600);
    CHECK(sem_id, "semget");

    /* initialise: mutex = 1 (unlocked), request = 0, response = 0 */
    unsigned short init_vals[SEM_COUNT] = {1, 0, 0};
    CHECK(semctl(sem_id, 0, SETALL, init_vals), "semctl SETALL");

    /* ---- 3) install signal handlers ---------------------------------------- */
    struct sigaction sa = {.sa_handler = sig_handler, .sa_flags = 0};
    sigemptyset(&sa.sa_mask);
    sigaction(SIGINT,  &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);
    sigaction(SIGQUIT, &sa, NULL);

    printf("[SERVER] Ready (cmd shm id=%d, sem id=%d). PID=%d\n",
           shm_cmd_id, sem_id, getpid());

    /* ---- 4) main dispatch loop -------------------------------------------- */
    while (keep_running) {
        /* Wait for a request from any client */
        sem_wait(sem_id, SEM_REQUEST);   /* BLOCKING */

        /* Grab the command in an exclusive section */
        sem_wait(sem_id, SEM_MUTEX);
        char cmd_buf[MAX_CMD];
        strncpy(cmd_buf, shm_cmd, MAX_CMD);
        cmd_buf[MAX_CMD-1] = '\0';
        /* clear the command area for the next client */
        memset(shm_cmd, 0, SHM_SIZE);
        sem_signal(sem_id, SEM_MUTEX);   /* release mutex */

        /* ----------------------------------------------------------------- */
        /* Parse the command (read <file> | write <file> <data>)               */
        char *saveptr = NULL;
        char *tok = strtok_r(cmd_buf, " ", &saveptr);
        if (!tok) continue;   /* empty line – ignore */

        if (strcmp(tok, "read") == 0) {
            char *fname = strtok_r(NULL, " ", &saveptr);
            if (!fname || !is_valid_filename(fname)) {
                fprintf(stderr, "[SERVER] Invalid read filename.\n");
                continue;
            }

            /* allocate a **private** key for the reply shm */
            key_t reply_key = ftok(SERVER_KEY_PATH, REPLY_PROJ_ID + getpid() % 0xFFFF);
            if (reply_key == -1) {
                perror("[SERVER] ftok(reply)");
                continue;
            }

            /* spin off a worker thread – it will write the reply key back */
            struct read_job *job = malloc(sizeof(*job));
            if (!job) { perror("malloc"); continue; }
            strncpy(job->filename, fname, MAX_PATH);
            job->filename[MAX_PATH-1] = '\0';
            job->reply_key = reply_key;

            pthread_t th;
            if (pthread_create(&th, NULL, read_worker, job) != 0) {
                perror("[SERVER] pthread_create");
                free(job);
                continue;
            }
            pthread_detach(th);   /* we don't need to join */
        }
        else if (strcmp(tok, "write") == 0) {
            char *fname = strtok_r(NULL, " ", &saveptr);
            char *data = strtok_r(NULL, "", &saveptr);   /* rest of line */
            if (!fname || !data || !is_valid_filename(fname)) {
                fprintf(stderr, "[SERVER] Invalid write command.\n");
                continue;
            }

            /* write the data into ./data/<fname> (overwrite) */
            char path[PATH_MAX];
            snprintf(path, sizeof(path), "./data/%s", fname);
            int fd = open(path, O_WRONLY | O_CREAT | O_TRUNC, 0600);
            if (fd == -1) {
                perror("[SERVER][WRITE] open");
                continue;
            }

            size_t to_write = strnlen(data, MAX_DATA);
            if (write(fd, data, to_write) != (ssize_t)to_write) {
                perror("[SERVER][WRITE] write");
            } else {
                printf("[SERVER][WRITE] Wrote %zu bytes to %s\n", to_write, path);
            }
            close(fd);
        }
        else {
            fprintf(stderr, "[SERVER] Unknown command: %s\n", tok);
        }
        /* ---- end of command processing ----------------------------------- */
    }

    cleanup();
    return 0;
}
