#define _XOPEN_SOURCE 700
#include "common.h"

static int shm_cmd_id = -1;
static int sem_id = -1;
static char *shm_cmd = NULL;

/* ---------- cleanup ------------------------------------------------------ */
static void cleanup(void)
{
    if (shm_cmd) {
        shmdt(shm_cmd);
        shm_cmd = NULL;
    }
}

/* ---------- usage -------------------------------------------------------- */
static void usage(const char *prog)
{
    fprintf(stderr, "Usage: %s \"read <filename>\" | \"write <filename> <data>\"\n", prog);
    exit(EXIT_FAILURE);
}

/* ---------- main ---------------------------------------------------------- */
int main(int argc, char *argv[])
{
    if (argc != 2) usage(argv[0]);

    /* ---- 1) connect to the server's command shm & semaphore set ------------- */
    key_t cmd_key = ftok(SERVER_KEY_PATH, SERVER_PROJ_ID);
    if (cmd_key == -1) {
        perror("ftok");
        exit(EXIT_FAILURE);
    }

    shm_cmd_id = shmget(cmd_key, SHM_SIZE, 0600);        /* must already exist */
    if (shm_cmd_id == -1) {
        perror("shmget (command)");
        exit(EXIT_FAILURE);
    }
    shm_cmd = shmat(shm_cmd_id, NULL, 0);
    CHECK((intptr_t)shm_cmd, "shmat (command)");

    sem_id = semget(cmd_key, SEM_COUNT, 0600);
    if (sem_id == -1) {
        perror("semget");
        cleanup();
        exit(EXIT_FAILURE);
    }

    /* ---- 2) Validate the command line ------------------------------------- */
    char cmd_copy[MAX_CMD];
    strncpy(cmd_copy, argv[1], MAX_CMD);
    cmd_copy[MAX_CMD-1] = '\0';

    char *saveptr = NULL;
    char *tok = strtok_r(cmd_copy, " ", &saveptr);
    if (!tok) { usage(argv[0]); }

    int is_read = 0;
    if (strcmp(tok, "read") == 0) {
        is_read = 1;
        char *fname = strtok_r(NULL, " ", &saveptr);
        if (!fname || !is_valid_filename(fname)) {
            fprintf(stderr, "[CLIENT] Invalid filename for read.\n");
            cleanup();
            exit(EXIT_FAILURE);
        }
    }
    else if (strcmp(tok, "write") == 0) {
        char *fname = strtok_r(NULL, " ", &saveptr);
        char *data  = strtok_r(NULL, "", &saveptr);
        if (!fname || !data || !is_valid_filename(fname)) {
            fprintf(stderr, "[CLIENT] Invalid syntax for write.\n");
            cleanup();
            exit(EXIT_FAILURE);
        }
        /* data length is limited by MAX_CMD (already captured) */
    }
    else {
        fprintf(stderr, "[CLIENT] Unknown command: %s\n", tok);
        cleanup();
        exit(EXIT_FAILURE);
    }

    /* ---- 3) Acquire exclusive access to the command shm -------------------- */
    sem_wait(sem_id, SEM_MUTEX);      /* binary lock */
    /*  Ensure that no other client is holding the mutex – this is the "wait until there is no other writer/reader" part */
    /*  The server has already set the command area to zero after each request, */
    /*  but we also make sure the buffer is empty before we write.            */
    memset(shm_cmd, 0, SHM_SIZE);
    /* ---- 4) Write the full command string into the shared memory ----------- */
    strncpy(shm_cmd, argv[1], SHM_SIZE);
    shm_cmd[SHM_SIZE-1] = '\0';

    /* ---- 5) Signal the server that a request is ready ---------------------- */
    sem_signal(sem_id, SEM_REQUEST);
    /* Release the mutex – the server will lock it again before reading */
    sem_signal(sem_id, SEM_MUTEX);

    /* ---- 6) If it is a READ, wait for the response key --------------------- */
    if (is_read) {
        /* Block until server puts the reply key and raises SEM_RESPONSE */
        sem_wait(sem_id, SEM_RESPONSE);

        /* The reply key is stored as a decimal string in the command shm */
        char key_str[32];
        strncpy(key_str, shm_cmd, sizeof(key_str)-1);
        key_str[31] = '\0';
        key_t reply_key = (key_t)strtol(key_str, NULL, 10);
        if (reply_key == (key_t)-1) {
            fprintf(stderr, "[CLIENT] Invalid reply key received.\n");
            cleanup();
            exit(EXIT_FAILURE);
        }

        /* Attach to the reply shared memory – we do not know the size, so we try a safe max */
        int shmid_reply = shmget(reply_key, MAX_DATA, 0600);
        if (shmid_reply == -1) {
            perror("[CLIENT] shmget(reply)");
            cleanup();
            exit(EXIT_FAILURE);
        }
        char *shm_reply = shmat(shmid_reply, NULL, SHM_RDONLY);
        if (shm_reply == (void*)-1) {
            perror("[CLIENT] shmat(reply)");
            cleanup();
            exit(EXIT_FAILURE);
        }

        /* Print the received file content */
        printf("%s\n", shm_reply);

        /* Clean up the reply segment (client is the owner of this temporary object) */
        shmdt(shm_reply);
        shmctl(shmid_reply, IPC_RMID, NULL);
    }
    else {
        /* WRITE command – we can simply exit after the request has been queued */
        printf("[CLIENT] Write request queued.\n");
    }

    cleanup();
    return 0;
}
