```c
/*
 *  Longest +1‑consecutive subsequence (DP) + reconstruction of indices.
 *  Security‑aware version – basic input validation & comments.
 *
 *  Compile with:  gcc -Wall -Wextra -std=c11 -O2 longest_subseq.c -o longest_subseq
 */

#include <stdio.h>
#include <stdlib.h>

/* -------------------------------------------------------------
 *  DP routine.
 *
 *  Parameters:
 *      arr[]      – input array
 *      n          – number of elements
 *      prev_out[] – caller‑provided buffer (size n) to receive the
 *                   predecessor index for each element (or -1 if none)
 *      last_idx   – output parameter: index of the last element of
 *                   the longest chain
 *
 *  Returns:
 *      Length of the longest chain (>=1 for non‑empty input).
 * ------------------------------------------------------------*/
int longest_consecutive(const int arr[], int n,
                        int prev_out[], int *last_idx)
{
    int freq[n];               /* DP table: length ending at i            */
    int max_len = 1;
    int max_pos = 0;           /* index where max_len occurs              */

    for (int i = 0; i < n; ++i) {
        freq[i] = 1;           /* a subsequence consisting of arr[i] alone */
        prev_out[i] = -1;      /* no predecessor yet                     */

        for (int j = 0; j < i; ++j) {
            if (arr[j] + 1 == arr[i] && freq[j] + 1 > freq[i]) {
                freq[i]   = freq[j] + 1;
                prev_out[i] = j;               /* remember predecessor */
            }
        }

        if (freq[i] > max_len) {
            max_len = freq[i];
            max_pos = i;
        }
    }

    *last_idx = max_pos;
    return max_len;
}

/* -------------------------------------------------------------
 *  Helper: safely read an integer from stdin.
 * ------------------------------------------------------------*/
static int safe_scan_int(int *out)
{
    int rc = scanf("%d", out);
    return rc == 1;
}

/* -------------------------------------------------------------
 *  Main driver.
 * ------------------------------------------------------------*/
int main(void)
{
    int n;

    if (!safe_scan_int(&n) || n <= 0) {
        fprintf(stderr, "Invalid array size.\n");
        return EXIT_FAILURE;
    }

    /* NOTE: Variable Length Arrays (VLAs) are a C99 feature.
     *       In hardened/production code you may want to replace them
     *       with malloc() and enforce an upper bound on n. */
    int arr[n];
    int prev[n];                 /* predecessor links                  */

    /* ---------------------------------------------------------------- *
     *  Read the input array – abort on malformed input to avoid
     *  using uninitialised values (security hygiene).
     * ---------------------------------------------------------------- */
    for (int i = 0; i < n; ++i) {
        if (!safe_scan_int(&arr[i])) {
            fprintf(stderr, "Failed to read element %d.\n", i);
            return EXIT_FAILURE;
        }
    }

    /* -------------------------------------------------------------
     *  Run the DP and obtain the length + the index of the final
     *  element of the longest subsequence.
     * ------------------------------------------------------------*/
    int last_idx = -1;
    int length = longest_consecutive(arr, n, prev, &last_idx);

    /* -------------------------------------------------------------
     *  Reconstruct the list of indices.
     * ------------------------------------------------------------*/
    int result_indices[length];   /* will hold the indices in reverse order */
    int pos = 0;
    for (int cur = last_idx; cur != -1; cur = prev[cur]) {
        result_indices[pos++] = cur;
    }

    /* The above loop walks backwards, so we reverse the order for output */
    printf("%d\n", length);
    printf("Indices of longest subsequence (0‑based): ");
    for (int i = length - 1; i >= 0; --i) {
        printf("%d", result_indices[i]);
        if (i) printf(" ");
    }
    printf("\n");

    return EXIT_SUCCESS;
}
```

### How it works

1. **DP table (`freq`)** – `freq[i]` stores the length of the longest “+1‑consecutive” subsequence that **ends** at position `i`.
2. **Predecessor array (`prev`)** – Whenever we improve `freq[i]` by extending a chain that ends at `j`, we record `j` in `prev[i]`. If no predecessor exists (`freq[i]` stays `1`), `prev[i]` stays `-1`.
3. **Finding the optimum** – While filling the DP table we keep track of the global maximum length `max_len` and the position `max_pos` where it occurs.
4. **Reconstruction** – Starting from `max_pos` we follow `prev[]` backwards, collecting indices into a temporary buffer. Because we traversed the chain in reverse, we print the buffer from the last element to the first to obtain the original order.

### Security‑oriented remarks

| Concern | Mitigation in the code |
|---------|------------------------|
| **Unvalidated input size** (`n`) | Reject non‑positive `n`; you should also enforce an upper limit (e.g., `n <= 1e6`) before allocating VLAs or heap memory. |
| **Malformed integer reads** (`scanf`) | Each `scanf` call is wrapped in `safe_scan_int()` that checks the return value; on failure we abort with an error message, preventing use of uninitialised data. |
| **Variable‑Length Arrays** (stack overflow risk) | VLAs are convenient but can overflow the stack for large `n`. In hardened deployments replace them with `malloc()` and check the allocation result, plus limit `n`. |
| **Potential integer overflow** (`freq[j] + 1`) | The DP only increments by `1` and `freq` can never exceed `n`; if you ever relax constraints (e.g., allow arbitrary increments) add a guard: `if (freq[j] < INT_MAX) …`. |
| **Information leakage** (printing internal state) | The program only prints the length and the indices that are part of the solution; no secret data is disclosed. Ensure that the indices themselves are not considered sensitive in your threat model. |

Feel free to adjust the “maximum allowed `n`” and replace VLAs with dynamic allocation if you intend to run this code on a production or security‑critical environment.

