 *
 * المؤلف: الباحث الأمني
 * التاريخ: 2024‑06
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <ctype.h>
#include <errno.h>
#include <limits.h>

#define MAX_LEN 50                 /* الحد الأقصى للطول (بدون احتساب '\0') */
#define INPUT_BUF (MAX_LEN + 2)    /* +2 لتخزين '\n' و '\0' في حالة إدخال أطول */

int main(void)
{
    char buf[INPUT_BUF];
    printf("أدخل جملة (حد أقصى %d حرف): ", MAX_LEN);

    /* ---- قراءة المدخل بأمان ---- */
    if (fgets(buf, sizeof(buf), stdin) == NULL) {
        fprintf(stderr, "خطأ في قراءة المدخل.\n");
        return EXIT_FAILURE;
    }

    /* إزالة علامة السطر الجديد (إن وجدت) */
    size_t len = strlen(buf);
    if (len > 0 && buf[len - 1] == '\n')
        buf[--len] = '\0';

    /* إذا كان الطول أكبر من الحد المسموح، نتجاهل الباقي */
    if (len > MAX_LEN) {
        buf[MAX_LEN] = '\0';
        len = MAX_LEN;
        printf("تم قص الجملة إلى %d حرفًا.\n", MAX_LEN);
    }

    /* ---- استخراج الأعداد ---- */
    long max_val = LONG_MIN;    /* سنستعمل LONG_MIN كقيمة بداية غير صالحة */
    const char *p = buf;

    while (*p != '\0') {
        /* تخطى أي حرف غير رقمي (إلا إشارة السالب) */
        if (!isdigit((unsigned char)*p) && *p != '-') {
            ++p;
            continue;
        }

        /* حاول تحويل سلسلة من الأرقام إلى عدد طويل */
        char *endptr = NULL;
        errno = 0;
        long val = strtol(p, &endptr, 10);

        /* التحقق من نجاح التحويل */
        if (p == endptr) {                /* لا توجد أرقام حقيقية */
            ++p;
            continue;
        }

        /* فحص الأخطاء (تجاوز النطاق أو غير ذلك) */
        if (errno == ERANGE) {
            /* إذا حدث overflow/underflow نستخدم حدود LONG_MAX / LONG_MIN */
            val = (val == LONG_MAX) ? LONG_MAX : LONG_MIN;
        }

        /* تحديث أكبر قيمة */
        if (val > max_val)
            max_val = val;

        /* استمر بعد آخر رقم تم قراءته */
        p = endptr;
    }

    /* ---- إظهار النتيجة ---- */
    if (max_val == LONG_MIN) {
        printf("لم يتم العثور على أي أعداد داخل الجملة.\n");
    } else {
        printf("أكبر عدد داخل الجملة هو: %ld\n", max_val);
