static bit   playing       = 0;   // 播放中 (不與 song_playing 混淆)
static bit   paused        = 0;   // 播放暫停
static bit   record_mode   = 0;   // 鍵入時自動錄製

/* -----------------------------------------------------------
   下面的函式都放在 main() 之前，保持程式結構清晰
----------------------------------------------------------- */
```

### 2.2 兩個工具函式

```c
/* -----------------------------------------------------------
   delay10us() – 您的程式已提供 `delay_10us()`，這裡
   包裝成更易讀的名稱，返回毫秒級延遲
----------------------------------------------------------- */
static void delay_ms(unsigned int ms)
{
    while (ms--) delay_10us(100);   // 100 * 10us = 1ms
}

/* -----------------------------------------------------------
   set_timer_for_freq() – 計算 Timer‑0 初值（與您原始
   代碼相同），同時保證原子性（關中斷）
----------------------------------------------------------- */
static void set_timer_for_freq(unsigned int f)
{
    unsigned int val;
    unsigned char hi, lo;

    if (f == 0) {               // 靜音 – 直接關閉方波
        song_playing = 0;
        return;
    }

    val = Clk / f;              // 計算週期
    val = 0xFFFF - val;         // 取補碼（Timer‑0 向上計數）

    hi = (val >> 8) & 0xFF;
    lo = val & 0xFF;

    // 計算過程與寫入計時器必須禁止中斷，避免 ISR 把舊值寫回
    EA = 0;                     // 關全局中斷
    val_H = hi;
    val_L = lo;
    TH0 = hi;
    TL0 = lo;
    EA = 1;                     // 重新開啟
}
```

### 2.3 鍵盤 → 音符映射與錄製邏輯

```c
/* -----------------------------------------------------------
   map_key_to_note() – 把鍵值映射到 freq[] 的索引。
   這裡僅使用 1~9、0、*、# (共 12 個鍵) 對應 12 個音階，
   其餘 A‑D 作為控制鍵，返回 0xFF 表示 “控制鍵”
----------------------------------------------------------- */
static signed char map_key_to_note(char key)
{
    // 我們假設 freq[] 前 12 個元素分別是 C4~B4（C 大調）
    // 0: C   1: D   2: E   3: F   4: G   5: A   6: B   7: C5 ...
    const signed char map[16] = {
        0,  // '1' → C4  (freq[0] = 262)
        1,  // '2' → D4
        2,  // '3' → E4
        3,  // 'A' → 控制鍵
        4,  // '4' → F4
        5,  // '5' → G4
        6,  // '6' → A4
        7,  // 'B' → 控制鍵
        8,  // '7' → B4
        9,  // '8' → C5
        10, // '9' → D5
        11, // 'C' → 控制鍵
        12, // '*' → 靜音 (NOTE_OFF) – 可作為 “休止符”
        0,  // '0' → 再次 C4（可自行改成其他音）
        13, // '#' → 控制鍵
        14  // 'D' → 控制鍵
    };

    // 把鍵字符轉為索引 (0‑15)
    unsigned char idx;
    switch (key) {
        case '1': idx = 0;  break;
        case '2': idx = 1;  break;
        case '3': idx = 2;  break;
        case 'A': idx = 3;  break;
        case '4': idx = 4;  break;
        case '5': idx = 5;  break;
        case '6': idx = 6;  break;
        case 'B': idx = 7;  break;
        case '7': idx = 8;  break;
        case '8': idx = 9;  break;
        case '9': idx = 10; break;
        case 'C': idx = 11; break;
        case '*': idx = 12; break;
        case '0': idx = 13; break;
        case '#': idx = 14; break;
        case 'D': idx = 15; break;
        default:  idx = 0xFF; break;   // 不會出現的字符
    }

    // 判斷是否為控制鍵
    if (idx >= 3 && (idx==3||idx==7||idx==11||idx==15))   // A B C D
        return -1;        // 控制鍵
    return map[idx];
}

/* -----------------------------------------------------------
   handle_keypress() – 主循環裡調用的核心函式
   1. 判斷是音符鍵還是控制鍵
   2. 若是音符鍵 → 立刻產生聲音、寫入緩衝區（如果在錄製模式）
   3. 若是控制鍵 → 依照規則切換播放/暫停/保存/清除/退出
----------------------------------------------------------- */
static void handle_keypress(char key)
{
    signed char note_idx = map_key_to_note(key);
    unsigned int freq_val;
    unsigned char beat_val = 5;   // 預設節拍（與您原 Delay(time_listX[i]) 的單位相同）

    /* ---------- 控制鍵處理 ---------- */
    if (note_idx == -1) {
        switch (key) {
            case 'A':   // 開始/暫停播放
                if (playing) {
                    if (paused) {
                        paused = 0;          // 恢復
                        song_playing = 1;
                    } else {
                        paused = 1;          // 暫停
                        song_playing = 0;
                    }
                } else if (music_length > 0) {
                    // 先前錄製過音樂，點 A 開始播放
                    playing = 1;
                    paused  = 0;
                    play_idx = 0;
                    song_playing = 1;    // 允許 ISR 產生方波
                }
                break;

            case 'B':   // 保存錄製的音樂 (只在錄製模式下有效)
                if (record_mode && music_length > 0) {
                    // 剛剛錄製的已經在緩衝區，這裡僅標誌「已保存」,
                    // 之後的播放會直接使用緩衝區內容。
                    // 若要把它寫入非易失性存儲(Flash/E2PROM)，此處須調用相應API。
                }
                break;

            case 'C':   // 清空緩衝區，重新錄製
                music_length = 0;
                write_idx = 0;
                buffer_full = 0;
                record_mode = 1;        // 立即進入錄製狀態
                break;

            case 'D':   // 退出/停止播放，返回待命
                playing = 0;
                paused  = 0;
                song_playing = 0;       // 停止方波
                break;
        }
        return;
    }

    /* ---------- 音符鍵處理 ---------- */
    // 取得音高 (freq[] 項)
    freq_val = freq[(unsigned char)note_idx];   // 0 表示 “靜音”

    // 立即把頻率寫入 Timer0，使 ISR 能產生相應方波
    set_timer_for_freq(freq_val);
    song_playing = (freq_val != 0);   // 若 freq==0 (靜音) 則關閉方波

    // 一個「音符」的持續時間由 `beat_val` 决定（此處簡化為固定值）
    delay_ms(beat_val * 100);        // 100ms 為一拍，可自行調整

    // 停止方波（讓間隔聽起來像音符分離）
    song_playing = 0;

    // 若當前處於錄製狀態，寫入緩衝區
    if (record_mode && !buffer_full) {
        music_buffer[write_idx] = (unsigned char)note_idx;   // 保存音高索引
        beat_buffer[write_idx] = beat_val;                  // 保存節拍
        write_idx++;
        music_length = write_idx;
        if (write_idx >= MAX_NOTES) {
            buffer_full = 1;   // 已滿，阻止再寫入
            record_mode = 0;   // 自動退出錄製（防止溢位）
        }
    }
}

/* -----------------------------------------------------------
   播放緩衝區的核心函式 – 只在 playing && !paused 時被調用
   循環讀取 `music_buffer` → `beat_buffer` → 設定 Timer → 延遲節拍
----------------------------------------------------------- */
static void playback_step(void)
{
    unsigned char note_idx;
    unsigned int freq_val;
    unsigned char beat_val;

    if (!playing || paused) return;   // 確保不在非播放狀態呼叫

    note_idx = music_buffer[play_idx];
    beat_val = beat_buffer[play_idx];
    freq_val = freq[note_idx];

    set_timer_for_freq(freq_val);
    song_playing = (freq_val != 0);
    delay_ms(beat_val * 100);
    song_playing = 0;      // 關閉方波

    // 前進指標，若已到結尾則自動回到開頭（重複播放）
    play_idx++;
    if (play_idx >= music_length) {
        play_idx = 0;      // 循環
    }
}
