```c
/* 原子寫入 timer 值（避免 ISR 把舊值寫回） */
static void set_timer_for_freq(unsigned int f)
{
    unsigned int val;
    unsigned char hi, lo;

    EA = 0;                     // 1️⃣ 關中斷，保證原子性
    if (f == 0) {
        song_playing = 0;
        EA = 1;
        return;
    }

    val = Clk / f;
    val = 0xFFFF - val;
    hi = (val >> 8) & 0xFF;
    lo = val & 0xFF;

    val_H = hi;      // 若有其他 ISR 讀取，這裡同樣受保護
    val_L = lo;
    TH0 = hi;
    TL0 = lo;
    EA = 1;          // 2️⃣ 重新開啟中斷
}

/* 安全寫入緩衝區 */
static void buffer_put(unsigned char note_idx, unsigned char beat)
{
    if (buffer_full) return;                // 已滿不寫
    if (write_idx >= MAX_NOTES) {
        buffer_full = 1;
        record_mode = 0;
        return;
    }
    music_buffer[write_idx] = note_idx;
    beat_buffer[write_idx] = beat;
    ++write_idx;
    music_length = write_idx;
}

/* 去彈跳 (在主循環中) */
static char get_key_debounced(void)
{
    char k = matrix_keypad_scan();
    if (k) {
        delay_ms(DEBOUNCE_MS);
        // 再次確認仍然是相同按鍵
        if (matrix_keypad_scan() == k) return k;
    }
    return 0;
}
```

