    TOK_OPERATOR,
    TOK_FUNCTION,
    TOK_LEFT_PAREN,
    TOK_RIGHT_PAREN,
    TOK_COMMA
} token_type_t;

typedef struct {
    token_type_t type;
    char        str[32];          /* textual representation          */
    double      value;            /* for numbers                     */
} token_t;

/* -------------------------------------------------------------
 *  Operator description
 * ------------------------------------------------------------- */
