    char   symbol;
    int    precedence;            /* higher number → higher priority */
    int    right_assoc;           /* 1 = right‑associative (^) */
} op_desc_t;

static const op_desc_t ops[] = {
    {'+', 2, 0},
    {'-', 2, 0},
    {'*', 3, 0},
    {'/', 3, 0},
    {'^', 4, 1},
    {'\0',0,0}                     /* sentinel */
};

/* -------------------------------------------------------------
 *  Function description (case‑insensitive)
 * ------------------------------------------------------------- */
typedef struct {
    const char *name;
    double (*func)(double);
} func_desc_t;

static const func_desc_t funcs[] = {
    {"sin",  sin},
    {"cos",  cos},
    {"tan",  tan},
    {"log",  log},
    {"exp",  exp},
    {"sqrt", sqrt},
    {NULL,   NULL}
};

/* -------------------------------------------------------------
 *  Helper utilities (bounded string handling)
 * ------------------------------------------------------------- */
static int is_operator_char(char c) {
    for (int i = 0; ops[i].symbol; ++i)
        if (ops[i].symbol == c) return 1;
    return 0;
}

static const op_desc_t* get_op_desc(char c) {
    for (int i = 0; ops[i].symbol; ++i)
        if (ops[i].symbol == c) return &ops[i];
    return NULL;
}

/* Return function pointer or NULL if not a supported function */
static const func_desc_t* get_func_desc(const char *name) {
    for (int i = 0; funcs[i].name; ++i)
        if (strcasecmp(funcs[i].name, name) == 0)
            return &funcs[i];
    return NULL;
}

/* -------------------------------------------------------------
 *  Tokenizer – converts a raw string into an array of tokens
 * ------------------------------------------------------------- */
static int tokenize(const char *expr, token_t *out, int *out_len) {
    int pos = 0, len = 0;
    const char *p = expr;

    while (*p) {
        /* Skip whitespace */
        if (isspace((unsigned char)*p)) { ++p; continue; }

        /* Number (integer or floating point) */
        if (isdigit((unsigned char)*p) || *p == '.') {
