            out[len].str[i] = '\0';
            out[len].type = TOK_FUNCTION;   /* will be validated later */
            ++len;
            p += i;
            continue;
        }

        /* Parentheses and commas */
        if (*p == '(') { out[len].type = TOK_LEFT_PAREN;  out[len].str[0] = '('; out[len].str[1] = '\0'; ++len; ++p; continue; }
        if (*p == ')') { out[len].type = TOK_RIGHT_PAREN; out[len].str[0] = ')'; out[len].str[1] = '\0'; ++len; ++p; continue; }
        if (*p == ',') { out[len].type = TOK_COMMA;       out[len].str[0] = ','; out[len].str[1] = '\0'; ++len; ++p; continue; }

