/* -------------------------------------------------------------
 *  Shunting‑yard – infix → RPN (postfix) conversion
 * ------------------------------------------------------------- */
static int shunting_yard(const token_t *in, int in_len,
                         token_t *out, int *out_len) {
    token_t op_stack[MAX_STACK];
    int    op_top = -1;
    int    out_pos = 0;

    for (int i = 0; i < in_len; ++i) {
        token_t cur = in[i];

        switch (cur.type) {
        case TOK_NUMBER:
            out[out_pos++] = cur;
            break;

        case TOK_FUNCTION:
            /* Validate function name now – prevents later surprises */
            if (!get_func_desc(cur.str)) {
                fprintf(stderr, "Error: unknown function \"%s\"\n", cur.str);
                return -1;
            }
            op_stack[++op_top] = cur;   /* push function */
            break;

        case TOK_COMMA:
            /* Pop operators until left parenthesis or stack empty */
            while (op_top >= 0 && op_stack[op_top].type != TOK_LEFT_PAREN) {
                out[out_pos++] = op_stack[op_top--];
            }
            if (op_top < 0) {
                fprintf(stderr, "Error: misplaced comma or mismatched parentheses\n");
                return -2;
            }
            break;

        case TOK_OPERATOR: {
            const op_desc_t *cur_op = get_op_desc(cur.str[0]);
            if (!cur_op) {
                fprintf(stderr, "Error: unknown operator \"%c\"\n", cur.str[0]);
                return -3;
            }

            /* Handle unary plus/minus: if previous token is
               none, left‑paren, operator, or comma → treat as unary. */
            int unary = 0;
