                } else {   /* unary '+' – no effect */
                    continue;
                }
                op_stack[++op_top] = fake_func;
                break;
            }

            /* Normal binary operator handling */
            while (op_top >= 0 && op_stack[op_top].type == TOK_OPERATOR) {
                const op_desc_t *top_op = get_op_desc(op_stack[op_top].str[0]);
                if (!top_op) break;  /* safety */

                if ((cur_op->right_assoc == 0 && cur_op->precedence <= top_op->precedence) ||
                    (cur_op->right_assoc == 1 && cur_op->precedence <  top_op->precedence)) {
                    out[out_pos++] = op_stack[op_top--];
                } else {
                    break;
                }
            }
            op_stack[++op_top] = cur;
            break;
        }

        case TOK_LEFT_PAREN:
            op_stack[++op_top] = cur;
            break;

        case TOK_RIGHT_PAREN:
            /* Pop until left parenthesis */
            while (op_top >= 0 && op_stack[op_top].type != TOK_LEFT_PAREN) {
                out[out_pos++] = op_stack[op_top--];
            }
            if (op_top < 0) {
                fprintf(stderr, "Error: mismatched parentheses\n");
                return -4;
            }
            /* Discard the '(' */
            --op_top;

            /* If top of stack is a function, pop it to output */
            if (op_top >= 0 && op_stack[op_top].type == TOK_FUNCTION) {
                out[out_pos++] = op_stack[op_top--];
            }
            break;
        }
    }

    /* Drain remaining operators */
    while (op_top >= 0) {
        if (op_stack[op_top].type == TOK_LEFT_PAREN ||
            op_stack[op_top].type == TOK_RIGHT_PAREN) {
            fprintf(stderr, "Error: mismatched parentheses at end of expression\n");
            return -5;
        }
        out[out_pos++] = op_stack[op_top--];
    }

    *out_len = out_pos;
    return 0;
}

/* -------------------------------------------------------------
 *  RPN evaluator
 * ------------------------------------------------------------- */
static double eval_rpn(const token_t *rpn, int rpn_len, int *err) {
    double stack[MAX_STACK];
    int    top = -1;
    *err = 0;

    for (int i = 0; i < rpn_len; ++i) {
        token_t t = rpn[i];
        if (t.type == TOK_NUMBER) {
            stack[++top] = t.value;
        } else if (t.type == TOK_OPERATOR) {
            if (top < 1) { *err = -1; return 0.0; }  /* not enough operands */
            double b = stack[top--];
            double a = stack[top--];
            double res = 0.0;
            switch (t.str[0]) {
            case '+': res = a + b; break;
            case '-': res = a - b; break;
            case '*': res = a * b; break;
            case '/':
                if (b == 0.0) { *err = -2; return 0.0; }
                res = a / b;
                break;
            case '^': res = pow(a, b); break;
            default:
                *err = -3; return 0.0;
            }
            stack[++top] = res;
        } else if (t.type == TOK_FUNCTION) {
            /* Built‑in functions take exactly one argument (except 'neg') */
            if (top < 0) { *err = -4; return 0.0; }
            double arg = stack[top--];
            double res = 0.0;

            if (strcasecmp(t.str, "neg") == 0) {
                res = -arg;
            } else {
                const func_desc_t *fd = get_func_desc(t.str);
                if (!fd) { *err = -5; return 0.0; }
                errno = 0;
                res = fd->func(arg);
                if (errno) { *err = -6; return 0.0; }
            }
            stack[++top] = res;
        } else {
            *err = -7;
            return 0.0;
        }
    }

    if (top != 0) { *err = -8; return 0.0; }
    return stack[0];
}

/* -------------------------------------------------------------
 *  Main entry point – read‑eval loop
 * ------------------------------------------------------------- */
int main(void) {
    char   line[MAX_BUF];
    token_t tokens[MAX_TOKENS];
    token_t rpn[MAX_TOKENS];
    int    n_tok, n_rpn;
    int    rc, eval_err;
    double result;

    printf("=== Complex Calculator (C) ===\n");
    printf("Enter an expression, or an empty line to quit.\n");

    while (1) {
        printf("\n> ");
