/*******************************************************************
 * Disk Scheduling Simulator
 *   - 支持三种调度算法：FCFS、SSTF、SCAN
 *   - 从键盘读取：
 *        * 磁盘请求序列（磁道号）
 *        * 初始磁头位置
 *        * 初始移动方向（0: left, 1: right）——仅对 SCAN 有效
 *   - 输出每种算法的调度顺序及平均寻道长度
 *
 * 编译（gcc）:
 *   gcc -Wall -Wextra -o disk_sched disk_sched.c
 *
 * 运行示例:
 *   ./disk_sched
 *
 * 作者: ChatGPT（2024）
 *******************************************************************/

#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>
#include <string.h>

#define MAX_REQUESTS 1000   // 最大请求数（可以自行调大）
#define MAX_CYLINDER 199    // 磁盘最大磁道号（示例范围 0~199）

/*---------------------------------------------------------------*/
/* 通用数据结构 */
typedef struct {
    int *seq;          // 调度顺序（磁道号）
    int  len;          // 调度序列长度
    long total_seek;   // 累计寻道距离
} ScheduleResult;

/*---------------------------------------------------------------*/
/* FCFS：先来先服务 */
ScheduleResult fcfs(const int *requests, int n, int head_start) {
    ScheduleResult res;
    res.seq = (int *)malloc((n + 1) * sizeof(int));
    res.len = n + 1;
    res.total_seek = 0;

    int cur = head_start;
    res.seq[0] = cur;                 // 起始位置放在序列第 0 位
    for (int i = 0; i < n; ++i) {
        int next = requests[i];
        res.seq[i + 1] = next;
        res.total_seek += abs(next - cur);
        cur = next;
    }
    return res;
}

/*---------------------------------------------------------------*/
/* SSTF：每次服务离当前磁头最近的请求 */
ScheduleResult sstf(const int *requests, int n, int head_start) {
    // 复制请求数组，以便标记已访问
    int *remain = (int *)malloc(n * sizeof(int));
    bool *served = (bool *)calloc(n, sizeof(bool));
    memcpy(remain, requests, n * sizeof(int));

    ScheduleResult res;
    res.seq = (int *)malloc((n + 1) * sizeof(int));
    res.len = n + 1;
    res.total_seek = 0;

    int cur = head_start;
    res.seq[0] = cur;

    for (int step = 0; step < n; ++step) {
        // 找到最近的未服务请求
        int min_dist = MAX_CYLINDER + 1;
        int min_idx  = -1;
        for (int i = 0; i < n; ++i) {
            if (!served[i]) {
                int dist = abs(remain[i] - cur);
                if (dist < min_dist) {
                    min_dist = dist;
                    min_idx  = i;
                }
            }
        }
        // 必然能找到（因为 step < n）
        int next = remain[min_idx];
        served[min_idx] = true;
        res.seq[step + 1] = next;
        res.total_seek += min_dist;
        cur = next;
    }

    free(remain);
    free(served);
    return res;
}

/*---------------------------------------------------------------*/
/* SCAN（电梯） */
ScheduleResult scan(const int *requests, int n,
                    int head_start, int direction) {
    // direction: 0 = left (decrease), 1 = right (increase)
    // 将请求复制并排序
    int *sorted = (int *)malloc(n * sizeof(int));
    memcpy(sorted, requests, n * sizeof(int));

    // 简单的插入排序（n ≤ 1000，足够快）
    for (int i = 1; i < n; ++i) {
        int key = sorted[i];
        int j = i - 1;
        while (j >= 0 && sorted[j] > key) {
            sorted[j + 1] = sorted[j];
            --j;
        }
        sorted[j + 1] = key;
    }

    // 将磁头当前位置插入到有序序列中，便于分割左右两侧
    int *all = (int *)malloc((n + 2) * sizeof(int)); // +head +end
    int cnt = 0;
    all[cnt++] = head_start;      // 第 0 位始终是起始位置

    // 统计左侧（<= head）和右侧（> head）的请求数目
    int left_cnt = 0, right_cnt = 0;
    for (int i = 0; i < n; ++i) {
        if (sorted[i] < head_start) {
            ++left_cnt;
        } else {
            ++right_cnt;
        }
    }

    // 拼接序列（先左后右或先右后左，取决于初始方向）
    // 为了实现“电梯到端点再调头”，我们在序列里显式加入磁道 0 或 MAX_CYLINDER
    ScheduleResult res;
    res.seq = (int *)malloc((n + 3) * sizeof(int)); // 多预留几个位置
    int pos = 0;   // index in res.seq
    int cur = head_start;
    res.total_seek = 0;
    res.seq[pos++] = cur;   // 第 0 位 = 起始位置

    if (direction == 1) { // 向右（增大）扫描
        // 1) 先服务所有 >= head 的请求（升序）
        for (int i = 0; i < n; ++i) {
            if (sorted[i] >= head_start) {
                res.seq[pos++] = sorted[i];
                res.total_seek += abs(sorted[i] - cur);
                cur = sorted[i];
            }
        }
        // 2) 到达磁道最右端 (MAX_CYLINDER)（如果已经在最右端则不必再走）
        if (cur != MAX_CYLINDER) {
            res.seq[pos++] = MAX_CYLINDER;
            res.total_seek += abs(MAX_CYLINDER - cur);
            cur = MAX_CYLINDER;
        }
        // 3) 调头向左，服务剩余的请求（降序）
        for (int i = n - 1; i >= 0; --i) {
            if (sorted[i] < head_start) {
                res.seq[pos++] = sorted[i];
                res.total_seek += abs(sorted[i] - cur);
                cur = sorted[i];
            }
        }
    } else { // 向左（减小）扫描
        // 1) 先服务所有 < head 的请求（降序）
        for (int i = n - 1; i >= 0; --i) {
            if (sorted[i] < head_start) {
                res.seq[pos++] = sorted[i];
                res.total_seek += abs(sorted[i] - cur);
                cur = sorted[i];
            }
        }
        // 2) 到达磁道最左端 (0)
        if (cur != 0) {
            res.seq[pos++] = 0;
            res.total_seek += abs(cur - 0);
            cur = 0;
        }
        // 3) 调头向右，服务剩余的请求（升序）
        for (int i = 0; i < n; ++i) {
            if (sorted[i] >= head_start) {
                res.seq[pos++] = sorted[i];
                res.total_seek += abs(sorted[i] - cur);
                cur = sorted[i];
            }
        }
    }

    res.len = pos; // 实际使用的长度
    free(sorted);
    free(all);
    return res;
}

/*---------------------------------------------------------------*/
/* 辅助函数：打印调度序列并计算平均寻道长度 */
void print_result(const char *name, const ScheduleResult *r) {
    printf("\n=== %s ===\n", name);
    printf("调度顺序: ");
    for (int i = 0; i < r->len; ++i) {
        if (i) printf(" -> ");
        printf("%d", r->seq[i]);
    }
    printf("\n");
    printf("总寻道长度: %ld\n", r->total_seek);
    double avg = (double)r->total_seek / (r->len - 1);
    printf("平均寻道长度: %.2f\n", avg);
}

/*---------------------------------------------------------------*/
/* 主函数 */
int main(void) {
    int n;                  // 请求数
    int head;               // 磁头起始位置
    int direction;          // 初始移动方向（仅对 SCAN 有效）

    printf("=== 磁盘调度模拟 ===\n");
    printf("磁道号范围: 0 ~ %d\n", MAX_CYLINDER);
    printf("请输入请求数 (max %d): ", MAX_REQUESTS);
    if (scanf("%d", &n) != 1 || n <= 0 || n > MAX_REQUESTS) {
        fprintf(stderr, "请求数非法！\n");
        return EXIT_FAILURE;
    }

    int *requests = (int *)malloc(n * sizeof(int));
    printf("请输入 %d 个磁道请求（用空格或回车分隔）:\n", n);
    for (int i = 0; i < n; ++i) {
        if (scanf("%d", &requests[i]) != 1) {
            fprintf(stderr, "读取请求失败！\n");
            free(requests);
            return EXIT_FAILURE;
        }
        if (requests[i] < 0 || requests[i] > MAX_CYLINDER) {
            fprintf(stderr, "磁道号必须在 0~%d 之间！\n", MAX_CYLINDER);
            free(requests);
            return EXIT_FAILURE;
        }
    }

    printf("请输入磁头起始位置 (0~%d): ", MAX_CYLINDER);
    if (scanf("%d", &head) != 1 || head < 0 || head > MAX_CYLINDER) {
        fprintf(stderr, "起始位置非法！\n");
        free(requests);
        return EXIT_FAILURE;
    }

    printf("请输入 SCAN 初始移动方向 (0=向左, 1=向右): ");
    if (scanf("%d", &direction) != 1 || (direction != 0 && direction != 1)) {
        fprintf(stderr, "方向只能是 0 或 1！\n");
        free(requests);
        return EXIT_FAILURE;
    }

    /* --------- 运行三种调度算法 ---------- */
    ScheduleResult r_fcfs = fcfs(requests, n, head);
    ScheduleResult r_sstf = sstf(requests, n, head);
    ScheduleResult r_scan = scan(requests, n, head, direction);

    print_result("FCFS (先来先服务)", &r_fcfs);
    print_result("SSTF (最短寻道时间优先)", &r_sstf);
    print_result("SCAN (电梯算法)", &r_scan);

    /* 释放内存 */
    free(requests);
    free(r_fcfs.seq);
    free(r_sstf.seq);
    free(r_scan.seq);
    return EXIT_SUCCESS;
}
```

