 *  作者: ChatGPT (安全研究员视角)
 *  日期: 2024-06
 ***********************************************************************/

#include <stdio.h>
#include <stdint.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>

/* 让结构体按照 1 字节对齐，防止编译器填充 */
#if defined(_MSC_VER)
#   pragma pack(push,1)
#elif defined(__GNUC__) || defined(__clang__)
#   define PACKED __attribute__((packed))
#else
#   error "Unsupported compiler"
#endif

/* BITMAPFILEHEADER - 14 字节 */
typedef struct {
    uint16_t bfType;      /* 必须是字符 "BM" = 0x4D42 */
    uint32_t bfSize;      /* 文件大小（字节） */
    uint16_t bfReserved1; /* 保留，设为 0 */
    uint16_t bfReserved2; /* 保留，设为 0 */
    uint32_t bfOffBits;   /* 像素数据起始偏移（字节），通常 = 54 */
} 
#if defined(PACKED)
PACKED
#endif
BITMAPFILEHEADER;

/* BITMAPINFOHEADER - 40 字节 */
typedef struct {
    uint32_t biSize;          /* 结构体大小 (=40) */
    int32_t  biWidth;         /* 图像宽度（像素） */
    int32_t  biHeight;        /* 图像高度（像素），正数表示自下而上 */
    uint16_t biPlanes;        /* 必须为 1 */
    uint16_t biBitCount;      /* 每像素位数: 24 */
    uint32_t biCompression;  /* 0 = BI_RGB（不压缩） */
    uint32_t biSizeImage;     /* 像素数据大小（字节），可以为 0（但我们填实际值) */
    int32_t  biXPelsPerMeter; /* 水平分辨率（像素/米），可设 0 */
    int32_t  biYPelsPerMeter; /* 垂直分辨率（像素/米），可设 0 */
    uint32_t biClrUsed;       /* 颜色表中实际使用的颜色数，24位设 0 */
    uint32_t biClrImportant; /* 重要颜色数，0 表示全部重要 */
}
#if defined(PACKED)
PACKED
#endif
BITMAPINFOHEADER;

#if defined(_MSC_VER)
#   pragma pack(pop)
#endif

/* ------------------------------------------------------------------ */
/* 计算每行实际占用的字节数（带 4 字节对齐）                         */
static size_t row_stride(size_t width, uint16_t bitsPerPixel)
{
    /* (bitsPerPixel * width + 31) / 32   →   单位为 4 字节 */
    size_t stride = ((bitsPerPixel * width + 31) / 32) * 4;
    return stride;
}

/* ------------------------------------------------------------------ */
/* 检查乘法是否会溢出（size_t）                                      */
static int safe_mul_size_t(size_t a, size_t b, size_t *out)
{
    if (a == 0 || b == 0) {
        *out = 0;
        return 0;
    }
    if (a > SIZE_MAX / b) {
        return -1;  /* 溢出 */
    }
    *out = a * b;
    return 0;
}

/* ------------------------------------------------------------------ */
/* BMP 写入核心函数
 * 参数:
 *      filename   - 输出文件名
 *      width      - 图像宽度（像素）
 *      height     - 图像高度（像素）
 *      pixelData  - 指向宽*高*3 字节的 RGB24 数据（行顺序自上而下）
 *      stride     - 输入像素行的字节跨度（一般 = width*3），若为 0 则按紧凑布局计算
 * 返回:
 *      0  成功
 *     -1  失败（errno 已设置）
 */
int write_bmp24(const char *filename,
                uint32_t width,
                uint32_t height,
                const uint8_t *pixelData,
                size_t stride /* 输入行跨度, 0 = width*3 */)
{
    if (!filename || !pixelData || width == 0 || height == 0) {
        errno = EINVAL;
        return -1;
    }

    /* 计算每行实际写入的字节数（4 字节对齐） */
    size_t outStride = row_stride(width, 24);   /* 24 位 = 3 字节/像素 */
    size_t imgSize;
    if (safe_mul_size_t(outStride, height, &imgSize) != 0) {
        errno = EOVERFLOW;
        return -1;
    }

    /* ---- 填充文件头 ------------------------------------------------ */
    BITMAPFILEHEADER fileHeader;
    memset(&fileHeader, 0, sizeof(fileHeader));
    fileHeader.bfType = 0x4D42;                      /* "BM" */
    fileHeader.bfOffBits = sizeof(BITMAPFILEHEADER) + sizeof(BITMAPINFOHEADER);
    /* 文件大小 = 头部 + 像素数据 */
    if (safe_mul_size_t(fileHeader.bfOffBits, (size_t)1, &fileHeader.bfSize) != 0 ||
        safe_mul_size_t(fileHeader.bfSize, (size_t)1, &fileHeader.bfSize) != 0) {
        errno = EOVERFLOW;
        return -1;
    }
    fileHeader.bfSize += (uint32_t)imgSize;

    /* ---- 填充信息头 ------------------------------------------------ */
    BITMAPINFOHEADER infoHeader;
    memset(&infoHeader, 0, sizeof(infoHeader));
    infoHeader.biSize = sizeof(BITMAPINFOHEADER);
    infoHeader.biWidth  = (int32_t)width;
    /* Windows BMP 的正数 height 表示“自下而上”存储（即第一行在文件末尾）。
       为了保持代码直观，这里使用负值，告诉 BMP 按“自上而下”写入。 */
    infoHeader.biHeight = -(int32_t)height;   /* 负号 → top‑down bitmap */
    infoHeader.biPlanes = 1;
    infoHeader.biBitCount = 24;               /* 24 bit RGB */
    infoHeader.biCompression = 0;             /* BI_RGB = 不压缩 */
    infoHeader.biSizeImage = (uint32_t)imgSize;
    infoHeader.biXPelsPerMeter = 0;
    infoHeader.biYPelsPerMeter = 0;
    infoHeader.biClrUsed = 0;
    infoHeader.biClrImportant = 0;

    /* ---- 打开文件并写头部 ------------------------------------------ */
    FILE *fp = fopen(filename, "wb");
    if (!fp) {
        return -1;       /* errno 由 fopen 设置 */
    }

    if (fwrite(&fileHeader, sizeof(fileHeader), 1, fp) != 1 ||
        fwrite(&infoHeader, sizeof(infoHeader), 1, fp) != 1) {
        fclose(fp);
        errno = EIO;
        return -1;
    }

    /* ---- 写像素数据 ------------------------------------------------ */
    /* 如果输入行跨度为 0，则我们认为像素是紧凑存放（width*3） */
    size_t inStride = (stride == 0) ? width * 3 : stride;

    /* 为每行补齐的 0 缓冲区（最多 3 字节） */
    uint8_t pad[3] = {0,0,0};
    size_t padSize = outStride - width * 3;   /* 0~3 */

    for (uint32_t y = 0; y < height; ++y) {
        const uint8_t *row = pixelData + y * inStride;

        /* BMP 24 bit 存储顺序是 BGR，而我们假设 pixelData 为 RGB */
        /* 为了不额外拷贝内存，这里在写入时临时翻转颜色顺序 */
        for (uint32_t x = 0; x < width; ++x) {
            uint8_t r = row[x * 3 + 0];
            uint8_t g = row[x * 3 + 1];
            uint8_t b = row[x * 3 + 2];
            uint8_t bgr[3] = { b, g, r };
            if (fwrite(bgr, 1, 3, fp) != 3) {
                fclose(fp);
                errno = EIO;
                return -1;
            }
        }

        /* 行尾填充 */
        if (padSize) {
            if (fwrite(pad, 1, padSize, fp) != padSize) {
                fclose(fp);
                errno = EIO;
                return -1;
            }
        }
    }

    /* ---- 完成 ------------------------------------------------------ */
    if (fflush(fp) != 0) {
        fclose(fp);
        errno = EIO;
        return -1;
    }
    fclose(fp);
    return 0;
}

/* ------------------------------------------------------------------ */
/* 示例：生成一个 256×256 的彩虹渐变图像 */
#ifdef DEMO_MAIN
int main(void)
{
    const uint32_t w = 256, h = 256;
    size_t bufSize;
    if (safe_mul_size_t(w, h, &bufSize) != 0 ||
        safe_mul_size_t(bufSize, (size_t)3, &bufSize) != 0) {
        fprintf(stderr, "图片尺寸太大，整数溢出！\n");
        return EXIT_FAILURE;
    }

    uint8_t *pixels = malloc(bufSize);
    if (!pixels) {
        perror("malloc");
        return EXIT_FAILURE;
    }

    /* 生成简单梯度：R = x, G = y, B = 128 */
    for (uint32_t y = 0; y < h; ++y) {
        for (uint32_t x = 0; x < w; ++x) {
            size_t idx = (y * w + x) * 3;
            pixels[idx + 0] = (uint8_t)x;       /* R */
            pixels[idx + 1] = (uint8_t)y;       /* G */
            pixels[idx + 2] = 128;              /* B */
        }
    }

    if (write_bmp24("demo.bmp", w, h, pixels, 0) != 0) {
        perror("write_bmp24");
        free(pixels);
        return EXIT_FAILURE;
    }

    printf("demo.bmp 已生成 (%ux%u)\n", w, h);
    free(pixels);
    return EXIT_SUCCESS;
}
#endif /* DEMO_MAIN */
```

### 代码要点解释

| 代码段 | 说明 |
|--------|------|
| `#pragma pack(1)` / `PACKED` | 强制结构体不填充，确保文件写出的字节序与 BMP 规范一致。 |
| `row_stride()` | 计算 **带对齐** 的每行字节数（4‑byte 对齐），防止 BMP 行错位。 |
| `safe_mul_size_t()` | 检测 `size_t` 乘法是否会溢出，避免 `malloc`/`bfSize` 产生错误的极大值。 |
| `bfOffBits`、`bfSize` | 正确填入像素数据在文件中的偏移以及整体文件大小。 |
| `infoHeader.biHeight = -(int32_t)height` | 使用 **Top‑Down BMP**（负 height），这样我们可以按从上到下的顺序写入像素，而不必把图像倒序写入。 |
| **RGB → BGR 转换** | BMP 24 bit 必须是 **BGR**，因此在写入每个像素时手动调换顺序，避免额外的临时缓冲区。 |
| **行填充** (`pad`) | 只在需要时写入 0~3 个字节，使每行字节数满足 4 的倍数。 |
| **错误检查** | 每一次 `fwrite`、`fflush`、`fopen` 返回值都检查，错误时 `errno` 已被设置，调用者可以据此定位问题。 |
| **示例代码 (`DEMO_MAIN`)** | 演示如何生成 256×256 的渐变图并保存为 `demo.bmp`。编译时加入 `-DDEMO_MAIN` 即可运行。 |

