/*  fibonacci.c
 *  Print the first N Fibonacci numbers.
 *
 *  Security‑focused clean‑room implementation:
 *  - Uses standard-compliant `int main(void)`.
 *  - Uses 64‑bit unsigned arithmetic to delay overflow.
 *  - Checks for overflow before performing the addition.
 *  - Removes dead code and stray semicolons.
 *  - Prints a newline after every 2 numbers for readability.
 */

#include <stdio.h>
#include <stdbool.h>
#include <stdint.h>
#include <inttypes.h>   /* PRIu64 macro for portable printing */

#define TERMS   20      /* Number of terms to display – change with care */
#define PER_LINE 2      /* How many numbers per line (for formatting) */

/* Helper that detects unsigned 64‑bit overflow of a + b.
 * Returns true if a + b would overflow, false otherwise.               */
static bool will_overflow_uint64(uint64_t a, uint64_t b)
{
    return a > UINT64_MAX - b;
}

int main(void)
{
    uint64_t f1 = 1, f2 = 1;          /* First two Fibonacci numbers */
    int i;

    printf("The Fibonacci sequence (first %d terms):\n", TERMS);

    for (i = 1; i <= TERMS; ++i) {
        /* Print the current pair – use PRIu64 for portability */
        printf("%12" PRIu64 " %12" PRIu64, f1, f2);

        /* Insert a newline after PER_LINE pairs for readability */
        if (i % PER_LINE == 0) {
            putchar('\n');
        }

        /* Compute the next two numbers safely.
         * The classic recurrence is:
         *   next = f1 + f2;
         *   f1 = f2;
         *   f2 = next;
         * Using a temporary variable avoids the “use‑after‑update” bug.    */
        if (will_overflow_uint64(f1, f2)) {
            fprintf(stderr,
                    "\n[!] Overflow detected after term %d – stopping.\n",
                    i);
            break;
        }

        uint64_t next = f1 + f2;
        f1 = f2;
        f2 = next;
    }

    /* If the loop ended without printing a trailing newline (e.g., odd PER_LINE) */
    if (TERMS % PER_LINE != 0) {
        putchar('\n');
    }

    return 0;
}
