static bool is_valid_date(const Date *d) {
    if (d->year < 1) return false;
    if (d->month < 1 || d->month > 12) return false;
    int dim = days_in_month(d->year, d->month);
    if (d->day < 1 || d->day > dim) return false;
    return true;
}

/* 规范化日期：处理溢出的日/月/年
 *   - day > days_in_month → month+1, day-=dim
 *   - day < 1          → month-1, day+=days_of_prev_month
 *   - month > 12       → year+1, month-=12
 *   - month < 1        → year-1, month+=12
 *   若年份降到 0 以下则报错（不可接受）。
 */
static bool normalize_date(Date *d) {
    if (d->year < 1) return false;  /* 负或零年份不合法 */

    /* 处理月份溢出/借位 */
    while (d->month > 12) {
        d->month -= 12;
        d->year += 1;
        if (d->year < 1) return false;
    }
    while (d->month < 1) {
        d->month += 12;
        d->year -= 1;
        if (d->year < 1) return false;
    }

    /* 处理天数溢出/借位 */
    while (1) {
        int dim = days_in_month(d->year, d->month);
        if (d->day > dim) {
            d->day -= dim;
            d->month += 1;
            if (d->month > 12) {
                d->month = 1;
                d->year += 1;
                if (d->year < 1) return false;
            }
            continue;
        }
        if (d->day < 1) {
            d->month -= 1;
            if (d->month < 1) {
                d->month = 12;
                d->year -= 1;
                if (d->year < 1) return false;
            }
            d->day += days_in_month(d->year, d->month);
            continue;
        }
        break;  /* day 在合法范围内 */
    }

    return true;
}

