/********************************************************************
 *  expr_last_operator.c
 *  ---------------------------------
 *  功能：读取一行中缀算术表达式（仅支持 + - * / % 和整数/字母），
 *        输出“最后被计算的运算符”。如果表达式里没有运算符，
 *        则输出 "none".
 *
 *  编译示例 (gcc):
 *      gcc -std=c11 -Wall -Wextra -O2 expr_last_operator.c -o expr_last_operator
 *
 *  运行示例:
 *      $ echo "3+4*(2-1)" | ./expr_last_operator
 *      *
 ********************************************************************/

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <ctype.h>
#include <stdbool.h>

/*** ---------- 结构体定义 ---------- ***/
typedef struct Node {
    bool is_op;               // true: 运算符节点； false: 叶子（操作数）
    char op;                  // 当 is_op 为 true 时有效
    struct Node *left;        // 左子树
    struct Node *right;       // 右子树
} Node;

/*** ---------- 栈实现（仅用于指针） ---------- ***/
typedef struct {
    Node **data;
    int   top;
    int   capacity;
} PtrStack;

static PtrStack *ptrstack_create(int cap) {
    PtrStack *s = malloc(sizeof(*s));
    if (!s) abort();
    s->data = malloc(sizeof(Node *) * cap);
    if (!s->data) abort();
    s->top = -1;
    s->capacity = cap;
    return s;
}
static void ptrstack_free(PtrStack *s) {
    free(s->data);
    free(s);
}
static inline bool ptrstack_empty(const PtrStack *s) { return s->top == -1; }
static inline void ptrstack_push(PtrStack *s, Node *v) {
    if (s->top + 1 >= s->capacity) {
        s->capacity *= 2;
        s->data = realloc(s->data, sizeof(Node *) * s->capacity);
        if (!s->data) abort();
    }
    s->data[++s->top] = v;
}
static inline Node *ptrstack_pop(PtrStack *s) {
    if (ptrstack_empty(s)) return NULL;
    return s->data[s->top--];
}
static inline Node *ptrstack_peek(const PtrStack *s) {
    if (ptrstack_empty(s)) return NULL;
    return s->data[s->top];
}

/*** ---------- 运算符优先级 ---------- ***/
static int precedence(char op) {
    switch (op) {
        case '*': case '/': case '%': return 2;
        case '+': case '-':          return 1;
        default:                     return 0;   // '(' 和非法字符
    }
}

/*** ---------- 创建节点 ---------- ***/
static Node *make_operand_node(char token) {
    Node *n = malloc(sizeof(*n));
    if (!n) abort();
    n->is_op = false;
    n->op    = token;   // 仅保存一次字符（数字或变量名），实际不使用
    n->left  = n->right = NULL;
    return n;
}
static Node *make_operator_node(char op, Node *l, Node *r) {
    Node *n = malloc(sizeof(*n));
    if (!n) abort();
    n->is_op = true;
    n->op    = op;
    n->left  = l;
    n->right = r;
    return n;
}

/*** ---------- 释放整棵树 ---------- ***/
static void free_tree(Node *root) {
    if (!root) return;
    free_tree(root->left);
    free_tree(root->right);
    free(root);
}

/*** ---------- 主算法：把中缀表达式转成 AST ---------- ***/
static Node *parse_to_ast(const char *expr) {
    PtrStack *ops = ptrstack_create(32);   // 运算符栈
    PtrStack *vals = ptrstack_create(32);  // 操作数/子树栈

    for (size_t i = 0; expr[i] != '\0'; ++i) {
        char c = expr[i];

        /* 忽略空白 */
        if (isspace((unsigned char)c)) continue;

        /* ① 数字/字母 → 叶子节点 */
        if (isdigit((unsigned char)c) || isalpha((unsigned char)c)) {
            ptrstack_push(vals, make_operand_node(c));
            continue;
        }

        /* ② '(' → 直接压栈 */
        if (c == '(') {
            ptrstack_push(ops, (Node *)(intptr_t)'(');   // 把字符强转为指针存
            continue;
        }

        /* ③ ')' → 把 '(' 之前的所有运算符弹出并归并 */
        if (c == ')') {
            while (!ptrstack_empty(ops) &&
                   (char)(intptr_t)ptrstack_peek(ops) != '(') {
                char op = (char)(intptr_t)ptrstack_pop(ops);
                Node *right = ptrstack_pop(vals);
                Node *left  = ptrstack_pop(vals);
                ptrstack_push(vals, make_operator_node(op, left, right));
            }
            /* 弹出 '(' 本身 */
            if (!ptrstack_empty(ops))
                ptrstack_pop(ops);
            else {
                fprintf(stderr, "Error: mismatched parentheses.\n");
                exit(EXIT_FAILURE);
            }
            continue;
        }

        /* ④ 普通运算符 (+-*/%) */
        if (strchr("+-*/%", c)) {
            while (!ptrstack_empty(ops)) {
                char topop = (char)(intptr_t)ptrstack_peek(ops);
                if (topop == '(') break;                 // '(' 不参与比较
                if (precedence(topop) >= precedence(c)) {
                    // 较高或相等优先级的运算符先归并
                    topop = (char)(intptr_t)ptrstack_pop(ops);
                    Node *right = ptrstack_pop(vals);
                    Node *left  = ptrstack_pop(vals);
                    ptrstack_push(vals, make_operator_node(topop, left, right));
                } else break;
            }
            ptrstack_push(ops, (Node *)(intptr_t)c);
            continue;
        }

        /* ⑤ 其他字符 → 报错 */
        fprintf(stderr, "Error: illegal character '%c' in expression.\n", c);
        exit(EXIT_FAILURE);
    }

    /* 处理剩余的运算符 */
    while (!ptrstack_empty(ops)) {
        char op = (char)(intptr_t)ptrstack_pop(ops);
        if (op == '(' || op == ')') {
            fprintf(stderr, "Error: mismatched parentheses.\n");
            exit(EXIT_FAILURE);
        }
        Node *right = ptrstack_pop(vals);
        Node *left  = ptrstack_pop(vals);
        ptrstack_push(vals, make_operator_node(op, left, right));
    }

    Node *ast = ptrstack_pop(vals);
    if (!ptrstack_empty(vals)) {
        fprintf(stderr, "Error: malformed expression (extra operands).\n");
        exit(EXIT_FAILURE);
    }

    ptrstack_free(ops);
    ptrstack_free(vals);
    return ast;          // 根节点
}

/*** ---------- 提取“最后被计算的运算符” ---------- ***/
static char get_last_operator(Node *root) {
    if (!root) return '\0';
    if (!root->is_op) return '\0';   // 纯操作数，没有运算符
    return root->op;                 // 根节点即为最后一次执行的运算符
}

/*** ---------- 主函数 ---------- ***/
int main(void) {
    char line[1024];

    /* 读取一行表达式（可以使用管道、文件重定向或交互式输入） */
    if (!fgets(line, sizeof(line), stdin)) {
        fprintf(stderr, "Error: failed to read input.\n");
        return EXIT_FAILURE;
    }

    /* 去掉行尾换行符 */
    line[strcspn(line, "\r\n")] = '\0';

    /* 空行直接退出 */
    if (line[0] == '\0') return 0;

    Node *ast = parse_to_ast(line);
    char last_op = get_last_operator(ast);

    if (last_op)
        printf("%c\n", last_op);
    else
        printf("none\n");   // 没有任何运算符（例如 "42"）

    free_tree(ast);
    return 0;
}
