/*********************************************************************
 *  sum_digits.c
 *
 *  Compute the sum of the decimal digits of an integer.
 *
 *  Security‑focused implementation:
 *    • No buffer overflows (fixed size buffer + fgets)
 *    • Input validation (only optional sign + digits)
 *    • Safe conversion to int64_t (range checking)
 *    • No undefined behaviour – use unsigned long long for the sum
 *
 *  Compile:
 *      gcc -Wall -Wextra -pedantic -std=c11 -o sum_digits sum_digits.c
 *
 *  Run:
 *      ./sum_digits
 *
 *********************************************************************/

#define _POSIX_C_SOURCE 200809L   /* for strtol on some platforms */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <ctype.h>
#include <errno.h>

#define INPUT_MAX 64          /* plenty for a 64‑bit signed integer */

static int is_valid_number(const char *s)
{
    /* Allow optional leading '+' or '-' then at least one digit */
    if (*s == '+' || *s == '-') s++;

    if (!isdigit((unsigned char)*s))
        return 0;               /* no digit after sign */

    while (*s) {
        if (!isdigit((unsigned char)*s))
            return 0;
        s++;
    }
    return 1;
}

/* Convert safely, reporting overflow/underflow */
static int64_t safe_str_to_int64(const char *s, int *ok)
{
    char *endptr = NULL;
    errno = 0;
    long long val = strtoll(s, &endptr, 10);

    if (errno == ERANGE) {
        *ok = 0;                 /* overflow / underflow */
        return 0;
    }
    if (endptr == s || *endptr != '\0') {
        *ok = 0;                 /* not a pure number */
        return 0;
    }
    *ok = 1;
    return (int64_t)val;
}

/* Compute sum of decimal digits. Works for negative numbers as well. */
static unsigned long long digit_sum(int64_t n)
{
    unsigned long long sum = 0ULL;
    uint64_t u = (n < 0) ? -(uint64_t)n : (uint64_t)n;   /* absolute value */

    while (u > 0) {
        sum += u % 10ULL;
        u   /= 10ULL;
    }
    return sum;          /* for n == 0 the loop is skipped → sum == 0 */
}

int main(void)
{
    char line[INPUT_MAX];
    printf("Enter an integer (decimal, up to 64‑bit signed): ");

    if (!fgets(line, sizeof(line), stdin)) {
        fprintf(stderr, "Error: failed to read input.\n");
        return EXIT_FAILURE;
    }

    /* Strip trailing newline, if present */
    line[strcspn(line, "\n")] = '\0';

    /* Validate characters */
    if (!is_valid_number(line)) {
        fprintf(stderr, "Error: input must be a valid integer.\n");
        return EXIT_FAILURE;
    }

    int ok = 0;
    int64_t value = safe_str_to_int64(line, &ok);
    if (!ok) {
        fprintf(stderr, "Error: number out of range for 64‑bit signed integer.\n");
        return EXIT_FAILURE;
    }

    unsigned long long result = digit_sum(value);
    printf("Sum of digits of %lld = %llu\n", (long long)value, result);
    return EXIT_SUCCESS;
}
```

### How the program works

1. **Read input safely** – `fgets()` reads at most `INPUT_MAX‑1` characters, guaranteeing no overflow.
2. **Validate characters** – `is_valid_number()` ensures only an optional sign followed by digits are present.
3. **Convert to a 64‑bit signed integer** – `strtoll()` is used with thorough error checking (`errno`, `endptr`, range detection).
4. **Calculate digit sum** – `digit_sum()` works on the absolute value of the number, using unsigned arithmetic to avoid signed overflow.
5. **Print the result** – The program reports the original number and the computed sum.

### Security notes for researchers

* **Input size limitation** – The buffer size (`INPUT_MAX`) is deliberately generous but finite. If you ever need to support arbitrarily large numbers, switch to a big‑integer library (e.g., GMP) and adjust validation accordingly.
* **Avoiding `printf` format string attacks** – All format strings are constant. User data (`line`) is never used as a format string.
* **No use of deprecated/unsafe functions** – Functions like `gets()`, `atoi()`, `scanf("%s")` without width specifiers are avoided.
* **Potential future hardening** – If the program were to be part of a larger service (e.g., a network daemon), you would also add:
  * Time‑outs for input,
  * Rate‑limiting,
  * Memory‑safe allocation (e.g., `calloc` and bounds checks),
  * Use of a sandbox (e.g., `seccomp` or containers) to limit impact of any unforeseen bug.

---

**Compile & run example**

```bash
$ gcc -Wall -Wextra -pedantic -std=c11 -o sum_digits sum_digits.c
$ ./sum_digits
Enter an integer (decimal, up to 64‑bit signed): -12345
