#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>

int cmp_int(const void *a, const void *b)
{
    int ai = *(const int *)a;
    int bi = *(const int *)b;
    return (ai > bi) - (ai < bi);
}

/* Returns the length of the longest consecutive set and writes its
   first element into *out_start. */
int longest_consecutive(int *a, int n, int *out_start)
{
    if (n == 0) return 0;

    /* Make a copy we can sort without destroying the original order */
    int *copy = malloc(n * sizeof(int));
    if (!copy) return -1;               // allocation failure
    for (int i = 0; i < n; ++i) copy[i] = a[i];
    qsort(copy, n, sizeof(int), cmp_int);

    int best_len = 1, cur_len = 1;
    int best_start = copy[0], cur_start = copy[0];

    for (int i = 1; i < n; ++i) {
        if (copy[i] == copy[i-1]) {
            /* Duplicate – ignore */
            continue;
        }
        if (copy[i] == copy[i-1] + 1) {
            cur_len++;
        } else {
            if (cur_len > best_len) {
                best_len = cur_len;
                best_start = cur_start;
            }
            cur_len = 1;
            cur_start = copy[i];
        }
    }
    if (cur_len > best_len) {
        best_len = cur_len;
        best_start = cur_start;
    }

    free(copy);
    *out_start = best_start;
    return best_len;
}
