## Complete Source (`election.c`)

```c
/*********************************************************************
 *  election.c
 *
 *  Reads a file "votes.txt" that contains:
 *     – a list of candidate names (one per line)
 *     – a line with the votes (numbers separated by blanks)
 *
 *  The program produces "resultats.txt" with the following data:
 *     • each invalid vote (value > number_of_candidates)
 *     • total number of voters
 *     • number of valid votes
 *     • number of cancelled (invalid) votes
 *     • score per candidate
 *     • list of winner(s) (candidate(s) with the highest score)
 *
 *  Security‑oriented implementation:
 *       • bounded I/O (fgets)
 *       • strict error checking
 *       • safe integer conversion (strtol)
 *       • no uncontrolled format strings
 *       • all resources are correctly released
 *
 *  Compile with:   gcc -Wall -Wextra -O2 -o election election.c
 *
 *  Author:  <your name>
 *  Date:    2024‑06‑xx
 *********************************************************************/

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <ctype.h>
#include <errno.h>

#define MAX_CANDIDATES  200           /* generous upper bound */
#define MAX_LINE        1024          /* max length of a line in the file */
#define MAX_NAME_LEN    100           /* max length of a candidate name */

/*---------------------------------------------------------------*/
/* Helper: trim trailing '\n' and '\r' from a string               */
static void trim_newline(char *s)
{
    size_t len = strlen(s);
    while (len && (s[len-1] == '\n' || s[len-1] == '\r')) {
        s[--len] = '\0';
    }
}

/*---------------------------------------------------------------*/
/* Helper: test whether a line starts with a digit               */
static int line_starts_with_digit(const char *s)
{
    while (*s && isspace((unsigned char)*s)) s++;   /* skip leading blanks */
    return isdigit((unsigned char)*s);
}

/*---------------------------------------------------------------*/
/* Main program                                                   */
int main(void)
{
    FILE *fin  = NULL;
    FILE *fout = NULL;
    char line[MAX_LINE];

    /* ----------------------------------------------------------------
       1. Open the input file (votes.txt) and the output file
       ---------------------------------------------------------------- */
    fin = fopen("votes.txt", "r");
    if (!fin) {
        perror("Error opening votes.txt");
        return EXIT_FAILURE;
    }

    fout = fopen("resultats.txt", "w");
    if (!fout) {
        perror("Error creating resultats.txt");
        fclose(fin);
        return EXIT_FAILURE;
    }

    /* ----------------------------------------------------------------
       2. Read candidate names
       ---------------------------------------------------------------- */
    char candidates[MAX_CANDIDATES][MAX_NAME_LEN];
    size_t nb_candidates = 0;

    while (fgets(line, sizeof(line), fin)) {
        trim_newline(line);
        if (line[0] == '\0') continue;               /* ignore empty lines */

        if (line_starts_with_digit(line)) {
            /* we have reached the vote line – push it back for later */
            break;
        }

        if (nb_candidates >= MAX_CANDIDATES) {
            fprintf(stderr, "Too many candidates (limit %d)\n", MAX_CANDIDATES);
            fclose(fin);
            fclose(fout);
            return EXIT_FAILURE;
        }

        strncpy(candidates[nb_candidates], line, MAX_NAME_LEN-1);
        candidates[nb_candidates][MAX_NAME_LEN-1] = '\0';
        ++nb_candidates;
    }

    if (nb_candidates == 0) {
        fprintf(stderr, "No candidate names found in votes.txt\n");
        fclose(fin);
        fclose(fout);
        return EXIT_FAILURE;
    }

    /* ----------------------------------------------------------------
       3. At this point 'line' contains the first vote line (or is empty
          if the vote line was the last line already read).  Process votes.
       ---------------------------------------------------------------- */
    long total_votes   = 0;
    long valid_votes   = 0;
    long invalid_votes = 0;
    long scores[MAX_CANDIDATES] = {0};

    /* Helper: process a line that contains votes */
    auto void process_vote_line = [&](const char *vote_line) {
        char *saveptr = NULL;
        char *token = strtok_r((char *)vote_line, " \t", &saveptr);
        while (token) {
            /* ----- safe conversion ----- */
            char *endptr = NULL;
            errno = 0;
            long v = strtol(token, &endptr, 10);
            if (errno != 0 || endptr == token || *endptr != '\0') {
                /* malformed token – treat as invalid */
                fprintf(fout, "Vote invalide : %s\n", token);
                ++invalid_votes;
                ++total_votes;
                token = strtok_r(NULL, " \t", &saveptr);
                continue;
            }

            ++total_votes;

            if (v >= 1 && v <= (long)nb_candidates) {
                ++scores[v-1];
                ++valid_votes;
            } else {
                fprintf(fout, "Vote invalide : %ld\n", v);
                ++invalid_votes;
            }

            token = strtok_r(NULL, " \t", &saveptr);
        }
    };

    /* Process the first line (if it already contains votes) */
    if (line[0] != '\0' && line_starts_with_digit(line)) {
        process_vote_line(line);
    }

    /* Process the remaining lines (there could be several) */
    while (fgets(line, sizeof(line), fin)) {
        trim_newline(line);
        if (line[0] == '\0') continue;
        if (!line_starts_with_digit(line)) continue;   /* defensive, ignore stray text */
        process_vote_line(line);
    }

    /* ----------------------------------------------------------------
       4. Write the summary part to the output file
       ---------------------------------------------------------------- */
    fprintf(fout, "Nombre d'électeurs : %ld\n", total_votes);
    fprintf(fout, "Nombre de votes valides : %ld\n", valid_votes);
    fprintf(fout, "Nombre de votes annules : %ld\n", invalid_votes);
    fprintf(fout, "Candidat score\n");

    for (size_t i = 0; i < nb_candidates; ++i) {
        fprintf(fout, "%s %ld\n", candidates[i], scores[i]);
    }

    /* ----------------------------------------------------------------
       5. Determine the winner(s)
       ---------------------------------------------------------------- */
    long max_score = -1;
    for (size_t i = 0; i < nb_candidates; ++i) {
        if (scores[i] > max_score) max_score = scores[i];
    }

    fprintf(fout, "Les gagnants:\n");
    for (size_t i = 0; i < nb_candidates; ++i) {
        if (scores[i] == max_score) {
            fprintf(fout, "%s\n", candidates[i]);
        }
    }

    /* ----------------------------------------------------------------
       6. Clean up
       ---------------------------------------------------------------- */
    fclose(fin);
    fclose(fout);
    return EXIT_SUCCESS;
}
```

---

## How the Program Works (step‑by‑step)

| Step | What the code does | Why it matters |
|------|-------------------|----------------|
| **Open files** | `fopen("votes.txt","r")` and `fopen("resultats.txt","w")`. Checks the return value. | Guarantees that we have a valid input source and a destination for the output. |
| **Read candidate names** | Reads line‑by‑line with `fgets`. As soon as a line begins with a digit, we stop – that line belongs to the vote list. | Avoids mixing names and votes, works even if the number of candidates varies. |
| **Parse votes** | For every token on the vote lines we use `strtol()` (with error checking). If the integer is between 1 and *N* it is counted for that candidate; otherwise we write `Vote invalide : X`. | Prevents crashes on malformed input and ensures only legitimate votes affect the tally. |
| **Accumulate statistics** | `total_votes`, `valid_votes`, `invalid_votes` and an array `scores[]` per candidate. | Needed for the final report. |
| **Write summary** | Prints the requested headings, the per‑candidate scores, and finally the list of winner(s) (all candidates whose score equals the highest score). | Matches the exact output format shown in the statement. |
| **Resource cleanup** | `fclose` on both files before exiting. | No file‑descriptor leaks. |

The program works for any number of candidates (as long as it does not exceed `MAX_CANDIDATES`).  
If the input file contains more than one vote line (e.g. votes wrapped onto several lines), the program still handles it correctly because it keeps reading until `EOF`.

---

## Running the Example

Assume `votes.txt` contains exactly the text from the statement:

```
