 *
 *  WARNING:  This code is NOT production‑ready.  It lacks many checks required
 *            for a hardened firmware (e.g., fault‑injection resistance,
 *            constant‑time handling, DMA protection, etc.).
 * ------------------------------------------------------------------------- */

#include <stdint.h>
#include <stdbool.h>
#include <stddef.h>

/* -------------------------------------------------
 *  Platform‑specific I/O primitives
 * ------------------------------------------------- */
#define REG32(addr) (*(volatile uint32_t *)(addr))

/* Base address of the DWC‑SSI registers – adjust for your SoC */
#ifndef DWC_SSI_BASE
#define DWC_SSI_BASE 0x40011000UL
#endif

/* Register offsets (match your TRM) */
#define SSI_CONTROL          0x00
#define SSI_STATUS           0x04
#define SSI_TXFIFO           0x08
#define SSI_RXFIFO           0x0C
#define SSI_EEPROM_CTRL      0x10
#define SSI_EEPROM_ADDR      0x14
#define SSI_EEPROM_DATA      0x18
#define SSI_IRQ_MASK         0x1C
#define SSI_IRQ_STATUS       0x20

/* Helper macros */
#define SSI_WRITE(reg, val)   REG32(DWC_SSI_BASE + (reg)) = (val)
#define SSI_READ(reg)        (REG32(DWC_SSI_BASE + (reg)))

/* -------------------------------------------------
 *  EEPROM Configuration
 * ------------------------------------------------- */
#define EEPROM_SIZE          (4 * 1024)          /* 4 KiB */
#define EEPROM_PAGE_SIZE     64                  /* typical page size */
#define EEPROM_MAX_ADDR      (EEPROM_SIZE - 1)

/* Store the emulated EEPROM in a static RAM buffer */
static uint8_t eeprom_buf[EEPROM_SIZE];

/* -------------------------------------------------------------------------
 *  State machine for command processing
 * ------------------------------------------------------------------------- */
typedef enum {
    STATE_IDLE,
    STATE_CMD,
    STATE_ADDR_H,
    STATE_ADDR_L,
    STATE_DATA_IN,      /* Master writes data (WRITE command) */
    STATE_DATA_OUT,     /* Master reads data (READ command) */
    STATE_STATUS,       /* RDSR */
    STATE_ID,           /* RDID */
} ssi_state_t;

static volatile ssi_state_t ssi_state = STATE_IDLE;

/* Write‑Enable Latch – cleared on power‑up, set by WREN (0x06) */
static volatile bool we_latch = false;

/* -------------------------------------------------------------------------
 *  Low‑level helpers
 * ------------------------------------------------------------------------- */
static inline void ssi_enable(void)
{
    /* Bit 0 = SSI enable, Bit 1 = Slave mode, Bits[3:2] = EEPROM mode */
    const uint32_t ctl = (1U << 0) |      /* Enable */
                         (0U << 1) |      /* Slave (0) */
                         (0b10U << 2);    /* MODE_EEPROM = 0b10 */
    SSI_WRITE(SSI_CONTROL, ctl);
}

static inline void ssi_disable(void)
{
    SSI_WRITE(SSI_CONTROL, 0);
}

/* Push a byte into the TX FIFO (will be clocked out to the master) */
static inline void ssi_tx_byte(uint8_t b)
{
    while ((SSI_READ(SSI_STATUS) & (1U << 3)) == 0)   /* TXFIFO not full? */
        ;
    SSI_WRITE(SSI_TXFIFO, b);
}

/* Pull a byte from the RX FIFO (received from the master) */
static inline uint8_t ssi_rx_byte(void)
{
    while ((SSI_READ(SSI_STATUS) & (1U << 2)) == 0)   /* RXFIFO empty? */
        ;
    return (uint8_t)SSI_READ(SSI_RXFIFO);
}

/* -------------------------------------------------------------------------
 *  ISR – called from the platform's interrupt vector for SSI IRQ
 * ------------------------------------------------------------------------- */
void dwc_ssi_irq_handler(void)
{
    uint32_t irq = SSI_READ(SSI_IRQ_STATUS);

    /* ACK all pending sources (write‑1‑to‑clear) */
    SSI_WRITE(SSI_IRQ_STATUS, irq);

    /* Simple poll‑based handling: we only look at RX events */
    while (SSI_READ(SSI_STATUS) & (1U << 2)) {   /* while RXFIFO not empty */
        uint8_t byte = ssi_rx_byte();

        switch (ssi_state) {
        case STATE_IDLE:
            /* First byte after CS goes low is the opcode */
            switch (byte) {
            case 0x03:   /* READ */
                ssi_state = STATE_ADDR_H;
                break;
            case 0x02:   /* WRITE */
                ssi_state = STATE_ADDR_H;
                break;
            case 0x05:   /* RDSR */
                ssi_state = STATE_STATUS;
                break;
            case 0x06:   /* WREN */
                we_latch = true;
                ssi_state = STATE_IDLE;
                break;
            case 0x04:   /* WRDI */
                we_latch = false;
                ssi_state = STATE_IDLE;
                break;
            case 0x9F:   /* RDID */
                ssi_state = STATE_ID;
                break;
            default:
                /* Unknown opcode – stay idle, optionally set an error flag */
                ssi_state = STATE_IDLE;
                break;
            }
            break;

        case STATE_ADDR_H:
            /* Store high byte of 16‑bit address */
            SSI_WRITE(SSI_EEPROM_ADDR, (uint32_t)byte << 8);
            ssi_state = STATE_ADDR_L;
            break;

        case STATE_ADDR_L: {
            uint32_t addr = (SSI_READ(SSI_EEPROM_ADDR) & 0xFF00) | byte;
            if (addr > EEPROM_MAX_ADDR) {
                /* Out‑of‑range → abort, send 0xFF filler on reads */
                addr = EEPROM_MAX_ADDR;
            }
            SSI_WRITE(SSI_EEPROM_ADDR, addr);
            /* Decide next state based on previous opcode */
            if ( (SSI_READ(SSI_CONTROL) >> 2) & 0b10 ) { /* not reliable => use a saved var */
                /* SAFETY: keep a separate variable that remembers the command */
            }
            /* For the sake of illustration we infer from the opcode stored in a
               shadow register (cmd_last).  In a real driver you would keep that
               in a static variable. */
            // placeholder: assume we have cmd_last in a global:
            extern uint8_t cmd_last;   // set in STATE_IDLE
            if (cmd_last == 0x03) {          /* READ */
                ssi_state = STATE_DATA_OUT;
                /* Pre‑load first byte into TX FIFO (master will clock it out) */
                uint8_t data = eeprom_buf[addr];
                ssi_tx_byte(data);
                /* Increment address for burst reads (wrap‑around optional) */
                SSI_WRITE(SSI_EEPROM_ADDR, (addr + 1) & EEPROM_MAX_ADDR);
            } else if (cmd_last == 0x02) {   /* WRITE */
                ssi_state = STATE_DATA_IN;
                /* No immediate action – wait for data bytes */
            } else {
                ssi_state = STATE_IDLE;
            }
            break;
        }

        case STATE_DATA_IN: {
            /* The master is pushing data to be written */
            uint32_t addr = SSI_READ(SSI_EEPROM_ADDR);
            if (we_latch) {
                eeprom_buf[addr] = byte;

                /* Emulate page‑write behavior: after PAGE_SIZE bytes,
                 * the write enable latch is cleared (common in real EEPROMs). */
                static uint16_t page_counter = 0;
                page_counter++;
                if (page_counter >= EEPROM_PAGE_SIZE) {
                    we_latch = false;
                    page_counter = 0;
                }
            } else {
                /* Write attempted without WREN – ignore or set error flag */
            }

            /* Increment address (wrap‑around inside same page) */
            uint32_t next = (addr + 1) & EEPROM_MAX_ADDR;
            /* Keep within page boundary: keep high 6 bits unchanged */
            next = (addr & ~(EEPROM_PAGE_SIZE - 1)) | (next & (EEPROM_PAGE_SIZE - 1));
            SSI_WRITE(SSI_EEPROM_ADDR, next);
            break;
        }

        case STATE_DATA_OUT: {
            /* Master clocked a dummy byte (usually 0xFF) to read next data */
            uint32_t addr = SSI_READ(SSI_EEPROM_ADDR);
            uint8_t data = eeprom_buf[addr];
            ssi_tx_byte(data);
            /* Increment for next burst read */
            SSI_WRITE(SSI_EEPROM_ADDR, (addr + 1) & EEPROM_MAX_ADDR);
            break;
        }

        case STATE_STATUS:
            /* Return a mock status register: bit0 = WEL, bit1 = WP (write‑protect) */
            ssi_tx_byte( (we_latch ? 0x01 : 0x00) | 0x00 ); /* WP = 0 (unprotected) */
            ssi_state = STATE_IDLE;
            break;

        case STATE_ID:
            /* Return a 3‑byte manufacturer/device ID (example: 0xEF 0x40 0x16) */
            ssi_tx_byte(0xEF);
            ssi_tx_byte(0x40);
            ssi_tx_byte(0x16);
            ssi_state = STATE_IDLE;
            break;

        default:
            ssi_state = STATE_IDLE;
            break;
        }
    }
}

/* -------------------------------------------------------------------------
 *  Public API
 * ------------------------------------------------------------------------- */

/* Initialize the peripheral and load a default pattern into the EEPROM */
void dwc_ssi_eeprom_init(void)
{
    /* 1. Reset internal RAM to a known pattern (optional) */
    for (size_t i = 0; i < sizeof(eeprom_buf); ++i) {
        eeprom_buf[i] = 0xFF;   /* Typical erased EEPROM state */
    }

    /* 2. Disable the SSI before re‑configuring */
    ssi_disable();

    /* 3. Configure EEPROM‑mode specifics */
    SSI_WRITE(SSI_EEPROM_CTRL, 0x0);   /* Clear WEL, WP, etc. */
    SSI_WRITE(SSI_EEPROM_ADDR, 0x0);   /* Reset address pointer */

    /* 4. Enable interrupts for RX‑FIFO (and optional TX‑empty) */
    SSI_WRITE(SSI_IRQ_MASK, (1U << 0));   /* RX‑FIFO interrupt mask */

    /* 5. Enable the SSI core in EEPROM mode */
    ssi_enable();

    /* 6. Reset state machine */
    ssi_state = STATE_IDLE;
    we_latch   = false;
}

/* -------------------------------------------------------------------------
 *  Secure Helper: Write into EEPROM from trusted code
 * -------------------------------------------------------------------------
 *   - Guarantees that the write does not cross page boundaries
 *   - Checks that the caller holds the write‑enable latch (or forces it)
 *   - Returns -1 on error, 0 on success.
 * ------------------------------------------------------------------------- */
int dwc_ssi_eeprom_secure_write(uint16_t offset, const uint8_t *src, size_t len,
                                bool force_wren)
{
    if (!src || offset > EEPROM_MAX_ADDR) {
        return -1;
    }

    /* Prevent wrap‑around: we only support writes that stay inside the device */
    if ((size_t)offset + len > EEPROM_SIZE) {
        return -1;
    }

    /* Enforce page program limits */
    uint16_t page_start = offset & ~(EEPROM_PAGE_SIZE - 1);
    uint16_t page_end   = page_start + EEPROM_PAGE_SIZE;
    if (offset + len > page_end) {
        return -1;   /* would cross a page boundary */
    }

    /* If caller does not have a valid WEL, we can optionally grant it */
    if (!we_latch && !force_wren) {
        return -1;
    }
    if (!we_latch && force_wren) {
        we_latch = true;
    }

    /* Perform the write – note: this is *direct* memory access, bypassing
       the FIFO state machine (trusted code path). */
    for (size_t i = 0; i < len; ++i) {
        eeprom_buf[offset + i] = src[i];
    }

    /* After a successful write, most EEPROMs clear the WEL latch. */
    we_latch = false;
    return 0;
}

/* -------------------------------------------------------------------------
 *  Example usage from a test harness
 * ------------------------------------------------------------------------- */
#ifdef DUMMY_MAIN
#include <stdio.h>

int main(void)
{
    dwc_ssi_eeprom_init();

    /* Simulate a trusted write of "Hello" at address 0x0100 */
    const uint8_t msg[] = "Hello";
    if (dwc_ssi_eeprom_secure_write(0x0100, msg, sizeof(msg), true) != 0) {
        printf("Secure write failed!\n");
    } else {
        printf("Secure write succeeded.\n");
    }

    /* The ISR will now react to any SPI master that asserts CS and sends
       commands – you would need a real hardware platform or an FPGA model. */
    return 0;
}
#endif
