    puts("\n=== 万年历实验 - 日期调节 ===");
    puts("当前待设置日期: ");
    /* 这里的日期将在 main 中打印 */
    puts("\n操作菜单:");
    puts(" 1) 年 +1   2) 年 -1");
    puts(" 3) 月 +1   4) 月 -1");
    puts(" 5) 日 +1   6) 日 -1");
    puts(" 7) 同步系统时间 (需要 root)");
    puts(" 0) 退出");
    printf("请选择 (0-7): ");
}

/* 读取用户的单字符输入（忽略换行） */
static int read_choice(void)
{
    int ch;
    while ((ch = getchar()) != EOF) {
        if (ch == '\n')
            continue;   // 跳过空行
        /* 读取完后把剩余输入丢弃 */
        while (getchar() != '\n' && !feof(stdin));
        return ch - '0';
    }
    return -1;  // EOF
}

/* ---------- 主程序 ---------- */
int main(void)
{
    /* 1. 读取系统当前时间作为基准 */
    time_t now = time(NULL);
    if (now == (time_t)-1) {
        perror("time()");
        return EXIT_FAILURE;
    }

    struct tm cur_tm;
    if (!localtime_r(&now, &cur_tm)) {
        perror("localtime_r()");
        return EXIT_FAILURE;
    }

    /* 2. 用一个可编辑的副本来保存“待设置日期” */
    struct tm edit_tm = cur_tm;

    while (1) {
        /* 打印当前待设置日期 */
        printf("\n待设置日期: ");
        print_date(&edit_tm);

        show_menu();
        int choice = read_choice();
        if (choice < 0) {
            fprintf(stderr, "\n读取输入失败，程序退出。\n");
            break;
        }

        switch (choice) {
        case 0:  /* 退出 */
            puts("Bye!");
            return EXIT_SUCCESS;

        case 1: /* 年 +1 */
            edit_tm.tm_year += 1;
            normalize_tm(&edit_tm);
            puts("年 +1 完成。");
            break;

        case 2: /* 年 -1 */
            edit_tm.tm_year -= 1;
            normalize_tm(&edit_tm);
            puts("年 -1 完成。");
            break;

        case 3: /* 月 +1 */
            edit_tm.tm_mon += 1;
            normalize_tm(&edit_tm);
            puts("月 +1 完成。");
            break;

        case 4: /* 月 -1 */
            edit_tm.tm_mon -= 1;
            normalize_tm(&edit_tm);
            puts("月 -1 完成。");
            break;

        case 5: /* 日 +1 */
            edit_tm.tm_mday += 1;
            normalize_tm(&edit_tm);
            puts("日 +1 完成。");
            break;

        case 6: /* 日 -1 */
            edit_tm.tm_mday -= 1;
            normalize_tm(&edit_tm);
            puts("日 -1 完成。");
            break;

        case 7: /* 同步系统时间 */
            printf("即将把系统时间设置为 %04d-%02d-%02d，继续吗? (y/N): ",
                   edit_tm.tm_year + 1900,
                   edit_tm.tm_mon  + 1,
                   edit_tm.tm_mday);
            fflush(stdout);
            int confirm = getchar();
            while (getchar() != '\n' && !feof(stdin)); // 清除残余输入
            if (confirm == 'y' || confirm == 'Y') {
                if (sync_system_time(&edit_tm) == 0) {
                    puts("系统时间已成功更新。");
                } else {
                    puts("系统时间更新失败（可能缺少特权）。");
                }
            } else {
                puts("已取消同步。");
            }
            break;

        default:
            puts("无效选项，请重新输入。");
            break;
        }
    }

    return EXIT_SUCCESS;
}
```

