#define REGION_T1_STACK 5
#define REGION_T1_GUARD 6

void Task1_StackGuard(void *stack_base)
{
    // stack_base = low address of stack (grows down)
    uintptr_t guard_addr = (uintptr_t)stack_base; // 最低 256B 设 Guard

    MPU->RNR = REGION_T1_GUARD;
    MPU->RBAR = ARM_MPU_RBAR(0, guard_addr);
    MPU->RASR = ARM_MPU_RASR(
        0,
        ARM_MPU_AP_NONE,          // No access
        0,
        0,
        1,                        // XN
        ARM_MPU_REGION_SIZE_256B);
}
