## 7️⃣ 示例：完整的 “Secure Heap + MPU Guard” 小实现

> 以下代码演示 **如何在一个裸机/RTOS** 环境中把 **两层防护** 串联起来。它可以直接拷贝到项目中，作为 “安全加固模板”。  

```c
/* secure_heap.h ---------------------------------------------------------- */
#pragma once
#include <stddef.h>
#include <stdint.h>
#include <stdbool.h>

#define SECURE_HEAP_SIZE      (8 * 1024)            // 8 KiB
#define SECURE_CANARY         0x5A5AA5A5U

typedef struct {
    uint32_t canary_front;
    size_t   real_size;       // 真正请求的 user size
    uint8_t  data[];          // flexible array
} secure_block_t;

/* API */
void  secure_heap_init(void);
void *secure_malloc(size_t size);
void  secure_free(void *ptr);

/* MPU guard -------------------------------------------------------------- */
void mpu_guard_add(void *addr, size_t size, bool executable);
void mpu_guard_remove(void *addr, size_t size);
```

```c
/* secure_heap.c ---------------------------------------------------------- */
#include "secure_heap.h"
#include "cmsis_gcc.h"   // __disable_irq / __enable_irq
#include <string.h>

static uint8_t heap_mem[SECURE_HEAP_SIZE] __attribute__((aligned(8)));
static size_t  heap_offset = 0;

/* 简单的线性分配器（仅示例） */
static void *raw_alloc(size_t total)
{
    void *p = NULL;
    __disable_irq();
    if (heap_offset + total <= SECURE_HEAP_SIZE) {
        p = &heap_mem[heap_offset];
        heap_offset += total;
    }
    __enable_irq();
    return p;
}

void secure_heap_init(void) { heap_offset = 0; }

void *secure_malloc(size_t size)
{
    /* 1. 计算块大小：前后 canary + 用户数据 */
    size_t total = sizeof(secure_block_t) + size + sizeof(uint32_t); // rear canary
    secure_block_t *blk = raw_alloc(total);
    if (!blk) return NULL;

    /* 2. 初始化 canary */
    blk->canary_front = SECURE_CANARY;
    blk->real_size   = size;
    uint32_t *rear_canary = (uint32_t *)(blk->data + size);
    *rear_canary = SECURE_CANARY;

    /* 3. 为块创建 MPU Region（RW, XN） */
    mpu_guard_add(blk->data, size, false);

    return blk->data;
}

void secure_free(void *ptr)
{
    if (!ptr) return;
    secure_block_t *blk = (secure_block_t *)((uint8_t *)ptr - offsetof(secure_block_t, data));

    /* 4. 检测 canary 完整性 */
    if (blk->canary_front != SECURE_CANARY ||
        *((uint32_t *)(blk->data + blk->real_size)) != SECURE_CANARY) {
        // 触发安全异常：可能的堆溢出或双重释放
        __BKPT(0); // halting for debugger / crash
    }

    /* 5. 移除 MPU Region */
    mpu_guard_remove(blk->data, blk->real_size);

    /* NOTE: 本演示不做真正回收，实际产品请实现空闲块链表或 buddy */
}
```

```c
/* mpu_guard.c ------------------------------------------------------------- */
#include "cmsis_gcc.h"
#include "core_cm33.h"

#define MAX_GUARD_REGIONS    8
static uint8_t guard_count = 0;

/* 简单的循环分配 Region 编号（实际产品可使用动态映射表） */
void mpu_guard_add(void *addr, size_t size, bool executable)
{
    if (guard_count >= MAX_GUARD_REGIONS) return; // 超限，直接返回
    uint32_t region = guard_count++;

    MPU->RNR = region;
    MPU->RBAR = ARM_MPU_RBAR(0, (uint32_t)addr);
    MPU->RASR = ARM_MPU_RASR(
        0,
        ARM_MPU_AP_FULL,          // RW for privileged + unprivileged
        0,
        0,
        executable ? 0 : 1,       // XN = 1 => non‑executable
        ARM_MPU_RASR_SIZE(size)); // 自动取最近的 2^N 大小
    __DSB(); __ISB();
}

void mpu_guard_remove(void *addr, size_t size)
{
    /* 在硬件上没办法“删除”，只能把属性设为 NONE */
    for (uint32_t i = 0; i < guard_count; ++i) {
        MPU->RNR = i;
        if ((MPU->RBAR & MPU_RBAR_BASE_Msk) == ((uint32_t)addr & ~0x1F)) {
            MPU->RASR = ARM_MPU_RASR(0, ARM_MPU_AP_NONE, 0, 0, 1,
                                    ARM_MPU_RASR_SIZE(size));
            break;
        }
    }
    __DSB(); __ISB();
}
```

- **使用方式**：

```c
int main(void)
{
    MPU_Init();          // 先配置系统 MPU
    secure_heap_init();

    uint8_t *buf = secure_malloc(200);
    memset(buf, 0xAA, 200);       // 正常使用
    // buf[200] = 0x55;           // 越界写会触发 canary 检测
    secure_free(buf);
}
```

> **为什么这段代码更安全？**  
> 1. **Canary**：前后 0x5A5AA5A5 检测溢出。  
> 2. **MPU Guard**：每块堆内存在分配后立即把 **只读/不可执行** 权限写入 MPU，防止 **代码注入** 与 **跨块读/写**。  
> 3. **双重释放检测**：释放后若 `canary` 被破坏则触发硬件断点（在生产环境可改为安全重启）。  
> 4. **最小特权**：只在 **privileged** 核心代码里调用 `mpu_guard_*`，普通任务无法修改 MPU。

