    /* Port > 4000 – można go podać jako argument (argv[1]), domyślnie 5001 */
    const int SERVER_PORT = (argc > 1) ? atoi(argv[1]) : 5001;

    int sockfd;
    struct sockaddr_in6 servaddr, cliaddr;   // IPv6 jest uniwersalne; w IPv4 wystarczy sockaddr_in
    ssize_t nbytes;
    char buffer[MAX_BUF];
    socklen_t cli_len = sizeof(cliaddr);

    /* 1. Utworzenie socketu UDP */
    if ((sockfd = socket(AF_INET6, SOCK_DGRAM, 0)) < 0) {
        perror("socket()");
        exit(EXIT_FAILURE);
    }

    /* 2. Zero‑init i ustawienie adresu serwera (listen on any interface) */
    memset(&servaddr, 0, sizeof(servaddr));
    servaddr.sin6_family = AF_INET6;
    servaddr.sin6_addr = in6addr_any;          // 0::0 – wszystkie interfejsy
    servaddr.sin6_port = htons(SERVER_PORT);

    /* 3. bind() */
    if (bind(sockfd, (struct sockaddr *)&servaddr, sizeof(servaddr)) < 0) {
        perror("bind()");
        close(sockfd);
        exit(EXIT_FAILURE);
    }

    printf("[SERVER] nasłuchiwanie na porcie %d (IPv6/IPv4) …\n", SERVER_PORT);

    /* 4. Pętla nieskończona */
    while (1) {
        memset(buffer, 0, sizeof(buffer));
        nbytes = recvfrom(sockfd, buffer, sizeof(buffer) - 1, 0,
                          (struct sockaddr *)&cliaddr, &cli_len);
        if (nbytes < 0) {
            perror("recvfrom()");
            continue;   // nie przerywaj serwera
        }

        buffer[nbytes] = '\0';            // bezpieczeństwo – zakończenie stringa
        printf("[SERVER] odebrano od %s:%d → \"%s\"\n",
               inet_ntop(AF_INET6, &cliaddr.sin6_addr, buffer, sizeof(buffer)),
               ntohs(cliaddr.sin6_port), buffer);

        /* 5. Konwersja na duże litery */
        for (int i = 0; i < nbytes; ++i) buffer[i] = toupper((unsigned char)buffer[i]);

        /* 6. Odpowiedź */
        ssize_t sent = sendto(sockfd, buffer, nbytes, 0,
                              (struct sockaddr *)&cliaddr, cli_len);
        if (sent != nbytes) {
            perror("sendto()");
        } else {
            printf("[SERVER] odparowano \"%s\"\n", buffer);
        }
    }

    /* 7. (nigdy nie osiągnięte) */
    close(sockfd);
    return 0;
}
```

**Komentarze bezpieczeństwa w kodzie serwera**

- **`MAX_BUF`** – ustalony stały rozmiar, nie przyjmuje więcej niż 255 B.
- **`memset(buffer,0,…)`** – zerowanie bufora przed `recvfrom()`.
- **Sprawdzanie zwrotów** – każde wywołanie systemowe jest weryfikowane; w razie błędu serwer nie przestaje działać, lecz loguje problem.
- **`toupper()`** na znakach typu `unsigned char` – unika nieprzewidzianego zachowania przy znakach ujemnych (w zależności od kodowania).

