    if (argc < 2) {
        fprintf(stderr, "Użycie: %s <adres> [port] [\"Imię Nazwisko\"]\n", argv[0]);
        exit(EXIT_FAILURE);
    }

    const char *server_ip = argv[1];
    const int SERVER_PORT = (argc > 2) ? atoi(argv[2]) : 5001;
    const char *name = (argc > 3) ? argv[3] : DEFAULT_NAME;

    int sockfd;
    struct sockaddr_in6 serveraddr;
    ssize_t nbytes;

    /* 1. Utworzenie socketu UDP */
    if ((sockfd = socket(AF_INET6, SOCK_DGRAM, 0)) < 0) {
        perror("socket()");
        exit(EXIT_FAILURE);
    }

    /* 2. Wypełnienie struktury adresu serwera */
    memset(&serveraddr, 0, sizeof(serveraddr));
    serveraddr.sin6_family = AF_INET6;
    serveraddr.sin6_port   = htons(SERVER_PORT);
    if (inet_pton(AF_INET6, server_ip, &serveraddr.sin6_addr) <= 0) {
        /* Spróbuj IPv4 -> IPv6‑mapped */
        struct in_addr ipv4addr;
        if (inet_pton(AF_INET, server_ip, &ipv4addr) <= 0) {
            perror("inet_pton()");
            close(sockfd);
            exit(EXIT_FAILURE);
        }
        /* IPv4‑mapped IPv6 address ::ffff:a.b.c.d */
        serveraddr.sin6_addr = in6addr_any;
        serveraddr.sin6_addr.s6_addr[10] = 0xff;
        serveraddr.sin6_addr.s6_addr[11] = 0xff;
        memcpy(&serveraddr.sin6_addr.s6_addr[12], &ipv4addr, 4);
    }

    /* 3. Wysłanie imienia i nazwiska */
    nbytes = sendto(sockfd, name, strlen(name), 0,
                    (struct sockaddr *)&serveraddr, sizeof(serveraddr));
    if (nbytes < 0) {
        perror("sendto()");
        close(sockfd);
        exit(EXIT_FAILURE);
    }
    printf("[CLIENT] Wysłano: \"%s\" → %s:%d\n",
           name, server_ip, SERVER_PORT);

    /* 4. Oczekiwanie na odpowiedź (timeout 2 s) */
    struct timeval tv = {.tv_sec = 2, .tv_usec = 0};
    setsockopt(sockfd, SOL_SOCKET, SO_RCVTIMEO, &tv, sizeof(tv));

    char recvbuf[MAX_BUF];
    struct sockaddr_in6 srcaddr;
    socklen_t src_len = sizeof(srcaddr);

    nbytes = recvfrom(sockfd, recvbuf, sizeof(recvbuf) - 1, 0,
                      (struct sockaddr *)&srcaddr, &src_len);
    if (nbytes < 0) {
        perror("recvfrom()");
        close(sockfd);
        exit(EXIT_FAILURE);
    }
    recvbuf[nbytes] = '\0';
    printf("[CLIENT] Odpowiedź serwera: \"%s\"\n", recvbuf);

    close(sockfd);
    return 0;
}
```

**Uwaga bezpieczeństwa**  
- `recvfrom()` ma **timeout** (`SO_RCVTIMEO`), co chroni klienta przed wiecznym blokowaniem, jeśli serwer nie odpowie.
- Na wejściu przyjmujemy jedynie **jedną linijkę** (długość ograniczona `MAX_BUF`). Nie ma ryzyka przepełnienia bufora przy odbiorze.

