     *  2) Przygotowanie struktury adresowej
     * ---------------------------------------------------------- */
    memset(&addr, 0, sizeof(struct sockaddr_un));
    addr.sun_family = AF_UNIX;
    strncpy(addr.sun_path, SOCKET_PATH, sizeof(addr.sun_path) - 1);

    /* ----------------------------------------------------------
     *  3) Bindowanie gniazda do ścieżki w systemie plików
     * ---------------------------------------------------------- */
    if (bind(listen_fd, (struct sockaddr *)&addr, sizeof(struct sockaddr_un)) == -1)
        die("bind");

    /* Opcjonalnie: ograniczamy dostęp do pliku gniazda (0600) */
    if (chmod(SOCKET_PATH, 0600) == -1)
        die("chmod");

    /* ----------------------------------------------------------
     *  4) Nasłuchiwanie
     * ---------------------------------------------------------- */
    if (listen(listen_fd, BACKLOG) == -1)
        die("listen");

    printf("Serwer nasłuchuje na %s …\n", SOCKET_PATH);

    /* ----------------------------------------------------------
     *  5) Akceptacja jednego połączenia (w laboratorium to wystarczy)
     * ---------------------------------------------------------- */
    if ((conn_fd = accept(listen_fd, NULL, NULL)) == -1)
        die("accept");

    /* ----------------------------------------------------------
     *  6) Odczyt danych od klienta
     * ---------------------------------------------------------- */
    nread = recv(conn_fd, buf, BUF_SIZE - 1, 0);
    if (nread == -1)
        die("recv");
    buf[nread] = '\0';                 /* terminator C-string */
    printf("Otrzymano od klienta: \"%s\"\n", buf);

    /* ----------------------------------------------------------
     *  7) Przetwarzanie – zamiana na duże litery
     * ---------------------------------------------------------- */
    to_upper(buf);

    /* ----------------------------------------------------------
     *  8) Odesłanie wyniku
     * ---------------------------------------------------------- */
    nwrite = send(conn_fd, buf, strlen(buf), 0);
    if (nwrite == -1)
        die("send");

    printf("Wysłano z powrotem: \"%s\"\n", buf);

    /* ----------------------------------------------------------
     *  9) Sprzątanie
     * ---------------------------------------------------------- */
    close(conn_fd);
    close(listen_fd);
    unlink(SOCKET_PATH);      /* usuwa plik socketu */
    return 0;
}
