## 3. Kod klienta (`uds_client.c`)

```c
/* --------------------------------------------------------------
 *  uds_client.c  –  prosty klient Unix‑Domain Socket (SOCK_STREAM)
 *  Wysyła imię i nazwisko, odbiera odpowiedź (wielkie litery)
 *  -------------------------------------------------------------- */
#include <sys/socket.h>
#include <sys/un.h>
#include <unistd.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>

#define SOCKET_PATH "/tmp/uds_demo.sock"
#define BUF_SIZE    256

static void die(const char *msg)
{
    perror(msg);
    exit(EXIT_FAILURE);
}

/* Czyści bufor i usuwa znak nowej linii, jeżeli został wczytany */
static void strip_newline(char *s)
{
    char *p = strchr(s, '\n');
    if (p) *p = '\0';
}

int main(void)
{
    int fd = -1;
    struct sockaddr_un addr;
    char send_buf[BUF_SIZE];
    char recv_buf[BUF_SIZE];
    ssize_t nwrite, nread;

    /* ----------------------------------------------------------
     *  1) Utworzenie gniazda (AF_UNIX, SOCK_STREAM)
     * ---------------------------------------------------------- */
    if ((fd = socket(AF_UNIX, SOCK_STREAM, 0)) == -1)
        die("socket");

    /* ----------------------------------------------------------
     *  2) Przygotowanie adresu serwera
     * ---------------------------------------------------------- */
    memset(&addr, 0, sizeof(struct sockaddr_un));
    addr.sun_family = AF_UNIX;
    strncpy(addr.sun_path, SOCKET_PATH, sizeof(addr.sun_path) - 1);

    /* ----------------------------------------------------------
     *  3) Połączenie z serwerem
     * ---------------------------------------------------------- */
    if (connect(fd, (struct sockaddr *)&addr, sizeof(struct sockaddr_un)) == -1)
        die("connect");

    /* ----------------------------------------------------------
     *  4) Pobranie danych od użytkownika (imię i nazwisko)
     * ---------------------------------------------------------- */
    printf("Podaj imię i nazwisko: ");
    if (!fgets(send_buf, sizeof(send_buf), stdin))
        die("fgets");
    strip_newline(send_buf);   /* usuwa \n */

    /* ----------------------------------------------------------
     *  5) Wysłanie danych
     * ---------------------------------------------------------- */
    nwrite = send(fd, send_buf, strlen(send_buf), 0);
    if (nwrite == -1)
        die("send");
    printf("Wysłano: \"%s\"\n", send_buf);

    /* ----------------------------------------------------------
     *  6) Odbiór odpowiedzi
     * ---------------------------------------------------------- */
    nread = recv(fd, recv_buf, sizeof(recv_buf) - 1, 0);
    if (nread == -1)
        die("recv");
    recv_buf[nread] = '\0';
    printf("Odpowiedź serwera: \"%s\"\n", recv_buf);

    /* ----------------------------------------------------------
     *  7) Sprzątanie
     * ---------------------------------------------------------- */
    close(fd);
    return 0;
}
```

