        return -1;
    }
    return 0;
}

/* 添加日记 */
static void add_diary(void) {
    DiaryEntry e;
    memset(&e, 0, sizeof(e));
    if (input_date(&e.date)!=0) return;
    if (find_entry(g_head, &e.date)) {
