    }
    printf("请输入关键字 (最多 31 字符): "); read_line(e.keyword, sizeof(e.keyword));
    printf("请输入内容 (最多 511 字符): "); read_line(e.content, sizeof(e.content));
    insert_entry(&g_head, &e);
    save_diary();
    printf("日记已添加/更新。\n");
}

