    if (*s == '-' || *s == '+') s++;
    while (*s) {
        if (*s == '.') {
            if (dot) return 0;   /* 只能有一个小数点 */
            dot = 1;
        } else if (isdigit((unsigned char)*s)) {
            digit = 1;
        } else {
            return 0;
        }
        s++;
    }
    return digit;
}
