    }

    printf("请输入生产厂家：");
    if (safe_input(p.manufacturer, sizeof(p.manufacturer)) < 0) return;

    printf("请输入品牌：");
    if (safe_input(p.brand, sizeof(p.brand)) < 0) return;

    /* 插入到数组末尾 */
    g_products[g_count++] = p;
    printf("商品添加成功！当前商品总数：%d\n", g_count);
}

/* 5.3 查询商品（支持三种维度） */
static void query_product(void)
{
    char buf[INPUT_BUF];
    printf("\n=== 商品查询 ===\n");
    printf("查询方式：\n");
    printf("1. 按类别\n");
    printf("2. 按名称\n");
    printf("3. 按生产厂家\n");
    printf("请选择 (1-3)：");
    if (safe_input(buf, sizeof(buf)) < 0) return;
    int choice = atoi(buf);
    if (choice < 1 || choice > 3) {
        printf("选择错误！\n");
        return;
    }

    int found = 0;
    switch (choice) {
        case 1: {   /* 按类别 */
            printf("请输入类别 (1-食品 2-化妆品 3-日用品 4-饮料)：");
            if (safe_input(buf, sizeof(buf)) < 0) return;
            Category cat;
            if (!str2category(buf, &cat)) {
                printf("类别输入错误！\n");
                return;
            }
            for (int i = 0; i < g_count; ++i) {
                if (g_products[i].category == cat) {
                    print_product(&g_products[i]);
                    ++found;
                }
            }
            break;
        }
        case 2: {   /* 按名称 */
            printf("请输入商品名称 (全匹配)：");
            if (safe_input(buf, sizeof(buf)) < 0) return;
            for (int i = 0; i < g_count; ++i) {
                if (strcmp(g_products[i].name, buf) == 0) {
                    print_product(&g_products[i]);
                    ++found;
                }
            }
            break;
        }
        case 3: {   /* 按生产厂家 */
            printf("请输入生产厂家名称 (全匹配)：");
            if (safe_input(buf, sizeof(buf)) < 0) return;
            for (int i = 0; i < g_count; ++i) {
                if (strcmp(g_products[i].manufacturer, buf) == 0) {
                    print_product(&g_products[i]);
                    ++found;
                }
            }
            break;
        }
    }

    if (!found) {
        printf("该记录不存在！\n");
    }
}

/* 5.4 修改商品（先查询，再修改） */
static void modify_product(void)
{
    char buf[INPUT_BUF];
    printf("\n=== 商品修改 ===\n");
    printf("先输入商品类别 (1-食品 2-化妆品 3-日用品 4-饮料)：");
    if (safe_input(buf, sizeof(buf)) < 0) return;
    Category cat;
    if (!str2category(buf, &cat)) {
        printf("类别错误！\n");
        return;
    }
    printf("输入要修改的商品名称：");
    if (safe_input(buf, sizeof(buf)) < 0) return;
    int idx = find_product(cat, buf);
    if (idx < 0) {
        printf("未找到该商品，无法修改！\n");
        return;
    }

    Product *p = &g_products[idx];
    printf("当前商品信息如下：\n");
    print_product(p);

    printf("请选择要修改的字段：\n");
    printf("1. 名称   2. 单价   3. 库存量   4. 生产厂家   5. 品牌   6. 类别\n");
    printf("输入序号 (可一次修改多项，用空格分隔，例如 \"2 4\")：");
    if (safe_input(buf, sizeof(buf)) < 0) return;

    /* 解析用户输入的多个数字 */
    char *tok = strtok(buf, " ");
    while (tok) {
        int sel = atoi(tok);
        switch (sel) {
            case 1: {
                printf("新名称：");
                if (safe_input(p->name, sizeof(p->name)) < 0) return;
                break;
            }
            case 2: {
                printf("新单价：");
                if (safe_input(buf, sizeof(buf)) < 0) return;
                if (!is_float(buf)) {
                    printf("单价非法！\n");
                } else {
                    p->price = atof(buf);
                }
                break;
            }
            case 3: {
                printf("新库存量：");
                if (safe_input(buf, sizeof(buf)) < 0) return;
                if (!is_integer(buf)) {
                    printf("库存非法！\n");
                } else {
                    p->stock = atoi(buf);
                }
                break;
            }
            case 4: {
                printf("新生产厂家：");
                if (safe_input(p->manufacturer, sizeof(p->manufacturer)) < 0) return;
                break;
            }
            case 5: {
                printf("新品牌：");
                if (safe_input(p->brand, sizeof(p->brand)) < 0) return;
                break;
            }
            case 6: {
                printf("新类别 (1-食品 2-化妆品 3-日用品 4-饮料)：");
                if (safe_input(buf, sizeof(buf)) < 0) return;
                Category newcat;
                if (!str2category(buf, &newcat)) {
                    printf("类别非法，保持原值。\n");
                } else {
                    p->category = newcat;
                }
                break;
            }
            default:
                printf("未知选项 %d，跳过。\n", sel);
                break;
        }
        tok = strtok(NULL, " ");
    }

    printf("修改完成，当前商品信息：\n");
    print_product(p);
}

/* 5.5 删除商品 */
static void delete_product(void)
{
    char buf[INPUT_BUF];
    printf("\n=== 商品删除 ===\n");
    printf("先输入商品类别 (1-食品 2-化妆品 3-日用品 4-饮料)：");
    if (safe_input(buf, sizeof(buf)) < 0) return;
    Category cat;
    if (!str2category(buf, &cat)) {
        printf("类别错误！\n");
        return;
    }
    printf("请输入要删除的商品名称：");
    if (safe_input(buf, sizeof(buf)) < 0) return;

    int idx = find_product(cat, buf);
    if (idx < 0) {
        printf("该商品不存在！\n");
        return;
    }

    /* 把数组最后一项搬到要删除的位置，保持连续性 */
    g_products[idx] = g_products[g_count - 1];
    --g_count;
    printf("商品已删除，当前商品总数 %d。\n", g_count);
}

/* 5.6 统计功能 */
static int cmp_price_desc(const void *a, const void *b)
{
    double pa = ((Product*)a)->price;
    double pb = ((Product*)b)->price;
    return (pa < pb) - (pa > pb);   /* 降序 */
}
static int cmp_stock_desc(const void *a, const void *b)
{
    int sa = ((Product*)a)->stock;
    int sb = ((Product*)b)->stock;
    return (sb - sa);
}
static int cmp_manufacturer_desc(const void *a, const void *b)
{
    return strcmp(((Product*)b)->manufacturer, ((Product*)a)->manufacturer);
}

/* 统计并按用户选择的字段排序后输出 */
static void statistics(void)
{
    if (g_count == 0) {
        printf("当前库存为空，无统计信息。\n");
        return;
    }

    printf("\n=== 商品统计 ===\n");
    printf("当前库存商品总数：%d\n", g_count);
    printf("请选择排序方式 (1-价格 2-库存量 3-生产厂家)：");
    char buf[INPUT_BUF];
    if (safe_input(buf, sizeof(buf)) < 0) return;
    int mode = atoi(buf);

    /* 复制一份临时数组用于排序，避免破坏原始顺序 */
    Product tmp[MAX_PRODUCTS];
    memcpy(tmp, g_products, g_count * sizeof(Product));

    switch (mode) {
        case 1:
            qsort(tmp, g_count, sizeof(Product), cmp_price_desc);
            printf("按价格（从高到低）排序：\n");
            break;
        case 2:
            qsort(tmp, g_count, sizeof(Product), cmp_stock_desc);
            printf("按库存量（从高到低）排序：\n");
            break;
        case 3:
            qsort(tmp, g_count, sizeof(Product), cmp_manufacturer_desc);
            printf("按生产厂家（字典序倒序）排序：\n");
            break;
        default:
            printf("无效排序方式，使用原始顺序。\n");
            break;
    }

    for (int i = 0; i < g_count; ++i) {
        print_product(&tmp[i]);
    }
}

/* ---------- 6. 主菜单 ---------- */
