## 3️⃣ 安全的改写示例

下面给出一个 **可编译、符合安全编码规范** 的示例，实现相同语义的初始化过程。

```c
#include <stdio.h>
#include <string.h>
#include <stdint.h>   // uintptr_t
#include <stddef.h>   // size_t

#define OT_SMR_BUF_SET_MAX          (16)
#define SMR_REGION_NUM_MAX          (16)
#define SMR_REGION_NAME_LEN_MAX     (64)

typedef enum {
    OT_SMR_ALLOCATOR_BBAA = 1,   // Binary Buddy Allocation Algorithm
    OT_SMR_ALLOCATOR_BUTT
} ot_smr_allocator;

/* 使用 uintptr_t 保存地址，size_t 保存长度/对齐 */
typedef struct {
    char     region_name[SMR_REGION_NAME_LEN_MAX];
    uintptr_t addr;            // 采用无符号指针宽度类型
    size_t    len;
} ot_smr_region;

typedef struct {
    ot_smr_region regions[SMR_REGION_NUM_MAX];
    size_t       num;           // 用 size_t 描述元素个数
    ot_smr_allocator allocator;
} ot_smr_attr;

typedef struct {
    char   region_name[SMR_REGION_NAME_LEN_MAX];
    size_t len;
    size_t align;
} ot_smr_alloc_attr;

/* ------------------- 安全的帮助函数 ------------------- */

/* 初始化单个 region，确保名字不越界 */
static int init_region(ot_smr_region *r,
                       const char *name,
                       uintptr_t addr,
                       size_t len)
{
    if (!r || !name) return -1;

    /* 防止 name 长度超过缓冲区 */
    size_t name_len = strnlen(name, SMR_REGION_NAME_LEN_MAX - 1);
    memcpy(r->region_name, name, name_len);
    r->region_name[name_len] = '\0';

    r->addr = addr;
    r->len  = len;
    return 0;
}

/* 将 region 加入 attr，自动检查上限 */
static int add_region_to_attr(ot_smr_attr *attr,
                              const ot_smr_region *r)
{
    if (!attr || !r) return -1;
    if (attr->num >= SMR_REGION_NUM_MAX) {
        /* 超出上限，拒绝加入 */
        return -2;
    }
    attr->regions[attr->num] = *r;   // 结构体整体拷贝（安全，因为已初始化）
    attr->num++;
    return 0;
}

/* ------------------- main ------------------- */
int main(void)
{
    ot_smr_region jay;
    if (init_region(&jay, "jolin", 0x10, 1) != 0) {
        fprintf(stderr, "init_region failed\n");
        return 1;
    }

    ot_smr_attr attr = {0};               // 完全零初始化，防止垃圾值
    attr.allocator = OT_SMR_ALLOCATOR_BBAA;
    attr.num = 0;                         // 明确设置起始元素数量

    if (add_region_to_attr(&attr, &jay) != 0) {
        fprintf(stderr, "add_region_to_attr failed\n");
        return 1;
    }

    /* 这里演示打印枚举值（安全） */
    printf("allocator = %d, num = %zu\n",
           (int)attr.allocator,
           attr.num);
    return 0;
}
```

