/*********************************************************************
 *  文件名 : merge_sort_unique.c
 *  描述   : 读取两个字符串，对每个字符串分别排序后合并，
 *           合并后再次排序并去除重复字符。
 *  编译   : gcc -Wall -Wextra -pedantic -std=c11 merge_sort_unique.c -o merge_sort_unique
 *  运行   : ./merge_sort_unique
 *
 *  作者   : (Your Name)
 *  日期   : 2024‑06‑xx
 *********************************************************************/

#include <stdio.h>
#include <string.h>
#include <stdlib.h>

#define MAX_LEN 256   /* 每个输入字符串的最大长度（不含 '\0'） */

/*--------------------------------------------------------------
 *  比较函数：供 qsort 使用，按 ASCII 升序比较
 *--------------------------------------------------------------*/
static int cmp_char(const void *a, const void *b)
{
    return (*(const unsigned char *)a) - (*(const unsigned char *)b);
}

/*--------------------------------------------------------------
 *  去重函数：已排序的字符串中删除相邻的相同字符
 *  参数:
 *      src   - 已排序的源字符串（可修改）
 *  返回值:
 *      去重后字符串的长度（不含结尾 '\0'）
 *--------------------------------------------------------------*/
static size_t remove_duplicates(char *src)
{
    if (src[0] == '\0')
        return 0;

    size_t write_idx = 0;                     /* 下一个写入位置 */
    for (size_t read_idx = 1; src[read_idx] != '\0'; ++read_idx) {
        if (src[read_idx] != src[write_idx]) {  /* 与前一个字符不同则保留 */
            ++write_idx;
            src[write_idx] = src[read_idx];
        }
    }
    src[write_idx + 1] = '\0';                 /* 添加字符串结束符 */
    return write_idx + 1;                      /* 返回新长度 */
}

/*--------------------------------------------------------------
 *  安全读取一行字符串（去掉换行符）
 *--------------------------------------------------------------*/
static void safe_readline(char *buf, size_t bufsize)
{
    /* fgets 会保留换行符（若有），我们手动去掉 */
    if (fgets(buf, (int)bufsize, stdin) == NULL) {
        /* 输入错误或 EOF，直接退出 */
        perror("fgets");
        exit(EXIT_FAILURE);
    }
    /* 去除结尾的 '\n'（如果存在） */
    size_t len = strlen(buf);
    if (len > 0 && buf[len - 1] == '\n')
        buf[len - 1] = '\0';
}

/*--------------------------------------------------------------
 *  主函数
 *--------------------------------------------------------------*/
int main(void)
{
    char str1[MAX_LEN + 1];   /* +1 用于存放终止符 '\0' */
    char str2[MAX_LEN + 1];
    char merged[2 * MAX_LEN + 1];   /* 合并后最大长度 */

    printf("请输入第一个字符串（最长 %d 个字符）：\n> ", MAX_LEN);
    safe_readline(str1, sizeof(str1));

    printf("请输入第二个字符串（最长 %d 个字符）：\n> ", MAX_LEN);
    safe_readline(str2, sizeof(str2));

    /* ---------------------------------------------------------
       1) 分别对 str1、str2 进行字符排序
       --------------------------------------------------------- */
    size_t n1 = strlen(str1);
    size_t n2 = strlen(str2);

    qsort(str1, n1, sizeof(char), cmp_char);
    qsort(str2, n2, sizeof(char), cmp_char);

    /* ---------------------------------------------------------
       2) 合并两个已排序的字符串
       --------------------------------------------------------- */
    memcpy(merged, str1, n1);
    memcpy(merged + n1, str2, n2);
    merged[n1 + n2] = '\0';

    /* ---------------------------------------------------------
       3) 对合并后的结果再次排序
       --------------------------------------------------------- */
    qsort(merged, n1 + n2, sizeof(char), cmp_char);

    /* ---------------------------------------------------------
       4) 删除重复字符
       --------------------------------------------------------- */
    size_t final_len = remove_duplicates(merged);

    /* ---------------------------------------------------------
       输出结果
       --------------------------------------------------------- */
    printf("\n=== 处理过程 ===\n");
    printf("第一个字符串（已排序） : %s\n", str1);
    printf("第二个字符串（已排序） : %s\n", str2);
    printf("合并后再次排序         : %s\n", merged);
    printf("去重后的最终字符串    : %s\n", merged);
    printf("最终长度（字符数）    : %zu\n", final_len);

    return 0;
}
```

