## 📁 Full Source (`sigusr1_demo.c`)

```c
/* -------------------------------------------------------------
 * sigusr1_demo.c – demo of a SIGUSR1 handler
 * -------------------------------------------------------------
 * Compile:   gcc -Wall -Wextra -O2 -std=c11 sigusr1_demo.c -o sigusr1_demo
 * Run:       ./sigusr1_demo
 * -------------------------------------------------------------
 * Author:    <TWOJE IMIĘ I NAZWISKO>
 * License:   MIT (feel free to reuse)
 * -------------------------------------------------------------
 */

#define _POSIX_C_SOURCE 200809L   /* needed for sigaction, nanosleep */
#include <stdio.h>
#include <unistd.h>
#include <signal.h>
#include <string.h>
#include <stdlib.h>
#include <errno.h>

/* -------------------------------------------------------------
 *  Async‑signal‑safe output function
 *
 *  We cannot call printf() inside a signal handler because it is
 *  not async‑signal‑safe.  The only POSIX‑guaranteed safe I/O
 *  function is write(2).  Therefore we use a small wrapper.
 * ------------------------------------------------------------- */
static void safe_write_str(const char *s)
{
    /* write() may be interrupted by another signal – retry */
    size_t len = strlen(s);
    while (len > 0) {
        ssize_t w = write(STDOUT_FILENO, s, len);
        if (w == -1) {
            if (errno == EINTR) continue;   /* retry */
            /* If we cannot write at all, there is nothing we can do */
            break;
        }
        s   += w;
        len -= w;
    }
}

/* -------------------------------------------------------------
 *  Signal handler for SIGUSR1
 *
 *  It prints:  "Hello, I am <NAME> <SURNAME>!\n"
 * ------------------------------------------------------------- */
static void sigusr1_handler(int signo)
{
    (void)signo;          /* unused, we know it is SIGUSR1 */
    const char msg[] = "Hello, I am <TWOJE IMIĘ I NAZWISKO>!\n";
    safe_write_str(msg);
}

/* -------------------------------------------------------------
 *  Install the handler using sigaction()
 * ------------------------------------------------------------- */
static void install_sigusr1_handler(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));

    sa.sa_handler = sigusr1_handler;
    /* Safer to block all other signals while the handler runs */
    sigfillset(&sa.sa_mask);
    /* Do not restart interrupted system calls automatically;
       we want the sleep() to be interruptible so that the program
       reacts promptly to the signal. */
    sa.sa_flags = 0;

    if (sigaction(SIGUSR1, &sa, NULL) == -1) {
        perror("sigaction");
        exit(EXIT_FAILURE);
    }
}

/* -------------------------------------------------------------
 *  Main loop – infinite sleep
 * ------------------------------------------------------------- */
int main(void)
{
    /* 1. Show our PID so that the user can send signals */
    printf("My PID is %ld – use: kill -USR1 %ld\n",
           (long)getpid(), (long)getpid());
    fflush(stdout);   /* make sure the line appears before we go to sleep */

    /* 2. Register the handler */
    install_sigusr1_handler();

    /* 3. Infinite loop with a modest sleep interval.
       nanosleep() is used because it is restartable and accurate.   */
    struct timespec ts = { .tv_sec = 2, .tv_nsec = 0 };   /* 2‑second pause */

    while (1) {
        /* The sleep may be interrupted by a signal (EINTR);
           we simply continue the loop – the signal handler has already
           printed the desired message.                                           */
        if (nanosleep(&ts, NULL) == -1 && errno != EINTR) {
            perror("nanosleep");
            /* Not fatal – continue looping */
        }
        /* Optional: you can add a tiny heartbeat here (e.g. a dot),
           but keep it async‑signal‑safe. */
    }

    /* Unreachable */
    return 0;
}
```

