 *
 * Run:
 *      ./prime_check
 *      Enter an integer:  29
 *      29 is a prime number.
 */

#define _POSIX_C_SOURCE 200809L   /* for getline() */
#include <stdio.h>
#include <stdlib.h>
#include <errno.h>
#include <limits.h>
#include <string.h>
#include <ctype.h>

/* --------------------------------------------------------------------- */
/* Helper: Trim leading and trailing whitespace */
static void trim(char **str)
{
    char *s = *str;
    while (isspace((unsigned char)*s)) ++s;          /* leading */
    char *end = s + strlen(s);
    while (end > s && isspace((unsigned char)*(end-1))) --end;  /* trailing */
    *end = '\0';
    *str = s;
}

/* --------------------------------------------------------------------- */
/* Securely parse a signed 64‑bit integer from a line of text.
 * Returns 0 on success, non‑zero on error.
 */
static int parse_int64(const char *line, long long *out)
{
    char *endptr = NULL;
    errno = 0;
    long long val = strtoll(line, &endptr, 10);

    /* Check for conversion errors */
    if (errno == ERANGE) {
        fprintf(stderr, "Error: number out of range for 64‑bit signed integer.\n");
        return -1;
    }
    if (endptr == line) {               /* no digits found */
        fprintf(stderr, "Error: no integer found in the input.\n");
        return -1;
    }
    /* Ensure that the rest of the string contains only whitespace */
    while (*endptr) {
        if (!isspace((unsigned char)*endptr)) {
            fprintf(stderr, "Error: unexpected character '%c' after number.\n", *endptr);
            return -1;
        }
        ++endptr;
    }
    *out = val;
    return 0;
}

/* --------------------------------------------------------------------- */
/* Determine whether n (>=2) is prime using trial division up to sqrt(n).
 * The loop uses only integer arithmetic – no floating point – to avoid
 * precision issues and to keep execution deterministic.
 */
static int is_prime(long long n)
{
    if (n < 2) return 0;                 /* 0,1 and negatives are not prime */
    if (n == 2 || n == 3) return 1;      /* the only even prime is 2 */

    if ((n & 1LL) == 0) return 0;        /* even numbers >2 are composite */

    /* We only need to test divisors up to floor(sqrt(n)).  Rather than call
     * sqrt() we use an integer loop where i*i <= n.  i*i fits in 128‑bit
     * intermediate on most modern compilers, but we explicitly cast to
     * unsigned long long to avoid signed overflow undefined behaviour.
     */
    for (long long i = 3; (unsigned long long)i * (unsigned long long)i <= (unsigned long long)n; i += 2) {
        if (n % i == 0)
            return 0;   /* divisor found → composite */
    }
    return 1;           /* no divisors → prime */
}

/* --------------------------------------------------------------------- */
int main(void)
{
    char *line = NULL;
    size_t len = 0;
    ssize_t nread;

    printf("Enter an integer: ");
    fflush(stdout);   /* make sure prompt appears before input */

    nread = getline(&line, &len, stdin);
    if (nread == -1) {
        perror("getline");
        free(line);
        return EXIT_FAILURE;
    }

    /* Remove the trailing newline that getline stores (if present) */
    if (nread > 0 && line[nread-1] == '\n')
        line[nread-1] = '\0';

    trim(&line);      /* strip surrounding whitespace */

    long long number;
    if (parse_int64(line, &number) != 0) {
        free(line);
        return EXIT_FAILURE;
    }

    if (is_prime(number))
        printf("%lld is a prime number.\n", number);
    else
        printf("%lld is NOT a prime number.\n", number);

    free(line);
    return EXIT_SUCCESS;
}
