#include <stdio.h>
#include <stdlib.h>
#include <math.h>
#include <float.h>
#include <stdbool.h>
#include <stdint.h>
#include <errno.h>

/* ----------------------------------------------------------------------
 * Error codes (positive integers, zero means success)
 * ---------------------------------------------------------------------- */
enum {
    SQRT_OK                 = 0,
    SQRT_ERR_NEGATIVE       = 1,   // input < 0
    SQRT_ERR_NAN            = 2,   // input is NaN
    SQRT_ERR_INFINITY       = 3,   // input is +inf
    SQRT_ERR_DISCREPANCY    = 4    // our result differs from libm sqrt()
};

/* ----------------------------------------------------------------------
 * Helper: check if two doubles differ by more than one ULP
 * ---------------------------------------------------------------------- */
static bool ulp_diff_exceeds_one(double a, double b)
{
    if (isnan(a) || isnan(b)) return true;
    if (isinf(a) || isinf(b)) return a != b;

    /* reinterpret the bits as uint64_t */
    union { double d; uint64_t u; } ua = { .d = a };
    union { double d; uint64_t u; } ub = { .d = b };

    /* Make ordering of signed zero/negative values monotonic */
    uint64_t ia = ua.u ^ ((int64_t)ua.u >> 63) & 0x7FFFFFFFFFFFFFFFULL;
    uint64_t ib = ub.u ^ ((int64_t)ub.u >> 63) & 0x7FFFFFFFFFFFFFFFULL;

    uint64_t diff = (ia > ib) ? (ia - ib) : (ib - ia);
    return diff > 1ULL;
}

/* ----------------------------------------------------------------------
 * safe_sqrt – constant‑time Newton‑Raphson sqrt
 *
 *  x   – input value (must be >= 0, non‑NaN, finite)
 *  out – pointer to double that receives the result (only written on success)
 *
 * Returns:
 *   SQRT_OK (0) on success, otherwise one of the SQRT_ERR_* codes.
 * ---------------------------------------------------------------------- */
int safe_sqrt(double x, double *out)
{
    if (out == NULL) {
        return SQRT_ERR_NEGATIVE;  // reuse code; in production use a dedicated error
    }

    /* ----------- Input validation ------------------------------------- */
    if (isnan(x))          return SQRT_ERR_NAN;
    if (isinf(x) && x > 0) return SQRT_ERR_INFINITY;
    if (x < 0.0)           return SQRT_ERR_NEGATIVE;

    /* Edge cases: 0 and 1 are exact */
    if (x == 0.0 || x == 1.0) {
        *out = x;
        return SQRT_OK;
    }

    /* ----------- Newton–Raphson (constant 30 iterations) ------------- */
    const int MAX_ITER = 30;         // 30 iterations → ~15‑digit accuracy for double
    double xn = x;                   // initial guess (x is always > 0)
    /* Guard against overflow of the initial guess: clamp to DBL_MAX */
    if (xn > DBL_MAX) xn = DBL_MAX;

    /* Fixed‑time loop: the iteration count does NOT depend on the data */
    for (int i = 0; i < MAX_ITER; ++i) {
        /* Prevent division by zero – xn can never be zero after first step,
           but we check defensively. */
        if (xn == 0.0) {
            xn = DBL_MIN;   // smallest positive subnormal
        }
        xn = 0.5 * (xn + x / xn);
    }

    /* ----------- Post‑verification (using libm sqrt) ----------------- */
    double libm_res = sqrt(x);

    if (ulp_diff_exceeds_one(xn, libm_res)) {
        /* The discrepancy is larger than one ULP – something is fishy.
           In a hardened environment we would fallback to libm directly. */
        return SQRT_ERR_DISCREPANCY;
    }

    *out = xn;
    return SQRT_OK;
}

/* ----------------------------------------------------------------------
 * Simple CLI driver (for demonstration)
 * ---------------------------------------------------------------------- */
static void usage(const char *progname)
{
    fprintf(stderr, "Usage: %s <non‑negative-number>\n", progname);
    exit(EXIT_FAILURE);
}

int main(int argc, char *argv[])
{
    if (argc != 2) usage(argv[0]);

    char *endptr = NULL;
    errno = 0;
    double input = strtod(argv[1], &endptr);
    if (errno != 0 || endptr == argv[1] || *endptr != '\0') {
        fprintf(stderr, "Error: invalid floating‑point value.\n");
        return EXIT_FAILURE;
