    double result = 0.0;
    int rc = safe_sqrt(input, &result);

    if (rc != SQRT_OK) {
        const char *msg;
        switch (rc) {
            case SQRT_ERR_NEGATIVE:   msg = "Negative input – square root undefined."; break;
            case SQRT_ERR_NAN:        msg = "Input is NaN."; break;
            case SQRT_ERR_INFINITY:   msg = "Input is +infinity – overflow."; break;
            case SQRT_ERR_DISCREPANCY:msg = "Result deviates from libm sqrt (>1 ULP)."; break;
            default:                  msg = "Unknown error."; break;
        }
        fprintf(stderr, "safe_sqrt failed: %s\n", msg);
        return EXIT_FAILURE;
    }

    printf("safe_sqrt(%.*g) = %.15g\n", DBL_DECIMAL_DIG, input, result);
    return EXIT_SUCCESS;
}
