/* ------------------------------------------------------------------ */
/*  Définition du nœud de la liste doublement chaînée                  */
/* ------------------------------------------------------------------ */
typedef struct Noeud {
    char    *mot;            /* chaîne dynamique (nul‑terminée)          */
    struct Noeud *prev;     /* pointeur vers le nœud précédent          */
    struct Noeud *next;     /* pointeur vers le nœud suivant            */
} Noeud;

/* ------------------------------------------------------------------ */
/*  Prototype des fonctions de l'API du dictionnaire                   */
/* ------------------------------------------------------------------ */
Noeud *creer_noeud(const char *mot);
void  ajoutMOT(Noeud **tete, const char *mot);
