### 2. Création d’un nœud sécurisé

```c
Noeud *creer_noeud(const char *mot)
{
    /* Vérification de la longueur */
    size_t len = strnlen(mot, MOT_MAX);
    if (len == MOT_MAX) {
        fprintf(stderr, "[SEC] Le mot dépasse la longueur maximale (%d).\n", MOT_MAX-1);
        return NULL;
    }

    /* Vérification de caractères non imprimables */
    for (size_t i = 0; i < len; ++i) {
        if (!isprint((unsigned char)mot[i])) {
            fprintf(stderr, "[SEC] Le mot contient des caractères non imprimables.\n");
            return NULL;
        }
    }

    /* Allocation du nœud */
    Noeud *n = malloc(sizeof(Noeud));
    if (!n) {
        perror("[SEC] malloc nœud");
        return NULL;
    }

    /* Allocation de la chaîne (avec terminaison NUL) */
    n->mot = malloc(len + 1);
    if (!n->mot) {
        perror("[SEC] malloc chaîne");
        free(n);
        return NULL;
    }

    /* Copie sécurisée */
    strncpy(n->mot, mot, len);
    n->mot[len] = '\0';

    n->prev = n->next = NULL;
    return n;
}
```

