### 3. Fonction `ajoutMOT` (insertion ordonnée)

```c
/* ---------------------------------------------------------------
   ajoutMOT : insère *mot* dans la liste pointée par *tete*,
   tout en maintenant l'ordre alphabétique.
   *tete* est un pointeur *sur* le pointeur tête pour pouvoir le
   mettre à jour lorsque le nouveau nœud devient le premier.
   --------------------------------------------------------------- */
void ajoutMOT(Noeud **tete, const char *mot)
{
    if (!tete || !mot) return;

    Noeud *nouveau = creer_noeud(mot);
    if (!nouveau) return;               /* création a échoué, aucune insertion */

    /* Cas 1 : liste vide → le nouveau devient la tête */
    if (*tete == NULL) {
        *tete = nouveau;
        return;
    }

    Noeud *courant = *tete;

    /* Parcourir jusqu'à trouver la bonne position (ou la fin) */
    while (courant) {
        int cmp = compare_mots(nouveau->mot, courant->mot);

        if (cmp == 0) {
            /* Le mot existe déjà → on ne l'insère pas (ou on peut le compter) */
            fprintf(stderr, "[INFO] Le mot \"%s\" est déjà présent.\n", mot);
            liberer_dictionnaire(nouveau);   /* libérer le nœud créé */
            return;
        }

        if (cmp < 0) {
            /* Insertion avant 'courant' */
            nouveau->next = courant;
            nouveau->prev = courant->prev;

            if (courant->prev)
                courant->prev->next = nouveau;
            else
                *tete = nouveau;            /* nouveau devient la tête */

            courant->prev = nouveau;
            return;
        }

        /* Sinon, on avance */
        if (courant->next == NULL) {
            /* Fin de liste → insertion en queue */
            courant->next = nouveau;
            nouveau->prev = courant;
            return;
        }
        courant = courant->next;
    }
}
```

