```cpp
#include <iostream>
#include <iomanip>
#include <cmath>
#include <limits>

using namespace std;

/* ----------  Параметры задачи  ---------- */
const int MAXN = 500;                 // максимальное количество вершин
const double INF = numeric_limits<double>::infinity();

/* ----------  Структуры данных  ---------- */
double w[MAXN][MAXN];                 // надёжность ребра (0 – нет ребра)
double distR[MAXN];                   // -log( reliability )
double bestReliability[MAXN];         // произведение надёжностей
bool used[MAXN];
int parent[MAXN];

/* ----------  Вспомогательные функции  ---------- */
void restorePath(int v, int s) {
    if (v == -1) return;
    restorePath(parent[v], s);
    cout << v << ' ';
}

/* ----------  Основная программа  ---------- */
int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, m;
    if (!(cin >> n >> m)) return 0;          // чтение количества вершин и рёбер
    if (n > MAXN) {
        cerr << "Error: number of vertices exceeds MAXN=" << MAXN << "\n";
        return 1;
    }

    // инициализируем матрицу нулями (отсутствие ребра)
    for (int i = 0; i < n; ++i)
        for (int j = 0; j < n; ++j)
            w[i][j] = 0.0;

    // ввод рёбер
    for (int i = 0; i < m; ++i) {
        int u, v;
        double p;
        cin >> u >> v >> p;          // вершины нумеруются от 0
        if (p < 0.0) p = 0.0;
        if (p > 1.0) p = 1.0;
        w[u][v] = p;
        w[v][u] = p;                 // граф неориентированный
    }

    int s, t;                        // старт и финиш
    cin >> s >> t;

    /* ----------  Dijkstra без кучи ---------- */
    for (int i = 0; i < n; ++i) {
        distR[i] = INF;
        bestReliability[i] = 0.0;
        used[i] = false;
        parent[i] = -1;
    }
    distR[s] = 0.0;
    bestReliability[s] = 1.0;

    for (int iter = 0; iter < n; ++iter) {
        // ищем неиспользованную вершину с минимальным distR (т.е. с max reliability)
        int v = -1;
        double bestDist = INF;
        for (int i = 0; i < n; ++i) {
            if (!used[i] && distR[i] < bestDist) {
                bestDist = distR[i];
                v = i;
            }
        }
        if (v == -1) break;           // все оставшиеся вершины недостижимы
        if (v == t) break;            // уже нашли оптимальный путь до t

        used[v] = true;

        // расслабляем соседей
        for (int u = 0; u < n; ++u) {
            if (w[v][u] <= 0.0) continue;            // нет ребра
            double edgeWeight = -log(w[v][u]);       // -log(p)
            if (distR[u] > distR[v] + edgeWeight) {
                distR[u] = distR[v] + edgeWeight;
                bestReliability[u] = bestReliability[v] * w[v][u];
                parent[u] = v;
            }
        }
    }

    /* ----------  Вывод результата ---------- */
    cout.setf(ios::fixed);
    cout << setprecision(6);

    if (bestReliability[t] == 0.0) {
        cout << "No path from " << s << " to " << t << ".\n";
    } else {
        cout << "Maximum reliability from " << s << " to " << t << " = "
             << bestReliability[t] << "\n";
        cout << "Path: ";
        restorePath(t, s);
        cout << "\n";
    }

    return 0;
}
```

