### 2.1 结构体定义

```c
/* -------------------------------------------------
 * 1) 动态 ID 表的内存布局
 * ------------------------------------------------- */
struct dyn_usb_id_table {
    struct usb_device_id *ids;   /* 实际的 ID 数组 */
    size_t               count;  /* 当前有效的 ID 条目数 */
    struct mutex         lock;   /* 保护并发读写 */
};
```

### 2.2 分配/释放函数

```c
static struct dyn_usb_id_table *dyn_idtbl_alloc(size_t max_entries)
{
    struct dyn_usb_id_table *tbl;

    tbl = kzalloc(sizeof(*tbl), GFP_KERNEL);
    if (!tbl)
        return NULL;

    tbl->ids = kzalloc(sizeof(struct usb_device_id) * max_entries,
                       GFP_KERNEL);
    if (!tbl->ids) {
        kfree(tbl);
        return NULL;
    }

    tbl->count = 0;
    mutex_init(&tbl->lock);
    return tbl;
}

static void dyn_idtbl_free(struct dyn_usb_id_table *tbl)
{
    if (!tbl)
        return;
    kfree(tbl->ids);
    kfree(tbl);
}
```

### 2.3 添加/删除 ID 条目（带锁）

```c
/* 返回 0 成功，-ENOSPC 表示空间已满 */
static int dyn_idtbl_add(struct dyn_usb_id_table *tbl,
                         const struct usb_device_id *new_id)
{
    int ret = 0;

    mutex_lock(&tbl->lock);

    if (tbl->count >= MAX_ENTRIES) {
        ret = -ENOSPC;
        goto out;
    }

    /* 直接拷贝结构体，确保所有匹配字段都被复制 */
    tbl->ids[tbl->count] = *new_id;
    tbl->count++;

out:
    mutex_unlock(&tbl->lock);
    return ret;
}

/* 删除时把要删除的条目移到数组尾部，再把 count--，保持紧凑 */
static int dyn_idtbl_del(struct dyn_usb_id_table *tbl,
                         const struct usb_device_id *del_id)
{
    size_t i, j;
    int found = 0;

    mutex_lock(&tbl->lock);
    for (i = 0; i < tbl->count; ++i) {
        if (memcmp(&tbl->ids[i], del_id, sizeof(*del_id)) == 0) {
            /* 把最后一个元素搬到这里 */
            tbl->ids[i] = tbl->ids[tbl->count - 1];
            tbl->count--;
            found = 1;
            break;
        }
    }
    mutex_unlock(&tbl->lock);
    return found ? 0 : -ENOENT;
}
