```c
static int rcu_idtbl_add(const struct usb_device_id *new_id)
{
    struct usb_device_id *new_arr;
    const struct usb_device_id __rcu *old_arr;
    size_t old_cnt, new_cnt;
    int ret = 0;

    /* 1) 读取旧表 */
    old_arr = rcu_dereference(rcu_tbl->ids);
    old_cnt = rcu_tbl->count;

    /* 2) 分配新表（+1） */
    new_arr = kmalloc_array(old_cnt + 1, sizeof(*new_arr), GFP_KERNEL);
    if (!new_arr)
        return -ENOMEM;

    /* 3) 复制旧表 + 新条目 */
    if (old_arr)
        memcpy(new_arr, old_arr, old_cnt * sizeof(*new_arr));
    new_arr[old_cnt] = *new_id;
    new_cnt = old_cnt + 1;

    /* 4) 原子替换 */
    rcu_assign_pointer(rcu_tbl->ids, new_arr);
    rcu_tbl->count = new_cnt;

    /* 5) 旧表延迟回收 */
    if (old_arr)
        call_rcu(&old_arr->rcu_head, (rcu_callback_t)kfree);

    return ret;
}
