### 6.  Reference Implementation (C, ISO‑C99)

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdbool.h>

#define MAXV 30               /* maximum number of intersections   */
#define INF -1LL              /* value printed for infinite paths  */
typedef unsigned long long ULL;

/* --------------------------------------------------------------- */
int main(void)
{
    int city = 0;
    int streets;

    while (scanf("%d", &streets) == 1) {
        /* -----------------------------------------------------------------
           1. read edges, remember the maximum vertex index
        ----------------------------------------------------------------- */
        int adj[MAXV][MAXV] = {0};
        int maxVertex = -1;

        for (int e = 0; e < streets; ++e) {
            int a, b;
            scanf("%d %d", &a, &b);
            adj[a][b] = 1;
            if (a > maxVertex) maxVertex = a;
            if (b > maxVertex) maxVertex = b;
        }

        int V = maxVertex + 1;          /* vertices are 0 … V‑1 */

        /* -----------------------------------------------------------------
           2. transitive closure (reachability)
        ----------------------------------------------------------------- */
        bool reach[MAXV][MAXV];
        for (int i = 0; i < V; ++i)
            for (int j = 0; j < V; ++j)
                reach[i][j] = (adj[i][j] != 0);

        for (int k = 0; k < V; ++k)
            for (int i = 0; i < V; ++i)
                if (reach[i][k])
                    for (int j = 0; j < V; ++j)
                        if (reach[k][j])
                            reach[i][j] = true;

        /* -----------------------------------------------------------------
           3. which vertices are on a directed cycle ?
        ----------------------------------------------------------------- */
        bool cycle[MAXV] = {0};
        for (int v = 0; v < V; ++v)
            if (reach[v][v]) cycle[v] = true;

        /* -----------------------------------------------------------------
           4. pairs with infinitely many routes
        ----------------------------------------------------------------- */
        bool infinite[MAXV][MAXV] = {0};
        for (int c = 0; c < V; ++c) if (cycle[c]) {
            for (int i = 0; i < V; ++i) if (reach[i][c]) {
                for (int j = 0; j < V; ++j) if (reach[c][j]) {
                    infinite[i][j] = true;
                }
            }
        }

        /* -----------------------------------------------------------------
           5. work only with acyclic vertices – build a DAG
        ----------------------------------------------------------------- */
        bool acyclic[MAXV];
        for (int v = 0; v < V; ++v) acyclic[v] = !cycle[v];

        /* indegree inside the DAG */
        int indeg[MAXV] = {0};
        for (int u = 0; u < V; ++u) if (acyclic[u])
            for (int v = 0; v < V; ++v) if (acyclic[v] && adj[u][v])
                indeg[v]++;

        /* topological order (Kahn) */
        int topo[MAXV];
        int tsize = 0;
        int q[MAXV];
        int qhead = 0, qtail = 0;
        for (int v = 0; v < V; ++v)
            if (acyclic[v] && indeg[v] == 0)
                q[qtail++] = v;

        while (qhead < qtail) {
            int u = q[qhead++];
            topo[tsize++] = u;
            for (int v = 0; v < V; ++v)
                if (acyclic[v] && adj[u][v]) {
                    if (--indeg[v] == 0)
                        q[qtail++] = v;
                }
        }

        /* -----------------------------------------------------------------
           6. count finite routes
        ----------------------------------------------------------------- */
        ULL count[MAXV][MAXV];
        for (int i = 0; i < V; ++i)
            for (int j = 0; j < V; ++j)
                count[i][j] = 0ULL;

        /* direct edges inside the DAG contribute one route */
        for (int u = 0; u < V; ++u) if (acyclic[u])
            for (int v = 0; v < V; ++v)
                if (acyclic[v] && adj[u][v])
                    count[u][v] = 1ULL;

        /* propagate along topological order */
        for (int idx = 0; idx < tsize; ++idx) {
            int u = topo[idx];
            for (int v = 0; v < V; ++v)
                if (acyclic[v] && adj[u][v]) {
                    for (int s = 0; s < V; ++s)
                        count[s][v] += count[s][u];
                }
        }

        /* -----------------------------------------------------------------
           7. output
        ----------------------------------------------------------------- */
        printf("matrix for city %d\n", city++);
        for (int i = 0; i < V; ++i) {
            for (int j = 0; j < V; ++j) {
                if (infinite[i][j])
                    printf("%lld", (long long)INF);
                else
                    printf("%llu", count[i][j]);
                if (j + 1 < V) putchar(' ');
            }
            putchar('\n');
        }
    }
    return 0;
}
```

The program follows exactly the algorithm proven correct above, conforms to
the C99 standard and compiles with any modern C compiler.

