inline void PrintError(const char* msg)
{
    DWORD err = GetLastError();
    LPVOID lpMsgBuf;
    FormatMessageA(FORMAT_MESSAGE_ALLOCATE_BUFFER |
                   FORMAT_MESSAGE_FROM_SYSTEM |
                   FORMAT_MESSAGE_IGNORE_IF_MISSING,
                   nullptr, err,
                   MAKELANGID(LANG_NEUTRAL, SUBLANG_DEFAULT),
                   (LPSTR)&lpMsgBuf, 0, nullptr);
    std::cerr << msg << ": " << (char*)lpMsgBuf;
    LocalFree(lpMsgBuf);
}

// Read N bytes from a HANDLE (blocking, returns false on error/EOF)
inline bool ReadExact(HANDLE h, void* buf, DWORD n)
{
    DWORD read = 0;
    BYTE* p = (BYTE*)buf;
    while (n > 0)
    {
        if (!ReadFile(h, p, n, &read, nullptr) || read == 0)
            return false;
        p += read;
        n -= read;
    }
    return true;
}

// Write N bytes to a HANDLE (blocking)
inline bool WriteExact(HANDLE h, const void* buf, DWORD n)
{
    DWORD written = 0;
    const BYTE* p = (const BYTE*)buf;
    while (n > 0)
    {
        if (!WriteFile(h, p, n, &written, nullptr) || written == 0)
            return false;
        p += written;
        n -= written;
    }
    return true;
}

// ------------------------------------------------------------
