### 4.2 Сервер  

```cpp
// ------------------------------------------------------------
// server.cpp
// ------------------------------------------------------------
#include <windows.h>
#include <iostream>
#include <fstream>
#include <unordered_map>
#include <shared_mutex>
#include "utils.h"

#pragma pack(push,1)
struct Employee {
    int32_t num;
    char    name[10];
    double  hours;
};
#pragma pack(pop)

enum class MsgType : uint32_t {
    REQ_READ   = 1,
    REQ_WRITE  = 2,
    RESP_DATA  = 3,
    REQ_COMMIT = 4,
    REQ_CLOSE  = 5,
    RESP_OK    = 6,
    RESP_ERR   = 7
};

#pragma pack(push,1)
struct MessageHeader {
    MsgType type;
    uint32_t payloadSize;
};
#pragma pack(pop)

#pragma pack(push,1)
struct ReqKey { int32_t employeeId; };
#pragma pack(pop)

using LockMap = std::unordered_map<int32_t, std::shared_mutex>;

static const wchar_t* PIPE_NAME = L"\\\\.\\pipe\\EmployeePipe";

class Server {
public:
    Server(const std::string& fileName) : fileName_(fileName) {}

    bool Init()
    {
        // 1. Открываем/создаём бинарный файл
        std::fstream f(fileName_, std::ios::in | std::ios::out | std::ios::binary);
        if (!f) {
            // файл отсутствует → создаём пустой
            std::ofstream out(fileName_, std::ios::binary);
            if (!out) {
                std::cerr << "Cannot create file " << fileName_ << "\n";
                return false;
            }
        }
        // читаем существующие записи в memory‑vector
        LoadFile();
        // создаём именованный канал (одно соединение – для упрощения)
        hPipe_ = CreateNamedPipeW(
            PIPE_NAME,
            PIPE_ACCESS_DUPLEX,
            PIPE_TYPE_MESSAGE | PIPE_READMODE_MESSAGE | PIPE_WAIT,
            PIPE_UNLIMITED_INSTANCES,
            4096, 4096,
            0,
            nullptr);
        if (hPipe_ == INVALID_HANDLE_VALUE) {
            PrintError("CreateNamedPipe");
            return false;
        }
        std::cout << "Server ready, waiting for client connections...\n";
        return true;
    }

    void Run()
    {
        // Ожидаем клиента (можно цикл for, но в лаборатории один клиент)
        BOOL connected = ConnectNamedPipe(hPipe_, nullptr) ?
                         TRUE : (GetLastError() == ERROR_PIPE_CONNECTED);
        if (!connected) {
            PrintError("ConnectNamedPipe");
            return;
        }
        std::cout << "Client connected.\n";

        // Обслуживание запросов в бесконечном цикле,
        // заканчивается, когда клиент посылает REQ_CLOSE со специальным id = -1
        while (true) {
            MessageHeader hdr{};
            if (!ReadExact(hPipe_, &hdr, sizeof(hdr))) {
                std::cerr << "Pipe closed or read error.\n";
                break;
            }

            // (payload может быть 0)
            std::vector<char> payload;
            if (hdr.payloadSize) {
                payload.resize(hdr.payloadSize);
                if (!ReadExact(hPipe_, payload.data(), hdr.payloadSize)) {
                    std::cerr << "Failed to read payload.\n";
                    break;
                }
            }

            // Обрабатываем тип сообщения
            switch (hdr.type) {
                case MsgType::REQ_READ:
                case MsgType::REQ_WRITE:
                case MsgType::REQ_CLOSE: {
                    if (payload.size() != sizeof(ReqKey)) {
                        SendError(1, "Bad payload size for key request");
                        continue;
                    }
                    auto* pKey = reinterpret_cast<ReqKey*>(payload.data());
                    if (pKey->employeeId == -1) { // sentinel – shutdown
                        std::cout << "Shutdown request received.\n";
                        SendOk();
                        return;
                    }
                    ProcessAccessRequest(hdr.type, pKey->employeeId);
                    break;
                }
                case MsgType::REQ_COMMIT: {
                    if (payload.size() != sizeof(Employee)) {
                        SendError(2, "Bad payload size for commit");
                        continue;
                    }
                    ProcessCommit(reinterpret_cast<Employee*>(payload.data()));
                    break;
                }
                default:
                    SendError(99, "Unknown message type");
                    break;
            }
        }
    }

    void Shutdown()
    {
        // Сохраняем изменения в файл
        SaveFile();
        // Выводим результат
        std::cout << "\n=== FINAL FILE CONTENT ===\n";
        PrintFile();
        CloseHandle(hPipe_);
    }

private:
    // ---------------------- Файловые операции ----------------------
    std::string fileName_;
    std::vector<Employee> records_;        // хранит все записи в памяти
    std::unordered_map<int32_t, size_t> id2idx_; // быстрый поиск по ID

    void LoadFile()
    {
        std::ifstream in(fileName_, std::ios::binary);
        if (!in) return;
        Employee e{};
        while (in.read(reinterpret_cast<char*>(&e), sizeof(e))) {
            id2idx_[e.num] = records_.size();
            records_.push_back(e);
        }
    }

    void SaveFile()
    {
        std::ofstream out(fileName_, std::ios::binary | std::ios::trunc);
        for (const auto& e : records_)
            out.write(reinterpret_cast<const char*>(&e), sizeof(e));
    }

    void PrintFile()
    {
        for (const auto& e : records_) {
            std::cout << "ID: " << e.num
                << ", Name: " << std::string(e.name,10).c_str()
                << ", Hours: " << e.hours << "\n";
        }
    }

    // ---------------------- Блокировки ----------------------
    LockMap locks_;

    // Возврат указателя *на запись* + проверка существования
    Employee* FindEmployee(int32_t id)
    {
        auto it = id2idx_.find(id);
        if (it == id2idx_.end())
            return nullptr;
        return &records_[it->second];
    }

    // ---------------------- Сообщения клиенту ----------------------
    void SendHeader(MsgType type, uint32_t payload = 0)
    {
        MessageHeader hdr{ type, payload };
        WriteExact(hPipe_, &hdr, sizeof(hdr));
    }

    void SendOk()
    {
        SendHeader(MsgType::RESP_OK, 0);
    }

    void SendError(uint32_t code, const char* text)
    {
        SendHeader(MsgType::RESP_ERR, sizeof(RespError));
        RespError err{ code };
        strncpy_s(err.text, text, _TRUNCATE);
        WriteExact(hPipe_, &err, sizeof(err));
    }

    void SendEmployee(const Employee* e)
    {
        SendHeader(MsgType::RESP_DATA, sizeof(Employee));
        WriteExact(hPipe_, e, sizeof(Employee));
    }

    // ---------------------- Обработка запросов ----------------------
    void ProcessAccessRequest(MsgType type, int32_t empId)
    {
        Employee* e = FindEmployee(empId);
        if (!e) {
            SendError(404, "Employee not found");
            return;
        }

        // Блокировка
        if (type == MsgType::REQ_READ) {
            // shared (read) lock
            std::shared_lock<std::shared_mutex> lock(locks_[empId]);
            // сразу отсылаем запись, а потом lock будет разрушен в конце функции —
            // однако клиенту надо «держать» lock до REQ_CLOSE, поэтому
            // сохраняем его в глобальном контейнере.
            activeReadLocks_[empId].push_back(std::make_shared<std::shared_lock<std::shared_mutex>>(lock));
            SendEmployee(e);
        }
        else if (type == MsgType::REQ_WRITE) {
            // exclusive (write) lock
            std::unique_lock<std::shared_mutex> lock(locks_[empId]);
            activeWriteLocks_[empId] = std::make_shared<std::unique_lock<std::shared_mutex>>(lock);
            SendEmployee(e);
        }
        else if (type == MsgType::REQ_CLOSE) {
            // client wants to release lock (read or write). В этом упрощённом варианте
            // мы просто стираем сохранённые shared/unique_lock объекты.
            if (activeWriteLocks_.count(empId)) {
                activeWriteLocks_.erase(empId);
                SendOk();
            } else if (activeReadLocks_.count(empId)) {
                activeReadLocks_.erase(empId);
                SendOk();
            } else {
                SendError(400, "No lock held for this ID");
            }
        }
    }

    void ProcessCommit(Employee* newRec)
    {
        // write‑lock *должна* быть держана клиентом
        // (проверяем, есть ли уникальная блокировка в контейнере)
        if (!activeWriteLocks_.count(newRec->num)) {
            SendError(403, "Write lock not held for this record");
            return;
        }

        Employee* e = FindEmployee(newRec->num);
        if (!e) {
            SendError(404, "Employee not found");
            return;
        }
        // Обновляем в памяти
        *e = *newRec;
        SendOk();
    }

    // ---------------------- Хранилище активных блокировок ----------------------
    // Мы сохраняем shared/unique_lock в виде shared_ptr‑ов, чтобы они оставались живыми
    // пока клиент не отправит REQ_CLOSE.
    std::unordered_map<int32_t, std::shared_ptr<std::unique_lock<std::shared_mutex>>> activeWriteLocks_;
    std::unordered_map<int32_t, std::vector<std::shared_ptr<std::shared_lock<std::shared_mutex>>>> activeReadLocks_;
};

int main()
{
    std::cout << "Enter binary file name: ";
    std::string fileName;
    std::getline(std::cin, fileName);
    if (fileName.empty())
        fileName = "employees.dat";

    Server srv(fileName);
    if (!srv.Init())
        return 1;

    // 1) Сначала заполняем записи (можно вводить вручную)
    std::cout << "\n=== Ввод начальных записей ===\n";
    while (true) {
        Employee e{};
        std::cout << "ID (0 - finish): ";  int id; std::cin >> id;
        if (id == 0) break;
        e.num = id;
        std::cout << "Name (<=9 chars): ";  std::cin >> e.name;
        std::cout << "Hours: "; std::cin >> e.hours;
        // Добавляем в серверный массив
        // Прямо в объект Server: (можно добавить публичный метод)
        // Здесь просто пушим в локальный vector; после запуска сервера он будет
        // доступен клиенту.
        // Для упрощения делаем прямой доступ к полям:
        srv.records_.push_back(e);
        srv.id2idx_[e.num] = srv.records_.size() - 1;
        // Инициализируем блокировку (по умолчанию разблокирована)
        srv.locks_[e.num];
    }
    std::cin.ignore(); // очистка \n после последнего ввода

    std::cout << "\n=== Текущее содержимое файла ===\n";
    srv.PrintFile();

    // 2) Приём клиентских запросов
    srv.Run();

    // 3) Финальная печать и завершение
    srv.Shutdown();
    return 0;
}
```

