    uint32_t payloadSize;
};

struct ReqKey { int32_t employeeId; };
#pragma pack(pop)

#pragma pack(push,1)
struct Employee {
    int32_t num;
    char    name[10];
    double  hours;
};
#pragma pack(pop)

static const wchar_t* PIPE_NAME = L"\\\\.\\pipe\\EmployeePipe";

class Client {
public:
    bool Connect()
    {
        hPipe_ = CreateFileW(
            PIPE_NAME,
            GENERIC_READ | GENERIC_WRITE,
            0,
            nullptr,
            OPEN_EXISTING,
            0,
            nullptr);
        if (hPipe_ == INVALID_HANDLE_VALUE) {
            PrintError("CreateFile (connect to pipe)");
            return false;
        }
        // Устанавливаем режим сообщений (необязательно, но гарантирует
        // атомаризацию сообщений)
        DWORD mode = PIPE_READMODE_MESSAGE;
        if (!SetNamedPipeHandleState(hPipe_, &mode, nullptr, nullptr)) {
            PrintError("SetNamedPipeHandleState");
            CloseHandle(hPipe_);
            return false;
        }
        return true;
    }

    void Run()
    {
        while (true) {
            std::cout << "\n--- MENU ---\n"
                      << "1 – Read record\n"
                      << "2 – Write record\n"
                      << "0 – Exit client\n"
                      << "Select: ";
            int choice; std::cin >> choice;
            if (choice == 0) {
                // отправляем "shutdown" sentinel (id = -1) через REQ_CLOSE
                SendClose(-1);
                break;
            } else if (choice == 1) {
                HandleRead();
            } else if (choice == 2) {
                HandleWrite();
            } else {
                std::cout << "Invalid choice.\n";
            }
        }
    }

    void Disconnect()
    {
        if (hPipe_ != INVALID_HANDLE_VALUE)
            CloseHandle(hPipe_);
    }

private:
    HANDLE hPipe_ = INVALID_HANDLE_VALUE;

    // ------------------- Вспомогательные функции -------------------
    void SendHeader(MsgType type, uint32_t payloadSize = 0)
    {
        MessageHeader hdr{ type, payloadSize };
        WriteExact(hPipe_, &hdr, sizeof(hdr));
    }

    bool ReceiveHeader(MessageHeader& hdr)
    {
        return ReadExact(hPipe_, &hdr, sizeof(hdr));
    }

    void SendKey(int32_t id)
    {
        ReqKey key{ id };
        SendHeader(MsgType::REQ_READ, sizeof(key));
        WriteExact(hPipe_, &key, sizeof(key));
    }

    // ------------------- Меню --------------------------------------------------
    void HandleRead()
    {
        int32_t id = AskId();
        // запрос на чтение
        SendHeader(MsgType::REQ_READ, sizeof(ReqKey));
        ReqKey key{ id };
        WriteExact(hPipe_, &key, sizeof(key));

        // ждём ответ
        MessageHeader resp;
        if (!ReceiveHeader(resp)) { std::cerr << "Pipe closed.\n"; return; }

        if (resp.type == MsgType::RESP_DATA && resp.payloadSize == sizeof(Employee)) {
            Employee emp;
            ReadExact(hPipe_, &emp, sizeof(emp));
            PrintEmployee(emp);
            // снимаем read‑lock
            SendHeader(MsgType::REQ_CLOSE, sizeof(ReqKey));
            WriteExact(hPipe_, &key, sizeof(key));
            // ждём подтверждения
            ReceiveHeader(resp);
            if (resp.type == MsgType::RESP_OK) std::cout << "Read lock released.\n";
        } else {
            PrintErrorMessage(resp);
        }
    }

    void HandleWrite()
    {
        int32_t id = AskId();

        // запрос write‑lock
        SendHeader(MsgType::REQ_WRITE, sizeof(ReqKey));
        ReqKey key{ id };
        WriteExact(hPipe_, &key, sizeof(key));

        // получаем запись
        MessageHeader resp;
        if (!ReceiveHeader(resp)) { std::cerr << "Pipe closed.\n"; return; }

        if (resp.type != MsgType::RESP_DATA || resp.payloadSize != sizeof(Employee)) {
            PrintErrorMessage(resp);
            return;
        }

        Employee emp;
        ReadExact(hPipe_, &emp, sizeof(emp));
        std::cout << "Current record:\n";
        PrintEmployee(emp);

        // вводим новые значения
        std::cout << "Enter new name (<=9 chars, ENTER to KEEP): ";
        std::string newName;
        std::cin >> newName;
        if (!newName.empty())
            strncpy_s(emp.name, newName.c_str(), _TRUNCATE);
        std::cout << "Enter new hours (negative to KEEP): ";
        double newHours; std::cin >> newHours;
        if (newHours >= 0) emp.hours = newHours;

        // отправляем изменённую запись
        SendHeader(MsgType::REQ_COMMIT, sizeof(Employee));
        WriteExact(hPipe_, &emp, sizeof(emp));
        // ждём подтверждения
        ReceiveHeader(resp);
        if (resp.type == MsgType::RESP_OK) std::cout << "Record saved.\n";
        else PrintErrorMessage(resp);

        // снимаем write‑lock
        SendHeader(MsgType::REQ_CLOSE, sizeof(ReqKey));
        WriteExact(hPipe_, &key, sizeof(key));
        ReceiveHeader(resp);
        if (resp.type == MsgType::RESP_OK) std::cout << "Write lock released.\n";
    }

    void SendClose(int32_t sentinelId)
    {
        // REQ_CLOSE с id = -1 = "shutdown server"
        ReqKey key{ sentinelId };
        SendHeader(MsgType::REQ_CLOSE, sizeof(key));
        WriteExact(hPipe_, &key, sizeof(key));
        // Можно игнорировать ответ
        MessageHeader resp;
        ReceiveHeader(resp);
    }

    int32_t AskId()
    {
        std::cout << "Enter employee ID: ";
        int32_t id; std::cin >> id;
        return id;
    }

    void PrintEmployee(const Employee& e)
    {
        std::cout << "ID   : " << e.num << "\n"
                  << "Name : " << std::string(e.name,10) << "\n"
                  << "Hours: " << e.hours << "\n";
    }

    void PrintErrorMessage(const MessageHeader& hdr)
    {
        if (hdr.type == MsgType::RESP_ERR) {
            RespError err{};
            if (hdr.payloadSize >= sizeof(err))
                ReadExact(hPipe_, &err, sizeof(err));
            std::cerr << "Error (" << err.code << "): " << err.text << "\n";
        } else {
            std::cerr << "Unexpected response type.\n";
        }
    }
};

int main()
{
    Client cl;
    if (!cl.Connect())
        return 1;

    cl.Run();
    cl.Disconnect();
    return 0;
}
```

