    constexpr int64_t LIMIT    = 5000;       // target sum limit
    constexpr int MIN_VALUE   = 0;           // allowed range (change as needed)
    constexpr int MAX_VALUE   = std::numeric_limits<int>::max();

    std::vector<int> v;
    v.reserve(1024); // initial reservation to reduce reallocations

    int n;
    while (true) {
        int ret = std::scanf("%d", &n);
        if (ret == EOF) break;               // normal termination
        if (ret != 1) {                       // non‑numeric token
            std::fprintf(stderr, "Invalid input – non‑numeric token encountered.\n");
            std::exit(EXIT_FAILURE);
        }

        // Range check (adjust according to the problem statement)
        if (n < MIN_VALUE || n > MAX_VALUE) {
            std::fprintf(stderr,
                         "Input value %d out of allowed range [%d, %d].\n",
                         n, MIN_VALUE, MAX_VALUE);
            std::exit(EXIT_FAILURE);
        }

        // Enforce memory limit
        if (v.size() >= MAX_ELEMS) {
            std::fprintf(stderr, "Too many numbers – limit of %zu reached.\n", MAX_ELEMS);
            std::exit(EXIT_FAILURE);
