/* SPDX-License-Identifier: GPL-2.0 */
/*
 * mmap_demo.c  –  示例内核模块，演示通过 mmap 与用户空间共享一页内存
 *
 * 编译:  make -C /lib/modules/$(uname -r)/build M=$(pwd) modules
 * 加载:  sudo insmod mmap_demo.ko
