#include <linux/module.h>
#include <linux/fs.h>
#include <linux/mm.h>
#include <linux/slab.h>
#include <linux/uaccess.h>
#include <linux/cdev.h>
#include <linux/device.h>
#include <linux/highmem.h>
#include <linux/vmalloc.h>
#include <linux/sched.h>

#define DEV_NAME   "mmap_demo"
#define PAGE_ORDER 0          /* 2^0 = 1 page = 4KB */

/* -------------------------------------------------------------
 *  全局对象：字符设备 + 共享页
 * ------------------------------------------------------------- */
static dev_t dev_number;
static struct cdev cdev;
static struct class *cls;

/* 共享缓冲区：单独分配的物理页面 */
static struct page *shared_page;   /* 只读一次 alloc_pages() */
static void *vaddr;                /* 对应的内核虚拟地址，仅用于调试 */

/* -------------------------------------------------------------
 *  file_operations
 * ------------------------------------------------------------- */
static int mmap_demo_open(struct inode *inode, struct file *filp)
{
    /* 把共享 page 的指针放到 private_data，供 mmap 使用 */
    filp->private_data = shared_page;
    pr_info("[mmap_demo] open, pid=%d\n", current->pid);
    return 0;
}

static int mmap_demo_release(struct inode *inode, struct file *filp)
{
    pr_info("[mmap_demo] release, pid=%d\n", current->pid);
    filp->private_data = NULL;
    return 0;
}

/*
 * mmap 实现要点：
 *   1) 检查用户请求的映射长度是否超过我们准备的页面数。
 *   2) 通过 remap_pfn_range 把内核物理页映射到用户虚拟地址。
 *   3) 设置页面属性（PROT_READ/PROT_WRITE）对应内核页的权限。
 */
static int mmap_demo_mmap(struct file *filp, struct vm_area_struct *vma)
{
    unsigned long pfn;
    size_t size = vma->vm_end - vma->vm_start;
    struct page *page = filp->private_data;

    if (!page) {
        pr_err("[mmap_demo] mmap called with no page attached\n");
        return -ENODEV;
    }

    /* 只允许映射单页（4KB），如果用户请求更大直接拒绝 */
    if (size > PAGE_SIZE) {
        pr_err("[mmap_demo] request size %zu > %lu (PAGE_SIZE)\n",
               size, (unsigned long)PAGE_SIZE);
        return -EINVAL;
    }

    /* 检查映射属性：本例允许 rw，生产代码请根据需求严格控制 */
    if ((vma->vm_flags & VM_WRITE) && !(vma->vm_flags & VM_SHARED)) {
        /* 只写共享映射才安全，防止写时复制（COW）产生私有副本 */
        pr_err("[mmap_demo] writable mapping must be MAP_SHARED\n");
        return -EINVAL;
    }

    /* 取得物理页帧号 */
    pfn = page_to_pfn(page);

    /* 把页映射到用户空间 */
    if (remap_pfn_range(vma, vma->vm_start, pfn,
                        size, vma->vm_page_prot)) {
        pr_err("[mmap_demo] remap_pfn_range failed\n");
        return -EAGAIN;
    }

    pr_info("[mmap_demo] mmap succeeded pid=%d, size=%zu\n",
            current->pid, size);
    return 0;
}

/* 简单的 ioctl（可选），演示如何通过 ioctl 给用户一个 “魔数” */
#define MMAP_DEMO_GET_MAGIC _IOR('M', 0x01, __u32)

static long mmap_demo_ioctl(struct file *filp, unsigned int cmd,
                            unsigned long arg)
{
    __u32 magic = 0x5A5A5A5A;
    if (cmd == MMAP_DEMO_GET_MAGIC) {
        if (copy_to_user((void __user *)arg, &magic, sizeof(magic)))
            return -EFAULT;
        return 0;
    }
    return -ENOTTY;
}

/* -------------------------------------------------------------
 *  file_operations 结构体
 * ------------------------------------------------------------- */
static const struct file_operations mmap_demo_fops = {
    .owner   = THIS_MODULE,
    .open    = mmap_demo_open,
    .release = mmap_demo_release,
    .mmap    = mmap_demo_mmap,
    .unlocked_ioctl = mmap_demo_ioctl,
};

/* -------------------------------------------------------------
 *  模块加载 / 卸载
 * ------------------------------------------------------------- */
static int __init mmap_demo_init(void)
{
    int ret;

    /* 1) 分配一个字符设备号 */
    ret = alloc_chrdev_region(&dev_number, 0, 1, DEV_NAME);
    if (ret) {
        pr_err("[mmap_demo] alloc_chrdev_region failed %d\n", ret);
        return ret;
    }

    /* 2) 初始化 cdev */
    cdev_init(&cdev, &mmap_demo_fops);
    cdev.owner = THIS_MODULE;
    ret = cdev_add(&cdev, dev_number, 1);
    if (ret) {
        pr_err("[mmap_demo] cdev_add failed %d\n", ret);
        goto err_unregister_chrdev;
    }

    /* 3) 创建 /dev 节点（使用 class） */
    cls = class_create(THIS_MODULE, DEV_NAME);
    if (IS_ERR(cls)) {
        pr_err("[mmap_demo] class_create failed\n");
        ret = PTR_ERR(cls);
        goto err_del_cdev;
    }

    device_create(cls, NULL, dev_number, NULL, DEV_NAME);

    /* 4) 分配一页物理内存 */
    shared_page = alloc_pages(GFP_KERNEL | __GFP_ZERO, PAGE_ORDER);
    if (!shared_page) {
        pr_err("[mmap_demo] alloc_pages failed\n");
        ret = -ENOMEM;
        goto err_destroy_device;
    }
    vaddr = page_address(shared_page);   // 便于调试：在内核里直接访问

    /* 初始化页内容（演示） */
    snprintf(vaddr, PAGE_SIZE, "Hello from kernel! pid=%d\n", current->pid);

    pr_info("[mmap_demo] loaded, major=%d, minor=%d, page=%p\n",
            MAJOR(dev_number), MINOR(dev_number), vaddr);
    return 0;

err_destroy_device:
    device_destroy(cls, dev_number);
    class_destroy(cls);
err_del_cdev:
    cdev_del(&cdev);
err_unregister_chrdev:
    unregister_chrdev_region(dev_number, 1);
    return ret;
}

static void __exit mmap_demo_exit(void)
{
    if (shared_page)
        __free_pages(shared_page, PAGE_ORDER);

    device_destroy(cls, dev_number);
    class_destroy(cls);
    cdev_del(&cdev);
    unregister_chrdev_region(dev_number, 1);

    pr_info("[mmap_demo] unloaded\n");
}

module_init(mmap_demo_init);
module_exit(mmap_demo_exit);

MODULE_LICENSE("GPL");
MODULE_AUTHOR("Security Researcher <you@example.com>");
MODULE_DESCRIPTION("Demo of kernel <-> userspace communication via mmap");
MODULE_VERSION("1.0");
```

