## 2. 用户空间程序（`mmap_user.c`）

```c
/*
 * mmap_user.c – 使用 mmap 与内核模块共享页面的示例程序
 *
 * 编译:   gcc -Wall -O2 -o mmap_user mmap_user.c
 *
 * 运行:   sudo ./mmap_user
 *
 * 说明:
 *   - 需要对 /dev/mmap_demo 具备读写权限（示例中使用 chmod 666）。
 *   - 通过 mmap 获得的指针可以直接读写共享页。
 *   - 为演示安全问题，示例会尝试写入并再次读取，验证写回内核。
 */

#define _GNU_SOURCE
#include <stdio.h>
#include <stdlib.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/mman.h>
#include <string.h>
#include <errno.h>
#include <sys/ioctl.h>

#define DEV_PATH   "/dev/mmap_demo"
#define PAGE_SIZE  4096
#define MAGIC_IOCTL _IOR('M', 0x01, __u32)

int main(void)
{
    int fd;
    void *map;
    char *cmap;
    __u32 magic;

    /* 1) 打开字符设备 */
    fd = open(DEV_PATH, O_RDWR);
    if (fd < 0) {
        perror("open");
        return 1;
    }

    /* 2) 通过 ioctl 获取 “魔数”，演示控制通道 */
    if (ioctl(fd, MAGIC_IOCTL, &magic) == 0) {
        printf("[user] magic = 0x%08x\n", magic);
    } else {
        perror("ioctl");
    }

    /* 3) mmap 单页 */
    map = mmap(NULL, PAGE_SIZE, PROT_READ | PROT_WRITE,
               MAP_SHARED, fd, 0);
    if (map == MAP_FAILED) {
        perror("mmap");
        close(fd);
        return 1;
    }

    cmap = (char *)map;
    printf("[user] mmap returned address %p\n", cmap);
    printf("[user] initial content: \"%s\"\n", cmap);

    /* 4) 写入共享页 */
    const char *msg = "Hello from userspace!";
    strncpy(cmap, msg, PAGE_SIZE - 1);
    cmap[PAGE_SIZE - 1] = '\0';        // 防止越界

    /* 5) 立即读取验证（因为是共享映射，读取的就是我们刚写的） */
    printf("[user] after write: \"%s\"\n", cmap);

    /* 6) 同步回内核（可选） */
    if (msync(map, PAGE_SIZE, MS_SYNC) == -1) {
        perror("msync");
    }

    /* 7) 清理 */
    if (munmap(map, PAGE_SIZE) == -1) {
        perror("munmap");
    }
    close(fd);
    return 0;
}
```

