    return lstn;
}

/* Принимает новое соединение и добавляет его в массив клиентов */
static void accept_new_client(int lstn, client_t *clients, fd_set *master_set, int *max_fd)
{
    struct sockaddr_storage peer_addr;
    socklen_t peer_len = sizeof(peer_addr);
    int new_fd = accept(lstn, (struct sockaddr *)&peer_addr, &peer_len);
    if (new_fd == -1) {
        if (errno != EWOULDBLOCK && errno != EAGAIN)
            perror("accept");
        return;
    }

    /* Делим сокет неблокирующим, чтобы последующий recv/ send не блокировал */
    int flags = fcntl(new_fd, F_GETFL, 0);
    fcntl(new_fd, F_SETFL, flags | O_NONBLOCK);

    /* Находим свободный слот в массиве клиентов */
    for (int i = 0; i < MAX_CLIENTS; ++i) {
        if (clients[i].fd == -1) {
            clients[i].fd = new_fd;
            clients[i].buf_len = 0;
            FD_SET(new_fd, master_set);
            if (new_fd > *max_fd) *max_fd = new_fd;

            char host[NI_MAXHOST], serv[NI_MAXSERV];
            getnameinfo((struct sockaddr *)&peer_addr, peer_len,
                        host, sizeof(host), serv, sizeof(serv),
                        NI_NUMERICHOST | NI_NUMERICSERV);
            printf("Новое соединение: fd=%d, %s:%s\n", new_fd, host, serv);
            return;
        }
    }

    /* Если массив заполнен – отказываем в обслуживании */
    fprintf(stderr, "Слишком много клиентов, отклоняем fd=%d\n", new_fd);
    close(new_fd);
}

/* Обрабатывает данные от клиента (в этом примере – echo) */
static void handle_client_data(client_t *c, fd_set *master_set, int *max_fd)
{
    ssize_t n = recv(c->fd, c->buf + c->buf_len,
                     RECV_BUF_SIZE - c->buf_len, 0);
    if (n == -1) {
        if (errno != EWOULDBLOCK && errno != EAGAIN) {
            perror("recv");
            goto close_client;
        }
        return; // ничего не пришло, но сокет всё ещё жив
    }

    if (n == 0) {                       // клиент закрыл соединение
        printf("Клиент fd=%d закрыл соединение\n", c->fd);
        goto close_client;
    }

    c->buf_len += (size_t)n;

    /* В простейшем варианте сразу отсылаем всё полученное обратно */
    ssize_t sent = 0;
    while (sent < (ssize_t)c->buf_len) {
        ssize_t m = send(c->fd, c->buf + sent, c->buf_len - sent, 0);
        if (m == -1) {
            if (errno == EWOULDBLOCK || errno == EAGAIN) {
                /* Сокет пока не готов к записи – выдержим краткий тайм‑аут */
                usleep(1000);
                continue;
            }
            perror("send");
            goto close_client;
        }
        sent += m;
    }

    /* Очищаем буфер после успешной отправки */
    c->buf_len = 0;
    return;

close_client:
    FD_CLR(c->fd, master_set);
    if (c->fd == *max_fd) {
        /* Пересчитываем max_fd, т.к. текущий может исчезнуть */
        *max_fd = -1;
        for (int i = 0; i < MAX_CLIENTS; ++i)
            if (clients[i].fd > *max_fd) *max_fd = clients[i].fd;
    }
    close(c->fd);
    c->fd = -1;
    c->buf_len = 0;
}

/* ------------------------------- main ------------------------------- */
int main(int argc, char *argv[])
{
    if (argc != 3) {
        fprintf(stderr, "Usage: %s <listen_ip> <listen_port>\n", argv[0]);
        exit(EXIT_FAILURE);
    }

    int listener = create_listener(argv[1], argv[2]);
    if (listener == -1) exit(EXIT_FAILURE);

    /* Инициализируем массив клиентов */
    client_t clients[MAX_CLIENTS];
    for (int i = 0; i < MAX_CLIENTS; ++i) clients[i].fd = -1;

    fd_set master_set, read_set;
    FD_ZERO(&master_set);
    FD_SET(listener, &master_set);
    int max_fd = listener;

    printf("Сервер запущен, слушаем %s:%s (fd=%d)\n", argv[1], argv[2], listener);

    while (1) {
        read_set = master_set;   // select() изменяет набор, поэтому копируем

        /* Тайм‑аут 1 сек – можно использовать 0 для блокирующего ожидания */
        struct timeval tv = { .tv_sec = 1, .tv_usec = 0 };
        int ready = select(max_fd + 1, &read_set, NULL, NULL, &tv);
        if (ready == -1) {
            if (errno == EINTR) continue; // прерывание сигнала – просто перезапускаем
            perror("select");
            break;
        }

        if (ready == 0) {
            /* Нет активности – можно выполнять housekeeping (тайм‑ауты,
               очистку неактивных клиентов и т.п.). */
            continue;
        }

        /* 1. Приём новых соединений */
        if (FD_ISSET(listener, &read_set)) {
            accept_new_client(listener, clients, &master_set, &max_fd);
        }

        /* 2. Обрабатываем уже подключённых клиентов */
        for (int i = 0; i < MAX_CLIENTS; ++i) {
            if (clients[i].fd != -1 && FD_ISSET(clients[i].fd, &read_set)) {
                handle_client_data(&clients[i], &master_set, &max_fd);
            }
        }
    }

    /* Корректно закрываем сокеты */
    close(listener);
    for (int i = 0; i < MAX_CLIENTS; ++i)
        if (clients[i].fd != -1) close(clients[i].fd);

    return 0;
}
```

---

## Что здесь происходит?

| Шаг | Описание |
|-----|----------|
| **1.** `create_listener()` | Создаёт TCP‑слушающий сокет, делает его неблокирующим и начинает прослушивание. |
| **2.** `accept_new_client()` | При наличии входящего соединения (`select` сообщает о готовности `listener`) вызывается `accept()`. Новый клиент добавляется в массив `clients[]` и его дескриптор помещается в `master_set`. |
| **3.** `select()` | Ожидает готовности **любой** из дескрипторов в `master_set` (как слушающего, так и клиентских). Это и даёт «псевдо‑параллельность»: сервер переключается между клиентами, когда у кого‑то появляется данные. |
| **4.** `handle_client_data()` | Читает данные от клиента (неблокирующий `recv()`), в примере сразу отправляет их обратно (`echo`). При ошибке/разрыве соединения клиент удаляется из набора. |
| **5.** Главный цикл | Постоянно повторяет шаги 2‑4, поддерживая до `FD_SETSIZE` (обычно 1024) одновременных соединений без использования потоков. |

---

## Безопасностные соображения (что следует улучшить)

| Тема | Почему важно | Как исправить (кратко) |
|------|--------------|------------------------|
| **Ограничение размера буфера** | `recv()` может заполнить `buf` полностью, но клиент может дальше писать, вызывая переполнение. | Проверять `c->buf_len` и, если буфер полностью заполнен, отбрасывать дальнейшие данные или увеличивать буфер динамически (с проверкой `malloc`/`realloc`). |
| **Защита от DoS (много соединений)** | `select()` способен обслуживать только `FD_SETSIZE` дескрипторов; злоумышленник может открыть их все. | Ограничить `MAX_CLIENTS` небольшим числом, использовать очередь подключений, применять `iptables`/`fail2ban`, вести учёт количества запросов от одного IP. |
| **Тайм‑ауты бездействия** | Оставлять «мертвые» соединения открытыми позволяет злоумышленнику занять ресурсы. | Добавлять поле `last_activity` в `client_t` и периодически закрывать соединения, где с последнего чтения/записи прошло > N секунд. |
| **Обработка сигналов** | При получении `SIGINT`/`SIGTERM` сервер просто завершится, не закрыв сокеты корректно. | Установить обработчики сигналов, которые ставят флаг `volatile sig_atomic_t stop = 1;` и позволяют безопасно выйти из цикла. |
| **Логи и аудит** | Необходимо фиксировать попытки соединения, ошибки и потенциально вредоносные запросы. | Писать в `syslog`/файлы, использовать `logrotate`. |
| **Проверка входных данных** | Если сервер будет выполнять какие‑то команды, ввод надо валидировать. | Добавлять whitelist/blacklist, использовать парсинг протокола и проверять длину и формат. |

