gcc -Wall -Wextra -O2 -o simple_select_server simple_select_server.c

# 2. Запустить
./simple_select_server 0.0.0.0 12345 &

# 3. Подключиться несколькими клиентами (пример через netcat)
nc 127.0.0.1 12345
# введите любой текст → сервер отзовется тем же

# 4. Проверить, что сервер обслуживает нескольких клиентов одновременно
for i in {1..5}; do
    (echo "msg $i" | nc 127.0.0.1 12345 &) 
done
