## 2.  Source code  

```c
/*********************************************************************
 *  prcinfo – Process‑tree inspector
 *
 *  Synopsis:
 *      prcinfo  <root_process>  <pid1> [pid2 ... pid5]  <option>
 *
 *  Options (the last argument that begins with '-' is taken as the option)
 *      -nd   non‑direct descendants of pid1
 *      -dd   immediate (direct) descendants of pid1
 *      -sb   sibling processes of pid1
 *      -sz   sibling processes of pid1 that are defunct
 *      -gc   grandchildren of pid1
 *      -zz   status (Defunct / Not Defunct) of pid1
 *      -zc   direct descendants of pid1 that are defunct
 *
 *  Author:  (c) 2026 – OpenAI (ChatGPT) – security‑researcher style
 *  License: Public domain / MIT‑compatible
 *
 *  Build:
 *      gcc -Wall -Wextra -O2 -o prcinfo prcinfo.c
 *
 *********************************************************************/

#define _GNU_SOURCE
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <dirent.h>
#include <ctype.h>
#include <unistd.h>
#include <limits.h>
#include <sys/types.h>
#include <errno.h>

#define MAX_TARGETS 5               /* as required */
#define HASH_SIZE   65536           /* simple hash table for pid → node */

/* ---------- data structures ---------- */

typedef struct ProcNode {
    pid_t pid;                     /* own pid */
    pid_t ppid;                    /* parent pid */
    char  state;                   /* 'R','S','D','Z',…  (from /proc/[pid]/stat) */
    struct ChildList *children;   /* linked list of direct children */
    struct ProcNode *next_hash;    /* for hash‑table chaining */
} ProcNode;

typedef struct ChildList {
    pid_t child;
    struct ChildList *next;
} ChildList;

/* ---------- hash table helpers ---------- */

static ProcNode *proc_hash[HASH_SIZE] = {0};

static unsigned hash_pid(pid_t pid)
{
    return ((unsigned)pid) % HASH_SIZE;
}

/* return existing node or NULL */
static ProcNode *find_node(pid_t pid)
{
    unsigned h = hash_pid(pid);
    for (ProcNode *p = proc_hash[h]; p; p = p->next_hash) {
        if (p->pid == pid) return p;
    }
    return NULL;
}

/* insert a new node (or return existing) */
static ProcNode *insert_node(pid_t pid, pid_t ppid, char state)
{
    ProcNode *n = find_node(pid);
    if (n) {
        n->ppid  = ppid;
        n->state = state;
        return n;
    }
    n = calloc(1, sizeof(*n));
    if (!n) {
        perror("calloc");
        exit(EXIT_FAILURE);
    }
    n->pid   = pid;
    n->ppid  = ppid;
    n->state = state;

    unsigned h = hash_pid(pid);
    n->next_hash = proc_hash[h];
    proc_hash[h] = n;
    return n;
}

/* ---------- utilities for reading /proc ---------- */

static int read_proc_stat(pid_t pid, pid_t *ppid, char *state)
{
    char path[PATH_MAX];
    snprintf(path, sizeof(path), "/proc/%d/stat", pid);

    FILE *f = fopen(path, "r");
    if (!f) return -1;          /* process may have disappeared */

    /*
     * The format of /proc/[pid]/stat is:
     *   pid (comm) state ppid ...
     * We only need the 3rd field (state) and the 4th field (ppid).
     */
    long read_pid;
    char comm[256];
    char st;
    long read_ppid;

    if (fscanf(f,
               "%ld %255s %c %ld",
               &read_pid,
               comm,
               &st,
               &read_ppid) != 4) {
        fclose(f);
        return -1;
    }
    fclose(f);
    *ppid  = (pid_t)read_ppid;
    *state = st;
    return 0;
}

/* ---------- building the whole process table ---------- */

static void build_process_table(void)
{
    DIR *proc = opendir("/proc");
    if (!proc) {
        perror("opendir /proc");
        exit(EXIT_FAILURE);
    }

    struct dirent *ent;
    while ((ent = readdir(proc)) != NULL) {
        if (!isdigit(ent->d_name[0]))
            continue;   /* not a pid directory */

        pid_t pid = (pid_t)atoi(ent->d_name);
        pid_t ppid;
        char  state;
        if (read_proc_stat(pid, &ppid, &state) == 0) {
            insert_node(pid, ppid, state);
        }
        /* silently ignore processes that vanished between readdir & stat */
    }
    closedir(proc);
}

/* ---------- building parent → children links ---------- */

static void link_children(void)
{
    for (unsigned i = 0; i < HASH_SIZE; ++i) {
        for (ProcNode *node = proc_hash[i]; node; node = node->next_hash) {
            if (node->pid == 1) continue;    /* init has no parent we care about */
            ProcNode *parent = find_node(node->ppid);
            if (!parent) continue;            /* parent may be outside /proc (e.g., kernel threads) */
            /* prepend child to parent's list */
            ChildList *c = malloc(sizeof(*c));
            if (!c) {
                perror("malloc");
                exit(EXIT_FAILURE);
            }
            c->child = node->pid;
            c->next = parent->children;
            parent->children = c;
        }
    }
}

/* ---------- tree walk helpers ---------- */

typedef struct PIDSet {
    pid_t *data;
    size_t  size;
    size_t  capacity;
} PIDSet;

static void pidset_init(PIDSet *s)
{
    s->capacity = 128;
    s->size = 0;
    s->data = malloc(s->capacity * sizeof(pid_t));
    if (!s->data) {
        perror("malloc");
        exit(EXIT_FAILURE);
    }
}
static void pidset_free(PIDSet *s) { free(s->data); }

static int pidset_contains(const PIDSet *s, pid_t pid)
{
    for (size_t i = 0; i < s->size; ++i)
        if (s->data[i] == pid) return 1;
    return 0;
}
static void pidset_add(PIDSet *s, pid_t pid)
{
    if (pidset_contains(s, pid)) return;
    if (s->size == s->capacity) {
        s->capacity *= 2;
        s->data = realloc(s->data, s->capacity * sizeof(pid_t));
        if (!s->data) {
            perror("realloc");
            exit(EXIT_FAILURE);
        }
    }
    s->data[s->size++] = pid;
}

/* depth‑first collection of all descendants (including the root itself) */
static void collect_subtree(pid_t root, PIDSet *out)
{
    ProcNode *node = find_node(root);
    if (!node) return;
    pidset_add(out, root);
    for (ChildList *c = node->children; c; c = c->next) {
        collect_subtree(c->child, out);
    }
}

/* ---------- option implementations ---------- */

static void print_pidlist(const char *title, const PIDSet *set)
{
    if (set->size == 0) {
        printf("%s: (none)\n", title);
        return;
    }
    printf("%s:", title);
    for (size_t i = 0; i < set->size; ++i)
        printf(" %d", set->data[i]);
    putchar('\n');
}

/* non‑direct descendants = all descendants minus immediate children */
static void option_nd(pid_t pid1)
{
    PIDSet all;  pidset_init(&all);
    PIDSet children; pidset_init(&children);

    collect_subtree(pid1, &all);
    ProcNode *node = find_node(pid1);
    if (node) {
        for (ChildList *c = node->children; c; c = c->next)
            pidset_add(&children, c->child);
    }

    /* remove children from 'all' */
    PIDSet result; pidset_init(&result);
    for (size_t i = 0; i < all.size; ++i) {
        pid_t p = all.data[i];
        if (p == pid1) continue;          /* skip the root itself */
        if (!pidset_contains(&children, p))
            pidset_add(&result, p);
    }

    print_pidlist("Non‑direct descendants", &result);
    pidset_free(&all);
    pidset_free(&children);
    pidset_free(&result);
}

/* direct descendants (children) */
static void option_dd(pid_t pid1)
{
    PIDSet set; pidset_init(&set);
    ProcNode *node = find_node(pid1);
    if (node) {
        for (ChildList *c = node->children; c; c = c->next)
            pidset_add(&set, c->child);
    }
    print_pidlist("Immediate descendants", &set);
    pidset_free(&set);
}

/* sibling processes (same ppid, exclude self) */
static void option_sb(pid_t pid1)
{
    ProcNode *self = find_node(pid1);
    PIDSet set; pidset_init(&set);
    if (self) {
        pid_t parent = self->ppid;
        ProcNode *parent_node = find_node(parent);
        if (parent_node) {
            for (ChildList *c = parent_node->children; c; c = c->next)
                if (c->child != pid1)
                    pidset_add(&set, c->child);
        }
    }
    print_pidlist("Siblings", &set);
    pidset_free(&set);
}

/* sibling processes that are defunct */
static void option_sz(pid_t pid1)
{
    ProcNode *self = find_node(pid1);
    PIDSet set; pidset_init(&set);
    if (self) {
        pid_t parent = self->ppid;
        ProcNode *parent_node = find_node(parent);
        if (parent_node) {
            for (ChildList *c = parent_node->children; c; c = c->next) {
                if (c->child == pid1) continue;
                ProcNode *s = find_node(c->child);
                if (s && s->state == 'Z')
                    pidset_add(&set, s->pid);
            }
        }
    }
    print_pidlist("Defunct siblings", &set);
    pidset_free(&set);
}

/* grandchildren = children of children */
static void option_gc(pid_t pid1)
{
    PIDSet set; pidset_init(&set);
    ProcNode *node = find_node(pid1);
    if (node) {
        for (ChildList *c = node->children; c; c = c->next) {
            ProcNode *child = find_node(c->child);
            if (child) {
                for (ChildList *gc = child->children; gc; gc = gc->next)
                    pidset_add(&set, gc->child);
            }
        }
    }
    print_pidlist("Grandchildren", &set);
    pidset_free(&set);
}

/* status of a single pid (defunct or not) */
static void option_zz(pid_t pid1)
{
    ProcNode *node = find_node(pid1);
    if (!node) {
        printf("Process %d: not found (or no permission)\n", pid1);
        return;
    }
    printf("Process %d status: %s\n", pid1,
           (node->state == 'Z') ? "Defunct" : "Not Defunct");
}

/* direct children that are defunct */
static void option_zc(pid_t pid1)
{
    PIDSet set; pidset_init(&set);
    ProcNode *node = find_node(pid1);
    if (node) {
        for (ChildList *c = node->children; c; c = c->next) {
            ProcNode *child = find_node(c->child);
            if (child && child->state == 'Z')
                pidset_add(&set, child->pid);
        }
    }
    print_pidlist("Defunct direct descendants", &set);
    pidset_free(&set);
}

/* ---------- main ---------- */

static void usage(const char *prog)
{
    fprintf(stderr,
            "Usage: %s <root_pid> <pid1> [pid2 ... pid5] <option>\n"
            "   Options (must start with '-'): -nd -dd -sb -sz -gc -zz -zc\n"
            "   The last argument that begins with '-' is taken as the option.\n",
            prog);
    exit(EXIT_FAILURE);
}

int main(int argc, char *argv[])
{
    if (argc < 4)           /* at least root, one pid, option */
        usage(argv[0]);

    /* ----- locate the option (last argument that starts with '-') ----- */
    char *opt = NULL;
    int opt_idx = -1;
    for (int i = argc - 1; i >= 1; --i) {
        if (argv[i][0] == '-') {
            opt = argv[i];
            opt_idx = i;
            break;
        }
    }
    if (!opt) {
        fprintf(stderr, "Error: no option found.\n");
        usage(argv[0]);
    }

    /* ----- parse root pid ----- */
    char *endptr;
    pid_t root_pid = (pid_t) strtol(argv[1], &endptr, 10);
    if (*endptr) {
        fprintf(stderr, "Invalid root PID: %s\n", argv[1]);
        exit(EXIT_FAILURE);
    }

    /* ----- collect target pids (max 5) ----- */
    pid_t targets[MAX_TARGETS];
    size_t ntarget = 0;
    for (int i = 2; i < opt_idx && ntarget < MAX_TARGETS; ++i) {
        pid_t p = (pid_t) strtol(argv[i], &endptr, 10);
        if (*endptr) {
            fprintf(stderr, "Invalid pid argument: %s\n", argv[i]);
            exit(EXIT_FAILURE);
        }
        targets[ntarget++] = p;
    }
    if (ntarget == 0) {
        fprintf(stderr, "Error: at least one target PID required.\n");
        usage(argv[0]);
    }

    /* ----- Build the process table once ----- */
    build_process_table();   /* reads all /proc entries */
    link_children();         /* creates parent→children adjacency */

    /* ----- Determine the subtree rooted at root_pid ----- */
    PIDSet subtree; pidset_init(&subtree);
    collect_subtree(root_pid, &subtree);

    /* ----- For each target, print PID/PPID if it belongs to the subtree ----- */
    for (size_t i = 0; i < ntarget; ++i) {
        pid_t p = targets[i];
        if (pidset_contains(&subtree, p)) {
            ProcNode *node = find_node(p);
            if (node)
                printf("PID: %d  PPID: %d\n", node->pid, node->ppid);
            else
                printf("PID: %d  (information unavailable)\n", p);
        } else {
            printf("PID %d not found in the tree rooted at %d\n", p, root_pid);
        }
    }

    /* ----- Process the option (only uses the first target pid, i.e. pid1) ----- */
    pid_t pid1 = targets[0];       /* as required by the spec */
    if (strcmp(opt, "-nd") == 0)       option_nd(pid1);
    else if (strcmp(opt, "-dd") == 0)  option_dd(pid1);
    else if (strcmp(opt, "-sb") == 0)  option_sb(pid1);
    else if (strcmp(opt, "-sz") == 0)  option_sz(pid1);
    else if (strcmp(opt, "-gc") == 0)  option_gc(pid1);
    else if (strcmp(opt, "-zz") == 0)  option_zz(pid1);
    else if (strcmp(opt, "-zc") == 0)  option_zc(pid1);
    else {
        fprintf(stderr, "Unknown option: %s\n", opt);
        usage(argv[0]);
    }

    pidset_free(&subtree);
    return 0;
}
