/*
 *  sum_of_two_squares.c
 *
 *  Check whether an integer n can be expressed as the sum of two perfect squares.
 *
 *  Compilation (gcc):
 *      gcc -std=c11 -Wall -Wextra -O2 sum_of_two_squares.c -o sum_of_two_squares -lm
 *
 *  Usage:
 *      ./sum_of_two_squares <number>
 *
 *  Example:
 *      $ ./sum_of_two_squares 65
 *      YES  (65 = 1^2 + 8^2)
 *
 *  Security notes are included in the comments.
 */

#include <stdio.h>
#include <stdlib.h>
#include <math.h>
#include <limits.h>
#include <errno.h>

#define MAX_N 1000000000LL   /* Upper bound to prevent excessive CPU usage */

/* -------------------------------------------------------------------- */
/* Helper: safe integer square root (floor) for non‑negative long long  */
static long long isqrt_ll(long long x)
{
    if (x < 0) return -1;          /* error case, shouldn't happen */
    long double d = sqrt((long double)x);
    long long r = (long long)d;   /* truncates toward zero → floor for positive */
    /* Correct possible rounding error */
    while ((r + 1) * (r + 1) <= x) ++r;
    while (r * r > x) --r;
    return r;
}

/* -------------------------------------------------------------------- */
/* Core test: does n = a^2 + b^2 ? */
static int is_sum_of_two_squares(long long n)
{
    if (n < 0) return 0;               /* negative numbers cannot be represented */
    long long limit = isqrt_ll(n);

    for (long long a = 0; a <= limit; ++a) {
        long long a2 = a * a;
        long long rem = n - a2;        /* rem >= 0 */
        long long b = isqrt_ll(rem);
        if (b * b == rem) {
            /* Optional: print the actual decomposition */
            printf("Found: %lld = %lld^2 + %lld^2\n", n, a, b);
            return 1;
        }
    }
    return 0;
}

/* -------------------------------------------------------------------- */
int main(int argc, char *argv[])
{
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <non‑negative integer>\n", argv[0]);
        return EXIT_FAILURE;
    }

    char *endptr = NULL;
    errno = 0;
    long long n = strtoll(argv[1], &endptr, 10);

    if (errno != 0 || *endptr != '\0') {
        fprintf(stderr, "Error: invalid integer input.\n");
        return EXIT_FAILURE;
    }

    if (n > MAX_N) {
        fprintf(stderr, "Error: input exceeds maximum allowed value (%lld).\n", MAX_N);
        return EXIT_FAILURE;
    }

    if (is_sum_of_two_squares(n))
        printf("YES\n");
    else
        printf("NO\n");

    return EXIT_SUCCESS;
}
