 *  编译  ： gcc -Wall -Wextra -std=c11 -o calendar calendar.c     *
 ********************************************************************/
#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <inttypes.h>

typedef struct {
    int year;   /* 1 ~ 9999 */
    int month;  /* 1 ~ 12   */
    int day;    /* 1 ~ 31   */
} Date;

/* ------------------- 工具函数 ------------------- */

/* 检查年份、月份、日期是否合法（仅作基本范围检查） */
static int is_valid_date(const Date *d)
{
    if (d->year < 1 || d->year > 9999) return 0;
    if (d->month < 1 || d->month > 12) return 0;
    if (d->day < 1 || d->day > 31) return 0;
    return 1;
}

/* 把 Date 转成 time_t 并交给 mktime 进行正规化（自动处理闰年、月份天数等） */
static void normalize(Date *d)
{
    struct tm tm = {0};

    tm.tm_year = d->year - 1900;   /* tm_year 以 1900 为基准 */
    tm.tm_mon  = d->month - 1;     /* tm_mon 0‑11 */
    tm.tm_mday = d->day;
    tm.tm_isdst = -1;              /* 让库自行决定 DST */

    /* mktime 会把非法的日期（如 2023‑02‑30）调节成合法日期 */
    time_t t = mktime(&tm);
    if (t == (time_t)-1) {
        /* 极端错误（理论上不应该到这里） */
        fprintf(stderr, "内部错误：无法正规化日期！\n");
        exit(EXIT_FAILURE);
    }

    /* 重新取回正规化后的值 */
    localtime_r(&t, &tm);
    d->year  = tm.tm_year + 1900;
    d->month = tm.tm_mon + 1;
    d->day   = tm.tm_mday;
}

/* 增减年份 */
static void add_years(Date *d, int delta)
{
    d->year += delta;
    normalize(d);
}

/* 增减月份 */
static void add_months(Date *d, int delta)
{
    d->month += delta;
    /* 让 mktime 负责跨年/跨月的细节 */
    normalize(d);
}

/* 增减天数 */
static void add_days(Date *d, int delta)
{
    d->day += delta;
    normalize(d);
}

/* 打印当前日期 */
static void print_date(const Date *d)
{
    printf("%04d-%02d-%02d\n", d->year, d->month, d->day);
}

/* ------------------- 主程序 ------------------- */
int main(void)
{
    Date current = {0}, original = {0};

    /* ---------- 1. 输入初始日期 ---------- */
    printf("请输入初始日期（年 月 日），例如：1996 3 20\n");
    while (1) {
        if (scanf("%d %d %d", &current.year, &current.month, &current.day) != 3) {
            fprintf(stderr, "输入格式错误，请重新输入！\n");
            /* 清空输入缓冲区 */
            int ch; while ((ch = getchar()) != '\n' && ch != EOF);
            continue;
        }
        if (!is_valid_date(&current)) {
            fprintf(stderr, "日期范围错误，请确保：1≤年≤9999，1≤月≤12，1≤日≤31\n");
            continue;
        }
        /* 用 mktime 再次正规化一次，以防 1996-2-30 之类的非法组合 */
        normalize(&current);
        break;
    }

    /* 保存一份原始日期用于“重置” */
    original = current;

    /* ---------- 2. 菜单循环 ---------- */
    while (1) {
        printf("\n===== 万年历实验 =====\n");
        printf("当前日期："); print_date(&current);
        printf("请选择操作 (输入对应数字后回车)：\n");
        printf(" 1) 增加年份\n");
        printf(" 2) 减少年份\n");
        printf(" 3) 增加月份\n");
        printf(" 4) 减少月份\n");
        printf(" 5) 增加天数\n");
        printf(" 6) 减少天数\n");
        printf(" 7) 重置为最初输入的日期\n");
        printf(" 0) 退出程序\n");
        printf("您的选择: ");

        int choice;
        if (scanf("%d", &choice) != 1) {
            fprintf(stderr, "读取失败，请重新输入！\n");
            int ch; while ((ch = getchar()) != '\n' && ch != EOF);
            continue;
        }

        if (choice == 0) {
            printf("Bye!\n");
            break;
        }

        switch (choice) {
            case 1: {
                int n; printf("请输入要增加的年份数 (正整数)：");
                if (scanf("%d", &n) != 1 || n < 0) {
