 * ---------------------------------------------------------- */
static void lock_both_ordered(sem_t *first, sem_t *second,
                              const char *first_name,
                              const char *second_name)
{
    if (sem_wait(first) == -1) {
        perror("sem_wait first");
        return;
    }
    printf(">>> %s ZAJĘTY (pid=%d)\n", first_name, getpid());

    /* Mała sztuczna pauza, aby drugie procesy mogły przejąć drugi semafor */
    usleep(200000);   // 200 ms

    if (sem_wait(second) == -1) {
        perror("sem_wait second");
        /* Staramy się zwolnić pierwszy, żeby nie zostawić go w zajętości */
        sem_post(first);
        return;
    }
    printf(">>> %s ZAJĘTY (pid=%d)\n", second_name, getpid());

    printf(">>> Oba semafory zajęte – *działanie krytyczne* (pid=%d)\n", getpid());

