--------------------------------------------------------------------

#### Complexity Analysis  

Let  

* `L` be the total number of characters (including blanks) read after the
  first line,
* `C` be the number of categories,
* `Q_i` be the number of answer characters in category *i* (so
  `Σ Q_i ≤ L`).

The algorithm scans each character once ⇒ **O(L)** time.  
All auxiliary structures store one entry per category ⇒ **O(C)** memory,
which is at most **O(L)**.

--------------------------------------------------------------------

#### Reference Implementation  (C, ISO‑C99)

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <ctype.h>

typedef struct {
    char *answers;   // printed answer string (no blanks, no $)
    int  points;     // final points after joker handling
} Category;

/* read a whole line, return NULL on EOF */
static char *read_line(void) {
    size_t size = 0;
    char *buf = NULL;
    ssize_t len = getline(&buf, &size, stdin);
    if (len == -1) {
        free(buf);
        return NULL;
    }
    /* strip trailing newline */
    if (len > 0 && buf[len - 1] == '\n')
        buf[len - 1] = '\0';
    return buf;
}

int main(void) {
    int boundary;
    if (scanf("%d", &boundary) != 1)
        return 0;                       // no input
    /* consume the rest of the line after the integer */
    int c;
    while ((c = getchar()) != '\n' && c != EOF) {}

    Category *cat = NULL;
    size_t cat_cnt = 0, cat_cap = 0;

    int joker_used = 0;
    size_t joker_category = (size_t)-1;   // invalid by default

    char *line;
    while ((line = read_line()) != NULL) {
        /* allocate new category */
        if (cat_cnt == cat_cap) {
            cat_cap = cat_cap ? cat_cap * 2 : 4;
            cat = realloc(cat, cat_cap * sizeof(Category));
        }
        Category *cur = &cat[cat_cnt];
        cur->answers = NULL;
        size_t ans_cap = 0, ans_len = 0;
        cur->points = 0;

        int question_no = 1;   // 1‑based index inside this category

        for (size_t i = 0; line[i] != '\0'; ++i) {
            char ch = line[i];
            if (isspace((unsigned char)ch))
                continue;               // ignore blanks

            if (ch == '$') {
                if (!joker_used) {
                    joker_used = 1;
                    joker_category = cat_cnt;
                }
                continue;               // never stored nor scored
            }

            /* store printable answer character */
            if (ans_len + 1 >= ans_cap) {
                ans_cap = ans_cap ? ans_cap * 2 : 8;
                cur->answers = realloc(cur->answers, ans_cap);
            }
            cur->answers[ans_len++] = ch;

            /* scoring */
            if (ch == 'o') {
                if (question_no < boundary)
                    cur->points += 1;
                else
                    cur->points += 2;
            }
            /* x and - give 0 points */

            ++question_no;
        }

        /* terminate answer string */
        if (ans_len == 0) {
            cur->answers = NULL;
        } else {
            if (ans_len >= ans_cap) {
                ans_cap = ans_len + 1;
                cur->answers = realloc(cur->answers, ans_cap);
            }
            cur->answers[ans_len] = '\0';
        }

        free(line);
        ++cat_cnt;
    }

    /* --- apply joker ---------------------------------------------- */
    if (joker_used) {
        cat[joker_category].points *= 2;
    } else if (cat_cnt > 0) {
        cat[cat_cnt - 1].points *= 2;
    }

    /* --- compute totals --------------------------------------------- */
    long total = 0;
    for (size_t i = 0; i < cat_cnt; ++i)
        total += cat[i].points;

    size_t half_cnt = (cat_cnt + 1) / 2;          // ceil(N/2)
    long halftime = 0;
    for (size_t i = 0; i < half_cnt; ++i)
        halftime += cat[i].points;

    /* --- output ---------------------------------------------------- */
    for (size_t i = 0; i < cat_cnt; ++i) {
        if (cat[i].answers)
            puts(cat[i].answers);
        else
            puts("");               // empty line if no answer characters
    }
    printf("%ld %ld\n", halftime, total);

    /* free memory */
    for (size_t i = 0; i < cat_cnt; ++i)
        free(cat[i].answers);
    free(cat);
    return 0;
}
```

The program follows exactly the algorithm proven correct above and conforms
to the C99 standard. It reads from standard input until EOF, prints the
required answer lines and finally the halftime and total points.

