/* -------------------  Global data  --------------------------- */
#define MAX_ELEMS 1024                     /* hard‑limit for safety   */
static double g_numbers[MAX_ELEMS];        /* the values to average   */
static size_t g_count = 0;                  /* how many are filled    */

/* -------------------  Helper: safe add ---------------------- */
static int safe_add(double a, double b, double *out)
{
    /* Using double makes overflow practically impossible,
       but we still guard against NaN / Inf. */
    if (isnan(a) || isnan(b)) return -1;
    *out = a + b;
    if (isinf(*out)) return -1;
    return 0;
}

/* -------------------  The average function ------------------ */
void compute_and_print_average(void)
{
