/*
 *  libwebsockets + libuv WebSocket 客户端示例
 *  兼容 libwebsockets v4.x~v5.x，使用 libuv 做事件循环。
 *
 *  关键点：
 *   1. 用 LWS 创建一个 client_context，指定 uv 的 event loop 作为外部 loop。
 *   2. 通过 lws_client_connect_via_info() 发起连接。
 *   3. 在 LWS 回调中收发数据、处理 TLS、错误等。
 *   4. 通过 uv_run() / uv_stop() 驱动整个程序。
 *
 *  编译：
 *      mkdir build && cd build && cmake .. && make
 *
 *  运行（普通 WS）:
 *      ./ws_uv_client ws://echo.websocket.org:80
 *
 *  运行（安全 WS）:
 *      ./ws_uv_client wss://echo.websocket.org:443 ./cert/ca.crt
 *
 *  作者：安全研究员视角提供的示例代码
 */

#define _POSIX_C_SOURCE 200112L   /* for getaddrinfo */
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <assert.h>

#include <libwebsockets.h>
#include <uv.h>

/* --------------------------- 全局变量 --------------------------- */
static struct lws_context *g_ctx = NULL;     /* libwebsockets context               */
static struct lws *g_wsi = NULL;             /* 当前 WebSocket 实例                */
static uv_loop_t *g_uv_loop = NULL;          /* libuv 主循环                       */
static int g_exit_requested = 0;             /* 主循环退出标识                    */

/* --------------------------- 配置结构 --------------------------- */
typedef struct {
    const char *url;          /* ws://host:port/path 或 wss://... */
    const char *ca_path;      /* (optional) CA 证书路径，TLS 必要   */
    const char *protocol;     /* 协议子协议，可为空                 */
    const char *origin;       /* Origin 头，可为空                  */
} client_cfg_t;

/* --------------------------- LWS 回调 --------------------------- */
static int ws_client_cb(struct lws *wsi,
                        enum lws_callback_reasons reason,
                        void *user, void *in, size_t len)
{
    (void)user;   /* 本示例不使用 per-connection user data */

    switch (reason) {
    case LWS_CALLBACK_CLIENT_ESTABLISHED:
        printf("[+] WebSocket 已建立连接\n");
        /* 立即发送一条测试帧 */
        {
            const char *msg = "Hello from libuv+libwebsockets!";
            unsigned char *buf = (unsigned char *)lws_wsi_tx_get_buf(
                    wsi, LWS_PRE + strlen(msg));
            memcpy(buf + LWS_PRE, msg, strlen(msg));
            lws_write(wsi, buf + LWS_PRE, strlen(msg), LWS_WRITE_TEXT);
        }
        break;

    case LWS_CALLBACK_CLIENT_RECEIVE:
        printf("[<] 收到数据 (%zu bytes): %.*s\n", len, (int)len, (char *)in);
        break;

    case LWS_CALLBACK_CLIENT_WRITEABLE:
        /* 这里可以在需要时继续写数据，示例里不做额外处理 */
        break;

    case LWS_CALLBACK_CLIENT_CONNECTION_ERROR:
        printf("[-] 连接错误: %s\n", in ? (char *)in : "(no reason)");
        g_exit_requested = 1;
        break;

    case LWS_CALLBACK_CLIENT_CLOSED:
        printf("[*] 连接已关闭\n");
        g_exit_requested = 1;
        break;

    case LWS_CALLBACK_CLIENT_SSL_CERT_ERROR:
        printf("[-] TLS 证书验证错误: %s\n", (char *)in);
        /* 返回 0 => 继续（不安全），返回 -1 => 中止 */
        return -1;   /* 直接中止连接，防止 MITM */
        break;

    default:
        break;
    }
    return 0;
}

/* --------------------------- 协议表 --------------------------- */
static const struct lws_protocols protocols[] = {
    {
        .name = "default-protocol",      /* 必须与 client_cfg.protocol 匹配 */
        .callback = ws_client_cb,
        .per_session_data_size = 0,
        .rx_buffer_size = 0,
        .id = 0,
        .user = NULL,
        .tx_packet_size = 0,
    },
    { NULL, NULL, 0, 0, 0, NULL, 0 }      /* 结束标记 */
};

/* --------------------------- 创建 LWS Context --------------------------- */
static struct lws_context *create_lws_context(uv_loop_t *loop)
{
    struct lws_context_creation_info info;
    memset(&info, 0, sizeof(info));

    info.port = CONTEXT_PORT_NO_LISTEN;          /* Client 只需要一个 context，不监听端口 */
    info.protocols = protocols;
    info.options = LWS_SERVER_OPTION_DO_SSL_GLOBAL_INIT |
                   LWS_SERVER_OPTION_EXPLICIT_VHOSTS |
                   LWS_SERVER_OPTION_LIBUV;     /* 启用 libuv 兼容层 */
    info.fd_limit_per_thread = 1 + 64;          /* 调整 fd 限制（可选） */
    info.pt_serv_buf_size = 16 * 1024;          /* 发送缓冲区大小 */
    info.uv_loop = loop;                        /* 把 libuv 循环注入 LWS */

    struct lws_context *ctx = lws_create_context(&info);
    if (!ctx) {
        fprintf(stderr, "[-] 创建 libwebsockets context 失败\n");
        return NULL;
    }
    return ctx;
}

/* --------------------------- 发起连接 --------------------------- */
static int ws_client_connect(const client_cfg_t *cfg)
{
    struct lws_client_connect_info i;
    memset(&i, 0, sizeof(i));

    i.context = g_ctx;
    i.address = cfg->url;          /* URL 解析在后面手动处理 */
    i.port = 0;                    /* 让 libwebsockets 根据 scheme 自动解析 */
    i.path = "/";
    i.host = i.address;            /* Host Header */
    i.origin = cfg->origin ? cfg->origin : i.address;
    i.ssl_connection = 0;
    i.protocol = cfg->protocol ? cfg->protocol : "default-protocol";

    /* 解析 URL（scheme://host:port/path） */
    {
        char scheme[8] = {0}, hostport[256] = {0}, path[256] = {0};
        if (sscanf(cfg->url, "%7[^:]://%255[^/]/%255[^\n]",
                   scheme, hostport, path) < 2) {
            fprintf(stderr, "[-] URL 解析错误: %s\n", cfg->url);
            return -1;
        }

        /* 提取 host 与 port */
        char host[256] = {0};
        int port = 0;
        if (sscanf(hostport, "%255[^:]:%d", host, &port) == 2) {
            /* 已经带端口 */
        } else {
            strcpy(host, hostport);
            port = (strcmp(scheme, "wss") == 0) ? 443 : 80;
        }

        i.address = host;
        i.port = port;
        i.path = (*path) ? path : "/";
        i.host = host;          /* Host header */
        i.origin = cfg->origin ? cfg->origin : host;

        if (strcmp(scheme, "wss") == 0) {
            i.ssl_connection = LWS_SSL_ALLOW_INSECURE_CONNECTIONS; // 暂不强制验证（后面自行校验）
        }
    }

    /* TLS 证书校验（如果提供 CA） */
    if (cfg->ca_path && *cfg->ca_path) {
        i.ssl_connection = LWS_SSL_ENABLE_SERVER_CERT_HOSTNAME_CHECK |
                           LWS_SSL_ENABLE_CLIENT_CERT_VERIFICATION |
                           LWS_SSL_ALLOW_INSECURE_CONNECTIONS; /* 允许自签名时手动检查 */

        struct lws_ssl_capability *ssl_cap = lws_ssl_capability_new();
        if (!ssl_cap) {
            fprintf(stderr, "[-] 创建 SSL capability 失败\n");
            return -1;
        }
        ssl_cap->ca_filepath = cfg->ca_path;
        i.ssl_capability = ssl_cap;
    }

    g_wsi = lws_client_connect_via_info(&i);
    if (!g_wsi) {
        fprintf(stderr, "[-] 连接创建失败\n");
        return -1;
    }
    return 0;
}

/* --------------------------- 主函数 --------------------------- */
int main(int argc, char **argv)
{
    if (argc < 2) {
        printf("用法: %s <ws|wss>://host[:port]/[path] [ca_path]\n", argv[0]);
        return EXIT_FAILURE;
    }

    client_cfg_t cfg = {
        .url = argv[1],
        .ca_path = (argc >= 3) ? argv[2] : NULL,
        .protocol = NULL,   /* 如果服务器要求子协议，可在此填入 */
        .origin = NULL,
    };

    /* 1. 初始化 libuv 循环 */
    g_uv_loop = (uv_loop_t *)malloc(sizeof(uv_loop_t));
    uv_loop_init(g_uv_loop);

    /* 2. 创建 libwebsockets context（绑定到同一 uv loop） */
    g_ctx = create_lws_context(g_uv_loop);
    if (!g_ctx)
        return EXIT_FAILURE;

    /* 3. 发起 WebSocket 连接 */
    if (ws_client_connect(&cfg) != 0) {
        lws_context_destroy(g_ctx);
        uv_loop_close(g_uv_loop);
        free(g_uv_loop);
        return EXIT_FAILURE;
    }

    /* 4. 进入事件循环 */
    printf("[*] 进入 uv loop，等待事件…\n");
    while (!g_exit_requested) {
        /* uv_run 会调用 libwebsockets 内部的 uv_poll */
        uv_run(g_uv_loop, UV_RUN_DEFAULT);
        /* 若要手动驱动一次 lws_service 可以这样：
         *   lws_service(g_ctx, 0);
         */
    }

    /* 5. 清理 */
    lws_context_destroy(g_ctx);
    uv_loop_close(g_uv_loop);
    free(g_uv_loop);
    printf("[*] 客户端退出\n");
    return EXIT_SUCCESS;
}
