/*********************************************************************
 * 24 点游戏 – 最小复杂度树（回溯）实现
 * 作者  : 安全研究员（ChatGPT）
 * 说明  : 通过递归合并两数的方式穷举所有可能的运算树。
 *         只使用标准 C99，全部采用安全函数（snprintf、fabs）。
 * 编译  : gcc -std=c99 -Wall -Wextra -O2 -o game24 game24.c
 *********************************************************************/

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <math.h>

#define N 4                     // 输入数字个数（固定）
#define EPS 1e-6                // 浮点比较容差
#define EXPR_MAX 256            // 单个表达式字符串缓冲区大小

/* -----------------------------------------------------------------
 * 结构体：保存当前递归层的数值及对应的表达式
 * -----------------------------------------------------------------*/
typedef struct {
    double val;                 // 当前数值（double，便于除法）
    char expr[EXPR_MAX];        // 对应的中缀表达式（已加括号）
} Node;

/* -----------------------------------------------------------------
 * 递归搜索函数
 * 参数:
 *   nodes   - 当前剩余的节点数组（长度 cnt）
 *   cnt     - nodes 中有效元素个数
 *   outExpr - 成功时返回的完整表达式（调用者负责输出）
 * 返回:
 *   1  找到等于 24 的表达式
 *   0  未找到
 * -----------------------------------------------------------------*/
static int solve(Node nodes[], int cnt, char outExpr[EXPR_MAX])
{
    if (cnt == 1) {
        if (fabs(nodes[0].val - 24.0) < EPS) {
            /* 复制最终表达式 */
            strncpy(outExpr, nodes[0].expr, EXPR_MAX - 1);
            outExpr[EXPR_MAX - 1] = '\0';
            return 1;
        }
        return 0;
    }

    /* 对所有 unordered pair (i, j) 进行组合 */
    for (int i = 0; i < cnt; ++i) {
        for (int j = i + 1; j < cnt; ++j) {
            Node a = nodes[i];
            Node b = nodes[j];

            /* 生成一个新的数组，除去 i、j，保留其他 */
            Node next[N];
            int k = 0;
            for (int t = 0; t < cnt; ++t) {
                if (t != i && t != j) {
                    next[k++] = nodes[t];
                }
            }

            /* 下面依次尝试六种可能的二元运算（加、减、乘、除） */
            Node cand;    // 保存候选结果

            /* 1) a + b */
            cand.val = a.val + b.val;
            snprintf(cand.expr, EXPR_MAX, "(%s+%s)", a.expr, b.expr);
            next[k] = cand;
            if (solve(next, k + 1, outExpr)) return 1;

            /* 2) a - b */
            cand.val = a.val - b.val;
            snprintf(cand.expr, EXPR_MAX, "(%s-%s)", a.expr, b.expr);
            next[k] = cand;
            if (solve(next, k + 1, outExpr)) return 1;

            /* 3) b - a */
            cand.val = b.val - a.val;
            snprintf(cand.expr, EXPR_MAX, "(%s-%s)", b.expr, a.expr);
            next[k] = cand;
            if (solve(next, k + 1, outExpr)) return 1;

            /* 4) a * b */
            cand.val = a.val * b.val;
            snprintf(cand.expr, EXPR_MAX, "(%s*%s)", a.expr, b.expr);
            next[k] = cand;
            if (solve(next, k + 1, outExpr)) return 1;

            /* 5) a / b (b != 0) */
            if (fabs(b.val) > EPS) {
                cand.val = a.val / b.val;
                snprintf(cand.expr, EXPR_MAX, "(%s/%s)", a.expr, b.expr);
                next[k] = cand;
                if (solve(next, k + 1, outExpr)) return 1;
            }

            /* 6) b / a (a != 0) */
            if (fabs(a.val) > EPS) {
                cand.val = b.val / a.val;
                snprintf(cand.expr, EXPR_MAX, "(%s/%s)", b.expr, a.expr);
                next[k] = cand;
                if (solve(next, k + 1, outExpr)) return 1;
            }
        }
    }
    return 0;   // 所有组合均未成功
}

/* -----------------------------------------------------------------
 * 主函数：读取 4 个整数，调用 solve，输出结果或提示无解
 * -----------------------------------------------------------------*/
int main(void)
{
    int input[N];
    printf("请输入 4 个整数（空格或回车分隔）: ");

    /* 安全读取，确保恰好读取到 4 个整数 */
    if (scanf("%d %d %d %d", &input[0], &input[1],
              &input[2], &input[3]) != 4) {
        fprintf(stderr, "错误：请输入恰好 4 个整数。\n");
        return EXIT_FAILURE;
    }

    /* 初始化节点数组，每个节点的表达式就是自身的字符串 */
    Node start[N];
    for (int i = 0; i < N; ++i) {
        start[i].val = (double)input[i];
        snprintf(start[i].expr, EXPR_MAX, "%d", input[i]);
    }

    char answer[EXPR_MAX];
    if (solve(start, N, answer)) {
        printf("找到解： %s = 24\n", answer);
    } else {
        printf("抱歉，无法用四则运算得到 24。\n");
    }

    return EXIT_SUCCESS;
}
```

### 代码说明

| 位置 | 关键点 |
|------|--------|
| `Node` 结构体 | 同时保存数值和对应的完整表达式（已加括号），便于递归返回时直接拼接。 |
| `solve()` 递归 | 采用 **pair‑wise 合并** 的方式遍历所有二叉树结构，最大递归深度 3（常数），时间复杂度约 `O(1)`。 |
| `snprintf` | 防止缓冲区溢出，自动截断至 `EXPR_MAX-1`。 |
| `EPS` 检查 | 浮点除法前检查除数是否接近 0，防止 `NaN`/`Inf`。 |
| `main()` 输入检查 | `scanf` 返回值校验确保读取到四个整数，否则提前退出。 |

