/*
 *  Repetitious‑Numbers Counter
 *  -----------------------------------------
 *  Reads a sequence of integers and tells you how many *different*
 *  numbers appear more than once.
 *
 *  Compile (example):
 *      gcc -std=c99 -Wall -Wextra -O2 repetitious.c -o repetitious
 *
 *  Run:
 *      ./repetitious
 *
 *  Author:  (your name)
 *  License:  Public Domain / MIT – feel free to reuse.
 */

#include <stdio.h>
#include <stdlib.h>
#include <errno.h>
#include <string.h>

/* ------------------------------------------------------------------ */
/* Configuration ---------------------------------------------------- */
/* ------------------------------------------------------------------ */

/* Set to 1 if you also want to see which numbers repeated and how many
   times they occurred.  Set to 0 to get only the total count. */
#define SHOW_DETAILS 1

/* ------------------------------------------------------------------ */
/* Helper: comparison function for qsort() --------------------------- */
/* ------------------------------------------------------------------ */
static int cmp_int(const void *a, const void *b)
{
    const int ia = *(const int *)a;
    const int ib = *(const int *)b;
    if (ia < ib) return -1;
    if (ia > ib) return +1;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Main ------------------------------------------------------------- */
/* ------------------------------------------------------------------ */
int main(void)
{
    size_t n = 0;          /* how many numbers the user will give */
    printf("Enter how many integers you will input: ");
    if (scanf("%zu", &n) != 1) {
        fprintf(stderr, "Failed to read the count.\n");
        return EXIT_FAILURE;
    }

    if (n == 0) {
        printf("No numbers to process.\n");
        return EXIT_SUCCESS;
    }

    /* Allocate space for the numbers */
    int *arr = malloc(n * sizeof(int));
    if (!arr) {
        perror("malloc");
        return EXIT_FAILURE;
    }

    /* Read the numbers */
    printf("Enter %zu integer(s) separated by spaces or newlines:\n", n);
    for (size_t i = 0; i < n; ++i) {
        if (scanf("%d", &arr[i]) != 1) {
            fprintf(stderr, "Error: expected integer %zu.\n", i + 1);
            free(arr);
            return EXIT_FAILURE;
        }
    }

    /* Sort the array – identical numbers become neighbours */
    qsort(arr, n, sizeof(int), cmp_int);

    /* Scan the sorted array and collect repetitions */
    size_t repeatKinds = 0;          /* how many distinct values repeat */
    size_t repeatTotal = 0;          /* total amount of repeated entries (optional) */
    size_t capacity = 0;             /* capacity of detail arrays */
    int *repVals = NULL;             /* values that repeat (if SHOW_DETAILS) */
    size_t *repCnt = NULL;           /* how many times each repeated value appears */

    for (size_t i = 0; i < n; ) {
        size_t j = i + 1;
        while (j < n && arr[j] == arr[i])
            ++j;                     /* j now points to the first different element */

        size_t count = j - i;        /* how many times arr[i] occurs */

        if (count >= 2) {
            ++repeatKinds;
            repeatTotal += count;

            if (SHOW_DETAILS) {
                if (repeatKinds > capacity) {
                    /* grow the detail arrays (simple exponential growth) */
                    capacity = capacity ? capacity * 2 : 4;
                    repVals = realloc(repVals, capacity * sizeof(int));
                    repCnt  = realloc(repCnt, capacity * sizeof(size_t));
                    if (!repVals || !repCnt) {
                        perror("realloc");
                        free(arr);
                        free(repVals);
                        free(repCnt);
                        return EXIT_FAILURE;
                    }
                }
                repVals[repeatKinds - 1] = arr[i];
                repCnt[repeatKinds - 1]  = count;
            }
        }
        i = j;                       /* continue scanning from the next distinct value */
    }

    /* --------------------------------------------------------------- */
    /* Output ---------------------------------------------------------- */
    /* --------------------------------------------------------------- */
    printf("\n--- Result -------------------------------------------------\n");
    printf("Distinct numbers that repeated: %zu\n", repeatKinds);
    if (repeatKinds == 0) {
        printf("No repetitions found.\n");
    } else {
#if SHOW_DETAILS
        printf("Details (value : occurrences):\n");
        for (size_t k = 0; k < repeatKinds; ++k) {
            printf("  %d : %zu\n", repVals[k], repCnt[k]);
        }
#endif
        printf("Total amount of repeated entries (including first occurrences): %zu\n",
               repeatTotal);
    }

    /* Clean up */
    free(arr);
    free(repVals);
    free(repCnt);
    return EXIT_SUCCESS;
}
```

