#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <ctype.h>

typedef struct Node {
    int data;
    struct Node *next;
} Node;

/* create a new node */
static Node *new_node(int value) {
    Node *p = (Node *)malloc(sizeof(Node));
    if (!p) {
        perror("malloc");
        exit(EXIT_FAILURE);
    }
    p->data = value;
    p->next = NULL;
    return p;
}

/* append a node to the tail of the list */
static void append_tail(Node **head, Node **tail, int value) {
    Node *p = new_node(value);
    if (*head == NULL) {          // first element
        *head = *tail = p;
    } else {
        (*tail)->next = p;
        *tail = p;
    }
}

/* reverse a singly linked list (nodes, not data) */
static Node *reverse_list(Node *head) {
    Node *prev = NULL;
    Node *cur  = head;
    while (cur) {
        Node *next = cur->next;
        cur->next = prev;
        prev = cur;
        cur = next;
    }
    return prev;                  // new head
}

/* print list elements separated by a single space */
static void print_list(Node *head) {
    for (Node *p = head; p != NULL; p = p->next) {
        if (p != head) putchar(' ');
        printf("%d", p->data);
    }
    putchar('\n');
}

/* ----- main --------------------------------------------------- */
int main(void) {
    /* read the whole input (it is short) */
    char *input = NULL;
    size_t len = 0;
    ssize_t nread = getline(&input, &len, stdin);
    if (nread == -1) {            // empty input
        printf("NULL\n");
        free(input);
        return 0;
    }

    Node *head = NULL, *tail = NULL;

    /* tokenize by whitespace */
    const char *delim = " \t\r\n";
    char *token = strtok(input, delim);
    while (token) {
        if (strcmp(token, ".") == 0)          // terminator
            break;

        /* try to convert the whole token to an integer */
        char *endptr;
        long val = strtol(token, &endptr, 10);
        if (*endptr == '\0') {                // full conversion succeeded
            append_tail(&head, &tail, (int)val);
        }
        /* else: incorrect token – silently ignore */

        token = strtok(NULL, delim);
    }

    free(input);

    if (head == NULL) {          // empty list
        printf("NULL\n");
        return 0;
    }

    head = reverse_list(head);
    print_list(head);

    /* free memory */
    while (head) {
        Node *tmp = head;
        head = head->next;
        free(tmp);
    }

    return 0;
}
```

