## 2. Полный исходный код

```c
/*  resistor_finder.c
 *
 *  Console utility for Windows (MSVC/MinGW) that prints a combination of
 *  standard E‑12 resistors which gives the required resistance.
 *
 *  Build (MinGW):
 *      gcc -Wall -Wextra -O2 resistor_finder.c -o resistor_finder.exe
 *
 *  Build (MSVC):
 *      cl /W4 /O2 resistor_finder.c
 *
 *  author:  security researcher (ChatGPT)
 *  date:    2024‑06
 */

#define _CRT_SECURE_NO_WARNINGS  // для VS – отключаем предупреждения о scanf

#include <stdio.h>
#include <stdlib.h>
#include <math.h>
#include <string.h>

#define MAX_RESISTORS   1024   // максимальное количество разных номиналов в массиве
#define MAX_COMBINATION 64    // достаточно для практических целей

/* ---------- 1. Стандартные номиналы (E‑12) ---------- */
static const int e12_values[] = {
    10, 12, 15, 18, 22, 27, 33, 39, 47, 56, 68, 82
};
static const int e12_cnt = sizeof(e12_values) / sizeof(e12_values[0]);

/* ---------- 2. Хранилище всех резисторов, которые будем использовать ---------- */
static long long resistor_list[MAX_RESISTORS];
static int resistor_cnt = 0;

/* Добавляем в список все варианты: base*10^k, где base – из e12, k = … */
static void build_resistor_list(double target_ohm)
{
    /* Мы будем хранить сопротивление в микромилли‑омах (µΩ = 1e-6 Ω) –
     * это позволяет удобно работать с целыми числами, но без переполнения
     * для диапазона до 10 МΩ (10^7 Ω) => 10^13 µΩ < 2^63. */
    const long long ONE_UOHM = 1000000LL;    // 1 Ω = 1 000 000 µΩ
    const long long MAX_UOHM = (long long)(target_ohm * ONE_UOHM * 10.0); // 10×запас

    long long multiplier = ONE_UOHM;   // 1 Ω в µΩ
    for (int decade = -2; decade <= 7; ++decade)   // от 0.01 Ω до 10 MΩ (запас)
    {
        for (int i = 0; i < e12_cnt; ++i) {
            long long val = (long long)round(e12_values[i] * multiplier);
            if (val <= 0) continue;
            if (val > MAX_UOHM) continue;    // слишком большой, дальше не будем
            resistor_list[resistor_cnt++] = val;
        }
        multiplier *= 10LL;   // переходим к следующей декаде
    }

    /* Сортируем по убыванию – удобно для DFS (берём больший резистор первым) */
    for (int i = 0; i < resistor_cnt - 1; ++i) {
        for (int j = i + 1; j < resistor_cnt; ++j) {
            if (resistor_list[i] < resistor_list[j]) {
                long long tmp = resistor_list[i];
                resistor_list[i] = resistor_list[j];
                resistor_list[j] = tmp;
            }
        }
    }
}

/* ---------- 3. Поиск комбинации ---------- */
static long long target_uohm;                         // требуемое сопротивление в µΩ
static int best_depth = INT_MAX;                     // минимум резисторов найденный пока
static long long best_combination[MAX_COMBINATION]; // лучший набор
static int   best_counts[MAX_COMBINATION];           // сколько штук каждого номинала

/* Текущее состояние DFS */
static long long cur_combination[MAX_COMBINATION];
static int   cur_counts[MAX_COMBINATION];
static int   cur_depth = 0;

/* Прототип рекурсии */
static void dfs(int idx, long long cur_sum);

static void dfs(int idx, long long cur_sum)
{
    /* Достигли требуемой суммы? */
    if (cur_sum == target_uohm) {
        if (cur_depth < best_depth) {
            best_depth = cur_depth;
            memcpy(best_combination, cur_combination, sizeof(long long) * cur_depth);
            memcpy(best_counts,      cur_counts,   sizeof(int)   * cur_depth);
        }
        return;
    }

    if (cur_depth >= best_depth) return;   // уже хуже лучшего

    if (idx >= resistor_cnt) return;       // перебрали все варианты

    long long resistor = resistor_list[idx];
    long long max_possible = cur_sum + resistor * (target_uohm - cur_sum) / resistor;
    if (max_possible < target_uohm) {
        /* Даже если взять этот резистор бесконечно, не сможем дотянуться */
        return;
    }

    /* Попытка взять N штук текущего резистора (от большего к меньшему) */
    int max_qty = (int)((target_uohm - cur_sum) / resistor);
    for (int qty = max_qty; qty >= 0; --qty) {
        if (qty > 0) {
            cur_combination[cur_depth] = resistor;
            cur_counts[cur_depth] = qty;
            ++cur_depth;
        }

        long long new_sum = cur_sum + resistor * qty;
        if (new_sum <= target_uohm) {
            dfs(idx + 1, new_sum);
        }

        if (qty > 0) {
            --cur_depth;   // откатываем добавленный элемент
        }
    }
}

/* ---------- 4. Вывод результата ---------- */
static void print_result(void)
{
    if (best_depth == INT_MAX) {
        printf("Комбинацию невозможно собрать из стандартных резисторов E‑12.\n");
        return;
    }

    printf("Найдено %d резисторов:\n", best_depth);
    for (int i = 0; i < best_depth; ++i) {
        double ohm = (double)best_combination[i] / 1e6; // µΩ → Ω
        if (best_counts[i] == 1)
            printf("  1 × %.3g Ω\n", ohm);
        else
            printf("  %d × %.3g Ω\n", best_counts[i], ohm);
    }

    /* Сводим в одну строку вида 2*5.1Ω + 1*0.02Ω */
    printf("Итого: ");
    int first = 1;
    for (int i = 0; i < best_depth; ++i) {
        double ohm = (double)best_combination[i] / 1e6;
        if (!first) printf(" + ");
        if (best_counts[i] == 1)
            printf("%.3gΩ", ohm);
        else
            printf("%d*%.3gΩ", best_counts[i], ohm);
        first = 0;
    }
    printf("\n");
}

/* ---------- 5. main ---------- */
int main(void)
{
    double input_resistance;
    printf("Введите требуемое сопротивление (Ом, можно с дробью): ");
    if (scanf("%lf", &input_resistance) != 1) {
        fprintf(stderr, "Ошибка ввода!\n");
        return 1;
    }
    if (input_resistance <= 0.0) {
        fprintf(stderr, "Сопротивление должно быть положительным числом.\n");
        return 1;
    }

    /* Переводим в микромилли‑омы (µΩ) – 1 Ω = 1 000 000 µΩ */
    target_uohm = (long long) llround(input_resistance * 1e6);
    build_resistor_list(input_resistance);
    if (resistor_cnt == 0) {
        fprintf(stderr, "Не удалось сформировать список стандартных резисторов.\n");
        return 1;
    }

    dfs(0, 0);
    print_result();

    return 0;
}
```

