int utf8_substring(const char *src,
                   size_t from_char,   /* 1‑based! 3 → третий символ */
                   size_t to_char,     /* включительно */
                   char **out)         /* [out] выделенный буфер */
{
    if (!src || !out) return -1;

    /* 1. Устанавливаем локаль, чтобы мб‑функции понимали UTF‑8 */
    if (!setlocale(LC_CTYPE, "")) {
