    mbstate_t state;
    memset(&state, 0, sizeof(state));

    size_t i = 0;                 /* текущий индекс в байтах */
    size_t char_no = 0;           /* номер текущего символа (1‑based) */
    size_t start_byte = (size_t)-1;   /* смещение начала подстроки */
    size_t end_byte   = (size_t)-1;   /* смещение **последнего** байта +1 */

