 *      gcc -Wall -Wextra -pedantic -std=c11 -O2 nok2.c -o nok2
 *
 *  Example run (matches the specification):
 *      $ ./nok2
 *      A:10
 *      B:20
 *      C:30
 *      D:40
 *      NOK(a,b): 20
 *      NOK(a,c): 30
 *      NOK(a,d): 40
 */

#include <stdio.h>
#include <stdint.h>
#include <inttypes.h>
#include <stdlib.h>
#include <errno.h>
#include <limits.h>

/* ---------- Helper: safe multiplication with overflow detection ---------- */
static int safe_mul_int64(int64_t a, int64_t b, int64_t *out)
{
    /* Both operands are non‑negative after we take absolute values,
       so we can work with unsigned arithmetic for the overflow test. */
    if (a == 0 || b == 0) {
        *out = 0;
        return 1;
    }

    if (a > INT64_MAX / b)   /* overflow would occur */
        return 0;

    *out = a * b;
    return 1;
}

/* --------------------------- GCD (Euclidean) --------------------------- */
static int64_t gcd_int64(int64_t a, int64_t b)
{
    /* Work with non‑negative numbers – sign does not affect GCD */
    if (a < 0) a = -a;
    if (b < 0) b = -b;

    while (b != 0) {
        int64_t r = a % b;
        a = b;
        b = r;
    }
    return a;
}

/* ------------------------ LCM – the NOK2 function ----------------------- */
static int64_t NOK2(int64_t a, int64_t b)
{
    /* LCM(0, x) == 0, LCM(x, 0) == 0 – definition used by most languages */
    if (a == 0 || b == 0)
        return 0;

    int64_t g = gcd_int64(a, b);           /* GCD is always positive */
    int64_t a_div_g = a / g;                /* division first – no overflow */

    int64_t lcm;
    if (!safe_mul_int64(a_div_g, b, &lcm)) {
        /* In a production system we would signal the error more clearly.
           Here we abort with a diagnostic message. */
        fprintf(stderr,
                "Error: overflow while computing LCM(%"
                PRId64 ",%" PRId64 ")\n",
                a, b);
        exit(EXIT_FAILURE);
    }

    /* Ensure the result is non‑negative (LCM is defined as positive) */
    if (lcm < 0) lcm = -lcm;
    return lcm;
}

/* ---------------------------- Input helper ------------------------------ */
static int64_t read_int64(const char *prompt)
{
    char line[256];
    int64_t value;
    char *endptr;

    while (1) {
        printf("%s", prompt);
        if (!fgets(line, sizeof(line), stdin)) {
            /* EOF or read error */
            fprintf(stderr, "Input error. Exiting.\n");
            exit(EXIT_FAILURE);
        }

        errno = 0;
        value = strtoll(line, &endptr, 10);
        if (errno == ERANGE) {
            fprintf(stderr, "Number out of range. Try again.\n");
            continue;
        }
        /* Skip trailing whitespace */
        while (*endptr && (*endptr == ' ' || *endptr == '\t' || *endptr == '\n'))
            ++endptr;

        if (*endptr != '\0') {
            fprintf(stderr, "Invalid characters in input. Try again.\n");
            continue;
        }
        return value;
    }
}

/* ------------------------------- main ----------------------------------- */
int main(void)
{
    /* Read the four numbers */
    int64_t A = read_int64("A:");
    int64_t B = read_int64("B:");
    int64_t C = read_int64("C:");
    int64_t D = read_int64("D:");

    /* Compute the three LCMs using NOK2 */
    int64_t lcm_ab = NOK2(A, B);
    int64_t lcm_ac = NOK2(A, C);
    int64_t lcm_ad = NOK2(A, D);

    /* Output exactly as required */
    printf("NOK(a,b): %"
           PRId64 "\n", lcm_ab);
    printf("NOK(a,c): %"
           PRId64 "\n", lcm_ac);
    printf("NOK(a,d): %"
           PRId64 "\n", lcm_ad);

    return 0;
}
```

---

## Why This Implementation Is “Secure”

| Threat / Issue                              | Mitigation in the code                                                               |
|--------------------------------------------|--------------------------------------------------------------------------------------|
| **Integer overflow** (product of two large numbers) | The multiplication is performed **after** dividing by `gcd`, and `safe_mul_int64` checks for overflow **before** it happens. |
| **Negative inputs** – LCM is defined for natural numbers | `NOK2` converts the inputs to absolute values for the GCD step and forces a non‑negative result. |
| **Invalid or malicious user input**       | `read_int64` loops until a valid 64‑bit integer is provided, rejecting non‑numeric characters and out‑of‑range values. |
| **Buffer overflow on input**               | `fgets` reads at most 255 characters into a static buffer, guaranteeing null‑termination. |
| **Undefined behaviour (division by zero)**| `NOK2` explicitly returns `0` when either argument is `0`, avoiding a division‑by‑zero trap. |
| **Potential information leakage via crashes** | Errors are reported to `stderr` with a clear message; the program exits cleanly (`exit(EXIT_FAILURE)`). |

---

## How to Test It Quickly

```bash
$ gcc -Wall -Wextra -pedantic -std=c11 -O2 nok2.c -o nok2
$ ./nok2
A:10
B:20
C:30
D:40
NOK(a,b): 20
NOK(a,c): 30
NOK(a,d): 40
```

Try edge‑cases:

| Input (`A B C D`) | Expected LCMs (`A,B`, `A,C`, `A,D`) |
|--------------------|--------------------------------------|
| `0 5 7 9`          | `0 0 0` (any LCM with zero is zero) |
| `-12 18 5 -6`      | `36 60 12` (signs are ignored)      |
| `9223372036854775807 1 2 3` | `9223372036854775807 18446744073709551614 (overflow) → program aborts with error` |

The last line demonstrates overflow detection – the program refuses to produce an incorrect value and terminates with an error message.

--- 

**That’s the complete, security‑aware solution in C.** Feel free to integrate the `NOK2` function into larger projects; just remember to keep the overflow checks if you work with values that can approach the limits of `int64_t`.

