## 1️⃣  Full Source (C99)

```c
/*********************************************************************
 *  Binary search on a file of sorted student records
 *  -------------------------------------------------
 *  - Reads up to 10 records from "student.txt"
 *  - Prompts the user for a student number
 *  - Finds the record with a binary search
 *  - Prints name, grade and the position in the array
 *
 *  Security‑researcher notes are embedded as comments.
 *********************************************************************/

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <limits.h>   /* for INT_MAX, INT_MIN */

#define MAX_RECORDS   10          /* we only allocate space for 10 */
#define NAME_MAXLEN   10          /* as in the original struct */
#define FILE_PATH     "C:\\cmpe231\\2009Spring\\student.txt"

/* ------------------------------------------------------------------
 *  Data structure – identical to the original but with a safer name
 * ------------------------------------------------------------------ */
struct studinfo {
    int   stnr;                 /* student number (sorted)   */
    char  name[NAME_MAXLEN + 1];/* +1 for terminating '\0'  */
    int   grade;
};

/* ------------------------------------------------------------------
 *   Prototypes
 * ------------------------------------------------------------------ */
static int  load_records(const char *path, struct studinfo *buf, size_t max);
static int  binary_search(const struct studinfo *arr, size_t n, int key);
static void safe_fgets(char *dst, size_t size, FILE *src);

/* ------------------------------------------------------------------
 *   main()
 * ------------------------------------------------------------------ */
int main(void)
{
    struct studinfo students[MAX_RECORDS];
    int            n_records;
    long           key;               /* to allow overflow detection   */
    char           line[64];

    /* ---------------------------------------------------------------
     *  Load data from the file – with full error handling
     * --------------------------------------------------------------- */
    n_records = load_records(FILE_PATH, students, MAX_RECORDS);
    if (n_records <= 0) {
        fprintf(stderr, "No records could be loaded – aborting.\n");
        return EXIT_FAILURE;
    }

    /* ---------------------------------------------------------------
     *  Prompt the operator for a student number (read from stdin)
     * --------------------------------------------------------------- */
    printf("Enter student number to look up: ");
    if (!fgets(line, sizeof(line), stdin)) {
        fprintf(stderr, "Input error.\n");
        return EXIT_FAILURE;
    }

    /* Convert safely – reject non‑numeric garbage */
    char *endptr;
    errno = 0;
    key = strtol(line, &endptr, 10);
    if (errno != 0 || endptr == line || *endptr != '\n') {
        fprintf(stderr, "Invalid number.\n");
        return EXIT_FAILURE;
    }

    /* ---------------------------------------------------------------
     *  Binary search (the array is sorted by stnr)
     * --------------------------------------------------------------- */
    int idx = binary_search(students, (size_t)n_records, (int)key);
    if (idx < 0) {
        printf("Student number %ld NOT found in the database.\n", key);
    } else {
        printf("Found at position %d:\n", idx);
        printf("  Name  : %s\n", students[idx].name);
        printf("  Grade : %d\n", students[idx].grade);
    }

    return EXIT_SUCCESS;
}

/* ------------------------------------------------------------------
 *  load_records()
 *  Reads up to `max` lines from the given file.
 *  Returns the number of successfully stored records, or -1 on error.
 * ------------------------------------------------------------------ */
static int load_records(const char *path, struct studinfo *buf, size_t max)
{
    FILE *fp = fopen(path, "r");
    if (!fp) {
        perror("fopen");
        return -1;
    }

    size_t cnt = 0;
    /* NOTE: using while (!feof(fp)) is wrong – it causes a *duplicate* last
     * read attempt.  Instead we read until fscanf fails or we hit the
     * maximum number of records. */
    while (cnt < max) {
        int   stnr;
        char  name[NAME_MAXLEN + 2];   /* +2 to detect overflow */
        int   grade;

        int items = fscanf(fp, "%d %10s %d", &stnr, name, &grade);
        if (items == EOF)               /* reached end of file */
            break;
        if (items != 3) {               /* malformed line */
            fprintf(stderr,
                    "Malformed record at line %zu – skipping.\n", cnt + 1);
            /* discard the rest of the line */
            int c;
            while ((c = fgetc(fp)) != '\n' && c != EOF) { }
            continue;
        }

        /* Safely copy the name (always NUL‑terminate) */
        strncpy(buf[cnt].name, name, NAME_MAXLEN);
        buf[cnt].name[NAME_MAXLEN] = '\0';

        buf[cnt].stnr  = stnr;
        buf[cnt].grade = grade;
        ++cnt;
    }

    fclose(fp);
    return (int)cnt;
}

/* ------------------------------------------------------------------
 *  binary_search()
 *  Classic iterative binary search on an array sorted by stnr.
 *  Returns the index of the key, or -1 if the key is not present.
 * ------------------------------------------------------------------ */
static int binary_search(const struct studinfo *arr, size_t n, int key)
{
    size_t lo = 0;
    size_t hi = n;

    while (lo < hi) {
        size_t mid = lo + (hi - lo) / 2;   /* avoid overflow */

        if (arr[mid].stnr == key) {
            return (int)mid;               /* found */
        } else if (arr[mid].stnr < key) {
            lo = mid + 1;                  /* search right half */
        } else {
            hi = mid;                      /* search left half */
        }
    }
    return -1;                             /* not found */
}

/* ------------------------------------------------------------------
 *  safe_fgets()
 *  Wrapper that guarantees a NUL‑terminated string and strips the
 *  trailing newline if present.
 * ------------------------------------------------------------------ */
static void safe_fgets(char *dst, size_t size, FILE *src)
{
    if (fgets(dst, (int)size, src) != NULL) {
        size_t len = strlen(dst);
        if (len && dst[len - 1] == '\n')
            dst[len - 1] = '\0';
    } else {
        dst[0] = '\0';
    }
}
