```java
import org.bytedeco.javacv.FFmpegFrameRecorder;

public FFmpegFrameRecorder createH264Recorder(String outputPath,
                                              int width,
                                              int height,
                                              int fps) {
    // `outputPath` can be a filename, a URL (e.g., "rtmp://..."), or "pipe:0"
    FFmpegFrameRecorder recorder = new FFmpegFrameRecorder(outputPath, width, height);

    // --- Video codec settings -------------------------------------------------
    recorder.setVideoCodec(avcodec.AV_CODEC_ID_H264);   // H.264
    recorder.setFormat("mp4");                         // MP4 container (or "flv", "matroska", etc.)
    recorder.setPixelFormat(avutil.AV_PIX_FMT_YUV420P);
    recorder.setFrameRate(fps);
    recorder.setVideoBitrate(2_000_000);               // 2 Mbps (adjust per use‑case)

    // --- Encoder preset (speed vs. quality) -----------------------------------
    // libx264 options (if you have it compiled in FFmpeg)
    recorder.setVideoOption("preset", "veryfast");     // ultra‑fast, superfast, veryfast, ... 
    recorder.setVideoOption("crf", "23");              // constant rate factor (lower = better)
    // Optional: enforce baseline profile for maximum compatibility
    recorder.setVideoOption("profile", "baseline");

    // --- Miscellaneous --------------------------------------------------------
    recorder.setAudioChannels(0);                      // No audio (set to >0 if you need it)
    recorder.setInterleaved(true);                    // Recommended for MP4

