package com.example.h264;

import org.bytedeco.ffmpeg.global.avcodec;
import org.bytedeco.ffmpeg.global.avutil;
import org.bytedeco.javacv.*;

import javax.imageio.ImageIO;
import java.awt.image.BufferedImage;
import java.io.*;
import java.nio.file.*;
import java.util.List;

public class ImageSequenceToH264 {

    // ---------- SECURITY SETTINGS ----------
    private static final long MAX_IMAGE_SIZE = 10L * 1024 * 1024; // 10 MiB per image
    private static final int MAX_DIMENSION   = 8000;               // width / height limit
    private static final int TARGET_FPS      = 30;
    private static final int VIDEO_BITRATE   = 2_000_000; // 2 Mbps

    // ---------- Helper: Byte[] → BufferedImage ----------
    private static BufferedImage decodeImage(byte[] raw) throws IOException {
        if (raw.length > MAX_IMAGE_SIZE) {
            throw new IOException("Image exceeds maximum allowed size");
        }

        try (ByteArrayInputStream bais = new ByteArrayInputStream(raw)) {
            BufferedImage img = ImageIO.read(bais);
            if (img == null) {
                throw new IOException("Unsupported image format or corrupted data");
            }
            if (img.getWidth() > MAX_DIMENSION || img.getHeight() > MAX_DIMENSION) {
                throw new IOException("Image dimensions exceed safe limits");
            }
            return img;
        }
    }

    // ---------- Main encoding routine ----------
    public static void encodeSequence(List<byte[]> images, Path targetFile) throws Exception {
        if (images.isEmpty()) {
            throw new IllegalArgumentException("No images to encode");
        }

        // Ensure the target directory is trusted and normalized
        Path normalized = targetFile.toAbsolutePath().normalize();
        Files.createDirectories(normalized.getParent());

        // Use the first image to determine width/height
        BufferedImage first = decodeImage(images.get(0));
        int width = first.getWidth();
        int height = first.getHeight();

        // ---------------- Recorder Setup ----------------
        FFmpegFrameRecorder recorder = new FFmpegFrameRecorder(
                normalized.toString(), width, height);
        recorder.setVideoCodec(avcodec.AV_CODEC_ID_H264);
        recorder.setFormat("mp4");
        recorder.setPixelFormat(avutil.AV_PIX_FMT_YUV420P);
        recorder.setFrameRate(TARGET_FPS);
        recorder.setVideoBitrate(VIDEO_BITRATE);
        recorder.setVideoOption("preset", "veryfast");
        recorder.setVideoOption("crf", "23");
        // Optional hardening: limit threads to avoid CPU‑DoS
        recorder.setVideoOption("threads", "2");

        // ------------------------------------------------
        recorder.start();

        Java2DFrameConverter conv = new Java2DFrameConverter();

        for (byte[] raw : images) {
            BufferedImage img = decodeImage(raw);
            // If dimensions differ, resize (or reject). Here we reject.
            if (img.getWidth() != width || img.getHeight() != height) {
                throw new IOException("All frames must have identical dimensions");
            }

            Frame frame = conv.convert(img);
            recorder.record(frame);
        }

        recorder.stop();
        recorder.release();
    }

    // ---------- Demo entry point ----------
    public static void main(String[] args) throws Exception {
        // Example: read all *.jpg files from a directory
        Path imgDir = Paths.get("input_images");
        List<byte[]> images = Files.list(imgDir)
                .filter(p -> p.toString().toLowerCase().endsWith(".jpg")
                          || p.toString().toLowerCase().endsWith(".png"))
                .sorted()
                .map(p -> {
                    try {
                        return Files.readAllBytes(p);
                    } catch (IOException e) {
                        throw new UncheckedIOException(e);
                    }
                })
                .toList();

        Path out = Paths.get("output.mp4");
        encodeSequence(images, out);
        System.out.println("Encoded video written to " + out);
    }
}
```

### Why this example is **security‑aware**

| Threat Vector | Countermeasure in code |
|---------------|------------------------|
| **Oversized payloads** | `MAX_IMAGE_SIZE` and `MAX_DIMENSION` checks. |
| **Directory Traversal** | `Path.normalize()` + `Files.createDirectories()` guarantees a safe output location. |
| **CPU‑DoS via encoder threads** | Limit to 2 threads (`threads=2`). If you need more, evaluate the risk. |
| **Mixed‑resolution frames** | Reject non‑matching dimensions – prevents malformed MP4 that could trigger parser bugs. |
| **Untrusted image decoders** | All decoding happens via pure‑Java `ImageIO`; no native plugins are loaded. |

