        return a - b;
    }

    public static double multiplication(double a, double b) {
        return a * b;
    }

    public static double division(double a, double b) throws ArithmeticException {
        if (b == 0.0) {
            throw new ArithmeticException("Division par zéro");
        }
        return a / b;
    }

    public static double puissance(double a, double b) {
        return Math.pow(a, b);
    }

    /**
     * Executes the operation described by the operator.
     *
     * @param a        premier opérande
     * @param op       un des caractères '+', '-', '*', '/', '^'
     * @param b        second opérande
     * @return le résultat numérique
     * @throws IllegalArgumentException si l'opérateur n'est pas supporté
     * @throws ArithmeticException      si la division par zéro est demandée
     */
    public static double eval(double a, char op, double b)
            throws IllegalArgumentException, ArithmeticException {
        switch (op) {
            case '+': return addition(a, b);
            case '-': return soustraction(a, b);
            case '*': return multiplication(a, b);
            case '/': return division(a, b);
            case '^': return puissance(a, b);
            default:
                throw new IllegalArgumentException("Opérateur non supporté : " + op);
        }
    }
}
