```java
import java.io.*;
import java.net.*;
import java.util.concurrent.*;
import java.util.logging.*;

/**
 * TCP server that offers a basic calculator service.
 *
 * Protocol (one‑line request, one‑line response):
 *
 *   client  -> "12 + 7"
 *   server  -> "19.0"
 *
 * Errors are returned as plain text prefixed with "ERR:".
 */
public class Serveur {

    // -------------------------------------------------------
    // Configuration – modify as needed
    // -------------------------------------------------------
    private static final int PORT = 5555;               // port d'écoute
    private static final int MAX_CONCURRENT_CLIENTS = 50; // limite size thread‑pool
    private static final Logger LOG = Logger.getLogger("CalculateurServer");

    // -------------------------------------------------------
    // Main entry point
    // -------------------------------------------------------
    public static void main(String[] args) {
        // Simple console logger
        LOG.setLevel(Level.INFO);
        LOG.addHandler(new ConsoleHandler());

        // Thread pool to handle each client in isolation
        ExecutorService pool = Executors.newFixedThreadPool(MAX_CONCURRENT_CLIENTS);

        try (ServerSocket serverSocket = new ServerSocket(PORT)) {
            LOG.info("Serveur lancé, en attente de connexions sur le port " + PORT);

            while (true) {
                try {
                    Socket client = serverSocket.accept(); // bloquant
                    LOG.info("Nouvelle connexion depuis " + client.getRemoteSocketAddress());

                    // Soumettre le traitement à la thread‑pool
                    pool.submit(() -> handleClient(client));
                } catch (IOException e) {
                    LOG.log(Level.WARNING, "Erreur d'acceptation d'une connexion", e);
                }
            }
        } catch (IOException e) {
            LOG.log(Level.SEVERE, "Impossible d'ouvrir le port " + PORT, e);
        } finally {
            pool.shutdown();
        }
    }

    // -------------------------------------------------------
    // Gestion d'un client unique
    // -------------------------------------------------------
    private static void handleClient(Socket client) {
        // Utilisation du try‑with‑resources pour garantir la fermeture
        try (Socket socket = client;
             BufferedReader in = new BufferedReader(
                     new InputStreamReader(socket.getInputStream()));
             BufferedWriter out = new BufferedWriter(
                     new OutputStreamWriter(socket.getOutputStream()))) {

            String request;
            // Le protocole est simple : le client envoie une ligne puis attend la réponse
            while ((request = in.readLine()) != null) {
                LOG.fine("Requête reçue : " + request);
                String response = processRequest(request);
                out.write(response);
                out.newLine();          // newline = fin de message
                out.flush();
            }
        } catch (IOException e) {
            LOG.log(Level.INFO, "Connexion fermée avec le client " +
                    client.getRemoteSocketAddress(), e);
        }
    }

    // -------------------------------------------------------
    // Analyse + exécution de la requête
    // -------------------------------------------------------
    private static String processRequest(String request) {
        // Trim pour enlever espaces superflus
        request = request.trim();
        if (request.isEmpty()) {
            return "ERR: requête vide";
        }

        // Découpage simple : "operand1 operator operand2"
        // On accepte plusieurs espaces entre les tokens
        String[] parts = request.split("\\s+");
        if (parts.length != 3) {
            return "ERR: format attendu <operande1> <opérateur> <operande2>";
        }

        double a, b;
        char op;

        try {
            a = Double.parseDouble(parts[0]);
            b = Double.parseDouble(parts[2]);
        } catch (NumberFormatException nfe) {
            return "ERR: opérandes numériques invalides";
        }

        // Opérateur autorisé : + - * / ^
        if (parts[1].length() != 1) {
            return "ERR: opérateur invalide";
        }
        op = parts[1].charAt(0);
        if ("+-*/^".indexOf(op) == -1) {
            return "ERR: opérateur non supporté (seulement + - * / ^)";
        }

        // Réaliser le calcul en capturant les éventuelles exceptions
        try {
            double result = Calculatrice.eval(a, op, b);
            // Retourner le résultat avec un nombre raisonnable de décimales
            return Double.toString(result);
        } catch (ArithmeticException ae) {
            return "ERR: " + ae.getMessage();
        } catch (IllegalArgumentException iae) {
            return "ERR: " + iae.getMessage();
        }
    }
}
```

