        String host = (args.length >= 1) ? args[0] : DEFAULT_HOST;

        try (Socket socket = new Socket(host, PORT);
             BufferedReader in = new BufferedReader(
                     new InputStreamReader(socket.getInputStream()));
             BufferedWriter out = new BufferedWriter(
                     new OutputStreamWriter(socket.getOutputStream()));
             Scanner scanner = new Scanner(System.in)) {

            System.out.println("Connecté au serveur calculatrice sur " + host + ":" + PORT);
            System.out.println("Entrez une expression du type \"12 + 7\" ou \"quit\" pour sortir.");

            while (true) {
                System.out.print("> ");
                String line = scanner.nextLine();
                if (line == null) break;
                line = line.trim();
                if (line.equalsIgnoreCase("quit") || line.equalsIgnoreCase("exit")) {
                    break;
                }

                // Envoie la requête
                out.write(line);
                out.newLine();
                out.flush();

                // Attend la réponse du serveur
                String response = in.readLine();
                if (response == null) {
                    System.out.println("Le serveur a fermé la connexion.");
                    break;
                }

                System.out.println("Réponse : " + response);
            }

        } catch (IOException e) {
            System.err.println("Erreur de connexion au serveur : " + e.getMessage());
        }
    }
}
