import com.alibaba.nacos.api.config.ConfigService;
import com.alibaba.nacos.api.config.ConfigFactory;
import org.yaml.snakeyaml.DumperOptions;
import org.yaml.snakeyaml.Yaml;
import org.yaml.snakeyaml.constructor.Constructor;

public class NacosYamlDemo {

    private static final String DATA_ID = "crawler-config.yaml";
    private static final String GROUP   = "DEFAULT_GROUP";

    public static void main(String[] args) throws Exception {
        // 1️⃣ 初始化 Nacos ConfigService
        Properties props = new Properties();
        props.put("serverAddr", "127.0.0.1:8848");   // 替換成自己的地址
        ConfigService configService = ConfigFactory.createConfigService(props);

        // 2️⃣ 拉取原始 yaml
        String yamlStr = configService.getConfig(DATA_ID, GROUP, 5000);
        System.out.println("原始配置:\n" + yamlStr);

        // 3️⃣ 轉成 POJO
        Yaml yaml = new Yaml(new Constructor(CrawlerConfig.class));
        CrawlerConfig cfg = yaml.load(yamlStr);

        // 4️⃣ 修改業務參數
        cfg.getCrawler().setEnabled(false);
        cfg.getCrawler().setThreadPoolSize(20);
        cfg.getCrawler().setUrls(List.of("https://newsite.com"));

        // 5️⃣ 重新序列化
        DumperOptions opts = new DumperOptions();
        opts.setDefaultFlowStyle(DumperOptions.FlowStyle.BLOCK);
        opts.setIndent(2);
        opts.setPrettyFlow(true);
        Yaml yamlWriter = new Yaml(opts);
        String newYaml = yamlWriter.dump(cfg);
        System.out.println("修改後配置:\n" + newYaml);

        // 6️⃣ 發佈回 Nacos
        boolean published = configService.publishConfig(DATA_ID, GROUP, newYaml);
        System.out.println("發布結果: " + published);
    }
