## 4️⃣ Spring Security 设计

### 4️⃣.1 采用 JWT + Bearer Token

- **登录** → 产生 `accessToken`（15 min） + `refreshToken`（7 day）。  
- **刷新** → 前端在 `accessToken` 失效前用 `refreshToken` 换取新 token。  
- **退出** → 前端删除本地 token，后端可以把 `refreshToken` 加入黑名单（可选）。

### 4️⃣.2 核心配置

```java
// src/main/java/com/example/carregistry/config/SecurityConfig.java
@Configuration
@EnableWebSecurity
@EnableMethodSecurity(prePostEnabled = true)   // 支持 @PreAuthorize
public class SecurityConfig {

    private final JwtUserDetailsService userDetailsService;
    private final JwtUtil jwtUtil;

    public SecurityConfig(JwtUserDetailsService userDetailsService, JwtUtil jwtUtil) {
        this.userDetailsService = userDetailsService;
        this.jwtUtil = jwtUtil;
    }

    @Bean
    public SecurityFilterChain filterChain(HttpSecurity http) throws Exception {
        http
            .csrf(csrf -> csrf.disable()) // 对 REST API 采用 JWT，关闭 CSRF
            .cors(Customizer.withDefaults())
            .sessionManagement(sess -> sess.sessionCreationPolicy(SessionCreationPolicy.STATELESS))
            .exceptionHandling(exc -> exc
                .authenticationEntryPoint((req, resp, e) -> {
                    resp.setContentType(MediaType.APPLICATION_JSON_VALUE);
                    resp.setStatus(HttpServletResponse.SC_UNAUTHORIZED);
                    resp.getWriter().write("{\"error\":\"Unauthorized\"}");
                })
            )
            .authorizeHttpRequests(auth -> auth
                .requestMatchers("/api/auth/**").permitAll()
                .requestMatchers(HttpMethod.GET, "/api/vehicles/**").hasAnyRole("ADMIN","USER","COMPANY")
                .requestMatchers(HttpMethod.POST, "/api/vehicles/**").hasAnyRole("ADMIN","USER")
                .requestMatchers(HttpMethod.PUT, "/api/vehicles/**").hasAnyRole("ADMIN","USER")
                .requestMatchers(HttpMethod.DELETE, "/api/vehicles/**").hasAnyRole("ADMIN","USER")
                .requestMatchers("/api/admin/**").hasRole("ADMIN")
                .anyRequest().authenticated()
            )
            .addFilterBefore(jwtAuthenticationFilter(), UsernamePasswordAuthenticationFilter.class);

        return http.build();
    }

    @Bean
    public JwtAuthenticationFilter jwtAuthenticationFilter() {
        return new JwtAuthenticationFilter(jwtUtil, userDetailsService);
    }

    @Bean
    public PasswordEncoder passwordEncoder() {
        return new BCryptPasswordEncoder(12); // 强度 12
    }

    @Bean
    public AuthenticationManager authenticationManager(
            AuthenticationConfiguration cfg) throws Exception {
        return cfg.getAuthenticationManager();
    }
}
```

### 4️⃣.3 JWT 工具类

```java
// src/main/java/com/example/carregistry/config/JwtUtil.java
@Component
public class JwtUtil {

    @Value("${jwt.secret}")
    private String secret;

    @Value("${jwt.access-expiration}")
    private long accessExpiration; // ms

    @Value("${jwt.refresh-expiration}")
    private long refreshExpiration;

    private final Key key;

    @PostConstruct
    public void init() {
        this.key = Keys.hmacShaKeyFor(secret.getBytes(StandardCharsets.UTF_8));
    }

    public String generateAccessToken(UserDetails userDetails) {
        return Jwts.builder()
                .setSubject(userDetails.getUsername())
                .claim("roles", userDetails.getAuthorities()
                        .stream()
                        .map(GrantedAuthority::getAuthority)
                        .collect(Collectors.toList()))
                .setIssuedAt(new Date())
                .setExpiration(new Date(System.currentTimeMillis() + accessExpiration))
                .signWith(key, SignatureAlgorithm.HS256)
                .compact();
    }

    public String generateRefreshToken(UserDetails userDetails) {
        return Jwts.builder()
                .setSubject(userDetails.getUsername())
                .setIssuedAt(new Date())
                .setExpiration(new Date(System.currentTimeMillis() + refreshExpiration))
                .signWith(key, SignatureAlgorithm.HS256)
                .compact();
    }

    public String extractUsername(String token) {
        return Jwts.parserBuilder().setSigningKey(key)
                .build()
                .parseClaimsJws(token)
                .getBody()
                .getSubject();
    }

    public boolean validateToken(String token, UserDetails userDetails) {
        try {
            Claims claims = Jwts.parserBuilder()
                    .setSigningKey(key).build()
                    .parseClaimsJws(token)
                    .getBody();
            return claims.getSubject().equals(userDetails.getUsername())
                    && !claims.getExpiration().before(new Date());
        } catch (JwtException | IllegalArgumentException e) {
            return false;
        }
    }
}
```

### 4️⃣.4 JWT Authentication Filter

```java
// src/main/java/com/example/carregistry/config/JwtAuthenticationFilter.java
public class JwtAuthenticationFilter extends OncePerRequestFilter {

    private final JwtUtil jwtUtil;
    private final JwtUserDetailsService userDetailsService;

    public JwtAuthenticationFilter(JwtUtil jwtUtil, JwtUserDetailsService userDetailsService) {
        this.jwtUtil = jwtUtil;
        this.userDetailsService = userDetailsService;
    }

    @Override
    protected void doFilterInternal(HttpServletRequest request,
                                    HttpServletResponse response,
                                    FilterChain filterChain) throws ServletException, IOException {

        final String authHeader = request.getHeader(HttpHeaders.AUTHORIZATION);
        String username = null;
        String token = null;

        if (StringUtils.hasText(authHeader) && authHeader.startsWith("Bearer ")) {
            token = authHeader.substring(7);
            try {
                username = jwtUtil.extractUsername(token);
            } catch (Exception e) {
                // token 解析错误，留空交给后面的异常处理
            }
        }

        if (username != null && SecurityContextHolder.getContext().getAuthentication() == null) {
            UserDetails userDetails = userDetailsService.loadUserByUsername(username);
            if (jwtUtil.validateToken(token, userDetails)) {
                UsernamePasswordAuthenticationToken authToken =
                        new UsernamePasswordAuthenticationToken(
                                userDetails,
                                null,
                                userDetails.getAuthorities()
                        );
                authToken.setDetails(new WebAuthenticationDetailsSource().buildDetails(request));
                SecurityContextHolder.getContext().setAuthentication(authToken);
            }
        }
        filterChain.doFilter(request, response);
    }
}
```

### 4️⃣.5 `UserDetailsService` 实现

```java
// src/main/java/com/example/carregistry/service/JwtUserDetailsService.java
@Service
public class JwtUserDetailsService implements UserDetailsService {

    private final UserRepository userRepo;

    public JwtUserDetailsService(UserRepository userRepo) {
        this.userRepo = userRepo;
    }

    @Override
    public UserDetails loadUserByUsername(String username) throws UsernameNotFoundException {
        User user = userRepo.findByUsername(username)
                .orElseThrow(() -> new UsernameNotFoundException("User not found"));
        List<GrantedAuthority> authorities = user.getRoles()
                .stream()
                .map(r -> new SimpleGrantedAuthority("ROLE_" + r.getName().toUpperCase()))
                .collect(Collectors.toList());

        return new org.springframework.security.core.userdetails.User(
                user.getUsername(),
                user.getPassword(),
                authorities);
    }
}
```

### 4️⃣.6 方法级别权限控制（示例）

```java
@Service
public class VehicleService {

    private final VehicleRepository vehicleRepo;
    private final UserRepository userRepo;

    @Transactional
    public Vehicle createVehicle(VehicleDTO dto, String username) {
        User user = userRepo.findByUsername(username)
                .orElseThrow(() -> new IllegalArgumentException("User not found"));
        // 只允许拥有 USER 或 ADMIN 角色的用户创建
        if (!user.hasRole("USER") && !user.hasRole("ADMIN")) {
            throw new AccessDeniedException("无权创建车辆");
        }

        Vehicle v = new Vehicle();
        v.setLicensePlate(dto.getLicensePlate());
        v.setBrand(dto.getBrand());
        v.setModel(dto.getModel());
        v.setYear(dto.getYear());
        v.setOwner(user);
        return vehicleRepo.save(v);
    }

    @PreAuthorize("@vehicleRepo.findById(#id).orElseThrow().owner.username == authentication.name " +
                  "or hasRole('ADMIN')")
    public Vehicle updateVehicle(Long id, VehicleDTO dto) {
        Vehicle v = vehicleRepo.findById(id)
                .orElseThrow(() -> new EntityNotFoundException("Vehicle not found"));
        // 只要符合 @PreAuthorize 条件，就可更新
        v.setBrand(dto.getBrand());
        v.setModel(dto.getModel());
        v.setYear(dto.getYear());
        return vehicleRepo.save(v);
    }

    // 删除也使用相同的 @PreAuthorize
}
```

