### 6.2 Axios 实例 + 拦截器

```ts
// src/api/index.ts
import axios from 'axios';
import router from '@/router';
import { useAuthStore } from '@/store/auth';

const api = axios.create({
  baseURL: import.meta.env.VITE_API_BASE || '/api',
});

api.interceptors.request.use(config => {
  const token = useAuthStore().accessToken;
  if (token) {
    config.headers.Authorization = `Bearer ${token}`;
  }
  return config;
});

api.interceptors.response.use(
  res => res,
  async err => {
    if (err.response?.status === 401) {
      // 尝试使用 refresh token
      const auth = useAuthStore();
      try {
        await auth.refreshToken();
        // 重新发起原请求
        return api(err.config);
      } catch (_) {
        auth.logout();
        router.replace({ name: 'Login' });
      }
    }
    return Promise.reject(err);
  }
);

export default api;
```

### 6.3 Pinia Auth Store

```ts
// src/store/auth.ts
import { defineStore } from 'pinia';
import api from '@/api';
import jwtDecode from 'jwt-decode';

interface JwtPayload {
  sub: string;
  exp: number;
  roles: string[];
}

export const useAuthStore = defineStore('auth', {
  state: () => ({
    accessToken: '' as string,
    refreshToken: '' as string,
    user: null as null | { username: string; roles: string[] },
  }),
  getters: {
    isAuthenticated: state => !!state.accessToken,
    isAdmin: state => state.user?.roles.includes('ADMIN'),
    // … 其它角色 getter
  },
  actions: {
    async login(payload: { username: string; password: string }) {
      const resp = await api.post('/auth/login', payload);
      this.setTokens(resp.data);
    },
    async register(payload: any) {
      await api.post('/auth/register', payload);
    },
    async refreshToken() {
      const resp = await api.post('/auth/refresh', { token: this.refreshToken });
      this.setTokens(resp.data);
    },
    setTokens({ accessToken, refreshToken }: { accessToken: string; refreshToken: string }) {
      this.accessToken = accessToken;
      this.refreshToken = refreshToken;
      const payload = jwtDecode<JwtPayload>(accessToken);
      this.user = { username: payload.sub, roles: payload.roles };
      // 可将 token 写入 localStorage (注意 XSS 防护)
      localStorage.setItem('accessToken', accessToken);
      localStorage.setItem('refreshToken', refreshToken);
    },
    initFromStorage() {
      const at = localStorage.getItem('accessToken');
      const rt = localStorage.getItem('refreshToken');
      if (at && rt) {
        this.setTokens({ accessToken: at, refreshToken: rt });
      }
    },
    logout() {
      this.accessToken = '';
      this.refreshToken = '';
      this.user = null;
      localStorage.clear();
    },
  },
});
```

