## 3. 关键代码示例（安全实现）

下面给出 **最小可运行** 的安全 Socket 示例，演示 **TLS + Token + MAC** 的完整流程。完整项目请结合业务协议（JSON/ProtoBuf）以及 Swing UI 实现。

### 3.1 服务器端（客服端）— SSLServerSocket + 线程池

```java
// ServerMain.java
public class ServerMain {
    private static final int PORT = 8443;
    private static final String KEYSTORE_PATH = "conf/server-keystore.jks";
    private static final String KEYSTORE_PASS = System.getenv("KS_PASS"); // 不硬编码

    public static void main(String[] args) throws Exception {
        SSLContext ctx = SSLContext.getInstance("TLSv1.3");
        KeyStore ks = KeyStore.getInstance("JKS");
        try (FileInputStream fis = new FileInputStream(KEYSTORE_PATH)) {
            ks.load(fis, KEYSTORE_PASS.toCharArray());
        }
        KeyManagerFactory kmf = KeyManagerFactory.getInstance("SunX509");
        kmf.init(ks, KEYSTORE_PASS.toCharArray());

        // 如需要双向认证，启用 TrustManager
        ctx.init(kmf.getKeyManagers(), null, new SecureRandom());

        SSLServerSocketFactory ssf = ctx.getServerSocketFactory();
        try (SSLServerSocket server = (SSLServerSocket) ssf.createServerSocket(PORT)) {
            server.setNeedClientAuth(false); // 如使用双向认证设为 true
            System.out.println("客服端已启动，监听端口 " + PORT);

            ExecutorService pool = Executors.newCachedThreadPool();
            while (true) {
                SSLSocket socket = (SSLSocket) server.accept();
                // 限制每个IP的并发数可在此处拦截
                pool.execute(new ClientHandler(socket));
            }
        }
    }
}
```

#### 3.2 业务处理 `ClientHandler`

```java
// ClientHandler.java
class ClientHandler implements Runnable {
    private final SSLSocket socket;
    private static final long TIMEOUT_MS = 30_000L; // 心跳/空闲超时

    ClientHandler(SSLSocket socket) {
        this.socket = socket;
    }

    @Override
    public void run() {
        try (socket;
             DataInputStream in = new DataInputStream(new BufferedInputStream(socket.getInputStream()));
             DataOutputStream out = new DataOutputStream(new BufferedOutputStream(socket.getOutputStream()))) {
            socket.setSoTimeout((int) TIMEOUT_MS);

            // 1️⃣ 登录阶段（示例：用户名+密码 -> Token）
            String loginReq = in.readUTF(); // JSON: {"type":"login","user":"bob","pwd":"xxx"}
            String token = AuthService.authenticateAndIssueToken(loginReq);
            if (token == null) {
                out.writeUTF(Json.error("auth_failed"));
                out.flush();
                return;
            }
            out.writeUTF(Json.success("token", token));
            out.flush();

            // 2️⃣ 主循环：收发业务报文
            while (true) {
                String raw = in.readUTF(); // 每条报文为 JSON 字符串
                Message msg = Message.fromJson(raw);
                if (!MessageVerifier.verify(msg, token)) {
                    out.writeUTF(Json.error("mac_invalid"));
                    out.flush();
                    continue;
                }
                // 业务分发（文字、文件、图片等）
                handleMessage(msg, out, token);
            }
        } catch (SocketTimeoutException e) {
            // 心跳超时 → 关闭会话，记录日志
            Logger.warn("客户端超时断开: " + socket.getRemoteSocketAddress());
        } catch (Exception e) {
            Logger.error("会话异常", e);
        }
    }

    private void handleMessage(Message msg, DataOutputStream out, String token) throws IOException {
        switch (msg.getType()) {
            case "text":
                // 转发至对应客服，保存至本地加密日志
                ChatLog.append(msg.getSessionId(), msg.getPayload());
                out.writeUTF(Json.success("ack"));
                break;
            case "file":
                // 校验文件属性，写入磁盘（加密保存）
                FileMeta fm = FileProcessor.saveEncrypted(msg.getPayload(), token);
                out.writeUTF(Json.success("file_saved", fm.getFileId()));
                break;
            // … 其它类型
            default:
                out.writeUTF(Json.error("unknown_type"));
        }
        out.flush();
    }
}
```

#### 3.3 客户端（用户端）— SSLSocket

```java
// ClientMain.java
public class ClientMain {
    private static final String HOST = "server.example.com";
    private static final int PORT = 8443;
    private static final String TRUSTSTORE_PATH = "conf/client-truststore.jks";
    private static final String TRUST_PASS = System.getenv("TS_PASS");

    public static void main(String[] args) throws Exception {
        SSLContext ctx = SSLContext.getInstance("TLSv1.3");
        KeyStore ts = KeyStore.getInstance("JKS");
        try (FileInputStream fis = new FileInputStream(TRUSTSTORE_PATH)) {
            ts.load(fis, TRUST_PASS.toCharArray());
        }
        TrustManagerFactory tmf = TrustManagerFactory.getInstance("SunX509");
        tmf.init(ts);
        ctx.init(null, tmf.getTrustManagers(), new SecureRandom());

        try (SSLSocket socket = (SSLSocket) ctx.getSocketFactory().createSocket(HOST, PORT);
             DataInputStream in = new DataInputStream(socket.getInputStream());
             DataOutputStream out = new DataOutputStream(socket.getOutputStream())) {

            // 登录
            out.writeUTF(Json.login("alice", "pwd123"));
            out.flush();
            String loginResp = in.readUTF();
            String token = Json.parse(loginResp).getString("token");

            // 发送文字
            Message text = Message.builder()
                    .type("text")
                    .sessionId("sess-001")
                    .payload("您好，我想查询订单")
                    .seq(1)
                    .mac(MessageSigner.sign(token, "text", "sess-001", "您好，我想查询订单", 1))
                    .build();
            out.writeUTF(text.toJson());
            out.flush();

            // 接收回应（简化示例）
            System.out.println("服务端回: " + in.readUTF());
        }
    }
}
```

