## 3️⃣ Domain Model – `UserSession`

```java
package com.example.jwtms.model;

import lombok.*;
import org.springframework.data.redis.core.RedisHash;

import java.io.Serializable;
import java.time.Instant;
import java.util.Set;

/**
 * One entry per *active* JWT session.
 *
 * The key is: "session:{userId}:{sessionId}"
 */
@Getter @Setter @NoArgsConstructor @AllArgsConstructor @Builder
@RedisHash("session")
public class UserSession implements Serializable {

    private static final long serialVersionUID = 1L;

    /** Composite key – not stored as a field, used only for RedisHash key generation */
    @Transient
    private String redisKey;   // e.g. session:42:8b7d6a...

    /** Subject – typically the user's DB id */
    private String userId;

    /** Unique per‑login identifier – UUID */
    private String sessionId;

    /** Set of functionality identifiers (e.g. "PAYMENTS", "REPORTING") */
    private Set<String> scopes;

    /** When the session becomes invalid */
    private Instant expiresAt;
}
