## 5️⃣ JWT Utility – `JwtTokenProvider`

```java
package com.example.jwtms.security;

import com.example.jwtms.model.UserSession;
import io.jsonwebtoken.*;
import io.jsonwebtoken.security.Keys;
import lombok.extern.slf4j.Slf4j;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.stereotype.Component;

import javax.crypto.SecretKey;
import java.time.Instant;
import java.util.*;

@Slf4j
@Component
public class JwtTokenProvider {

    private final SecretKey secretKey;
    private final String issuer;
    private final long expirationMillis;
    private final long refreshWindowMillis;

    public JwtTokenProvider(@Value("${jwt.secret}") String secretBase64,
                            @Value("${jwt.issuer}") String issuer,
                            @Value("${jwt.expiration}") String expiration,
                            @Value("${jwt.refresh-window}") String refreshWindow) {

        this.secretKey = Keys.hmacShaKeyFor(Base64.getUrlDecoder().decode(secretBase64));
        this.issuer = issuer;

        // Parse human‑readable durations (e.g. "30m", "1h")
        this.expirationMillis = parseDuration(expiration);
        this.refreshWindowMillis = parseDuration(refreshWindow);
    }

    /** Convert "30m", "2h", "1d" → milliseconds */
    private long parseDuration(String txt) {
        if (txt.endsWith("ms")) return Long.parseLong(txt.replace("ms", ""));
        if (txt.endsWith("s"))  return Long.parseLong(txt.replace("s", "")) * 1000;
        if (txt.endsWith("m"))  return Long.parseLong(txt.replace("m", "")) * 60_000;
        if (txt.endsWith("h"))  return Long.parseLong(txt.replace("h", "")) * 3_600_000;
        if (txt.endsWith("d"))  return Long.parseLong(txt.replace("d", "")) * 86_400_000;
        throw new IllegalArgumentException("Unsupported duration: " + txt);
    }

    /** -------------------------------------------------------------
     *  1️⃣ Create a JWT from a freshly‑authenticated UserSession.
     * ------------------------------------------------------------ */
    public String generateToken(UserSession session) {
        Instant now = Instant.now();
        Instant expiry = session.getExpiresAt();

        Map<String, Object> claims = new HashMap<>();
        claims.put("sid", session.getSessionId());           // session fingerprint
        claims.put("scopes", session.getScopes());           // functionality list
        claims.put("uid", session.getUserId());              // optional, for quick access

        return Jwts.builder()
                .setClaims(claims)
                .setSubject(session.getUserId())
                .setIssuer(issuer)
                .setIssuedAt(Date.from(now))
                .setExpiration(Date.from(expiry))
                .signWith(secretKey, SignatureAlgorithm.HS256)
                .compact();
    }

    /** -------------------------------------------------------------
     *  2️⃣ Validate a JWT (signature + expiry)
     * ------------------------------------------------------------ */
    public Jws<Claims> validateToken(String token) {
        try {
            return Jwts.parserBuilder()
                    .setSigningKey(secretKey)
                    .requireIssuer(issuer)
                    .build()
                    .parseClaimsJws(token);
        } catch (JwtException e) {
            log.warn("Invalid JWT: {}", e.getMessage());
            throw new IllegalArgumentException("Invalid JWT", e);
        }
    }

    /** -------------------------------------------------------------
     *  3️⃣ Extract the “session fingerprint” (sid) from a token.
     * ------------------------------------------------------------ */
    public String getSessionId(String token) {
        return validateToken(token).getBody().get("sid", String.class);
    }

    /** -------------------------------------------------------------
     *  4️⃣ Extract the list of scopes from a token.
     * ------------------------------------------------------------ */
    @SuppressWarnings("unchecked")
    public Set<String> getScopes(String token) {
        Claims body = validateToken(token).getBody();
        Object scopes = body.get("scopes");
        if (scopes instanceof Collection) {
            return new HashSet<>((Collection<String>) scopes);
        }
        return Collections.emptySet();
    }

    /** -------------------------------------------------------------
     *  5️⃣ Helper: compute default expiry for a newly‑created session.
     * ------------------------------------------------------------ */
    public Instant computeDefaultExpiry() {
        return Instant.now().plusMillis(expirationMillis);
    }

    /** -------------------------------------------------------------
     *  6️⃣ Helper: is the token close enough to expiry to be refreshed?
     * ------------------------------------------------------------ */
    public boolean isRefreshable(Claims claims) {
        Date exp = claims.getExpiration();
        long timeToExpiry = exp.getTime() - System.currentTimeMillis();
        return timeToExpiry <= refreshWindowMillis;
    }
}
