## 6️⃣ Spring Security Filter – `JwtAuthenticationFilter`

```java
package com.example.jwtms.security;

import com.example.jwtms.model.UserSession;
import com.example.jwtms.repo.UserSessionRepository;
import jakarta.servlet.FilterChain;
import jakarta.servlet.ServletException;
import jakarta.servlet.http.*;
import lombok.extern.slf4j.Slf4j;
import org.springframework.http.HttpHeaders;
import org.springframework.security.authentication.*;
import org.springframework.security.core.*;
import org.springframework.security.core.authority.SimpleGrantedAuthority;
import org.springframework.security.web.authentication.*;
import org.springframework.stereotype.Component;
import org.springframework.util.StringUtils;

import java.io.IOException;
import java.util.*;
import java.util.stream.Collectors;

/**
 * Filters **every** request, extracts the Bearer token,
 * validates it, checks the session exists in Redis,
 * and builds an Authentication object containing the scopes as authorities.
 *
 * If validation fails → 401 (handled by AuthenticationEntryPoint).
 */
@Slf4j
@Component
public class JwtAuthenticationFilter extends OncePerRequestFilter {

    private final JwtTokenProvider tokenProvider;
    private final UserSessionRepository sessionRepo;
    private final AuthenticationManager authenticationManager;

    public JwtAuthenticationFilter(JwtTokenProvider tokenProvider,
                                   UserSessionRepository sessionRepo,
                                   AuthenticationManager authenticationManager) {
        this.tokenProvider = tokenProvider;
        this.sessionRepo = sessionRepo;
        this.authenticationManager = authenticationManager;
    }

    /** -------------------------------------------------------------
     *  Core filter logic
     * ------------------------------------------------------------ */
    @Override
    protected void doFilterInternal(HttpServletRequest request,
                                    HttpServletResponse response,
                                    FilterChain filterChain) throws ServletException, IOException {

        try {
            String token = resolveToken(request);
            if (StringUtils.hasText(token)) {
                // 1️⃣ Validate signature & expiry
                var claimsJws = tokenProvider.validateToken(token);
                var claims = claimsJws.getBody();

                // 2️⃣ Pull the session fingerprint from the JWT
                String sessionId = claims.get("sid", String.class);
                String userId    = claims.getSubject();

                // 3️⃣ Verify the session exists and is still valid in Redis
                String redisKey = buildRedisKey(userId, sessionId);
                Optional<UserSession> maybeSession = sessionRepo.findById(redisKey);
                if (maybeSession.isEmpty()) {
                    log.warn("Session not found or revoked: user={}, sid={}", userId, sessionId);
                    throw new BadCredentialsException("Session revoked");
                }

                // 4️⃣ Build authorities from the scopes claim
                @SuppressWarnings("unchecked")
                Collection<String> scopes = (Collection<String>) claims.get("scopes", Collection.class);
                List<GrantedAuthority> authorities = scopes.stream()
                        .map(scope -> new SimpleGrantedAuthority("SCOPE_" + scope))
                        .collect(Collectors.toList());

                // 5️⃣ Create Authentication token & set it into SecurityContext
                UsernamePasswordAuthenticationToken authentication =
                        new UsernamePasswordAuthenticationToken(userId, null, authorities);
                authentication.setDetails(new WebAuthenticationDetailsSource().buildDetails(request));
                SecurityContextHolder.getContext().setAuthentication(authentication);
            }

            filterChain.doFilter(request, response);
        } catch (Exception ex) {
            // Let Spring Security handle the error (401) via the entry point.
            SecurityContextHolder.clearContext();
            logger.debug("Authentication failed: {}", ex.getMessage());
            getFailureHandler().onAuthenticationFailure(request, response,
                    new BadCredentialsException(ex.getMessage(), ex));
        }
    }

    /** -------------------------------------------------------------
     *  Resolve token from the Authorization header ("Bearer <jwt>")
     * ------------------------------------------------------------ */
    private String resolveToken(HttpServletRequest request) {
        String bearer = request.getHeader(HttpHeaders.AUTHORIZATION);
        if (StringUtils.hasText(bearer) && bearer.startsWith("Bearer ")) {
            return bearer.substring(7);
        }
        return null;
    }

    /** -------------------------------------------------------------
     *  Helper: Redis key format (mirrors UserSession.redisKey)
     * ------------------------------------------------------------ */
    public static String buildRedisKey(String userId, String sessionId) {
        return String.format("session:%s:%s", userId, sessionId);
    }

    /** -------------------------------------------------------------
     *  Failure handler – simply returns 401 with a JSON body.
     * ------------------------------------------------------------ */
    private AuthenticationFailureHandler getFailureHandler() {
        return new SimpleUrlAuthenticationFailureHandler() {
            @Override
            public void onAuthenticationFailure(HttpServletRequest request,
                                                HttpServletResponse response,
                                                AuthenticationException exception) throws IOException {
                response.setStatus(HttpServletResponse.SC_UNAUTHORIZED);
                response.setContentType("application/json");
                response.getWriter().write("{\"error\":\"" + exception.getMessage() + "\"}");
            }
        };
    }
}
```

