## 8️⃣ Authentication Service – `AuthService`

```java
package com.example.jwtms.service;

import com.example.jwtms.model.UserSession;
import com.example.jwtms.repo.UserSessionRepository;
import com.example.jwtms.security.JwtTokenProvider;
import com.example.jwtms.security.JwtAuthenticationFilter;
import lombok.RequiredArgsConstructor;
import org.springframework.stereotype.Service;

import java.time.Instant;
import java.util.*;

@Service
@RequiredArgsConstructor
public class AuthService {

    private final JwtTokenProvider tokenProvider;
    private final UserSessionRepository sessionRepo;

    /**
     * Simulated credential check – replace with real UserDetailsService / DB.
     */
    public boolean checkCredentials(String username, String password) {
        // In real life, verify password hash from DB
        return "user".equals(username) && "pwd".equals(password);
    }

    /**
     * Create a **new session** limited to the supplied scopes.
     *
     * @param userId  (normally the DB id)
     * @param scopes  functional scopes requested for this session
     * @return signed JWT
     */
    public String createSession(String userId, Set<String> scopes) {
        String sessionId = UUID.randomUUID().toString();
        Instant expiresAt = tokenProvider.computeDefaultExpiry();

        UserSession session = UserSession.builder()
                .userId(userId)
                .sessionId(sessionId)
                .scopes(scopes)
                .expiresAt(expiresAt)
                .build();

        // Store in Redis using the composite key format
        String redisKey = JwtAuthenticationFilter.buildRedisKey(userId, sessionId);
        session.setRedisKey(redisKey);
        sessionRepo.save(session);   // key = redisKey

        return tokenProvider.generateToken(session);
    }

    /**
     * Revoke a single session – removes it from Redis.
     */
    public void revokeSession(String userId, String sessionId) {
        String redisKey = JwtAuthenticationFilter.buildRedisKey(userId, sessionId);
        sessionRepo.deleteById(redisKey);
    }

    /**
     * List *active* sessions for a user (useful for UI “logout from other devices”).
     */
    public List<UserSession> listActiveSessions(String userId) {
        // This simplistic approach iterates over all keys. In production use a proper
        // Redis SCAN with a pattern "session:{userId}:*".
        List<UserSession> active = new ArrayList<>();
        sessionRepo.findAll().forEach(sess -> {
            if (sess.getUserId().equals(userId)) active.add(sess);
        });
        return active;
    }
}
