## 9️⃣ REST Controllers  

### 9.1 Login & Session Management (`AuthController`)

```java
package com.example.jwtms.controller;

import com.example.jwtms.service.AuthService;
import lombok.*;
import org.springframework.http.*;
import org.springframework.validation.annotation.Validated;
import org.springframework.web.bind.annotation.*;

import jakarta.validation.constraints.*;
import java.util.*;

@RestController
@RequestMapping("/auth")
@RequiredArgsConstructor
public class AuthController {

    private final AuthService authService;

    /** -------------------------------------------------------------
     *  1️⃣ Login – issue a JWT scoped to the requested functionalities.
     * ------------------------------------------------------------ */
    @PostMapping("/login")
    public ResponseEntity<LoginResponse> login(@Validated @RequestBody LoginRequest req) {
        if (!authService.checkCredentials(req.getUsername(), req.getPassword())) {
            return ResponseEntity.status(HttpStatus.UNAUTHORIZED).build();
        }

        // In a real app, the userId is the primary key from DB
        String userId = "user-" + req.getUsername();

        // Scopes are supplied by the client (or you can derive them from role)
        Set<String> scopes = new HashSet<>(req.getScopes());

        String jwt = authService.createSession(userId, scopes);
        return ResponseEntity.ok(new LoginResponse(jwt, scopes));
    }

    /** -------------------------------------------------------------
     *  2️⃣ Logout a single session (requires the JWT to be present)
     * ------------------------------------------------------------ */
    @PostMapping("/logout")
    public ResponseEntity<Void> logout(@RequestHeader(HttpHeaders.AUTHORIZATION) String bearer) {
        // Extract token -> sessionId & userId
        String token = bearer.replace("Bearer ", "");
        var claims = authService.getTokenProvider().validateToken(token).getBody();
        String sessionId = claims.get("sid", String.class);
        String userId    = claims.getSubject();

        authService.revokeSession(userId, sessionId);
        return ResponseEntity.noContent().build();
    }

    /** -------------------------------------------------------------
     *  3️⃣ List active sessions for the current user
     * ------------------------------------------------------------ */
    @GetMapping("/sessions")
    public ResponseEntity<List<UserSessionDTO>> list(@RequestHeader(HttpHeaders.AUTHORIZATION) String bearer) {
        String token = bearer.replace("Bearer ", "");
        var claims = authService.getTokenProvider().validateToken(token).getBody();
        String userId = claims.getSubject();

        List<UserSessionDTO> result = authService.listActiveSessions(userId).stream()
                .map(s -> new UserSessionDTO(s.getSessionId(), s.getScopes(), s.getExpiresAt()))
                .toList();

        return ResponseEntity.ok(result);
    }

    /* --------------------------------------------------------------
     *  DTOs – keep them in the same file for brevity
     * -------------------------------------------------------------- */
    @Data
    static class LoginRequest {
        @NotBlank private String username;
        @NotBlank private String password;
        /** Scopes requested for this session (e.g. ["PAYMENTS","REPORTING"]) */
        private List<String> scopes = Collections.emptyList();
    }

    @Data @AllArgsConstructor
    static class LoginResponse {
        private String token;
        private Set<String> scopes;
    }

    @Data @AllArgsConstructor
    static class UserSessionDTO {
        private String sessionId;
        private Set<String> scopes;
        private Instant expiresAt;
    }
}
