            Map.entry(Merchant.BITSKINS, new BitskinsMarket()),
            Map.entry(Merchant.BUFF163, new Buff163Market())
            // … ajouter les autres marchands ici
    );

    public static Market getMarket(Merchant merchant) {
        return REGISTRY.get(merchant);
    }
