                    // Certains marchands donnent uniquement un "instant_sale_price"
                    // Si ce n’est pas disponible, on ignore la vente potentielle.
                    PriceInfo sellInfo = skin.priceFor(sell).orElse(null);
                    if (sellInfo == null) continue;

                    BigDecimal sellPriceUsd = toUsd(sellInfo.price(), sellInfo.currency());

                    // Application des frais (commission) pour chaque côté
                    BigDecimal netBuy = applyFee(buyPriceUsd, buyInfo.fee());
                    BigDecimal netSell = applyFee(sellPriceUsd, sellInfo.fee()); // fee = négatif (commission sur la vente)

                    BigDecimal gross = sellPriceUsd.subtract(buyPriceUsd);
                    BigDecimal net = netSell.subtract(netBuy);

                    if (net.compareTo(BigDecimal.ZERO) > 0) {
                        opportunities.add(new ArbitrageOpportunity(
                                skin,
                                buy,
                                sell,
                                gross,
                                net,
                                buyPriceUsd,
                                sellPriceUsd));
                    }
                }
            }
        }

        // Trier par profit net décroissant
        opportunities.sort(Comparator.comparing(ArbitrageOpportunity::netProfit).reversed());
        return opportunities;
    }

    /** Convertit le prix dans la devise du market en USD (ou EUR) */
    private BigDecimal toUsd(BigDecimal amount, Optional<String> currencyOpt) {
        String cur = currencyOpt.orElse("USD");
        return switch (cur) {
            case "USD" -> amount;
            case "EUR" -> amount.divide(USD_TO_EUR, 4, BigDecimal.ROUND_HALF_UP);
            case "CNY" -> amount.multiply(CNY_TO_USD);
            default -> amount; // fallback, on suppose USD
        };
    }

    /** Applique la commission (exemple : 0.05 = 5 %) */
    private BigDecimal applyFee(BigDecimal price, Optional<BigDecimal> feeOpt) {
        BigDecimal fee = feeOpt.orElse(BigDecimal.ZERO);
        // fee positif = coût supplémentaire, fee négatif = perception (sale)
        return price.multiply(BigDecimal.ONE.add(fee));
    }
}
```

### 4️⃣.3 Service de haut niveau `TradeEngine`

```java
public final class TradeEngine {

    private final JsonSkinParser parser = new JsonSkinParser();
    private final ArbitrageService arbitrage = new ArbitrageService();

    /** 
     *  1️⃣  Télécharge le JSON (ou le lit depuis un fichier)
     *  2️⃣  Parse les skins
     *  3️⃣  Calcule les meilleures opportunités
     *  4️⃣  Retourne les N meilleures (par défaut 10)
     */
    public List<ArbitrageOpportunity> run(String json, int topN) throws IOException, MarketParseException {
        List<Skin> skins = parser.parse(json);
        List<ArbitrageOpportunity> all = arbitrage.findOpportunities(skins);
        return all.subList(0, Math.min(topN, all.size()));
    }
}
