package com.example.jira.util;

/**
 * CSV injection mitigation.  Excel (and similar) treat any cell starting
 * with =, +, -, @, or tab as a formula.  Strip the leading character or
 * prepend a single quote (`'`) so it is treated as a literal string.
 *
 * The logic is deliberately simple and fast – it does not attempt to
 * "clean" the value, only to neutralise formula injection.
 */
public final class CsvSanitizer {

    private static final char[] DANGEROUS_PREFIXES = {'=', '+', '-', '@', '\t'};

    private CsvSanitizer() { /* utility */ }

    public static String sanitize(String value) {
        if (value == null || value.isEmpty()) {
            return value;
        }
        char first = value.charAt(0);
        for (char prefix : DANGEROUS_PREFIXES) {
            if (first == prefix) {
                // Prepend a single quote.  Most spreadsheet apps display it
                // but treat the rest as literal text.
                return "'" + value;
            }
        }
        return value;
    }
}
```

