package com.example.jira.parser;

import com.example.jira.model.Issue;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

import javax.xml.XMLConstants;
import javax.xml.stream.*;
import java.io.InputStream;
import java.util.ArrayList;
import java.util.List;

/**
 * Secure, streaming parser for JIRA XML backup files.
 *
 * Important security around XML:
 *   • Disallow DOCTYPE declarations (prevents external entities).
 *   • Disable support for external DTDs and schemas.
 *   • Limit max entity expansion depth (fallback for older parsers).
 *
 * We use StAX (javax.xml.stream) because it is:
 *   - low‑memory (no DOM tree)
 *   - fast for large exports (hundreds of thousands of issues)
 *
 * The parser extracts a **handful of fields**; you can add more by extending the
 * state machine in the switch‑case block.
 */
public final class JiraXmlParser {

    private static final Logger LOG = LoggerFactory.getLogger(JiraXmlParser.class);

    private JiraXmlParser() { /* utility */ }

    /**
     * Parses an InputStream containing a JIRA XML backup.
     *
     * @param in XML data (must be UTF‑8 or the encoding declared in the XML prolog)
     * @return List of Issue objects (may be empty)
     * @throws XMLStreamException if parsing fails
     */
    public static List<Issue> parse(InputStream in) throws XMLStreamException {
        XMLInputFactory factory = XMLInputFactory.newInstance();

        // ---- SECURITY HARDENING ----
        // Disallow DTDs altogether – prevents XXE
        factory.setProperty(XMLInputFactory.SUPPORT_DTD, false);
        // Disallow external entity resolution
        factory.setProperty("javax.xml.stream.isSupportingExternalEntities", false);
        // If the underlying implementation supports it, block external schemas
        factory.setProperty(XMLConstants.ACCESS_EXTERNAL_DTD, "");
        factory.setProperty(XMLConstants.ACCESS_EXTERNAL_SCHEMA, "");

        XMLStreamReader reader = factory.createXMLStreamReader(in);
        List<Issue> issues = new ArrayList<>();

        // Temporary holder for the current issue’s fields
        String key = null, summary = null, description = null,
                status = null, assignee = null;

        // Track which element we are inside – needed for character data
        String currentElement = null;
        try {
            while (reader.hasNext()) {
                int event = reader.next();

                switch (event) {
                    case XMLStreamConstants.START_ELEMENT:
                        String localName = reader.getLocalName();
                        if ("Issue".equals(localName)) {
                            // Reset fields for a new issue
                            key = summary = description = status = assignee = null;
                        }
                        currentElement = localName;
                        break;

                    case XMLStreamConstants.CHARACTERS:
                        if (currentElement == null) break;
                        String text = reader.getText().trim();
                        if (text.isEmpty()) break;

                        switch (currentElement) {
                            case "key" -> key = text;
                            case "summary" -> summary = text;
                            case "description" -> description = text;
                            case "status" -> status = text;
                            case "assignee" -> assignee = text;
                        }
                        break;

                    case XMLStreamConstants.END_ELEMENT:
                        String endName = reader.getLocalName();
                        if ("Issue".equals(endName)) {
                            // Defensive: ensure at least a key is present
                            if (key != null) {
                                Issue issue = new Issue(
                                        key,
                                        summary != null ? summary : "",
                                        description != null ? description : "",
                                        status != null ? status : "",
                                        assignee != null ? assignee : ""
                                );
                                issues.add(issue);
                            } else {
                                LOG.warn("Encountered Issue element without a key – skipped");
                            }
                        }
                        // Clear the context element after leaving it
                        currentElement = null;
                        break;
                }
            }
        } finally {
            try {
                reader.close();
            } catch (Exception e) {
                LOG.debug("Failed to close XMLStreamReader", e);
            }
        }
        LOG.info("Parsed {} issues from XML export", issues.size());
        return issues;
    }
}
```

