package com.example.jira.parser;

import com.example.jira.model.Issue;
import com.example.jira.util.CsvSanitizer;
import com.opencsv.CSVReader;
import com.opencsv.exceptions.CsvException;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

import java.io.*;
import java.util.ArrayList;
import java.util.List;

/**
 * Parses a JIRA CSV export safely.
 *
 * The expected columns (case‑insensitive) are:
 *   - "Issue key"
 *   - "Summary"
 *   - "Description"
 *   - "Status"
 *   - "Assignee"
 *
 * If the header does not contain those columns, the parser attempts a
 * best‑effort match based on partial names.
 *
 * All cell values are passed through {@link CsvSanitizer} so that the resulting
 * CSV can be re‑exported without risking formula injection.
 */
public final class JiraCsvParser {

    private static final Logger LOG = LoggerFactory.getLogger(JiraCsvParser.class);
    private static final String[] REQUIRED_HEADERS = {
            "Issue key", "Summary", "Description", "Status", "Assignee"
    };

    private JiraCsvParser() { /* utility */ }

    public static List<Issue> parse(InputStream in) throws IOException, CsvException {
        try (Reader reader = new BufferedReader(new InputStreamReader(in, "UTF-8"));
             CSVReader csvReader = new CSVReader(reader)) {

            List<String[]> allRows = csvReader.readAll();
            if (allRows.isEmpty()) {
                LOG.warn("Empty CSV file");
                return List.of();
            }

            // Detect column indexes
            String[] header = allRows.get(0);
            int[] idx = mapHeaderIndexes(header);

            List<Issue> issues = new ArrayList<>(allRows.size() - 1);
            for (int i = 1; i < allRows.size(); i++) {
                String[] row = allRows.get(i);
                // Some CSV exports have variable column counts; guard against OOB.
                String key = safeGet(row, idx[0]);
                String summary = safeGet(row, idx[1]);
                String description = safeGet(row, idx[2]);
                String status = safeGet(row, idx[3]);
                String assignee = safeGet(row, idx[4]);

                // Apply CSV sanitisation on all fields (especially if you later write them out).
                Issue issue = new Issue(
                        CsvSanitizer.sanitize(key),
                        CsvSanitizer.sanitize(summary),
                        CsvSanitizer.sanitize(description),
                        CsvSanitizer.sanitize(status),
                        CsvSanitizer.sanitize(assignee)
                );
                issues.add(issue);
            }

            LOG.info("Parsed {} issues from CSV export", issues.size());
            return issues;
        }
    }

    /** Map required column names (case‑insensitive) to their positions in the header. */
    private static int[] mapHeaderIndexes(String[] header) {
        int[] idx = new int[REQUIRED_HEADERS.length];
        for (int j = 0; j < idx.length; j++) {
            idx[j] = -1;
        }

        for (int col = 0; col < header.length; col++) {
            String colName = header[col].trim().toLowerCase();
            for (int req = 0; req < REQUIRED_HEADERS.length; req++) {
                if (colName.contains(REQUIRED_HEADERS[req].toLowerCase())) {
                    idx[req] = col;
                }
            }
        }

        // Verify all required columns were found
        for (int i = 0; i < idx.length; i++) {
            if (idx[i] == -1) {
                LOG.warn("Required column '{}' not found – using empty strings for that field", REQUIRED_HEADERS[i]);
                // Keep -1, safeGet will return empty string.
            }
        }
        return idx;
    }

    /** Safely retrieve an element from the row or return an empty string if OOB. */
    private static String safeGet(String[] row, int index) {
        if (index >= 0 && index < row.length) {
            return row[index];
        }
        return "";
    }
}
```

