## 7. High‑Level Facade – `JiraExportParser.java`

```java
package com.example.jira.parser;

import com.example.jira.model.Issue;
import com.opencsv.exceptions.CsvException;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

import javax.xml.stream.XMLStreamException;
import java.io.*;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.List;

/**
 * Convenience wrapper that detects whether the supplied file is XML or CSV
 * and invokes the correct safe parser.
 *
 * **Usage example (CLI)**:
 *
 * <pre>
 *   java -jar jira-export-parser.jar /path/to/export.xml
 * </pre>
 *
 * The program will print each parsed issue to STDOUT (you can replace this
 * with any further analysis routine).
 */
public final class JiraExportParser {

    private static final Logger LOG = LoggerFactory.getLogger(JiraExportParser.class);

    private JiraExportParser() { /* utility */ }

    /** Detect file type by simple content sniffing (first non‑whitespace char). */
    private static boolean isXml(InputStream in) throws IOException {
        in.mark(2048);
        BufferedReader br = new BufferedReader(new InputStreamReader(in, "UTF-8"));
        int ch;
        while ((ch = br.read()) != -1) {
            if (!Character.isWhitespace(ch)) {
                in.reset();
                return ch == '<';
            }
        }
        in.reset();
        return false;
    }

    /** Parse a file (XML or CSV) and return the list of issues. */
    public static List<Issue> parseFile(Path file) throws IOException, XMLStreamException, CsvException {
        try (InputStream raw = Files.newInputStream(file);
             BufferedInputStream bis = new BufferedInputStream(raw)) {
            if (isXml(bis)) {
                LOG.info("Detected XML JIRA export: {}", file);
                return JiraXmlParser.parse(bis);
            } else {
                LOG.info("Assuming CSV JIRA export: {}", file);
                return JiraCsvParser.parse(bis);
            }
        }
    }

    /** Simple CLI entry‑point – prints issues in a readable format. */
    public static void main(String[] args) {
        if (args.length != 1) {
            System.err.println("Usage: java -jar jira-export-parser.jar <path-to-jira-export>");
            System.exit(1);
        }

        Path exportPath = Path.of(args[0]);
        if (!Files.isRegularFile(exportPath)) {
            System.err.println("File not found or not a regular file: " + exportPath);
            System.exit(2);
        }

        try {
            List<Issue> issues = parseFile(exportPath);
            System.out.println("=== Parsed Issues ===");
            for (Issue i : issues) {
                System.out.println(i);
            }
            System.out.println("Total: " + issues.size());
        } catch (XMLStreamException | CsvException e) {
            LOG.error("Parsing failed: {}", e.getMessage(), e);
            System.exit(3);
        } catch (IOException e) {
            LOG.error("I/O error: {}", e.getMessage(), e);
            System.exit(4);
        }
    }
}
```

