// File: Frame.java
import java.nio.ByteBuffer;
import java.security.*;
import javax.crypto.*;
import javax.crypto.spec.SecretKeySpec;
import java.util.Arrays;

public final class Frame {
    public static final byte TYPE_IMAGE     = 0x01;
    public static final byte TYPE_HEARTBEAT = 0x02;
    public static final byte TYPE_CLOSE     = (byte)0xFF;

    // 32‑byte HMAC‑SHA256 key (must be the same on both ends)
    private static final byte[] HMAC_KEY = "ReplaceWithYour32ByteSecret!".getBytes(); // 32 bytes

    /** Build a raw frame (length prefix + header + payload) */
    public static byte[] build(byte type, long timestamp, byte[] payload) throws Exception {
        MessageDigest sha = MessageDigest.getInstance("SHA-256");
        byte[] hash = sha.digest(payload);

        // HMAC over (type|timestamp|payload|hash)
        Mac mac = Mac.getInstance("HmacSHA256");
        mac.init(new SecretKeySpec(HMAC_KEY, "HmacSHA256"));
        mac.update(type);
        mac.update(longToBytes(timestamp));
        mac.update(payload);
        mac.update(hash);
        byte[] macBytes = mac.doFinal();

        int total = 4 + 1 + 8 + 32 + payload.length + macBytes.length;
        ByteBuffer bb = ByteBuffer.allocate(total);
        bb.putInt(1 + 8 + 32 + payload.length + macBytes.length); // length after this int
        bb.put(type);
        bb.putLong(timestamp);
        bb.put(hash);
        bb.put(payload);
        bb.put(macBytes);
        return bb.array();
    }

    /** Parse a frame, verify HMAC & hash. Returns payload */
    public static byte[] parse(ByteBuffer buf) throws Exception {
        // Buffer already contains exactly one frame (no length prefix)
        byte type = buf.get();
        long ts   = buf.getLong();
        byte[] hash = new byte[32];
        buf.get(hash);
        // payload length = remaining - macSize
        int macSize = 32; // HMAC‑SHA256 output size
        int payloadLen = buf.remaining() - macSize;
        byte[] payload = new byte[payloadLen];
        buf.get(payload);
        byte[] recvMac = new byte[macSize];
        buf.get(recvMac);

        // Verify HMAC
        Mac mac = Mac.getInstance("HmacSHA256");
        mac.init(new SecretKeySpec(HMAC_KEY, "HmacSHA256"));
        mac.update(type);
        mac.update(longToBytes(ts));
        mac.update(payload);
        mac.update(hash);
        byte[] calcMac = mac.doFinal();
        if (!MessageDigest.isEqual(calcMac, recvMac)) {
            throw new SecurityException("HMAC verification failed");
        }

        // Verify SHA‑256
        MessageDigest sha = MessageDigest.getInstance("SHA-256");
        byte[] calcHash = sha.digest(payload);
        if (!MessageDigest.isEqual(calcHash, hash)) {
            throw new SecurityException("Payload hash mismatch");
        }

        // Optional: reject old timestamps (replay) – e.g., older than 5 min
        long now = System.currentTimeMillis();
        if (Math.abs(now - ts) > 5 * 60_000) {
            throw new SecurityException("Timestamp out of acceptance window");
        }

        // If we got here, the frame is authentic and intact
        return payload;
    }

    private static byte[] longToBytes(long v) {
        ByteBuffer bb = ByteBuffer.allocate(Long.BYTES);
        bb.putLong(v);
        return bb.array();
    }
}
```

- **HMAC key** must be provisioned securely (e.g., derived from a TLS‑session‑specific secret). For demo we hard‑code it.  
- The `parse` method throws a `SecurityException` on any integrity/authentication failure, which we’ll catch and close the socket.

### 2.3 Server – ImageServer.java  

```java
// File: ImageServer.java
import javax.net.ssl.*;
import java.io.*;
import java.net.*;
import java.nio.ByteBuffer;
import java.nio.file.*;
import java.security.KeyStore;
import java.util.concurrent.*;

public class ImageServer {
    private static final int PORT = 8443;
    private static final int HEARTBEAT_TIMEOUT_MS = 30_000; // 30 s

    private final SSLServerSocket serverSocket;
    private final ExecutorService pool = Executors.newCachedThreadPool();

    public ImageServer(String ksPath, char[] ksPass, String tsPath, char[] tsPass) throws Exception {
        SSLContext ctx = SSLContext.getInstance("TLSv1.2");
        KeyManagerFactory kmf = KeyManagerFactory.getInstance(KeyManagerFactory.getDefaultAlgorithm());
        TrustManagerFactory tmf = TrustManagerFactory.getInstance(TrustManagerFactory.getDefaultAlgorithm());

        KeyStore ks = KeyStore.getInstance("PKCS12");
        ks.load(new FileInputStream(ksPath), ksPass);
        kmf.init(ks, ksPass);

        KeyStore ts = KeyStore.getInstance("PKCS12");
        ts.load(new FileInputStream(tsPath), tsPass);
        tmf.init(ts);

        ctx.init(kmf.getKeyManagers(), tmf.getTrustManagers(), null);
        SSLServerSocketFactory ssf = ctx.getServerSocketFactory();
        this.serverSocket = (SSLServerSocket) ssf.createServerSocket(PORT);
        this.serverSocket.setNeedClientAuth(true); // enforce mutual auth
    }

    public void start() {
        System.out.println("Server listening on port " + PORT);
        while (true) {
            try {
                SSLSocket client = (SSLSocket) serverSocket.accept();
                client.setSoTimeout(HEARTBEAT_TIMEOUT_MS * 2); // read timeout
                pool.submit(() -> handleClient(client));
            } catch (IOException e) {
                e.printStackTrace();
            }
        }
    }

    private void handleClient(SSLSocket socket) {
        String clientInfo = socket.getInetAddress() + ":" + socket.getPort();
        System.out.println("[+] Connected: " + clientInfo);
        try (socket;
             InputStream in  = socket.getInputStream();
             OutputStream out = socket.getOutputStream()) {

            // Separate thread for periodic heartbeats sent **to** the client
            ScheduledExecutorService hb = Executors.newSingleThreadScheduledExecutor();
            hb.scheduleAtFixedRate(() -> {
                try {
                    byte[] hbFrame = Frame.build(Frame.TYPE_HEARTBEAT,
                            System.currentTimeMillis(),
                            new byte[0]);
                    out.write(hbFrame);
                    out.flush();
                } catch (Exception e) {
                    // If we cannot write, close socket (client probably dead)
                    try {
                        socket.close();
                    } catch (IOException ignored) {}
                }
            }, 0, HEARTBEAT_TIMEOUT_MS, TimeUnit.MILLISECONDS);

            // Main receive loop
            while (true) {
                // --- read length prefix (4 bytes) ---
                byte[] lenBytes = in.readNBytes(4);
                if (lenBytes.length < 4) throw new EOFException("Stream closed");
                int frameLen = ByteBuffer.wrap(lenBytes).getInt();

                // --- read the entire frame ---
                byte[] frameBytes = in.readNBytes(frameLen);
                if (frameBytes.length < frameLen) throw new EOFException("Incomplete frame");

                ByteBuffer frameBuf = ByteBuffer.wrap(frameBytes);
                byte[] payload = Frame.parse(frameBuf);
                byte type = frameBytes[0]; // first byte after length is type

                if (type == Frame.TYPE_IMAGE) {
                    // Store image with a timestamped filename
                    String fname = "recv_" + System.currentTimeMillis() + ".jpg";
                    Files.write(Paths.get(fname), payload);
                    System.out.println("[*] Saved image: " + fname);
                } else if (type == Frame.TYPE_HEARTBEAT) {
                    // Heartbeat from client – nothing else to do,
                    // read timeout will take care of missing ones.
                } else if (type == Frame.TYPE_CLOSE) {
                    System.out.println("[*] Received CLOSE from client");
                    break;
                }
            }
            hb.shutdownNow();
            System.out.println("[+] Connection closed: " + clientInfo);
        } catch (SecurityException sec) {
            System.err.println("[!] Security violation from " + clientInfo + ": " + sec.getMessage());
        } catch (IOException | RuntimeException e) {
            System.err.println("[!] Communication error (" + clientInfo + "): " + e);
        }
    }

    public static void main(String[] args) throws Exception {
        // args: serverKeystore.p12 serverPass clientTruststore.p12 trustPass
        if (args.length != 4) {
            System.err.println("Usage: ImageServer <serverKS> <KSpass> <trustStore> <TSpass>");
            System.exit(1);
        }
        ImageServer server = new ImageServer(args[0], args[1].toCharArray(),
                args[2], args[3].toCharArray());
        server.start();
    }
}
```

**Key security choices**

| Feature | Reason |
|---------|--------|
| **TLS 1.2+** (`SSLContext.getInstance("TLSv1.2")`) | Guarantees forward‑secrecy ciphers (ECDHE).|
| **Mutual auth** (`setNeedClientAuth(true)`) | Prevents unauthorized clients from connecting.|
| **Socket read timeout** (`setSoTimeout`) | Detects silent dead peers; also bounds DoS latency. |
| **HMAC + SHA‑256** per frame | Guarantees authenticity + integrity, independent of TLS. |
| **Timestamp window** (5 min) | Mitigates replay attacks if an attacker captures frames. |
| **Fixed max image size** (optional) – not shown – you can reject payloads bigger than e.g., 5 MB to limit memory exhaustion. |

