    private static final int PORT = 8443;
    private static final int HEARTBEAT_INTERVAL_MS = 30_000;
    private static final int RECONNECT_DELAY_MS = 5_000;

    private final SSLSocket socket;
    private final OutputStream out;
    private final InputStream in;

    public ImageClient(String ksPath, char[] ksPass,
                       String tsPath, char[] tsPass) throws Exception {
        SSLContext ctx = SSLContext.getInstance("TLSv1.2");
        KeyManagerFactory kmf = KeyManagerFactory.getInstance(KeyManagerFactory.getDefaultAlgorithm());
        TrustManagerFactory tmf = TrustManagerFactory.getInstance(TrustManagerFactory.getDefaultAlgorithm());

        KeyStore ks = KeyStore.getInstance("PKCS12");
        ks.load(new FileInputStream(ksPath), ksPass);
        kmf.init(ks, ksPass);

        KeyStore ts = KeyStore.getInstance("PKCS12");
        ts.load(new FileInputStream(tsPath), tsPass);
        tmf.init(ts);

        ctx.init(kmf.getKeyManagers(), tmf.getTrustManagers(), null);
        SSLSocketFactory sf = ctx.getSocketFactory();
        this.socket = (SSLSocket) sf.createSocket(HOST, PORT);
        this.socket.startHandshake(); // explicit handshake
        this.out = socket.getOutputStream();
        this.in = socket.getInputStream();
    }

    /** A runnable that periodically sends heartbeats to the server */
    private ScheduledFuture<?> startHeartbeats() {
        ScheduledExecutorService executor = Executors.newSingleThreadScheduledExecutor();
        return executor.scheduleAtFixedRate(() -> {
            try {
                byte[] hb = Frame.build(Frame.TYPE_HEARTBEAT,
                        System.currentTimeMillis(),
                        new byte[0]);
                out.write(hb);
                out.flush();
            } catch (Exception e) {
                System.err.println("[!] Heartbeat failed: " + e.getMessage());
                // Let the outer logic close the socket.
            }
        }, 0, HEARTBEAT_INTERVAL_MS, TimeUnit.MILLISECONDS);
    }

    /** Send a single image file */
    public void sendImage(Path imgPath) throws Exception {
        byte[] payload = Files.readAllBytes(imgPath);
        byte[] frame = Frame.build(Frame.TYPE_IMAGE,
                System.currentTimeMillis(),
                payload);
        out.write(frame);
        out.flush();
        System.out.println("[*] Sent image " + imgPath.getFileName());
    }

    /** Receive frames (e.g., ACKs or server‑initiated heartbeats) */
    public void receiveLoop() {
        try {
            while (true) {
                byte[] lenBytes = in.readNBytes(4);
                if (lenBytes.length < 4) throw new EOFException();
                int frameLen = ByteBuffer.wrap(lenBytes).getInt();

                byte[] frame = in.readNBytes(frameLen);
                if (frame.length < frameLen) throw new EOFException();
                ByteBuffer bb = ByteBuffer.wrap(frame);
                byte type = frame[0];

                // For this simple demo we don’t expect payload from server,
                // just verify integrity.
                Frame.parse(bb);
                if (type == Frame.TYPE_HEARTBEAT) {
                    // server heartbeat – nothing to do
                } else if (type == Frame.TYPE_CLOSE) {
                    System.out.println("[*] Server closed connection");
                    break;
                }
            }
        } catch (IOException | SecurityException e) {
            System.err.println("[!] Receive error: " + e.getMessage());
        }
    }

    public void close() throws IOException {
        // send graceful CLOSE frame
        try {
            byte[] close = Frame.build(Frame.TYPE_CLOSE,
                    System.currentTimeMillis(),
                    new byte[0]);
            out.write(close);
            out.flush();
        } finally {
            socket.close();
        }
    }

    /** Demo driver – watches a directory and pushes new images */
    public static void main(String[] args) throws Exception {
        if (args.length != 4) {
            System.err.println("Usage: ImageClient <clientKS> <KSpass> <trustStore> <TSpass>");
            System.exit(1);
        }

        ImageClient client = new ImageClient(args[0], args[1].toCharArray(),
                args[2], args[3].toCharArray());

        ScheduledFuture<?> hb = client.startHeartbeats();

        // In a separate thread, read server messages (optional)
        new Thread(client::receiveLoop, "Receiver").start();

        // Demo: read all images from a local folder and send one per 2 seconds
        Path imgDir = Paths.get("test-images");
        int i = 0;
        try (DirectoryStream<Path> ds = Files.newDirectoryStream(imgDir, "*.{jpg,jpeg,png}")) {
            for (Path p : ds) {
                client.sendImage(p);
                Thread.sleep(2_000);
            }
        }

        // Graceful shutdown
        client.close();
        hb.cancel(true);
        System.out.println("[*] Client finished");
    }
}
```

