```java
package com.example.security;

import java.lang.reflect.Method;
import java.util.Arrays;

public class SecurityInterceptor {

    public static void checkAccess(Object target, String methodName, Object... args) {
        try {
            Method method = target.getClass().getMethod(methodName, toClasses(args));
            RequiresRole annotation = method.getAnnotation(RequiresRole.class);
            if (annotation != null) {
                String currentUserRole = CurrentUserHolder.getRole(); // ваш способ получения роли
                boolean allowed = Arrays.stream(annotation.value())
                                         .anyMatch(r -> r.equalsIgnoreCase(currentUserRole));
                if (!allowed) {
                    if (annotation.failFast()) {
                        throw new SecurityException("Access denied for role: " + currentUserRole);
                    } else {
                        System.out.println("Access denied, but failFast=false");
                        // можно вернуть false/null вместо броска
                    }
                }
            }
        } catch (NoSuchMethodException e) {
            throw new RuntimeException(e);
        }
    }

    private static Class<?>[] toClasses(Object[] args) {
