Если вам нужно проверить корректность использования аннотации **до выполнения кода**, реализуйте процессор:

```java
package com.example.processor;

import com.example.security.RequiresRole;
import javax.annotation.processing.*;
import javax.lang.model.SourceVersion;
import javax.lang.model.element.*;
import java.util.Set;

@SupportedAnnotationTypes("com.example.security.RequiresRole")
@SupportedSourceVersion(SourceVersion.RELEASE_17) // или ваш уровень Java
public class RequiresRoleProcessor extends AbstractProcessor {

    @Override
    public boolean process(Set<? extends TypeElement> annotations, RoundEnvironment roundEnv) {
        for (Element elem : roundEnv.getElementsAnnotatedWith(RequiresRole.class)) {
            // Пример проверки: аннотация не должна использоваться на приватных методах
            if (elem.getKind() == ElementKind.METHOD) {
                Set<Modifier> modifiers = elem.getModifiers();
                if (modifiers.contains(Modifier.PRIVATE)) {
                    processingEnv.getMessager().printMessage(
                        Diagnostic.Kind.ERROR,
                        "@RequiresRole cannot be applied to private methods",
                        elem);
                }
            }
        }
        return true; // аннотация обработана
    }
}
```

