## 7️⃣ SecurityConfig

```java
@EnableWebSecurity
@RequiredArgsConstructor
public class SecurityConfig {

    private final CustomUserDetailsService userDetailsService;
    private final JwtUtil jwtUtil;
    private final PasswordEncoder passwordEncoder;

    @Bean
    public AuthenticationManager authManager(HttpSecurity http) throws Exception {
        return http.getSharedObject(AuthenticationManagerBuilder.class)
                .userDetailsService(userDetailsService)
                .passwordEncoder(passwordEncoder)
                .and()
                .build();
    }

    @Bean
    public SecurityFilterChain filterChain(HttpSecurity http) throws Exception {
        JwtAuthenticationFilter jwtFilter = new JwtAuthenticationFilter(jwtUtil, userDetailsService);

        http
            // ---- CORS / CSRF ----
            .cors().and()
            .csrf().disable() // для чисто API, токен CSRF не нужен

            // ---- Session ----
            .sessionManagement()
                .sessionCreationPolicy(SessionCreationPolicy.STATELESS)
                .and()

            // ---- Endpoints ----
            .authorizeHttpRequests(authz -> authz
                .requestMatchers("/api/auth/**").permitAll()
                .requestMatchers(HttpMethod.GET, "/api/public/**").permitAll()
                .anyRequest().authenticated()
            )

            // ---- Exception handling ----
            .exceptionHandling()
                .authenticationEntryPoint((req, rsp, e) -> {
                    rsp.setContentType(MediaType.APPLICATION_JSON_VALUE);
                    rsp.setStatus(HttpServletResponse.SC_UNAUTHORIZED);
                    rsp.getWriter().write("{\"error\":\"Unauthorized\"}");
                })
                .and()

            // ---- Filters ----
            .addFilterBefore(jwtFilter, UsernamePasswordAuthenticationFilter.class);

        return http.build();
    }

    @Bean
    public CorsConfigurationSource corsConfigurationSource() {
        CorsConfiguration cfg = new CorsConfiguration();
        cfg.setAllowedOrigins(List.of("https://myfrontend.example.com"));
        cfg.setAllowedMethods(List.of("GET","POST","PUT","DELETE","OPTIONS"));
        cfg.setAllowedHeaders(List.of("*"));
        cfg.setAllowCredentials(true);
        UrlBasedCorsConfigurationSource source = new UrlBasedCorsConfigurationSource();
        source.registerCorsConfiguration("/**", cfg);
        return source;
    }
}
```

- **CSRF:** Отключаем, потому что клиент будет отправлять токен в `Authorization`‑заголовке. Если вы используете **HttpOnly cookie** вместо заголовка, включайте CSRF‑защиту.
- **CORS:** Ограничьте лишь доверенными доменами. Не используйте `"*"` в продакшене.

