## 1️⃣ Android Java version

```java
import android.graphics.PointF;
import java.util.ArrayList;
import java.util.List;

/**
 * Utility class that contains the same behaviour as the original JS code.
 * All methods are static for easy reuse.
 */
public final class TrailSmoother {

    private TrailSmoother() { /* prevent instantiation */ }

    /**
     * Re‑applies the smoothing {@code number} times.
     *
     * @param points the original list of points (may be null)
     * @param number how many iterations of smoothing to perform
     * @return a new List<PointF> with the smoothed coordinates
     */
    public static List<PointF> fittingTrailsMultiple(List<PointF> points, int number) {
        // If a null list is supplied we simply return an empty list – Java never has
        // a global “trailPoints” variable, so the caller must provide something.
        List<PointF> newPoints = (points != null) ? points : new ArrayList<>();

        for (int i = 0; i < number; i++) {
            newPoints = fittingTrails(newPoints);
        }
        return newPoints;
    }

    /**
     * One pass of the 5‑point averaging filter.
     *
     * @param points input poly‑line
     * @return a new List<PointF> with the filtered data
     */
    public static List<PointF> fittingTrails(List<PointF> points) {
        List<PointF> newPoints = new ArrayList<>(points.size());

        for (int i = 0; i < points.size(); i++) {
            // Keep the first two and last two points untouched – the original
            // JS used `i > 2 && i < points.length - 2` (note the off‑by‑one
            // because JS loops over *keys*).  In Java we start at 0, so we
            // need `i >= 2 && i < points.size() - 2`.
            if (i >= 2 && i < points.size() - 2) {
                newPoints.add(pointsAvg(points, i));
            } else {
                // Clone the point to avoid accidental aliasing of the original objects
                PointF src = points.get(i);
                newPoints.add(new PointF(src.x, src.y));
            }
        }
        return newPoints;
    }

    /**
     * Compute the average of five consecutive points centred on index {@code i}.
     *
     * @param points the full list (must have at least {@code i‑2}…{@code i+2})
     * @param i      centre index
     * @return a new PointF that represents the averaged coordinate
     */
    private static PointF pointsAvg(List<PointF> points, int i) {
        // Defensive bounds‑checking – the original JS assumed the caller never
        // asked for an out‑of‑range index, which can lead to a runtime error.
        if (i - 2 < 0 || i + 2 >= points.size()) {
            // If something went wrong we simply return the original point.
            // In a production app you might want to throw an exception instead.
            return new PointF(points.get(i).x, points.get(i).y);
        }

        float sumX = 0f;
        float sumY = 0f;
        for (int offset = -2; offset <= 2; offset++) {
            PointF p = points.get(i + offset);
            sumX += p.x;
            sumY += p.y;
        }
        return new PointF(sumX / 5f, sumY / 5f);
    }
}
```

