## 2️⃣ Kotlin version (if you prefer idiomatic Kotlin)

```kotlin
import android.graphics.PointF

object TrailSmoother {

    /**
     * Apply the smoothing filter [iterations] times.
     */
    fun fittingTrailsMultiple(
        points: List<PointF>?, iterations: Int
    ): List<PointF> {
        var newPoints = points?.toMutableList() ?: mutableListOf()
        repeat(iterations) {
            newPoints = fittingTrails(newPoints)
        }
        return newPoints
    }

    /**
     * One pass of the 5‑point average.
     */
    private fun fittingTrails(points: List<PointF>): List<PointF> {
        val result = mutableListOf<PointF>()
        for (i in points.indices) {
            if (i >= 2 && i < points.size - 2) {
                result.add(pointsAvg(points, i))
            } else {
                val p = points[i]
                result.add(PointF(p.x, p.y)) // copy to avoid aliasing
            }
        }
        return result
    }

    /**
     * Average of the 5 points centred on [centerIdx].
     */
    private fun pointsAvg(points: List<PointF>, centerIdx: Int): PointF {
        // Defensive guard – should never hit because the caller checks the range.
        if (centerIdx - 2 < 0 || centerIdx + 2 >= points.size) {
            return PointF(points[centerIdx].x, points[centerIdx].y)
        }

        var sumX = 0f
        var sumY = 0f
        for (offset in -2..2) {
            val p = points[centerIdx + offset]
            sumX += p.x
            sumY += p.y
        }
        return PointF(sumX / 5f, sumY / 5f)
    }
}
```

