package com.example.fiscal.service;

import com.example.fiscal.crypto.CmsSigner;
import com.example.fiscal.model.FiscalRequest;
import com.example.fiscal.security.KeyStoreHelper;
import com.fasterxml.jackson.databind.ObjectMapper;
import jakarta.validation.*;
import org.springframework.http.MediaType;
import org.springframework.stereotype.Service;
import org.springframework.web.reactive.function.client.*;

import java.security.PrivateKey;
import java.security.cert.X509Certificate;
import java.time.OffsetDateTime;
import java.util.*;

@Service
public class FiscalisationService {

    private static final String TAX_ENDPOINT = "https://fiskalizacija.porezna.hr/api/v1/transaction";
    private final WebClient webClient;
    private final ObjectMapper mapper;
    private final Validator validator;

    // Loaded once at startup
    private final PrivateKey privateKey;
    private final X509Certificate[] certChain;
    private final String fiscalisationId; // configured from properties

    public FiscalisationService(ObjectMapper mapper,
                                WebClient.Builder clientBuilder,
                                ValidatorFactory validatorFactory,
                                // inject config values via @Value or constructor params
                                String pkcs12Path,
                                char[] keystorePassword,
                                String keyAlias,
                                String fiscalisationId) throws Exception {

        this.mapper = mapper;
        this.validator = validatorFactory.getValidator();

        this.privateKey = KeyStoreHelper.loadPrivateKey(pkcs12Path, keystorePassword, keyAlias);
        this.certChain = KeyStoreHelper.loadCertificateChain(pkcs12Path, keystorePassword, keyAlias);
        this.fiscalisationId = fiscalisationId;

        // Configure TLS – enable only TLSv1.2+ and pin the server certificate
        this.webClient = clientBuilder
                .baseUrl(TAX_ENDPOINT)
                .defaultHeader("Content-Type", MediaType.APPLICATION_JSON_VALUE)
                .clientConnector(new ReactorClientHttpConnector(
                        HttpClient.create()
                                .secure(t -> t
                                        .sslContext(SslContextBuilder.forClient()
                                                .trustManager(InsecureTrustManagerFactory.INSTANCE) // replace with proper trust store
                                                .protocols("TLSv1.2", "TLSv1.3")
                                                .build())
                                        .defaultConfiguration(ChannelOption.CONNECT_TIMEOUT_MILLIS, 5000))
                ))
                .build();
    }

    public FiscalResponse sendReceipt(FiscalRequest.Item... items) throws Exception {
        // Build request payload (without signature)
        String requestId = UUID.randomUUID().toString();
        FiscalRequest unsig = new FiscalRequest(
                fiscalisationId,
                "CR-001",            // cash register identifier – configurable
                requestId,
                OffsetDateTime.now(),
                List.of(items),
                calculateTotal(items),
                "" // placeholder for signature
        );

        // Validate bean constraints (prevents malformed request)
        Set<ConstraintViolation<FiscalRequest>> violations = validator.validate(unsig);
        if (!violations.isEmpty()) {
            throw new ConstraintViolationException("Invalid fiscal request", violations);
        }

        // Serialize to canonical JSON (no pretty printing, stable key order)
        byte[] jsonBytes = mapper.writer()
                .withDefaultPrettyPrinter()
                .writeValueAsBytes(unsig); // mutable JSON slice – later we replace signature

        // Create CMS detached signature
        String signatureB64 = CmsSigner.signDetached(jsonBytes, privateKey, certChain);

        // Re-serialize with signature
        FiscalRequest signed = new FiscalRequest(
                fiscalisationId,
                unsig.cashRegisterId(),
                requestId,
                unsig.timestamp(),
                unsig.items(),
                unsig.totalAmount(),
                signatureB64
        );

        // POST the request
        FiscalResponse response = webClient.post()
                .uri("")
                .bodyValue(signed)
                .retrieve()
                .onStatus(HttpStatus::isError, clientResponse ->
                        clientResponse.bodyToMono(String.class)
                                .flatMap(body -> Mono.error(new RuntimeException(
                                        "Fiscal API error: " + clientResponse.statusCode() + " body: " + body))))
                .bodyToMono(FiscalResponse.class)
                .block(); // Blocking is OK inside a service call; replace with reactive chain if needed

        // Basic response validation
        if (!"OK".equalsIgnoreCase(response.status())) {
            throw new IllegalStateException("Fiscalisation rejected: " + response.errorMessage());
        }

        // Persist the receipt + response atomically
        persistReceipt(signed, response);

        return response;
    }

    private static java.math.BigDecimal calculateTotal(FiscalRequest.Item... items) {
        return Arrays.stream(items)
                .map(item -> item.unitPrice().multiply(item.quantity())
                        .add(item.taxAmount()))
                .reduce(java.math.BigDecimal.ZERO, java.math.BigDecimal::add);
    }

    private void persistReceipt(FiscalRequest request, FiscalResponse response) {
        // Example: write to an append‑only log (Kafka, DB, or WORM file)
        // You should also compute a hash chain: hash = SHA256(prevHash || request || response)
        // ... omitted for brevity
    }

    // POJO for the fiscal response (according to spec)
    public static record FiscalResponse(
            String status,
            String errorMessage,
            String ZKI,
            String JIR,
            OffsetDateTime serverTimestamp) {}
}
```

**Key Hardening Points**

1. **TLS Pinning** – Replace `InsecureTrustManagerFactory.INSTANCE` with a custom `TrustManagerFactory` that loads only the Porezna root CA (or the exact server cert).  
2. **Connection Timeouts & Retry** – Add `retryWhen(Retry.backoff(3, Duration.ofSeconds(2)))` on the `WebClient` pipeline, and a **dead‑letter queue** if the service is unavailable for > 5 mins.  
3. **Zero‑pad Private‑Key Buffers** – After signing, call `java.security.PrivateKey.destroy()` if the implementation supports it, and overwrite the `byte[]` that held the JSON payload.  
4. **Audit Logging** – Use an **append‑only log** (`Kafka` with log compaction disabled or `EventStoreDB`). Pre‑pend each entry with a **hash chain**; compute `hash_i = SHA256(hash_{i‑1} || entry)`. Store the final hash in a tamper‑evident external system (e.g., a blockchain anchor or a cloud KMS *digest*).  

