## 3. 客服端（Server + ServerHandler）

### 3.1 主服务器入口 `Server`

```java
// Server.java
package com.ecommerce.chat;

import java.io.IOException;
import java.net.*;
import java.util.*;
import java.util.concurrent.*;
import javax.swing.*;

public class Server {
    private static final int PORT = 9000;
    private ServerSocket serverSocket;
    private ExecutorService pool = Executors.newCachedThreadPool(); // 多用户
    /** 在线客服人员（可自行扩展） */
    private final List<Agent> agents = Collections.synchronizedList(new ArrayList<>());

    /** 简单的 “客服 UI” 用 Swing 实现，便于实时观察请求 */
    private final ServerUI ui = new ServerUI();

    public static void main(String[] args) {
        new Server().start();
    }

    public void start() {
        try {
            serverSocket = new ServerSocket(PORT);
            ui.log("服务器已启动，监听端口 " + PORT);
            // 启动固定数量的客服（示例 2 位）
            agents.add(new Agent("Agent-1"));
            agents.add(new Agent("Agent-2"));
            ui.refreshAgentList(agents);

            while (true) {
                Socket client = serverSocket.accept();
                pool.execute(new ServerHandler(client, this));
            }
        } catch (IOException e) {
            ui.log("服务器异常：" + e.getMessage());
        } finally {
            shutdown();
        }
    }

    /** 查找空闲客服 */
    public Agent findFreeAgent() {
        synchronized (agents) {
            for (Agent a : agents) {
                if (!a.isBusy()) {
                    return a;
                }
            }
        }
        return null; // 都忙
    }

    /** 当有新用户请求时弹框让客服选择 */
    public void notifyNewRequest(String userName, ServerHandler handler) {
        SwingUtilities.invokeLater(() -> {
            int opt = JOptionPane.showConfirmDialog(
                    ui,
                    "用户 [" + userName + "] 请求客服帮助，是否接受？",
                    "新请求",
                    JOptionPane.YES_NO_OPTION);
            if (opt == JOptionPane.YES_OPTION) {
                Agent agent = findFreeAgent();
                if (agent == null) {
                    // 所有客服忙，向用户发送 BUSY 提示
                    handler.send(Message.notice("SYSTEM", "所有客服当前忙，请稍后再试。"));
                    handler.close();
                } else {
                    agent.setBusy(true);
                    ui.log(agent.getName() + " 已接受用户 " + userName);
                    handler.setAgent(agent);
                    handler.send(Message.serviceResponse(agent.getName(), true));
                }
            } else {
                handler.send(Message.serviceResponse("SYSTEM", false));
                handler.close();
            }
        });
    }

    /** 客服结束会话后调用 */
    public void finishSession(ServerHandler handler) {
        Agent a = handler.getAgent();
        if (a != null) {
            a.setBusy(false);
            ui.log(a.getName() + " 已结束与 " + handler.getUserName() + " 的会话");
            ui.refreshAgentList(agents);
        }
        handler.close();
    }

    private void shutdown() {
        try {
            if (serverSocket != null && !serverSocket.isClosed())
                serverSocket.close();
        } catch (IOException ignored) {}
        pool.shutdownNow();
    }

    /** 简易的客服信息结构 */
    static class Agent {
        private final String name;
        private boolean busy = false;
        Agent(String n){ this.name=n; }
        public String getName(){ return name; }
        public boolean isBusy(){ return busy; }
        public void setBusy(boolean b){ this.busy=b; }
    }
}
```

### 3.2 每个用户的业务处理 `ServerHandler`

```java
// ServerHandler.java
package com.ecommerce.chat;

import java.io.*;
import java.net.Socket;

/**
 * 与单个用户对应的线程（由 Server 的线程池调度）。
 * 完成以下职责：
 *   1. 收到用户的第一次连接后，立刻向 Server 报告“新请求”，等待客服响应。
 *   2. 在客服接受后，转发双方的文字、图片、文件。
 *   3. 将所有文字消息持久化到 ChatRecord（图片/文件仅记录提示）。
 *   4. 客服主动发送 END/NOTICE 时关闭会话。
 */
public class ServerHandler implements Runnable {
    private final Socket socket;
    private final Server server;
    private ObjectInputStream in;
    private ObjectOutputStream out;
    private String userName;          // 如 "user-Alice"
    private Server.Agent agent;       // 分配的客服
    private ChatRecord record;

    public ServerHandler(Socket socket, Server server) {
        this.socket = socket;
        this.server = server;
    }

    public String getUserName() { return userName; }
    public Server.Agent getAgent() { return agent; }
    public void setAgent(Server.Agent a) { this.agent = a; }

    /** 发送消息给当前用户（已经建立 out） */
    public void send(Message m) {
        try {
            out.writeObject(m);
            out.flush();
        } catch (IOException e) {
            System.err.println("发送消息失败: " + e.getMessage());
        }
    }

    /** 主循环 */
    @Override
    public void run() {
        try {
            // 注意：先创建 Output 再创建 Input，避免阻塞
            out = new ObjectOutputStream(socket.getOutputStream());
            out.flush();
            in = new ObjectInputStream(socket.getInputStream());

            // 第一次收到的消息必须是用户的登录/发起请求
            Message first = (Message) in.readObject();
            if (first.getType() != Message.Type.TEXT || first.getText() == null) {
                send(Message.notice("SYSTEM", "非法的首次消息，连接强制关闭"));
                close();
                return;
            }
            this.userName = first.getFrom(); // 约定：first.text 为用户名
            this.record = new ChatRecord(userName);
            server.ui.log("新用户连接: " + userName);
            // 将历史记录回发给用户（客户端自行展示）
            send(Message.text("SYSTEM", "=== 历史记录 ===\n" + record.readAll()));

            // 报告 Server，等待客服接收/拒绝
            server.notifyNewRequest(userName, this);

            // 循环读取用户/客服发送的消息
            while (true) {
                Message msg = (Message) in.readObject();
                if (msg == null) break;

                // 根据不同类型处理
                switch (msg.getType()) {
                    case TEXT:
                        // 记录到本地
                        record.append(userName, msg.getText());
                        // 转发给客服（如果已分配）
                        if (agent != null) {
                            // 这里直接把消息写回同一 socket 给客服端的 UI（模拟）
                            // 实际项目中可以使用独立的客服 Socket 进行双向通信
                            // 为了演示，这里把消息再发送回客户端，客服 UI 会拦截
                            // （下文客服 UI 使用同一 ServerHandler 发送消息）
                            // 这里不做特殊处理，仅记录
                        }
                        break;
                    case IMAGE:
                        record.append(userName, "[图片] " + msg.getExtra());
                        // 实际传输的二进制已在msg.data里，直接转发
                        // 这里演示直接回发给客服 UI（同上）
                        break;
                    case FILE:
                        record.append(userName, "[文件] " + msg.getExtra());
                        break;
                    case SERVICE_RESPONSE:
                        // 这类消息只会由客服端发回，不会在此出现
                        break;
                    case END:
                        // 客服结束会话
                        server.finishSession(this);
                        return;
                    case NOTICE:
                        // 系统通知，可直接记录
                        record.append("SYSTEM", msg.getText());
                        break;
                    default:
                        break;
                }
            }
        } catch (Exception e) {
            System.err.println("会话异常: " + e.getMessage());
        } finally {
            close();
        }
    }

    /** 关闭所有资源 */
    public void close() {
        try { if (in != null) in.close(); } catch (Exception ignored) {}
        try { if (out != null) out.close(); } catch (Exception ignored) {}
        try { if (socket != null && !socket.isClosed()) socket.close(); } catch (Exception ignored) {}
    }
}
```

> **注意**  
> - 为了示例代码简洁，客服端 UI 与 `ServerHandler` 共享同一 Socket（即客服 UI 直接操作 `ServerHandler` 发送/接收消息）。实际生产环境应使用 **双端 Socket**：客户端与服务器的 **两个独立线程**（分别对应用户和客服），或使用 **WebSocket**、**HTTP 长轮询** 等协议。  

### 3.3 简易客服 UI `ServerUI`

```java
// ServerUI.java
package com.ecommerce.chat;

import java.awt.*;
import java.util.List;
