## 4. 用户端（Client + ClientUI）

### 4.1 客户端入口 `Client`

```java
// Client.java
package com.ecommerce.chat;

import java.io.*;
import java.net.Socket;
import java.util.concurrent.*;

public class Client {
    private static final String HOST = "127.0.0.1";
    private static final int PORT = 9000;
    private static final int BUSY_TIMEOUT_MS = 8000; // 8 秒未收到客服响应算忙

    private Socket socket;
    private ObjectOutputStream out;
    private ObjectInputStream in;
    private final ClientUI ui;
    private final String userName;
    private final ChatRecord record;
    private ScheduledExecutorService scheduler = Executors.newSingleThreadScheduledExecutor();

    public static void main(String[] args) throws Exception {
        // 简单的命令行参数：用户名
        String name = args.length > 0 ? args[0] : "user-" + System.currentTimeMillis();
        new Client(name).start();
    }

    public Client(String userName) throws IOException {
        this.userName = userName;
        this.ui = new ClientUI(this);
        this.record = new ChatRecord(userName);
    }

    public void start() throws IOException {
        socket = new Socket(HOST, PORT);
        out = new ObjectOutputStream(socket.getOutputStream());
        out.flush();
        in = new ObjectInputStream(socket.getInputStream());

        // 1️⃣ 发送首次握手消息（用户名为 from，内容为空）
        send(Message.text(userName, "HELLO"));  // 文本内容随便写，后端只取 from

        // 2️⃣ 启动接收线程
        new Thread(this::receiveLoop, "client-receiver").start();

        // 3️⃣ 开启“客服忙碌”检测定时器
        scheduler.schedule(() -> {
            // 如果在 BUSY_TIMEOUT_MS 内没有收到 SERVICE_RESPONSE，就认为忙
            if (!ui.isAgentConnected()) {
                ui.showBusyNotice();
                close();
            }
        }, BUSY_TIMEOUT_MS, TimeUnit.MILLISECONDS);
    }

    /** 发送消息（封装异常） */
    public void send(Message m) {
        try {
            out.writeObject(m);
            out.flush();
        } catch (IOException e) {
            ui.appendSystem("发送失败：" + e.getMessage());
        }
    }

    /** 接收循环：负责把服务器发来的文字、图片、文件显示在 UI 上 */
    private void receiveLoop() {
        try {
            while (true) {
                Message msg = (Message) in.readObject();
                if (msg == null) break;
                handleMessage(msg);
            }
        } catch (Exception e) {
            ui.appendSystem("连接已关闭或异常：" + e.getMessage());
        } finally {
            close();
        }
    }

    /** 处理来自服务器的各种消息 */
    private void handleMessage(Message msg) {
        switch (msg.getType()) {
            case TEXT:
                ui.appendFrom(msg.getFrom(), msg.getText());
                record.append(msg.getFrom(), msg.getText());
                break;
            case IMAGE:
                ui.appendImage(msg.getFrom(), msg.getData());
                record.append(msg.getFrom(), "[图片]");
                break;
            case FILE:
                ui.appendFile(msg.getFrom(), msg.getData(), msg.getExtra());
                record.append(msg.getFrom(), "[文件]" + msg.getExtra());
                break;
            case SERVICE_RESPONSE:
                // 客服是否接受
                if ("ACCEPT".equals(msg.getText())) {
                    ui.setAgentConnected(true);
                    ui.appendSystem("客服 [" + msg.getFrom() + "] 已接入，会话开始。");
                } else {
                    ui.appendSystem("客服已拒绝会话。");
                    close();
                }
                break;
            case NOTICE:
                ui.appendSystem("[系统通知] " + msg.getText());
                break;
            case END:
                ui.appendSystem("客服已结束会话。");
                close();
                break;
            default:
                break;
        }
    }

    /** 关闭资源，通知 UI */
    public void close() {
        try { if (in != null) in.close(); } catch (Exception ignored) {}
        try { if (out != null) out.close(); } catch (Exception ignored) {}
        try { if (socket != null && !socket.isClosed()) socket.close(); } catch (Exception ignored) {}
        scheduler.shutdownNow();
        ui.onConnectionClosed();
    }

    /** UI 需要的辅助方法 */
    public String getUserName() { return userName; }
    public ChatRecord getChatRecord() { return record; }
}
```

### 4.2 客户端 GUI `ClientUI`

```java
// ClientUI.java
package com.ecommerce.chat;

import java.awt.*;
import java.awt.event.*;
import java.io.*;
import java.nio.file.*;
import javax.imageio.ImageIO;
import javax.swing.*;

public class ClientUI extends JFrame {
    private final Client client;
    private JTextPane chatPane = new JTextPane();
    private JTextField inputField = new JTextField();
    private JButton sendBtn = new JButton("发送");
    private JButton imgBtn = new JButton("图片");
    private JButton fileBtn = new JButton("文件");
    private boolean agentConnected = false; // 是否已和客服连接

    public ClientUI(Client c) {
        this.client = c;
        setTitle("用户端 - " + c.getUserName());
        initUI();
        loadHistory();
        setDefaultCloseOperation(EXIT_ON_CLOSE);
        pack();
        setLocationRelativeTo(null);
        setVisible(true);
    }

    private void initUI() {
        chatPane.setEditable(false);
        JScrollPane scroll = new JScrollPane(chatPane);
        JPanel bottom = new JPanel(new BorderLayout(5,5));
        bottom.add(inputField, BorderLayout.CENTER);
        JPanel btns = new JPanel(new FlowLayout(FlowLayout.LEFT));
        btns.add(sendBtn);
        btns.add(imgBtn);
        btns.add(fileBtn);
        bottom.add(btns, BorderLayout.EAST);

        getContentPane().add(scroll, BorderLayout.CENTER);
        getContentPane().add(bottom, BorderLayout.SOUTH);

        // 事件
        sendBtn.addActionListener(e -> sendText());
        inputField.addActionListener(e -> sendText());
        imgBtn.addActionListener(e -> sendImage());
        fileBtn.addActionListener(e -> sendFile());
    }

    private void loadHistory() {
        String hist = client.getChatRecord().readAll();
        if (!hist.isEmpty()) {
            appendHTML("<i>--- 历史记录 ---</i><br>" + hist.replace("\n", "<br>") + "<br>");
        }
    }

    /** 发送文字 */
    private void sendText() {
        String txt = inputField.getText().trim();
        if (txt.isEmpty()) return;
        Message msg = Message.text(client.getUserName(), txt);
        client.send(msg);
        appendFrom(client.getUserName(), txt);
        client.getChatRecord().append(client.getUserName(), txt);
        inputField.setText("");
    }

    /** 发送图片（只支持 PNG/JPG） */
    private void sendImage() {
        JFileChooser fc = new JFileChooser();
        int rc = fc.showOpenDialog(this);
        if (rc != JFileChooser.APPROVE_OPTION) return;
        File f = fc.getSelectedFile();
        try {
            byte[] data = Files.readAllBytes(f.toPath());
            if (data.length > 5 * 1024 * 1024) {
                JOptionPane.showMessageDialog(this, "图片大小不得超过 5 MB");
                return;
            }
            Message msg = Message.image(client.getUserName(), data);
            client.send(msg);
            appendImage(client.getUserName(), data);
            client.getChatRecord().append(client.getUserName(), "[图片]");
        } catch (IOException ex) {
            JOptionPane.showMessageDialog(this, "读取图片失败：" + ex.getMessage());
        }
    }

    /** 发送任意文件（最大 10 MB） */
    private void sendFile() {
        JFileChooser fc = new JFileChooser();
        int rc = fc.showOpenDialog(this);
        if (rc != JFileChooser.APPROVE_OPTION) return;
        File f = fc.getSelectedFile();
        try {
            byte[] data = Files.readAllBytes(f.toPath());
            if (data.length > 10 * 1024 * 1024) {
                JOptionPane.showMessageDialog(this, "文件大小不得超过 10 MB");
                return;
            }
            Message msg = Message.file(client.getUserName(), data, f.getName());
            client.send(msg);
            appendFile(client.getUserName(), data, f.getName());
            client.getChatRecord().append(client.getUserName(), "[文件]" + f.getName());
        } catch (IOException ex) {
            JOptionPane.showMessageDialog(this, "读取文件失败：" + ex.getMessage());
        }
    }

    /** UI 辅助：追加文字 */
    public void appendFrom(String from, String text) {
        appendHTML("<b>" + from + ":</b> " + escapeHtml(text) + "<br>");
    }

    /** UI 辅助：系统提示 */
    public void appendSystem(String txt) {
        appendHTML("<i style='color:gray;'>" + escapeHtml(txt) + "</i><br>");
    }

    /** UI 辅助：图片 */
    public void appendImage(String from, byte[] data) {
        try {
            Image img = ImageIO.read(new ByteArrayInputStream(data));
            if (img != null) {
                ImageIcon ic = new ImageIcon(img.getScaledInstance(200, -1, Image.SCALE_SMOOTH));
                appendHTML("<b>" + from + ":</b> <br>");
                chatPane.insertIcon(ic);
                appendHTML("<br>");
            }
        } catch (IOException e) {
            appendSystem("图片显示错误：" + e.getMessage());
        }
    }

    /** UI 辅助：文件 */
    public void appendFile(String from, byte[] data, String fileName) {
        // 把文件写到本地的 downloads 目录，供用户打开
        try {
            Path dir = Paths.get("downloads");
            if (!Files.exists(dir)) Files.createDirectories(dir);
            Path out = dir.resolve(fileName);
            Files.write(out, data);
            appendHTML("<b>" + from + ":</b> <a href='file:///" + out.toAbsolutePath() + "'>"
                    + escapeHtml(fileName) + "</a><br>");
        } catch (IOException e) {
            appendSystem("文件保存错误：" + e.getMessage());
        }
    }

    /** 追加 HTML 到 JTextPane */
    private void appendHTML(String html) {
        try {
            HTMLEditorKit kit = (HTMLEditorKit) chatPane.getEditorKit();
            Document doc = chatPane.getDocument();
            kit.insertHTML((HTMLDocument) doc, doc.getLength(), html, 0, 0, null);
            chatPane.setCaretPosition(doc.getLength());
        } catch (Exception e) {
            // fallback: plain text
            try { chatPane.getDocument().insertString(chatPane.getDocument().getLength(),
                    html.replaceAll("<[^>]*>", ""), null); } catch (BadLocationException ignored) {}
        }
    }

    private String escapeHtml(String s) {
        return s.replace("&", "&amp;")
                .replace("<", "&lt;")
                .replace(">", "&gt;");
    }

    /** 在超时后提示“客服忙” */
    public void showBusyNotice() {
        appendSystem("[系统] 客服繁忙，稍后再试…");
    }

    /** 当连接关闭后禁用输入框 */
    public void onConnectionClosed() {
        inputField.setEnabled(false);
        sendBtn.setEnabled(false);
        imgBtn.setEnabled(false);
        fileBtn.setEnabled(false);
    }

    /** 设置是否已和客服建立会话（影响 UI 状态） */
    public void setAgentConnected(boolean flag) {
        this.agentConnected = flag;
        // 一旦接通，可开启发送按钮
        inputField.setEnabled(true);
        sendBtn.setEnabled(true);
        imgBtn.setEnabled(true);
        fileBtn.setEnabled(true);
    }

    public boolean isAgentConnected() {
        return agentConnected;
    }
}
```

> **重点说明**  
> 1. **超时检测**：`Client` 在发送第一次握手后，使用 `ScheduledExecutorService` 在 8 秒后检查 `ui.isAgentConnected()` 是否为 `true`，若仍为 `false`，则弹出 “客服忙” 提示并主动关闭连接。  
> 2. **图片/文件上限**：分别限制为 5 MB（图片）和 10 MB（文件），防止恶意上传导致 OOM。  
> 3. **聊天记录**：所有文字消息都会写入 `ChatRecord`（本地 `chats/<user>.log`），并在 UI 启动时回显。图片/文件只记录“[图片]”“[文件]文件名”。  
> 4. **线程安全**：`Server` 使用线程池，`ChatRecord.append` 为 `synchronized`，防止同一用户多次登录导致并发写。  

