package com.example.tcpsocket;

import android.os.Bundle;
import androidx.appcompat.app.AppCompatActivity;

/**
 * A thin activity that just starts a background TCP connection when the app launches.
 */
public class MainActivity extends AppCompatActivity {

    // Keep a reference so we can stop it when the Activity is destroyed.
    private NetworkConnection networkConnection;

    @Override
    protected void onCreate(Bundle savedInstanceState) {
        super.onCreate(savedInstanceState);
        // No UI needed for this demo – you could setContentView(R.layout.activity_main);
        // Start the network thread.
        networkConnection = new NetworkConnection("your.server.com", 12345);
        networkConnection.start();   // launches the internal thread
    }

    @Override
    protected void onDestroy() {
        super.onDestroy();
        // Gracefully stop the background thread and close the socket.
        if (networkConnection != null) {
            networkConnection.stop();
        }
    }
