public class OkHttpHelper {

    // ① 单例 OkHttpClient（推荐在 Application 中初始化，以便共享连接池、线程池）
    private static final OkHttpClient client = new OkHttpClient.Builder()
            .connectTimeout(15, TimeUnit.SECONDS)
            .readTimeout(20, TimeUnit.SECONDS)
            .writeTimeout(20, TimeUnit.SECONDS)
            // 开启日志（仅 Debug 环境，生产关闭）
            .addInterceptor(new HttpLoggingInterceptor().setLevel(HttpLoggingInterceptor.Level.BODY))
            // 如需证书钉扎，可在此加入 CertificatePinner
            .build();

    /**
     * POST 一个 JSON 字符串
     *
     * @param url      完整的 https://... URL
     * @param jsonBody 要发送的 JSON（已序列化的字符串）
     * @return 服务器响应体（String），或抛出 IOException
     */
    public static String postJson(String url, String jsonBody) throws IOException {
        MediaType JSON = MediaType.get("application/json; charset=utf-8");
        RequestBody body = RequestBody.create(jsonBody, JSON);

        Request request = new Request.Builder()
                .url(url)
                .post(body)
                // 这里可以自定义更多 Header
                .header("User-Agent", "MyApp/1.0")
                .build();

        try (Response response = client.newCall(request).execute()) {
            if (!response.isSuccessful()) {
                // 把错误码、错误体一起抛出，便于安全审计
                throw new IOException("Unexpected code " + response.code()
                        + " body:" + response.body().string());
            }
            // 读取响应体（自动关闭）
            return response.body().string();
        }
    }
}
```

