import java.io.*;
import java.net.*;
import java.util.concurrent.*;

/**
 * Server that receives {@link Packet}s on port 1024,
 * prints the content and replies with an ACK packet.
 *
 * ------------------------------------------------------------
 * Requirements fulfilled:
 *   • use getInputStream()   – to read the incoming bytes
 *   • use getOutputStream()  – to write the ACK packet back
 * ------------------------------------------------------------
 */
public class TCPPacketServer {

    private static final int PORT = 1024;
    /** a small thread‑pool so many clients can be served concurrently */
    private static final ExecutorService POOL = Executors.newFixedThreadPool(10);

    public static void main(String[] args) {
        System.out.println("TCPPacketServer – listening on port " + PORT);
        try (ServerSocket serverSocket = new ServerSocket(PORT)) {

            while (true) {
                Socket client = serverSocket.accept();
                System.out.println("New client: " + client.getRemoteSocketAddress());
                POOL.execute(new ClientHandler(client));
            }

        } catch (IOException e) {
            System.err.println("Server error: " + e.getMessage());
        } finally {
            POOL.shutdown();
        }
    }

    /** Handles a single client connection */
    private static class ClientHandler implements Runnable {
        private final Socket socket;
        private static int globalSerial = 0;   // only to illustrate that we can keep state

        ClientHandler(Socket socket) {
            this.socket = socket;
        }

        @Override
        public void run() {
            try (
                InputStream  in  = socket.getInputStream();   // <-- getInputStream()
                OutputStream out = socket.getOutputStream()    // <-- getOutputStream()
            ) {
                while (true) {
                    /* -------------------------------------------------------
                     * 1️⃣ Read a Packet object (the client uses ObjectOutputStream)
                     * ------------------------------------------------------- */
                    ObjectInputStream ois = new ObjectInputStream(in);
                    Packet received = (Packet) ois.readObject();

                    if ("CLOSE".equalsIgnoreCase(received.getData())) {
                        System.out.println("Client asked to close the connection.");
                        break;
                    }

                    System.out.println("FROM CLIENT " + socket.getRemoteSocketAddress()
                            + ": Packet SerialNo#" + received.getSerialNo()
                            + " – data = \"" + received.getData() + "\"");

                    /* -------------------------------------------------------
                     * 2️⃣ Build an ACK packet and send it back
                     * ------------------------------------------------------- */
                    Packet ack = new Packet(received.getSerialNo(), "ACK");
                    ByteArrayOutputStream baos = new ByteArrayOutputStream();
                    ObjectOutputStream oos = new ObjectOutputStream(baos);
                    oos.writeObject(ack);
                    oos.flush();

                    // write the raw bytes – exactly what the spec asks for
                    out.write(baos.toByteArray());
                    out.flush();
                }
            } catch (EOFException eof) {
                // client closed the socket abruptly – nothing to do
            } catch (IOException | ClassNotFoundException e) {
                System.err.println("Communication error with "
                        + socket.getRemoteSocketAddress() + ": " + e.getMessage());
            } finally {
                try {
                    socket.close();
                } catch (IOException ignore) { }
                System.out.println("Connection with client closed.");
            }
        }
    }
}
```

