import java.io.*;
import java.net.*;
import java.util.concurrent.atomic.AtomicInteger;

/**
 * Client that connects to TCPPacketServer (localhost:1024),
 * reads a line from the keyboard, wraps it into a {@link Packet},
 * sends it, receives an ACK packet and prints the result.
 *
 * ------------------------------------------------------------
 * Requirements fulfilled:
 *   • use Socket(host,1024)            – address of this computer
 *   • use getInputStream() / getOutputStream()
 *   • BufferedReader for keyboard input
 *   • PrintStream not needed for the packet part (binary data)
 * ------------------------------------------------------------
 */
public class TCPPacketClient {

    private static final String HOST = "localhost";
    private static final int PORT = 1024;
    private static final AtomicInteger SERIAL_GENERATOR = new AtomicInteger(1);

    public static void main(String[] args) {
        System.out.println("TCPPacketClient – connecting to " + HOST + ":" + PORT);

        try (Socket socket = new Socket(HOST, PORT);
             // keyboard input
             BufferedReader console = new BufferedReader(new InputStreamReader(System.in));
             // raw socket streams
             InputStream  in  = socket.getInputStream();   // <-- getInputStream()
             OutputStream out = socket.getOutputStream()    // <-- getOutputStream()
        ) {
            while (true) {
                System.out.print("Enter the data packet (type CLOSE to quit): ");
                String line = console.readLine();
                if (line == null) break;               // EOF on console

                // Build the packet
                int serial = SERIAL_GENERATOR.getAndIncrement();
                Packet pkt = new Packet(serial, line);

                // Serialize the packet and send it
                ByteArrayOutputStream baos = new ByteArrayOutputStream();
                ObjectOutputStream oos = new ObjectOutputStream(baos);
                oos.writeObject(pkt);
                oos.flush();
                out.write(baos.toByteArray());
                out.flush();

                // If the user typed CLOSE we stop after sending it
                if ("CLOSE".equalsIgnoreCase(line)) {
                    System.out.println("Sent CLOSE – terminating client.");
                    break;
                }

                /* -------------------------------------------------------
                 *  Wait for the ACK packet from the server
                 * ------------------------------------------------------- */
                ObjectInputStream ois = new ObjectInputStream(in);
                Packet ack = (Packet) ois.readObject();

                System.out.println("FROM SERVER: ACK received for SerialNo#"
                        + ack.getSerialNo() + " (data = \"" + ack.getData() + "\")");
            }

        } catch (IOException | ClassNotFoundException e) {
            System.err.println("Client error: " + e.getMessage());
        }
    }
}
```

