import java.io.*;
import java.net.*;

/**
 * “Message‑transform” server (mt‑server).
 * After the packet‑exchange phase the client may continue sending plain text.
 * For each line received the server returns the same line **in upper‑case**.
 *
 * ------------------------------------------------------------
 * Requirements fulfilled:
 *   • PrintStream ps = new PrintStream(socket.getOutputStream());
 *   • BufferedReader br = new BufferedReader(
 *            new InputStreamReader(socket.getInputStream()));
 * ------------------------------------------------------------
 */
public class MTServer {

    private static final int PORT = 8080;

    public static void main(String[] args) {
        System.out.println("MTServer – listening on port " + PORT);
        try (ServerSocket serverSocket = new ServerSocket(PORT)) {

            while (true) {
                Socket client = serverSocket.accept();
                System.out.println("Client connected from "
                        + client.getRemoteSocketAddress());

                // Each client handled in its own thread – the server can serve many
                new Thread(() -> handleClient(client)).start();
            }

        } catch (IOException e) {
            System.err.println("MTServer error: " + e.getMessage());
        }
    }

    private static void handleClient(Socket socket) {
        try (
            // Mandatory: use PrintStream for sending text
            PrintStream ps = new PrintStream(socket.getOutputStream(), true);
            // Mandatory: use BufferedReader for receiving text
            BufferedReader br = new BufferedReader(
                    new InputStreamReader(socket.getInputStream()));
        ) {
            // Simple greeting – not required by the spec but nice to have
            ps.println("WELCOME TO MT SERVER – send a line, I will uppercase it.");
            String line;

            while ((line = br.readLine()) != null) {
                if ("CLOSE".equalsIgnoreCase(line)) {
                    ps.println("GOODBYE");
                    System.out.println("Client requested CLOSE – terminating session.");
                    break;
                }
                String upper = line.toUpperCase();
                System.out.println("Received: \"" + line + "\" → replying \"" + upper + "\"");
                ps.println(upper);
            }

        } catch (IOException e) {
            System.err.println("Communication error with "
                    + socket.getRemoteSocketAddress() + ": " + e.getMessage());
        } finally {
            try {
                socket.close();
            } catch (IOException ignore) { }
        }
    }
}
```

