import java.io.*;
import java.net.*;

/**
 * Simple client that talks to MTServer (port 8080).
 * It reads a line from the keyboard, sends it, receives the upper‑cased
 * reply and prints it. Typing **CLOSE** terminates the session.
 *
 * ------------------------------------------------------------
 * Requirements fulfilled:
 *   • PrintStream ps = new PrintStream(socket.getOutputStream());
 *   • BufferedReader br = new BufferedReader(
 *            new InputStreamReader(socket.getInputStream()));
 * ------------------------------------------------------------
 */
public class MTClient {

    private static final String HOST = "localhost";
    private static final int PORT = 8080;

    public static void main(String[] args) {
        System.out.println("MTClient – connecting to " + HOST + ":" + PORT);
        try (Socket socket = new Socket(HOST, PORT);
             BufferedReader console = new BufferedReader(new InputStreamReader(System.in));
             PrintStream ps = new PrintStream(socket.getOutputStream(), true);
             BufferedReader br = new BufferedReader(
                     new InputStreamReader(socket.getInputStream()));
        ) {
            // Read and show the welcome line from the server
            System.out.println("[SERVER] " + br.readLine());

            while (true) {
                System.out.print("Enter text (CLOSE to quit): ");
                String line = console.readLine();
                if (line == null) break;

                ps.println(line);                     // send to server
                if ("CLOSE".equalsIgnoreCase(line)) {
                    System.out.println("Sent CLOSE – terminating client.");
                    break;
                }

                String reply = br.readLine();          // server's upper‑cased line
                System.out.println("[SERVER] " + reply);
            }

        } catch (IOException e) {
            System.err.println("MTClient error: " + e.getMessage());
        }
    }
}
