```java
package com.example.caesar;

/**
 * Реализация шифра Цезаря.
 * <p>
 * Поддерживает только латинские буквы (A‑Z, a‑z). 
 * Неалфавитные символы оставляются без изменений.
 */
public final class CaesarCipher {

    private CaesarCipher() {
        // Утилитный класс – нельзя создавать экземпляры
    }

    /**
     * Шифрует/расшифровывает заданный текст.
     *
     * @param text   исходный текст
     * @param shift  сдвиг (может быть отрицательным)
     * @return результат операции
     */
    public static String process(String text, int shift) {
        // Приводим сдвиг к диапазону [0, 25]
        int normalizedShift = ((shift % 26) + 26) % 26;
        StringBuilder sb = new StringBuilder(text.length());

        for (char c : text.toCharArray()) {
            sb.append(shiftChar(c, normalizedShift));
        }
        return sb.toString();
    }

    /**
     * Сдвигает одну букву на указанный шаг.
     *
     * @param c      исходный символ
     * @param shift  сдвиг в диапазоне [0, 25]
     * @return преобразованный символ
     */
    private static char shiftChar(char c, int shift) {
        if (c >= 'A' && c <= 'Z') {
            return (char) ('A' + (c - 'A' + shift) % 26);
        }
        if (c >= 'a' && c <= 'z') {
            return (char) ('a' + (c - 'a' + shift) % 26);
        }
        // Не буква – оставляем как есть
        return c;
    }
}
```

