            > encrypt   - зашифровать строку
            > decrypt   - расшифровать строку
            Введите команду (encrypt/decrypt) или 'exit' для выхода:
            """;

    public static void main(String[] args) {
        try (Scanner scanner = new Scanner(System.in)) {
            while (true) {
                System.out.println(USAGE);
                String command = scanner.nextLine().trim().toLowerCase();

                if ("exit".equals(command)) {
                    System.out.println("Bye!");
                    break;
                }

                if (!command.equals("encrypt") && !command.equals("decrypt")) {
                    System.out.println("Неправильная команда. Попробуйте ещё раз.");
                    continue;
                }

                System.out.print("Введите текст: ");
                String text = scanner.nextLine();

                System.out.print("Введите сдвиг (0‑25): ");
                int shift;
                try {
