package net.crud.springbootcrud.exception;

import org.springframework.ui.Model;
import org.springframework.web.bind.annotation.ControllerAdvice;
import org.springframework.web.bind.annotation.ExceptionHandler;
import org.springframework.web.servlet.mvc.support.RedirectAttributes;

@ControllerAdvice
public class GlobalExceptionHandler {

    @ExceptionHandler(IllegalArgumentException.class)
    public String handleBadRequest(IllegalArgumentException ex, Model model) {
        model.addAttribute("errorMessage", ex.getMessage());
        // You can render a generic error page or redirect to a specific view
        return "error/400";   // src/main/resources/templates/error/400.html
    }

    @ExceptionHandler(Exception.class)
    public String handleServerError(Exception ex, Model model) {
        model.addAttribute("errorMessage", "Unexpected server error – contact support.");
        // Log the full stack trace (never expose it to the client!)
        ex.printStackTrace();
        return "error/500";
    }
}
```

