                "-NoLogo",                 // не выводить баннер
                "-NoProfile",              // не загружать профиль
                "-Command", "-",           // читать команды из stdin
                "-ExecutionPolicy", "Bypass" // (по желанию) обход политики исполнения
        );

        // Перенаправляем ошибки в stdout, чтобы их не терять
        pb.redirectErrorStream(true);

        Process process = pb.start();

        // Потоки для общения с процессом
        try (BufferedWriter writer = new BufferedWriter(
                     new OutputStreamWriter(process.getOutputStream(), StandardCharsets.UTF_8));
             BufferedReader reader = new BufferedReader(
                     new InputStreamReader(process.getInputStream(), StandardCharsets.UTF_8))) {

            // Футур для асинхронного чтения вывода (чтобы избежать блокировок)
            ExecutorService exec = Executors.newSingleThreadExecutor();
            Future<Void> outputFuture = exec.submit(() -> {
                String line;
                while ((line = reader.readLine()) != null) {
                    System.out.println("[PS] " + line);
                }
                return null;
            });

            // Последовательно отсылаем команды в stdin
            for (String cmd : commands) {
                writer.write(cmd);
                writer.newLine();                // аналог Enter
                writer.flush();                  // отправляем сразу
                // Если нужна небольшая пауза, можно Thread.sleep(...);
            }

            // Закрываем ввод – это сигнал PowerShell, что больше команд нет
            writer.close();

            // Ожидаем завершения процесса (можно задать таймаут)
            int exitCode = process.waitFor();
            System.out.println("PowerShell завершился, код возврата = " + exitCode);

            // Дожидаемся, пока полностью выведется оставшийся вывод
            outputFuture.get(5, TimeUnit.SECONDS);
            exec.shutdownNow();
        } finally {
            // На всякий случай принудительно уничтожаем процесс
            process.destroyForcibly();
        }
    }
}
```

