// CustomerServiceServer.java
import javax.net.ssl.*;
import java.io.*;
import java.net.*;
import java.security.KeyStore;
import java.util.*;
import java.util.concurrent.*;

public class CustomerServiceServer {
    private static final int PORT = 8443;
    private static final int MAX_THREADS = 50; // 防止资源耗尽
    private final ExecutorService pool = Executors.newFixedThreadPool(MAX_THREADS);
    private final Map<String, AgentSession> agents = new ConcurrentHashMap<>(); // agentId → session
    private final Map<String, UserSession> users = new ConcurrentHashMap<>();   // userId → session
    private final BlockingQueue<UserRequest> pendingRequests = new LinkedBlockingQueue<>();

    // ====================== TLS 初始化 ======================
    private SSLServerSocketFactory createSslServerSocketFactory() throws Exception {
        // 这里使用 JKS，生产环境请使用 PKCS12 + 硬件 HSM
        KeyStore ks = KeyStore.getInstance("JKS");
        ks.load(new FileInputStream("server.keystore"), "changeit".toCharArray());

        KeyManagerFactory kmf = KeyManagerFactory.getInstance("SunX509");
        kmf.init(ks, "changeit".toCharArray());

        SSLContext ctx = SSLContext.getInstance("TLSv1.3");
        ctx.init(kmf.getKeyManagers(), null, new SecureRandom());

        return ctx.getServerSocketFactory();
    }

    public void start() throws Exception {
        SSLServerSocketFactory sf = createSslServerSocketFactory();
        try (SSLServerSocket ss = (SSLServerSocket) sf.createServerSocket(PORT)) {
            ss.setNeedClientAuth(false); // 若需要双向认证请改为 true
            System.out.println("客服服务器已启动，监听端口 " + PORT);
            while (true) {
                SSLSocket client = (SSLSocket) ss.accept();
                pool.execute(new ConnectionHandler(client));
            }
        }
    }

    // ====================== 连接处理器 ======================
    private class ConnectionHandler implements Runnable {
        private final SSLSocket socket;
        private BufferedReader in;
        private BufferedWriter out;
        private String peerId; // userId or agentId
        private boolean isAgent = false;

        ConnectionHandler(SSLSocket socket) {
            this.socket = socket;
        }

        @Override
        public void run() {
            try {
                socket.startHandshake(); // TLS 握手
                in  = new BufferedReader(new InputStreamReader(socket.getInputStream(), "UTF-8"));
                out = new BufferedWriter(new OutputStreamWriter(socket.getOutputStream(), "UTF-8"));

                // 首包必须是登录/身份声明
                String line = in.readLine();
                Message login = Message.fromJson(line);
                if (login.type != Message.Type.SYSTEM || !"login".equals(login.payload.text)) {
                    sendSystem("invalid_login");
                    close();
                    return;
                }
                this.peerId = login.from;
                this.isAgent = "agent".equals(login.payload.name); // payload.name = "agent" or "user"

                if (isAgent) {
                    agents.put(peerId, new AgentSession(peerId, out));
                    System.out.println("Agent connected: " + peerId);
                } else {
                    users.put(peerId, new UserSession(peerId, out));
                    System.out.println("User connected: " + peerId);
                    // 把用户加入等待队列，等待客服接入
                    pendingRequests.offer(new UserRequest(peerId, out));
                    // 触发 UI 提示 (这里用广播给所有已登录 Agent)
                    broadcastToAgents(new SystemMessage("new_user", peerId));
