                while ((line = in.readLine()) != null) {
                    Message msg = Message.fromJson(line);
                    handleMessage(msg);
                }
            } catch (Exception e) {
                System.err.println("Connection error [" + peerId + "]: " + e.getMessage());
            } finally {
                cleanup();
            }
