### 3.3 本地聊天记录管理 `ChatHistory`

```java
// ChatHistory.java
import java.io.*;
import java.nio.file.*;
import java.util.concurrent.locks.*;

public class ChatHistory {
    private static final String DIR = "chat_history";
    private static final ReentrantLock lock = new ReentrantLock();

    static {
        try { Files.createDirectories(Paths.get(DIR)); } catch (IOException ignored) {}
    }

    /** 追加单条消息到对应用户的历史文件 */
    public static void append(Message msg) {
        String fileName = DIR + File.separator + "history_" + sanitize(msg.from) + ".json";
        lock.lock();
        try (BufferedWriter bw = Files.newBufferedWriter(Paths.get(fileName), 
                StandardOpenOption.CREATE, StandardOpenOption.APPEND)) {
            bw.write(msg.toJson());
            bw.newLine();
        } catch (IOException e) {
            System.err.println("写入历史文件失败: " + e.getMessage());
        } finally {
            lock.unlock();
        }
    }

    /** 加载某用户全部历史（返回 JSON 行数组） */
    public static java.util.List<Message> load(String userId) {
        String fileName = DIR + File.separator + "history_" + sanitize(userId) + ".json";
        java.util.List<Message> list = new java.util.ArrayList<>();
        if (!Files.isRegularFile(Paths.get(fileName))) return list;
        lock.lock();
        try (BufferedReader br = Files.newBufferedReader(Paths.get(fileName))) {
            String line;
            while ((line = br.readLine()) != null) {
                try {
                    list.add(Message.fromJson(line));
                } catch (Exception ignored) {}
            }
        } catch (IOException e) {
            System.err.println("读取历史文件失败: " + e.getMessage());
        } finally {
            lock.unlock();
        }
        return list;
    }

    /** 防止路径遍历：只允许字母数字下划线 */
    private static String sanitize(String s) {
        return s.replaceAll("[^A-Za-z0-9_]", "_");
    }
}
```

