### 3.4 客户端 UI & I/O (`CustomerClient`)

> **Swing 必须在 Event‑Dispatch‑Thread (EDT) 中创建组件**，所有网络 I/O 必须放入单独线程，否则 UI 会卡死。

```java
// CustomerClient.java
import javax.net.ssl.*;
import javax.swing.*;
import java.awt.*;
import java.awt.event.*;
import java.io.*;
import java.security.KeyStore;
import java.util.List;

public class CustomerClient {
    private static final String SERVER_HOST = "localhost";
    private static final int SERVER_PORT = 8443;
    private SSLSocket socket;
    private BufferedReader in;
    private BufferedWriter out;

    private JFrame frame;
    private JTextArea chatArea;
    private JTextField inputField;
    private JButton sendBtn, imgBtn, fileBtn;
    private String myUserId = "user_" + System.currentTimeMillis(); // demo

    // =============== UI 初始化 ===============
    public void initUI() {
        frame = new JFrame("电商客服 - 用户端");
        frame.setSize(500, 600);
        frame.setDefaultCloseOperation(JFrame.EXIT_ON_CLOSE);
        frame.setLayout(new BorderLayout());

        chatArea = new JTextArea();
        chatArea.setEditable(false);
        JScrollPane sp = new JScrollPane(chatArea);
        frame.add(sp, BorderLayout.CENTER);

        JPanel bottom = new JPanel(new BorderLayout());
        inputField = new JTextField();
        bottom.add(inputField, BorderLayout.CENTER);

        JPanel btnPanel = new JPanel();
        sendBtn = new JButton("发送");
        imgBtn  = new JButton("图片");
        fileBtn = new JButton("文件");
        btnPanel.add(sendBtn);
        btnPanel.add(imgBtn);
        btnPanel.add(fileBtn);
        bottom.add(btnPanel, BorderLayout.EAST);
        frame.add(bottom, BorderLayout.SOUTH);

        // 绑定事件
        sendBtn.addActionListener(e -> sendText());
        imgBtn.addActionListener(e -> sendImage());
        fileBtn.addActionListener(e -> sendFile());

        frame.setVisible(true);
    }

    // =============== 网络连接 & 登录 ===============
    private void connectAndLogin() throws Exception {
        SSLSocketFactory sf = createSslSocketFactory();
        socket = (SSLSocket) sf.createSocket(SERVER_HOST, SERVER_PORT);
        socket.startHandshake();

        in  = new BufferedReader(new InputStreamReader(socket.getInputStream(), "UTF-8"));
        out = new BufferedWriter(new OutputStreamWriter(socket.getOutputStream(), "UTF-8"));

        // 登录报文
        Message login = new Message();
        login.type = Message.Type.SYSTEM;
        login.from = myUserId;
        login.to = "SERVER";
        login.timestamp = System.currentTimeMillis();
        login.payload = new Message.Payload();
        login.payload.text = "login";
        login.payload.name = "user"; // 供服务端识别身份
        sendRaw(login);
    }

    private SSLSocketFactory createSslSocketFactory() throws Exception {
        // 为简化演示，这里关闭证书校验（生产一定要校验！）
        SSLContext ctx = SSLContext.getInstance("TLS");
        ctx.init(null, new TrustManager[]{new X509TrustManager() {
            public java.security.cert.X509Certificate[] getAcceptedIssuers(){return null;}
            public void checkClientTrusted(java.security.cert.X509Certificate[] certs, String authType){}
            public void checkServerTrusted(java.security.cert.X509Certificate[] certs, String authType){}
        }}, new java.security.SecureRandom());
        return ctx.getSocketFactory();
    }

    // =============== 发送各种类型 ===============
    private void sendRaw(Message m) throws IOException {
        out.write(m.toJson());
        out.write("\n");
        out.flush();
    }

    private void sendText() {
        String txt = inputField.getText().trim();
        if (txt.isEmpty()) return;
        Message m = new Message();
        m.type = Message.Type.TEXT;
        m.from = myUserId;
        m.to   = "agent"; // 这里假设只对接一个客服 (后期可根据分配的客服 ID )
        m.timestamp = System.currentTimeMillis();
        m.payload = new Message.Payload();
        m.payload.text = txt;
        try { sendRaw(m); } catch (IOException e){ showError(e); }
        appendChat("我: " + txt);
        inputField.setText("");
    }

    private void sendImage() {
        JFileChooser fc = new JFileChooser();
        int rc = fc.showOpenDialog(frame);
        if (rc != JFileChooser.APPROVE_OPTION) return;
        File img = fc.getSelectedFile();
        if (img.length() > 5_000_000) { // 5 MB 限制
            JOptionPane.showMessageDialog(frame, "图片太大，请限制在 5 MB 以内");
            return;
        }
        try {
            byte[] data = Files.readAllBytes(img.toPath());
            Message m = new Message();
            m.type = Message.Type.IMAGE;
            m.from = myUserId;
            m.to   = "agent";
            m.timestamp = System.currentTimeMillis();
            m.payload = new Message.Payload();
            m.payload.name = img.getName();
            m.payload.size = data.length;
            m.payload.data = Base64.getEncoder().encodeToString(data);
            sendRaw(m);
            appendChat("[发送图片] " + img.getName());
        } catch (IOException e){ showError(e); }
    }

    private void sendFile() {
        JFileChooser fc = new JFileChooser();
        int rc = fc.showOpenDialog(frame);
        if (rc != JFileChooser.APPROVE_OPTION) return;
        File file = fc.getSelectedFile();
        if (file.length() > 10_000_000) { // 10 MB 限制
            JOptionPane.showMessageDialog(frame, "文件太大，请限制在 10 MB 以内");
            return;
        }
        try {
            byte[] data = Files.readAllBytes(file.toPath());
            Message m = new Message();
            m.type = Message.Type.FILE;
            m.from = myUserId;
            m.to   = "agent";
            m.timestamp = System.currentTimeMillis();
            m.payload = new Message.Payload();
            m.payload.name = file.getName();
            m.payload.size = data.length;
            m.payload.data = Base64.getEncoder().encodeToString(data);
            sendRaw(m);
            appendChat("[发送文件] " + file.getName());
        } catch (IOException e){ showError(e); }
    }

    // =============== 接收线程（后台） ===============
    private void startReceiver() {
        new Thread(() -> {
            try {
                String line;
                while ((line = in.readLine()) != null) {
                    Message msg = Message.fromJson(line);
                    handleIncoming(msg);
                }
            } catch (Exception e) {
                SwingUtilities.invokeLater(() -> JOptionPane.showMessageDialog(frame,
                        "网络异常: " + e.getMessage()));
            }
        }, "Receiver-Thread").start();
    }

    private void handleIncoming(Message msg) {
        SwingUtilities.invokeLater(() -> {
            switch (msg.type) {
                case TEXT:
                    appendChat("客服: " + msg.payload.text);
                    break;
                case IMAGE:
                    showImage(msg);
                    break;
                case FILE:
                    saveFile(msg);
                    break;
                case SYSTEM:
                    if ("busy".equals(msg.payload.text)) {
                        JOptionPane.showMessageDialog(frame, "客服忙碌，请稍后重试");
                    }
                    break;
                default: break;
            }
        });
    }

    private void showImage(Message msg) {
        try {
            byte[] data = Base64.getDecoder().decode(msg.payload.data);
            ImageIcon ic = new ImageIcon(data);
            chatArea.append("[图片] " + msg.payload.name + "\n");
            chatArea.insertIcon(ic);
            chatArea.append("\n");
        } catch (Exception e) { appendChat("[图片解析错误]"); }
    }

    private void saveFile(Message msg) {
        try {
            byte[] data = Base64.getDecoder().decode(msg.payload.data);
            JFileChooser fc = new JFileChooser();
            fc.setSelectedFile(new File(msg.payload.name));
            int rc = fc.showSaveDialog(frame);
            if (rc != JFileChooser.APPROVE_OPTION) return;
            Files.write(fc.getSelectedFile().toPath(), data);
            appendChat("[文件已保存] " + fc.getSelectedFile().getName());
        } catch (Exception e) { appendChat("[文件保存错误]"); }
    }

    private void appendChat(String s) {
        chatArea.append(s + "\n");
        chatArea.setCaretPosition(chatArea.getDocument().getLength());
    }

    private void showError(Exception e) {
        JOptionPane.showMessageDialog(frame, "错误: " + e.getMessage());
    }

    // =============== 启动入口 ===============
    public void start() {
        SwingUtilities.invokeLater(this::initUI);
        try {
            connectAndLogin();
            // 加载历史
            List<Message> hist = ChatHistory.load(myUserId);
            SwingUtilities.invokeLater(() -> {
                hist.forEach(m -> {
                    if (m.type == Message.Type.TEXT) {
                        appendChat((myUserId.equals(m.from) ? "我: " : "客服: ") + m.payload.text);
                    } // 简化：图片/文件略
                });
            });
            startReceiver();
        } catch (Exception e) {
            showError(e);
        }
    }

    public static void main(String[] args) {
        new CustomerClient().start();
    }
}
```

#### 客户端安全考虑

| 场景 | 防护措施 |
|------|----------|
| **TLS** | 在 `createSslSocketFactory()` 中使用 **证书校验**（演示中已关闭，仅供本地调试）。生产环境必须使用可信 CA 颁发的证书，并在客户端实现 `HostnameVerifier`。 |
| **文件上传** | *客户端* 在读取文件前检查 `File.length()`，并对 **文件扩展名** 进行白名单校验（仅允许运行所需的图片/文档）。 |
| **Base64 编码** | 防止 **二进制注入**，所有二进制内容仅在传输前转为 Base64。 |
| **UI 线程安全** | 所有 UI 更新使用 `SwingUtilities.invokeLater`，避免 **并发可见性** 问题。 |
| **异常与资源释放** | `finally` 中关闭 `socket`、`in`、`out`，防止 **资源泄漏**。 |

