                .ignoreHttpErrors(true)
                .get();

        List<NewsItem> result = new ArrayList<>();

        /*
         * 通过浏览器检查源码可知，每条新闻在 <ul class="news-list"> > <li> 中。
         *   <a href="/newsInfor/news/xxxx.html">标题</a>
         *   <span class="time">2024-05-20</span>
         */
        Elements liList = doc.select("ul.news-list > li");
        for (Element li : liList) {
            Element a = li.selectFirst("a");
            Element span = li.selectFirst("span.time");

            if (a == null) continue;   // 防御性检查

            NewsItem item = new NewsItem();
            item.title = a.text().trim();
            item.pubDate = (span != null) ? span.text().trim() : "";
            // 使用 Jsoup 的 absUrl 方法将相对路径转换为绝对路径
            item.detailUrl = a.absUrl("href");
            result.add(item);
        }

        return result;
    }

    /** ----------------------- 抓取详情 ----------------------- */
    /**
     * 根据新闻详情页的 URL 抓取正文、发布时间、图片地址（已转换为绝对 URL）。
     *
     * @param detailUrl 新闻详情页（完整 URL）
     * @return NewsDetail 对象
     */
    public static NewsDetail fetchNewsDetail(String detailUrl) throws IOException {
        Document doc = Jsoup.connect(detailUrl)
                .userAgent(USER_AGENT)
                .timeout(10_000)
                .ignoreHttpErrors(true)
                .get();

        NewsDetail detail = new NewsDetail();

        // 1️⃣ 标题
        // <h1 class="title">标题文字</h1>
        Element titleEl = doc.selectFirst("h1.title");
        if (titleEl != null) {
            detail.title = titleEl.text().trim();
        }

        // 2️⃣ 发布时间
        // <span class="time">2024-05-20</span>（或其它类名，根据实际源码定位）
        Element timeEl = doc.selectFirst("span.time");
        if (timeEl != null) {
            detail.pubDate = timeEl.text().trim();
        }

        // 3️⃣ 正文容器
        // <div class="article-content">…HTML…</div>
        Element contentEl = doc.selectFirst("div.article-content");
        if (contentEl == null) {
            // 有的页面可能用别的 class，如 .content、.newsDetail 等，做一次宽容的尝试
            contentEl = doc.selectFirst("div.news-detail, div.content, div.newsContent");
        }

        if (contentEl != null) {
            // 把正文中所有 <img> 的 src 转为绝对路径
            Elements imgs = contentEl.select("img");
            for (Element img : imgs) {
                // Jsoup 提供的 absUrl 能自动把相对地址转为完整 URL
                String absSrc = img.absUrl("src");
                if (absSrc != null && !absSrc.isEmpty()) {
                    img.attr("src", absSrc); // 替换为绝对地址
                    detail.imageUrls.add(absSrc);
                }
            }

            // 4️⃣ 取出处理后的 HTML
            detail.contentHtml = contentEl.html().trim();
        } else {
            detail.contentHtml = "";
        }

        return detail;
    }

    /** ----------------------- 防刷措施 ----------------------- */
    /**
     * 简单的随机睡眠（1~2 秒），防止对目标站点造成过高并发请求。
     */
    private static void sleepRandom() {
        int ms = 1000 + RAND.nextInt(1000); // 1000~2000 ms
        try {
            Thread.sleep(ms);
        } catch (InterruptedException ignored) {
        }
    }
}
```

