### 2.4 Security 配置

```java
package com.example.security;

import org.springframework.context.annotation.Bean;
import org.springframework.context.annotation.Configuration;
import org.springframework.security.config.Customizer;
import org.springframework.security.config.annotation.web.builders.HttpSecurity;
import org.springframework.security.config.annotation.web.configuration.EnableWebSecurity;
import org.springframework.security.web.SecurityFilterChain;
import org.springframework.security.web.session.HttpSessionEventPublisher;

@Configuration
@EnableWebSecurity
public class SecurityConfig {

    @Bean
    public SecurityFilterChain filterChain(HttpSecurity http) throws Exception {
        http
            // 1️⃣ 基本授权
            .authorizeHttpRequests(authz -> authz
                .antMatchers("/login", "/error", "/css/**", "/js/**").permitAll()
                .anyRequest().authenticated()
            )
            // 2️⃣ 表单登录
            .formLogin(form -> form
                .loginPage("/login")            // 自定义登录页面
                .defaultSuccessUrl("/")         // 登录成功后跳转
                .permitAll()
            )
            // 3️⃣ 登出处理
            .logout(logout -> logout
                .logoutUrl("/logout")
                .logoutSuccessUrl("/login?logout")
                .invalidateHttpSession(true)   // 清除 Session
                .deleteCookies("JSESSIONID")
            )
            // 4️⃣ Session 管理
            .sessionManagement(sess -> sess
                .invalidSessionUrl("/login?invalid")
                .maximumSessions(1)                 // 同一用户最多 1 个活跃 Session
                .maxSessionsPreventsLogin(false)    // 超出时踢掉旧的 Session
                .expiredUrl("/login?expired")
                .sessionFixation().newSession()     // 防止 Session Fixation
            )
            // 5️⃣ CSRF（页面渲染时保留，API 端点可关闭）
            .csrf(csrf -> csrf
                .ignoringAntMatchers("/api/**") // 对 API 端点关闭 CSRF
            );

        return http.build();
    }

    // 监听 Session 销毁事件（用于并发登录统计、审计等）
    @Bean
    public HttpSessionEventPublisher httpSessionEventPublisher() {
        return new HttpSessionEventPublisher();
    }
}
```

