### 3.5 JwtUtil（Token 生成 & 校验）

```java
package com.example.security.jwt;

import io.jsonwebtoken.*;
import io.jsonwebtoken.security.Keys;
import lombok.extern.slf4j.Slf4j;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.stereotype.Component;

import javax.annotation.PostConstruct;
import java.security.Key;
import java.time.*;
import java.util.*;

@Slf4j
@Component
public class JwtUtil {

    @Value("${jwt.secret}")
    private String base64Secret;

    @Value("${jwt.issuer}")
    private String issuer;

    @Value("${jwt.access-token-expiration}")
    private Duration accessTokenValidity;

    @Value("${jwt.refresh-token-expiration}")
    private Duration refreshTokenValidity;

    private Key key;

    @PostConstruct
    public void init() {
        byte[] secretBytes = Base64.getDecoder().decode(base64Secret);
        this.key = Keys.hmacShaKeyFor(secretBytes);
    }

    /** 生成 Access Token */
    public String generateAccessToken(String username, Collection<String> authorities) {
        Date now = new Date();
        Date exp = Date.from(Instant.now().plus(accessTokenValidity));

        Map<String, Object> claims = new HashMap<>();
        claims.put("roles", authorities);
        return Jwts.builder()
                .setSubject(username)
                .setIssuer(issuer)
                .setIssuedAt(now)
                .setExpiration(exp)
                .addClaims(claims)
                .signWith(key, SignatureAlgorithm.HS256)
                .compact();
    }

    /** 生成 Refresh Token（只携带 sub，放在 DB/Redis） */
    public String generateRefreshToken(String username) {
        Date now = new Date();
        Date exp = Date.from(Instant.now().plus(refreshTokenValidity));
        return Jwts.builder()
                .setSubject(username)
                .setIssuer(issuer)
                .setIssuedAt(now)
                .setExpiration(exp)
                .signWith(key, SignatureAlgorithm.HS256)
                .compact();
    }

    /** 校验并解析 Token */
    public Jws<Claims> parseClaims(String token) {
        try {
            return Jwts.parserBuilder()
                    .setSigningKey(key)
                    .requireIssuer(issuer)
                    .build()
                    .parseClaimsJws(token);
        } catch (JwtException e) {
            log.warn("Invalid JWT: {}", e.getMessage());
            throw e; // 交给 filter 捕获返回 401
        }
    }

    /** 判断是否过期 */
    public boolean isExpired(Claims claims) {
        return claims.getExpiration().before(new Date());
    }
}
```

### 3.6 登录接口（颁发 Token）

```java
package com.example.controller;

import com.example.security.jwt.JwtUtil;
import lombok.RequiredArgsConstructor;
import org.springframework.http.*;
import org.springframework.security.authentication.*;
import org.springframework.security.core.*;
import org.springframework.security.core.authority.SimpleGrantedAuthority;
import org.springframework.web.bind.annotation.*;

import java.util.*;
import java.util.stream.Collectors;

@RestController
@RequestMapping("/api/auth")
@RequiredArgsConstructor
public class AuthController {

    private final AuthenticationManager authenticationManager;
    private final JwtUtil jwtUtil;

    /** 登录：返回 access_token + refresh_token */
    @PostMapping("/login")
    public ResponseEntity<Map<String, String>> login(@RequestBody LoginRequest request) {
        UsernamePasswordAuthenticationToken authToken =
                new UsernamePasswordAuthenticationToken(request.getUsername(), request.getPassword());

        Authentication auth = authenticationManager.authenticate(authToken);

        // Spring Security 已经把用户信息放进 Authentication
        String username = auth.getName();
        List<String> roles = auth.getAuthorities()
                .stream().map(GrantedAuthority::getAuthority).collect(Collectors.toList());

        String accessToken = jwtUtil.generateAccessToken(username, roles);
        String refreshToken = jwtUtil.generateRefreshToken(username);

        // 可选：把 refresh token 持久化（Redis / DB）以便后续刷新或撤销
        // ...

        Map<String, String> body = new HashMap<>();
        body.put("access_token", accessToken);
        body.put("refresh_token", refreshToken);
        body.put("token_type", "Bearer");
        body.put("expires_in", String.valueOf(jwtUtil.getAccessTokenValidity().toSeconds()));
        return ResponseEntity.ok(body);
    }

    /** 刷新 Access Token（使用 Refresh Token） */
    @PostMapping("/refresh")
    public ResponseEntity<Map<String, String>> refresh(@RequestBody RefreshRequest request) {
        String refreshToken = request.getRefreshToken();
        // 校验 Refresh Token
        Jws<Claims> claims = jwtUtil.parseClaims(refreshToken);
        if (jwtUtil.isExpired(claims.getBody())) {
            return ResponseEntity.status(HttpStatus.UNAUTHORIZED).build();
        }
        String username = claims.getBody().getSubject();

        // 这里可以再次查询 DB 获取最新权限（防止权限变更后 token 仍旧老权限）
        // 简化示例：直接使用硬编码角色
        List<String> roles = List.of("ROLE_USER");

        String newAccessToken = jwtUtil.generateAccessToken(username, roles);
        Map<String, String> body = new HashMap<>();
        body.put("access_token", newAccessToken);
        body.put("token_type", "Bearer");
        body.put("expires_in", String.valueOf(jwtUtil.getAccessTokenValidity().toSeconds()));
        return ResponseEntity.ok(body);
    }

    // DTO
    static record LoginRequest(String username, String password) {}
    static record RefreshRequest(String refreshToken) {}
}
