### 3.7 Spring Security 配置（Stateless）

```java
package com.example.security;

import com.example.security.jwt.JwtAuthenticationFilter;
import lombok.RequiredArgsConstructor;
import org.springframework.context.annotation.*;
import org.springframework.security.authentication.*;
import org.springframework.security.config.annotation.authentication.configuration.*;
import org.springframework.security.config.annotation.web.builders.HttpSecurity;
import org.springframework.security.config.http.*;
import org.springframework.security.core.userdetails.*;
import org.springframework.security.web.*;
import org.springframework.security.web.authentication.UsernamePasswordAuthenticationFilter;

@Configuration
@EnableWebSecurity
@RequiredArgsConstructor
public class SecurityConfig {

    private final JwtAuthenticationFilter jwtAuthenticationFilter;
    private final UserDetailsService userDetailsService;

    // ① 认证管理器（用于登录）—— 这里使用 DaoAuthenticationProvider
    @Bean
    public AuthenticationManager authenticationManager(AuthenticationConfiguration config) throws Exception {
        return config.getAuthenticationManager();
    }

    // ② 密码编码器
    @Bean
    public PasswordEncoder passwordEncoder() {
        return new BCryptPasswordEncoder();
    }

    // ③ 授权规则
    @Bean
    public SecurityFilterChain filterChain(HttpSecurity http) throws Exception {
        http
            // ① 禁用 Session（Stateless）
            .sessionManagement(sess -> sess.sessionCreationPolicy(SessionCreationPolicy.STATELESS))
            // ② 统一异常返回 JSON
            .exceptionHandling(ex -> ex
                .authenticationEntryPoint((req, rsp, e) -> {
                    rsp.setContentType(MediaType.APPLICATION_JSON_VALUE);
                    rsp.setStatus(HttpServletResponse.SC_UNAUTHORIZED);
                    rsp.getWriter().write("{\"error\":\"Unauthorized\",\"message\":\"" + e.getMessage() + "\"}");
                })
            )
            // ③ 授权路由
            .authorizeHttpRequests(authz -> authz
                .antMatchers("/api/auth/**").permitAll()
                .anyRequest().authenticated()
            )
            // ④ 添加 JWT 过滤器（在 UsernamePasswordAuthenticationFilter 前）
            .addFilterBefore(jwtAuthenticationFilter, UsernamePasswordAuthenticationFilter.class)
            // ⑤ 关闭默认登录表单、CSRF（API 场景）
            .httpBasic(Customizer.withDefaults())
            .csrf(csrf -> csrf.disable());

        return http.build();
    }

    // ④ 配置 DaoAuthenticationProvider（登录时使用）
    @Bean
    public DaoAuthenticationProvider daoAuthenticationProvider() {
        DaoAuthenticationProvider provider = new DaoAuthenticationProvider();
        provider.setUserDetailsService(userDetailsService);
        provider.setPasswordEncoder(passwordEncoder());
        return provider;
    }
}
