### 3.8 JwtAuthenticationFilter（核心）

```java
package com.example.security.jwt;

import io.jsonwebtoken.Claims;
import io.jsonwebtoken.Jws;
import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import org.springframework.security.authentication.*;
import org.springframework.security.core.*;
import org.springframework.security.core.authority.*;
import org.springframework.security.core.context.*;
import org.springframework.stereotype.Component;
import org.springframework.util.StringUtils;
import org.springframework.web.filter.OncePerRequestFilter;

import jakarta.servlet.*;
import jakarta.servlet.http.*;
import java.io.IOException;
import java.util.*;

@Slf4j
@Component
@RequiredArgsConstructor
public class JwtAuthenticationFilter extends OncePerRequestFilter {

    private final JwtUtil jwtUtil;
    private final UserDetailsService userDetailsService; // 用于加载最新权限（可选）

    @Override
    protected void doFilterInternal(HttpServletRequest request,
                                    HttpServletResponse response,
                                    FilterChain filterChain) throws ServletException, IOException {

        String header = request.getHeader("Authorization");
        if (StringUtils.hasText(header) && header.startsWith("Bearer ")) {
            String token = header.substring(7);
            try {
                Jws<Claims> claimsJws = jwtUtil.parseClaims(token);
                Claims claims = claimsJws.getBody();

                if (jwtUtil.isExpired(claims)) {
                    log.warn("Token expired for user {}", claims.getSubject());
                    // 这里不抛异常，直接让后面的异常处理器返回 401
                } else {
                    String username = claims.getSubject();
                    @SuppressWarnings("unchecked")
                    List<String> roleStrings = (List<String>) claims.get("roles", List.class);
                    List<GrantedAuthority> authorities = roleStrings.stream()
                            .map(SimpleGrantedAuthority::new)
                            .toList();

                    // 可选：每次请求重新加载用户详情（防止角色变更后 token 仍旧旧角色）
                    // UserDetails userDetails = userDetailsService.loadUserByUsername(username);
                    // authorities = userDetails.getAuthorities();

                    UsernamePasswordAuthenticationToken authToken =
                            new UsernamePasswordAuthenticationToken(username, null, authorities);
                    SecurityContextHolder.getContext().setAuthentication(authToken);
                }
            } catch (JwtException e) {
                log.warn("JWT validation failed: {}", e.getMessage());
                // 让后面的 ExceptionTranslationFilter 触发 401
            }
        }

        filterChain.doFilter(request, response);
    }
}
```

