```java
public interface AntivirusScanner {
    boolean isClean(Path file) throws IOException;
}

public class ClamAVScanner implements AntivirusScanner {

    private static final int CHUNK_SIZE = 8192;
    private final String clamHost = "localhost";
    private final int clamPort = 3310;

    @Override
    public boolean isClean(Path file) throws IOException {
        try (Socket socket = new Socket(clamHost, clamPort);
             OutputStream out = socket.getOutputStream();
             InputStream in = socket.getInputStream();
             InputStream fileIn = Files.newInputStream(file)) {

            // 1️⃣ handshake
            out.write("zINSTREAM\0".getBytes(StandardCharsets.US_ASCII));

            // 2️⃣ Передаём файл кусками, каждый кусок начинается с длины (big‑endian)
            byte[] buffer = new byte[CHUNK_SIZE];
            int read;
            while ((read = fileIn.read(buffer)) != -1) {
                out.write(ByteBuffer.allocate(4).order(ByteOrder.BIG_ENDIAN).putInt(read).array());
                out.write(buffer, 0, read);
            }
            // 3️⃣ Окончание потока: 0‑байт длина
            out.write(new byte[]{0,0,0,0});
            out.flush();

            // 4️⃣ Читаем ответ
            BufferedReader reader = new BufferedReader(new InputStreamReader(in, StandardCharsets.US_ASCII));
            String response = reader.readLine(); // например: stream: OK
            return response != null && response.contains("OK");
        }
    }
}
```

> **Важно:** если антивирус не нужен в прототипе, просто сделайте `return true;`.

