## 4️⃣ Service Layer – `AdminService.java`

```java
package com.example.admin.service;

import com.example.admin.dao.AdminMapper;
import com.example.admin.model.Admin;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.security.crypto.bcrypt.BCrypt;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

import java.time.LocalDateTime;
import java.time.temporal.ChronoUnit;

@Service
public class AdminService {

    // ---------- Configuration constants ----------
    private static final int MAX_FAILED_ATTEMPTS = 5;
    private static final int LOCK_TIME_MINUTES = 30;

    @Autowired
    private AdminMapper adminMapper;

    /**
     * Perform the full authentication flow.
     *
     * @param username supplied login name
     * @param rawPassword supplied password (plain text from UI)
     * @return the Admin object without the password hash if login succeeds;
     *         null otherwise.
     */
    @Transactional
    public Admin login(String username, String rawPassword) {
        Admin admin = adminMapper.findByUsername(username);
        if (admin == null) {
            // No such user – we intentionally do NOT reveal that fact.
            return null;
        }

        // ---------- 1) Check lockout ----------
        if (admin.getLockedUntil() != null && admin.getLockedUntil().isAfter(LocalDateTime.now())) {
            // Account is still locked
            return null;
        }

        // ---------- 2) Verify password ----------
        boolean passwordMatches = BCrypt.checkpw(rawPassword, admin.getPasswordHash());

        if (passwordMatches) {
            // ---------- Successful login ----------
            resetFailedLoginInfo(admin);
            // It is a good practice to NOT expose the hash upwards.
            admin.setPasswordHash(null);
            return admin;
        } else {
            // ---------- Failed login ----------
            handleFailedLogin(admin);
            return null;
        }
    }

    /** Reset counters after a successful login */
    private void resetFailedLoginInfo(Admin admin) {
        admin.setLoginFailedCount(0);
        admin.setLastFailedAt(null);
        admin.setLockedUntil(null);
        adminMapper.updateLoginStatus(admin);
    }

    /** Increment counters and possibly lock the account */
    private void handleFailedLogin(Admin admin) {
        int failed = admin.getLoginFailedCount() == null ? 0 : admin.getLoginFailedCount();
        failed++;
        admin.setLoginFailedCount(failed);
        admin.setLastFailedAt(LocalDateTime.now());

        if (failed >= MAX_FAILED_ATTEMPTS) {
            // Lock the account for a fixed period
            LocalDateTime unlockAt = LocalDateTime.now().plus(LOCK_TIME_MINUTES, ChronoUnit.MINUTES);
            admin.setLockedUntil(unlockAt);
        }
        adminMapper.updateLoginStatus(admin);
    }

    /**
     * Utility method for creating a new admin (e.g., during bootstrap).
     * It hashes the password with BCrypt (default strength 10).
     */
    public void createAdmin(String username, String plainPassword) {
        Admin admin = new Admin();
        admin.setUsername(username);
        // BCrypt automatically generates a random salt
        admin.setPasswordHash(BCrypt.hashpw(plainPassword, BCrypt.gensalt()));
        // Insert using a MyBatis INSERT (not shown – would be another mapper method)
        // adminMapper.insert(admin);
    }
}
