## 5️⃣ Spring MVC Controller – `AdminController.java`

```java
package com.example.admin.web;

import com.example.admin.model.Admin;
import com.example.admin.service.AdminService;
import lombok.Data;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.stereotype.Controller;
import org.springframework.ui.Model;
import org.springframework.validation.BindingResult;
import org.springframework.web.bind.annotation.*;

import javax.validation.Valid;

/**
 * Handles the admin login UI.
 * The view technology can be JSP, Thymeleaf, or any templating engine.
 */
@Controller
@RequestMapping("/admin")
public class AdminController {

    @Autowired
    private AdminService adminService;

    /**
     * Show login page.
     */
    @GetMapping("/login")
    public String showLoginForm(Model model) {
        model.addAttribute("loginForm", new LoginForm());
        return "admin/login";   // resolves to /WEB-INF/views/admin/login.jsp (or .html)
    }

    /**
     * Process login submission.
     */
    @PostMapping("/login")
    public String processLogin(
            @ModelAttribute("loginForm") @Valid LoginForm loginForm,
            BindingResult bindingResult,
            Model model) {

        if (bindingResult.hasErrors()) {
            return "admin/login";
        }

        Admin admin = adminService.login(loginForm.getUsername(), loginForm.getPassword());

        if (admin == null) {
            // Uniform error message – do not disclose whether the user exists.
            model.addAttribute("loginError", "用户名或密码错误");
            return "admin/login";
        }

        // Successful login – store a minimal principal in session.
        // In production you should use Spring Security, not raw HttpSession.
        // Here we just set a flag for demo purposes.
        loginForm.getSession().setAttribute("ADMIN_PRINCIPAL", admin.getUsername());

        // Redirect to admin dashboard (Post/Redirect/Get pattern)
        return "redirect:/admin/dashboard";
    }

    @GetMapping("/dashboard")
    public String dashboard(@SessionAttribute(value = "ADMIN_PRINCIPAL", required = false) String adminUser,
                            Model model) {
        if (adminUser == null) {
            // Not logged in – send back to login page.
            return "redirect:/admin/login";
        }
        model.addAttribute("adminUser", adminUser);
        return "admin/dashboard";
    }

    // -----------------------------------------------------------------
    // Helper class for binding login form fields.
    // -----------------------------------------------------------------
    @Data
    public static class LoginForm {
        @NotBlank(message = "用户名不能为空")
        private String username;

        @NotBlank(message = "密码不能为空")
        private String password;

        // Spring will inject the native HttpSession automatically.
        // (Add the following setter to have it populated)
        private javax.servlet.http.HttpSession session;

        public void setSession(javax.servlet.http.HttpSession session) {
            this.session = session;
        }
    }
}
```

> **Explanation of the controller flow**
> 1. `GET /admin/login` renders a login page (e.g., `login.jsp`).  
> 2. `POST /admin/login` receives the form, validates non‑empty fields, forwards to `AdminService.login`.  
> 3. On success we put a lightweight principal (`ADMIN_PRINCIPAL`) into the HTTP session.  
> 4. The dashboard page checks that the session attribute exists; otherwise it redirects back to the login page.

