            .cors(Customizer.withDefaults())
            // Session management – stateless for JWT API, stateful for UI
            .sessionManagement(sess -> sess
                .sessionCreationPolicy(SessionCreationPolicy.STATELESS)
            );

        // ---- 3.2 Authorization rules (first match wins) ----
        http.authorizeHttpRequests(auth -> auth
            // Public health‑check/end‑point
            .requestMatchers("/actuator/**", "/public/**").permitAll()
            // Login page (if any) – formLogin will add its own filter
            .requestMatchers("/login", "/oauth2/**").permitAll()
            // API protected by Roles/Authorities
            .requestMatchers(HttpMethod.POST, "/api/admin/**").hasRole("ADMIN")
            .requestMatchers(HttpMethod.GET, "/api/**").hasAnyRole("USER", "ADMIN")
            // Anything else → deny (fail‑closed)
            .anyRequest().denyAll()
        );

        // ---- 3.3 Authentication mechanisms ----
        http
            // Form login – classic UI flow (adds UsernamePasswordAuthenticationFilter)
            .formLogin(form -> form
                .loginPage("/login")
                .defaultSuccessUrl("/home")
                .failureUrl("/login?error")
                .permitAll()
            )
            // HTTP Basic – useful for quick testing (disable in prod)
            .httpBasic(Customizer.withDefaults());

        // ---- 3.4 Adding a custom JWT filter (example) ----
        http.addFilterBefore(
                jwtAuthenticationFilter(authenticationManager(http.getSharedObject(AuthenticationConfiguration.class))),
                UsernamePasswordAuthenticationFilter.class   // place before the default auth filter
        );

        // --------------------------------------------------------------
        // 4️⃣  Return the built filter chain
        // --------------------------------------------------------------
        return http.build();
    }

    // -----------------------------------------------------------------
    // 5️⃣  JWT filter – a quick illustration (real impl should handle errors)
    // -----------------------------------------------------------------
    private OncePerRequestFilter jwtAuthenticationFilter(AuthenticationManager authMgr) {
        return new OncePerRequestFilter() {
            private final String BEARER = "Bearer ";

            @Override
            protected void doFilterInternal(HttpServletRequest req,
                                            HttpServletResponse resp,
                                            FilterChain chain)
                    throws ServletException, IOException {

                String authHeader = req.getHeader(HttpHeaders.AUTHORIZATION);
                if (authHeader != null && authHeader.startsWith(BEARER)) {
                    String token = authHeader.substring(BEARER.length());
