### 4.1 服务器端（Agent Center）

```java
// 主入口：启动 TLS Server + 线程池
public class AgentCenter {
    private static final int PORT = 8443;
    private static final int MAX_THREADS = Runtime.getRuntime().availableProcessors() * 2;
    private final ExecutorService pool = Executors.newFixedThreadPool(MAX_THREADS);
    private final SessionManager sessionMgr = new SessionManager();

    public void start() throws Exception {
        SSLServerSocket serverSocket = SslUtil.createSslServerSocket(PORT);
        System.out.println("Agent Center listening on " + PORT);
        while (!Thread.currentThread().isInterrupted()) {
            SSLSocket socket = (SSLSocket) serverSocket.accept();
            // 双向认证后生成 token
            String token = UUID.randomUUID().toString();
            pool.submit(new SessionHandler(socket, token, sessionMgr));
        }
    }

    public static void main(String[] args) throws Exception {
        new AgentCenter().start();
    }
}
```

```java
// 每个用户会话的处理器
class SessionHandler implements Runnable {
    private final SSLSocket socket;
    private final String token;
    private final SessionManager mgr;
    private final ObjectMapper json = new ObjectMapper(); // Jackson

    SessionHandler(SSLSocket s, String token, SessionManager mgr) {
        this.socket = s;
        this.token = token;
        this.mgr = mgr;
    }

    @Override
    public void run() {
        try (socket;
             BufferedReader in = new BufferedReader(new InputStreamReader(socket.getInputStream(), StandardCharsets.UTF_8));
             BufferedWriter out = new BufferedWriter(new OutputStreamWriter(socket.getOutputStream(), StandardCharsets.UTF_8))) {

            // 1. 将会话注册到 SessionManager，状态默认为 BUSY（等待坐席处理）
            mgr.register(token, this, out);

            // 2. 主循环：读取 JSON 行（每行一个完整 JSON）
            String line;
            while ((line = in.readLine()) != null) {
                JsonNode msg = json.readTree(line);
                handleMessage(msg);
            }
        } catch (Exception e) {
            // 捕获所有异常，记录并安全关闭
            Log.error("Session error token=" + token, e);
        } finally {
            mgr.deregister(token);
        }
    }

    private void handleMessage(JsonNode msg) throws IOException {
        String type = msg.get("type").asText();
        // === 控制流 ===
        switch (type) {
            case "control":
                // 业务指令：accept/reject/close 等
                ControlMessage ctrl = json.treeToValue(msg.get("payload"), ControlMessage.class);
                if ("close".equals(ctrl.cmd)) {
                    send(buildInfo("session closed"));
                    // 关闭会话
                    mgr.closeSession(token);
                }
                break;
            case "text":
                // 转发给已接入的坐席（如果已经绑定）
                mgr.forwardToAgent(token, msg);
                break;
            case "image":
            case "file":
                // 采用分块方式写入磁盘后再转发
                FileChunkHandler.handle(msg, token, mgr);
                break;
            default:
                send(buildError("unsupported type"));
        }
    }

    // 便捷的发送方法（自动换行）
    void send(JsonNode node) throws IOException {
        BufferedWriter out = mgr.getWriter(token);
        out.write(node.toString());
        out.newLine();
        out.flush();
    }

    private JsonNode buildError(String msg) {
        ObjectNode n = json.createObjectNode();
        n.put("type", "error");
        n.put("msg", msg);
        return n;
    }

    private JsonNode buildInfo(String msg) {
        ObjectNode n = json.createObjectNode();
        n.put("type", "control");
        n.put("msg", msg);
        return n;
    }
}
```

```java
// 会话管理器（坐席分配、状态、转发）
class SessionManager {
    // token -> SessionHandler
    private final ConcurrentMap<String, SessionHandler> sessions = new ConcurrentHashMap<>();
    // token -> AgentWorker（坐席）
    private final ConcurrentMap<String, AgentWorker> agentMap = new ConcurrentHashMap<>();

    // 坐席池（执勤坐席的列表）
    private final CopyOnWriteArrayList<AgentWorker> onlineAgents = new CopyOnWriteArrayList<>();

    void register(String token, SessionHandler handler, BufferedWriter writer) {
        sessions.put(token, handler);
        // 默认状态 BUSY，等待坐席选择
        // UI 可通过 listener 通知 “新用户请求”
    }

    void deregister(String token) {
        sessions.remove(token);
        agentMap.remove(token);
    }

    BufferedWriter getWriter(String token) {
        return sessions.get(token).getWriter(); // 会返回对应的 out
    }

    /** 坐席调用该方法接受会话 */
    void assignAgent(String token, AgentWorker agent) {
        agentMap.put(token, agent);
        // 把已经缓存的聊天记录发送给坐席（可选）
    }

    /** 向已绑定的坐席转发用户发送的消息 */
    void forwardToAgent(String token, JsonNode msg) throws IOException {
        AgentWorker aw = agentMap.get(token);
        if (aw != null) {
            aw.send(msg);
        } else {
            // 未分配坐席，返回 busy 提示
            sessions.get(token).send(buildBusy());
        }
    }

    void closeSession(String token) {
        SessionHandler h = sessions.remove(token);
        if (h != null) {
            try {
                h.send(buildInfo("session closed"));
            } catch (IOException ignored) {}
        }
        agentMap.remove(token);
        // 同时通知坐席
        AgentWorker aw = agentMap.get(token);
        if (aw != null) aw.notifyClose(token);
    }

    // 简单的 busy 报文
    private JsonNode buildBusy() {
        ObjectMapper om = new ObjectMapper();
        ObjectNode n = om.createObjectNode();
        n.put("type", "control");
        n.put("msg", "客服忙碌，请稍后…");
        return n;
    }
}
```

```java
// 坐席（客服）工作线程，负责 UI 与后端的桥接
class AgentWorker implements Runnable {
    private final SSLSocket socket;
    private final BufferedWriter out;
    private final BufferedReader in;
    private final ObjectMapper json = new ObjectMapper();
    private final SessionManager mgr;
    private final String agentId;   // 坐席唯一标识

    AgentWorker(SSLSocket s, SessionManager mgr, String agentId) throws IOException {
        this.socket = s;
        this.mgr = mgr;
        this.agentId = agentId;
        this.out = new BufferedWriter(new OutputStreamWriter(s.getOutputStream(), StandardCharsets.UTF_8));
        this.in = new BufferedReader(new InputStreamReader(s.getInputStream(), StandardCharsets.UTF_8));
    }

    @Override
    public void run() {
        try {
            // 坐席登录成功后，监听来自服务器的转发消息
            String line;
            while ((line = in.readLine()) != null) {
                JsonNode msg = json.readTree(line);
                // UI 线程通过 SwingUtilities.invokeLater 把消息加入聊天面板
                SwingUtilities.invokeLater(() -> UiAgentPanel.receiveMessage(msg));
            }
        } catch (Exception e) {
            Log.error("AgentWorker error, id=" + agentId, e);
        } finally {
            // 坐席下线，回收资源
            mgr.onlineAgents.remove(this);
            try { socket.close(); } catch (IOException ignored) {}
        }
    }

    // 坐席向用户发送消息（文本/文件/图片）
    void send(JsonNode msg) throws IOException {
        out.write(msg.toString());
        out.newLine();
        out.flush();
    }

    // 让坐席接受某个用户的会话
    void acceptSession(String token) throws IOException {
        ObjectNode req = json.createObjectNode();
        req.put("type", "control");
        ObjectNode payload = req.putObject("payload");
        payload.put("cmd", "accept");
        payload.put("token", token);
        send(req);
        mgr.assignAgent(token, this);
    }

    void rejectSession(String token) throws IOException {
        ObjectNode req = json.createObjectNode();
        req.put("type", "control");
        ObjectNode payload = req.putObject("payload");
        payload.put("cmd", "reject");
        payload.put("token", token);
        send(req);
        // 不分配坐席，用户会收到 busy 提示
    }

    void notifyClose(String token) throws IOException {
        // 坐席 UI 可弹窗“用户已结束会话”
    }
}
```

> **线程/资源要点**  
> - `SessionHandler`（每个用户）使用 **阻塞 I/O**，但在 **线程池** 中运行，避免创建过多线程。  
> - `AgentWorker` 只负责坐席自己的网络 I/O，坐席 **UI** 与业务逻辑通过 **事件队列** (`SwingUtilities.invokeLater`) 交互，防止 UI 卡死。  
> - 所有 **共享集合**(`sessions`, `onlineAgents`) 使用 **并发安全容器** (`ConcurrentHashMap`, `CopyOnWriteArrayList`)。  

