```java
public class UiUserPanel extends JPanel {
    private final JTextPane chatPane = new JTextPane();
    private final JTextField inputField = new JTextField();
    private final JButton sendBtn = new JButton("发送");
    private final JButton imgBtn = new JButton("图片");
    private final JButton fileBtn = new JButton("文件");
    private final UserClient client;

    public UiUserPanel(UserClient client) {
        this.client = client;
        setLayout(new BorderLayout());

        JScrollPane scroll = new JScrollPane(chatPane);
        chatPane.setEditable(false);
        add(scroll, BorderLayout.CENTER);

        JPanel bottom = new JPanel(new BorderLayout());
        bottom.add(inputField, BorderLayout.CENTER);
        bottom.add(sendBtn, BorderLayout.EAST);
        add(bottom, BorderLayout.SOUTH);

        JPanel left = new JPanel(new GridLayout(1, 2));
        left.add(imgBtn);
        left.add(fileBtn);
        add(left, BorderLayout.NORTH);

        // 事件绑定
        sendBtn.addActionListener(e -> sendText());
        imgBtn.addActionListener(e -> chooseAndSendImage());
        fileBtn.addActionListener(e -> chooseAndSendFile());
    }

    private void sendText() {
        String txt = inputField.getText().trim();
        if (txt.isEmpty()) return;
        try {
            client.sendText(txt);
            appendMessage("我", txt, true);
            inputField.setText("");
        } catch (Exception ex) {
            showError("发送失败：" + ex.getMessage());
        }
    }

    private void chooseAndSendImage() {
        JFileChooser fc = new JFileChooser();
        fc.setFileFilter(new FileNameExtensionFilter("图片文件", "png","jpg","jpeg","gif"));
        if (fc.showOpenDialog(this) == JFileChooser.APPROVE_OPTION) {
            Path p = fc.getSelectedFile().toPath();
            try {
                client.sendFile(p); // 复用同一接口，服务器解析为 image
                appendImage(p);
