package com.example;

import com.sun.net.httpserver.HttpServer;
import java.io.IOException;
import java.net.InetSocketAddress;

/**
 * Simple HTTP server that listens on port 8080 and registers the /upload endpoint.
 */
public class Main {

    private static final int PORT = 8080;

    public static void main(String[] args) throws IOException {
        // Bind the server to localhost only; change to 0.0.0.0 if you need external access.
        InetSocketAddress address = new InetSocketAddress("localhost", PORT);
        HttpServer server = HttpServer.create(address, 0);

        // Register handler for image uploads
        server.createContext("/upload", new ImageUploadHandler());

        // A single thread pool is enough for a PoC, but you may want a proper executor.
        server.setExecutor(java.util.concurrent.Executors.newFixedThreadPool(4));

        System.out.println("🚀 Server started on http://localhost:" + PORT + "/upload");
        server.start();
    }
}
