## 9. Контроллер аутентификации  

```java
@RestController
@RequestMapping("/api/auth")
@RequiredArgsConstructor
public class AuthController {

    private final AuthenticationManager authManager;
    private final JwtUtils jwtUtils;
    private final UserRepository userRepo;
    private final RefreshTokenRepository refreshTokenRepo;
    private final PasswordEncoder passwordEncoder;

    // ---------- LOGIN ----------
    @PostMapping("/login")
    public ResponseEntity<?> login(@RequestBody LoginRequest req,
                                   HttpServletResponse response) {

        // 1) Проверяем credentials
        Authentication authentication = authManager.authenticate(
                new UsernamePasswordAuthenticationToken(req.getUsername(), req.getPassword()));

        SecurityContextHolder.getContext().setAuthentication(authentication);
        UserDetails userDetails = (UserDetails) authentication.getPrincipal();

        // 2) Генерируем JWT
        String accessToken = jwtUtils.generateAccessToken(userDetails);

        // 3) Создаём refresh token и сохраняем в БД
        User user = userRepo.findByUsername(req.getUsername()).orElseThrow();
        RefreshToken refreshToken = createRefreshToken(user);
        refreshTokenRepo.save(refreshToken);

        // 4) Прокидываем refresh‑token в HttpOnly cookie
        Cookie refreshCookie = new Cookie("refreshToken", refreshToken.getToken());
        refreshCookie.setHttpOnly(true);
        refreshCookie.setSecure(true); // только по HTTPS
        refreshCookie.setPath("/api/auth/refresh");
        refreshCookie.setMaxAge((int) Duration.ofDays(7).getSeconds());
        refreshCookie.setSameSite("Strict");   // Java 11+ (или вручную Set‑Header)

        response.addCookie(refreshCookie);

        // 5) Возвращаем access‑token в теле (можно в header)
        return ResponseEntity.ok(new JwtResponse(accessToken));
    }

    // ---------- REFRESH ----------
    @PostMapping("/refresh")
    public ResponseEntity<?> refreshToken(@CookieValue(name = "refreshToken", required = false) String token,
                                          HttpServletResponse response) {

        if (token == null) {
            return ResponseEntity.status(HttpStatus.UNAUTHORIZED).body("Refresh token missing");
        }

        RefreshToken stored = refreshTokenRepo.findByToken(token)
                .orElseThrow(() -> new RuntimeException("Invalid refresh token"));

        if (stored.getExpiryDate().isBefore(Instant.now())) {
            refreshTokenRepo.delete(stored);
            return ResponseEntity.status(HttpStatus.UNAUTHORIZED).body("Refresh token expired");
        }

        // Генерируем новый access‑token
        UserDetails ud = userDetailsService.loadUserByUsername(stored.getUser().getUsername());
        String newAccess = jwtUtils.generateAccessToken(ud);

        // (по желанию) продлеваем refresh‑token или генерируем новый:
        // refreshTokenRepo.delete(stored);
        // RefreshToken newRefresh = createRefreshToken(stored.getUser());
        // refreshTokenRepo.save(newRefresh);
        // set cookie again ...

        return ResponseEntity.ok(new JwtResponse(newAccess));
    }

    // ---------- LOGOUT ----------
    @PostMapping("/logout")
    public ResponseEntity<?> logout(@CookieValue(name = "refreshToken", required = false) String token,
                                    HttpServletResponse response) {
        if (token != null) {
            refreshTokenRepo.findByToken(token).ifPresent(refreshTokenRepo::delete);
        }

        // Очистить cookie
        Cookie empty = new Cookie("refreshToken", null);
        empty.setPath("/api/auth/refresh");
        empty.setMaxAge(0);
        empty.setHttpOnly(true);
        empty.setSecure(true);
        empty.setSameSite("Strict");
        response.addCookie(empty);

        return ResponseEntity.ok("Logged out");
    }

    // ---------- Регистрация (опционально) ----------
    @PostMapping("/register")
    public ResponseEntity<?> register(@RequestBody RegisterRequest req) {
        if (userRepo.findByUsername(req.getUsername()).isPresent()) {
            return ResponseEntity.badRequest().body("Username already exists");
        }
        User user = new User();
        user.setUsername(req.getUsername());
        user.setPassword(passwordEncoder.encode(req.getPassword()));
        user.setRoles(Set.of("ROLE_USER"));
        userRepo.save(user);
        return ResponseEntity.ok("User created");
    }

    // ---------- Вспомогательные методы ----------
    private RefreshToken createRefreshToken(User user) {
        RefreshToken token = new RefreshToken();
        token.setToken(UUID.randomUUID().toString());
        token.setUser(user);
        token.setExpiryDate(Instant.now().plus(Duration.ofDays(7)));
        return token;
    }
}

/* DTO‑классы */
