            connectionPool.submit(() -> handleClient(client));
        }
    }

    // -----------------------------------------------------------------
    // SSL configuration (self‑signed test cert is enough for a lab)
    // -----------------------------------------------------------------
    private SSLServerSocket createSslServerSocket() throws Exception {
        KeyStore ks = KeyStore.getInstance("PKCS12");
        try (FileInputStream fis = new FileInputStream(KEYSTORE_PATH)) {
            ks.load(fis, KEYSTORE_PASS.toCharArray());
        }

        KeyManagerFactory kmf = KeyManagerFactory.getInstance("SunX509");
        kmf.init(ks, KEYSTORE_PASS.toCharArray());

        SSLContext ctx = SSLContext.getInstance("TLSv1.3");
        ctx.init(kmf.getKeyManagers(), null, null);

        SSLServerSocketFactory ssf = ctx.getServerSocketFactory();
        SSLServerSocket ss = (SSLServerSocket) ssf.createServerSocket(PORT);
        ss.setNeedClientAuth(false); // enable if you use client certs
        return ss;
    }

    // -----------------------------------------------------------------
    // Client handling – two‑way Object streams
    // -----------------------------------------------------------------
    private void handleClient(SSLSocket socket) {
        try (ObjectOutputStream out = new ObjectOutputStream(socket.getOutputStream());
             ObjectInputStream  in  = new ObjectInputStream(socket.getInputStream())) {

            // 1️⃣ Send initial workload batch (or keep idling until tasks appear)
            while (true) {
                // Pull a Task from the queue; block if empty.
                Task task = taskQueue.take();
                System.out.println("[Server] Sending task #" + task.getTaskId() + " to Android");
                out.writeObject(task);
                out.flush();

                // 2️⃣ Wait for the result back from Android
                PartialResult result = (PartialResult) in.readObject();
                System.out.println("[Server] Received result for task #" + result.getTaskId());

                // Resolve the awaiting CompletableFuture (if any)
                CompletableFuture<PartialResult> cf = pendingResults.remove(result.getTaskId());
                if (cf != null) cf.complete(result);
                else System.out.println("[Server] No local waiter for task " + result.getTaskId());
            }
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt(); // shutdown case
        } catch (EOFException | SocketException e) {
            System.out.println("[Server] Android client disconnected.");
        } catch (Exception e) {
            e.printStackTrace();
        }
    }

    // -----------------------------------------------------------------
    // Public API – add a new Task and optionally block for the result
    // -----------------------------------------------------------------
    public CompletableFuture<PartialResult> submitTask(Task task) {
        // Register a placeholder for the result.
        CompletableFuture<PartialResult> cf = new CompletableFuture<>();
        pendingResults.put(task.getTaskId(), cf);
        taskQueue.offer(task);
        return cf;
    }

    // -----------------------------------------------------------------
    // Example usage – push 100 tasks and aggregate the sums locally
    // -----------------------------------------------------------------
    public void demo() throws Exception {
        // Submit a batch of tasks
        for (int i = 0; i < 100; i++) {
            int[] payload = new int[10_000];
            for (int j = 0; j < payload.length; j++) payload[j] = i * j;
            Task t = new Task(i, payload);
            CompletableFuture<PartialResult> cf = submitTask(t);
            cf.thenAccept(r -> System.out.println("[Server] Final sum for task " + r.getTaskId() + " = " + r.getSum()));
        }
    }
}
```

**What the code does**

| Section | Purpose |
|---|---|
| **SSL Server socket** | Guarantees encrypted transport (TLS 1.3). In a real deployment replace the self‑signed keystore with a proper CA‑signed cert. |
| **taskQueue** | Holds tasks that are waiting to be handed out to the Android worker. |
| **pendingResults** | Allows the caller (your application logic) to block/wait for a specific result using `CompletableFuture`. |
| **handleClient** | Each Android device opens a persistent connection; the server serialises a `Task` → `ObjectOutputStream`, then blocks on `ObjectInputStream.readObject()` for the `PartialResult`. |
| **submitTask** | External code can fire‑and‑forget or `join()` on the returned `Future`. |
| **localWorkerPool** | Not used in the snippet above (only remote work), but you can also submit some tasks locally for “true” clustering (PC & Android share the load). |

> **Tip:** If you intend to have **multiple Android workers** simultaneously, you can keep a `ConcurrentLinkedQueue<SSLSocket>` of idle sockets and pop whichever is free.

### 3.2. Security Hardening (PC side)

1. **TLS Mutual Authentication** – set `ss.setNeedClientAuth(true)` and supply a `TrustManager` that validates a client cert.
2. **Input validation** – never trust the `payload` array size; enforce a maximum (e.g. `payload.length <= MAX_ELEMENTS`).
3. **Sandboxed execution** – run the actual computation inside a `java.security.AccessControlContext` that denies filesystem/network I/O.
4. **Resource limits** – use `ThreadPoolExecutor` with `setMaximumPoolSize`, `setQueueCapacity`, and optionally a per‑task timeout (`Future.get(30, TimeUnit.SECONDS)`).
5. **DoS protection** – track the rate of `Task` objects submitted by each socket; if a client floods the server, drop the connection.

---

## 4. Step‑4 – Parallel Execution on Each Node

The “worker” part of the system is essentially the same on PC and Android:

* Pull a `Task` from an inbound queue (provided by the network manager).  
* Run `processTask(task)` inside a thread from a pool.  
* Serialize the `PartialResult` back over the socket.

Below are two concrete implementations: one for **Java SE (PC)** and one for **Android**.

---

### 4.1. Worker implementation (shared code)

```java
// src/common/TaskProcessor.java
package common;

public interface TaskProcessor {
    /**
     * Compute a result for the supplied task.
     *
     * @param task the work unit
     * @return partial result (must be serialisable)
     */
    PartialResult process(Task task);
}
```

A **simple sum‑over‑array** implementation (you can replace this with any heavy algorithm):

```java
// src/common/SumProcessor.java
package common;

public class SumProcessor implements TaskProcessor {
    @Override
    public PartialResult process(Task task) {
        long sum = 0;
        for (int v : task.getPayload()) sum += v;
        return new PartialResult(task.getTaskId(), sum);
    }
}
```

---

### 4.2. PC Side Worker (local pool)

```java
// src/pc/LocalWorker.java
package pc;

import common.*;

import java.util.concurrent.*;

public class LocalWorker {

    private final ExecutorService pool;
    private final TaskProcessor processor;

    public LocalWorker(int parallelism) {
        // ForkJoinPool is a good default for CPU‑bound work
        this.pool = new ForkJoinPool(parallelism);
        this.processor = new SumProcessor();
    }

    /**
     * Submit a task that originates from the server's own queue
     * (e.g. you want the PC to also crunch some of the jobs).
     */
    public CompletableFuture<PartialResult> compute(Task task) {
        return CompletableFuture.supplyAsync(() -> processor.process(task), pool);
    }

    public void shutdown() {
        pool.shutdownNow();
    }
}
```

You can now **mix** the two sources of work:

```java
// inside TaskManagerServer.demo()
LocalWorker local = new LocalWorker(Runtime.getRuntime().availableProcessors());

for (int i = 0; i < 100; i++) {
    // same payload generation as before …
    Task t = new Task(i, payload);

    // Randomly decide who runs it (50 % PC, 50 % Android)
    if (Math.random() < 0.5) {
        CompletableFuture<PartialResult> cf = local.compute(t);
        cf.thenAccept(r -> System.out.println("[PC] Got local result: " + r.getSum()));
    } else {
        CompletableFuture<PartialResult> cf = submitTask(t); // remote
        cf.thenAccept(r -> System.out.println("[PC] Got remote result: " + r.getSum()));
    }
}
```

