### 2.1 SocketReceiver（TCP 示例）

```java
package com.example.h264;

import java.io.*;
import java.net.*;
import java.util.concurrent.*;

public class SocketReceiver implements Runnable {
    private final ServerSocket serverSocket;
    private final BlockingQueue<byte[]> nalQueue;   // 保存完整 NALU（不含 start code）

    // max NALU 长度保护（避免恶意超大帧）
    private static final int MAX_NALU_SIZE = 2 * 1024 * 1024; // 2 MiB

    public SocketReceiver(int port, BlockingQueue<byte[]> nalQueue) throws IOException {
        this.serverSocket = new ServerSocket(port);
        this.nalQueue = nalQueue;
    }

    @Override
    public void run() {
        try (Socket client = serverSocket.accept();
             InputStream in = new BufferedInputStream(client.getInputStream())) {

            // 按 Annex‑B（0x000001 / 0x00000001）切割
            byte[] buffer = new byte[4 * 1024];
            ByteArrayOutputStream nalu = new ByteArrayOutputStream();

            int read;
            while ((read = in.read(buffer)) != -1) {
                for (int i = 0; i < read; i++) {
                    nalu.write(buffer[i]);
                    // 检测 start code
                    if (endsWithStartCode(nalu)) {
                        // 去掉上一个 start code 前的 NALU（如果有）
                        byte[] payload = extractPayload(nalu);
                        if (payload != null && payload.length > 0 && payload.length <= MAX_NALU_SIZE) {
                            // 将完整 NALU 放入队列（阻塞，防止 OOM）
                            nalQueue.put(payload);
                        }
                        // 重置，保留当前 start code 作为下一个 NALU 的开头
                        nalu.reset();
                        nalu.write(0x00);
                        nalu.write(0x00);
                        nalu.write(0x00);
                        nalu.write(0x01);
                    }
                }
            }
        } catch (Exception e) {
            System.err.println("[SocketReceiver] error: " + e.getMessage());
        }
    }

    /** 判定 ByteArrayOutputStream 结尾是否为 Annex‑B start code */
    private boolean endsWithStartCode(ByteArrayOutputStream baos) {
        byte[] b = baos.toByteArray();
        int len = b.length;
        if (len < 3) return false;
        // 0x000001  或 0x00000001
        if (b[len - 3] == 0 && b[len - 2] == 0 && b[len - 1] == 1) return true;
        if (len >= 4 && b[len - 4] == 0 && b[len - 3] == 0 && b[len - 2] == 0 && b[len - 1] == 1) return true;
        return false;
    }

    /** 去掉前面的 start code，返回纯 NALU 内容 */
    private byte[] extractPayload(ByteArrayOutputStream baos) {
        byte[] full = baos.toByteArray();
        int offset = 0;
        // 跳过 0x000001 或 0x00000001
        if (full[0] == 0 && full[1] == 0 && full[2] == 0 && full[3] == 1) offset = 4;
        else if (full[0] == 0 && full[1] == 0 && full[2] == 1) offset = 3;
        else return null; // 非法帧
        int size = full.length - offset;
        byte[] payload = new byte[size];
        System.arraycopy(full, offset, payload, 0, size);
        return payload;
    }
}
```

> **安全点**  
> - **MAX_NALU_SIZE** 防止恶意客户端发送超大 NALU 造成 OOM。  
> - `BlockingQueue.put()` 会在队列满时阻塞，避免无限增长。建议在创建队列时使用 **有界实现**（`ArrayBlockingQueue`）。  
> - 使用 **`BufferedInputStream`** 防止 `read()` 产生大量系统调用。  
> - 只接受 **单一 client**（示例），生产环境应采用 **多客户端、鉴权** 或 **TLS**。

### 2.2 H264Decoder（基于 JavaCV / FFmpeg）

```java
package com.example.h264;

import org.bytedeco.javacv.*;
import org.bytedeco.ffmpeg.global.avutil;
import java.awt.image.*;
import java.util.concurrent.*;

public class H264Decoder implements Runnable {
    private final BlockingQueue<byte[]> nalQueue;
    private final BlockingQueue<BufferedImage> frameQueue; // 交给 UI 渲染

    // FFmpeg 解码器
    private final FFmpegFrameGrabber grabber;

    public H264Decoder(BlockingQueue<byte[]> nalQueue,
                       BlockingQueue<BufferedImage> frameQueue) {
        this.nalQueue = nalQueue;
        this.frameQueue = frameQueue;
        this.grabber = new FFmpegFrameGrabber("dummy"); // 使用内存输入
        // 仅解码 H.264
        this.grabber.setFormat("h264");
        this.grabber.setOption("flags", "low_delay");
        // 设定安全属性
        avutil.av_log_set_level(avutil.AV_LOG_ERROR); // 降低噪声日志
    }

    @Override
    public void run() {
        try {
            grabber.start();
            while (true) {
                // 取出一个完整 NALU（已去掉 start code）
                byte[] nalu = nalQueue.take(); // 阻塞
                // 将 NALU 包装成帧
                Frame raw = new Frame();
                raw.image = null;
                raw.samples = null;
                raw.data = nalu; // 对 FFmpegFrameGrabber 来说，data = Annex‑B 已经去掉 start code 也可以
                raw.imageDepth = avutil.AV_PIX_FMT_YUV420P; // 仅作占位

                // 直接喂入解码器
                grabber.grab(); // flush 旧帧（防止卡顿）
                grabber = new FFmpegFrameGrabber(new ByteArrayInputStream(nalu));
                grabber.setFormat("h264");
                grabber.start();

                Frame decoded = grabber.grabImage();
                if (decoded != null) {
                    // 转为 BufferedImage（JavaFX/Swing 可直接绘制）
                    Java2DFrameConverter converter = new Java2DFrameConverter();
                    BufferedImage img = converter.convert(decoded);
                    // 放入渲染队列（阻塞，防止太快累积）
                    frameQueue.put(img);
                }

                grabber.stop(); // 释放当前帧资源
            }
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
        } catch (Exception e) {
            System.err.println("[H264Decoder] error: " + e.getMessage());
        }
    }
}
```

> **说明**  
> - **JavaCV** 用 `FFmpegFrameGrabber` 直接读取 **ByteArrayInputStream**。  
> - 为了减小 **解码延迟**，每个 NALU 为单位创建临时 `grabber`，在生产环境可以使用 **AVCodecContext**（JNI）做更高效的 `avcodec_send_packet` / `avcodec_receive_frame`。  
> - `av_log_set_level` 降低 FFmpeg 默认日志，防止信息泄露。  
> - `frameQueue` 同样采用 **有界**（`ArrayBlockingQueue<BufferedImage>(30)`）防止 UI 线程慢导致堆积。  

> **安全点**  
> - 每次 `grabber.start()` 前对 `ByteArrayInputStream` 长度做检查（已在 `SocketReceiver` 限制）。  
> - 捕获所有 `Exception`，防止恶意 codec 潜在 **CVE**（例如 Heap‑Overflow）导致 Java 进程崩溃。  
> - 使用 **最新的 FFmpeg**（`javacv-platform` 自动提供），及时修补已知漏洞。  

