import java.util.*;
import java.util.concurrent.*;

public class TTTServer {

    // ----- Game State --------------------------------------------------------
    private static final int BOARD_SIZE = 3;
    private final char[][] board = new char[BOARD_SIZE][BOARD_SIZE];
    private final List<Player> players = new ArrayList<>(2);
    private volatile Player currentTurn; // who should move now

    // ----- TLS Setup ---------------------------------------------------------
    private static SSLServerSocketFactory createServerSocketFactory(String ksPath, String ksPass)
            throws KeyStoreException, IOException, NoSuchAlgorithmException,
                   CertificateException, UnrecoverableKeyException, KeyManagementException {
        KeyStore ks = KeyStore.getInstance("JKS");
        ks.load(new FileInputStream(ksPath), ksPass.toCharArray());

        KeyManagerFactory kmf = KeyManagerFactory.getInstance("SunX509");
        kmf.init(ks, ksPass.toCharArray());

        SSLContext ctx = SSLContext.getInstance("TLSv1.3");
        ctx.init(kmf.getKeyManagers(), null, null);
        return ctx.getServerSocketFactory();
    }

    // ----- Inner Player abstraction -------------------------------------------
    private class Player {
        final Socket socket;
        final BufferedReader in;
        final BufferedWriter out;
        final char symbol; // 'X' or 'O'

        Player(Socket s, char sym) throws IOException {
            this.socket = s;
            this.symbol = sym;
            this.in = new BufferedReader(new InputStreamReader(s.getInputStream()));
            this.out = new BufferedWriter(new OutputStreamWriter(s.getOutputStream()));
        }

        void send(String msg) throws IOException {
            out.write(msg);
            out.write('\n');
            out.flush();
        }

        void close() {
            try { socket.close(); } catch (IOException ignored) {}
        }
