                System.out.println("[SERVER] From " + p.symbol + ": " + line);
                if (line.startsWith("JOIN")) {
                    // Handled already – just acknowledge
                    p.send("WELCOME " + p.symbol);
                } else if (line.startsWith("PLAY")) {
                    if (p != currentTurn) {
                        p.send("ERROR Not your turn");
                        continue;
                    }
                    String[] parts = line.split("\\s+");
                    if (parts.length != 3) {
                        p.send("ERROR Bad PLAY format");
                        continue;
                    }
                    int r = Integer.parseInt(parts[1]);
                    int c = Integer.parseInt(parts[2]);
                    if (!applyMove(r, c, p.symbol)) {
                        p.send("ERROR Illegal move");
                        continue;
                    }
                    broadcast("MOVE " + r + " " + c + " " + p.symbol);
                    if (isWin(p.symbol)) {
                        p.send("END WIN");
                        getOpponent(p).send("END LOSS");
                        break;
                    } else if (isDraw()) {
                        broadcast("END DRAW");
                        break;
                    } else {
                        // Switch turn
                        currentTurn = getOpponent(p);
                        currentTurn.send("TURN");
                    }
                } else {
                    p.send("ERROR Unknown command");
                }
            }
        } catch (SocketTimeoutException e) {
            safeSend(p, "ERROR Timeout");
        } catch (Exception e) {
            safeSend(p, "ERROR " + e.getMessage());
        } finally {
            System.out.println("[SERVER] Player " + p.symbol + " disconnected.");
            // Cleanup: if a player leaves early, end the game for the other
            Player opponent = getOpponent(p);
            if (opponent != null) {
                safeSend(opponent, "END LOSS");
            }
        }
    }

    private Player getOpponent(Player p) {
        for (Player q : players) if (q != p) return q;
        return null;
    }

    private void safeSend(Player p, String msg) {
        try { p.send(msg); } catch (IOException ignored) {}
    }

    // ----- Main entry point ---------------------------------------------------
    public static void main(String[] args) throws Exception {
        if (args.length != 3) {
            System.err.println("Usage: java -jar server.jar <port> <keystore> <keystorePass>");
            System.exit(1);
        }
        int port = Integer.parseInt(args[0]);
        new TTTServer().start(port, args[1], args[2]);
    }
}
```

### 4.2. `TTTClient.java`

```java
package client;

import javafx.application.Application;
import javafx.application.Platform;
import javafx.geometry.Pos;
import javafx.scene.Scene;
import javafx.scene.control.*;
import javafx.scene.layout.*;
import javafx.stage.Stage;

import javax.net.ssl.*;
import java.io.*;
import java.security.*;
import java.security.cert.CertificateException;

public class TTTClient extends Application {

    // ---- UI components -------------------------------------------------------
    private final Button[][] cells = new Button[3][3];
    private Label statusLabel = new Label("Connecting…");
    private char mySymbol; // X or O
    private boolean myTurn = false;

    // ---- Network objects -----------------------------------------------------
    private BufferedReader in;
    private BufferedWriter out;

    // ---- TLS factory ---------------------------------------------------------
    private static SSLSocketFactory createSocketFactory(String truststore, String pass)
            throws KeyStoreException, IOException, NoSuchAlgorithmException,
                   CertificateException, KeyManagementException {
        KeyStore ts = KeyStore.getInstance("JKS");
        ts.load(new FileInputStream(truststore), pass.toCharArray());

        TrustManagerFactory tmf = TrustManagerFactory.getInstance("SunX509");
        tmf.init(ts);

        SSLContext ctx = SSLContext.getInstance("TLSv1.3");
        ctx.init(null, tmf.getTrustManagers(), null);
        return ctx.getSocketFactory();
    }

    // ---- Entry point ---------------------------------------------------------
    public static void main(String[] args) {
        launch(args);
    }

    // ---- JavaFX UI -----------------------------------------------------------
    @Override
    public void start(Stage primaryStage) {
        if (getParameters().getRaw().size() < 4) {
            showErrorAndExit("Usage: java -jar client.jar <host> <port> <truststore> <pass>");
            return;
        }
        String host = getParameters().getRaw().get(0);
        int port = Integer.parseInt(getParameters().getRaw().get(1));
        String truststore = getParameters().getRaw().get(2);
        String pass = getParameters().getRaw().get(3);

        GridPane grid = new GridPane();
        grid.setAlignment(Pos.CENTER);
        grid.setHgap(5);
        grid.setVgap(5);
        for (int r = 0; r < 3; r++) {
            for (int c = 0; c < 3; c++) {
                Button b = new Button(" ");
                b.setPrefSize(80, 80);
                final int rr = r, cc = c;
                b.setOnAction(e -> sendPlay(rr, cc));
                cells[r][c] = b;
                grid.add(b, c, r);
            }
        }

        VBox root = new VBox(10, statusLabel, grid);
        root.setAlignment(Pos.CENTER);
        primaryStage.setScene(new Scene(root, 300, 350));
        primaryStage.setTitle("Tic‑Tac‑Toe (JavaFX)");
        primaryStage.show();

        // --- Start networking on a background thread -------------------------
        new Thread(() -> {
            try {
                SSLSocketFactory sf = createSocketFactory(truststore, pass);
                SSLSocket socket = (SSLSocket) sf.createSocket(host, port);
                socket.startHandshake(); // forces TLS validation

                in = new BufferedReader(new InputStreamReader(socket.getInputStream()));
                out = new BufferedWriter(new OutputStreamWriter(socket.getOutputStream()));

                // 1️⃣ JOIN the game
                sendLine("JOIN");
                listenLoop(); // blocks until game ends or socket closed
            } catch (Exception ex) {
                Platform.runLater(() -> statusLabel.setText("ERROR: " + ex.getMessage()));
            }
        }, "network-thread").start();
    }

    private void sendPlay(int r, int c) {
        if (!myTurn) {
            statusLabel.setText("Not your turn.");
            return;
        }
        sendLine("PLAY " + r + " " + c);
    }

    private void sendLine(String txt) {
        try {
            out.write(txt);
            out.write('\n');
            out.flush();
        } catch (IOException ignored) { }
    }

    // ---- Network listener ----------------------------------------------------
    private void listenLoop() throws IOException {
        String line;
        while ((line = in.readLine()) != null) {
            final String msg = line;
            Platform.runLater(() -> handleMessage(msg));
        }
    }

    private void handleMessage(String msg) {
        System.out.println("[CLIENT] << " + msg);
        if (msg.startsWith("WELCOME")) {
            mySymbol = msg.charAt(8);
            statusLabel.setText("You are " + mySymbol);
        } else if (msg.equals("START")) {
            clearBoard();
            statusLabel.setText("Game started – waiting for turn…");
        } else if (msg.equals("TURN")) {
            myTurn = true;
            statusLabel.setText("Your turn (" + mySymbol + ")");
        } else if (msg.startsWith("MOVE")) {
            // MOVE <row> <col> <symbol>
            String[] p = msg.split("\\s+");
            int r = Integer.parseInt(p[1]);
            int c = Integer.parseInt(p[2]);
            char sym = p[3].charAt(0);
            cells[r][c].setText(String.valueOf(sym));
        } else if (msg.startsWith("END")) {
            String[] p = msg.split("\\s+");
            String result = p[1];
            myTurn = false;
            switch (result) {
                case "WIN":  statusLabel.setText("You WIN!"); break;
                case "LOSS": statusLabel.setText("You LOSE."); break;
                case "DRAW": statusLabel.setText("Draw."); break;
                default:     statusLabel.setText("Game ended."); break;
            }
        } else if (msg.startsWith("ERROR")) {
            statusLabel.setText("Error: " + msg.substring(6));
        }
    }

    // ---- UI helpers ----------------------------------------------------------
    private void clearBoard() {
        for (Button[] row : cells) for (Button b : row) b.setText(" ");
    }

    private void showErrorAndExit(String msg) {
        Alert a = new Alert(Alert.AlertType.ERROR, msg, ButtonType.CLOSE);
        a.showAndWait();
        Platform.exit();
    }
}
```

> **Why this is the *simplest* possible network game**  
> * One Java file per side (≈ 250 LOC each).  
> * No external serialization library – we only use plain strings.  
> * JavaFX UI is only 9 buttons and a status label.  
> * TLS is set up with a single `createServerSocketFactory` / `createSocketFactory` helper.  

