### 2.1 发送端 `VideoCaptureClient.java`

```java
import org.bytedeco.javacv.*;
import org.bytedeco.opencv.opencv_core.*;
import javax.net.ssl.*;
import java.io.*;
import java.security.*;
import java.security.cert.CertificateException;

public class VideoCaptureClient {

    // ------------------- TLS 参数 -------------------
    private static final String KEYSTORE_PATH = "client_keystore.p12";
    private static final String KEYSTORE_PASS = "changeit";
    private static final String TRUSTSTORE_PATH = "client_truststore.p12";
    private static final String TRUSTSTORE_PASS = "changeit";

    // 目标服务器（IP+端口）
    private static final String SERVER_HOST = "192.168.1.100";
    private static final int SERVER_PORT = 8443;

    // 视频来源：0 = 默认摄像头，或者文件路径
    private static final String VIDEO_SOURCE = "0"; // or "video.mp4"

    // JPEG 质量 (0-100)
    private static final int JPEG_QUALITY = 75;

    public static void main(String[] args) throws Exception {
        // 1️⃣ 初始化 TLS Socket
        SSLSocketFactory socketFactory = createSslSocketFactory();
        try (SSLSocket socket = (SSLSocket) socketFactory.createSocket(SERVER_HOST, SERVER_PORT);
             OutputStream out = socket.getOutputStream()) {

            // 2️⃣ 初始化视频抓取器
            FFmpegFrameGrabber grabber = new FFmpegFrameGrabber(
                    VIDEO_SOURCE.matches("\\d+") ? Integer.parseInt(VIDEO_SOURCE) : VIDEO_SOURCE);
            grabber.start();

            // 用于 Frame → BufferedImage 转换
            Java2DFrameConverter converter = new Java2DFrameConverter();

            // 3️⃣ 主循环：抓帧 → JPEG → 发送
            long frameIntervalMs = 33; // ~30 FPS
            while (true) {
                long t0 = System.currentTimeMillis();

                Frame frame = grabber.grabImage(); // 只抓取视频帧（不含音频）
                if (frame == null) break; // EOF

                // Convert to BufferedImage
                BufferedImage img = converter.convert(frame);

                // Encode JPEG
                ByteArrayOutputStream bos = new ByteArrayOutputStream();
                javax.imageio.ImageIO.write(img, "jpg", bos);
                byte[] jpegBytes = bos.toByteArray();

                // ---------- 自定义协议 ----------
                //   4字节 length (big‑endian) + 1字节 payload-type (0x01=JPEG) + payload
                DataOutputStream dos = new DataOutputStream(out);
                dos.writeInt(jpegBytes.length + 1);
                dos.writeByte(0x01); // payload type = JPEG
                dos.write(jpegBytes);
                dos.flush();

                // 控制帧率
                long elapsed = System.currentTimeMillis() - t0;
                long sleep = frameIntervalMs - elapsed;
                if (sleep > 0) Thread.sleep(sleep);
            }

            grabber.stop();
        }
    }

    // ---------- TLS 创建 ----------
    private static SSLSocketFactory createSslSocketFactory()
            throws KeyStoreException, IOException, NoSuchAlgorithmException,
            CertificateException, UnrecoverableKeyException, KeyManagementException {

        // Load client key store (用于双向 TLS 认证，若只单向可省略)
        KeyStore ks = KeyStore.getInstance("PKCS12");
        try (FileInputStream fis = new FileInputStream(KEYSTORE_PATH)) {
            ks.load(fis, KEYSTORE_PASS.toCharArray());
        }

        // Load trust store (服务器证书)
        KeyStore ts = KeyStore.getInstance("PKCS12");
        try (FileInputStream fis = new FileInputStream(TRUSTSTORE_PATH)) {
            ts.load(fis, TRUSTSTORE_PASS.toCharArray());
        }

        // KeyManager (client certificates)
        KeyManagerFactory kmf = KeyManagerFactory.getInstance(KeyManagerFactory.getDefaultAlgorithm());
        kmf.init(ks, KEYSTORE_PASS.toCharArray());

        // TrustManager (server certificates)
        TrustManagerFactory tmf = TrustManagerFactory.getInstance(TrustManagerFactory.getDefaultAlgorithm());
        tmf.init(ts);

        SSLContext ctx = SSLContext.getInstance("TLSv1.3");
        ctx.init(kmf.getKeyManagers(), tmf.getTrustManagers(), new SecureRandom());

        return ctx.getSocketFactory();
    }
}
