    private static final String KEYSTORE_PATH = "server_keystore.p12";
    private static final String KEYSTORE_PASS = "changeit";
    private static final String TRUSTSTORE_PATH = "server_truststore.p12";
    private static final String TRUSTSTORE_PASS = "changeit";

