        SSLServerSocketFactory factory = createSslServerSocketFactory();
        try (SSLServerSocket serverSocket = (SSLServerSocket) factory.createServerSocket(LISTEN_PORT)) {
            System.out.println("[*] Server listening on port " + LISTEN_PORT);
            serverSocket.setNeedClientAuth(true); // 双向TLS

