        frame.setDefaultCloseOperation(JFrame.EXIT_ON_CLOSE);
        frame.setSize(800, 600);
        label.setHorizontalAlignment(SwingConstants.CENTER);
        frame.add(label);
        frame.setVisible(true);
    }

    // ---------- TLS ----------
    private static SSLServerSocketFactory createSslServerSocketFactory()
            throws KeyStoreException, IOException, NoSuchAlgorithmException,
            CertificateException, UnrecoverableKeyException, KeyManagementException {

        KeyStore ks = KeyStore.getInstance("PKCS12");
        try (FileInputStream fis = new FileInputStream(KEYSTORE_PATH)) {
            ks.load(fis, KEYSTORE_PASS.toCharArray());
        }

        KeyStore ts = KeyStore.getInstance("PKCS12");
        try (FileInputStream fis = new FileInputStream(TRUSTSTORE_PATH)) {
            ts.load(fis, TRUSTSTORE_PASS.toCharArray());
        }

        KeyManagerFactory kmf = KeyManagerFactory.getInstance(KeyManagerFactory.getDefaultAlgorithm());
        kmf.init(ks, KEYSTORE_PASS.toCharArray());

        TrustManagerFactory tmf = TrustManagerFactory.getInstance(TrustManagerFactory.getDefaultAlgorithm());
        tmf.init(ts);

        SSLContext ctx = SSLContext.getInstance("TLSv1.3");
        ctx.init(kmf.getKeyManagers(), tmf.getTrustManagers(), new SecureRandom());

        return ctx.getServerSocketFactory();
    }
}
```

#### 关键点说明

| 步骤 | 代码片段 | 为什么要这么写 |
|------|----------|----------------|
| **TLS 双向认证** | `socketFactory.createSocket(...);` & `serverSocket.setNeedClientAuth(true);` | 防止 **MITM** 与 **未授权接入**，且客户端证书可做 **设备指纹** |
| **自定义帧协议** | `int length + byte type + payload` | 简单 **边界划分**，便于在 TCP 流中拆包；在安全审计时可直接检查 payload 类型 |
| **JPEG 压缩** | `ImageIO.write(img, "jpg", bos);` | 大幅降低带宽，占用 **<100 KB/frame**（依据质量） |
| **帧率控制** | `Thread.sleep(frameIntervalMs - elapsed);` | 防止 **CPU/网络饱和**，降低 **DoS** 风险 |
| **异常捕获** | `catch (EOFException ...)` | 正确关闭资源、避免 **资源泄露** |
| **GUI 渲染** | `SwingUtilities.invokeLater` | 防止 **线程安全** 问题（UI 线程 vs. I/O 线程） |

