    private String data;           // Base64 编码的二进制（可空）

    // ---------- getters / setters ----------
    public Type getType() { return type; }
    public void setType(Type type) { this.type = type; }
    public String getFrom() { return from; }
    public void setFrom(String from) { this.from = from; }
    public String getContent() { return content; }
    public void setContent(String content) { this.content = content; }
    public String getFilename() { return filename; }
    public void setFilename(String filename) { this.filename = filename; }
    public String getData() { return data; }
    public void setData(String data) { this.data = data; }

    // ---------- JSON 处理 ----------
    private static final ObjectMapper MAPPER = new ObjectMapper();

    public static Message fromJson(String json) throws Exception {
        return MAPPER.readValue(json, Message.class);
    }

    public String toJson() throws Exception {
        return MAPPER.writeValueAsString(this);
    }
}
```

> 依赖：`com.fasterxml.jackson.core:jackson-databind:2.15.2`（或更高）  
> `pom.xml` 中加入相应依赖即可。

### 5.2. 聊天记录持久化 `ChatRecordManager.java`

```java
package com.ecom.chat.utils;

import com.ecom.chat.common.Message;
import java.io.*;
import java.nio.file.*;
import java.time.LocalDateTime;
import java.util.*;
import java.util.concurrent.locks.*;

public class ChatRecordManager {
    private static final Path BASE_DIR = Paths.get("chat_records");
    private static final int MAX_RECORD_SIZE = 10 * 1024 * 1024; // 10 MB

    private final ReadWriteLock rwLock = new ReentrantReadWriteLock();

    public ChatRecordManager() throws IOException {
        if (!Files.exists(BASE_DIR)) {
            Files.createDirectories(BASE_DIR);
        }
    }

    /**
     * 读取指定用户的聊天记录（如果不存在返回空列表）
     */
    public List<Message> load(String userId) throws IOException {
        Path file = getUserFile(userId);
        rwLock.readLock().lock();
        try {
            if (!Files.exists(file)) {
                return new ArrayList<>();
            }
            try (BufferedReader br = Files.newBufferedReader(file)) {
                List<Message> msgs = new ArrayList<>();
                String line;
                while ((line = br.readLine()) != null) {
                    try {
                        msgs.add(Message.fromJson(line));
                    } catch (Exception ignored) {}
                }
                return msgs;
            }
        } finally {
            rwLock.readLock().unlock();
        }
    }

    /**
     * 向记录文件追加一条消息
     */
    public void append(String userId, Message msg) throws IOException {
        Path file = getUserFile(userId);
        rwLock.writeLock().lock();
        try {
            // 检查文件大小，防止无限增长
            if (Files.exists(file) && Files.size(file) > MAX_RECORD_SIZE) {
                // 简单的“滚动备份”
                Path backup = file.resolveSibling(file.getFileName() + ".bak");
                Files.move(file, backup, StandardCopyOption.REPLACE_EXISTING);
            }
            try (BufferedWriter bw = Files.newBufferedWriter(file,
                    StandardOpenOption.CREATE, StandardOpenOption.APPEND)) {
                bw.write(msg.toJson());
                bw.newLine();
            }
        } finally {
            rwLock.writeLock().unlock();
        }
    }

    private Path getUserFile(String userId) {
        // 防止路径遍历，只允许字母数字下划线
        if (!userId.matches("[A-Za-z0-9_]+")) {
            throw new IllegalArgumentException("Invalid userId");
        }
        return BASE_DIR.resolve("user_" + userId + ".log");
    }
}
