public class AdminConsole {
    private static final String ADMIN_FILE   = "admin.txt";
    private static final String PLAYER_FILE  = "players.bin";

    private String adminHash;                    // saved admin password hash
    private final List<Player> players = new ArrayList<>();
    private final Scanner in = new Scanner(System.in);

    /* --------------------------------------------------------------- */
    public static void main(String[] args) {
        AdminConsole console = new AdminConsole();
        console.run();
    }

    /* --------------------------------------------------------------- */
    public AdminConsole() {
        loadAdminPassword();
        loadPlayers();
    }

    /* --------------------------------------------------------------- */
    private void loadAdminPassword() {
        try (BufferedReader br = new BufferedReader(new FileReader(ADMIN_FILE))) {
            adminHash = br.readLine().trim();
        } catch (IOException e) {
            System.err.println("Cannot read admin.txt – creating default admin (password = admin).");
            adminHash = Utility.getHash("admin");
            saveAdminPassword();                // write the default file back
        }
    }

    private void saveAdminPassword() {
        try (PrintWriter pw = new PrintWriter(new FileWriter(ADMIN_FILE))) {
            pw.println(adminHash);
        } catch (IOException e) {
            System.err.println("Failed to write admin.txt");
        }
    }

    /* --------------------------------------------------------------- */
    private void loadPlayers() {
        File f = new File(PLAYER_FILE);
        if (!f.exists()) {
            System.out.println("players.bin not found – starting with an empty player list.");
            return;
        }
        try (ObjectInputStream ois = new ObjectInputStream(new FileInputStream(f))) {
            while (true) {
                Object obj = ois.readObject();
                if (obj instanceof Player) players.add((Player) obj);
            }
        } catch (EOFException ignored) {
            // normal termination of the stream
        } catch (Exception e) {
            System.err.println("Error loading players.bin: " + e);
        }
    }

    private void savePlayers() {
        try (ObjectOutputStream oos = new ObjectOutputStream(new FileOutputStream(PLAYER_FILE))) {
            for (Player p : players) oos.writeObject(p);
        } catch (IOException e) {
            System.err.println("Failed to save players: " + e);
        }
    }

    /* --------------------------------------------------------------- */
    private boolean loginAdmin() {
        System.out.print("Enter admin password > ");
        String pwd = in.nextLine();
        if (Utility.getHash(pwd).equals(adminHash)) {
            System.out.println("Login successful.\n");
            return true;
