```java
import java.util.*;

public class GameModule {
    private static final String PLAYER_FILE = "players.bin";

    private List<Player> playerDB = new ArrayList<>();
    private final Scanner in = new Scanner(System.in);

    public static void main(String[] args) {
        new GameModule().run();
    }

    private void run() {
        loadPlayers();
        System.out.println("\n=== HIGH‑SUM GAME ===\n");

        Player current = login();
        if (current == null) return;          // login failed → exit

        Dealer dealer = new Dealer();
        Deck deck = new Deck();

        boolean playAgain = true;
        while (playAgain) {
            playOneRound(current, dealer, deck);
            savePlayers();                    // persist chip changes

            System.out.print("\nPlay another game? (Y/N) > ");
            playAgain = in.nextLine().trim().equalsIgnoreCase("y");
        }
        System.out.println("\nThanks for playing!");
    }

    /* --------------------------------------------------------------- */
    /** Load all players from the binary file. */
    private void loadPlayers() {
        File f = new File(PLAYER_FILE);
        if (!f.exists()) {
            System.out.println("players.bin not found – no players to load.");
            return;
        }
        try (ObjectInputStream ois = new ObjectInputStream(new FileInputStream(f))) {
            while (true) {
                Object obj = ois.readObject();
                if (obj instanceof Player) playerDB.add((Player) obj);
            }
        } catch (EOFException ignored) {
            // Normal termination
        } catch (Exception e) {
            System.err.println("Error loading players: " + e);
        }
    }

    /** Persist the whole list (chip totals may have changed). */
    private void savePlayers() {
        try (ObjectOutputStream oos = new ObjectOutputStream(new FileOutputStream(PLAYER_FILE))) {
            for (Player p : playerDB) oos.writeObject(p);
        } catch (Exception e) {
            System.err.println("Error saving players: " + e);
        }
    }

    /* --------------------------------------------------------------- */
    /** Basic login that checks name + password against the player DB. */
    private Player login() {
        System.out.print("Login name > ");
        String name = in.nextLine().trim();
        System.out.print("Password > ");
        String pwd = in.nextLine().trim();

        for (Player p : playerDB) {
            if (p.getLoginName().equals(name) && p.checkPassword(pwd)) {
                System.out.println("Login successful.\n");
                return p;
            }
        }
        System.out.println("Invalid credentials.");
        return null;
    }

    /* --------------------------------------------------------------- */
    private void playOneRound(Player player, Dealer dealer, Deck deck) {
        final int NUM_ROUNDS = 4;
        int betOnTable = 0;
        boolean playerQuit = false;

        System.out.println("\n--- New Game ------------------------------------------------");
        System.out.println(player.getLoginName() + " has " + player.getChips() + " chips.");
        System.out.println("Dealer shuffles the deck.\n");

        deck.shuffle();
        dealer.clearCardsOnHand();
        player.clearCardsOnHand();

        // initial deal (2 cards each, dealer first)
        for (int i = 0; i < 2; i++) {
            dealer.addCard(deck.dealCard());
            player.addCard(deck.dealCard());
        }

        int round = 1;
        while (round <= NUM_ROUNDS) {
            System.out.println("\n--- ROUND " + round + " --------------------------------------");
            dealer.showCardsOnHand();          // dealer’s first card may be hidden
            player.showCardsOnHand();
            System.out.println("Your hand value = " + player.getTotalCardsValue());

            // ----- BETTING LOGIC -------------------------------------------------
            if (round >= 2) {
                // player may call or quit
                boolean valid = false;
                while (!valid) {
                    String prompt = (round == 2) ? "Do you want to follow? [Y/N] > "
                                                : "Call or Quit? [C/Q] > ";
                    String ans = in.nextLine().trim().toLowerCase();
                    if (ans.equals("y") || ans.equals("c")) {
                        valid = true;
                        int bet = readBet(player);
                        if (bet > 0) {
                            betOnTable += bet;
                            player.deductChips(bet);
                            System.out.println("Bet placed: " + bet);
                            System.out.println("Chips left: " + player.getChips());
                        }
                    } else if (ans.equals("n") || ans.equals("q")) {
                        valid = true;
                        playerQuit = true;
                        System.out.println("You quit this hand – dealer wins the current pot (" + betOnTable + ").");
                        round = NUM_ROUNDS + 1;    // break out of round loop
                    } else {
                        System.out.println("Please answer Y/N or C/Q.");
                    }
                }
            } else { // round 1: dealer forces a bet of 10 chips
                int dealerBet = 10;
                betOnTable += dealerBet;
                player.deductChips(dealerBet);
                System.out.println("Dealer forces a bet of 10 chips.");
                System.out.println("Chips left: " + player.getChips());
            }

            // ----- DEAL MORE CARDS ------------------------------------------------
            if (round == 2) {                     // 3rd card each
                dealer.addCard(deck.dealCard());
                player.addCard(deck.dealCard());
            } else if (round == 3) {              // 4th card each
                dealer.addCard(deck.dealCard());
                player.addCard(deck.dealCard());
            } else if (round == 4) {              // reveal dealer’s hidden card
                dealer.revealHiddenCard();
            }

            round++;
        }

        // ----- SHOWDOWN ---------------------------------------------------------
        if (!playerQuit) {
            System.out.println("\n--- SHOWDOWN -------------------------------------------------");
            dealer.showCardsOnHand();
            System.out.println("Dealer hand value = " + dealer.getTotalCardsValue());
            player.showCardsOnHand();
            System.out.println("Your hand value = " + player.getTotalCardsValue());

            if (player.getTotalCardsValue() > dealer.getTotalCardsValue()) {
                System.out.println("YOU WIN! You collect the pot of " + betOnTable + " chips.");
                player.addChips(betOnTable);
            } else {
                System.out.println("Dealer wins. You lose your bet.");
            }
        }
    }

    private int readBet(Player player) {
        while (true) {
            System.out.print("Enter your bet (>0, ≤your chips) > ");
            try {
                int bet = Integer.parseInt(in.nextLine().trim());
                if (bet <= 0) {
                    System.out.println("Bet must be positive.");
                } else if (bet > player.getChips()) {
                    System.out.println("You don't have that many chips.");
                } else {
                    return bet;
                }
            } catch (NumberFormatException e) {
