2️⃣ **基于 JWT 的握手身份验证**  

首先在 HTTP 登录接口返回 `Bearer <jwt>`（推荐使用 **Spring Security OAuth2 Resource Server**）。

#### 2.1 HandshakeInterceptor（验证 Token & Origin）

```java
@Component
public class JwtHandshakeInterceptor implements HandshakeInterceptor {

    private final JwtDecoder jwtDecoder; // Spring Security OAuth2 Resource Server auto‑config

    private static final List<String> ALLOWED_ORIGINS =
            List.of("https://app.example.com", "https://admin.example.com");

    public JwtHandshakeInterceptor(JwtDecoder jwtDecoder) {
        this.jwtDecoder = jwtDecoder;
    }

    @Override
    public boolean beforeHandshake(ServerHttpRequest request,
                                   ServerHttpResponse response,
                                   WebSocketHandler wsHandler,
                                   Map<String, Object> attributes) throws Exception {

        // ---- 1️⃣ Origin 校验 ----
        List<String> origins = request.getHeaders().get(HttpHeaders.ORIGIN);
        if (origins == null || origins.isEmpty()
                || !ALLOWED_ORIGINS.contains(origins.get(0))) {
            response.setStatusCode(HttpStatus.FORBIDDEN);
            return false;
        }

        // ---- 2️⃣ JWT 取出 & 校验 ----
        String token = null;
        // 支持两种取法：query string ?access_token=...  或  Authorization: Bearer ...
        if (request instanceof ServletServerHttpRequest servletReq) {
            token = servletReq.getServletRequest().getParameter("access_token");
            if (token == null) {
                String auth = servletReq.getServletRequest().getHeader(HttpHeaders.AUTHORIZATION);
                if (StringUtils.hasText(auth) && auth.startsWith("Bearer ")) {
                    token = auth.substring(7);
                }
            }
        }

        if (token == null) {
            response.setStatusCode(HttpStatus.UNAUTHORIZED);
            return false;
        }

        try {
            Jwt jwt = jwtDecoder.decode(token);
            // 选装：把用户信息放进 WebSocket session，供后续拦截器使用
            attributes.put("principal", new JwtAuthenticationToken(jwt));
        } catch (JwtException e) {
            response.setStatusCode(HttpStatus.UNAUTHORIZED);
            return false;
        }

        return true; // 通过握手
    }

    @Override
    public void afterHandshake(ServerHttpRequest request,
                               ServerHttpResponse response,
                               WebSocketHandler wsHandler,
                               Exception exception) {
        // nothing
    }
}
```

#### 2.2 配置 WebSocket 与拦截器

```java
@Configuration
@EnableWebSocketMessageBroker
public class WebSocketConfig implements WebSocketMessageBrokerConfigurer {

    private final JwtHandshakeInterceptor jwtHandshakeInterceptor;
    private final AuthChannelInterceptor authChannelInterceptor;

    public WebSocketConfig(JwtHandshakeInterceptor jwtHandshakeInterceptor,
                           AuthChannelInterceptor authChannelInterceptor) {
        this.jwtHandshakeInterceptor = jwtHandshakeInterceptor;
        this.authChannelInterceptor = authChannelInterceptor;
    }

    @Override
    public void registerStompEndpoints(StompEndpointRegistry registry) {
        registry.addEndpoint("/ws")                // 客户端使用 ws://host/ws 或 wss://host/ws
                .addInterceptors(jwtHandshakeInterceptor)
                .setAllowedOrigins("*")           // 实际请关闭或使用 whitelist
                .withSockJS();                    // 如需 SockJS fallback
    }

    @Override
    public void configureMessageBroker(MessageBrokerRegistry registry) {
        registry.enableSimpleBroker("/topic", "/queue")
                .setHeartbeatValue(new long[]{10000, 10000}); // 心跳 10s
        registry.setApplicationDestinationPrefixes("/app");
    }

    @Override
    public void configureClientInboundChannel(ChannelRegistration registration) {
        registration.interceptors(authChannelInterceptor);
    }
}
```

