package com.example.time;

import java.io.*;
import java.net.*;
import java.text.SimpleDateFormat;
import java.util.Date;

/**
 * 简单的时间服务器
 *
 * 接收形如 "From 学号 姓名： what time is it" 或 "From 学号 姓名：Exit" 的请求，
 * - 若是查询时间，返回 "To 姓名： yyyy-MM-dd HH:mm:ss"
 * - 若是退出请求，返回 "To 姓名： Bye" 并关闭该连接
 *
 * 为了演示安全风险，服务器 **不做任何身份校验**、**不加密**，仅为教学示例。
 */
public class TimeServer {

    /** 监听端口（可自行修改） */
    private static final int SERVER_PORT = 12345;

    public static void main(String[] args) {
        System.out.println("[Server] 启动时间服务器，监听端口 " + SERVER_PORT);
        try (ServerSocket serverSocket = new ServerSocket(SERVER_PORT)) {
            // 主循环：接受客户端连接
            while (true) {
                Socket clientSocket = serverSocket.accept(); // 阻塞等待
                System.out.println("[Server] 接收到来自 " + clientSocket.getRemoteSocketAddress() + " 的连接");
                // 为每个客户端创立独立线程
                new Thread(new ClientHandler(clientSocket)).start();
            }
        } catch (IOException e) {
            System.err.println("[Server] 异常退出: " + e.getMessage());
            e.printStackTrace();
        }
    }

    /** 处理单个客户端会话的内部类 */
    private static class ClientHandler implements Runnable {
        private final Socket socket;
        private final SimpleDateFormat sdf = new SimpleDateFormat("yyyy-MM-dd HH:mm:ss");

        ClientHandler(Socket socket) {
            this.socket = socket;
        }

        @Override
        public void run() {
            try (
                BufferedReader in = new BufferedReader(
                        new InputStreamReader(socket.getInputStream(), "UTF-8"));
                BufferedWriter out = new BufferedWriter(
                        new OutputStreamWriter(socket.getOutputStream(), "UTF-8"))
            ) {
                String line;
                // 只处理一条请求——本实验只要求一次请求后即结束会话
                if ((line = in.readLine()) != null) {
                    System.out.println("[Server] 收到请求: " + line);
                    // 解析请求
                    String response = processRequest(line);
                    out.write(response);
                    out.newLine();
                    out.flush();
                    System.out.println("[Server] 发送响应: " + response);
                }
            } catch (IOException e) {
                System.err.println("[Server] 与客户端通信异常: " + e.getMessage());
            } finally {
                try {
                    socket.close();
                    System.out.println("[Server] 关闭连接 " + socket.getRemoteSocketAddress());
                } catch (IOException ignored) {
                }
            }
        }

        /** 根据协议解析请求并生成响应 */
        private String processRequest(String request) {
            // request 示例: "From 20231001 张三： what time is it"
            //               "From 20231001 张三：Exit"
            // 先检查前缀是否为 "From "
            if (!request.startsWith("From ")) {
                return "Invalid request format";
            }

            // 去掉前缀后，以 "：" 分割左右两部分
            int colonIdx = request.indexOf('：');   // 中文全角冒号
            if (colonIdx == -1) {
                colonIdx = request.indexOf(':'); // 兼容全半角
                if (colonIdx == -1) {
                    return "Invalid request format";
                }
            }

            String header = request.substring(5, colonIdx).trim(); // 学号 姓名
            String body   = request.substring(colonIdx + 1).trim(); // 具体指令

            // 再把 header 拆成学号和姓名（本实验不使用学号，只保留姓名）
            String[] parts = header.split("\\s+");
            if (parts.length < 2) {
                return "Invalid header format";
            }
            String name = parts[1]; // 姓名

            if (body.equalsIgnoreCase("Exit")) {
                return "To " + name + "： Bye";
            } else {
                // 这里不检查 body 内容，只默认是时间查询
                String now = sdf.format(new Date());
                return "To " + name + "： " + now;
            }
        }
    }
}
```

