## 3️⃣ 客户端代码（`TimeClient.java`）

```java
package com.example.time;

import java.io.*;
import java.net.*;
import java.util.*;

/**
 * 客户端模拟 5 次交互：
 *
 *   1. 发送 "From 学号 姓名： what time is it"
 *   2. 接收并打印服务器返回的时间
 *   3. 重复 4 次，最后一次改为发送 "Exit" 并期待 "Bye"
 *
 * 为了演示，这里把每一次的学号/姓名写死在数组里，实际使用时可以改为
 * 从键盘读取或配置文件读取。
 */
public class TimeClient {

    private static final String SERVER_HOST = "localhost";
    private static final int SERVER_PORT = 12345;

    /** 演示用的 5 组学生信息 */
    private static final String[][] STUDENTS = {
            {"20231001", "张三"},
            {"20231002", "李四"},
            {"20231003", "王五"},
            {"20231004", "赵六"},
            {"20231005", "钱七"}
    };

    public static void main(String[] args) throws Exception {
        System.out.println("[Client] 启动客户端，准备向 " + SERVER_HOST + ":" + SERVER_PORT + " 发送请求");

        for (int i = 0; i < STUDENTS.length; i++) {
            String id   = STUDENTS[i][0];
            String name = STUDENTS[i][1];
            // 前四次查询时间，第五次发送 Exit
            boolean isLast = (i == STUDENTS.length - 1);
            String payload = isLast
                    ? String.format("From %s %s：Exit", id, name)
                    : String.format("From %s %s： what time is it", id, name);

            System.out.println("\n[Client] 第 " + (i + 1) + " 次请求 => " + payload);
            String response = sendAndReceive(payload);
            System.out.println("[Client] 服务器响应 => " + response);
        }

        System.out.println("\n[Client] 所有交互结束，客户端退出");
    }

    /** 与服务器建立一次 TCP 连接，发送请求并读取单行响应 */
    private static String sendAndReceive(String request) throws IOException {
        try (
                Socket socket = new Socket(SERVER_HOST, SERVER_PORT);
                BufferedWriter out = new BufferedWriter(
                        new OutputStreamWriter(socket.getOutputStream(), "UTF-8"));
                BufferedReader in = new BufferedReader(
                        new InputStreamReader(socket.getInputStream(), "UTF-8"))
        ) {
            // 发送请求（换行结束）
            out.write(request);
            out.newLine();
            out.flush();

            // 读取服务器返回的单行响应
            String reply = in.readLine();
            return reply != null ? reply : "(无响应)";
        }
    }
}
```

