### 8.4 级联下拉的前端脚本 `cascade.js`

```javascript
/**
 * 级联下拉（一级 -> 二级 -> 三级）实现
 * 依赖 jQuery、Bootstrap
 * 所有 AJAX 请求均附带 CSRF token
 */
$(function () {
    const csrfToken = $("meta[name='_csrf']").attr("content") || $("input[name='_csrf']").val();

    /** 统一的 AJAX 统一设置 */
    $.ajaxSetup({
        beforeSend: function (xhr) {
            xhr.setRequestHeader('X-CSRF-TOKEN', csrfToken);
        }
    });

    // 当一级单位改变时，加载二级
    $('#orgLevel1').on('change', function () {
        const parentId = $(this).val();
        resetSelect('#orgLevel2');
        resetSelect('#orgLevel3');
        if (parentId) {
            loadChildren(parentId, '#orgLevel2');
        }
    });

    // 当二级单位改变时，加载三级
    $('#orgLevel2').on('change', function () {
        const parentId = $(this).val();
        resetSelect('#orgLevel3');
        if (parentId) {
            loadChildren(parentId, '#orgLevel3');
        }
    });

    // 编辑页面回显时，自动触发加载
    const preSelected = {
        level1: $('#orgLevel1').val(),
        level2: $('#orgLevel2').data('selected'),   // data-selected由后台写入
        level3: $('#orgLevel3').data('selected')
    };
    if (preSelected.level1) {
        loadChildren(preSelected.level1, '#orgLevel2', preSelected.level2);
    }
    if (preSelected.level2) {
        loadChildren(preSelected.level2, '#orgLevel3', preSelected.level3);
    }

    /** 重置下拉框 */
    function resetSelect(selector) {
        $(selector).empty().append('<option value="">请选择</option>');
    }

    /** 从后端获取子单位并填充 */
    function loadChildren(parentId, targetSelect, selectedId) {
        $.getJSON('/org/children/' + parentId, function (data) {
            const $sel = $(targetSelect);
            $.each(data, function (i, item) {
                const $opt = $('<option>').val(item.id).text(item.name);
                if (selectedId && item.id == selectedId) {
                    $opt.prop('selected', true);
                }
                $sel.append($opt);
            });
        });
    }
});
```

> **安全说明**  
> - **CSRF token** 通过 `$.ajaxSetup` 自动加入每一次 AJAX 请求的 Header 中，配合 Spring Security 的 Cookie‑CSRF 实现防护。  
> - 所有 Ajax 返回的 JSON 为纯数据对象，前端直接渲染，不进行 `eval`，避免 **XSS**。  

