        ctx.init(kmf.getKeyManagers(), tmf.getTrustManagers(), new SecureRandom());

        SSLSocketFactory factory = ctx.getSocketFactory();

        try (SSLSocket socket = (SSLSocket) factory.createSocket(SERVER_HOST, SERVER_PORT)) {
            socket.setEnabledCipherSuites(new String[]{
                    "TLS_AES_128_GCM_SHA256",
                    "TLS_AES_256_GCM_SHA384"
            });
            socket.startHandshake();

            // ---- 发送自定义协议帧 ----
            DataOutputStream dos = new DataOutputStream(socket.getOutputStream());
            int offset = 0;
            while (offset < payload.length) {
                int chunk = Math.min(MAX_FRAME_SIZE, payload.length - offset);
                long ts = System.currentTimeMillis();

                dos.writeInt(chunk);   // 长度
                dos.writeLong(ts);     // 时间戳
                dos.write(payload, offset, chunk);
                dos.flush();

                offset += chunk;
            }
        } catch (SSLException se) {
            // 只记录概要信息到日志，防止泄漏证书细节
            System.err.println("TLS 握手失败: " + se.getMessage());
        }
    }
}
