            this.socket = socket;
        }

        @Override
        public void run() {
            try (Socket s = socket) {
                out = new DataOutputStream(s.getOutputStream());
                in  = new DataInputStream(s.getInputStream());

                // 1️⃣ 握手：客户端发送 USER_ID（TEXT 类型），服务器返回确认或“忙”
                Message hello = receiveMessage(s);
                if (hello == null || hello.getType() != Message.Type.TEXT) {
                    sendSystem("Invalid handshake");
                    return;
                }
                userId = hello.getText();  // 简单示例：直接使用用户发送的字符串
                if (sessions.containsKey(userId)) {
                    // 当前已有会话，可选择拒绝或接管
                    sendSystem("已有客服正在处理，是否接管？(YES/NO)");
                    Message reply = receiveMessage(s);
                    // 省略交互细节...
                }

                // 记录会话
                sessions.put(userId, this);
                System.out.println("[Agent] New session: " + userId);

                // 2️⃣ 加载历史记录（本地 JSON）
                loadHistory(userId);

                // 3️⃣ 主循环：收发消息
                while (true) {
                    Message msg = receiveMessage(s);
                    if (msg == null) { // 超时或异常
                        // 超时可视为“客服忙”提示给用户
                        sendSystem("客服暂时未响应，请稍后再试");
                        break;
                    }

