                    switch (msg.getType()) {
                        case TEXT:
                            handleUserText(msg);
                            break;
                        case IMAGE:
                            handleUserImage(msg);
                            break;
                        case FILE:
                            handleUserFile(msg);
                            break;
                        default:
                            sendSystem("不支持的消息类型");
