                }
            } catch (Exception e) {
                e.printStackTrace();
                // 发送错误信息，确保客户端能够感知异常
            } finally {
                // 关闭会话、持久化聊天记录
                if (userId != null) {
                    sessions.remove(userId);
                    saveHistory(userId);
                }
