            Path imgPath = Paths.get("records", userId, "images", System.currentTimeMillis() + ".png");
            Files.createDirectories(imgPath.getParent());
            Files.write(imgPath, msg.getPayload());
            appendHistory(userId, "[User] <图片> " + imgPath.getFileName());
            // 回传确认
