            sendMessage(socket, reply);
            appendHistory(userId, "[Agent] 已收到图片");
        }

        private void handleUserFile(Message msg) throws IOException {
            // 类似图片的处理，只是保存为任意文件
            Path filePath = Paths.get("records", userId, "files", System.currentTimeMillis() + ".dat");
            Files.createDirectories(filePath.getParent());
