                List<String> cur = new ArrayList<>();
                if (Files.exists(file)) {
                    cur = mapper.readValue(file.toFile(),
                            new TypeReference<List<String>>() {});
                }
                cur.add("[" + new java.util.Date() + "] " + line);
                mapper.writerWithDefaultPrettyPrinter().writeValue(file.toFile(), cur);
            } catch (IOException e) {
                e.printStackTrace();
            }
        }

