## 4. Persistent Store – `RecordingStore.java`

```java
package com.example.mouserecorder;

import com.google.gson.*;
import com.google.gson.reflect.TypeToken;

import java.io.*;
import java.lang.reflect.Type;
import java.nio.file.*;
import java.util.Collections;
import java.util.HashMap;
import java.util.Map;

/**
 * Handles (de)serialisation of the entire recordings map.
 * The file is stored in the user's home directory:
 *   $HOME/.mouse_recorder/recordings.json
 */
public class RecordingStore {

    private static final Path STORE_DIR =
            Paths.get(System.getProperty("user.home"), ".mouse_recorder");
    private static final Path STORE_FILE = STORE_DIR.resolve("recordings.json");

    private static final Gson GSON = new GsonBuilder()
            .setPrettyPrinting()
            .create();

    /** @return a mutable map – callers can add/remove entries. */
    public static Map<String, Recording> load() {
        try {
            if (!Files.exists(STORE_FILE)) {
                Files.createDirectories(STORE_DIR);
                // write an empty JSON object so we always have a file
                Files.writeString(STORE_FILE, "{}");
                return new HashMap<>();
            }

            String json = Files.readString(STORE_FILE);
            Type type = new TypeToken<Map<String, Recording>>() {}.getType();
            Map<String, Recording> map = GSON.fromJson(json, type);
            return map != null ? map : new HashMap<>();
        } catch (IOException | JsonSyntaxException e) {
            System.err.println("Failed to load recordings: " + e);
            return new HashMap<>();
        }
    }

    public static void save(Map<String, Recording> recordings) {
        try {
            Files.createDirectories(STORE_DIR);
            String json = GSON.toJson(recordings);
            Files.writeString(STORE_FILE, json, StandardOpenOption.CREATE,
                    StandardOpenOption.TRUNCATE_EXISTING);
        } catch (IOException e) {
            System.err.println("Failed to save recordings: " + e);
        }
    }
}
```

