## 5. Capture Logic – `Recorder.java`

```java
package com.example.mouserecorder;

import java.awt.*;
import java.util.concurrent.*;
import java.util.concurrent.atomic.AtomicBoolean;

/**
 * Runs in its own thread, polls the mouse position every 10 ms,
 * timestamps each sample and stores it into the supplied Recording.
 *
 * Start → new Recorder(...).start()
 * Stop  → recorder.stopRecording()
 */
public class Recorder {

    private static final int POLL_INTERVAL_MS = 10;

    private final Recording recording;
    private final Robot robot;
    private final ScheduledExecutorService executor;
    private final AtomicBoolean running = new AtomicBoolean(false);
    private long startTime;

    public Recorder(Recording recording) throws AWTException {
        this.recording = recording;
        this.robot = new Robot();
        this.executor = Executors.newSingleThreadScheduledExecutor(r -> {
            Thread t = new Thread(r, "MouseRecorderThread");
            t.setDaemon(true);
            return t;
        });
    }

    public void start() {
        if (running.getAndSet(true)) return; // already running
        startTime = System.currentTimeMillis();
        executor.scheduleAtFixedRate(this::sampleMouse, 0,
                POLL_INTERVAL_MS, TimeUnit.MILLISECONDS);
    }

    private void sampleMouse() {
        if (!running.get()) return;
        Point p = MouseInfo.getPointerInfo().getLocation();
        long elapsed = System.currentTimeMillis() - startTime;
        recording.points.add(new Recording.PointWithTime(p.x, p.y, elapsed));
    }

    /** Stops the sampling thread and shuts down the executor. */
    public void stopRecording() {
        if (!running.getAndSet(false)) return;
        executor.shutdownNow();
    }
}
```

