## 6. Playback Logic – `Player.java`

```java
package com.example.mouserecorder;

import java.awt.*;
import java.util.List;
import java.util.concurrent.*;

/**
 * Replays a stored Recording by moving the mouse to each point at the
 * recorded timestamp. Runs in its own thread so the UI remains responsive.
 *
 * Usage:
 *   Player p = new Player(recording);
 *   p.play();
 */
public class Player {

    private final Recording recording;
    private final Robot robot;
    private final ExecutorService executor = Executors.newSingleThreadExecutor();

    public Player(Recording recording) throws AWTException {
        this.recording = recording;
        this.robot = new Robot();
    }

    public Future<?> play() {
        return executor.submit(() -> {
            List<Recording.PointWithTime> pts = recording.points;
            if (pts.isEmpty()) return;

            long start = System.currentTimeMillis();
            long base = pts.get(0).time; // typically 0
            for (Recording.PointWithTime pt : pts) {
                long target = start + (pt.time - base);
                long now = System.currentTimeMillis();
                long sleep = target - now;
                if (sleep > 0) {
                    try {
                        Thread.sleep(sleep);
                    } catch (InterruptedException ignored) {
                        break; // abort on interruption
                    }
                }
                robot.mouseMove(pt.x, pt.y);
            }
        });
    }

    public void shutdown() {
        executor.shutdownNow();
    }
}
```

