public class Main {

    private static final Map<String, Recording> recordings = RecordingStore.load();

    public static void main(String[] args) {
        // Install the global hot‑key listener *before* the UI is shown.
        try {
            HotKeyListener.install(recordings);
        } catch (NativeHookException e) {
            System.err.println("Failed to install global hotkeys: " + e);
            System.exit(1);
        }

        // All UI work on EDT
        SwingUtilities.invokeLater(Main::createAndShowGui);
    }

    private static void createAndShowGui() {
        JFrame frame = new JFrame("Mouse Recorder");
        frame.setDefaultCloseOperation(JFrame.EXIT_ON_CLOSE);
        frame.setSize(620, 400);
        frame.setLocationRelativeTo(null);

        // Table model – each row = one Recording
        DefaultTableModel model = new DefaultTableModel(
                new Object[]{"Name", "Duration (s)", "Points"}, 0) {
            @Override public boolean isCellEditable(int row, int col) { return false; }
        };
        JTable table = new JTable(model);
        table.setSelectionMode(ListSelectionModel.SINGLE_SELECTION);
        table.setFillsViewportHeight(true);
        table.setAutoCreateRowSorter(true);

        // Fill model from the map
        populateTableModel(model);

        // Add a right‑click context menu
        JPopupMenu popup = new JPopupMenu();
        JMenuItem deleteItem = new JMenuItem("Delete");
        deleteItem.addActionListener(e -> deleteSelectedRecording(table, model));
        popup.add(deleteItem);
        table.setComponentPopupMenu(popup);

        // Double‑click or ENTER = play
        table.addMouseListener(new MouseAdapter() {
            @Override public void mouseClicked(MouseEvent e) {
                if (e.getClickCount() == 2 && table.getSelectedRow() != -1) {
                    playSelected(table);
                }
            }
        });
        table.getInputMap(JComponent.WHEN_ANCESTOR_OF_FOCUSED_COMPONENT)
             .put(KeyStroke.getKeyStroke(KeyEvent.VK_ENTER, 0), "play");
        table.getActionMap().put("play", new AbstractAction() {
            @Override public void actionPerformed(ActionEvent e) {
                playSelected(table);
            }
        });

        // Bottom status line – screen size
        Dimension screen = Toolkit.getDefaultToolkit().getScreenSize();
        JLabel status = new JLabel("Screen: " + screen.width + "×" + screen.height);
        status.setBorder(BorderFactory.createEmptyBorder(4,4,4,4));

        frame.add(new JScrollPane(table), BorderLayout.CENTER);
        frame.add(status, BorderLayout.SOUTH);
        frame.setVisible(true);
    }

    private static void populateTableModel(DefaultTableModel model) {
        model.setRowCount(0);
        for (Recording r : recordings.values()) {
            model.addRow(new Object[]{
                    r.name,
                    String.format("%.2f", r.getDuration() / 1000.0),
                    r.points.size()
            });
        }
    }

    private static void deleteSelectedRecording(JTable table, DefaultTableModel model) {
        int viewRow = table.getSelectedRow();
        if (viewRow == -1) return;
        int modelRow = table.convertRowIndexToModel(viewRow);
        String name = (String) model.getValueAt(modelRow, 0);
        int confirm = JOptionPane.showConfirmDialog(
                table,
                "Delete recording '" + name + "'?",
                "Confirm Delete",
                JOptionPane.YES_NO_OPTION);
        if (confirm == JOptionPane.YES_OPTION) {
            recordings.remove(name);
            RecordingStore.save(recordings);
            model.removeRow(modelRow);
        }
    }

    private static void playSelected(JTable table) {
        int viewRow = table.getSelectedRow();
        if (viewRow == -1) return;
        int modelRow = table.convertRowIndexToModel(viewRow);
        String name = (String) table.getModel().getValueAt(modelRow, 0);
        Recording rec = recordings.get(name);
        if (rec == null) {
            JOptionPane.showMessageDialog(table,
                    "Recording not found (it may have been deleted).",
                    "Error",
                    JOptionPane.ERROR_MESSAGE);
            return;
        }

        // Play in background & show a small progress dialog
        SwingWorker<Void, Void> worker = new SwingWorker<>() {
            @Override protected Void doInBackground() throws Exception {
                Player player = new Player(rec);
                player.play().get(); // wait until finished
                return null;
            }

            @Override protected void done() {
                // no UI update needed – just close the dialog
            }
        };

        JDialog dlg = new JDialog((Frame) null, "Playing '" + rec.name + "'", true);
        dlg.setLayout(new BorderLayout());
        dlg.add(new JLabel("Playing... press ESC to abort.", SwingConstants.CENTER), BorderLayout.CENTER);
        dlg.setSize(300, 120);
        dlg.setLocationRelativeTo(table);
        dlg.addKeyListener(new KeyAdapter() {
            @Override public void keyPressed(KeyEvent e) {
                if (e.getKeyCode() == KeyEvent.VK_ESCAPE) {
                    worker.cancel(true);
                    dlg.dispose();
                }
            }
        });
        dlg.setDefaultCloseOperation(JDialog.DISPOSE_ON_CLOSE);
        dlg.setVisible(true);

        worker.execute();
    }
}
