                int len;
                try {
                    len = dis.readInt(); // 自动大端（network order）
                } catch (EOFException e) {
                    System.out.println("Client closed connection");
                    break;
                }
                if (len <= 0 || len > 2_000_000) { // 基本检查，防止异常大值导致 OOM
                    System.err.println("Invalid NAL length: " + len);
                    break;
                }

                byte[] nal = new byte[len];
                dis.readFully(nal);
                // 解码单帧 NAL（这里假设发送的 NAL 已经是完整的帧，例如 SPS+PPS+IDR或普通帧）
                BufferedImage img = decodeNalToImage(nal);
                if (img != null) {
                    SwingUtilities.invokeLater(() -> videoLabel.setIcon(new ImageIcon(img)));
                }
            }
        } catch (Exception e) {
            System.err.println("Error handling client: " + e.getMessage());
            e.printStackTrace();
        } finally {
            try { client.close(); } catch (IOException ignored) {}
        }
    }

    /** 使用 JCodec 把单个 NAL（Annex B）解码为 BufferedImage */
    private BufferedImage decodeNalToImage(byte[] annexB) {
        try {
            // JCodec 不直接支持裸 Annex B，必须包装为 ByteBuffer 并使用 H264Decoder
            org.jcodec.codecs.h264.H264Decoder decoder = new org.jcodec.codecs.h264.H264Decoder();
            // 将 Annex B 转成 NALUnit 列表
            org.jcodec.codecs.h264.io.model.NALUnit[] units = org.jcodec.codecs.h264.io.model.NALUnit.readFromByteBuffer(ByteBuffer.wrap(annexB));
