public class H264NettyServer {
    private final int port = 8443; // TLS 常用 443/8443
    public static void main(String[] args) throws Exception {
        new H264NettyServer().run();
    }

    public void run() throws Exception {
        // SSLContext (自签名或企业CA)
        SslContext sslCtx = SslContextBuilder.forServer(
                new File("cert/server.crt"),
                new File("cert/server.key"))
                .trustManager(new File("cert/ca.crt")) // mutual TLS 可选
                .clientAuth(ClientAuth.REQUIRE)
                .build();

        EventLoopGroup boss = new NioEventLoopGroup(1);
        EventLoopGroup worker = new NioEventLoopGroup();
        try {
            ServerBootstrap b = new ServerBootstrap();
            b.group(boss, worker)
             .channel(NioServerSocketChannel.class)
             .childHandler(new ChannelInitializer<SocketChannel>() {
                 @Override
                 protected void initChannel(SocketChannel ch) {
                     ChannelPipeline p = ch.pipeline();
                     p.addLast(sslCtx.newHandler(ch.alloc()));
                     // LengthFieldBasedFrameDecoder: 4-byte length + NAL
                     p.addLast(new LengthFieldBasedFrameDecoder(
                             Integer.MAX_VALUE, 0, 4, 0, 4));
                     // 自己的业务处理
                     p.addLast(new H264FrameHandler());
                 }
             })
             .option(ChannelOption.SO_BACKLOG, 128)
             .childOption(ChannelOption.SO_RCVBUF, 2 * 1024 * 1024); // 2 MB 接收缓冲

            ChannelFuture f = b.bind(port).sync();
            System.out.println("TLS H264 server listening on " + port);
            f.channel().closeFuture().sync();
        } finally {
            boss.shutdownGracefully();
            worker.shutdownGracefully();
        }
    }
}
