public class H264FrameHandler extends SimpleChannelInboundHandler<ByteBuf> {

    // 限流：每秒最多 30 帧（可根据分辨率调节）
    private final RateLimiter limiter = RateLimiter.create(30.0);

    // JavaCV 解码器
    private final FFmpegFrameGrabber grabber = new FFmpegFrameGrabber(new ByteArrayInputStream(new byte[0]));

    public H264FrameHandler() {
        // 配置解码器（只要初始化一次，后面每次喂入新数据即可）
        grabber.setFormat("h264");
        grabber.setOption("fflags", "nobuffer");
        grabber.setOption("flags", "low_delay");
        try {
            grabber.start();
        } catch (Exception e) {
            throw new RuntimeException("Failed to start FFmpegFrameGrabber", e);
        }
    }

    @Override
    protected void channelRead0(ChannelHandlerContext ctx, ByteBuf msg) throws Exception {
        if (!limiter.tryAcquire()) {
            // 丢帧策略：直接返回，防止 CPU 爆炸
            return;
        }

        // NAL 数据已经剥离长度字段，由 LengthFieldBasedFrameDecoder 完成
        byte[] nalBytes = new byte[msg.readableBytes()];
        msg.readBytes(nalBytes);
        // 将单个 NAL 包装成完整的 H264 ES（FFmpeg 需要完整的 Annex B）
        // 为了兼容多 NAL（SPS+PPS+Slice）需要自行缓存，这里演示最简方案
        try (ByteArrayInputStream bis = new ByteArrayInputStream(nalBytes)) {
            grabber.setInputStream(bis);
            Frame frame = grabber.grabImage(); // 只抓图像帧
            if (frame != null) {
                BufferedImage img = new Java2DFrameConverter().convert(frame);
                // 渲染到 UI（Swing/JavaFX） —— 这里用线程安全的方式交给 UI 线程
                SwingUtilities.invokeLater(() -> MyVideoPanel.updateImage(img));
            }
        } catch (Exception e) {
            // 解码错误可能是非法 NAL（攻击者尝试触发缓冲区溢出等），记录日志并断开连接
            System.err.println("Bad NAL from " + ctx.channel().remoteAddress() + ": " + e.getMessage());
            ctx.close();
        }
    }

    @Override
    public void exceptionCaught(ChannelHandlerContext ctx, Throwable cause) {
        System.err.println("Exception: " + cause);
        ctx.close();
    }

    @Override
    public void channelInactive(ChannelHandlerContext ctx) throws Exception {
        System.out.println("Client disconnected: " + ctx.channel().remoteAddress());
        super.channelInactive(ctx);
    }
}
```

> **关键安全点说明**  
> 1. **TLS 加密**：`SslContextBuilder` 用自签名或商业证书，`clientAuth(ClientAuth.REQUIRE)` 实现**双向认证**。  
> 2. **帧长度校验**：`LengthFieldBasedFrameDecoder` 会自动抛出 `TooLongFrameException`，避免 **缓冲区溢出**。  
> 3. **速率限制（RateLimiter）**：防止恶意高帧率导致 CPU 过载（DoS）。  
> 4. **异常立即关闭**：对不合法的 NAL（比如经过篡改的 SPS / PPS）直接 `ctx.close()`，防止后续漏洞利用。  
> 5. **资源池**：`FFmpegFrameGrabber` 只创建一次并复用，避免频繁 JNI 调用导致内存泄漏。  
> 6. **输入检查**：在 `channelRead0` 前已由 Netty Frame Decoder 检查长度，进一步防止 **整数溢出**。

