public class NumPagesExtractor {

    /** Максимальный размер файла, который мы считаем «безопасным» для загрузки. */
    private static final long MAX_DOCX_SIZE = 50 * 1024 * 1024; // 50 MiB

    public static void main(String[] args) throws Exception {
        if (args.length != 1) {
            System.err.println("Usage: java -jar numpages.jar <path-to-docx>");
            System.exit(1);
        }

        File docxFile = new File(args[0]);

        // ---------- 1. Защищённый ввод ----------
        validateFile(docxFile);

        // ---------- 2. Открываем пакет ----------
        WordprocessingMLPackage wordMLPackage = WordprocessingMLPackage.load(docxFile);

        // ---------- 3. Обновляем поля ----------
        // При этом docx4j проводит layout‑pass и формирует метаданные о страницах.
        updateAllFields(wordMLPackage);

        // ---------- 4. Читаем значение NUMPAGES ----------
        Integer numPages = extractNumPages(wordMLPackage);
        if (numPages == null) {
            System.err.println("Не удалось найти поле NUMPAGES в документе.");
        } else {
            System.out.println("Точное количество страниц: " + numPages);
        }
    }

    /** Проверка размера/целостности входного файла. */
    private static void validateFile(File f) throws IOException {
        if (!f.isFile()) {
            throw new FileNotFoundException("Файл не найден: " + f.getAbsolutePath());
        }
        if (f.length() > MAX_DOCX_SIZE) {
            throw new IOException("Файл слишком большой (" + f.length() + " байт). " +
                    "Допустимый максимум: " + MAX_DOCX_SIZE + " байт.");
        }
        // Обезопаcиваем от zip‑бомб: docx4j автоматически ограничивает количество
        // вложенных ZIP‑записей, но можно добавить дополнительный Guard, если нужно.
    }

    /** Обновление всех полей в документе, включая NUMPAGES. */
    private static void updateAllFields(WordprocessingMLPackage wordMLPackage) throws Docx4JException {
        // Сначала включаем «программный» рендеринг, чтобы правильно посчитать страницы.
        // Генерируем PDF в память – это заставит docx4j выполнить layout‑pass.
        try (ByteArrayOutputStream baos = new ByteArrayOutputStream()) {
            PdfConversion conversion = new PdfConversionViaXSLFO(wordMLPackage);
            conversion.output(baos, new org.docx4j.convert.out.pdf.PdfConversionOptions());
        } catch (Exception e) {
            // Если PDF-конвертация упала, всё равно попытаемся обновить поля «обычным» способом.
            System.err.println("PDF‑конвертация завершилась ошибкой, продолжаем без неё: " + e.getMessage());
        }

        // После layout‑pass вызываем FieldUpdater – он заменит <fldSimple> и <instrText>
        // значениями, рассчитанными движком.
        MainDocumentPart mdp = wordMLPackage.getMainDocumentPart();
        mdp.variableReplace(new java.util.HashMap<>()); // чистим переменные, если они там есть

        // Обновляем всё: https://github.com/plutext/docx4j/blob/master/src/main/java/org/docx4j/model/fields/FieldUpdater.java
        new FieldUpdater(wordMLPackage).updateFields();
    }

    /** Ищем первое вхождение поля NUMPAGES (может быть несколько, берём любой). */
    private static Integer extractNumPages(WordprocessingMLPackage wordMLPackage) {
        // Поле NUMPAGES обычно реализовано как <w:fldSimple w:instr="NUMPAGES \* MERGEFORMAT">
        // либо как <w:fldChar w:fldCharType="begin"/> + <w:instrText>NUMPAGES</w:instrText> + <w:fldChar w:fldCharType="separate"/> + <w:t>3</w:t> + <w:fldChar w:fldCharType="end"/>
