        // 1) Простой вариант – ищем <w:fldSimple>
        List<Object> simpleFlds = mdp.getJaxbElement().getBody()
                .getContent()
                .stream()
                .filter(o -> o instanceof P)
                .map(o -> (P) o)
                .flatMap(p -> p.getContent().stream())
                .filter(o -> o instanceof R)
                .map(o -> (R) o)
                .flatMap(r -> r.getContent().stream())
                .filter(o -> o instanceof JAXBElement)
                .map(o -> (JAXBElement) o)
                .filter(e -> e.getDeclaredType().equals(FldSimple.class))
                .map(e -> (FldSimple) e.getValue())
                .filter(fs -> fs.getInstr().toUpperCase().startsWith("NUMPAGES"))
                .toList();

        if (!simpleFlds.isEmpty()) {
            // Внутри FldSimple искомый текст уже заменён на число.
            String txt = simpleFlds.get(0).getContent().get(0).toString(); // обычно один <w:t>
            try {
                return Integer.valueOf(txt.trim());
            } catch (NumberFormatException ignored) {}
        }

        // 2) Если документ использует «complex» field (begin‑separate‑end)
        // Мы будем искать последовательность fldChar(begin) → instrText(NUMPAGES) → fldChar(separate) → w:t(число)
        List<Object> bodyContent = mdp.getJaxbElement().getBody().getContent();

        for (int i = 0; i < bodyContent.size(); i++) {
            if (!(bodyContent.get(i) instanceof P)) continue;
            P p = (P) bodyContent.get(i);
            List<Object> runs = p.getContent();
            for (int j = 0; j < runs.size(); j++) {
                if (!(runs.get(j) instanceof R)) continue;
                R r = (R) runs.get(j);
                // ищем fldChar(begin)
                if (hasFldCharOfType(r, STFldCharType.BEGIN)) {
                    // проверяем следующее Run – instrText
                    if (j + 1 < runs.size() && runs.get(j + 1) instanceof R) {
                        R instrRun = (R) runs.get(j + 1);
                        String instr = getInstrText(instrRun);
                        if (instr != null && instr.trim().toUpperCase().startsWith("NUMPAGES")) {
                            // ищем fldChar(separate) и после него число
                            for (int k = j + 2; k < runs.size(); k++) {
                                R candidate = (R) runs.get(k);
                                if (hasFldCharOfType(candidate, STFldCharType.SEPARATE)) {
                                    // следующее Run после SEPARATE – это число
                                    if (k + 1 < runs.size() && runs.get(k + 1) instanceof R) {
                                        R numberRun = (R) runs.get(k + 1);
                                        String number = getText(numberRun);
                                        if (number != null) {
                                            try {
                                                return Integer.valueOf(number.trim());
                                            } catch (NumberFormatException ignored) {}
                                        }
                                    }
                                }
                            }
                        }
                    }
                }
            }
        }

        // Если дошли сюда – поле не найдено
        return null;
    }

    /** Проверка наличия <w:fldChar w:fldCharType="…"> */
    private static boolean hasFldCharOfType(R run, STFldCharType type) {
        for (Object o : run.getContent()) {
            if (o instanceof JAXBElement) {
                JAXBElement<?> je = (JAXBElement<?>) o;
                if (je.getDeclaredType().equals(FldChar.class)) {
                    FldChar fc = (FldChar) je.getValue();
                    return fc.getFldCharType() == type;
                }
            }
        }
        return false;
    }

    /** Возвращает текст из <w:instrText> внутри run */
    private static String getInstrText(R run) {
        for (Object o : run.getContent()) {
            if (o instanceof JAXBElement) {
                JAXBElement<?> je = (JAXBElement<?>) o;
                if (je.getDeclaredType().equals(CTText.class) && "instrText".equals(je.getName().getLocalPart())) {
                    return ((CTText) je.getValue()).getValue();
                }
            }
        }
        return null;
    }

    /** Возвращает обычный <w:t> текст внутри run */
    private static String getText(R run) {
        for (Object o : run.getContent()) {
            if (o instanceof JAXBElement) {
                JAXBElement<?> je = (JAXBElement<?>) o;
                if (je.getDeclaredType().equals(Text.class)) {
                    return ((Text) je.getValue()).getValue();
                }
            }
        }
        return null;
    }
}
