## 4️⃣ 按角色跳转的 **AuthenticationSuccessHandler**

```java
package com.example.demo.config;

import jakarta.servlet.ServletException;
import jakarta.servlet.http.*;
import org.springframework.security.core.*;
import org.springframework.security.web.authentication.AuthenticationSuccessHandler;
import org.springframework.stereotype.Component;

import java.io.IOException;
import java.util.*;

@Component
public class CustomAuthenticationSuccessHandler implements AuthenticationSuccessHandler {

    // 这里的映射可以外部化（如配置文件）以便维护
    private static final Map<String, String> ROLE_TARGET_URL = Map.of(
            "ROLE_ADMIN", "/admin/dashboard",
            "ROLE_USER",  "/user/home"
    );

    @Override
    public void onAuthenticationSuccess(HttpServletRequest request,
                                        HttpServletResponse response,
                                        Authentication authentication)
            throws IOException, ServletException {

        Collection<? extends GrantedAuthority> authorities = authentication.getAuthorities();
        String targetUrl = "/"; // 默认

        for (GrantedAuthority auth : authorities) {
            String roleName = auth.getAuthority();
            if (ROLE_TARGET_URL.containsKey(roleName)) {
                targetUrl = ROLE_TARGET_URL.get(roleName);
                break; // 按顺序取第一个匹配的角色
            }
        }

        // 防止出现 Open Redirect 漏洞，确保是内部相对路径
        if (!targetUrl.startsWith("/")) {
            targetUrl = "/";
        }

        response.sendRedirect(targetUrl);
    }
}
```

