## 5️⃣ Spring Security 配置（Java Config）

```java
package com.example.demo.config;

import com.example.demo.service.MyUserDetailsService;
import org.springframework.context.annotation.*;
import org.springframework.security.authentication.AuthenticationProvider;
import org.springframework.security.authentication.dao.*;
import org.springframework.security.config.Customizer;
import org.springframework.security.config.annotation.web.*;
import org.springframework.security.config.annotation.web.builders.*;
import org.springframework.security.crypto.bcrypt.*;
import org.springframework.security.crypto.password.PasswordEncoder;
import org.springframework.security.web.*;
import org.springframework.security.web.util.matcher.AntPathRequestMatcher;

@Configuration
@EnableWebSecurity
public class SecurityConfig {

    private final MyUserDetailsService userDetailsService;
    private final CustomAuthenticationSuccessHandler successHandler;

    public SecurityConfig(MyUserDetailsService userDetailsService,
                          CustomAuthenticationSuccessHandler successHandler) {
        this.userDetailsService = userDetailsService;
        this.successHandler = successHandler;
    }

    // ------------------ PasswordEncoder --------------------
    @Bean
    public PasswordEncoder passwordEncoder() {
        // 推荐使用 BCrypt，strength 12 已经足够
        return new BCryptPasswordEncoder(12);
    }

    // ------------------ AuthenticationProvider ----------------
    @Bean
    public DaoAuthenticationProvider authenticationProvider() {
        DaoAuthenticationProvider provider = new DaoAuthenticationProvider();
        provider.setUserDetailsService(userDetailsService);
        provider.setPasswordEncoder(passwordEncoder());
        return provider;
    }

    // ------------------ SecurityFilterChain -----------------
    @Bean
    public SecurityFilterChain filterChain(HttpSecurity http) throws Exception {
        http
            // 1️⃣ 关闭默认登录页，使用自定义 login.html
            .formLogin(form -> form
                .loginPage("/login")          // GET /login 返回页面
                .loginProcessingUrl("/perform_login") // POST 表单提交地址
                .successHandler(successHandler) // 登录成功后的跳转
                .failureUrl("/login?error=true")
                .permitAll()
            )

            // 2️⃣ 登出配置
            .logout(logout -> logout
                .logoutRequestMatcher(new AntPathRequestMatcher("/logout"))
                .logoutSuccessUrl("/login?logout")
                .invalidateHttpSession(true)
                .deleteCookies("JSESSIONID")
                .permitAll()
            )

            // 3️⃣ CSRF（默认开启）——如果是纯 API 可自行关闭
            .csrf(csrf -> csrf
                .ignoringRequestMatchers("/h2-console/**") // 示例：对 H2 控制台关闭 CSRF
            )

            // 4️⃣ 访问鉴权：根据角色限制 URL
            .authorizeHttpRequests(authz -> authz
                // ⬇️ 静态资源（css/js/img）不需要认证
                .requestMatchers("/css/**", "/js/**", "/images/**", "/webjars/**").permitAll()
                // ⬇️ 登录页、错误页 etc.
                .requestMatchers("/", "/login", "/error", "/access-denied").permitAll()
                // ⬇️ ADMIN 专属页面
                .requestMatchers("/admin/**").hasRole("ADMIN")
                // ⬇️ USER 专属页面
                .requestMatchers("/user/**").hasRole("USER")
                // ⬇️ 所有其他请求必须登录
                .anyRequest().authenticated()
            )

            // 5️⃣ 会话管理（防止并发登录、session fixation 等）
            .sessionManagement(sess -> sess
                .sessionFixation().migrateSession()
                .maximumSessions(1)                     // 每个账号最多一次登录
                .maxSessionsPreventsLogin(false)        // 允许新登录踢掉旧会话
                .expiredUrl("/login?expired")
            );

        // 6️⃣ 如果你需要基于角色的权限层级（例如 ADMIN 也拥有 USER 权限），可以配置 RoleHierarchy
        // 下面的 bean 在后面声明
        return http.build();
    }

    // ------------------ Role Hierarchy（可选） -----------------
    // ADMIN > USER，表示 ADMIN 自动拥有 USER 的所有权限
    @Bean
    public RoleHierarchy roleHierarchy() {
        RoleHierarchyImpl hierarchy = new RoleHierarchyImpl();
        hierarchy.setHierarchy("ROLE_ADMIN > ROLE_USER");
        return hierarchy;
    }

    // ------------------ AccessDeniedHandler（可选） ------------
    @Bean
    public AccessDeniedHandler accessDeniedHandler() {
        return (request, response, accessDeniedException) -> {
            // 统一跳转到自定义页面，避免泄露细节
            response.sendRedirect(request.getContextPath() + "/access-denied");
        };
    }
}
```

### 关键点说明

| 配置项 | 作用 | 常见坑点 |
|---|---|---|
| `formLogin().loginPage("/login")` | 自定义登录页（GET 请求返回 `login.html`） | 必须 **permitAll()** 否则会导致无限重定向 |
| `loginProcessingUrl("/perform_login")` | 表单 `POST` 提交地址，Spring Security 自动拦截 | 表单 `action` 必须对应此路径 |
| `successHandler` | 登录成功后自行决定跳转页面（按角色） | 确保返回 **相对路径**，防止 Open Redirect 漏洞 |
| `antMatchers` / `mvcMatchers` | URL ↔ 角色映射 | `hasRole("ADMIN")` 实际检查 `ROLE_ADMIN`，记得在 DB/代码中加前缀 |
| `csrf().ignoringRequestMatchers(...)` | 对特定端点关闭 CSRF（如 H2 控制台） | 生产环境 **不要** 关闭全局 CSRF |
| `sessionManagement().maximumSessions(1)` | 同用户只能登录一次，防止会话劫持 | 多设备需要时改为 `maximumSessions(Integer.MAX_VALUE)` |
| `RoleHierarchy` | 角色层级（ADMIN 包含 USER 权限） | 只在 `hasAuthority`/`hasRole` 检查时生效，**不** 自动在 `@PreAuthorize` 中生效，若使用 SpEL，需要配置 `@EnableMethodSecurity` 并在 `MethodSecurityExpressionHandler` 中注入层级 |
| `PasswordEncoder` | 密码加密（BCrypt） | 同时在 `UserDetailsService` 中使用相同的 encoder，否则登录失败 |

