    @Autowired private UserMapper userMapper;
    @Autowired private PersonMapper personMapper;
    @Autowired private OrgMapper orgMapper;
    @Autowired private RoleMapper roleMapper;

    /**
     * 登录校验：先查询用户 → bcrypt 检查密码 → 装配关联对象 → 返回。
     */
    @Override
    public User login(String username, String rawPassword) {
        User user = userMapper.findByUsername(username);
        if (user == null || !Objects.equals(user.getStatus(), 1)) {
            return null; // 用户不存在或被禁用
        }
        // BCrypt 校验
        if (!PasswordUtil.matches(rawPassword, user.getPassword())) {
            return null; // 密码错误
        }

        // 装配关联信息（一次性查询，实际可用 MyBatis Association / ResultMap 简化）
        Person person = personMapper.findById(user.getPersonId());
        Org org = orgMapper.findById(user.getOrgId());
        List<Role> roles = userMapper.findRolesByUserId(user.getId());

        user.setPerson(person);
        user.setOrg(org);
        user.setRoles(roles);
        return user;
    }

    /**
     * 注册新用户（示例实现）：
     * 1. 先保存 Person → Org（如果已存在则直接使用） → 保存 User（密码 BCrypt） → 关联默认角色
     */
    @Override
    @Transactional
    public User register(User user, String rawPassword) {
        // 保存人员信息
        Person person = user.getPerson();
        personMapper.insert(person);
        user.setPersonId(person.getId());

        // 假设 org 已经存在，只需要把 id 赋值进来
        // 如果想自动创建组织，可在此补充逻辑

        // 加密密码
        String bcrypt = PasswordUtil.encode(rawPassword);
        user.setPassword(bcrypt);
        user.setStatus(1);
        userMapper.insert(user);

        // 关联默认角色（如 USER）
        Role defaultRole = roleMapper.findByName("USER");
        if (defaultRole != null) {
            // 手动写入关联表
            // 这里直接使用 MyBatis 注解写脚本，也可以写专门的 UserRoleMapper
            // 为简单演示，使用 SqlSession 的 execute
            // 下面会使用一个临时 Mapper
            userMapper.insertUserRole(user.getId(), defaultRole.getId());
        }

        return user;
    }
}
```

> **注意**：上述 `UserMapper` 需要额外提供 `insertUserRole` 方法，或另建 `UserRoleMapper`。下面给出两种实现方式。

