package com.example.ratelimit;

import com.bucket4j.*;
import com.bucket4j.distributed.proxy.ProxyManager;
import com.bucket4j.redis.lettuce.cas.LettuceBasedProxyManager;
import io.lettuce.core.RedisClient;
import io.lettuce.core.api.StatefulRedisConnection;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.context.annotation.Bean;
import org.springframework.context.annotation.Configuration;

import java.time.Duration;
import java.util.function.Supplier;

@Configuration
public class RateLimitConfig {

    // ----- Redis client ----------------------------------------------------
    @Bean(destroyMethod = "shutdown")
    public RedisClient redisClient(@Value("${spring.redis.host}") String host,
                                   @Value("${spring.redis.port}") int port) {
        return RedisClient.create("redis://" + host + ":" + port);
    }

    @Bean(destroyMethod = "close")
    public StatefulRedisConnection<String, byte[]> redisConnection(RedisClient client) {
        // Lettuce connection that stores raw byte[] (Bucket4j needs binary)
        return client.connect(new io.lettuce.core.codec.StringCodec(),
                               new io.lettuce.core.codec.ByteArrayCodec());
    }

    // ----- Bucket4j ProxyManager ------------------------------------------------
    @Bean
    public ProxyManager<String> bucketProxyManager(StatefulRedisConnection<String, byte[]> connection) {
        // The manager serialises the BucketState as binary via Jackson (default)
        return LettuceBasedProxyManager.builderFor(connection).build();
    }

    // ----- Bucket configuration (shared for all keys) -------------------------
    @Bean
    public BucketConfiguration bucketConfiguration(
            @Value("${ratelimit.api.capacity}") long capacity,
            @Value("${ratelimit.api.refillTokens}") long refillTokens,
            @Value("${ratelimit.api.refillPeriod}") long refillPeriod,
            @Value("${ratelimit.api.refillUnit}") String refillUnit) {

        Refill refill = Refill.greedy(refillTokens,
                Duration.of(refillPeriod, java.time.temporal.ChronoUnit.valueOf(refillUnit)));
        Bandwidth limit = Bandwidth.classic(capacity, refill);
        return BucketConfiguration.builder()
                .addLimit(limit)
                .build();
    }

    // ----- Helper that returns a bucket for a given key (e.g., API key, IP) ----
    @Bean
    public BucketProvider bucketProvider(ProxyManager<String> proxyManager,
                                         BucketConfiguration bucketConfig) {
        return new BucketProvider(proxyManager, bucketConfig);
    }
}
```

### 4.3. `BucketProvider.java`

```java
package com.example.ratelimit;

import com.bucket4j.Bucket;
import com.bucket4j.distributed.proxy.ProxyManager;
import com.bucket4j.distributed.proxy.ProxyBucket;
import com.bucket4j.BucketConfiguration;

/**
 * Thin wrapper that creates (or fetches) a distributed bucket for a given key.
 *
 * The bucket state is stored in Redis under the key you provide.
 */
public class BucketProvider {

    private final ProxyManager<String> proxyManager;
    private final BucketConfiguration config;

    public BucketProvider(ProxyManager<String> proxyManager, BucketConfiguration config) {
        this.proxyManager = proxyManager;
        this.config = config;
    }

    /**
     * @param key any unique identifier (API‑key, user‑id, client‑IP)
     * @return a bucket bound to that key
     */
    public Bucket resolveBucket(String key) {
        // The proxy bucket is a thin wrapper around a remote bucket.
        // The first call will create the bucket in Redis with the supplied config.
        return proxyManager.builder()
                .withKey(key)
                .withConfiguration(config)
                .build()
                .asBucket(); // converts ProxyBucket → Bucket API
    }
}
```

