## 5. Intercepting incoming requests

You can use a **HandlerInterceptor**, a **Filter**, or Spring MVC’s **@ControllerAdvice**.  
Below we implement a **Spring `HandlerInterceptor`** that checks the token before the controller runs and adds classic `Rate-Limit-*` response headers.

### 5.1. `RateLimitInterceptor.java`

```java
package com.example.ratelimit;

import com.bucket4j.Bucket;
import com.bucket4j.BucketConfiguration;
import com.bucket4j.BucketState;
import jakarta.servlet.http.HttpServletRequest;
import jakarta.servlet.http.HttpServletResponse;
import org.springframework.http.HttpHeaders;
import org.springframework.stereotype.Component;
import org.springframework.web.servlet.HandlerInterceptor;

import java.time.Duration;
import java.util.concurrent.TimeUnit;

/**
 * Interceptor enforces a token‑bucket limit per API‑key (or IP if none provided).
 *
 * It adds the following HTTP headers:
 *   - X-Rate-Limit-Limit      : total capacity
 *   - X-Rate-Limit-Remaining  : tokens left after this request
 *   - X-Rate-Limit-Reset      : seconds until bucket is fully refilled
 *
 * If the request cannot consume a token → 429 Too Many Requests.
 */
@Component
public class RateLimitInterceptor implements HandlerInterceptor {

    private final BucketProvider bucketProvider;

    public RateLimitInterceptor(BucketProvider bucketProvider) {
        this.bucketProvider = bucketProvider;
    }

    /**
     * Helper: extracts a client identifier.
     * 1️⃣ If an Authorization header with an API‑key is present → use it.
     * 2️⃣ Fallback to the client IP (X‑Forwarded‑For -> remoteAddr).
     */
    private String resolveKey(HttpServletRequest request) {
        String auth = request.getHeader(HttpHeaders.AUTHORIZATION);
        if (auth != null && !auth.isBlank()) {
            // Expect "Bearer <api-key>" – we only need the key part.
            return auth.replaceFirst("(?i)Bearer\\s+", "").trim();
        }
        // Use IP (good enough for demo). In production you may combine IP+user‑id.
        String xf = request.getHeader("X-Forwarded-For");
        if (xf != null && !xf.isBlank()) {
            return xf.split(",")[0].trim(); // first address in chain
        }
        return request.getRemoteAddr();
    }

    @Override
    public boolean preHandle(HttpServletRequest request, HttpServletResponse response, Object handler) throws Exception {

        String key = resolveKey(request);
        Bucket bucket = bucketProvider.resolveBucket(key);

        // Try to consume a single token instantly (no wait)
        if (bucket.tryConsume(1)) {
            // Add useful headers for the client (optional, but standard)
            BucketState state = bucket.getAvailableTokens();
            response.setHeader("X-Rate-Limit-Limit", String.valueOf(state.getCapacity()));
            response.setHeader("X-Rate-Limit-Remaining", String.valueOf(state.getAvailableTokens()));
            // Approximate time to full refill (seconds)
            long nanosToFull = state.getNanosToFullRefill();
            response.setHeader("X-Rate-Limit-Reset", String.valueOf(TimeUnit.NANOSECONDS.toSeconds(nanosToFull)));
            return true; // proceed to controller
        } else {
            // Not enough tokens → 429
            response.setStatus(HttpServletResponse.SC_TOO_MANY_REQUESTS);
            response.getWriter().write("Too Many Requests - Rate limit exceeded");
            // Also expose headers showing the limit
            response.setHeader("Retry-After", "60"); // tell client to wait a minute (example)
            return false;
        }
    }
}
```

