import java.io.*;
import java.net.*;
import java.nio.ByteBuffer;
import java.util.concurrent.*;

public class LengthPrefixedClient {

    private final String host;
    private final int port;
    private final int readTimeoutMillis;   // 读取超时，防止僵尸连接

    public LengthPrefixedClient(String host, int port, int readTimeoutMillis) {
        this.host = host;
        this.port = port;
        this.readTimeoutMillis = readTimeoutMillis;
    }

    public void start() {
        try (Socket socket = new Socket()) {
            // 1️⃣ 关联目标并设置超时
            socket.connect(new InetSocketAddress(host, port), 5000); // 连接超时 5s
            socket.setSoTimeout(readTimeoutMillis); // 读取超时

            // 2️⃣ 获取流
            InputStream in = socket.getInputStream();
            OutputStream out = socket.getOutputStream();

            // 这里演示一个简单的请求/响应循环
            ExecutorService executor = Executors.newSingleThreadExecutor();
            executor.submit(() -> readLoop(in));
            // 写一个示例请求（长度前缀+payload）
            sendMessage(out, "HELLO SERVER".getBytes());

            // ... 业务代码可以继续写，例如周期发送心跳
            // 为演示，睡 10 秒后关闭
            Thread.sleep(10_000);
            executor.shutdownNow();

        } catch (IOException | InterruptedException e) {
            System.err.println("[ERROR] 通信异常: " + e.getMessage());
        }
    }

    /** 发送一条长度前缀消息 */
    private void sendMessage(OutputStream out, byte[] payload) throws IOException {
        // 4 字节大端长度前缀
        byte[] lenBytes = ByteBuffer.allocate(4).putInt(payload.length).array();
        out.write(lenBytes);
        out.write(payload);
        out.flush();
        System.out.println("[SEND] 已发送 " + payload.length + " 字节");
    }

    /** 持续读取，直到对端关闭或异常 */
    private void readLoop(InputStream in) {
        try {
            while (true) {
                // ① 读取长度（4 字节）
                byte[] lenBuf = readExact(in, 4);
                if (lenBuf == null) {
                    System.out.println("[INFO] 对端关闭连接");
                    break;
                }
                int payloadLen = ByteBuffer.wrap(lenBuf).getInt();

                // ② 防御：限制最大消息体（防止 OOM、DoS）
                final int MAX_PAYLOAD = 10 * 1024 * 1024; // 10 MB
                if (payloadLen < 0 || payloadLen > MAX_PAYLOAD) {
                    System.err.println("[SECURITY] 非法 payload 长度: " + payloadLen);
                    break; // 主动断开
                }

                // ③ 读取完整 payload
                byte[] payload = readExact(in, payloadLen);
                if (payload == null) {
                    System.out.println("[INFO] 对端意外关闭（在 payload 读取阶段）");
                    break;
                }

                // ④ 业务处理（这里简单打印）
                String msg = new String(payload, "UTF-8");
                System.out.println("[RECV] 长度=" + payloadLen + " 内容=" + msg);
            }
        } catch (SocketTimeoutException toe) {
            System.err.println("[TIMEOUT] 读取超时，认为对端不活跃，关闭连接");
        } catch (IOException e) {
            System.err.println("[ERROR] 读取异常: " + e.getMessage());
        }
    }

    /** 读取恰好 n 个字节，返回 null 表示流已提前关闭 */
    private byte[] readExact(InputStream in, int n) throws IOException {
        byte[] buf = new byte[n];
        int offset = 0;
        while (offset < n) {
            int read = in.read(buf, offset, n - offset);
            if (read == -1) {
                // 对端已关闭
                return null;
            }
            offset += read;
        }
        return buf;
    }

    public static void main(String[] args) {
        new LengthPrefixedClient("127.0.0.1", 9000, 15_000).start();
    }
