            // HashiCorp Vault, Azure Key Vault, etc.) you would pull them here instead.
            store.connect(imapHost, Integer.parseInt(imapPort), imapUser, imapPass);

            // -----------------------------------------------------------
            // 3️⃣  Open INBOX read‑only – we never modify server flags.
            // -----------------------------------------------------------
            try (Folder inbox = store.getFolder("INBOX")) {
                if (!inbox.exists()) {
                    throw new MessagingException("INBOX folder does not exist on server.");
                }
                inbox.open(Folder.READ_ONLY);

                // Fetch only UNSEEN messages to avoid re‑processing old mail.
                Message[] messages = inbox.search(new FlagTerm(new Flags(Flags.Flag.SEEN), false));

                System.out.println("Found " + messages.length + " unseen message(s).");

                // -------------------------------------------------------
                // 4️⃣  Process each message – extract subject & number.
                // -------------------------------------------------------
                for (Message msg : messages) {
                    processMessage(msg);
                }

                // Optionally mark them as SEEN after successful processing:
                // inbox.setFlags(messages, new Flags(Flags.Flag.SEEN), true);
            }
        }
    }

    /** Handles a single message: extracts the needed data and stores it. */
    private void processMessage(Message msg) throws MessagingException, IOException {
        // ----- Subject handling ------------------------------------------------
        String subject = msg.getSubject();
        if (subject == null) {
            subject = "(no subject)";
        }

        // Defensive: verify that the subject contains the word "number" (case‑insensitive)
        if (!subject.toLowerCase().contains("number")) {
            // You may decide to ignore this message – security researchers often
            // whitelist expected patterns before further parsing.
            System.out.println("Skipping message (subject does not contain 'number'): " + subject);
            return;
        }

        // ----- Body handling ----------------------------------------------------
        String bodyText = extractPlainText(msg);
        if (bodyText == null) {
            System.out.println("Skipping message (no plain‑text body): " + subject);
            return;
        }

        // ----- Number extraction ------------------------------------------------
        Matcher matcher = NUMBER_PATTERN.matcher(bodyText);
        if (!matcher.find()) {
            System.out.println("Skipping message (no 8‑digit number found): " + subject);
            return;
        }
        String number = matcher.group(); // first occurrence

        // ----- Store in the synchronized Hashtable -------------------------------
        // Keys are the exact subject strings; value is the extracted number.
        // Hashtable is synchronized; for higher concurrency use ConcurrentHashMap.
        subjectNumberMap.put(subject, number);
        System.out.println("Stored: [" + subject + "] → [" + number + "]");
    }

    /**
     * Extract the first plain‑text part of a possibly multipart message.
     * Returns {@code null} if no plain text can be found.
     */
    private String extractPlainText(Part part) throws MessagingException, IOException {
        if (part.isMimeType("text/plain")) {
            // Direct plain‑text message – simple case.
            return (String) part.getContent();
        }

        if (part.isMimeType("multipart/*")) {
            Multipart mp = (Multipart) part.getContent();
            // Walk through parts in order – stop at the first text/plain.
            for (int i = 0; i < mp.getCount(); i++) {
                BodyPart bp = mp.getBodyPart(i);
                String result = extractPlainText(bp);
                if (result != null) {
                    return result;
                }
            }
        }

        // Could also handle "text/html" → strip tags with a sanitizer if needed.
        // For security we avoid executing any embedded scripts or loading remote resources.
        return null;
    }

    /** Helper to dump the collected map (for demo only – avoid logging secrets). */
    private void printMap() {
        System.out.println("\n=== Collected Subject → Number Map ===");
        subjectNumberMap.forEach((k, v) -> System.out.println("Subject: \"" + k + "\"  |  Number: " + v));
    }

    // -------------------------------------------------------------------------
    // Getters (if other components need the map) – returns an unmodifiable view.
    // -------------------------------------------------------------------------
    public java.util.Map<String, String> getSubjectNumberMap() {
        return java.util.Collections.unmodifiableMap(subjectNumberMap);
    }
}
