## 5️⃣ 业务层（`handleClient`）示例

```java
package com.example.service;

import com.example.datasource.RoutingDataSource;
import lombok.extern.slf4j.Slf4j;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Service;

import java.net.Socket;
import java.sql.ResultSet;
import java.sql.SQLException;

@Service
@Slf4j
public class ClientHandlerService {

    private final JdbcTemplate jdbcTemplate; // 注入的是 RoutingDataSource 包装的 JdbcTemplate

    public ClientHandlerService(JdbcTemplate jdbcTemplate) {
        this.jdbcTemplate = jdbcTemplate;
    }

    /**
     * 对单个 socket 进行业务处理。
     * 1️⃣ 先根据 client IP 设定路由的 DataSource key
     * 2️⃣ 业务完成后一定要清理 ThreadLocal
     */
    public void handleClient(Socket socket) {
        String clientIp = socket.getInetAddress().getHostAddress();
        try {
            // ==== ① 根据 IP 选库 =====
            String dsKey = lookupDataSourceKey(clientIp);
            log.info("Client [{}] mapped to datasource [{}]", clientIp, dsKey);
            RoutingDataSource.setDataSourceKey(dsKey);

            // ==== ② 业务代码（示例：查询/写入）=====
            // 示例：假设业务协议是 “SELECT <table> WHERE id=<n>”
            // 这里仅演示一次查询，实际请使用自定义协议解析
            // 注意使用 ? 占位符防止 SQL 注入
            String sql = "SELECT name FROM device_data WHERE id = ?";
            Integer id = 1; // 这里只是示例
            String name = jdbcTemplate.queryForObject(sql, new Object[]{id}, String.class);
            log.info("查询结果: {}", name);

            // ==== ③ 发送结果回客户端 =====
            String response = "Result: " + name + "\n";
            socket.getOutputStream().write(response.getBytes());

        } catch (Exception e) {
            log.error("Error handling client {}: {}", clientIp, e.getMessage(), e);
            // 给客户端一个错误提示（可选）
            try {
                socket.getOutputStream().write(("ERROR: " + e.getMessage() + "\n").getBytes());
            } catch (Exception ignored) {}
        } finally {
            // ==== ④ 清理 ThreadLocal，防止线程池复用导致错库 ====
            RoutingDataSource.clearDataSourceKey();

            // ==== ⑤ 关闭 socket （防止泄漏） ====
            try {
                socket.close();
            } catch (Exception ignored) {}
        }
    }

    /** 简单映射表：IP → DataSource key，实际可读取自配置文件或数据库 */
    private String lookupDataSourceKey(String ip) {
        // 这里直接硬编码演示，实际请使用 @ConfigurationProperties 注入
        switch (ip) {
            case "192.168.1.10":
                return "dev-db";
            case "192.168.1.20":
                return "test-db";
            default:
                return "prod-db"; // default
        }
    }
}
```

