import java.net.ServerSocket;
import java.net.Socket;
import java.util.concurrent.*;

@Component
@Slf4j
public class SocketServer implements ApplicationRunner {

    /** 端口号（硬编码 9000，或通过 @Value 注入） */
    private static final int LISTEN_PORT = 9000;

    /** 线程池，核心数=CPU 数，最大数=CPU*2，队列长度自行调节 */
    private final ExecutorService executor = new ThreadPoolExecutor(
            Runtime.getRuntime().availableProcessors(),
            Runtime.getRuntime().availableProcessors() * 2,
            60L, TimeUnit.SECONDS,
            new LinkedBlockingQueue<>(500),
            new ThreadFactory() {
                private final AtomicInteger idx = new AtomicInteger(0);
                @Override
                public Thread newThread(Runnable r) {
                    Thread t = new Thread(r, "socket-worker-" + idx.incrementAndGet());
                    t.setDaemon(true);
                    return t;
                }
            },
            new ThreadPoolExecutor.CallerRunsPolicy());

    private final ClientHandlerService clientHandlerService;

    public SocketServer(ClientHandlerService clientHandlerService) {
        this.clientHandlerService = clientHandlerService;
    }

    @Override
    public void run(ApplicationArguments args) throws Exception {
        // ==== ① 创建 TLS ServerSocket (强烈建议) ====
        // 如果不需要 TLS，可直接 new ServerSocket(LISTEN_PORT)
        ServerSocket serverSocket = createSecureServerSocket(LISTEN_PORT);
        log.info("Secure socket server listening on port {}", LISTEN_PORT);

        // ==== ② 主循环：接受连接并交给线程池处理 ====
        while (!Thread.currentThread().isInterrupted()) {
            try {
                Socket socket = serverSocket.accept();
                log.info("New client connected from {}", socket.getInetAddress());

                // 将每一次连接的业务委托给线程池
                executor.submit(() -> clientHandlerService.handleClient(socket));
            } catch (IOException e) {
                log.error("Accept failed: {}", e.getMessage(), e);
                // 如果是因为 socket 被关闭，则退出循环
                if (serverSocket.isClosed()) break;
            }
        }

        // ==== ③ 关闭资源（在容器关闭时调用） ====
        shutdown(serverSocket);
    }

    /** 创建支持 TLS 的 ServerSocket（使用 JDK 默认的 TLS/SSL 实现） */
    private ServerSocket createSecureServerSocket(int port) throws IOException {
        // 这里使用 JDK 自带的默认密钥库，实际请使用自己的 keystore（.p12/.jks）
        // 示例：System.setProperty("javax.net.ssl.keyStore", "classpath:server-keystore.p12");
        // 示例：System.setProperty("javax.net.ssl.keyStorePassword", "changeit");
        SSLServerSocketFactory factory = (SSLServerSocketFactory) SSLServerSocketFactory.getDefault();
        return factory.createServerSocket(port);
    }

    /** 优雅关闭 */
    private void shutdown(ServerSocket serverSocket) {
        try {
            serverSocket.close();
        } catch (IOException ignored) {}
        executor.shutdown();
        try {
            if (!executor.awaitTermination(30, TimeUnit.SECONDS)) {
                executor.shutdownNow();
            }
        } catch (InterruptedException ignored) {}
        log.info("Socket server stopped.");
    }
}
