public class InterfaceEnforcementPostProcessor
        implements BeanDefinitionRegistryPostProcessor, PriorityOrdered {

    /** 目标接口：只有实现此接口的类才被允许 */
    private final Class<?> requiredInterface;

    /** （可选）黑名单接口集合：如果实现任意一个则直接拒绝 */
    private final Set<Class<?>> prohibitedInterfaces = new HashSet<>();

    public InterfaceEnforcementPostProcessor(Class<?> requiredInterface) {
        this.requiredInterface = requiredInterface;
    }

    /** 通过 addProhibited(...) 可以动态加入黑名单 */
    public void addProhibited(Class<?> iface) {
        prohibitedInterfaces.add(iface);
    }

    /** ---------- 入口点：BeanDefinitionRegistry ---------- */
    @Override
    public void postProcessBeanDefinitionRegistry(BeanDefinitionRegistry registry) throws BeansException {
        // 取得容器默认的 ClassLoader（Spring 用于加载 bean 类）
        ClassLoader beanClassLoader = determineClassLoader(registry);

        for (String beanName : registry.getBeanDefinitionNames()) {
            BeanDefinition bd = registry.getBeanDefinition(beanName);

            try {
                Class<?> candidateClass = resolveBeanClass(bd, beanClassLoader);
                if (candidateClass == null) {
                    // 可能是 FactoryBean 或 factory‑method，后置检查会在实例化时再次校验
                    continue;
                }

                // ① 代理类：获取真实的目标类（CGLIB/JDK代理会生成子类）
                Class<?> realClass = AopUtils.getTargetClass(candidateClass);

                // ② 检查必须实现的接口
                if (!requiredInterface.isAssignableFrom(realClass)) {
                    throw new IllegalStateException(String.format(
                            "Bean '%s' (%s) does NOT implement required interface %s",
                            beanName, realClass.getName(), requiredInterface.getName()));
                }

                // ③ 检查黑名单接口（如 java.io.Serializable、java.rmi.Remote 等）
                for (Class<?> prohibited : prohibitedInterfaces) {
                    if (prohibited.isAssignableFrom(realClass)) {
                        throw new IllegalStateException(String.format(
                                "Bean '%s' (%s) implements prohibited interface %s",
                                beanName, realClass.getName(), prohibited.getName()));
                    }
                }

            } catch (ClassNotFoundException | LinkageError ex) {
                // 类不存在或加载错误 → 视为风险，直接抛异常终止容器启动
                throw new IllegalStateException("Unable to resolve class for bean '" + beanName + "'", ex);
            }
        }
    }

    /** ---------- 该方法在后置处理阶段不需要实现 ---------- */
    @Override
    public void postProcessBeanFactory(ConfigurableListableBeanFactory beanFactory) throws BeansException {
        // No‑op – All checks already done in the registry phase.
    }

    /** ---------- 辅助方法 ---------- */

    /**
     * 根据 BeanDefinition 解析出实际的 Class 对象（不触发静态初始化）。
     * 支持普通类、FactoryBean、factory‑method 三种情况。
     */
    private Class<?> resolveBeanClass(BeanDefinition bd, ClassLoader classLoader)
            throws ClassNotFoundException {

        // 1️⃣ 普通 bean：直接使用 beanClassName
        String className = bd.getBeanClassName();
        if (className != null) {
            return Class.forName(className, false, classLoader);
        }

        // 2️⃣ FactoryBean：如果 BeanDefinition 实现了 FactoryBean 接口
