import java.net.*;

public class BlockingServer {
    // 业务端口
    private static final int PORT = 8888;
    // 单个连接最大读取时间（毫秒），0 表示永不超时（极易导致 DoS）
    private static final int SO_TIMEOUT = 30_000; // 30 秒

    public static void main(String[] args) throws IOException {
        ServerSocket server = new ServerSocket();
        // 绑定到指定端口，使用默认 backlog
        server.bind(new InetSocketAddress(PORT));
        System.out.println("[+] Server listening on " + PORT);

        while (true) {
            Socket client = null;
            try {
                // 1. accept() 会阻塞，直到有客户端发起 TCP 三次握手完成
                client = server.accept();
                System.out.println("[+] Accepted connection from " + client.getRemoteSocketAddress());

                // 2. 设置读取超时，防止单个客户端长时间占用线程
                client.setSoTimeout(SO_TIMEOUT);

                // 3. 进入业务处理（阻塞读取）
                handleClient(client);
            } catch (SocketTimeoutException e) {
                // 读取超时，一般不需要特殊处理，关闭连接即可
                System.err.println("[-] Read timeout: " + e.getMessage());
            } catch (IOException e) {
                System.err.println("[-] IO error: " + e);
            } finally {
                if (client != null && !client.isClosed()) {
                    client.close();
                }
            }
        }
    }

    private static void handleClient(Socket client) throws IOException {
        // 获取阻塞的 InputStream
        InputStream in = client.getInputStream();
        OutputStream out = client.getOutputStream();

        // 简单的回显协议（读取一行，原样返回）
        BufferedReader br = new BufferedReader(new InputStreamReader(in, "UTF-8"));
        BufferedWriter bw = new BufferedWriter(new OutputStreamWriter(out, "UTF-8"));

        String line;
        while ((line = br.readLine()) != null) {   // 这里是阻塞读取
            System.out.println("[*] Received: " + line);
            bw.write("Echo: " + line);
            bw.newLine();
            bw.flush();

            // 可根据业务自行决定何时 break，防止无限循环
            if ("quit".equalsIgnoreCase(line.trim())) {
                break;
            }
        }
    }
}
```

#### 关键点解释  

| 步骤 | 说明 | 安全意义 |
|------|------|----------|
| `server.accept()` | **阻塞**，直到有客户端连接。 | 防止空轮询，CPU 使用率低。 |
| `client.setSoTimeout(ms)` | 读取超时，`InputStream.read()` 超时会抛 `SocketTimeoutException`。 | 防止单个恶意客户端占用线程导致 **DoS**。 |
| `br.readLine()` | **阻塞**，读取完整一行（`\n` 或 `\r\n`）。 | 如未设超时，恶意客户端可以发送无限大的数据包导致内存占满。 |
| `if ("quit".equalsIgnoreCase(...))` | 主动退出循环，释放资源。 | 防止“无限阻塞”导致资源泄漏。 |

