            try {
                if (!executor.awaitTermination(5, TimeUnit.SECONDS)) {
                    LOG.warning("Thread pool did not terminate cleanly");
                }
            } catch (InterruptedException ignored) {
                Thread.currentThread().interrupt();
            }
        }

