## 8️⃣ JWT 工具类 (`JwtUtil.java`)

```java
package com.example.authdemo.security;

import io.jsonwebtoken.*;
import io.jsonwebtoken.security.Keys;
import jakarta.annotation.PostConstruct;
import lombok.extern.slf4j.Slf4j;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.stereotype.Component;

import java.security.Key;
import java.util.Date;

/**
 * 简化的 JWT 生成 / 校验工具。生产环境可考虑增加 JTI、Audience、Issuer 等字段。
 */
@Slf4j
@Component
public class JwtUtil {

    @Value("${jwt.secret}")
    private String secretKey;

    @Value("${jwt.expirationMs}")
    private long jwtExpirationMs;

    @Value("${jwt.header}")
    private String header;

    @Value("${jwt.tokenPrefix}")
    private String tokenPrefix;

    private Key key;

    @PostConstruct
    public void init() {
        // 建议使用 Base64 编码的密钥，这里直接使用原始字符串
        this.key = Keys.hmacShaKeyFor(secretKey.getBytes());
    }

    /** 生成 token，subject 为用户名 */
    public String generateToken(String username) {
        Date now = new Date();
        Date expiry = new Date(now.getTime() + jwtExpirationMs);
        return Jwts.builder()
                .setSubject(username)
                .setIssuedAt(now)
                .setExpiration(expiry)
                // .setId(UUID.randomUUID().toString()) // 可选：用于黑名单
                .signWith(key, SignatureAlgorithm.HS256)
                .compact();
    }

    /** 从请求头里提取 token （不含 Bearer 前缀） */
    public String resolveToken(String bearerToken) {
        if (bearerToken != null && bearerToken.startsWith(tokenPrefix + " ")) {
            return bearerToken.substring((tokenPrefix + " ").length());
        }
        return null;
    }

    /** 校验 token 是否合法且未过期 */
    public boolean validateToken(String token) {
        try {
            Jwts.parserBuilder().setSigningKey(key).build().parseClaimsJws(token);
            return true;
        } catch (ExpiredJwtException e) {
            log.warn("JWT expired: {}", e.getMessage());
        } catch (JwtException e) { // 包括 SignatureException、MalformedJwtException 等
            log.warn("Invalid JWT: {}", e.getMessage());
        }
        return false;
    }

    /** 解析 token，返回用户名 */
    public String getUsernameFromToken(String token) {
        Claims claims = Jwts.parserBuilder()
                .setSigningKey(key).build()
                .parseClaimsJws(token)
                .getBody();
        return claims.getSubject();
    }

    public String getHeader() {
        return header;
    }

    public String getTokenPrefix() {
        return tokenPrefix;
    }
}
```

