## 9️⃣ Spring Security 配置 (`SecurityConfig.java`)

```java
package com.example.authdemo.config;

import com.example.authdemo.security.JwtAuthenticationFilter;
import com.example.authdemo.security.JwtUtil;
import lombok.RequiredArgsConstructor;
import org.springframework.context.annotation.Bean;
import org.springframework.context.annotation.Configuration;
import org.springframework.http.HttpMethod;
import org.springframework.security.authentication.AuthenticationManager;
import org.springframework.security.authentication.dao.DaoAuthenticationProvider;
import org.springframework.security.config.Customizer;
import org.springframework.security.config.annotation.authentication.configuration.AuthenticationConfiguration;
import org.springframework.security.config.annotation.method.configuration.EnableMethodSecurity;
import org.springframework.security.config.http.SessionCreationPolicy;
import org.springframework.security.core.userdetails.*;
import org.springframework.security.crypto.bcrypt.BCryptPasswordEncoder;
import org.springframework.security.crypto.password.PasswordEncoder;
import org.springframework.security.web.*;
import org.springframework.security.web.authentication.UsernamePasswordAuthenticationFilter;
import org.springframework.security.web.util.matcher.*;

@Configuration
@EnableMethodSecurity
@RequiredArgsConstructor
public class SecurityConfig {

    private final JwtUtil jwtUtil;
    private final UserDetailsService userDetailsService; // 自动注入下面的 bean

    /** 1. PasswordEncoder (BCrypt) */
    @Bean
    public PasswordEncoder passwordEncoder() {
        return new BCryptPasswordEncoder();
    }

    /** 2. DAO Provider 关联 UserDetailsService & PasswordEncoder */
    @Bean
    public DaoAuthenticationProvider authenticationProvider() {
        DaoAuthenticationProvider provider = new DaoAuthenticationProvider();
        provider.setUserDetailsService(userDetailsService);
        provider.setPasswordEncoder(passwordEncoder());
        return provider;
    }

    /** 3. AuthenticationManager（用于手工认证） */
    @Bean
    public AuthenticationManager authenticationManager(AuthenticationConfiguration cfg) throws Exception {
        return cfg.getAuthenticationManager();
    }

    /** 4. 将 JWTFilter 插入过滤链 */
    @Bean
    public SecurityFilterChain filterChain(HttpSecurity http) throws Exception {
        JwtAuthenticationFilter jwtFilter = new JwtAuthenticationFilter(jwtUtil, userDetailsService);

        http
            // ① 关闭 CSRF，因为我们使用 stateless token
            .csrf(csrf -> csrf.disable())
            // ② 无状态 Session
            .sessionManagement(sm -> sm.sessionCreationPolicy(SessionCreationPolicy.STATELESS))
            // ③ 统一异常处理（可以根据需求自定义）
            .exceptionHandling(ex -> ex
                .authenticationEntryPoint((req, rsp, e) -> {
                    rsp.sendError(401, "Unauthorized: " + e.getMessage());
                })
                .accessDeniedHandler((req, rsp, e) -> {
                    rsp.sendError(403, "Forbidden: " + e.getMessage());
                })
            )
            // ④ 授权路由
            .authorizeHttpRequests(auth -> auth
                // 公开接口
                .requestMatchers(HttpMethod.POST, "/api/auth/register").permitAll()
                .requestMatchers(HttpMethod.POST, "/api/auth/login").permitAll()
                // 退出接口：只要已登录即可调用（后端实现 token 黑名单可选）
                .requestMatchers(HttpMethod.POST, "/api/auth/logout").authenticated()
                // 其他所有请求需要认证
                .anyRequest().authenticated()
            )
            // ⑤ 添加 JWT Filter
            .addFilterBefore(jwtFilter, UsernamePasswordAuthenticationFilter.class);

        return http.build();
    }

    /** 6. UserDetailsService（从 DB 查询用户） */
    @Bean
    public UserDetailsService userDetailsService(UserDetailsRepository repo) {
        return username -> repo.findByUsername(username)
                .map(user -> User.builder()
                        .username(user.getUsername())
                        .password(user.getPassword())
                        .roles(user.getRole().replace("ROLE_", "")) // Spring Security expects roles without prefix
                        .build())
                .orElseThrow(() -> new UsernameNotFoundException("User not found"));
    }
}
```

> **说明**  
> - `UserDetailsRepository` 需要自己实现或直接使用 `UserRepository`（这里我额外写了一个接口），示例中 `UserDetailsService` 通过包装 `User` 为 `org.springframework.security.core.userdetails.User`。
> - `JwtAuthenticationFilter` 会在每个请求里解析 `Authorization: Bearer xxx`，并把 `Authentication` 放入 `SecurityContext`。

