## 4️⃣  Java Implementation (JCE)

```java
import javax.crypto.Cipher;
import javax.crypto.KeyGenerator;
import javax.crypto.SecretKey;
import javax.crypto.spec.GCMParameterSpec;
import java.security.SecureRandom;
import java.util.Arrays;

public class NfcEncryptor {

    private static final int AES_KEY_SIZE = 128;          // bits
    private static final int GCM_TAG_LENGTH = 128;        // bits
    private static final int GCM_IV_LENGTH = 12;          // bytes

    /**
     * Encrypts the supplied plain text using AES‑GCM.
     *
     * @param plaintext UTF‑8 string to encrypt
     * @param key       SecretKey (AES)
     * @return byte[] payload = IV || ciphertext || tag
     */
    public static byte[] encryptForNfc(String plaintext, SecretKey key) throws Exception {
        // 1️⃣  Prepare cipher
        Cipher cipher = Cipher.getInstance("AES/GCM/NoPadding");

        // 2️⃣  Generate a fresh 12‑byte nonce (IV)
        byte[] iv = new byte[GCM_IV_LENGTH];
        SecureRandom random = SecureRandom.getInstanceStrong();
        random.nextBytes(iv);

        // 3️⃣  Initialise cipher in ENCRYPT mode
        GCMParameterSpec spec = new GCMParameterSpec(GCM_TAG_LENGTH, iv);
        cipher.init(Cipher.ENCRYPT_MODE, key, spec);

        // 4️⃣  Encrypt
        byte[] plaintextBytes = plaintext.getBytes(java.nio.charset.StandardCharsets.UTF_8);
        byte[] cipherTextWithTag = cipher.doFinal(plaintextBytes); // automatically appends tag

        // 5️⃣  Assemble payload: IV || ciphertext || tag
        byte[] result = new byte[iv.length + cipherTextWithTag.length];
        System.arraycopy(iv, 0, result, 0, iv.length);
        System.arraycopy(cipherTextWithTag, 0, result, iv.length, cipherTextWithTag.length);
        return result;
    }

    /* -------------------------------------------------------------
       Demo / test harness – NOT for production key handling!
    ------------------------------------------------------------- */
    public static void main(String[] args) throws Exception {
        String plain = "A0123456|99999|XYZ";

        // Generate a random 128‑bit key (store it securely!)
        KeyGenerator keyGen = KeyGenerator.getInstance("AES");
        keyGen.init(AES_KEY_SIZE);
        SecretKey key = keyGen.generateKey();

        byte[] payload = encryptForNfc(plain, key);
        System.out.println("Payload length: " + payload.length + " bytes");

        // Debug: print hex representation
        System.out.println("Hex: " + bytesToHex(payload));
    }

    /** Helper to pretty‑print a byte array as hex */
    private static String bytesToHex(byte[] bytes) {
        StringBuilder sb = new StringBuilder();
        for (byte b : bytes) {
            sb.append(String.format("%02x", b));
        }
        return sb.toString();
    }
}
```

### What you see when you run it

```
Payload length: 48 bytes
Hex: <12‑byte IV><20‑byte ciphertext><16‑byte tag>
```

Again, **48 bytes** is far under the 136‑byte limit.

