### 9️⃣ 业务层：认证服务 `src/services/authService.ts`

```ts
import { getRepository } from 'typeorm';
import { User } from '../models/User';
import { LoginLog } from '../models/LoginLog';
import bcrypt from 'bcryptjs';
import jwt from 'jsonwebtoken';
import {
  JWT_ACCESS_SECRET,
  JWT_REFRESH_SECRET,
  ACCESS_TOKEN_EXPIRES_IN,
  REFRESH_TOKEN_EXPIRES_IN,
} from '../config/secret';
import { Request } from 'express';
import { v4 as uuidv4 } from 'uuid';
import { redis, setWithTTL } from '../utils/redisClient';
import { logger } from '../utils/logger';

interface TokenPair {
  accessToken: string;
  refreshToken: string;
}

/**
 * 生成 JWT（access & refresh）
 * - access: short‑lived, put in Authorization: Bearer <token>
 * - refresh: httpOnly cookie, longer, used to re‑issue access
 */
function generateTokens(user: User, deviceId?: string): TokenPair {
  const jti = uuidv4(); // token identifier for revocation

  const payload = {
    sub: user.id,
    email: user.email,
    jti,
    // 可加入 deviceId、role、权限列表等
    ...(deviceId && { deviceId }),
  };

  const accessToken = jwt.sign(payload, JWT_ACCESS_SECRET, {
    expiresIn: ACCESS_TOKEN_EXPIRES_IN,
  });

  const refreshToken = jwt.sign(
    {
      ...payload,
      // refresh token 标记不同的用途（可自行添加 claim）
    },
    JWT_REFRESH_SECRET,
    { expiresIn: REFRESH_TOKEN_EXPIRES_IN }
  );

  // 将 refresh jti 暂存到 Redis（用于主动撤销）
  redis.set(`refresh_jti:${jti}`, 'valid', 'EX', 7 * 24 * 60 * 60); // 7d

  return { accessToken, refreshToken };
}

/**
 * 记录登录日志（审计）
 */
async function logLogin(
  userId: string | null,
  email: string,
  ip: string,
  ua: string,
  success: boolean
) {
  const repo = getRepository(LoginLog);
  await repo.save({
    userId,
    email,
    ip,
    userAgent: ua,
    success,
  });
}

/**
 * 检查用户是否被锁定（暴力攻击防护）
 */
async function isUserLocked(user: User): Promise<boolean> {
  if (!user.isLocked) return false;
  if (user.lockUntil && user.lockUntil > new Date()) return true;
  // lock expiration → 解锁
  user.isLocked = false;
  user.lockUntil = null;
  await getRepository(User).save(user);
  return false;
}

/**
 * 记录一次失败尝试并在超过阈值后锁定账号
 */
async function recordFailedAttempt(user: User, ip: string) {
  const key = `fail_login:${user.id}`;
  const attempts = await redis.incr(key);
  if (attempts === 1) {
    // 第一次失败，设置 ttl 为 LOCK_TIME_MINUTES
    await redis.expire(key, LOCK_TIME_MINUTES * 60);
  }
  if (attempts >= MAX_LOGIN_ATTEMPTS) {
    user.isLocked = true;
    user.lockUntil = new Date(Date.now() + LOCK_TIME_MINUTES * 60 * 1000);
    await getRepository(User).save(user);
    logger.warn(`User ${user.email} locked due to too many failed logins from IP ${ip}`);
  }
}

/**
 * 登录主流程
 */
export async function login(
  req: Request,
  email: string,
  password: string,
  mfaCode?: string,
  deviceId?: string
) {
  const userRepo = getRepository(User);
  const user = await userRepo.findOne({ where: { email } });

  // ★ 防止用户枚举：即使不存在也执行一次 bcrypt.hash 比较耗时，统一返回错误
  if (!user) {
    // 模拟密码校验耗时
    await bcrypt.compare(password, await bcrypt.hash(password, BCRYPT_SALT_ROUNDS));
    await logLogin(null, email, req.ip, req.get('User-Agent') || '', false);
    throw new Error('Invalid credentials');
  }

  if (await isUserLocked(user)) {
    await logLogin(user.id, email, req.ip, req.get('User-Agent') || '', false);
    throw new Error('Account locked. Try later.');
  }

  const passwordMatch = await bcrypt.compare(password, user.passwordHash);
  if (!passwordMatch) {
    await recordFailedAttempt(user, req.ip);
    await logLogin(user.id, email, req.ip, req.get('User-Agent') || '', false);
    throw new Error('Invalid credentials');
  }

  // ---- 如果开启 MFA ----
  if (user.mfaEnabled) {
    if (!mfaCode) {
      // 第一次请求返回需要 MFA 标记
      return { requireMfa: true };
    }
    const storedCode = await redis.get(`mfa:${user.id}`);
    if (!storedCode || storedCode !== mfaCode) {
      await logLogin(user.id, email, req.ip, req.get('User-Agent') || '', false);
      throw new Error('Invalid MFA code');
    }
    // 验证成功后删除一次性码
    await redis.del(`mfa:${user.id}`);
  }

  // 登录成功 → 清除失败计数
  await redis.del(`fail_login:${user.id}`);

  // 生成 JWT
  const { accessToken, refreshToken } = generateTokens(user, deviceId);

  // 记录审计日志
  await logLogin(user.id, email, req.ip, req.get('User-Agent') || '', true);

  return {
    requireMfa: false,
    tokens: {
      accessToken,
      // 刷新令牌会放进 HttpOnly Cookie，由路由统一写入响应
    },
  };
}

/**
 * 刷新 Access Token（使用 Refresh Token）
 */
export async function refreshAccessToken(refreshToken: string) {
  try {
    const payload = jwt.verify(refreshToken, JWT_REFRESH_SECRET) as any;
    // 检查 jti 是否已撤销
    const exists = await redis.get(`refresh_jti:${payload.jti}`);
    if (!exists) throw new Error('Token revoked');

    const userRepo = getRepository(User);
    const user = await userRepo.findOne(payload.sub);
    if (!user) throw new Error('User not found');

    // 新的 Access Token
    const newAccess = jwt.sign(
      {
        sub: user.id,
        email: user.email,
        jti: payload.jti,
        ...(payload.deviceId && { deviceId: payload.deviceId }),
      },
      JWT_ACCESS_SECRET,
      { expiresIn: ACCESS_TOKEN_EXPIRES_IN }
    );

    return newAccess;
  } catch (e) {
    logger.warn('Refresh token invalid: ', e);
    throw new Error('Invalid refresh token');
  }
}

/**
 * 主动撤销（退出登录） → 移除 refresh_jti
 */
export async function revokeRefreshToken(jti: string) {
  await redis.del(`refresh_jti:${jti}`);
}
```

### 10️⃣ 路由层 `src/routes/auth.ts`

```ts
import { Router, Request, Response, NextFunction } from 'express';
import { login, refreshAccessToken, revokeRefreshToken } from '../services/authService';
import { loginValidator, loginRateLimiter } from '../middlewares/validation';
import { loginValidator as validatorArray } from '../middlewares/validation';
import { logger } from '../utils/logger';
import { v4 as uuidv4 } from 'uuid';

const router = Router();

/**
 * POST /api/v1/auth/login
 *  - 支持普通登录 + MFA（一次性验证码）
 *  - 成功后返回 access token (JSON) + 设置 httpOnly refresh token cookie
 */
router.post(
  '/login',
  loginRateLimiter,
  validatorArray,
  async (req: Request, res: Response, next: NextFunction) => {
    const { email, password, mfaCode, deviceId } = req.body;
    try {
      const result = await login(req, email, password, mfaCode, deviceId);
      if (result.requireMfa) {
        // 前端收到该标记后会弹出 MFA 输入框再重新调用 /login（携带 mfaCode）
        return res.status(202).json({ requireMfa: true, message: 'MFA required' });
      }

      // 写入 Refresh Token Cookie
      const refreshToken = result.tokens.refreshToken;
      res.cookie('refresh_token', refreshToken, {
        httpOnly: true,
        secure: true,            // 仅在 HTTPS 下发送
        sameSite: 'strict',      // 防 CSRF
        path: '/api/v1/auth',    // 只在 auth 路径携带
        maxAge: 7 * 24 * 60 * 60 * 1000, // 与 refresh token ttl 对齐
      });

      // 返回 Access Token
      res.json({
        accessToken: result.tokens.accessToken,
        tokenType: 'Bearer',
        expiresIn: 15 * 60, // 15 分钟（秒）
      });
    } catch (err: any) {
      logger.warn(`Login failed for ${email}: ${err.message}`);
      // 统一错误码，防止信息泄露
      res.status(401).json({ code: 401, message: 'Invalid credentials' });
    }
  }
);

/**
 * POST /api/v1/auth/refresh
 *  - 使用 HttpOnly Refresh Token 重新签发 Access Token
 */
router.post('/refresh', async (req: Request, res: Response) => {
  const refreshToken = req.cookies?.refresh_token;
  if (!refreshToken) {
    return res.status(401).json({ code: 401, message: 'No refresh token' });
  }
  try {
    const newAccess = await refreshAccessToken(refreshToken);
    res.json({ accessToken: newAccess, tokenType: 'Bearer', expiresIn: 15 * 60 });
  } catch (e) {
    res.clearCookie('refresh_token', { httpOnly: true, secure: true, sameSite: 'strict' });
    res.status(401).json({ code: 401, message: 'Refresh token invalid' });
  }
});

/**
 * POST /api/v1/auth/logout
 *  - 清除 Refresh Token Cookie 并撤销服务器端 jti
 */
router.post('/logout', async (req: Request, res: Response) => {
  const refreshToken = req.cookies?.refresh_token;
  if (refreshToken) {
    try {
      const payload: any = jwt.verify(refreshToken, JWT_REFRESH_SECRET);
      await revokeRefreshToken(payload.jti);
    } catch (_) {
      // ignore verification errors
    }
  }
  res.clearCookie('refresh_token', { httpOnly: true, secure: true, sameSite: 'strict' });
  res.json({ message: 'Logged out' });
});

export default router;
```

