(async () => {
  // 1️⃣ 连接数据库
  await createConnection({
    type: 'postgres',
    host: process.env.DB_HOST || 'localhost',
    port: Number(process.env.DB_PORT) || 5432,
    username: process.env.DB_USER,
    password: process.env.DB_PASS,
    database: process.env.DB_NAME,
    entities: [__dirname + '/models/*.ts'],
    synchronize: true, // 生产请改为 migration
    logging: false,
  });

  // 2️⃣ 初始化 Express
  const app = express();

  // 3️⃣ 安全中间件
  app.use(helmet()); // 启用 CSP、X‑Frame‑Options 等
  app.use(cors({
    origin: process.env.CORS_ORIGIN?.split(',') || 'https://your-frontend.com',
    credentials: true, // 允许发送 Cookie
  }));
  app.use(express.json({ limit: '1mb' }));
  app.use(cookieParser());
  app.use(morgan('combined', { stream: { write: (msg) => logger.info(msg.trim()) } }));

  // 4️⃣ 路由挂载
  app.use('/api/v1/auth', authRouter);

  // 5️⃣ 统一错误处理（避免 stack 泄漏）
  app.use((err: any, req: express.Request, res: express.Response, next: express.NextFunction) => {
    logger.error(`Unhandled error: ${err.stack}`);
    res.status(500).json({ code: 500, message: 'Internal Server Error' });
  });

  const PORT = process.env.PORT || 3000;
  app.listen(PORT, () => {
    logger.info(`🚀 Auth service listening on http://0.0.0.0:${PORT}`);
