import java.io.*;
import java.nio.file.*;

public class AdminFile {

    private static final String ADMIN_FILE = "admin.txt";
    /** default password = "admin" (hash will be stored) */
    private static final String DEFAULT_PASSWORD = "admin";

    /** Returns the SHA‑256 hash that is stored in admin.txt.  
     *  If the file does not exist it is created with the default password. */
    public static String loadAdminHash() {
        try {
            if (!Files.exists(Paths.get(ADMIN_FILE))) {
                // create file with default password hash
                String hash = Utility.getHash(DEFAULT_PASSWORD);
                Files.write(Paths.get(ADMIN_FILE), hash.getBytes());
                return hash;
            }
            // read the whole file (it contains only the hash)
            String stored = new String(Files.readAllBytes(Paths.get(ADMIN_FILE))).trim();
            if (stored.isEmpty()) {
                // corrupt file – re‑initialise with default password
                String hash = Utility.getHash(DEFAULT_PASSWORD);
                Files.write(Paths.get(ADMIN_FILE), hash.getBytes());
                return hash;
            }
            return stored;
        } catch (IOException e) {
            throw new RuntimeException("Cannot read admin file", e);
        }
    }

    /** Overwrites admin.txt with a new SHA‑256 hash */
    public static void saveAdminHash(String newHash) {
        try {
