## 4. AdminModule – all admin actions + proper login / password change

```java
import java.io.*;
import java.util.*;

public class AdminModule {

    private static final String PLAYERS_FILENAME = "players.bin";

    private List<Player> players = new ArrayList<>();

    /** Load players from the binary file – if the file does not exist we start with an empty list */
    @SuppressWarnings("unchecked")
    private void loadPlayers() {
        File f = new File(PLAYERS_FILENAME);
        if (!f.exists()) {
            System.out.println("[INFO] No player file found – starting with an empty list.");
            return;
        }
        try (ObjectInputStream ois = new ObjectInputStream(new FileInputStream(f))) {
            while (true) {
                try {
                    Player p = (Player) ois.readObject();
                    players.add(p);
                } catch (EOFException eof) {
                    break;
                }
            }
        } catch (Exception e) {
            System.out.println("[ERROR] Could not load players: " + e.getMessage());
        }
        System.out.println("[INFO] Loaded " + players.size() + " player(s).");
    }

    /** Persist the whole list (overwrite) */
    private void savePlayers() {
        try (ObjectOutputStream oos = new ObjectOutputStream(new FileOutputStream(PLAYERS_FILENAME))) {
            for (Player p : players) oos.writeObject(p);
        } catch (IOException e) {
            System.out.println("[ERROR] Could not save players: " + e.getMessage());
        }
    }

    /** ---------------------- ADMIN LOGIN ---------------------- */
    private void adminLogin() {
        System.out.println("=== ADMIN LOGIN ===");
        String storedHash = AdminFile.loadAdminHash();   // read the hash from admin.txt

        while (true) {
            String password = Keyboard.readString("Enter admin password: ");
            String enteredHash = Utility.getHash(password);
            if (storedHash.equals(enteredHash)) {
                System.out.println("Welcome, admin!");
                return;                     // success
            }
            System.out.println("Incorrect password – try again.");
        }
    }

    /* ---------- ADMIN MENU ---------- */
    private void adminMenu() {
        String[] menu = {
                "Create a player",
                "Delete a player",
                "View all players",
                "Issue chips to a player",
                "Reset a player's password",
                "Change admin password",
                "Logout"
        };

        while (true) {
            int choice = Keyboard.getUserOption("ADMIN MENU", menu);
            switch (choice) {
                case 1: createPlayer(); break;
                case 2: deletePlayer(); break;
                case 3: viewAllPlayers(); break;
                case 4: issueChips(); break;
                case 5: resetPlayerPassword(); break;
                case 6: changeAdminPassword(); break;
                case 7: System.out.println("Logging out…"); return;
                default: System.out.println("Invalid choice");
            }
        }
    }

    /* ---------- MENU ACTIONS ---------- */

    private void createPlayer() {
        String name = Keyboard.readString("New player login name: ");
        if (findPlayer(name) != null) {
            System.out.println("A player with that name already exists.");
            return;
        }
        String pwd = Keyboard.readString("New player password: ");
        int chips = Keyboard.readInt("Initial chips: ");
        Player p = new Player(name, pwd, chips);
        players.add(p);
        savePlayers();
        System.out.println("Player created.");
    }

    private void deletePlayer() {
        String name = Keyboard.readString("Player name to delete: ");
        Player p = findPlayer(name);
        if (p == null) {
            System.out.println("No such player.");
            return;
        }
        players.remove(p);
        savePlayers();
        System.out.println("Player deleted.");
    }

    private void viewAllPlayers() {
        System.out.println("\n=== PLAYER LIST ===");
        for (Player p : players) {
            System.out.printf("Login: %s | Chips: %d%n", p.getLoginName(), p.getChips());
        }
        System.out.println();
    }

    private void issueChips() {
        String name = Keyboard.readString("Player to credit chips: ");
        Player p = findPlayer(name);
        if (p == null) {
            System.out.println("No such player.");
            return;
        }
        int amount = Keyboard.readInt("Number of chips to add: ");
        if (amount <= 0) {
            System.out.println("Amount must be positive.");
            return;
        }
        p.addChips(amount);
        savePlayers();
        System.out.println("Chips added.");
    }

    private void resetPlayerPassword() {
        String name = Keyboard.readString("Player whose password to reset: ");
        Player p = findPlayer(name);
        if (p == null) {
            System.out.println("No such player.");
            return;
        }
        String newPwd = Keyboard.readString("New password: ");
        p.setHashPassword(Utility.getHash(newPwd)); // User.setHashPassword is protected – we add a public wrapper in User
        savePlayers();
        System.out.println("Password reset.");
    }

    private void changeAdminPassword() {
        String current = Keyboard.readString("Enter current admin password: ");
        String storedHash = AdminFile.loadAdminHash();
        if (!storedHash.equals(Utility.getHash(current))) {
            System.out.println("Current password incorrect – aborting.");
            return;
        }
        String newPwd = Keyboard.readString("Enter new admin password: ");
        String confirm = Keyboard.readString("Confirm new password: ");
        if (!newPwd.equals(confirm)) {
            System.out.println("Passwords do not match – aborting.");
            return;
        }
        String newHash = Utility.getHash(newPwd);
        AdminFile.saveAdminHash(newHash);
        System.out.println("Admin password successfully changed.");
    }

    /** Helper – linear search */
    private Player findPlayer(String login) {
        for (Player p : players)
            if (p.getLoginName().equalsIgnoreCase(login))
                return p;
        return null;
    }

    /* ---------- PUBLIC ENTRY ---------- */
    public void run() {
        loadPlayers();          // read the current data set
        adminLogin();           // authenticate admin first
        adminMenu();            // then show the menu
    }

    /* ---------- MAIN ---------- */
    public static void main(String[] args) {
        new AdminModule().run();
    }
}
```

