### 3.1 Common（共享）

#### 3.1.1 Message.java

```java
package common;

import java.io.Serializable;
import java.util.Arrays;

public class Message implements Serializable {
    private static final long serialVersionUID = 1L;

    public enum MessageType { TEXT, IMAGE, FILE, SYSTEM }

    private MessageType type;
    private String from;      // userId / agentId
    private String to;        // 对方 id，或 "ALL" 表示广播
    private byte[] data;      // payload
    private String extra;     // 附加说明（文件名、系统指令等）

    // ---------- constructors ----------
    public Message(MessageType type, String from, String to, byte[] data, String extra) {
        this.type = type;
        this.from = from;
        this.to = to;
        this.data = data;
        this.extra = extra;
    }

    // ---------- factory helpers ----------
    public static Message text(String from, String to, String txt) {
        return new Message(MessageType.TEXT, from, to, txt.getBytes(java.nio.charset.StandardCharsets.UTF_8), null);
    }

    public static Message image(String from, String to, byte[] imgBytes, String fileName) {
        return new Message(MessageType.IMAGE, from, to, imgBytes, fileName);
    }

    public static Message file(String from, String to, byte[] fileBytes, String fileName) {
        return new Message(MessageType.FILE, from, to, fileBytes, fileName);
    }

    public static Message system(String from, String to, String cmd, String extra) {
        return new Message(MessageType.SYSTEM, from, to, cmd.getBytes(java.nio.charset.StandardCharsets.UTF_8), extra);
    }

    // ---------- getters ----------
    public MessageType getType()   { return type; }
    public String getFrom()        { return from; }
    public String getTo()          { return to; }
    public byte[] getData()        { return data; }
    public String getExtra()       { return extra; }

    @Override
    public String toString() {
        return "Message{" +
                "type=" + type +
                ", from='" + from + '\'' +
                ", to='" + to + '\'' +
                ", extra='" + extra + '\'' +
                ", dataLen=" + (data == null ? 0 : data.length) +
                '}';
    }
}
```

#### 3.1.2 ChatRecordManager.java（本地记录的加密持久化）

```java
package common;

import com.google.gson.*;
import javax.crypto.*;
import javax.crypto.spec.*;
import java.io.*;
import java.nio.file.*;
import java.security.*;
import java.util.*;

public class ChatRecordManager {
    private static final String RECORD_DIR = "chat_records";
    private static final String ALGORITHM = "AES";
    private static final String TRANSFORMATION = "AES/GCM/NoPadding";
    private static final int GCM_TAG_LEN = 128; // bits
    private static final int SALT_LEN = 16;

    private final Gson gson = new GsonBuilder().setPrettyPrinting().create();

    public ChatRecordManager() {
        new File(RECORD_DIR).mkdirs();
    }

    /** 生成基于用户密码的秘钥（PBKDF2） */
    private SecretKey deriveKey(char[] password, byte[] salt) throws GeneralSecurityException {
        SecretKeyFactory factory = SecretKeyFactory.getInstance("PBKDF2WithHmacSHA256");
        PBEKeySpec spec = new PBEKeySpec(password, salt, 65536, 256);
        SecretKey tmp = factory.generateSecret(spec);
        return new SecretKeySpec(tmp.getEncoded(), ALGORITHM);
    }

    /** 写入记录（加密） */
    public void saveChat(String userId, List<Message> history, char[] password) throws Exception {
        Path file = Paths.get(RECORD_DIR, userId + ".dat");
        byte[] salt = new byte[SALT_LEN];
        SecureRandom sr = new SecureRandom();
        sr.nextBytes(salt);
        SecretKey key = deriveKey(password, salt);

        Cipher cipher = Cipher.getInstance(TRANSFORMATION);
        byte[] iv = new byte[12];
        sr.nextBytes(iv);
        GCMParameterSpec spec = new GCMParameterSpec(GCM_TAG_LEN, iv);
        cipher.init(Cipher.ENCRYPT_MODE, key, spec);

        ByteArrayOutputStream bos = new ByteArrayOutputStream();
        try (CipherOutputStream cos = new CipherOutputStream(bos, cipher);
             OutputStreamWriter w = new OutputStreamWriter(cos, java.nio.charset.StandardCharsets.UTF_8)) {
            gson.toJson(history, w);
        }

        // 把 iv、salt、密文整体写入文件
        try (FileOutputStream fos = new FileOutputStream(file.toFile())) {
            fos.write(salt);
            fos.write(iv);
            fos.write(bos.toByteArray());
        }
    }

    /** 读取记录（解密） */
    public List<Message> loadChat(String userId, char[] password) throws Exception {
        Path file = Paths.get(RECORD_DIR, userId + ".dat");
        if (!Files.exists(file)) return new ArrayList<>();

        byte[] all = Files.readAllBytes(file);
        byte[] salt = Arrays.copyOfRange(all, 0, SALT_LEN);
        byte[] iv   = Arrays.copyOfRange(all, SALT_LEN, SALT_LEN + 12);
        byte[] ct   = Arrays.copyOfRange(all, SALT_LEN + 12, all.length);

        SecretKey key = deriveKey(password, salt);
        Cipher cipher = Cipher.getInstance(TRANSFORMATION);
        GCMParameterSpec spec = new GCMParameterSpec(GCM_TAG_LEN, iv);
        cipher.init(Cipher.DECRYPT_MODE, key, spec);

        try (CipherInputStream cis = new CipherInputStream(new ByteArrayInputStream(ct), cipher);
             InputStreamReader r = new InputStreamReader(cis, java.nio.charset.StandardCharsets.UTF_8)) {
            Message[] arr = gson.fromJson(r, Message[].class);
            return new ArrayList<>(Arrays.asList(arr));
        }
    }
}
```

> **注意**：`password` 参数应在登录时从 UI 获得，并在使用完后立即清除（`Arrays.fill`），防止在内存中泄露。

