### 3.2 Server（客服端）

#### 3.2.1 ServerMain.java（入口）

```java
package server;

import common.*;
import javax.net.ssl.*;
import java.io.*;
import java.net.*;
import java.security.*;
import java.util.concurrent.*;

public class ServerMain {
    private static final int PORT = 9999;
    private static final int MAX_THREADS = 50;

    // 保存已登录客服的会话对象，key: agentId
    private static final ConcurrentMap<String, AgentSession> agents = new ConcurrentHashMap<>();

    // 保存每个用户的对应客服（如果已接受）
    private static final ConcurrentMap<String, AgentSession> userToAgent = new ConcurrentHashMap<>();

    public static void main(String[] args) throws Exception {
        SSLServerSocket server = createSSLServerSocket(PORT);
        System.out.println("客服端已启动，监听端口 " + PORT);

        ExecutorService pool = Executors.newFixedThreadPool(MAX_THREADS);
        while (true) {
            SSLSocket client = (SSLSocket) server.accept();
            // 为每个连接分配独立 Worker
            pool.submit(new ClientWorker(client));
        }
    }

    /** 基础的 TLS 初始化（使用 JKS） */
    private static SSLServerSocket createSSLServerSocket(int port) throws Exception {
        char[] ksPass = "keystorePass".toCharArray();
        KeyStore ks = KeyStore.getInstance("JKS");
        ks.load(new FileInputStream("server.keystore"), ksPass);
        KeyManagerFactory kmf = KeyManagerFactory.getInstance("SunX509");
        kmf.init(ks, "keyPass".toCharArray());

        // 客户端可信任的 CA（可选双向认证）
        KeyStore ts = KeyStore.getInstance("JKS");
        ts.load(new FileInputStream("truststore.jks"), "trustPass".toCharArray());
        TrustManagerFactory tmf = TrustManagerFactory.getInstance("SunX509");
        tmf.init(ts);

        SSLContext ctx = SSLContext.getInstance("TLSv1.3");
        ctx.init(kmf.getKeyManagers(), tmf.getTrustManagers(), new SecureRandom());

        SSLServerSocketFactory ssf = ctx.getServerSocketFactory();
        SSLServerSocket ss = (SSLServerSocket) ssf.createServerSocket(port);
        ss.setNeedClientAuth(true); // 双向认证（如果需要）
        return ss;
    }

    /** 工作线程：处理单个用户的全部 I/O */
    static class ClientWorker implements Runnable {
        private final SSLSocket socket;
        private ObjectInputStream in;
        private ObjectOutputStream out;
        private String userId; // 客户端登录后确定

        ClientWorker(SSLSocket socket) {
            this.socket = socket;
        }

        @Override
        public void run() {
            try {
                // 建立流（注意顺序：先 out 再 in）
                out = new ObjectOutputStream(socket.getOutputStream());
                out.flush();
                in  = new ObjectInputStream(socket.getInputStream());

                // 1. 登录验证（简单示例，真实请接入 DB）
                Message loginMsg = (Message) in.readObject();
                if (loginMsg.getType() != Message.MessageType.SYSTEM ||
                    !"LOGIN".equals(new String(loginMsg.getData(), "UTF-8"))) {
                    sendSystem("SERVER", loginMsg.getFrom(), "ERROR", "登录失败");
                    socket.close(); return;
                }
                userId = loginMsg.getFrom(); // 假设登录用户名就是 userId
                System.out.println("[登录] 用户 " + userId + " 已连接");

                // 2. 发送新用户请求给所有在线客服（UI 层会弹窗）
                broadcastToAgents(Message.system("SERVER", "ALL", "NEW_REQUEST", userId));

                // 3. 主循环：转发消息或处理系统指令
                while (true) {
                    Message msg = (Message) in.readObject();
                    handleMessage(msg);
                }
            } catch (EOFException eof) {
                System.out.println("[断开] 用户 " + userId + " 已下线");
            } catch (Exception e) {
                e.printStackTrace();
            } finally {
                cleanup();
            }
        }

        /** 处理不同类型的消息 */
        private void handleMessage(Message msg) throws IOException {
            switch (msg.getType()) {
                case TEXT:
                case IMAGE:
                case FILE:
                    // 只转发给当前已经接受此用户请求的客服
                    AgentSession agent = userToAgent.get(userId);
                    if (agent != null) {
                        agent.send(msg);
                        // 同时把记录持久化（略）
                    } else {
                        // 未被接受，返回忙碌提示
                        sendSystem(userId, "SERVER", "BUSY", "当前无客服可用，请稍后…");
                    }
                    break;

                case SYSTEM:
                    String cmd = new String(msg.getData(), java.nio.charset.StandardCharsets.UTF_8);
                    // 客服端接受请求的指令
                    if ("ACCEPT".equals(cmd)) {
                        // 只在客服端收到该指令后写回
                        AgentSession agentSess = agents.get(msg.getFrom()); // from = agentId
                        if (agentSess != null) {
                            userToAgent.put(userId, agentSess);
                            sendSystem(userId, "SERVER", "ACCEPTED", "客服已经接入");
                        }
                    } else if ("REJECT".equals(cmd)) {
                        sendSystem(userId, "SERVER", "REJECTED", "客服已拒绝，请稍后");
                    }
                    break;

                default:
                    // ignore
            }
        }

        /** 给客户端发送系统消息 */
        private void sendSystem(String from, String to, String cmd, String extra) throws IOException {
            Message sys = Message.system(from, to, cmd, extra);
            out.writeObject(sys);
            out.flush();
        }

        /** 向所有在线客服广播 */
        private void broadcastToAgents(Message msg) {
            agents.values().forEach(agent -> {
                try { agent.send(msg); } catch (Exception ignored) {}
            });
        }

        /** 资源释放 */
        private void cleanup() {
            try { if (in != null) in.close(); } catch (Exception ignored) {}
            try { if (out != null) out.close(); } catch (Exception ignored) {}
            try { socket.close(); } catch (Exception ignored) {}
        }
    }

    /** 代表已登录的客服（Agent）会话 */
    static class AgentSession {
        private final String agentId;
        private final ObjectOutputStream out;

        AgentSession(String agentId, ObjectOutputStream out) {
            this.agentId = agentId;
            this.out = out;
        }

        void send(Message msg) throws IOException {
            synchronized (out) { // 防止多线程写冲突
                out.writeObject(msg);
                out.flush();
            }
        }
    }

    /** 注册客服（在客服 UI 登录成功后调用） */
    public static void registerAgent(String agentId, ObjectOutputStream out) {
        agents.put(agentId, new AgentSession(agentId, out));
    }

    /** 注销客服 */
    public static void unregisterAgent(String agentId) {
        agents.remove(agentId);
    }
}
```

> **要点**  
> * `ServerMain` 负责 **TLS** 监听并把每个新连接交给 `ClientWorker`。  
> * `ClientWorker` 完成 **用户登录 → 新请求广播 → 消息转发** 的完整流程。  
> * 通过 `agents`（所有在线客服）与 `userToAgent`（用户 ↔ 客服映射）实现 **一对多**（客服能接多个用户）与 **多对一** 的调度。

