#### 3.2.2 AgentGUI.java（客服 Swing 界面）

```java
package server;

import common.*;
import javax.net.ssl.*;
import java.awt.*;
import java.awt.event.*;
import java.io.*;
import java.util.*;
import javax.swing.*;

public class AgentGUI extends JFrame {
    private final JTextArea logArea = new JTextArea();
    private final JList<String> waitingList = new JList<>(new DefaultListModel<>());
    private final Map<String, ChatWindow> chatWindows = new HashMap<>();

    private SSLSocket socket;
    private ObjectOutputStream out;
    private ObjectInputStream in;
    private String agentId = "agent001"; // 示例，可改为登录后获取

    public AgentGUI() {
        setTitle("客服端 - " + agentId);
        setSize(600, 400);
        setLocationRelativeTo(null);
        setDefaultCloseOperation(EXIT_ON_CLOSE);
        initUI();
        initNetwork();
    }

    private void initUI() {
        JPanel left = new JPanel(new BorderLayout());
        left.add(new JLabel("待处理请求"), BorderLayout.NORTH);
        left.add(new JScrollPane(waitingList), BorderLayout.CENTER);
        JButton btnAccept = new JButton("接受");
        JButton btnReject = new JButton("拒绝");
        JPanel btnPanel = new JPanel(new GridLayout(1,2));
        btnPanel.add(btnAccept); btnPanel.add(btnReject);
        left.add(btnPanel, BorderLayout.SOUTH);

        btnAccept.addActionListener(e -> {
            String user = waitingList.getSelectedValue();
            if (user != null) {
                sendSystem(user, "ACCEPT");
                ((DefaultListModel<String>)waitingList.getModel()).removeElement(user);
                openChatWindow(user);
            }
        });
        btnReject.addActionListener(e -> {
            String user = waitingList.getSelectedValue();
            if (user != null) {
                sendSystem(user, "REJECT");
                ((DefaultListModel<String>)waitingList.getModel()).removeElement(user);
            }
        });

        JPanel right = new JPanel(new BorderLayout());
        logArea.setEditable(false);
        right.add(new JScrollPane(logArea), BorderLayout.CENTER);

        JSplitPane split = new JSplitPane(JSplitPane.HORIZONTAL_SPLIT, left, right);
        split.setDividerLocation(200);
        add(split);
    }

    /** 建立 TLS 连接并登录 */
    private void initNetwork() {
        try {
            socket = ServerMain.createSSLServerSocket(0) // reuse ServerMain 方法获取 SSLContext
                    .accept(); // 实际应使用 SSLSocketFactory 连接到服务器，这里简化
            out = new ObjectOutputStream(socket.getOutputStream());
            out.flush();
            in  = new ObjectInputStream(socket.getInputStream());

            // 注册到 Server（示例：直接调用静态方法）
            ServerMain.registerAgent(agentId, out);

            // 登录系统（这里使用简单的 SYSTEM 消息）
            Message login = Message.system(agentId, "SERVER", "LOGIN", null);
            out.writeObject(login);
            out.flush();

            // 启动接收线程
            new Thread(this::receiveLoop, "Agent-Receiver").start();
        } catch (Exception e) {
            showError("网络初始化失败: " + e.getMessage());
        }
    }

    /** 循环读取服务器推送的消息 */
    private void receiveLoop() {
        try {
            while (true) {
                Message msg = (Message) in.readObject();
                handleServerMessage(msg);
            }
        } catch (Exception e) {
            showError("连接已断开: " + e.getMessage());
        }
    }

    /** 处理来自服务器的各种消息 */
    private void handleServerMessage(Message msg) {
        switch (msg.getType()) {
            case SYSTEM:
                String cmd = new String(msg.getData());
                if ("NEW_REQUEST".equals(cmd)) {
                    String userId = msg.getExtra();
                    SwingUtilities.invokeLater(() ->
                        ((DefaultListModel<String>)waitingList.getModel()).addElement(userId));
                } else if ("BUSY".equals(cmd)) {
                    // 可以在 UI 中弹窗提示
                    JOptionPane.showMessageDialog(this, "用户 " + msg.getFrom() + " 提示客服忙碌");
                }
                break;

            case TEXT:
            case IMAGE:
            case FILE:
                // 交给对应的聊天窗口展示
                ChatWindow cw = chatWindows.computeIfAbsent(msg.getFrom(),
                        uid -> openChatWindow(uid));
                cw.appendMessage(msg);
                break;
            default:
                // ignore
        }
    }

    /** 打开（或取得已有的）与某用户的聊天窗口 */
    private ChatWindow openChatWindow(String userId) {
        return chatWindows.computeIfAbsent(userId, uid -> {
            ChatWindow win = new ChatWindow(uid, out);
            win.setLocationRelativeTo(this);
            win.setVisible(true);
            return win;
        });
    }

    /** 向服务器发送系统指令（接受/拒绝） */
    private void sendSystem(String toUser, String action) {
        try {
            Message sys = Message.system(agentId, toUser, action, null);
            out.writeObject(sys);
            out.flush();
        } catch (IOException e) {
            showError("发送指令失败: " + e.getMessage());
        }
    }

    private void showError(String msg) {
        SwingUtilities.invokeLater(() -> JOptionPane.showMessageDialog(this, msg, "错误", JOptionPane.ERROR_MESSAGE));
    }

    /** --------------------- 内部类：聊天窗口 --------------------- */
    static class ChatWindow extends JFrame {
        private final JTextArea txtArea = new JTextArea();
        private final JTextField inputField = new JTextField();
        private final JButton btnSend = new JButton("发送");
        private final JButton btnImg = new JButton("图片");
        private final JButton btnFile = new JButton("文件");
        private final String userId;
        private final ObjectOutputStream out;

        ChatWindow(String userId, ObjectOutputStream out) {
            this.userId = userId;
            this.out = out;
            setTitle("与用户 " + userId + " 对话");
            setSize(500, 400);
            initUI();
        }

        private void initUI() {
            txtArea.setEditable(false);
            JPanel bottom = new JPanel(new BorderLayout());
            bottom.add(inputField, BorderLayout.CENTER);
            bottom.add(btnSend, BorderLayout.EAST);
            JPanel tools = new JPanel(new FlowLayout(FlowLayout.LEFT));
            tools.add(btnImg); tools.add(btnFile);
            bottom.add(tools, BorderLayout.NORTH);

            add(new JScrollPane(txtArea), BorderLayout.CENTER);
            add(bottom, BorderLayout.SOUTH);

            btnSend.addActionListener(e -> sendText());
            btnImg.addActionListener(e -> chooseAndSendImage());
            btnFile.addActionListener(e -> chooseAndSendFile());

            // 按 Enter 直接发送文字
            inputField.addActionListener(e -> sendText());
        }

        private void sendText() {
            String txt = inputField.getText().trim();
            if (txt.isEmpty()) return;
            try {
                Message msg = Message.text("agent", userId, txt);
                out.writeObject(msg);
                out.flush();
                appendMessage(msg); // 本地先展示
                inputField.setText("");
            } catch (IOException ex) {
                JOptionPane.showMessageDialog(this, "发送失败: " + ex.getMessage());
            }
        }

        private void chooseAndSendImage() {
            JFileChooser fc = new JFileChooser();
            fc.setFileFilter(new javax.swing.filechooser.FileNameExtensionFilter("图片文件", "jpg","png","jpeg","bmp"));
            if (fc.showOpenDialog(this) == JFileChooser.APPROVE_OPTION) {
                File f = fc.getSelectedFile();
                try {
                    byte[] data = Files.readAllBytes(f.toPath());
                    Message msg = Message.image("agent", userId, data, f.getName());
                    out.writeObject(msg);
                    out.flush();
                    appendMessage(msg);
                } catch (IOException ex) {
                    JOptionPane.showMessageDialog(this, "发送图片失败: " + ex.getMessage());
                }
            }
        }

        private void chooseAndSendFile() {
            JFileChooser fc = new JFileChooser();
            if (fc.showOpenDialog(this) == JFileChooser.APPROVE_OPTION) {
                File f = fc.getSelectedFile();
                try {
                    byte[] data = Files.readAllBytes(f.toPath());
                    Message msg = Message.file("agent", userId, data, f.getName());
                    out.writeObject(msg);
                    out.flush();
                    appendMessage(msg);
                } catch (IOException ex) {
                    JOptionPane.showMessageDialog(this, "发送文件失败: " + ex.getMessage());
                }
            }
        }

        /** 在聊天框中追加已收到/已发送的消息 */
        void appendMessage(Message msg) {
            SwingUtilities.invokeLater(() -> {
                switch (msg.getType()) {
                    case TEXT:
                        txtArea.append(msg.getFrom() + ": " + new String(msg.getData(), java.nio.charset.StandardCharsets.UTF_8) + "\n");
                        break;
                    case IMAGE:
                        txtArea.append(msg.getFrom() + " 发送了一张图片: " + msg.getExtra() + "\n");
                        // 可选：把二进制转为 ImageIcon 添加到文本框（略）
                        break;
                    case FILE:
                        txtArea.append(msg.getFrom() + " 发送了文件: " + msg.getExtra() + "\n");
                        // 若想直接保存，可弹窗询问保存路径
                        break;
                    default:
                        // ignore
                }
            });
        }
    }

    // -------------------------------------------------------------
    public static void main(String[] args) {
        SwingUtilities.invokeLater(() -> new AgentGUI().setVisible(true));
    }
}
```

> **重点说明**  
> * **UI 线程**（EDT）仅负责绘制与用户交互，所有网络 I/O 完全在 `receiveLoop` 线程中完成。  
> * 当收到 **SYSTEM:NEW_REQUEST** 时，客服 UI 会把用户名加入 `JList`，随后客服可以点击 “接受”/“拒绝”。  
> * 聊天窗口 (`ChatWindow`) 负责文字、图片、文件的发送和显示。图片和文件均以 **二进制** 形式封装在 `Message` 中，服务端直接转发给对应的用户。  

