### 3.3 Client（用户端）

#### 3.3.1 ClientMain.java（入口 + UI）

```java
package client;

import common.*;
import javax.net.ssl.*;
import java.awt.*;
import java.awt.event.*;
import java.io.*;
import java.nio.file.*;
import java.security.*;
import java.util.*;
import javax.swing.*;

public class ClientMain extends JFrame {
    private final JTextArea chatArea = new JTextArea();
    private final JTextField inputField = new JTextField();
    private final JButton btnSend = new JButton("发送");
    private final JButton btnImg = new JButton("图片");
    private final JButton btnFile = new JButton("文件");
    private final JLabel statusLabel = new JLabel("未连接");

    private SSLSocket socket;
    private ObjectOutputStream out;
    private ObjectInputStream in;
    private String userId;
    private ChatRecordManager recordMgr = new ChatRecordManager();
    private List<Message> history = new ArrayList<>();

    public ClientMain() {
        setTitle("用户端");
        setSize(500, 400);
        setLocationRelativeTo(null);
        setDefaultCloseOperation(EXIT_ON_CLOSE);
        initUI();
        // 登录/连接前先弹框取得用户信息
        promptLogin();
    }

    private void initUI() {
        chatArea.setEditable(false);
        JPanel bottom = new JPanel(new BorderLayout());
        bottom.add(inputField, BorderLayout.CENTER);
        bottom.add(btnSend, BorderLayout.EAST);
        JPanel tools = new JPanel(new FlowLayout(FlowLayout.LEFT));
        tools.add(btnImg); tools.add(btnFile);
        bottom.add(tools, BorderLayout.NORTH);
        add(new JScrollPane(chatArea), BorderLayout.CENTER);
        add(bottom, BorderLayout.SOUTH);
        add(statusLabel, BorderLayout.NORTH);

        btnSend.addActionListener(e -> sendText());
        btnImg.addActionListener(e -> chooseAndSendImage());
        btnFile.addActionListener(e -> chooseAndSendFile());
        inputField.addActionListener(e -> sendText());
    }

    /** 登录弹窗（演示阶段仅使用用户名/密码） */
    private void promptLogin() {
        JTextField tfUser = new JTextField();
        JPasswordField pfPass = new JPasswordField();
        Object[] msg = {"用户名:", tfUser, "密码:", pfPass};
        int option = JOptionPane.showConfirmDialog(this, msg, "登录", JOptionPane.OK_CANCEL_OPTION);
        if (option != JOptionPane.OK_OPTION) {
            System.exit(0);
        }
        userId = tfUser.getText().trim();
        char[] password = pfPass.getPassword();

        // 读取历史记录（解密）
        try {
            history = recordMgr.loadChat(userId, password);
            history.forEach(this::showMessage);
        } catch (Exception e) {
            JOptionPane.showMessageDialog(this, "加载历史记录失败: " + e.getMessage());
        }

        // 建立 TLS 连接
        try {
            socket = createSSLClientSocket("localhost", 9999);
            out = new ObjectOutputStream(socket.getOutputStream());
            out.flush();
            in  = new ObjectInputStream(socket.getInputStream());

            // 登录系统（这里使用 SYSTEM 消息）
            Message login = Message.system(userId, "SERVER", "LOGIN", null);
            out.writeObject(login);
            out.flush();

            statusLabel.setText("已连接，等待客服响应…");
            new Thread(this::receiveLoop, "Client-Receiver").start();
        } catch (Exception ex) {
            JOptionPane.showMessageDialog(this, "连接失败: " + ex.getMessage());
            System.exit(1);
        } finally {
            // 抹掉密码
            Arrays.fill(password, '\0');
        }
    }

    /** TLS 客户端创建（使用 truststore） */
    private SSLSocket createSSLClientSocket(String host, int port) throws Exception {
        char[] tsPass = "trustPass".toCharArray();
        KeyStore ts = KeyStore.getInstance("JKS");
        ts.load(new FileInputStream("client.truststore"), tsPass);
        TrustManagerFactory tmf = TrustManagerFactory.getInstance("SunX509");
        tmf.init(ts);

        SSLContext ctx = SSLContext.getInstance("TLSv1.3");
        ctx.init(null, tmf.getTrustManagers(), new SecureRandom());

        SSLSocketFactory factory = ctx.getSocketFactory();
        return (SSLSocket) factory.createSocket(host, port);
    }

    /** 接收线程循环 */
    private void receiveLoop() {
        try {
            while (true) {
                Message msg = (Message) in.readObject();
                // 系统指令（如客服忙、接受、拒绝等）
                if (msg.getType() == Message.MessageType.SYSTEM) {
                    String cmd = new String(msg.getData(), java.nio.charset.StandardCharsets.UTF_8);
                    handleSystemMessage(cmd, msg);
                } else {
                    // 加入历史并展示
                    history.add(msg);
                    showMessage(msg);
                }
            }
        } catch (Exception e) {
            SwingUtilities.invokeLater(() -> statusLabel.setText("已断开: " + e.getMessage()));
        }
    }

    private void handleSystemMessage(String cmd, Message msg) {
        SwingUtilities.invokeLater(() -> {
            switch (cmd) {
                case "BUSY":
                    statusLabel.setText("客服忙碌，请稍后重试");
                    break;
                case "ACCEPTED":
                    statusLabel.setText("已连接客服");
                    break;
                case "REJECTED":
                    statusLabel.setText("对方拒绝服务，稍后再试");
                    break;
                default:
                    statusLabel.setText("系统消息：" + cmd);
            }
        });
    }

    /** 发送文字 */
    private void sendText() {
        String txt = inputField.getText().trim();
        if (txt.isEmpty()) return;
        try {
            Message msg = Message.text(userId, "SERVER", txt);
            out.writeObject(msg);
            out.flush();
            // 本地先展示，记录历史
            history.add(msg);
            showMessage(msg);
            inputField.setText("");
        } catch (IOException ex) {
            JOptionPane.showMessageDialog(this, "发送失败: " + ex.getMessage());
        }
    }

    /** 发送图片 */
    private void chooseAndSendImage() {
        JFileChooser fc = new JFileChooser();
        fc.setFileFilter(new javax.swing.filechooser.FileNameExtensionFilter("图片文件", "jpg","png","jpeg","bmp"));
        if (fc.showOpenDialog(this) == JFileChooser.APPROVE_OPTION) {
            File f = fc.getSelectedFile();
            try {
                byte[] data = Files.readAllBytes(f.toPath());
                Message msg = Message.image(userId, "SERVER", data, f.getName());
                out.writeObject(msg);
                out.flush();
                history.add(msg);
                showMessage(msg);
            } catch (IOException ex) {
                JOptionPane.showMessageDialog(this, "发送图片失败: " + ex.getMessage());
            }
        }
    }

    /** 发送文件 */
    private void chooseAndSendFile() {
        JFileChooser fc = new JFileChooser();
        if (fc.showOpenDialog(this) == JFileChooser.APPROVE_OPTION) {
            File f = fc.getSelectedFile();
            try {
                byte[] data = Files.readAllBytes(f.toPath());
                Message msg = Message.file(userId, "SERVER", data, f.getName());
                out.writeObject(msg);
                out.flush();
                history.add(msg);
                showMessage(msg);
            } catch (IOException ex) {
                JOptionPane.showMessageDialog(this, "发送文件失败: " + ex.getMessage());
            }
        }
    }

    /** 将收到的消息渲染到 UI（文字、图片、文件） */
    private void showMessage(Message msg) {
        SwingUtilities.invokeLater(() -> {
            switch (msg.getType()) {
                case TEXT:
                    chatArea.append(msg.getFrom() + ": " + new String(msg.getData(), java.nio.charset.StandardCharsets.UTF_8) + "\n");
                    break;
                case IMAGE:
                    chatArea.append(msg.getFrom() + " 发送了一张图片: " + msg.getExtra() + "\n");
                    // 将二进制保存为临时文件并展示（演示）
                    try {
                        Path tmp = Files.createTempFile("recv_", "_" + msg.getExtra());
                        Files.write(tmp, msg.getData());
                        ImageIcon icon = new ImageIcon(tmp.toAbsolutePath().toString());
                        chatArea.insertIcon(icon);
                        chatArea.append("\n");
                    } catch (IOException ignored) {}
                    break;
                case FILE:
                    chatArea.append(msg.getFrom() + " 发送了文件: " + msg.getExtra() + "（点击保存）\n");
                    // 简单实现：右键保存/弹出保存框（略）
                    break;
                default:
                    // ignore
            }
        });
    }

    /** 程序退出时保存聊天记录（加密） */
    @Override
    public void dispose() {
        super.dispose();
        // 要求用户再次输入密码以加密保存
        JPasswordField pf = new JPasswordField();
        int opt = JOptionPane.showConfirmDialog(this, pf, "保存记录密码", JOptionPane.OK_CANCEL_OPTION);
        if (opt == JOptionPane.OK_OPTION) {
            char[] pwd = pf.getPassword();
            try {
                recordMgr.saveChat(userId, history, pwd);
                Arrays.fill(pwd, '\0');
            } catch (Exception e) {
                JOptionPane.showMessageDialog(this, "保存记录失败: " + e.getMessage());
            }
        }
        try {
            if (socket != null) socket.close();
        } catch (IOException ignored) {}
    }

    public static void main(String[] args) {
        SwingUtilities.invokeLater(() -> new ClientMain().setVisible(true));
    }
}
```

> **关键点**  
> 1. **登录**：示例使用用户名 + 密码，实际生产要接入统一身份鉴别（OAuth、JWT 等）。  
> 2. **聊天记录**：在 `ClientMain` 启动时读取（解密）历史，退出时再次加密保存。  
> 3. **图片/文件展示**：这里仅示例把图片保存为临时文件并直接以 `ImageIcon` 插入 `JTextArea`，文件则可以弹框保存到用户选定的位置。  
> 4. **异常处理**：所有网络 I/O 包装在 `try/catch`，异常信息打印到 UI 状态栏或弹框，防止程序直接崩溃。  

