/**
 * 将一张 JPEG/PNG（二进制）图片转换为 H.264 帧，并通过 TCP Socket 发送。
 * 这里演示单帧的“实时流”。如果你需要把多帧图片组成视频，只需要循环调用
 * `encodeAndSend(frame)` 即可，FFmpegFrameRecorder 会自动维护时间戳。
 */
public class ImageToH264ViaSocket {

    // ---------- 参数 ----------
    private static final String REMOTE_HOST = "127.0.0.1";
    private static final int REMOTE_PORT = 5000;
    private static final int VIDEO_WIDTH = 640;     // 必须和图片尺寸一致，或者自行做 resize
    private static final int VIDEO_HEIGHT = 480;
    private static final int FPS = 25;              // 对于单帧流可以随意设定
    // ---------- End 参数 ----------

    private Socket socket;
    private OutputStream out;
    private FFmpegFrameRecorder recorder;
    private OpenCVFrameConverter.ToIplImage converter = new OpenCVFrameConverter.ToIplImage();

    /** 初始化网络连接和 FFmpeg 编码器 */
    public void init() throws IOException {
        // 1. 建立 Socket（可换成 SSLSocket、DatagramSocket 等）
        socket = new Socket(REMOTE_HOST, REMOTE_PORT);
        out = new BufferedOutputStream(socket.getOutputStream());

        // 2. 创建 FFmpegFrameRecorder（输出到内存 ByteArrayOutputStream）
        //    我们把 recorder 的“文件名”写成 "pipe:0"，表示写入标准输出
        recorder = new FFmpegFrameRecorder(out, VIDEO_WIDTH, VIDEO_HEIGHT);
        recorder.setFormat("h264");                 // 只输出 H.264 原始流（不封装容器）
        recorder.setVideoCodec(avcodec.AV_CODEC_ID_H264);
        recorder.setPixelFormat(avutil.AV_PIX_FMT_YUV420P);
        recorder.setFrameRate(FPS);
        recorder.setGopSize(FPS * 2);               // I 帧间隔，视需求自行调
        recorder.setOption("preset", "ultrafast"); // 编码速度/质量权衡
        recorder.setOption("tune", "zerolatency"); // 低延迟模式（适合实时）

        // 3. 启动编码器
        try {
            recorder.start();
        } catch (org.bytedeco.javacv.FrameRecorder.Exception e) {
            throw new IOException("Failed to start FFmpegFrameRecorder", e);
        }
    }

    /** 把二进制图片 (byte[]) 进行解码、编码并发送 */
    public void encodeAndSend(byte[] imgData) throws IOException {
        // ① 读取图片到 BufferedImage（JDK 标准库）
        BufferedImage img;
        try (ByteArrayInputStream bais = new ByteArrayInputStream(imgData)) {
            img = ImageIO.read(bais);
            if (img == null) throw new IOException("Unsupported image format or corrupted data");
        }

        // ② 如有必要，做一次 resize，保证尺寸一致
        if (img.getWidth() != VIDEO_WIDTH || img.getHeight() != VIDEO_HEIGHT) {
            BufferedImage resized = new BufferedImage(VIDEO_WIDTH, VIDEO_HEIGHT, BufferedImage.TYPE_3BYTE_BGR);
            resized.getGraphics().drawImage(img, 0, 0, VIDEO_WIDTH, VIDEO_HEIGHT, null);
            img = resized;
        }

        // ③ 转成 OpenCV Mat（IplImage） → Frame（FFmpeg 可识别的结构）
        //    这里使用 JavaCV 的转换工具，将 BufferedImage -> Frame
        Frame frame = converter.convert(toIplImage(img));

        // ④ 编码并写入 socket
        try {
            recorder.record(frame);
        } catch (org.bytedeco.javacv.FrameRecorder.Exception e) {
            throw new IOException("FFmpegFrameRecorder.record() failed", e);
        }
    }

    /** 关闭资源 */
    public void close() {
        try {
            if (recorder != null) {
                recorder.stop();
                recorder.release();
            }
        } catch (Exception ignored) {}
        try {
            if (out != null) out.close();
            if (socket != null) socket.close();
        } catch (IOException ignored) {}
    }

    // ---------- 工具方法 ----------
    /** BufferedImage → IplImage（OpenCV） */
    private static org.bytedeco.javacpp.opencv_core.IplImage toIplImage(BufferedImage img) {
        // 把 BufferedImage 的 BGR 数据包装成 IplImage
        DataBufferByte data = (DataBufferByte) img.getRaster().getDataBuffer();
        byte[] pixels = data.getData();
        // BGR 与 OpenCV 默认的 BGR 顺序一致
        org.bytedeco.javacpp.opencv_core.IplImage ipl = org.bytedeco.javacpp.opencv_core.IplImage.create(
                img.getWidth(),
                img.getHeight(),
                org.bytedeco.javacpp.opencv_core.IPL_DEPTH_8U,
                3);
        ipl.getByteBuffer().put(pixels);
        return ipl;
    }
    // ---------- End 工具 ----------
}
```

