@RestController
@RequestMapping("/api")
@RequiredArgsConstructor
public class FrameController {

    // 用于暂存待编码的图片，容量可自行调节（比如 200 帧）
    private final BlockingQueue<BufferedImage> frameQueue = 
            new ArrayBlockingQueue<>(200);

    // 防止短时间内大量上传（简单限流）
    private final RateLimiter limiter = RateLimiter.create(30); // 30 FPS max

    @PostMapping(value = "/frame", consumes = MediaType.MULTIPART_FORM_DATA_VALUE)
    public ResponseEntity<String> uploadFrame(@RequestParam("file") MultipartFile file) 
            throws IOException {

        if (!limiter.tryAcquire()) {
            return ResponseEntity.status(HttpStatus.TOO_MANY_REQUESTS)
                    .body("Rate limit exceeded");
        }

        // 基本校验：文件大小、MIME 类型、图片可解析性
        if (file.isEmpty() || !file.getContentType().startsWith("image/")) {
            return ResponseEntity.badRequest().body("Invalid image file");
        }

        BufferedImage img = ImageIO.read(file.getInputStream());
        if (img == null) {
            return ResponseEntity.badRequest().body("Unsupported image format");
        }

        // 队列满则丢帧（业务可自行决定保留或阻塞）
        if (!frameQueue.offer(img)) {
            // 这里可以统计丢帧率，以便后续调优
            return ResponseEntity.status(HttpStatus.INSUFFICIENT_STORAGE)
                    .body("Frame queue full, frame dropped");
        }

        return ResponseEntity.ok("Frame accepted");
    }

    /** 将队列暴露给编码器 */
    public BlockingQueue<BufferedImage> getFrameQueue() {
        return frameQueue;
    }
}
```

