    @PostConstruct
    public void startEncoder() {
        // 异步启动编码线程（Spring 自带 @Async 也可以）
        new Thread(this::encodeLoop, "h264-encoder").start();
    }

    private void encodeLoop() {
        // JCodec encoder 环境准备
        H264Encoder encoder = new H264Encoder();
        // 这里的 "Frame" 实际是 Picture (YUV420) 类型
        Picture8Bit pic = Picture.create(WIDTH, HEIGHT, ColorSpace.YUV420);
        ByteArrayOutputStream nalus = new ByteArrayOutputStream();

        while (true) {
            try {
                BufferedImage img = frameController.getFrameQueue().take(); // 阻塞
                // 1️⃣ 将 BufferedImage -> YUV420 (快速缩放/裁剪)
                AWTUtil.fromBufferedImage(img, pic);

                // 2️⃣ 编码单帧，返回 Annex‑B NALU 列表
                ByteBuffer out = encoder.encodeFrame(pic, null);
                nalus.reset();
                nalus.write(out.array(), 0, out.remaining());

                // 3️⃣ 将每帧封装为自定义包并放入 outboundQueue
                byte[] packet = packH264Nalus(nalus.toByteArray());
                // 如果队列满则丢包（业务可改为阻塞 put）
                outboundQueue.offer(packet);
            } catch (InterruptedException e) {
                Thread.currentThread().interrupt();
                break;
            } catch (Exception ex) {
                // 生产环境建议回放日志 + 监控告警
                ex.printStackTrace();
            }
        }
    }

    /**
     * 简单的自定义协议：
     * 4 bytes: payload length (big‑endian)
     * 8 bytes: timestamp (epoch ms)
     * N bytes: Annex‑B NALU (0x000001 …)
     */
    private byte[] packH264Nalus(byte[] payload) {
        ByteBuffer buf = ByteBuffer.allocate(4 + 8 + payload.length);
        buf.putInt(payload.length);
        buf.putLong(System.currentTimeMillis());
        buf.put(payload);
        return buf.array();
    }

    /** Netty Handler 需要读取的队列 */
    public LinkedBlockingQueue<byte[]> getOutboundQueue() {
        return outboundQueue;
    }
}
```

> **注意**：  
> - **JCodec 的 `H264Encoder`** 并未实现完整的 GOP、B‑frame 功能，仅适用于 **低延迟、纯 I‑frame** 场景。如果需要 **可调码率、B‑frame**，强烈建议使用 **本地 FFmpeg**（通过 ProcessBuilder）或 **JavaCV**（FFmpeg JNI）。  
> - 这里的 `Picture8Bit` 必须与 `BufferedImage` 分辨率匹配；如果上传的图片尺寸不符，需要 **统一缩放**（`java.awt.Graphics2D` 或 `Imgscalr`）后再送入编码器。  

