### 3.2 服务端核心（ServerMain + ClientHandler）

```java
// ServerMain.java
import javax.net.ssl.*;
import java.io.*;
import java.net.*;
import java.security.KeyStore;
import java.util.concurrent.*;

public class ServerMain {
    // 线程池：每个客户端对应一个 Handler，最多 50 人同时在线（可调）
    private static final ExecutorService POOL = Executors.newFixedThreadPool(50);
    // 保存在线客服和普通用户的映射
    private static final ConcurrentHashMap<String, ClientHandler> ONLINE = new ConcurrentHashMap<>();

    // 记录所有聊天日志的根目录
    private static final File LOG_ROOT = new File("chat_logs");

    // ======================================================
    public static void main(String[] args) throws Exception {
        SSLServerSocket server = createSSLServerSocket(8443);
        System.out.println("[Server] Listening on 8443 (TLS) ...");

        while (true) {
            SSLSocket socket = (SSLSocket) server.accept();
            // 每个 TCP 连接都交给线程池处理
            POOL.submit(() -> {
                try {
                    new ClientHandler(socket).run();
                } catch (Exception e) {
                    e.printStackTrace();
                }
            });
        }
    }

    // ------------------------------------------------------
    private static SSLServerSocket createSSLServerSocket(int port) throws Exception {
        // 使用 JKS 自签证书（生产环境请换成受信 CA）
        KeyStore ks = KeyStore.getInstance("JKS");
        ks.load(new FileInputStream("server.keystore"), "changeit".toCharArray());

        KeyManagerFactory kmf = KeyManagerFactory.getInstance("SunX509");
        kmf.init(ks, "changeit".toCharArray());

        SSLContext ctx = SSLContext.getInstance("TLS");
        ctx.init(kmf.getKeyManagers(), null, null); // 不要求客户端证书

        SSLServerSocketFactory ssf = ctx.getServerSocketFactory();
        SSLServerSocket ss = (SSLServerSocket) ssf.createServerSocket(port);
        ss.setNeedClientAuth(false); // 如需双向 TLS，设为 true 并配置 TrustManager
        return ss;
    }

    // ======================================================
    // 内部类：负责单个连接的读写，关联用户 id
    static class ClientHandler {
        private final SSLSocket socket;
        private BufferedReader in;
        private BufferedWriter out;
        private String userId; // 对应用户或客服端标识
        private volatile boolean isAgent = false; // 是否是客服

        ClientHandler(SSLSocket socket) throws IOException {
            this.socket = socket;
            this.in  = new BufferedReader(new InputStreamReader(socket.getInputStream(), "UTF-8"));
            this.out = new BufferedWriter(new OutputStreamWriter(socket.getOutputStream(), "UTF-8"));
        }

        void run() throws Exception {
            // 1️⃣ 首次消息必须是 CTRL 登录请求
            Message login = Message.fromJson(in.readLine());
            if (login.type != Message.Type.CTRL) {
                sendError("First message must be CTRL login");
                close();
                return;
            }
            this.userId = login.from; // 这里假设客户端已经完成身份校验（token）
            this.isAgent = "agent".equals(login.payload); // payload 为 "agent" 表示客服端

            // 加入在线映射
            ONLINE.put(userId, this);
            System.out.println("[Server] " + (isAgent ? "客服" : "用户") + " 登录: " + userId);

            // 2️⃣ 若是用户，检查历史记录并推送给客户端
            if (!isAgent) {
                sendChatHistory();
                // 3️⃣ 通知所有在线客服有新用户请求
                broadcastToAgents(ctrlMessage("NEW_USER", userId));
                // 4️⃣ 启动一个计时器，如果 30 秒未被任何客服接管，则发送 BUSY
                scheduleBusyNotice(30_000);
            }

            // 5️⃣ 主循环：读取对端消息并路由
            String line;
            while ((line = in.readLine()) != null) {
                Message msg = Message.fromJson(line);
                routeMessage(msg);
            }
        }

        // --------------------------------------------------
        private void routeMessage(Message msg) throws Exception {
            // 对消息进行审计日志（仅演示）
            System.out.println("[Msg] " + msg.type + " from " + msg.from + " to " + msg.to);

            // 保存到本地聊天记录
            persistMessage(msg);

            // 目标用户/客服（单向映射? 双向映射都行，这里直接使用 to）
            ClientHandler target = ONLINE.get(msg.to);
            if (target != null) {
                target.send(msg);
            } else {
                // 对方离线，返回错误或缓存（略）
                sendError("Target offline: " + msg.to);
            }
        }

        // --------------------------------------------------
        /** 将消息写入对端 */
        void send(Message msg) throws Exception {
            out.write(msg.toJson());
            out.newLine();
            out.flush();
        }

        // --------------------------------------------------
        /** 简单错误消息 */
        private void sendError(String info) throws Exception {
            Message err = new Message();
            err.type = Message.Type.CTRL;
            err.from = "system";
            err.to   = userId;
            err.payload = "ERROR:" + info;
            send(err);
        }

        // --------------------------------------------------
        /** 把聊天记录追加到本地文件，文件名为 user_<id>.log */
        private void persistMessage(Message msg) {
            try {
                File log = new File(LOG_ROOT, "user_" + userId + ".log");
                try (FileWriter fw = new FileWriter(log, true)) {
                    fw.write(msg.toJson() + System.lineSeparator());
                }
            } catch (IOException e) {
                e.printStackTrace(); // 生产环境改为日志框架
            }
        }

        /** 将已有历史记录一次性推送给客户端（只在用户登录时） */
        private void sendChatHistory() {
            File log = new File(LOG_ROOT, "user_" + userId + ".log");
            if (!log.exists()) return;
            try (BufferedReader br = new BufferedReader(new FileReader(log))) {
                String line;
                while ((line = br.readLine()) != null) {
                    Message msg = Message.fromJson(line);
                    send(msg); // 直接转发给客户端，客户端自行渲染
                }
            } catch (Exception e) {
                e.printStackTrace();
            }
        }

        // --------------------------------------------------
        /** 向所有在线客服广播控制消息 */
        private void broadcastToAgents(Message ctrl) {
            ONLINE.values().stream()
                .filter(h -> h.isAgent)
                .forEach(h -> {
                    try { h.send(ctrl); } catch (Exception ignore) {}
                });
        }

        /** 构造简单的控制消息 */
        private Message ctrlMessage(String cmd, String payload) {
            Message m = new Message();
            m.type = Message.Type.CTRL;
            m.from = "system";
            m.to   = "agents";
            m.payload = cmd + ":" + payload;
            return m;
        }

        /** 若 30 秒内没有客服接手，则发送 BUSY 给用户 */
        private void scheduleBusyNotice(long delayMs) {
            ScheduledExecutorService scheduler = Executors.newSingleThreadScheduledExecutor();
            scheduler.schedule(() -> {
                // 检查当前用户是否已经被某客服绑定（这里用一个标记，省略实现）
                if (!isAgent && !hasAgentAssigned()) {
                    Message busy = new Message();
                    busy.type = Message.Type.BUSY;
                    busy.from = "system";
                    busy.to   = userId;
                    busy.payload = "客服忙，请稍后再试";
                    try { send(busy); } catch (Exception ignore) {}
                }
            }, delayMs, TimeUnit.MILLISECONDS);
        }

        private boolean hasAgentAssigned() {
            // 简单示例：遍历 online，检查是否有客服的 target 为此 userId
            return ONLINE.values().stream()
                .anyMatch(h -> h.isAgent && userId.equals(h.currentTarget));
        }

        private String currentTarget = null; // 当客服接手后设置

        // --------------------------------------------------
        void close() {
            try { socket.close(); } catch (IOException ignore) {}
            ONLINE.remove(userId);
        }
    }
}
```

#### 关键点说明  

| 区域 | 说明 | 安全/性能提示 |
|------|------|--------------|
| **TLS 初始化** | 读取 `server.keystore`，创建 `SSLServerSocket`。 | 生产环境请使用 **强密码**（AES‑256‑GCM），关闭老旧协议 (`TLSv1.0/1.1`)。 |
| **线程池** | `ExecutorService` 限制并发度，防止 `fork bomb`。 | 使用 `ThreadPoolExecutor` 并配置 `RejectedExecutionHandler`。 |
| **ConcurrentHashMap** | 保存在线用户，天然线程安全。 | 对 `ONLINE` 的遍历只读，不做 `remove`，防止 `ConcurrentModificationException`。 |
