/** 登录信息的简单 DTO */
class LoginInfo {
    String userId;
    boolean isAgent; // true: 客服端
}

/** NetWorker 负责所有网络 I/O，内部使用阻塞队列与 UI 解耦 */
class NetWorker {
    private final SSLSocket socket;
    private final BufferedReader in;
    private final BufferedWriter out;
    private final BlockingQueue<Message> sendQueue = new LinkedBlockingQueue<>();
    private final ExecutorService executor = Executors.newSingleThreadExecutor();
    private final LoginInfo loginInfo;

    NetWorker(SSLSocket socket, LoginInfo loginInfo) throws IOException {
        this.socket = socket;
        this.loginInfo = loginInfo;
        this.in  = new BufferedReader(new InputStreamReader(socket.getInputStream(), "UTF-8"));
        this.out = new BufferedWriter(new OutputStreamWriter(socket.getOutputStream(), "UTF-8"));
    }

    /** 启动读写线程 */
    void start() {
        // ① 发送登录控制消息
        executor.submit(this::writeLoop);
        executor.submit(this::readLoop);
        sendLogin();
    }

    private void sendLogin() {
        Message login = new Message();
        login.type = Message.Type.CTRL;
        login.from = loginInfo.userId;
        login.to   = "server";
        login.payload = loginInfo.isAgent ? "agent" : "user";
        sendQueue.offer(login);
    }

    /** 将 Message 放入发送队列，供 UI 调用 */
    void send(Message msg) {
        sendQueue.offer(msg);
    }

    /** 读取线程（阻塞） */
    private void readLoop() {
        try {
            String line;
            while ((line = in.readLine()) != null) {
                Message msg = Message.fromJson(line);
                // 把消息投递到 UI 线程（EDT）
                SwingUtilities.invokeLater(() -> ChatWindow.dispatchMessage(msg));
            }
        } catch (Exception e) {
            e.printStackTrace();
            // TODO: 连接异常 UI 通知
        } finally {
            close();
        }
    }

    /** 写入线程：从 sendQueue 中取出消息并写出 */
    private void writeLoop() {
        try {
            while (!socket.isClosed()) {
                Message msg = sendQueue.take(); // 阻塞
                out.write(msg.toJson());
                out.newLine();
                out.flush();
            }
        } catch (InterruptedException ignored) {
        } catch (Exception e) {
            e.printStackTrace();
        } finally {
            close();
        }
    }

    void close() {
        try { socket.close(); } catch (IOException ignore) {}
        executor.shutdownNow();
    }
}

