import java.util.concurrent.ForkJoinPool;
import java.util.concurrent.RecursiveAction;
import java.util.concurrent.ThreadLocalRandom;

public class QuickSortMultithreaded extends RecursiveAction {

    private static final long serialVersionUID = 1L;

    private final int[] array;
    private final int low;
    private final int high;

    /**
     * Creates a new QuickSort task.
     *
     * @param array the array to sort
     * @param low   starting index (inclusive)
     * @param high  ending index (inclusive)
     */
    public QuickSortMultithreaded(int[] array, int low, int high) {
        this.array = array;
        this.low   = low;
        this.high  = high;
    }

    /** Entry point for the Fork/Join framework. */
    @Override
    protected void compute() {
        // Base case – a segment of length 0 or 1 is already sorted
        if (low >= high) {
            return;
        }

        // Partition the current segment and obtain the pivot position
        int pivotIndex = partition(array, low, high);

        // Create subtasks for the left and right partitions
        QuickSortMultithreaded leftTask  = new QuickSortMultithreaded(array, low, pivotIndex - 1);
        QuickSortMultithreaded rightTask = new QuickSortMultithreaded(array, pivotIndex + 1, high);

        // Execute subtasks – we fork the smaller one to keep the recursion tree shallow
        if ((pivotIndex - low) < (high - pivotIndex)) {
            leftTask.fork();         // run left side in a separate thread
            rightTask.compute();     // compute right side in the current thread
            leftTask.join();         // wait for left side to finish
        } else {
            rightTask.fork();
            leftTask.compute();
            rightTask.join();
        }
    }

    /**
     * Lomuto‑style partition that chooses a random pivot,
     * moves it to the end of the segment and then partitions
     * the array around that pivot.
     *
     * @return the final index of the pivot after partitioning
     */
    private static int partition(int[] arr, int low, int high) {
        // Choose a random pivot index in [low, high]
        int pivotIdx = ThreadLocalRandom.current().nextInt(low, high + 1);
        // Move the pivot to the end (position 'high')
        swap(arr, pivotIdx, high);

        int pivot = arr[high];
        int i = low;       // will track the boundary of elements < pivot

        for (int j = low; j < high; j++) {
            if (arr[j] <= pivot) {
                swap(arr, i, j);
                i++;
            }
        }

        // Place pivot in its final sorted location
        swap(arr, i, high);
        return i;
    }

    /** Simple utility to swap two elements in an array. */
    private static void swap(int[] arr, int i, int j) {
        if (i == j) {
            return;                 // no work required
        }
        int tmp = arr[i];
        arr[i]   = arr[j];
        arr[j]   = tmp;
    }

    /* ------------------------------------------------------------------ */
    /*  Driver / test harness                                               */
    /* ------------------------------------------------------------------ */
    public static void main(String[] args) {
        int[] data = {54, 64, 95, 82, 12, 32, 63};

