    private static final long MAX_IMAGE_SIZE = 10L * 1024 * 1024; // 10 MB

    public static void main(String[] args) throws Exception {
        if (args.length < 2) {
            System.out.println("Usage: java ImageSenderClient <host> <port> <image1> [<image2> ...]");
            return;
        }

        String host = args[0];
        int port = Integer.parseInt(args[1]);
        List<Path> images = new ArrayList<>();
        for (int i = 2; i < args.length; i++) {
            images.add(Paths.get(args[i]));
        }

        // 建立普通 TCP 连接（若要 TLS，请使用 SSLSocketFactory）
        try (Socket socket = new Socket(host, port);
             DataOutputStream out = new DataOutputStream(new BufferedOutputStream(socket.getOutputStream()))) {

            // 1️⃣ 发送图片数量（int）
            out.writeInt(images.size());

            for (Path imgPath : images) {
                // 2️⃣ 文件名（UTF‑8）+ 长度
                String fileName = imgPath.getFileName().toString(); // 仅文件名，不含路径
                byte[] nameBytes = fileName.getBytes(StandardCharsets.UTF_8);
                if (nameBytes.length > 65535) {
                    throw new IllegalArgumentException("Filename too long: " + fileName);
                }
                out.writeShort(nameBytes.length);
                out.write(nameBytes);

                // 3️⃣ 文件大小（long）
                long fileSize = Files.size(imgPath);
                if (fileSize > MAX_IMAGE_SIZE) {
                    throw new IllegalArgumentException("File too large (> " + MAX_IMAGE_SIZE + "): " + imgPath);
                }
                out.writeLong(fileSize);

                // 4️⃣ 发送文件内容
                try (InputStream fileIn = Files.newInputStream(imgPath)) {
                    byte[] buffer = new byte[8192];
                    long left = fileSize;
                    while (left > 0) {
                        int read = fileIn.read(buffer, 0, (int) Math.min(buffer.length, left));
                        if (read == -1) break;
                        out.write(buffer, 0, read);
                        left -= read;
                    }
                }

                System.out.println("Sent image: " + imgPath);
            }

            out.flush(); // 确保所有字节写出
            System.out.println("All images sent, closing connection.");
        }
    }
}
```

