                line = console.readLine();

                // Build and send the packet
                Packet packet = new Packet(serialNo++, line);
                oos.writeObject(packet);
                oos.flush();

                // Receive the ACK packet from the server
                Packet response = (Packet) ois.readObject();

                System.out.println("FROM SERVER:Packet SerialNo#" + response.getSerialNo()
                        + " is recieved");

                if ("CLOSE".equalsIgnoreCase(line)) {
                    break;      // stop the loop after the server has already ACKed
                }
            }

        } catch (IOException | ClassNotFoundException e) {
            e.printStackTrace();
        }
    }
}
