```java
import jakarta.websocket.*;
import java.io.*;
import java.net.URI;
import java.nio.ByteBuffer;
import java.security.SecureRandom;
import java.util.Base64;
import java.util.concurrent.CountDownLatch;
import java.util.concurrent.TimeUnit;

@ClientEndpoint
public class ImageWebSocketClient {

    private Session session;
    private final CountDownLatch closeLatch = new CountDownLatch(1);
    private static final int MAX_IMAGE_SIZE = 10 * 1024 * 1024; // 10 MiB – adjust to your policy

    @OnOpen
    public void onOpen(Session session) {
        System.out.println("WebSocket opened: " + session.getId());
        this.session = session;
    }

    @OnMessage
    public void onMessage(String txt) {
        // Handle textual control messages (e.g., ACK, error codes)
        System.out.println("Server: " + txt);
    }

    @OnError
    public void onError(Session session, Throwable thr) {
        System.err.println("WebSocket error: " + thr);
    }

    @OnClose
    public void onClose(Session session, CloseReason reason) {
        System.out.println("WebSocket closed: " + reason);
        closeLatch.countDown();
    }

    /**
     * Sends the supplied image bytes as a binary frame.
     * Will fragment automatically if the underlying implementation supports it.
     */
    public void sendImage(byte[] imageBytes) throws IOException {
        if (imageBytes == null) {
            throw new IllegalArgumentException("imageBytes must not be null");
        }
        if (imageBytes.length > MAX_IMAGE_SIZE) {
            throw new IllegalArgumentException(
                "Image size (" + imageBytes.length + " bytes) exceeds the max allowed " + MAX_IMAGE_SIZE);
        }
        // Using ByteBuffer to avoid copying the array internally
        ByteBuffer payload = ByteBuffer.wrap(imageBytes);
        session.getBasicRemote().sendBinary(payload);
        System.out.println("Image (" + imageBytes.length + " bytes) sent.");
    }

    /** Graceful shutdown */
    public void close() throws IOException, InterruptedException {
        if (session != null && session.isOpen()) {
            session.close();
            // Wait for onClose latch (max 5 s)
            closeLatch.await(5, TimeUnit.SECONDS);
        }
    }

    /** Helper: loads an image from the filesystem safely */
    public static byte[] loadImage(Path path) throws IOException {
        long size = Files.size(path);
        if (size > MAX_IMAGE_SIZE) {
            throw new IOException("File too large for allowed limit");
        }
        // Use a bounded stream to guard against truncated reads
        try (InputStream in = Files.newInputStream(path);
             ByteArrayOutputStream out = new ByteArrayOutputStream((int) size)) {
            byte[] buf = new byte[8192];
            int read;
            while ((read = in.read(buf)) != -1) {
                out.write(buf, 0, read);
            }
            return out.toByteArray();
        }
    }

    /** Entry point – simple demo */
    public static void main(String[] args) throws Exception {
        if (args.length != 1) {
            System.err.println("Usage: java ImageWebSocketClient <path-to-image>");
            System.exit(1);
