## 6. 核心业务 `SocketServerService.java`

> 关键点：  
> - **启动/关闭线程安全**（使用 `@PostConstruct` / `@PreDestroy`）  
> - **线程池**：`Executors.newFixedThreadPool` 与 **Guava RateLimiter** 防止连接洪水  
> - **异常捕获**：防止单个错误导致服务崩溃  
> - **资源释放**：`ServerSocket` 与 `Socket` 必须在 finally 中关闭  
> - **TLS**（可选）示例：`SSLServerSocketFactory`  

```java
package com.example.socketreceiver.service;

import com.example.socketreceiver.config.SocketServerConfig;
import com.google.common.util.concurrent.RateLimiter;
import jakarta.annotation.PostConstruct;
import jakarta.annotation.PreDestroy;
import lombok.extern.slf4j.Slf4j;

import org.springframework.stereotype.Service;

import javax.net.ssl.*;
import java.io.*;
import java.net.*;
import java.nio.charset.StandardCharsets;
import java.security.KeyStore;
import java.util.Collections;
import java.util.Set;
import java.util.concurrent.*;

@Slf4j
@Service
public class SocketServerService {

    private final SocketServerConfig config;
    private ServerSocket serverSocket;
    private final ExecutorService clientPool;
    private final Set<Socket> activeSockets = Collections.newSetFromMap(new ConcurrentHashMap<>());

    /** 每秒允许的最大新连接数（防暴力连接） */
    private final RateLimiter connectionRateLimiter;

    public SocketServerService(SocketServerConfig config) {
        this.config = config;
        this.clientPool = Executors.newFixedThreadPool(
                Math.max(2, Runtime.getRuntime().availableProcessors()));
        this.connectionRateLimiter = RateLimiter.create(config.getMaxClientConnections() / 10.0);
        // 例如：maxClientConnections=500 → 每秒最多接受 50 条新连接
    }

    /** Spring 启动后自动打开 ServerSocket */
    @PostConstruct
    public void start() {
        try {
            if (config.isEnableTls()) {
                this.serverSocket = createSslServerSocket();
                log.info("[TLS] Socket Server started on {} (TLS enabled)", config.getPort());
            } else {
                this.serverSocket = new ServerSocket();
                this.serverSocket.bind(new InetSocketAddress(config.getPort()), config.getBacklog());
                this.serverSocket.setSoTimeout(config.getAcceptTimeoutMs());
                log.info("[Plain] Socket Server started on {}", config.getPort());
            }

            // 启动 accept 循环线程（单独线程，避免阻塞 Spring）
            Thread acceptThread = new Thread(this::acceptLoop, "Socket-Accept-Thread");
            acceptThread.setDaemon(true);
            acceptThread.start();

        } catch (IOException e) {
            log.error("Failed to start socket server on port {}: {}", config.getPort(), e.getMessage(), e);
            // 这里可以选择立即退出或继续运行（视业务需求而定）
            throw new IllegalStateException(e);
        }
    }

    /** 关闭 ServerSocket 与线程池 */
    @PreDestroy
    public void stop() {
        try {
            log.info("Shutting down socket server...");
            if (serverSocket != null && !serverSocket.isClosed()) {
                serverSocket.close(); // 会导致 accept() 抛出 SocketException，循环退出
            }
            clientPool.shutdownNow();
            // 关闭所有活跃客户端连接
            for (Socket s : activeSockets) {
                try {
                    s.close();
                } catch (IOException ignored) {}
            }
            log.info("Socket server stopped.");
        } catch (IOException e) {
            log.warn("Error while shutting down socket server: {}", e.getMessage(), e);
        }
    }

    /** 接受新连接的主循环 */
    private void acceptLoop() {
        while (!serverSocket.isClosed()) {
            try {
                // **限速**：如果当前速率超过阈值，直接拒绝连接
                if (!connectionRateLimiter.tryAcquire(1, TimeUnit.SECONDS)) {
                    log.warn("Connection rate limit exceeded, rejecting new client");
                    // 拒绝策略：直接 accept 并立即关闭
                    Socket tmp = serverSocket.accept();
                    tmp.close();
                    continue;
                }

                Socket client = serverSocket.accept();
                log.info("New client connected: {}:{}", client.getRemoteSocketAddress(),
                         client.getPort());

                // 防止激活过多连接（更细粒度的并发控制）
                if (activeSockets.size() >= config.getMaxClientConnections()) {
                    log.warn("Too many concurrent clients ({}), rejecting {}", activeSockets.size(),
                             client.getRemoteSocketAddress());
                    client.close();
                    continue;
                }

                // 设置 socket 参数（防止长时间阻塞）
                client.setSoTimeout(config.getReadTimeoutMs());
                client.setTcpNoDelay(true);
                activeSockets.add(client);

                clientPool.submit(() -> handleClient(client));

            } catch (SocketTimeoutException e) {
                // Accept 超时是一种正常现象，只是让循环有机会检查 shutdown 标志
                continue;
            } catch (SocketException e) {
                // serverSocket 被关闭后会抛出异常，退出循环
                if (serverSocket.isClosed()) {
                    log.info("Server socket closed, terminating accept loop.");
                } else {
                    log.error("SocketException in accept loop: {}", e.getMessage(), e);
                }
                break;
            } catch (IOException e) {
                log.error("IOException while accepting client: {}", e.getMessage(), e);
            }
        }
    }

    /** 处理单个客户端的业务 */
    private void handleClient(Socket client) {
        try (InputStream in = client.getInputStream();
             OutputStream out = client.getOutputStream()) {

            // 简单协议示例：每行数据为一条消息（UTF-8 编码）
            BufferedReader reader = new BufferedReader(new InputStreamReader(in, StandardCharsets.UTF_8));
            BufferedWriter writer = new BufferedWriter(new OutputStreamWriter(out, StandardCharsets.UTF_8));

            String line;
            while ((line = reader.readLine()) != null) {
                // ---------- 安全检查 ----------
                // 1️⃣ 过滤非法字符（仅示例，实际根据业务规则）
                if (line.contains("\0") || line.length() > 4096) {
                    log.warn("Received malformed message from {}: {}", client.getRemoteSocketAddress(), line);
                    writer.write("ERROR: Malformed message\r\n");
                    writer.flush();
                    continue;
                }

                // 2️⃣ 防止命令注入、SQL 注入等（此示例只做日志）
                log.info("Received from {}: {}", client.getRemoteSocketAddress(), line);

                // ---------- 业务逻辑 ----------
                // 这里可以把数据转发给其它系统、入库、写文件等
                String response = processMessage(line);
                writer.write(response);
                writer.flush();
            }

        } catch (SocketTimeoutException e) {
            log.info("Read timeout from {}: {}", client.getRemoteSocketAddress(), e.getMessage());
        } catch (IOException e) {
            log.warn("I/O error with client {}: {}", client.getRemoteSocketAddress(), e.getMessage(), e);
        } finally {
            // 清理资源
            try {
                client.close();
            } catch (IOException ignored) {}
            activeSockets.remove(client);
            log.info("Client {} disconnected, active clients: {}", client.getRemoteSocketAddress(),
                     activeSockets.size());
        }
    }

    /** 简单的业务处理（示例） */
    private String processMessage(String msg) {
        // 这里演示一个“回显 + 时间戳”的业务
        String timestamp = java.time.Instant.now().toString();
        return "ECHO [" + timestamp + "]: " + msg + "\r\n";
    }

    /** 若打开 TLS，需要使用自签/CA 证书创建 SSLServerSocket */
    private SSLServerSocket createSslServerSocket() throws IOException {
        try {
            // 加载 keystore（建议使用 JKS/PKCS12）
            KeyStore ks = KeyStore.getInstance(config.getKeystore().getType());
            try (InputStream ksStream = getClass().getResourceAsStream(
                    config.getKeystore().getPath())) {
                if (ksStream == null) {
                    throw new FileNotFoundException("Keystore not found: " + config.getKeystore().getPath());
                }
                ks.load(ksStream, config.getKeystore().getPassword().toCharArray());
            }

            // 初始化 KeyManagerFactory
            KeyManagerFactory kmf = KeyManagerFactory.getInstance(KeyManagerFactory.getDefaultAlgorithm());
            kmf.init(ks, config.getKeystore().getPassword().toCharArray());

            // 初始化 SSLContext
            SSLContext sslCtx = SSLContext.getInstance("TLSv1.3");
            sslCtx.init(kmf.getKeyManagers(), null, null);

            SSLServerSocketFactory factory = sslCtx.getServerSocketFactory();
            SSLServerSocket sslServerSocket = (SSLServerSocket) factory.createServerSocket(
                    config.getPort(), config.getBacklog());

            // 可选：强制使用安全套件
            sslServerSocket.setEnabledProtocols(new String[]{"TLSv1.3"});
            sslServerSocket.setEnabledCipherSuites(sslServerSocket.getSupportedCipherSuites());

            sslServerSocket.setSoTimeout(config.getAcceptTimeoutMs());
            return sslServerSocket;

        } catch (Exception e) {
            log.error("Failed to create SSL ServerSocket: {}", e.getMessage(), e);
            throw new IOException("SSL initialization error", e);
        }
    }
}
