package com.example.util;

import java.text.MessageFormat;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

public final class QuestionPlaceholderUtil {

    private QuestionPlaceholderUtil() {}

    /** ----------- 方式 1：MessageFormat 版 ----------- */
    public static String replaceWithMessageFormat(String template, Object... args) {
        // Convert "?N" -> "{N-1}"
        String converted = template.replaceAll("\\?(\\d+)", m -> {
            int idx = Integer.parseInt(m.group(1)) - 1;
            return "{" + idx + "}";
        });
        return MessageFormat.format(converted, args);
    }

    /** ----------- 方式 2：正则手工版 ----------- */
    private static final Pattern QUESTION_PATTERN = Pattern.compile("\\?(\\d+)");
    public static String replaceWithRegex(String source, Object... args) {
        if (source == null) return null;
        Matcher matcher = QUESTION_PATTERN.matcher(source);
        StringBuffer sb = new StringBuffer();
        while (matcher.find()) {
            int idx = Integer.parseInt(matcher.group(1)) - 1;
            String repl = (idx >= 0 && idx < args.length)
                    ? Matcher.quoteReplacement(String.valueOf(args[idx]))
                    : matcher.group(); // keep original if out‑of‑range
            matcher.appendReplacement(sb, repl);
        }
        matcher.appendTail(sb);
        return sb.toString();
    }
}
```

