## 3. Servlet Implementation (Security‑Focused)

```java
package com.example.servlet;

import com.fasterxml.jackson.databind.ObjectMapper;
import jakarta.servlet.ServletException;
import jakarta.servlet.annotation.WebInitParam;
import jakarta.servlet.annotation.WebServlet;
import jakarta.servlet.http.HttpServlet;
import jakarta.servlet.http.HttpServletRequest;
import jakarta.servlet.http.HttpServletResponse;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

import java.io.IOException;
import java.math.BigDecimal;
import java.math.RoundingMode;
import java.util.Collections;
import java.util.Map;
import java.util.regex.Pattern;

/**
 * Temperature conversion & comparison servlet.
 *
 * <p>
 *   Endpoint: {@code POST /temp/compare}
 *   <br>
 *   Content-Type: {@code application/json}
 *   <br>
 *   Request body example:
 *   <pre>
 *   {
 *     "value": "37.0",
 *     "scale": "C",          // or "F"
 *     "compareTo": "100",    // value to compare against
 *     "compareScale": "F"    // scale of the compare value
 *   }
 *   </pre>
 * </p>
 *
 * <p>All inputs are strictly validated, JSON is parsed with Jackson (fails fast) and
 * the response is a well‑formed JSON document.  Errors are reported with generic
 * messages to avoid leaking internal details.</p>
 */
@WebServlet(
    urlPatterns = {"/temp/compare"},
    initParams = {
        @WebInitParam(name = "maxPayloadSize", value = "8192") // 8 KB limit
    }
)
public class TemperatureCompareServlet extends HttpServlet {

    private static final long serialVersionUID = 1L;
    private static final Logger LOG = LoggerFactory.getLogger(TemperatureCompareServlet.class);
    private static final ObjectMapper MAPPER = new ObjectMapper();

    /** Whitelist for scale values (case‑insensitive). */
    private static final Pattern SCALE_PATTERN = Pattern.compile("^[CFcf]$");

    /** Max length of any string field (prevent log‑injection & memory abuse). */
    private static final int MAX_FIELD_LENGTH = 32;

    /** Payload size limit (read from init‑param). */
    private int maxPayloadSize = 8 * 1024; // default 8 KB

    @Override
    public void init() throws ServletException {
        String cfg = getServletConfig().getInitParameter("maxPayloadSize");
        if (cfg != null) {
            try {
                maxPayloadSize = Integer.parseInt(cfg);
            } catch (NumberFormatException e) {
                LOG.warn("Invalid maxPayloadSize init param '{}', using default 8KB", cfg);
            }
        }
        LOG.info("TemperatureCompareServlet initialised – max payload: {} bytes", maxPayloadSize);
    }

    /** Data‑transfer object used only inside the servlet – immutable for safety. */
    private static final class TempRequest {
        final BigDecimal value;
        final char scale;            // 'C' or 'F'
        final BigDecimal compareTo;
        final char compareScale;     // 'C' or 'F'

        TempRequest(BigDecimal value, char scale,
                    BigDecimal compareTo, char compareScale) {
            this.value = value;
            this.scale = scale;
            this.compareTo = compareTo;
            this.compareScale = compareScale;
        }
    }

    @Override
    protected void doPost(HttpServletRequest req,
                          HttpServletResponse resp) throws ServletException, IOException {

        // --------------------------------------------------------------------
        // 1️⃣ Enforce Content-Type + HTTPS (if not already forced by front‑end)
        // --------------------------------------------------------------------
        if (!"application/json".equalsIgnoreCase(req.getContentType())) {
            resp.sendError(HttpServletResponse.SC_UNSUPPORTED_MEDIA_TYPE,
                    "Only application/json is accepted");
            return;
        }

        // Optional: if you control the web server, enforce HTTPS via redirect
        // if (!req.isSecure()) { resp.sendRedirect("https://" + req.getServerName() + req.getRequestURI()); return; }

        // -------------------------------------------------------------
        // 2️⃣ Safely read the body with a size guard (prevent OOM attacks)
        // -------------------------------------------------------------
        if (req.getContentLengthLong() > maxPayloadSize) {
            resp.sendError(HttpServletResponse.SC_REQUEST_ENTITY_TOO_LARGE,
                    "Payload exceeds the allowed size");
            return;
        }

        // Read into a bounded byte array (maxPayloadSize+1 helps detect overflow)
        byte[] buffer = new byte[maxPayloadSize + 1];
        int bytesRead = req.getInputStream().readNBytes(buffer, 0, maxPayloadSize + 1);
        if (bytesRead > maxPayloadSize) {
            resp.sendError(HttpServletResponse.SC_REQUEST_ENTITY_TOO_LARGE,
                    "Payload exceeds the allowed size");
            return;
        }
        // Trim to actual length
        byte[] payload = (bytesRead == buffer.length) ? buffer : java.util.Arrays.copyOf(buffer, bytesRead);
        String json = new String(payload, java.nio.charset.StandardCharsets.UTF_8).trim();

        // ------------------------------
        // 3️⃣ Parse & validate JSON input
        // ------------------------------
        TempRequest request;
        try {
            @SuppressWarnings("unchecked")
            Map<String, Object> map = MAPPER.readValue(json, Map.class);
            request = validateAndConvert(map);
        } catch (Exception e) {
            LOG.warn("Invalid JSON payload: {}", sanitizeLog(json));
            resp.sendError(HttpServletResponse.SC_BAD_REQUEST, "Malformed request");
            return;
        }

        // --------------------
        // 4️⃣ Perform conversion
        // --------------------
        BigDecimal inputInCelsius = request.scale == 'C' ?
                request.value :
                fahrenheitToCelsius(request.value);

        BigDecimal compareInCelsius = request.compareScale == 'C' ?
                request.compareTo :
                fahrenheitToCelsius(request.compareTo);

        int comparison = inputInCelsius.compareTo(compareInCelsius); // -1, 0, 1

        // -------------------------------------------------
        // 5️⃣ Build a **JSON** response (no HTML, no XSS risk)
        // -------------------------------------------------
        resp.setContentType("application/json;charset=UTF-8");
        resp.setCharacterEncoding("UTF-8");

        Map<String, Object> responseBody = Map.of(
                "value", request.value,
                "scale", String.valueOf(request.scale),
                "valueInCelsius", round(inputInCelsius),
                "valueInFahrenheit", round(celsiusToFahrenheit(inputInCelsius)),
                "compareTo", request.compareTo,
                "compareScale", String.valueOf(request.compareScale),
                "compareInCelsius", round(compareInCelsius),
                "compareInFahrenheit", round(celsiusToFahrenheit(compareInCelsius)),
                "comparison", comparisonToString(comparison) // "greater", "equal", "less"
        );

        MAPPER.writeValue(resp.getOutputStream(), responseBody);
    }

    // --------------------------------------------------------------------
    // Helper methods – each one is deliberately small, pure, and unit‑testable
    // --------------------------------------------------------------------

    /** Validate raw JSON map & convert to a typed request object. */
    private TempRequest validateAndConvert(Map<String, Object> raw) throws IllegalArgumentException {
        // Helper to fetch, trim, and enforce max length
        String getString(String key) {
            Object o = raw.get(key);
            if (o == null) throw new IllegalArgumentException("Missing key: " + key);
            String s = o.toString().trim();
            if (s.length() > MAX_FIELD_LENGTH) throw new IllegalArgumentException(key + " too long");
            return s;
        }

        // 1️⃣ value
        String valueStr = getString("value");
        BigDecimal value = parseBigDecimal(valueStr, "value");

        // 2️⃣ scale (C or F)
        String scaleStr = getString("scale");
        if (!SCALE_PATTERN.matcher(scaleStr).matches())
            throw new IllegalArgumentException("Invalid scale");
        char scale = Character.toUpperCase(scaleStr.charAt(0));

        // 3️⃣ compareTo
        String compareStr = getString("compareTo");
        BigDecimal compare = parseBigDecimal(compareStr, "compareTo");

        // 4️⃣ compareScale
        String compareScaleStr = getString("compareScale");
        if (!SCALE_PATTERN.matcher(compareScaleStr).matches())
            throw new IllegalArgumentException("Invalid compareScale");
        char compareScale = Character.toUpperCase(compareScaleStr.charAt(0));

        return new TempRequest(value, scale, compare, compareScale);
    }

    /** Sanitise strings before logging (breaks new‑lines, limits length). */
    private static String sanitizeLog(String input) {
        if (input == null) return "";
        // Remove CR/LF and truncate to a safe length
        String sanitized = input.replaceAll("[\\r\\n]", "").trim();
        return sanitized.length() > 200 ? sanitized.substring(0, 200) + "…" : sanitized;
    }

    /** Parse a numeric value with strict range checking. */
    private static BigDecimal parseBigDecimal(String s, String field) {
        try {
            // Use BigDecimal for arbitrary precision, then limit scale to 4 decimal places
            return new BigDecimal(s).setScale(4, RoundingMode.HALF_UP);
        } catch (NumberFormatException | ArithmeticException e) {
            throw new IllegalArgumentException("Invalid numeric value for " + field);
        }
    }

    /** Celsius → Fahrenheit (precise, no floating point errors). */
    private static BigDecimal celsiusToFahrenheit(BigDecimal c) {
        // (C × 9/5) + 32
        return c.multiply(BigDecimal.valueOf(9))
                .divide(BigDecimal.valueOf(5), 10, RoundingMode.HALF_UP)
                .add(BigDecimal.valueOf(32));
    }

    /** Fahrenheit → Celsius */
    private static BigDecimal fahrenheitToCelsius(BigDecimal f) {
        // (F – 32) × 5/9
        return f.subtract(BigDecimal.valueOf(32))
                .multiply(BigDecimal.valueOf(5))
                .divide(BigDecimal.valueOf(9), 10, RoundingMode.HALF_UP);
    }

    /** Round to two decimal places for display (still keeps internal precision). */
    private static BigDecimal round(BigDecimal bd) {
        return bd.setScale(2, RoundingMode.HALF_UP);
    }

    /** Human‑readable comparison result. */
    private static String comparisonToString(int cmp) {
        return switch (cmp) {
            case -1 -> "less";
            case 0 -> "equal";
            case 1 -> "greater";
            default -> "unknown";
        };
    }
}
```

### What Makes This Servlet **Secure**?

| # | Security Concern | How It Is Handled |
|---|-------------------|-------------------|
| **1** | **Content‑type enforcement** | Returns `415 Unsupported Media Type` if request isn’t JSON. |
| **2** | **Payload size / DoS** | `maxPayloadSize` (default 8 KB) protects against memory exhaustion; request body read into a bounded buffer. |
| **3** | **JSON parsing** | Jackson’s “fail‑fast” mode (`readValue`) throws on malformed JSON; errors are logged with sanitised output. |
| **4** | **Input validation** | <ul><li>Scale values restricted to the whitelist `{C,F}` (case‑insensitive).</li><li>String fields limited to 32 characters.</li><li>Numerics parsed with `BigDecimal` and forced to 4‑decimal‑place scale.</li></ul> |
| **5** | **Numeric overflow / precision attacks** | `BigDecimal` has virtually unlimited range; we later round to a **display** scale (2 decimals) but keep internal precision for accurate comparison. |
| **6** | **Logging safety** | `sanitizeLog()` strips CR/LF characters and caps length, preventing log injection/poisoning. |
| **7** | **Error handling / info leakage** | Generic messages (`400 Bad Request`, `415`, `413`, `500`) are sent to the client; server stack traces are **never** exposed. |
| **8** | **Cross‑Site Scripting (XSS)** | Response is pure JSON (`application/json`). No HTML is rendered, eliminating reflected XSS vectors. |
| **9** | **HTTP Header Injection** | No user‑controlled values are echoed into HTTP headers. |
| **10** | **CSRF** | The endpoint is read‑only (`POST` used for convenience but could be `GET`). For state‑changing APIs, include a CSRF token (example code omitted for brevity). |
| **11** | **Transport security** | While the servlet itself cannot enforce TLS, we add a commented snippet for an HTTPS redirect and recommend using `Strict-Transport-Security` at the proxy/reverse‑proxy level. |
| **12** | **Dependency hygiene** | Use **Jackson 2.15+** (no known critical CVEs) and the **current Jakarta Servlet API (5.x)**. Keep dependencies up‑to‑date with tools like `OWASP Dependency‑Check`. |

