Below is a **complete, self‑contained example** of a tiny “database” that stores arbitrary Java objects in a `java.util.Hashtable` and persists the whole table to disk by using **Java serialization**.  

It is written to be **readable** (lots of comments) and **secure‑by‑design** – i.e. it shows the most common pitfalls of using Java serialization and how you can mitigate them.

---

## 1️⃣ Overview

| Feature | Description |
|--------|--------------|
| **In‑memory store** | `Hashtable<String, Serializable>` – thread‑safe, fast O(1) look‑ups. |
| **Persistence** | `save(String file)` and `load(String file)` – write/read the whole table via `ObjectOutputStream`/`ObjectInputStream`. |
| **CRUD API** | `put(key,obj)`, `get(key)`, `remove(key)`, `contains(key)`, `size()`. |
| **Security hardening** | <ul><li>Signed & encrypted payload (optional).</li><li>Whitelist‑based deserialization (avoid “gadget” attacks).</li><li>File permissions & atomic replace.</li><li>Input validation on keys.</li></ul> |
| **Extensibility** | Plug‑in `Serializer` interface for alternative formats (JSON, protobuf, …). |

---

## 2️⃣ Source Code

```java
package com.example.minidb;

import java.io.*;
import java.nio.file.*;
import java.security.*;
import java.security.spec.*;
import java.util.Hashtable;
import java.util.Objects;
import java.util.Set;
import java.util.logging.Level;
import java.util.logging.Logger;
import javax.crypto.*;
import javax.crypto.spec.SecretKeySpec;

/**
 * MiniDB – a tiny, thread‑safe key/value store that can be persisted to a file.
 *
 * <p><b>Security note:</b> Java native serialization is convenient but historically
 * vulnerable to deserialization attacks (e.g. arbitrary code execution via
 * gadget chains).  This implementation mitigates the risk by:
 *
 * <ul>
 *   <li>Accepting only objects that implement {@link java.io.Serializable}.</li>
 *   <li>Optionally encrypting the serialized bytes with a strong symmetric key.</li>
 *   <li>Whitelisting permitted classes during deserialization (see {@link #ALLOWED_CLASSES}).</li>
 *   <li>Writing to a temporary file then atomically moving it to the target path.</li>
 * </ul>
 *
 * <p>If you need stronger guarantees (e.g. signed data, integrity checks) you can
 * extend the {@code encrypt()} / {@code decrypt()} methods or plug‑in a custom
 * {@link Serializer}.
 */
public final class MiniDB implements Closeable {

    // -----------------------------------------------------------------------
    // Configuration – adjust to your threat model
    // -----------------------------------------------------------------------
    /** Set of fully‑qualified class names that we allow to be deserialized.
     *  Add your own domain classes here. */
    private static final Set<String> ALLOWED_CLASSES = Set.of(
            "java.lang.String",
            "java.lang.Integer",
            "java.lang.Long",
            "java.lang.Double",
            "java.util.ArrayList",
            "java.util.HashMap",
            // add your own POJOs, e.g. "com.example.model.User"
            "com.example.minidb.SamplePayload"
    );

    /** Symmetric encryption algorithm used for at‑rest protection.
     *  Change to AES/GCM/NoPadding for authenticated encryption. */
    private static final String CIPHER_ALGO = "AES";

    /** Size of the secret key in bytes (256‑bit is recommended, requires JCE Unlimited Strength). */
    private static final int KEY_SIZE_BYTES = 32;

    // -----------------------------------------------------------------------
    // Private fields
    // -----------------------------------------------------------------------
    private final Hashtable<String, Serializable> store = new Hashtable<>();
    private final Path filePath;                     // where the DB lives on disk
    private final SecretKey encryptionKey;           // can be null → no encryption
    private final Logger logger = Logger.getLogger(MiniDB.class.getName());

    // -----------------------------------------------------------------------
    // Constructors
    // -----------------------------------------------------------------------
    /**
     * Creates a MiniDB that persists to {@code filePath}.
     *
     * @param filePath       location of the DB file (will be created if missing)
     * @param encryptionKey  optional 256‑bit key for AES encryption; pass {@code null}
     *                        for plain‑text storage (not recommended for production)
     * @throws IOException   if the file cannot be created / accessed
     */
    public MiniDB(Path filePath, byte[] encryptionKey) throws IOException {
        Objects.requireNonNull(filePath, "filePath cannot be null");
        this.filePath = filePath.toAbsolutePath();

        // Ensure the parent directory exists and is not world‑writable
        Files.createDirectories(this.filePath.getParent());
        setFilePermissions(this.filePath);

        if (encryptionKey != null) {
            if (encryptionKey.length != KEY_SIZE_BYTES) {
                throw new IllegalArgumentException(
                        "Encryption key must be exactly " + KEY_SIZE_BYTES + " bytes");
            }
            this.encryptionKey = new SecretKeySpec(encryptionKey, CIPHER_ALGO);
        } else {
            this.encryptionKey = null;
        }

        // Load existing data if the file already exists
        if (Files.exists(this.filePath)) {
            load();
        }
    }

    /** Convenience overload – no encryption (plain‑text). */
    public MiniDB(Path filePath) throws IOException {
        this(filePath, null);
    }

    // -----------------------------------------------------------------------
    // Public CRUD API
    // -----------------------------------------------------------------------
    /** Stores a value under the given key. Overwrites any existing entry. */
    public void put(String key, Serializable value) {
        validateKey(key);
        Objects.requireNonNull(value, "value cannot be null");
        store.put(key, value);
    }

    /** Retrieves the value for the given key, or {@code null} if absent. */
    public Serializable get(String key) {
        validateKey(key);
        return store.get(key);
    }

    /** Removes the entry for {@code key} and returns the former value (or {@code null}). */
    public Serializable remove(String key) {
        validateKey(key);
        return store.remove(key);
    }

    /** Returns {@code true} if the store contains the given key. */
    public boolean contains(String key) {
        validateKey(key);
        return store.containsKey(key);
    }

    /** Number of entries currently stored. */
    public int size() {
        return store.size();
    }

