        byte[] payload = (encryptionKey != null) ? encrypt(rawBytes) : rawBytes;

        // Write atomically: tmp → final
        Path tmp = Files.createTempFile(filePath.getParent(), "minidb", ".tmp");
        try (OutputStream out = Files.newOutputStream(tmp, StandardOpenOption.WRITE)) {
            out.write(payload);
        }

        // Atomic move replaces any previous file (POSIX guarantees atomicity on same FS)
        Files.move(tmp, filePath, StandardCopyOption.REPLACE_EXISTING, StandardCopyOption.ATOMIC_MOVE);
