            logger.info("MiniDB loaded (" + store.size() + " entries)");
        } catch (ClassNotFoundException e) {
            logger.log(Level.SEVERE, "Failed to resolve class during deserialization", e);
            throw new IOException(e);
        } catch (InvalidClassException | StreamCorruptedException e) {
