        String hashed = BCrypt.hashpw(password, BCrypt.gensalt(BCRYPT_COST));
        users.put(username, new User(username, hashed));
        return Response.ok("REGISTERED");
    }

    // ---- 2. Login ----------------------------------------------------
    private Response login(Request req, SSLSocket socket) throws BadRequestException {
        String username = req.getPayload().get("username");
        String password = req.getPayload().get("password");
        String clientIp = socket.getInetAddress().getHostAddress();

        // Throttle per username+IP
        LoginThrottle throttle = loginThrottles.computeIfAbsent(username, k -> new LoginThrottle());
        if (!throttle.allow()) {
            return Response.error("TOO_MANY_ATTEMPTS");
        }

        User u = users.get(username);
        if (u == null || !BCrypt.checkpw(password, u.getPasswordHash())) {
            throttle.recordFailure();
            return Response.error("INVALID_CREDENTIALS");
        }

        // If user already has a token, reject (single session policy)
        if (sessions.values().stream().anyMatch(s -> s.getUsername().equals(username))) {
            return Response.error("ALREADY_LOGGED_IN");
        }

        // SUCCESS – generate token
        String token = generateToken();
        Session sess = new Session(username, Instant.now().plus(SESSION_TTL));
        sessions.put(token, sess);
        return Response.okMap(Map.of("token", token));
    }

    // ---- 3. Logout ---------------------------------------------------
    private Response logout(Request req) throws UnauthenticatedException {
        String token = req.getPayload().get("token");
        if (token == null || !sessions.containsKey(token))
            throw new UnauthenticatedException();

        sessions.remove(token);
        return Response.ok("LOGGED_OUT");
    }

    // ---- 4. Search Hotel (public) ------------------------------------
    private Response searchHotel(Request req) throws BadRequestException {
        String name = req.getPayload().get("nomeHotel");
        String city = req.getPayload().get("città");
        validateNonEmpty(name, "nomeHotel");
        validateNonEmpty(city, "città");

        // dummy data - replace with DB query
        Hotel h = new Hotel(name, city, 8.7, List.of("Wifi", "Pool"));
        return Response.okMap(Map.of("hotel", h));
    }

    // ---- 5. Search All Hotels (public) -------------------------------
    private Response searchAllHotels(Request req) throws BadRequestException {
        String city = req.getPayload().get("città");
        validateNonEmpty(city, "città");

        // dummy list – order by ranking (descending)
        List<Hotel> list = List.of(
                new Hotel("Grand Plaza", city, 9.2, List.of()),
                new Hotel("Budget Inn", city, 7.4, List.of())
        );
        return Response.okMap(Map.of("hotels", list));
    }

    // ---- 6. Insert Review (requires auth) ---------------------------
    private Response insertReview(Request req) throws UnauthenticatedException, BadRequestException {
        Session sess = requireAuth(req);
        Map<String, String> p = req.getPayload();

        String hotelName = p.get("nomeHotel");
        String city = p.get("nomeCittà");
        double globalScore = Double.parseDouble(p.get("GlobalScore"));
        // SingleScores could be a JSON array – parse accordingly

        // process and store review (omitted)
