    }

    // ---- 7. Show My Badges (requires auth) -------------------------
    private Response showMyBadges(Request req) throws UnauthenticatedException {
        Session sess = requireAuth(req);
        // dummy badge
        String badge = "Bronze explorer";
        return Response.okMap(Map.of("badge", badge));
    }

    // -----------------------------------------------------------------
    //   Helper utilities
    // -----------------------------------------------------------------

    private Session requireAuth(Request req) throws UnauthenticatedException {
        String token = req.getPayload().get("token");
        if (token == null) throw new UnauthenticatedException();
        Session s = sessions.get(token);
        if (s == null || s.isExpired()) throw new UnauthenticatedException();
        return s;
    }

    private String generateToken() {
        byte[] b = new byte[32];
        rng.nextBytes(b);
        return Base64.getUrlEncoder().withoutPadding().encodeToString(b);
    }

    private void validateNonEmpty(String val, String field) throws BadRequestException {
        if (val == null || val.isBlank()) throw new BadRequestException(field.toUpperCase() + "_REQUIRED");
    }

    // -----------------------------------------------------------------
    //   DTOs & simple models (Jackson friendly)
    // -----------------------------------------------------------------

    static class Request {
        private String action;
        private Map<String, String> payload = new HashMap<>();

        public String getAction() { return action; }
        public Map<String, String> getPayload() { return payload; }
    }

    static class Response {
        private String status;      // "OK" or "ERROR"
        private String message;     // optional
        private Map<String, Object> data = new HashMap<>();
        private boolean terminate = false;

        static Response ok(String msg) {
            Response r = new Response();
            r.status = "OK";
            r.message = msg;
            return r;
        }

        static Response okMap(Map<String, Object> map) {
            Response r = new Response();
            r.status = "OK";
            r.data = map;
            return r;
        }

        static Response error(String msg) {
            Response r = new Response();
            r.status = "ERROR";
            r.message = msg;
            return r;
        }

        static Response terminate() {
            Response r = new Response();
            r.terminate = true;
            return r;
        }

        public boolean isTerminate() { return terminate; }
    }

    static class User {
        private final String username;
        private final String passwordHash;
        User(String u, String h) { this.username = u; this.passwordHash = h; }
        public String getPasswordHash() { return passwordHash; }
    }

    static class Session {
        private final String username;
        private final Instant expiresAt;
        Session(String u, Instant e) { this.username = u; this.expiresAt = e; }
        public String getUsername() { return username; }
        public boolean isExpired() { return Instant.now().isAfter(expiresAt); }
    }

    static class LoginThrottle {
        private static final int MAX_ATTEMPTS = 5;
        private static final Duration BLOCK_TIME = Duration.ofMinutes(5);
        private final Deque<Instant> attempts = new ArrayDeque<>();

        synchronized boolean allow() {
            Instant now = Instant.now();
            // purge old entries
            while (!attempts.isEmpty() && attempts.peekFirst().isBefore(now.minus(BLOCK_TIME))) {
                attempts.pollFirst();
            }
            return attempts.size() < MAX_ATTEMPTS;
        }

        synchronized void recordFailure() {
            attempts.addLast(Instant.now());
        }
    }

    static class Hotel {
        public final String name;
        public final String city;
        public final double ranking;
        public final List<String> amenities;
        Hotel(String n, String c, double r, List<String> a) {
            this.name = n; this.city = c; this.ranking = r; this.amenities = a;
        }
    }

    // -----------------------------------------------------------------
    //   Custom exception types
    // -----------------------------------------------------------------
    static class BadRequestException extends Exception {
        BadRequestException(String msg) { super(msg); }
    }
    static class UnauthenticatedException extends Exception {}
}
