    // Use an Executor (or Kotlin coroutine) – never on the UI thread!
    Executors.newSingleThreadExecutor().execute(() -> {
        SecureTcpClient client = new SecureTcpClient("example.com", 443);
        try {
            client.connect();                       // TLS handshake
            client.sendLine("HELLO SERVER");        // simple line protocol
            String answer = client.readLine();
            Log.i("Demo", "Server replied: " + answer);
        } catch (Exception e) {
            Log.e("Demo", "Secure TCP failed", e);
        } finally {
