        TrustManagerFactory.getDefaultAlgorithm());
sysTMF.init((KeyStore) null); // loads system CAs

X509TrustManager systemTM = (X509TrustManager) sysTMF.getTrustManagers()[0];
X509TrustManager pinnedTM = /* load your pinned certs */;

X509TrustManager combined = new X509TrustManager() {
    public java.security.cert.X509Certificate[] getAcceptedIssuers() {
        return pinnedTM.getAcceptedIssuers();
    }
    public void checkClientTrusted(java.security.cert.X509Certificate[] chain,
