### 2.2 `StudentService.java`

```java
package com.example.sms.service;

import com.example.sms.model.Student;

import java.util.*;
import java.util.concurrent.locks.ReentrantReadWriteLock;
import java.util.stream.Collectors;

/**
 * Business layer that manages Student objects.
 * <p>
 * Thread‑safe using a read/write lock (allowing concurrent reads, exclusive writes).
 * Uses generics and Java collections throughout.
 */
public class StudentService {

    /** Primary storage – key is the student ID (unique). */
    private final Map<String, Student> studentsById = new HashMap<>();

    /** Secondary index for fast name lookup (case‑insensitive). */
    private final Multimap<String, Student> studentsByName = new Multimap<>();

    /** Lock to protect the collections from concurrent modifications. */
    private final ReentrantReadWriteLock rwLock = new ReentrantReadWriteLock();

    // ----------------------------------------------------------------------
    // CRUD Operations
    // ----------------------------------------------------------------------

    /**
     * Adds a new student. Returns {@code true} if added successfully,
     * {@code false} if a student with the same ID already exists.
     */
    public boolean addStudent(Student student) {
        Objects.requireNonNull(student, "student");
        rwLock.writeLock().lock();
        try {
            if (studentsById.containsKey(student.getId())) {
                return false; // duplicate id
            }
            studentsById.put(student.getId(), student);
            studentsByName.put(normalize(student.getFullName()), student);
            return true;
        } finally {
            rwLock.writeLock().unlock();
        }
    }

    /**
     * Removes a student by ID. Returns the removed {@link Student} or {@code null}
     * if no matching record was found.
     */
    public Student removeStudent(String id) {
        Objects.requireNonNull(id, "id");
        rwLock.writeLock().lock();
        try {
            Student removed = studentsById.remove(id);
            if (removed != null) {
                studentsByName.remove(normalize(removed.getFullName()), removed);
            }
            return removed;
        } finally {
            rwLock.writeLock().unlock();
        }
    }

    /**
     * Updates an existing student. The ID cannot be changed.
     * Returns {@code true} if the update succeeded, {@code false} otherwise.
     */
    public boolean updateStudent(Student updated) {
        Objects.requireNonNull(updated, "updated");
        rwLock.writeLock().lock();
        try {
            Student existing = studentsById.get(updated.getId());
            if (existing == null) {
                return false; // nothing to update
            }
            // Remove old indexes
            studentsByName.remove(normalize(existing.getFullName()), existing);
            // Replace the record
            studentsById.put(updated.getId(), updated);
            // Add new indexes
            studentsByName.put(normalize(updated.getFullName()), updated);
            return true;
        } finally {
            rwLock.writeLock().unlock();
        }
    }

    // ----------------------------------------------------------------------
    // Query Operations
    // ----------------------------------------------------------------------

    /**
     * Finds a student by exact ID (case‑sensitive). Returns {@code Optional.empty()}
     * if not found.
     */
    public Optional<Student> findById(String id) {
        Objects.requireNonNull(id, "id");
        rwLock.readLock().lock();
        try {
            return Optional.ofNullable(studentsById.get(id));
        } finally {
            rwLock.readLock().unlock();
        }
    }

    /**
     * Finds students whose full name contains the supplied keyword (case‑insensitive).
     */
    public List<Student> findByName(String keyword) {
        Objects.requireNonNull(keyword, "keyword");
        String norm = normalize(keyword);
        rwLock.readLock().lock();
        try {
            // Linear scan of the secondary index – efficient for modest data sets.
            return studentsByName.entries()
                                 .stream()
                                 .filter(e -> e.key.contains(norm))
                                 .map(e -> e.value)
                                 .distinct()
                                 .collect(Collectors.toList());
        } finally {
            rwLock.readLock().unlock();
        }
    }

    /**
     * Returns a read‑only snapshot of all students sorted by ID.
     */
    public List<Student> getAllStudentsSortedById() {
        rwLock.readLock().lock();
        try {
            return studentsById.values()
                               .stream()
                               .sorted(Comparator.comparing(Student::getId))
                               .collect(Collectors.toUnmodifiableList());
        } finally {
            rwLock.readLock().unlock();
        }
    }

    // ----------------------------------------------------------------------
    // Reporting Helpers
    // ----------------------------------------------------------------------

    /**
     * Generates a simple textual report of all students.
     */
    public String generateReport() {
        StringBuilder sb = new StringBuilder();
        sb.append("=== Student Management Report ===\n");
        sb.append(String.format("%-10s %-20s %-12s %-30s %-15s%n",
                "ID", "Name", "DOB", "E‑mail", "Major"));
        sb.append("-".repeat(90)).append('\n');

        for (Student s : getAllStudentsSortedById()) {
            sb.append(String.format("%-10s %-20s %-12s %-30s %-15s%n",
                    s.getId(),
                    s.getFullName(),
                    s.getDateOfBirth(),
                    s.getEmail(),
                    s.getMajor()));
        }
        sb.append("\nTotal students: ").append(studentsById.size()).append('\n');
        return sb.toString();
    }

    // ----------------------------------------------------------------------
    // Private utility methods
    // ----------------------------------------------------------------------

    private static String normalize(String s) {
        return s.trim().toLowerCase(Locale.ROOT);
    }

    // ----------------------------------------------------------------------
    // A tiny Multi‑map implementation (key → Set<value>) used only inside this class.
    // ----------------------------------------------------------------------
    private static final class Multimap<K, V> {
        private final Map<K, Set<V>> map = new HashMap<>();

        void put(K key, V value) {
            map.computeIfAbsent(key, k -> new HashSet<>()).add(value);
        }

        void remove(K key, V value) {
            Set<V> set = map.get(key);
            if (set != null) {
                set.remove(value);
                if (set.isEmpty()) {
                    map.remove(key);
                }
            }
        }

        Set<Entry<K, V>> entries() {
            Set<Entry<K, V>> e = new HashSet<>();
            for (Map.Entry<K, Set<V>> me : map.entrySet()) {
                for (V v : me.getValue()) {
                    e.add(new Entry<>(me.getKey(), v));
                }
            }
            return e;
        }

        static final class Entry<K, V> {
            final K key;
            final V value;
            Entry(K k, V v) { this.key = k; this.value = v; }
        }
    }
}
```

#### Why this design matters from a security perspective

| Feature | Security benefit |
|---------|------------------|
| **Immutable Student objects** | Prevents accidental side‑effects – a compromised reference cannot mutate stored data without going through `StudentService`. |
| **Read/write lock** | Guarantees thread‑safe access; eliminates race‑conditions that could lead to data loss or inconsistent state (which sometimes become attack vectors). |
| **Secondary index (multimap)** | Enables fast, case‑insensitive searches without scanning the whole map each time, reducing the surface for Denial‑of‑Service via costly queries. |
| **All public methods validate arguments (`Objects.requireNonNull`)** | Early fail‑fast prevents `NullPointerException`s that could otherwise be leveraged for information leakage. |

