public final class ConsoleUI {

    private final StudentService service;
    private final Scanner scanner = new Scanner(System.in);

    public ConsoleUI(StudentService service) {
        this.service = service;
    }

    public void start() {
        printWelcome();
        boolean running = true;
        while (running) {
            printMenu();
            String choice = scanner.nextLine().trim();
            switch (choice) {
                case "1" -> addStudent();
                case "2" -> removeStudent();
                case "3" -> updateStudent();
                case "4" -> searchById();
                case "5" -> searchByName();
                case "6" -> generateReport();
                case "0" -> running = false;
                default  -> System.out.println("Invalid option – try again.");
            }
        }
        System.out.println("Good‑bye!");
    }

    // ------------------------------------------------------------------
    // UI actions
    // ------------------------------------------------------------------

    private void addStudent() {
        System.out.println("\n--- Add New Student ---");
        Student s = readStudentFromConsole(false);
        if (s == null) return;
        boolean ok = service.addStudent(s);
        System.out.println(ok ? "Student added." : "Student with that ID already exists.");
    }

    private void removeStudent() {
        System.out.print("\nEnter student ID to delete: ");
        String id = scanner.nextLine().trim();
        Student removed = service.removeStudent(id);
        if (removed != null) {
            System.out.println("Removed: " + removed);
        } else {
            System.out.println("No student found with that ID.");
        }
    }

    private void updateStudent() {
        System.out.println("\n--- Update Existing Student ---");
        Student s = readStudentFromConsole(true);
        if (s == null) return;
        boolean ok = service.updateStudent(s);
        System.out.println(ok ? "Student updated." : "Student not found.");
    }

    private void searchById() {
        System.out.print("\nEnter student ID: ");
        String id = scanner.nextLine().trim();
        Optional<Student> opt = service.findById(id);
        System.out.println(opt.map(Object::toString).orElse("Not found."));
    }

    private void searchByName() {
        System.out.print("\nEnter name keyword: ");
        String keyword = scanner.nextLine().trim();
        List<Student> results = service.findByName(keyword);
        if (results.isEmpty()) {
            System.out.println("No matches.");
        } else {
            System.out.println("Matches:");
            results.forEach(System.out::println);
        }
    }

    private void generateReport() {
        System.out.println("\n" + service.generateReport());
    }

    // ------------------------------------------------------------------
    // Helpers
    // ------------------------------------------------------------------

    private Student readStudentFromConsole(boolean mustExist) {
        System.out.print("ID (e.g., S12345): ");   String id = scanner.nextLine().trim();
