        System.out.print("First name: ");          String first = scanner.nextLine().trim();
        System.out.print("Last name: ");           String last = scanner.nextLine().trim();
        System.out.print("Date of birth (YYYY-MM-DD): ");
        String dobStr = scanner.nextLine().trim();
        LocalDate dob;
        try {
