/**
 * Very small subset of the CAS REST protocol.
 *
 *   GET  /cas/login?service={serviceUrl}
 *   GET  /cas/validate?service={serviceUrl}&ticket={ticket}
 *
 *   /login redirects the user to a fake login page.
 *   /validate returns "yes\nusername" when ticket is known.
 */
@RestController
@RequestMapping("/cas")
class CasController {

    // In‑memory map: ticket → username
    private final Map<String, String> ticketCache = new HashMap<>();

    @GetMapping("/login")
    public String login(@RequestParam String service) {
        // In a real CAS you’d present a login UI.
        // For the demo we auto‑login as "alex" and issue a ticket.
        String ticket = "ST-" + UUID.randomUUID();
        ticketCache.put(ticket, "alex");   // user principal
        // Redirect back to the service with the ticket
        return "<html><body>"
                + "Logging you in as <b>alex</b>...<script>"
                + "window.location='" + service + "?ticket=" + ticket + "';"
                + "</script>"
                + "</body></html>";
    }

    @GetMapping("/validate")
    public String validate(@RequestParam String service,
                           @RequestParam String ticket) {
        String principal = ticketCache.remove(ticket); // one‑time use
        if (principal != null) {
            return "yes\n" + principal;
        }
        return "no";
    }

    @GetMapping("/logout")
    public String logout(@RequestParam(required = false) String service) {
        // In a real deployment you’d propagate SLO to all services.
        return "<html><body>"
                + "You have been logged out from the mock CAS."
                + (service != null ? "<script>window.location='" + service + "';</script>" : "")
                + "</body></html>";
    }
}
