```java
package eduverse.client;

import org.apereo.cas.client.validation.Cas20ServiceTicketValidator;
import org.springframework.boot.SpringApplication;
import org.springframework.boot.autoconfigure.SpringBootApplication;
import org.springframework.context.annotation.Bean;
import org.springframework.security.authentication.*;
import org.springframework.security.config.Customizer;
import org.springframework.security.config.annotation.web.builders.HttpSecurity;
import org.springframework.security.core.*;
import org.springframework.security.core.authority.SimpleGrantedAuthority;
import org.springframework.security.web.SecurityFilterChain;
import org.springframework.security.web.authentication.logout.*;

import java.util.*;

@SpringBootApplication
public class ClientApplication {

    public static void main(String[] args) {
        SpringApplication.run(ClientApplication.class, args);
    }

    /***
     * ----- CAS‑Specific Beans -----
     */
    @Bean
    public ServiceProperties serviceProperties() {
        ServiceProperties sp = new ServiceProperties();
        // This must be the exact URL that CAS will redirect back to:
        sp.setService("https://localhost:8443/login/cas");
        sp.setSendRenew(false);
        return sp;
    }

    @Bean
    public CasAuthenticationProvider casAuthenticationProvider(ServiceProperties sp) {
        CasAuthenticationProvider provider = new CasAuthenticationProvider();
        provider.setServiceProperties(sp);
        provider.setTicketValidator(new Cas20ServiceTicketValidator("https://localhost:8085/cas"));
        provider.setUserDetailsService(username -> {
            // In a real deployment you would look up user attributes here.
            List<GrantedAuthority> authorities = List.of(new SimpleGrantedAuthority("ROLE_USER"));
            return new User(username, "", authorities);
        });
        provider.setKey("eduverseCasKey"); // unique identifier for this provider
        return provider;
    }

    /***
     * ----- Spring Security Chain -----
     */
    @Bean
    public SecurityFilterChain filterChain(HttpSecurity http,
                                            AuthenticationManager authManager,
                                            ServiceProperties sp) throws Exception {

        // 1️⃣  Configure the CAS entry point – this redirects unauthenticated requests
        //    to the CAS server login page.
        CasAuthenticationEntryPoint casEntryPoint = new CasAuthenticationEntryPoint();
        casEntryPoint.setLoginUrl("https://localhost:8085/cas/login");
        casEntryPoint.setServiceProperties(sp);

        // 2️⃣  Configure logout – both local session invalidation and CAS‑side SLO.
        LogoutSuccessHandler logoutSuccessHandler = new CasLogoutSuccessHandler();
        ((CasLogoutSuccessHandler) logoutSuccessHandler).setSingleSignOut(true);
        ((CasLogoutSuccessHandler) logoutSuccessHandler).setLogoutUrl("https://localhost:8085/cas/logout?service=https://localhost:8443/");

        http
            // ----------------------------
            // Basic web security
            // ----------------------------
            .csrf(csrf -> csrf.disable()) // For demo only – enable CSRF in prod
            .authorizeHttpRequests(authz -> authz
                .requestMatchers("/", "/error", "/public/**").permitAll()
                .anyRequest().authenticated()
            )
            // ----------------------------
            // CAS authentication filter
            // ----------------------------
            .addFilter(casAuthenticationFilter(authManager, sp))
            // ----------------------------
            // Exception handling – redirect to CAS login when not authenticated
            // ----------------------------
            .exceptionHandling(ex -> ex
                .authenticationEntryPoint(casEntryPoint)
            )
            // ----------------------------
            // Logout handling (both local and remote)
            // ----------------------------
            .logout(logout -> logout
                .logoutSuccessHandler(logoutSuccessHandler)
                .invalidateHttpSession(true)
                .clearAuthentication(true)
                .deleteCookies("JSESSIONID")
                .permitAll()
            );

        return http.build();
    }

    /**
     * CAS authentication filter – parses the `ticket` parameter that CAS
     * appends to the service URL after a successful login.
     */
    private CasAuthenticationFilter casAuthenticationFilter(AuthenticationManager authManager,
                                                             ServiceProperties sp) {
        CasAuthenticationFilter filter = new CasAuthenticationFilter();
        filter.setAuthenticationManager(authManager);
        filter.setServiceProperties(sp);
        return filter;
    }

    /**
     * Tell Spring to use the custom AuthenticationProvider we built.
     */
    @Bean
    public AuthenticationManager authenticationManager(CasAuthenticationProvider casProvider) {
        return new ProviderManager(Collections.singletonList(casProvider));
    }
}
```

