package eduverse.client;

import org.springframework.security.core.annotation.AuthenticationPrincipal;
import org.springframework.stereotype.Controller;
import org.springframework.ui.Model;
import org.springframework.web.bind.annotation.GetMapping;

@Controller
public class WebController {

    @GetMapping("/")
    public String home() {
        return "home"; // public landing page (templates/home.html)
    }

    @GetMapping("/dashboard")
    public String dashboard(@AuthenticationPrincipal org.springframework.security.core.userdetails.User user,
                            Model model) {
        // The user object is populated by CAS after ticket validation.
        model.addAttribute("username", user.getUsername());
        model.addAttribute("authorities", user.getAuthorities());
        return "dashboard"; // protected page (templates/dashboard.html)
    }

    @GetMapping("/logout")
    public String logout() {
        // Spring Security will catch this URL and perform logout via the filter chain.
        return "redirect:/";
    }
}
