```java
package com.example.model;

import jakarta.persistence.*;
import jakarta.validation.constraints.*;

/**
 * Simple JPA entity representing an employee.
 * All fields have validation annotations to enforce a “secure‑by‑design”
 * data contract before the ORM hits the DB.
 */
@Entity
@Table(name = "employees",
       uniqueConstraints = @UniqueConstraint(columnNames = {"email"}))
public class Employee {

    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY) // H2 auto‑increments
    private Long id;

    @Column(nullable = false, length = 100)
    @NotBlank(message = "First name is required")
    @Size(max = 100, message = "First name must be ≤ 100 chars")
    private String firstName;

    @Column(nullable = false, length = 100)
    @NotBlank(message = "Last name is required")
    @Size(max = 100, message = "Last name must be ≤ 100 chars")
    private String lastName;

    @Column(nullable = false, unique = true, length = 150)
    @NotBlank(message = "Email is required")
    @Email(message = "Email must be valid")
    @Size(max = 150, message = "Email must be ≤ 150 chars")
    private String email;

    @Column(nullable = false)
    @Min(value = 0, message = "Salary cannot be negative")
    private Double salary;

    // ----------------------------------------------
    // Constructors, getters, setters, toString()
    // ----------------------------------------------

    public Employee() { }

    public Employee(String firstName, String lastName,
                    String email, Double salary) {
        this.firstName = firstName;
        this.lastName  = lastName;
        this.email     = email;
        this.salary    = salary;
    }

    public Long getId() { return id; }

    public String getFirstName() { return firstName; }
    public void setFirstName(String firstName) { this.firstName = firstName; }

    public String getLastName() { return lastName; }
    public void setLastName(String lastName) { this.lastName = lastName; }

    public String getEmail() { return email; }
    public void setEmail(String email) { this.email = email; }

    public Double getSalary() { return salary; }
    public void setSalary(Double salary) { this.salary = salary; }

    @Override
    public String toString() {
        return "Employee{id=" + id +
               ", firstName='" + firstName + '\'' +
               ", lastName='" + lastName + '\'' +
               ", email='" + email + '\'' +
               ", salary=" + salary + '}';
    }
}
```

> **Security tip:** Avoid storing *plain* passwords in this entity. If you need authentication, use a dedicated `User` table with a **strong, salted hash** (`BCrypt`, `Argon2`, …) and never log the password field.

