## 4. DAO / Bootstrap (`src/main/java/com/example/dao/EmployeeDao.java`)

```java
package com.example.dao;

import com.example.model.Employee;
import jakarta.persistence.*;
import org.hibernate.Session;
import org.hibernate.SessionFactory;
import org.hibernate.cfg.Configuration;

/**
 * Tiny DAO that demonstrates a safe “save” operation.
 *
 * In a real service you would inject the SessionFactory via CDI / Spring,
 * wrap calls in a container‑managed transaction and handle rollback
 * automatically. For demonstration we do it manually.
 */
public class EmployeeDao implements AutoCloseable {

    private final SessionFactory sessionFactory;

    public EmployeeDao() {
        // Build SessionFactory once (expensive). In production you would
        // keep a singleton or use a container-managed EntityManagerFactory.
        Configuration cfg = new Configuration().configure(); // reads hibernate.cfg.xml
        sessionFactory = cfg.buildSessionFactory();
    }

    /**
     * Persists the given employee inside its own transaction.
     * If any validation or DB error occurs the transaction is rolled back.
     */
    public void save(Employee employee) {
        Transaction tx = null;
        try (Session session = sessionFactory.openSession()) {
            tx = session.beginTransaction();

            // Hibernate automatically uses a prepared statement under the hood.
            // The entity is validated (Bean Validation) *before* hitting the DB.
            session.persist(employee);

            tx.commit();
            System.out.println("✅ Employee persisted: " + employee);
        } catch (Exception e) {
            if (tx != null && tx.isActive())
                tx.rollback();
            // Do NOT expose stack‑traces directly to an end‑user; log securely instead.
            System.err.println("❌ Failed to persist employee: " + e.getMessage());
            // In production re‑throw a custom unchecked exception or map to an HTTP 5xx.
            throw e;
