public interface Encyclopedia extends Remote {

    /** Returns a list of 300 random words. */
    List<String> generateWords() throws RemoteException;

    /** ----------- ANALYSIS METHODS (single‑threaded) ----------- */

    /** 1 – total number of characters (including spaces). */
    int Count(List<String> words) throws RemoteException;

    /** 2 – set of repeated words. */
