    /** 3 – longest word (first one if tie). */
    String longest(List<String> words) throws RemoteException;

    /** 4 – shortest word (first one if tie). */
    String shortest(List<String> words) throws RemoteException;

    /** 5 – map of word → frequency. */
    Map<String, Integer> Repeat(List<String> words) throws RemoteException;

    /** ----------- ANALYSIS METHODS (multi‑threaded) ----------- */

    /** Run all five analyses in parallel and return the results in a container. */
    AnalysisResult parallelAnalyse(List<String> words) throws RemoteException;
}

/**
