package rmienc;

import java.rmi.RemoteException;
import java.rmi.server.UnicastRemoteObject;
import java.util.*;
import java.util.concurrent.*;

public class EncyclopediaImpl extends UnicastRemoteObject implements Encyclopedia {

    private static final long serialVersionUID = 1L;
    private final Random rand = new Random();

    protected EncyclopediaImpl() throws RemoteException {
        super();
    }

    /* ----------  Helper to create random words ---------- */
    private String randomWord() {
        // Length between 3 and 12 characters
        int len = 3 + rand.nextInt(10);
        StringBuilder sb = new StringBuilder(len);
        for (int i = 0; i < len; i++) {
            // lower‑case letters a‑z
            sb.append((char) ('a' + rand.nextInt(26)));
        }
        return sb.toString();
    }

    @Override
    public List<String> generateWords() throws RemoteException {
        List<String> list = new ArrayList<>(300);
        for (int i = 0; i < 300; i++) {
            list.add(randomWord());
        }
        return list;
    }

    /* ----------  SINGLE‑THREADED ANALYSES ---------- */

    @Override
    public int Count(List<String> words) throws RemoteException {
        // spaces between words count as 1 char each, i.e. (words‑1) spaces
        int chars = words.stream().mapToInt(String::length).sum();
        return chars + Math.max(0, words.size() - 1);
    }

    @Override
    public Set<String> repeatedwords(List<String> words) throws RemoteException {
        Map<String, Integer> freq = new HashMap<>();
        for (String w : words) freq.merge(w, 1, Integer::sum);
        Set<String> rep = new HashSet<>();
        for (Map.Entry<String,Integer> e : freq.entrySet())
            if (e.getValue() > 1) rep.add(e.getKey());
        return rep;
    }

    @Override
    public String longest(List<String> words) throws RemoteException {
        return words.stream()
                .max(Comparator.comparingInt(String::length))
                .orElse("");
    }

    @Override
    public String shortest(List<String> words) throws RemoteException {
        return words.stream()
                .min(Comparator.comparingInt(String::length))
                .orElse("");
    }

    @Override
    public Map<String,Integer> Repeat(List<String> words) throws RemoteException {
        Map<String,Integer> freq = new HashMap<>();
        for (String w : words) freq.merge(w, 1, Integer::sum);
        return freq;
    }

    /* ----------  MULTI‑THREADED ANALYSIS ---------- */

    @Override
    public AnalysisResult parallelAnalyse(List<String> words) throws RemoteException {
        ExecutorService pool = Executors.newFixedThreadPool(Runtime.getRuntime().availableProcessors());

        // Create 5 callables – each computes one of the required results
        Callable<Integer> cCount = () -> Count(words);
        Callable<Set<String>> cRepWords = () -> repeatedwords(words);
        Callable<String> cLongest = () -> longest(words);
        Callable<String> cShortest = () -> shortest(words);
        Callable<Map<String,Integer>> cFreq = () -> Repeat(words);

        try {
            List<Future<?>> futures = new ArrayList<>();
            futures.add(pool.submit(cCount));
            futures.add(pool.submit(cRepWords));
            futures.add(pool.submit(cLongest));
            futures.add(pool.submit(cShortest));
            futures.add(pool.submit(cFreq));

            AnalysisResult result = new AnalysisResult();
            result.totalChars   = (Integer) futures.get(0).get();
            result.repeated     = (Set<String>) futures.get(1).get();
            result.longest      = (String) futures.get(2).get();
            result.shortest     = (String) futures.get(3).get();
            result.frequencies  = (Map<String,Integer>) futures.get(4).get();

            return result;
        } catch (InterruptedException | ExecutionException e) {
            throw new RemoteException("Parallel analysis failed", e);
        } finally {
            pool.shutdown();
        }
    }
}
```

