package rmienc;

import java.util.*;
import java.util.concurrent.*;

/**
 * Utility used on the **client side** to invoke the remote methods and
 * to measure the elapsed time of each approach.
 */
public class Analyzer {

    /** Runs the single‑threaded version and returns elapsed time (ms). */
    public static long runSingleThreaded(Encyclopedia remote,
                                         List<String> words,
                                         ResultHolder holder) throws Exception {
        long start = System.currentTimeMillis();

        holder.totalChars = remote.Count(words);
        holder.repeated    = remote.repeatedwords(words);
        holder.longest     = remote.longest(words);
        holder.shortest    = remote.shortest(words);
        holder.freqMap     = remote.Repeat(words);

        long end = System.currentTimeMillis();
        return end - start;
    }

    /** Runs the multi‑threaded version and returns elapsed time (ms). */
    public static long runMultiThreaded(Encyclopedia remote,
                                        List<String> words,
                                        ResultHolder holder) throws Exception {
        long start = System.currentTimeMillis();

        AnalysisResult ar = remote.parallelAnalyse(words);
        holder.totalChars = ar.totalChars;
        holder.repeated    = ar.repeated;
        holder.longest     = ar.longest;
        holder.shortest    = ar.shortest;
        holder.freqMap     = ar.frequencies;

        long end = System.currentTimeMillis();
        return end - start;
    }

    /** Simple bean to hold the five results for the UI. */
    public static class ResultHolder {
        public int totalChars;
        public Set<String> repeated;
        public String longest;
        public String shortest;
        public Map<String,Integer> freqMap;
    }
}
