public static class CryptoHelper
{
    // 32‑byte (256‑bit) pre‑shared key, base64 encoded for convenience
    public static readonly byte[] PreSharedKey = Convert.FromBase64String(
        "BfM0e6ZTS1nVg7W9Z0nM0kLJY7G0x8tW2V+S3vUvkHk="); // 32 bytes

    // 12‑byte nonce (recommended for GCM). We'll prepend a random 4‑byte counter.
    public static byte[] GenerateNonce()
    {
        var nonce = new byte[12];
        RandomNumberGenerator.Fill(nonce);
        return nonce;
    }

    // Encrypt: returns [nonce(12)] + [ciphertext] + [tag(16)]
    public static byte[] Encrypt(ReadOnlySpan<byte> plain)
    {
        var nonce = GenerateNonce();
        using var aes = new AesGcm(PreSharedKey);
        var cipher = new byte[plain.Length];
        var tag = new byte[16];
        aes.Encrypt(nonce, plain, cipher, tag);
        var result = new byte[nonce.Length + cipher.Length + tag.Length];
        Buffer.BlockCopy(nonce, 0, result, 0, nonce.Length);
        Buffer.BlockCopy(cipher, 0, result, nonce.Length, cipher.Length);
        Buffer.BlockCopy(tag, 0, result, nonce.Length + cipher.Length, tag.Length);
        return result;
    }

    // Decrypt: expects same layout as above.
    public static byte[] Decrypt(ReadOnlySpan<byte> encrypted)
    {
        if (encrypted.Length < 12 + 16) // at least nonce + tag
            throw new ArgumentException("Ciphertext too short");

        var nonce = encrypted.Slice(0, 12);
        var tag = encrypted.Slice(encrypted.Length - 16, 16);
        var cipher = encrypted.Slice(12, encrypted.Length - 12 - 16);
        var plain = new byte[cipher.Length];

        using var aes = new AesGcm(PreSharedKey);
        aes.Decrypt(nonce, cipher, tag, plain);
        return plain;
    }
}
```

> **安全提示**：  
> - **PSK** 仅用于原型；正式部署请使用 **TLS / X.509** 完成握手。  
> - **Nonce** 需要保证不重复（这里使用全随机 12‑byte，概率极低冲突）。  
> - **鉴别标签（Tag）** 已经由 GCM 验证，无需额外 MAC。  

### 3.2 客户端 – SOCKS5 代理 + 隧道

我们实现 **最小化的 SOCKS5**（只支持 `CONNECT`，不再实现 BIND、UDP ASSOCIATE）。

```csharp
// VpnClient.cs
using System;
using System.Net;
using System.Net.Sockets;
using System.Threading.Tasks;
using System.Collections.Concurrent;

public class VpnClient
{
    private readonly IPAddress _serverIp;
    private readonly int _serverPort;
    private readonly int _listenPort; // 本地 SOCKS5 端口，例如 1080
    private TcpListener _listener;

    // 为每个客户端维持一个持久的隧道（可复用），这里使用简单的池化实现
    private readonly ConcurrentBag<TcpClient> _tunnelPool = new();

    public VpnClient(IPAddress serverIp, int serverPort, int listenPort = 1080)
    {
        _serverIp = serverIp;
        _serverPort = serverPort;
        _listenPort = listenPort;
    }

    public async Task StartAsync()
    {
        _listener = new TcpListener(IPAddress.Any, _listenPort);
        _listener.Start();
        Console.WriteLine($"[Client] SOCKS5 proxy listening on 0.0.0.0:{_listenPort}");

        while (true)
        {
            var client = await _listener.AcceptTcpClientAsync();
            _ = HandleSocksConnectionAsync(client); // fire‑and‑forget
        }
    }

    private async Task<TcpClient> GetOrCreateTunnelAsync()
    {
        if (_tunnelPool.TryTake(out var existing))
        {
            if (existing.Connected) return existing;
            existing.Dispose();
        }

        var tunnel = new TcpClient();
        await tunnel.ConnectAsync(_serverIp, _serverPort);
        return tunnel;
    }

    private async Task HandleSocksConnectionAsync(TcpClient client)
    {
        var stream = client.GetStream();

        // -------- SOCKS5 handshake ----------
        // read VER, NMETHODS, METHODS...
        var buf = new byte[2];
        await stream.ReadExactlyAsync(buf, 0, 2);
        if (buf[0] != 0x05) { client.Close(); return; }

        int nMethods = buf[1];
        var methods = new byte[nMethods];
        await stream.ReadExactlyAsync(methods, 0, nMethods);
        // We just accept "No authentication" (0x00)
        await stream.WriteAsync(new byte[] { 0x05, 0x00 }, 0, 2);

        // -------- SOCKS5 request ----------
        // read first 4 bytes: VER CMD RSV ATYP
        buf = new byte[4];
        await stream.ReadExactlyAsync(buf, 0, 4);
        if (buf[0] != 0x05 || buf[1] != 0x01) // only CONNECT supported
        {
            client.Close(); return;
        }

        string destHost;
        int destPort;

        switch (buf[3])
        {
            case 0x01: // IPv4
                var ipBytes = new byte[4];
                await stream.ReadExactlyAsync(ipBytes, 0, 4);
                destHost = new IPAddress(ipBytes).ToString();
                break;
            case 0x03: // DOMAINNAME
                var len = stream.ReadByte();
                var domain = new byte[len];
                await stream.ReadExactlyAsync(domain, 0, len);
                destHost = System.Text.Encoding.ASCII.GetString(domain);
                break;
            case 0x04: // IPv6
                var ip6 = new byte[16];
                await stream.ReadExactlyAsync(ip6, 0, 16);
                destHost = new IPAddress(ip6).ToString();
                break;
            default:
                client.Close(); return;
        }

        var portBytes = new byte[2];
        await stream.ReadExactlyAsync(portBytes, 0, 2);
        destPort = (portBytes[0] << 8) | portBytes[1];

        // -------- Build a request packet to the server ----------
        // Simple framing: [LEN(2)] [DEST_HOST_LEN(1)] [HOST] [PORT(2)] [PAYLOAD...]
        // We'll send the request encrypted as a single message.
        var hostBytes = System.Text.Encoding.UTF8.GetBytes(destHost);
        var request = new byte[1 + hostBytes.Length + 2];
        request[0] = (byte)hostBytes.Length;
        Buffer.BlockCopy(hostBytes, 0, request, 1, hostBytes.Length);
        request[1 + hostBytes.Length] = (byte)(destPort >> 8);
        request[2 + hostBytes.Length] = (byte)(destPort & 0xFF);

        var encrypted = CryptoHelper.Encrypt(request);
        var lenPrefix = BitConverter.GetBytes((ushort)encrypted.Length);
        if (BitConverter.IsLittleEndian) Array.Reverse(lenPrefix);

        var tunnel = await GetOrCreateTunnelAsync();
        var tunnelStream = tunnel.GetStream();

        // Send length + encrypted payload
        await tunnelStream.WriteAsync(lenPrefix, 0, 2);
        await tunnelStream.WriteAsync(encrypted, 0, encrypted.Length);

        // -------- Reply to the SOCKS client: success ----------
        // 0x00 succeeded, bind address/port are ignored (set to 0.0.0.0:0)
        var reply = new byte[] { 0x05, 0x00, 0x00, 0x01, 0, 0, 0, 0, 0, 0 };
        await stream.WriteAsync(reply, 0, reply.Length);

        // -------- Start bidirectional forwarding ----------
        var remoteStream = tunnelStream; // the same tunnel carries both directions
        _ = PipeAsync(stream, remoteStream, true);   // client -> server
        _ = PipeAsync(remoteStream, stream, false); // server -> client
    }

    private async Task PipeAsync(NetworkStream src, NetworkStream dst, bool isClientToServer)
    {
        try
        {
            var buffer = new byte[8192];
            while (true)
            {
                int read = await src.ReadAsync(buffer, 0, buffer.Length);
                if (read == 0) break; // EOF

                // 对于「客户端→服务器」方向，需要把业务数据再次包装成「VPN 数据流」：
                if (isClientToServer)
                {
                    // frame: [LEN(2)] + encrypted([DATA])
                    var payload = new byte[read];
                    Buffer.BlockCopy(buffer, 0, payload, 0, read);
                    var encrypted = CryptoHelper.Encrypt(payload);
                    var lenPrefix = BitConverter.GetBytes((ushort)encrypted.Length);
                    if (BitConverter.IsLittleEndian) Array.Reverse(lenPrefix);
                    await dst.WriteAsync(lenPrefix, 0, 2);
                    await dst.WriteAsync(encrypted, 0, encrypted.Length);
                }
                else // server→client: 已经是明文（服务器已解密），直接转发
                {
                    await dst.WriteAsync(buffer, 0, read);
                }
            }
        }
        catch (Exception ex)
        {
            // silent swallow – the other pipe will close the connection soon
        }
        finally
        {
            src.Dispose();
            dst.Dispose();
        }
    }
}
```

**说明**

1. **SOCKS5 握手**：只实现 `NO AUTHENTICATION REQUIRED`，足够本地系统代理使用。  
2. **请求封装**：我们把 **目标地址 + 端口** 作为一个短消息（< 256 bytes）加密后发送给服务器。  
3. **隧道复用**：`_tunnelPool` 保存已经建立的 TCP 连接，这样每个本地 `CONNECT` 不需要再重新 `TCP handshake` 服务器；只在需要时创建新隧道。  
4. **双向转发**：`PipeAsync` 一端负责把业务数据再次加密发送到服务器（客户端→服务器），另一端直接把服务器解密后的业务数据写回本地。  

> **实际生产中**，建议在隧道层实现 **帧头**（长度 + 序列号），并在 **每帧** 加入 **MAC** 或 **GCM Tag**，防止重放与篡改。  

### 3.3 服务器 – 隧道监听 + 业务转发

服务器的职责：

1. 接收客户端发来的 **加密帧**（长度 + GCM 加密）  
2. 解密后读取 **目标主机 + 端口**（只在第一次帧出现）  
3. 与目标建立 **普通 TCP 连接**，随后把后续的业务数据 **明文** 转发过去（以及把响应回传给客户端，加密后发送）。

```csharp
// VpnServer.cs
using System;
using System.Net;
using System.Net.Sockets;
using System.Threading.Tasks;
using System.Collections.Concurrent;

public class VpnServer
{
    private readonly int _listenPort; // 服务器端口，例如 5000
    private TcpListener _listener;

    // 这里我们维护每条隧道对应的目标连接
    private readonly ConcurrentDictionary<TcpClient, (TcpClient target, bool isTargetSet)> _map
        = new();

    public VpnServer(int listenPort = 5000)
    {
        _listenPort = listenPort;
    }

    public async Task StartAsync()
    {
        _listener = new TcpListener(IPAddress.Any, _listenPort);
        _listener.Start();
        Console.WriteLine($"[Server] Listening on 0.0.0.0:{_listenPort}");

        while (true)
        {
            var client = await _listener.AcceptTcpClientAsync();
            _ = HandleClientAsync(client); // fire‑and‑forget
        }
    }

    private async Task HandleClientAsync(TcpClient client)
    {
        var stream = client.GetStream();
        NetworkStream targetStream = null;
        try
        {
            while (true)
            {
                // 读取帧长度（2 字节 big‑endian）
                var lenPrefix = new byte[2];
                await stream.ReadExactlyAsync(lenPrefix, 0, 2);
                if (BitConverter.IsLittleEndian) Array.Reverse(lenPrefix);
                int payloadLen = BitConverter.ToUInt16(lenPrefix, 0);
                if (payloadLen <= 0) break;

                var encrypted = new byte[payloadLen];
                await stream.ReadExactlyAsync(encrypted, 0, payloadLen);
                var plain = CryptoHelper.Decrypt(encrypted);

                // 第一次帧里会携带“目标信息”，后续帧仅为业务数据
                if (!_map.TryGetValue(client, out var entry) || !entry.isTargetSet)
                {
                    // 解析目标信息
                    var hostLen = plain[0];
                    var host = System.Text.Encoding.UTF8.GetString(plain, 1, hostLen);
                    int port = (plain[1 + hostLen] << 8) | plain[2 + hostLen];
                    Console.WriteLine($"[Server] New tunnel → {host}:{port}");

                    // 建立到目标的 TCP 连接
                    var target = new TcpClient();
                    await target.ConnectAsync(host, port);
                    targetStream = target.GetStream();

                    // 记录映射
                    _map[client] = (target, true);

                    // 开始把目标响应回传给客户端（明文 -> 加密）
                    _ = ReadFromTargetAndSendAsync(targetStream, client);
                }
                else
                {
                    // 业务数据转发到目标（解密后直接写入目标 Socket）
                    await targetStream.WriteAsync(plain, 0, plain.Length);
                }
            }
        }
        catch (Exception ex)
        {
            Console.WriteLine($"[Server] Exception: {ex.Message}");
        }
        finally
        {
            Cleanup(client);
        }
    }

    private async Task ReadFromTargetAndSendAsync(NetworkStream source, TcpClient client)
    {
        try
        {
            var buffer = new byte[8192];
            while (true)
            {
                int read = await source.ReadAsync(buffer, 0, buffer.Length);
                if (read == 0) break; // target closed

                // 加密后发送给客户端
                var payload = new byte[read];
                Buffer.BlockCopy(buffer, 0, payload, 0, read);
                var encrypted = CryptoHelper.Encrypt(payload);
                var lenPrefix = BitConverter.GetBytes((ushort)encrypted.Length);
                if (BitConverter.IsLittleEndian) Array.Reverse(lenPrefix);
                var clientStream = client.GetStream();
                await clientStream.WriteAsync(lenPrefix, 0, 2);
                await clientStream.WriteAsync(encrypted, 0, encrypted.Length);
            }
        }
        catch (Exception ex)
        {
            // ignore, connection will be cleaned up by upper logic
        }
    }

    private void Cleanup(TcpClient client)
    {
        if (_map.TryRemove(client, out var tuple))
        {
            tuple.target?.Close();
        }
        client.Close();
    }
}
```

> 代码里我们使用了 `Stream.ReadExactlyAsync`（.NET 6+）来确保一次拿到完整的字节数。如果你使用 .NET Framework，请自行实现循环读取。

### 3.4 启动入口

```csharp
// Program.cs
using System;
using System.Net;
using System.Threading.Tasks;

class Program
{
    static async Task Main(string[] args)
    {
        if (args.Length == 0)
        {
            Console.WriteLine("Usage: Vpn.exe [client|server] [options...]");
            return;
        }

        if (args[0].Equals("client", StringComparison.OrdinalIgnoreCase))
        {
            // 示例: Vpn.exe client 203.0.113.10 5000 1080
            var serverIp = IPAddress.Parse(args[1]);
            var serverPort = int.Parse(args[2]);
            var localPort = args.Length > 3 ? int.Parse(args[3]) : 1080;

            var client = new VpnClient(serverIp, serverPort, localPort);
            await client.StartAsync();
        }
        else if (args[0].Equals("server", StringComparison.OrdinalIgnoreCase))
        {
            // 示例: Vpn.exe server 5000
            var listenPort = args.Length > 1 ? int.Parse(args[1]) : 5000;
            var server = new VpnServer(listenPort);
            await server.StartAsync();
        }
    }
}
```

