  - Implements a **`require` function** that can load other JavaScript files (simple CommonJS‑style).
  - Optionally **spawns a separate Node.js process** and forwards `console.*` calls to its STDIN/STDOUT, mimicking a real terminal.

--- 

## 3. The “Node‑like” Shim (`NodeShim.kt`)

> **Why a shim?**  
> Nashorn is a pure JavaScript engine; it does **not** provide the Node built‑ins (`process`, `require`, `console`, etc.). The shim supplies just enough to feel like a Node REPL while keeping everything inside the Minecraft JVM.

### 3.1 Full Source

```kotlin
package com.example.forge

import jdk.nashorn.api.scripting.NashornScriptEngineFactory
import jdk.nashorn.api.scripting.ScriptObjectMirror
import java.io.*
import java.nio.file.Files
import java.nio.file.Path
import java.util.logging.Logger
import javax.script.Bindings
import javax.script.ScriptEngine
import javax.script.ScriptException

/**
 * NodeShim holds a Nashorn engine and wires a handful of Node‑style globals.
 *
 * @param logger  Forge logger used for fallback printing.
 */
class NodeShim(private val logger: Logger) {

    /** Underlying Nashorn engine */
    private val engine: ScriptEngine = NashornScriptEngineFactory()
        .getScriptEngine(
            // Enable "load" and "print" (these are standard Nashorn options)
            "--no-java", "--no-syntax-extensions"
        )

    /** Bindings that will be visible to all scripts */
    private val globalBindings: Bindings = engine.createBindings()

    /** Process used for the external Node terminal (if any) */
    private var nodeProcess: Process? = null
    private var nodeWriter: BufferedWriter? = null
    private var nodeReader: BufferedReader? = null

    init {
        // -----------------------------------------------------------------
        // 1. Install console object (console.log, etc.)
        // -----------------------------------------------------------------
        val console = object {
            fun log(vararg args: Any?) = forwardOutput("log", args)
            fun error(vararg args: Any?) = forwardOutput("error", args)
            fun warn(vararg args: Any?) = forwardOutput("warn", args)
            fun info(vararg args: Any?) = forwardOutput("info", args)
        }
        globalBindings["console"] = console

        // -----------------------------------------------------------------
        // 2. Provide a very simple CommonJS‑style require()
        // -----------------------------------------------------------------
        val require = object {
            fun require(moduleName: String): Any? {
                // Resolve relative paths or builtin pseudo‑modules
                return when (moduleName) {
                    "math" -> MathModule // example builtin
                    else -> loadJsModule(Path.of(moduleName))
                }
            }
        }
        globalBindings["require"] = require

        // -----------------------------------------------------------------
        // 3. Expose other useful globals (process, __dirname, etc.)
        // -----------------------------------------------------------------
        globalBindings["process"] = mapOf(
            "argv" to arrayOf<String>(),
            "platform" to System.getProperty("os.name")
        )
        engine.setBindings(globalBindings, javax.script.ScriptContext.GLOBAL_SCOPE)
    }

    // -----------------------------------------------------------------
    // PUBLIC API
    // -----------------------------------------------------------------

    /** Evaluate a single *.js file */
    @Throws(ScriptException::class, IOException::class)
    fun evalFile(file: Path) {
        Files.newBufferedReader(file).use { reader ->
            val script = reader.readText()
            // In a CommonJS style, we wrap the file in a function so that
            // `module`, `exports`, and `require` behave as expected.
            val wrapper = """
                (function (exports, require, module, __filename, __dirname) {
                    $script
                });
                """.trimIndent()
            val fn = engine.eval(wrapper) as ScriptObjectMirror
            val exports = mutableMapOf<String, Any?>()
            val module = mutableMapOf<String, Any?>("exports" to exports)
            val dirname = file.parent?.toAbsolutePath()?.toString() ?: ""
            fn.call(null, exports, globalBindings["require"], module, file.toString(), dirname)
        }
    }

    /** Start a separate Node.js process and wire its stdio */
    fun startNodeProcess() {
        // Look for a `node` binary on the system path
        val cmd = if (System.getProperty("os.name").lowercase().contains("win"))
            arrayOf("cmd", "/c", "node")
        else
            arrayOf("node")

        try {
            nodeProcess = ProcessBuilder(*cmd)
                .redirectErrorStream(true) // combine stdout+stderr
                .start()
            nodeWriter = BufferedWriter(OutputStreamWriter(nodeProcess!!.outputStream))
            nodeReader = BufferedReader(InputStreamReader(nodeProcess!!.inputStream))

            // Pump Node's output into the Forge logger (or console)
            Thread {
                var line: String?
                while (nodeReader!!.readLine().also { line = it } != null) {
                    logger.info("[Node] $line")
                }
            }.apply { isDaemon = true; start() }

            logger.info("Node.js subprocess started (PID=${nodeProcess!!.pid()})")
        } catch (e: IOException) {
            logger.warning("Could not start Node.js: ${e.message}. Falling back to JVM console.")
            nodeProcess = null
        }
    }

    /** Stop the Node subprocess (if running) */
    fun stopNodeProcess() {
        nodeProcess?.destroy()
        nodeProcess = null
    }

    // -----------------------------------------------------------------
    // INTERNAL HELPERS
    // -----------------------------------------------------------------

    /** Simple builtin module – can be expanded or replaced */
    private object MathModule {
        @JvmStatic fun add(a: Number, b: Number) = a.toDouble() + b.toDouble()
        @JvmStatic fun mul(a: Number, b: Number) = a.toDouble() * b.toDouble()
    }

    /** Resolve a script file for `require` (relative to the current working dir) */
    @Throws(IOException::class)
    private fun loadJsModule(path: Path): Any? {
        val resolved = if (path.isAbsolute) path else Path.of(System.getProperty("user.dir")).resolve(path)
        if (!Files.exists(resolved)) {
            logger.warning("require() could not find $resolved")
            return null
        }
        // Load the file and return its `module.exports`
        val script = Files.readString(resolved)
        val wrapper = """
            (function (exports, require, module, __filename, __dirname) {
                $script
            });
            """.trimIndent()
        val fn = engine.eval(wrapper) as ScriptObjectMirror
        val exports = mutableMapOf<String, Any?>()
        val module = mutableMapOf<String, Any?>("exports" to exports)
        val dirname = resolved.parent?.toAbsolutePath()?.toString() ?: ""
        fn.call(null, exports, globalBindings["require"], module, resolved.toString(), dirname)
        // Return `module.exports`
        return module["exports"]
    }

    /** Forward console.* calls either to Node (if it exists) or to the Forge logger */
    private fun forwardOutput(level: String, args: Array<out Any?>) {
        val msg = args.joinToString(" ") { it?.toString() ?: "null" }
        // 1. Try to push to external Node process
        if (nodeWriter != null) {
            try {
                nodeWriter!!.write("$level $msg\n")
                nodeWriter!!.flush()
                return
            } catch (e: IOException) {
                logger.warning("Lost connection to Node process: ${e.message}")
                nodeWriter = null
                nodeProcess?.destroy()
            }
        }
        // 2. Fallback to the MC logger
        when (level) {
            "log", "info" -> logger.info(msg)
            "error" -> logger.severe(msg)
            "warn" -> logger.warning(msg)
            else -> logger.info(msg)
        }
    }
}
```

#### How It Works

| Feature | Implementation |
|---------|----------------|
| **`console`** | Kotlin `object` with methods (`log`, `error`, …). Calls are routed through `forwardOutput()`. |
| **`require`** | Very lightweight CommonJS loader. Looks for built‑ins (`math` shown as example) or loads a `.js` file, wrapping it in a function to expose `exports`, `module`, `require`, `__filename`, `__dirname`. |
| **Node process integration** | `startNodeProcess()` launches a separate `node` binary (if it’s on your `PATH`). The shim writes `console.*` calls to `node`’s stdin as simple text lines (`log Hello`). A background thread reads node’s stdout and prints it via the Forge logger, giving you a **terminal‑style view** in `logs/latest.log` or the console. |
| **Fallback** | If `node` isn’t found or the subprocess dies, the shim simply writes to the Minecraft logger – you still get output. |
| **Safety** | All scripts run in the same JVM, so they can call Java classes unless you explicitly block them. You can tighten security by **removing** `"--no-java"` from the engine options or **using a custom `ClassFilter`** (Nashorn supports that since JDK 8u40). |

---

