```java
package com.example.canvasupload;

import jakarta.servlet.http.HttpServletResponse;
import jakarta.validation.constraints.NotNull;
import lombok.AllArgsConstructor;
import lombok.Data;
import lombok.NoArgsConstructor;
import org.apache.tika.Tika;
import org.apache.tika.mime.MimeTypes;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.http.HttpHeaders;
import org.springframework.http.MediaType;
import org.springframework.http.ResponseEntity;
import org.springframework.util.unit.DataSize;
import org.springframework.validation.annotation.Validated;
import org.springframework.web.bind.annotation.*;
import org.springframework.web.multipart.MultipartFile;

import javax.imageio.ImageIO;
import java.awt.image.BufferedImage;
import java.io.*;
import java.nio.file.*;
import java.util.*;

@RestController
@RequestMapping("/api")
@Validated
public class CanvasUploadController {

    private final Path storageDir;
    private final Tika tika = new Tika(); // for mime sniffing

    // Configurable properties (application.yml)
    public CanvasUploadController(@Value("${app.storage.dir}") String dir) throws IOException {
        this.storageDir = Paths.get(dir).toAbsolutePath().normalize();
        Files.createDirectories(this.storageDir);
    }

    // ---------- 2️⃣ POST endpoint ----------
    @PostMapping(value = "/uploadCanvas", consumes = MediaType.MULTIPART_FORM_DATA_VALUE)
    public ResponseEntity<Map<String, String>> handleCanvasUpload(
            @RequestPart("image") @NotNull MultipartFile file) throws IOException {

        // ---- STEP 1: Global size limit (Spring Boot property) ----
        // (configured via spring.servlet.multipart.max-file-size, see below)

        // ---- STEP 2: Validate content type (whitelist) ----
        String detectedMime = tika.detect(file.getInputStream());
        List<String> allowedMimes = List.of("image/png", "image/jpeg", "image/webp");
        if (!allowedMimes.contains(detectedMime)) {
            return ResponseEntity.badRequest()
                    .body(Map.of("error", "Unsupported image type: " + detectedMime));
        }

        // ---- STEP 3: Verify that the bytes really decode as an image ----
        try (InputStream is = file.getInputStream()) {
            BufferedImage img = ImageIO.read(is);
            if (img == null) {
                return ResponseEntity.badRequest()
                        .body(Map.of("error", "File is not a valid image"));
            }
        }

        // ---- STEP 4: (Optional) Scan with an AV engine ----
        // Example stub – replace with real ClamAV / VirusTotal integration.
        // if (!avScanner.isClean(file.getBytes())) { … }

        // ---- STEP 5: Generate a safe, random filename ----
        String ext = MimeTypes.getDefaultMimeTypes().forName(detectedMime).getExtension(); // ".png"
        String safeName = UUID.randomUUID().toString() + ext;
        Path target = storageDir.resolve(safeName);

        // ---- STEP 6: Store atomically (move from temp) ----
        try (InputStream is = file.getInputStream()) {
            Files.copy(is, target, StandardCopyOption.REPLACE_EXISTING);
        }

        // ---- STEP 7: Return a reference (ID or URL) ----
        String url = "/images/" + safeName; // We'll expose a GET endpoint below
        return ResponseEntity.ok(Map.of("id", safeName, "url", url));
    }

    // ---------- 4️⃣ GET endpoint for serving the image ----------
    @GetMapping("/images/{filename:.+}")
    public void serveImage(@PathVariable String filename,
                           HttpServletResponse response) throws IOException {

        // Prevent path traversal – we only accept filenames that match the generated pattern
        if (!filename.matches("[0-9a-fA-F-]{36}\\.[a-z]{3,4}")) {
            response.sendError(HttpServletResponse.SC_BAD_REQUEST, "Invalid filename");
            return;
        }

        Path imagePath = storageDir.resolve(filename).normalize();

        // Ensure the file exists and is inside the storage dir
        if (!Files.isRegularFile(imagePath) || !imagePath.startsWith(storageDir)) {
            response.sendError(HttpServletResponse.SC_NOT_FOUND);
            return;
        }

        // Detect MIME again (small overhead, but guarantees we send the right type)
        String mime = tika.detect(imagePath);
        response.setContentType(mime);
        // Defensive headers
        response.setHeader(HttpHeaders.CONTENT_DISPOSITION, "inline; filename=\"" + filename + "\"");
        response.setHeader(HttpHeaders.CACHE_CONTROL, "private, max-age=86400"); // 1‑day cache
        response.setHeader("X-Content-Type-Options", "nosniff"); // stop content sniffing attacks
        response.setHeader("X-Frame-Options", "SAMEORIGIN"); // optional, if you embed in iframes

        // Stream file – do NOT load whole image into memory for large uploads
        try (InputStream is = Files.newInputStream(imagePath);
             OutputStream os = response.getOutputStream()) {
            is.transferTo(os);
        }
    }
}
