### 2.2 Plain Servlet Approach (for legacy containers)

```java
@WebServlet("/uploadCanvas")
@MultipartConfig(
        fileSizeThreshold = 1024 * 1024, // 1 MiB before writing to disk
        maxFileSize = 5 * 1024 * 1024,   // 5 MiB per file
        maxRequestSize = 5 * 1024 * 1024 // total request size
)
public class CanvasUploadServlet extends HttpServlet {

    private final Path storageDir = Paths.get(System.getProperty("java.io.tmpdir"), "canvas-uploads");
    private final Tika tika = new Tika();
    private final List<String> whitelist = List.of("image/png", "image/jpeg", "image/webp");

    @Override
    public void init() throws ServletException {
        try {
            Files.createDirectories(storageDir);
        } catch (IOException e) {
            throw new ServletException("Unable to create storage dir", e);
        }
    }

    @Override
    protected void doPost(HttpServletRequest req, HttpServletResponse resp) throws ServletException, IOException {
        Part part = req.getPart("image");
        if (part == null) {
            resp.sendError(HttpServletResponse.SC_BAD_REQUEST, "Missing 'image' part");
            return;
        }

        // ---- Size limit already enforced by @MultipartConfig ----

        // ---- MIME sniffing ----
        String mime = tika.detect(part.getInputStream());
        if (!whitelist.contains(mime)) {
            resp.sendError(HttpServletResponse.SC_UNSUPPORTED_MEDIA_TYPE, "Invalid image type");
            return;
        }

        // ---- Verify actual image decode ----
        try (InputStream is = part.getInputStream()) {
            if (ImageIO.read(is) == null) {
                resp.sendError(HttpServletResponse.SC_BAD_REQUEST, "Invalid image data");
                return;
            }
        }

        // ---- Generate safe filename ----
        String ext = mime.split("/")[1]; // e.g., "png"
        String safeName = UUID.randomUUID().toString() + "." + ext;
        Path target = storageDir.resolve(safeName);

        // ---- Store atomically ----
        try (InputStream is = part.getInputStream()) {
            Files.copy(is, target, StandardCopyOption.REPLACE_EXISTING);
        }

        // ---- Respond with JSON (use a proper JSON library in production) ----
        resp.setContentType("application/json");
        resp.getWriter().write("{\"id\":\"" + safeName + "\",\"url\":\"/image/" + safeName + "\"}");
    }

    // GET endpoint for /image/* placed in another servlet or via a filter
}
