```javascript
import React, { useRef, useState } from 'react';
import './App.css';

function App() {
  const canvasRef = useRef();
  const [preview, setPreview] = useState(null);
  const [error, setError] = useState(null);

  const drawDemo = () => {
    const ctx = canvasRef.current.getContext('2d');
    ctx.fillStyle = '#f44336';
    ctx.fillRect(0, 0, 300, 150);
    ctx.fillStyle = '#fff';
    ctx.font = '30px sans-serif';
    ctx.fillText('Canvas Demo', 30, 80);
  };

  const upload = async () => {
    const fmt = 'image/png';
    const blob = await new Promise(res => canvasRef.current.toBlob(res, fmt));
    const fd = new FormData();
    fd.append('image', blob, 'demo.png');

    try {
      const resp = await fetch('/api/uploadCanvas', {
        method: 'POST',
        credentials: 'same-origin', // CSRF cookie automatically sent
        body: fd,
      });

      if (!resp.ok) {
        const txt = await resp.text();
        throw new Error(txt || 'Upload failed');
      }

      const data = await resp.json(); // { id, url }
      setPreview(data.url);
      setError(null);
    } catch (e) {
      setError(e.message);
    }
  };

  return (
    <div className="App">
      <h1>Canvas → Blob → Java Upload</h1>
      <canvas ref={canvasRef} width={300} height={150}></canvas>
      <div style={{ marginTop: 10 }}>
        <button onClick={drawDemo}>Draw Demo</button>
        <button onClick={upload}>Upload</button>
      </div>
      {error && <p style={{ color: 'red' }}>{error}</p>}
      {preview && (
        <div style={{ marginTop: 20 }}>
          <h3>Stored image:</h3>
          <img src={preview} alt="uploaded" />
        </div>
      )}
    </div>
  );
}

export default App;
```

