## 3. REST Controller

```java
package com.ncs.api.auth.controller;

import com.ncs.api.auth.dto.*;
import com.ncs.api.auth.service.AuthFailureException;
import com.ncs.api.auth.service.FrontendAuthService;
import jakarta.servlet.http.HttpServletRequest;

import org.springframework.http.HttpStatus;
import org.springframework.http.ResponseEntity;
import org.springframework.validation.annotation.Validated;
import org.springframework.web.bind.annotation.*;

@RestController
@RequestMapping("/api/auth")
@Validated
public class AuthController {

    private final FrontendAuthService authService;

    public AuthController(FrontendAuthService authService) {
        this.authService = authService;
    }

    /**
     * Front‑end login endpoint.
     *
     * POST /api/auth/login
     * {
     *   "login": "john.doe@example.com",
     *   "password": "s3cr3t"
     * }
     */
    @PostMapping("/login")
    public ResponseEntity<?> login(@RequestBody LoginRequest request,
                                   HttpServletRequest servletRequest) {

        // Extract client IP (fallback to X‑Forwarded‑For for reverse‑proxy setups)
        String clientIp = servletRequest.getHeader("X-Forwarded-For");
        if (clientIp == null || clientIp.isBlank()) {
            clientIp = servletRequest.getRemoteAddr();
        }

        try {
            AuthSuccessResponse resp = authService.authenticate(
                    request.getLogin(),
                    request.getPassword(),
                    clientIp
            );
            return ResponseEntity.ok(resp);
        } catch (AuthFailureException ex) {
            AuthErrorResponse err = new AuthErrorResponse();
            err.setTitle(ex.getTitle());
            err.setMessage(ex.getMessage());
            err.setHint(ex.getHint());
            err.setType(ex.getType());
            err.setLockAccount(ex.isLockAccount());

            // 400 – bad request (invalid credentials, account locked, etc.)
            // 401 – could be used as well, but we keep a single contract.
            return ResponseEntity.status(HttpStatus.BAD_REQUEST).body(err);
        }
    }
}
```

