## 4. Global Exception‑Handling (optional but recommended)

```java
package com.ncs.api.auth.exception;

import com.ncs.api.auth.dto.AuthErrorResponse;
import com.ncs.api.auth.service.AuthFailureException;
import org.springframework.http.HttpStatus;
import org.springframework.http.ResponseEntity;
import org.springframework.web.bind.annotation.*;

@RestControllerAdvice
public class GlobalAuthExceptionHandler {

    @ExceptionHandler(AuthFailureException.class)
    public ResponseEntity<AuthErrorResponse> handleAuthFailure(AuthFailureException ex) {
        AuthErrorResponse err = new AuthErrorResponse();
        err.setTitle(ex.getTitle());
        err.setMessage(ex.getMessage());
        err.setHint(ex.getHint());
        err.setType(ex.getType());
        err.setLockAccount(ex.isLockAccount());

        return ResponseEntity.status(HttpStatus.BAD_REQUEST).body(err);
    }

    // catch‑all for unexpected runtime errors – never leak stacktraces to the client
    @ExceptionHandler(Exception.class)
    public ResponseEntity<AuthErrorResponse> handleUnexpected(Exception ex) {
        AuthErrorResponse err = new AuthErrorResponse();
        err.setTitle("Внутренняя ошибка сервера");
        err.setMessage("Попробуйте позже. Если проблема сохраняется — обратитесь в службу поддержки.");
        err.setHint(null);
        err.setType("DANGER");
        err.setLockAccount(false);

        // log the exception (use your preferred logger)
        ex.printStackTrace(); // replace with logger.error(...)

        return ResponseEntity.status(HttpStatus.INTERNAL_SERVER_ERROR).body(err);
    }
}
