 *   5. 设置正确的 Content‑Type 与字符编码；
 *   6. 防止 HTTP 参数污染（只读取预期字段）。
 */
@WebServlet(name = "DivideServlet", urlPatterns = {"/divide"})
public class DivideServlet extends HttpServlet {

    /** 简单的 HTML 实体转义工具（生产环境建议使用 OWASP ESAPI、Apache Commons Text 等） */
    private String escapeHtml(String s) {
        if (s == null) return "";
        return s.replace("&", "&amp;")
                .replace("<", "&lt;")
                .replace(">", "&gt;")
                .replace("\"", "&quot;")
                .replace("'", "&#x27;");
    }

    /** 这里演示一个极简的 CSRF Token 校验（实际请使用会话或 Double‑Submit‑Cookie 等） */
    private boolean isValidCsrfToken(HttpServletRequest req) {
        String tokenFromForm = req.getParameter("csrfToken");
        // 假设在用户登录后把 token 保存到 session 中
        HttpSession session = req.getSession(false);
        if (session == null) return false;
        String tokenFromSession = (String) session.getAttribute("csrfToken");
        return tokenFromForm != null && tokenFromForm.equals(tokenFromSession);
    }

    @Override
    protected void doPost(HttpServletRequest request, HttpServletResponse response)
            throws ServletException, IOException {

        // 1️⃣ 设定请求字符集（防止乱码+防止 Unicode 注入）
        request.setCharacterEncoding("UTF-8");
        response.setContentType("text/html;charset=UTF-8");

        // 2️⃣ CSRF 校验（如未实现可注释掉）
        // if (!isValidCsrfToken(request)) {
        //     response.sendError(HttpServletResponse.SC_FORBIDDEN, "Invalid CSRF token");
        //     return;
        // }

        // 3️⃣ 读取仅需的两个参数
        String dividendStr = request.getParameter("dividend");
        String divisorStr  = request.getParameter("divisor");

        // 4️⃣ 参数为空或未提交的快速返回
        if (dividendStr == null || divisorStr == null ||
            dividendStr.isEmpty() || divisorStr.isEmpty()) {
            sendError(response, "请提供完整的两个数字");
            return;
        }

        double dividend, divisor;
        try {
            // 5️⃣ 严格的数值转换（捕获 NumberFormatException）
            dividend = Double.parseDouble(dividendStr.trim());
            divisor  = Double.parseDouble(divisorStr.trim());
        } catch (NumberFormatException e) {
            sendError(response, "输入的内容不是合法的数字");
            return;
        }

        // 6️⃣ 除数为 0 的业务校验
        if (Math.abs(divisor) < Double.MIN_VALUE) { // 对 double 做近似比较
            sendError(response, "除数不能为 0");
            return;
        }

        // 7️⃣ 实际除法运算
        double result = dividend / divisor;

        // 8️⃣ 生成安全的 HTML 响应
        PrintWriter out = response.getWriter();
        out.println("<!DOCTYPE html>");
        out.println("<html lang=\"zh-CN\"><head><meta charset=\"UTF-8\"><title>运算结果</title></head><body>");
        out.println("<h1>除法运算结果</h1>");
        out.println("<p>");
        out.println(escapeHtml(dividendStr) + " ÷ " + escapeHtml(divisorStr) + " = " + result);
        out.println("</p>");
        out.println("<p><a href=\"divide.html\">返回继续计算</a></p>");
        out.println("</body></html>");
    }

    /** 统一错误页面输出，避免把异常堆栈直接返回给终端用户 */
    private void sendError(HttpServletResponse resp, String message) throws IOException {
        resp.setStatus(HttpServletResponse.SC_BAD_REQUEST);
        PrintWriter out = resp.getWriter();
        out.println("<!DOCTYPE html>");
        out.println("<html lang=\"zh-CN\"><head><meta charset=\"UTF-8\"><title>错误</title></head><body>");
        out.println("<h1>错误提示</h1>");
        out.println("<p class=\"error\">" + escapeHtml(message) + "</p>");
        out.println("<p><a href=\"divide.html\">返回重新输入</a></p>");
        out.println("</body></html>");
    }
}
```

