package com.example.security;

import javax.xml.XMLConstants;
import javax.xml.parsers.DocumentBuilder;
import javax.xml.parsers.DocumentBuilderFactory;
import javax.xml.parsers.ParserConfigurationException;

import javax.xml.transform.OutputKeys;
import javax.xml.transform.Transformer;
import javax.xml.transform.TransformerFactory;
import javax.xml.transform.dom.DOMSource;
import javax.xml.transform.stream.StreamResult;

import javax.xml.xpath.XPath;
import javax.xml.xpath.XPathConstants;
import javax.xml.xpath.XPathExpression;
import javax.xml.xpath.XPathFactory;

import org.w3c.dom.Document;
import org.w3c.dom.Node;
import org.w3c.dom.NodeList;

/**
 * Utility to safely extract a piece of XML from a raw XML string.
 *
 * <p>Typical usage:
 *
 * <pre>{@code
 * String xml = "<root><secret>abc</secret><data id=\"42\">Hello</data></root>";
 * String xpath = "/root/data";
 * String result = XmlExtractor.extractFragment(xml, xpath);
 * System.out.println(result);   // prints: <data id="42">Hello</data>
 * }</pre>
 *
 * <p>The class disables DTDs, external entities and other risky features,
 * preventing XXE and denial‑of‑service attacks such as the Billion Laughs attack.
 */
public final class XmlExtractor {

    private XmlExtractor() {
        // Utility class – no instantiation.
    }

    /**
     * Parses the supplied XML string, runs the given XPath expression,
     * and returns the matched node (or node list) as a string.
     *
     * @param xmlString        the complete XML document as a {@code String}
     * @param xpathExpression  an XPath expression that selects the fragment you want.
     *                         Example: {@code "/root/data"} or {@code "//item[@id='10']"}
     * @return the XML fragment(s) that match the XPath expression,
     *         serialized exactly as they appear in the original document
     *         (including start/end tags and attributes). If nothing matches,
     *         an empty string is returned.
     *
     * @throws Exception if parsing fails, the XPath is malformed,
     *                   or any security‑related feature cannot be disabled.
     */
    public static String extractFragment(String xmlString, String xpathExpression) throws Exception {
        if (xmlString == null) {
            throw new IllegalArgumentException("xmlString must not be null");
        }
        if (xpathExpression == null || xpathExpression.isBlank()) {
            throw new IllegalArgumentException("xpathExpression must not be null/blank");
        }

        // --------------------------------------------------------------------
        // 1. Build a *secure* DocumentBuilderFactory
        // --------------------------------------------------------------------
        DocumentBuilderFactory dbf = DocumentBuilderFactory.newInstance();

        // ---- Disallow DTDs (prevents external entity attacks) ----
        dbf.setFeature("http://apache.org/xml/features/disallow-doctype-decl", true);
        // ---- Disallow external general entities ----
        dbf.setFeature("http://xml.org/sax/features/external-general-entities", false);
        // ---- Disallow external parameter entities ----
        dbf.setFeature("http://xml.org/sax/features/external-parameter-entities", false);
        // ---- Disallow XML Entity Expansion (Billion Laughs) ----
        dbf.setFeature("http://apache.org/xml/features/entity-expansion-limit", true);
        // ---- Secure processing (also disables DTDs on some parsers) ----
        dbf.setFeature(XMLConstants.FEATURE_SECURE_PROCESSING, true);

        // Optional: turn off validation entirely (we are only interested in well‑formed XML)
        dbf.setValidating(false);
        dbf.setNamespaceAware(true); // needed for most XPath expressions

        DocumentBuilder db = dbFactorySecureBuilder(dbf);

        // --------------------------------------------------------------------
        // 2. Parse the XML string into a DOM Document
        // --------------------------------------------------------------------
        Document doc = db.parse(new java.io.ByteArrayInputStream(xmlString.getBytes(java.nio.charset.StandardCharsets.UTF_8)));

        // --------------------------------------------------------------------
        // 3. Compile and evaluate the XPath expression
        // --------------------------------------------------------------------
        XPathFactory xPathFactory = XPathFactory.newInstance();
        XPath xpath = xPathFactory.newXPath();

        XPathExpression expr = xpath.compile(xpathExpression);
        Object evaluationResult = expr.evaluate(doc, XPathConstants.NODESET);
        NodeList nodes = (NodeList) evaluationResult;

        // --------------------------------------------------------------------
        // 4. Serialize matched node(s) back to a String
        // --------------------------------------------------------------------
        if (nodes.getLength() == 0) {
            return ""; // nothing matched
        }

        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < nodes.getLength(); i++) {
            Node n = nodes.item(i);
            sb.append(nodeToString(n));
        }
        return sb.toString();
    }

    // ------------------------------------------------------------------------
    // Helper: create a DocumentBuilder that throws on any anti‑feature failure
    // ------------------------------------------------------------------------
    private static DocumentBuilder dbFactorySecureBuilder(DocumentBuilderFactory dbf) throws ParserConfigurationException {
        // Some XML parsers will *silently* ignore a feature they don't understand.
        // By calling `setFeature` inside the method above, we already forced the
        // parser to fail fast if the feature is unsupported. The following
        // statement forces the factory to *really* apply the configuration.
        dbf.setXIncludeAware(false);
        dbf.setExpandEntityReferences(false);
        return dbf.newDocumentBuilder();
    }

    // ------------------------------------------------------------------------
    // Helper: turn a DOM Node (Element, Document, etc.) into a pretty XML string
    // ------------------------------------------------------------------------
    private static String nodeToString(Node node) throws Exception {
        // We use a Transformer with indentation turned off to preserve the
        // original formatting as much as possible (the JDK doesn't keep whitespace
        // exactly as in the source, but this is usually good enough).
        TransformerFactory tf = TransformerFactory.newInstance();

        // Secure‑processing again – some transformer implementations support external
        // entities via XSLT; we disable them.
        tf.setFeature(XMLConstants.FEATURE_SECURE_PROCESSING, true);
        Transformer transformer = tf.newTransformer();

        // Omit XML declaration for fragments (otherwise you'll get `<?xml …?>` on every node)
        transformer.setOutputProperty(OutputKeys.OMIT_XML_DECLARATION, "yes");
        // Preserve original encoding (we use UTF‑8 throughout)
        transformer.setOutputProperty(OutputKeys.ENCODING, "UTF-8");
        // Optional: no indentation
        transformer.setOutputProperty(OutputKeys.INDENT, "no");

        java.io.StringWriter writer = new java.io.StringWriter();
        transformer.transform(new DOMSource(node), new StreamResult(writer));
        return writer.toString();
    }

    // ------------------------------------------------------------------------
    // Demo / simple test harness – can be removed or turned into a unit test
    // ------------------------------------------------------------------------
    public static void main(String[] args) {
        try {
            String xml = """
                    <?xml version="1.0" encoding="UTF-8"?>
                    <root>
                        <secret>top‑secret</secret>
                        <data id="42">Hello <b>world</b>!</data>
                        <list>
                            <item>first</item>
                            <item>second</item>
                        </list>
                    </root>
                    """;

