            String xpath1 = "/root/data";
            System.out.println("XPath 1 result: " + extractFragment(xml, xpath1));
            // → <data id="42">Hello <b>world</b>!</data>

            // 2️⃣  Extract all <item> nodes (returns them concatenated)
            String xpath2 = "//item";
            System.out.println("XPath 2 result: " + extractFragment(xml, xpath2));
