import org.bytedeco.javacv.*;

public class RealTimeStreamer {
    // 视频参数（可根据实际需求调节）
    private static final int WIDTH  = 1280;
    private static final int HEIGHT = 720;
    private static final int FRAME_RATE = 30;   // 目标帧率
    private static final int BITRATE = 2000_000; // 2Mbit/s

    private FFmpegFrameRecorder recorder;

    /**
     * @param outputUrl 典型形式：rtmp://host/app/streamKey
     */
    public RealTimeStreamer(String outputUrl) {
        // 第三个参数是音频通道数（这里不使用音频，设为 0）
        recorder = new FFmpegFrameRecorder(outputUrl, WIDTH, HEIGHT, 0);
        // 关键参数配置
        recorder.setFormat("flv");                 // RTMP 常用容器
        recorder.setVideoCodec(avcodec.AV_CODEC_ID_H264);
        recorder.setFrameRate(FRAME_RATE);
        recorder.setVideoBitrate(BITRATE);
        recorder.setPixelFormat(avutil.AV_PIX_FMT_YUV420P); // H.264 常用像素格式

        // 可选：开启低延迟模式
        recorder.setOption("tune", "zerolatency");
        recorder.setOption("preset", "ultrafast");
    }

    public void start() throws FrameRecorder.Exception {
        recorder.start();
    }

    public void record(Frame frame) throws FrameRecorder.Exception {
        recorder.record(frame);
    }

    public void stop() throws FrameRecorder.Exception {
        recorder.stop();
        recorder.release();
    }
}
```

### 2.2 捕获摄像头并实时推送

```java
public static void main(String[] args) throws Exception {
    // 1) 目标 RTMP 地址（请自行部署 RTMP 服务器或使用云服务）
    String rtmpUrl = "rtmp://my-rtmp-server/app/stream123?token=YOUR_SECURE_TOKEN";

    RealTimeStreamer streamer = new RealTimeStreamer(rtmpUrl);
    streamer.start();

    // 2) 获取本地摄像头（OpenCV FrameGrabber）
    OpenCVFrameGrabber grabber = new OpenCVFrameGrabber(0);
    grabber.setImageWidth(WIDTH);
    grabber.setImageHeight(HEIGHT);
    grabber.start();

    long startTime = System.nanoTime();
    long frameCount = 0;

    while (frameCount < 300) { // 示例推流 10 秒（30fps * 10）
        Frame frame = grabber.grab();
        if (frame == null) continue;

        // 计算时间戳，确保连续播放的同步（尤其是推 RTMP 时）
        long ts = (System.nanoTime() - startTime) / 1000;   // 微秒
        frame.timestamp = ts;

        streamer.record(frame);
        frameCount++;
    }

    // 3) 资源释放
    grabber.stop();
    grabber.release();
    streamer.stop();

    System.out.println("推流结束");
}
```

