## 3️⃣ JWT 工具类

```java
// src/main/java/com/example/demo/security/JwtUtil.java
package com.example.demo.security;

import io.jsonwebtoken.*;
import io.jsonwebtoken.security.Keys;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.stereotype.Component;

import java.security.Key;
import java.util.Date;

@Component
public class JwtUtil {

    // 读取配置文件中的 secret（建议使用 environment 变量或密钥管理系统）
    private final Key key;
    private final long jwtExpirationInMs;

    public JwtUtil(@Value("${app.jwtSecret}") String secret,
                   @Value("${app.jwtExpirationMs}") long expirationMs) {
        // secret 必须至少 256 位（32 字节）才能用于 HS256
        this.key = Keys.hmacShaKeyFor(secret.getBytes());
        this.jwtExpirationInMs = expirationMs;
    }

    /** 生成 token */
    public String generateToken(String username) {
        Date now = new Date();
        Date expiry = new Date(now.getTime() + jwtExpirationInMs);
        return Jwts.builder()
                .setSubject(username)
                .setIssuedAt(now)
                .setExpiration(expiry)
                .signWith(key, SignatureAlgorithm.HS256)
                .compact();
    }

    /** 解析 token，返回用户名（subject） */
    public String getUsernameFromToken(String token) {
        return Jwts.parserBuilder()
                .setSigningKey(key)
                .build()
                .parseClaimsJws(token)
                .getBody()
                .getSubject();
    }

    /** 校验 token 是否合法、未过期 */
    public boolean validateToken(String token) {
        try {
            Jwts.parserBuilder().setSigningKey(key).build().parseClaimsJws(token);
            return true;
        } catch (JwtException | IllegalArgumentException e) {
            // 这里可以细分异常 (ExpiredJwtException, MalformedJwtException …)
            return false;
        }
    }
}
```

