## 🎯 Пример полного рабочего кода (Android + Kotlin)

```kotlin
// 1️⃣ Читаем XML из assets (можно заменить на любой InputStream)
fun readXmlFromAssets(context: Context, fileName: String): InputStream =
    context.assets.open(fileName)

// 2️⃣ Парсим безопасно
fun extractArrayNamesSecure(stream: InputStream): List<String> =
    parseArrayNames(stream)

// 3️⃣ Преобразуем имена в ресурсные ID (если нужны)
fun mapNamesToResIds(context: Context, names: List<String>): List<Int> =
    resolveIds(context, names)

// 4️⃣ Всё вместе
fun getArrayIdsFromExternalXml(context: Context, xmlFile: String): List<Int> {
    context.assets.open(xmlFile).use { xmlStream ->
        val names = extractArrayNamesSecure(xmlStream)
        return mapNamesToResIds(context, names)
    }
}

// Пример вызова (например, в Activity)
val ids = getArrayIdsFromExternalXml(this, "external.xml")
Log.i("SEC", "Получены ID массивов: $ids")
```

