```java
package com.example.blockchain;

import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.time.Instant;

/**
 * A single block in our blockchain.
 *
 * SECURITY NOTE:
 *   • All fields that affect the block hash are declared final – they must never
 *     change after the block is mined.  Mutating a field would break the
 *     cryptographic integrity guarantees.
 *   • The hash is calculated using SHA‑256, which is currently considered
 *     pre‑image resistant and collision‑resistant for the size of the data
 *     we store (small educational payloads).  Production chains often
 *     switch to SHA‑3 or a custom PoW hash algorithm (e.g., Ethash, Equihash)
 *     to mitigate ASIC centralisation.
 */
public class Block {

    /* ---------- immutable block header ---------- */
    private final int index;                 // position in the chain
    private final long timestamp;            // seconds since epoch
    private final String previousHash;       // hash of the preceding block
    private final String data;               // any payload (e.g., transaction list)
    private final int difficulty;            // number of leading zero bits required

    /* ---------- mutable mining fields ---------- */
    private long nonce;                      // varies during PoW
    private String hash;                     // resulting hash after mining

    /**
     * Construct a new block. Mining is performed later via {@link #mineBlock()}.
     *
     * @param index         sequential index (0 for genesis)
     * @param data          payload (transactions, etc.)
     * @param previousHash  hash of the previous block (or "0" for genesis)
     * @param difficulty    PoW difficulty – how many leading zero *bits* are required
     */
    public Block(int index, String data, String previousHash, int difficulty) {
        this.index = index;
        this.timestamp = Instant.now().getEpochSecond();
        this.previousHash = previousHash;
        this.data = data;
        this.difficulty = difficulty;
        this.nonce = 0L;
        this.hash = calculateHash();   // initial hash (pre‑PoW) – will change after mining
    }

    /** Compute the block hash from the *current* fields. */
    public String calculateHash() {
        String input = index + Long.toString(timestamp) + previousHash + data + nonce;
        return applySHA256(input);
    }

    /** Perform proof‑of‑work – find a nonce that yields a hash with the required leading zeros. */
    public void mineBlock() {
        String target = "0".repeat(difficulty); // e.g. difficulty=4 → "0000"
        while (!hash.substring(0, difficulty).equals(target)) {
            nonce++;
            hash = calculateHash();
        }
        System.out.println("Block Mined! #" + index + " [hash: " + hash + "]");
    }

    /** Utility: SHA‑256 hash of a string, returned as a hex‑string. */
    public static String applySHA256(String input) {
        try {
            MessageDigest digest = MessageDigest.getInstance("SHA-256");
            byte[] hashBytes = digest.digest(input.getBytes(StandardCharsets.UTF_8));

            // Convert byte[] → hex string
            StringBuilder hexString = new StringBuilder(2 * hashBytes.length);
            for (byte b : hashBytes) {
                String hex = Integer.toHexString(0xff & b);
                if (hex.length() == 1) hexString.append('0');
                hexString.append(hex);
            }
            return hexString.toString();

        } catch (Exception e) {
            throw new RuntimeException("SHA-256 algorithm not available", e);
        }
    }

    /* ----------- getters (no setters – immutability) ----------- */
    public int getIndex() { return index; }
    public long getTimestamp() { return timestamp; }
    public String getPreviousHash() { return previousHash; }
    public String getData() { return data; }
    public int getDifficulty() { return difficulty; }
    public long getNonce() { return nonce; }
    public String getHash() { return hash; }

    @Override
    public String toString() {
        return "Block{" +
                "index=" + index +
                ", timestamp=" + timestamp +
                ", previousHash='" + previousHash + '\'' +
                ", data='" + data + '\'' +
                ", difficulty=" + difficulty +
                ", nonce=" + nonce +
                ", hash='" + hash + '\'' +
                '}';
    }
}
```

### Why these choices matter  

| Item | Security implication |
|------|----------------------|
| **`final` fields** | Guarantees no post‑mining mutation. If a block could be altered after being linked, an attacker could change transaction data without breaking the chain. |
| **SHA‑256** | Widely vetted, currently resistant to pre‑image attacks. It is *slow enough* for a toy PoW yet fast enough to run on a laptop. |
| **Proof‑of‑Work** | Improves *liveness* and *tamper resistance*: an attacker must redo the PoW for the target block **and** all subsequent blocks to rewrite history. |
| **Difficulty as leading‐zero **bits*** | Simpler than Bitcoin’s “target” representation, but still conveys the same exponential work factor. |

