        // 1️⃣  Initialise a blockchain with a modest difficulty
        // ---------------------------------------------------------
        int difficulty = 4;               // 4 leading zeros ≈ 2^4 hash attempts per block on average
        Blockchain blockchain = new Blockchain(difficulty);

        // ---------------------------------------------------------
        // 2️⃣  Add a few blocks (simulating transactions)
        // ---------------------------------------------------------
        System.out.println("\n--- Adding blocks ---");
        blockchain.addBlock("Alice pays Bob 5 BTC");
        blockchain.addBlock("Bob pays Charlie 2 BTC");
        blockchain.addBlock("Charlie pays Dave 1 BTC");

        System.out.println("\n--- Full chain dump ---");
        System.out.println(blockchain);

        // ---------------------------------------------------------
        // 3️⃣  Verify chain integrity – should be VALID
        // ---------------------------------------------------------
        System.out.println("Is chain valid? " + blockchain.isChainValid());

        // ---------------------------------------------------------
        // 4️⃣  *Malicious* tampering: change data of the second block
        // ---------------------------------------------------------
        System.out.println("\n--- Tampering with block #2 ---");
        Block tampered = blockchain.getChain().get(2); // index 2 = third block (0‑based)
