            java.lang.reflect.Field dataField = Block.class.getDeclaredField("data");
            dataField.setAccessible(true);
            dataField.set(tampered, "Alice pays Mallory 100 BTC"); // corrupt the payload
        } catch (Exception e) {
            throw new RuntimeException(e);
        }

        System.out.println("After tampering, is chain valid? " + blockchain.isChainValid());

        // ---------------------------------------------------------
        // 5️⃣  (Optional) Re‑mine the tampered block to *force* a valid chain.
        // ---------------------------------------------------------
        System.out.println("\n--- Re‑mining tampered block (simulating 51% attacker) ---");
        tampered.mineBlock();                // redo PoW for the corrupted block only
        // Note: we must also re‑mine *all* subsequent blocks, otherwise the link breaks.
        // For brevity we only re‑mine the immediate successor:
        Block next = blockchain.getChain().get(3);
        // Re‑link the hash pointer & re‑mine
        java.lang.reflect.Field prevHashField = Block.class.getDeclaredField("previousHash");
        prevHashField.setAccessible(true);
        prevHashField.set(next, tampered.getHash());
        next.mineBlock();

        System.out.println("\n--- Chain after attacker re‑mined the altered segment ---");
        System.out.println(blockchain);
        System.out.println("Is chain valid now? " + blockchain.isChainValid());
    }
