import jakarta.servlet.RequestDispatcher;
import jakarta.servlet.http.HttpServletRequest;
import org.springframework.boot.web.error.ErrorAttributeOptions;
import org.springframework.boot.web.servlet.error.ErrorAttributes;
import org.springframework.boot.web.servlet.error.ErrorController;
import org.springframework.stereotype.Controller;
import org.springframework.ui.Model;
import org.springframework.web.bind.annotation.GetMapping;

import java.util.Map;

/**
 * A minimal, **secure** error controller that renders a custom HTML page.
 *
 * <p>
 *   It does NOT expose stack traces or internal exception messages to the client.
 *   All sensitive details are logged server‑side only.
 * </p>
 */
@Controller
public class CustomErrorController implements ErrorController {

    private final ErrorAttributes errorAttributes;

    public CustomErrorController(ErrorAttributes errorAttributes) {
        this.errorAttributes = errorAttributes;
    }

    /**
     * Handles any request that reaches the framework's generic error endpoint.
     *
     * @param request the servlet request (used to fetch the HTTP status)
     * @param model   the MVC model that will be passed to the view
     * @return the logical view name of the custom error page (e.g. "error.html")
     */
    @GetMapping("/error")
    public String handleError(HttpServletRequest request, Model model) {
        // 1️⃣ Retrieve the error attributes **without** stacktrace / exception details.
        //    This prevents leakage of internal information.
        ErrorAttributeOptions options = ErrorAttributeOptions.defaults()
                // Explicitly *exclude* stack trace and exception messages
                .excluding(ErrorAttributeOptions.Include.STACK_TRACE)
                .excluding(ErrorAttributeOptions.Include.EXCEPTION);

        Map<String, Object> errorAttrs = errorAttributes.getErrorAttributes(request, options);
        int status = (int) errorAttrs.getOrDefault("status", 500);

        // 2️⃣ Populate a sanitized model for the view.
        model.addAttribute("status", status);
        model.addAttribute("error", errorAttrs.getOrDefault("error", "Unexpected error"));
        model.addAttribute("message", errorAttrs.getOrDefault("message", "An error occurred"));
        model.addAttribute("timestamp", errorAttrs.getOrDefault("timestamp", ""));

        // 3️⃣ Log the full details (including stack trace) for ops/security teams.
        //    DO NOT send these to the client.
        Exception ex = (Exception) request.getAttribute(RequestDispatcher.ERROR_EXCEPTION);
        if (ex != null) {
            // Use a logger that integrates with your central log system.
            // (e.g. Logback, Log4j2, etc.)
            // LoggerFactory.getLogger(CustomErrorController.class).error("Unhandled exception", ex);
        }

        // 4️⃣ Return the view name. Make sure you have `src/main/resources/templates/error.html`
        //    (or .ftl, .jsp, etc.) on the classpath.
