/* --------------------------------------------------------------
   3️⃣  CAMERA SETTINGS
   -------------------------------------------------------------- */
let camDist = 8;               // distance of “camera” from origin (used for perspective)
function project(v){
  // simple perspective:  (x/z, y/z) scaled to canvas size
  const fov = 1.0; // focal length
  const scale = fov * camDist / (camDist - v.z);
  return new Vec3(v.x * scale, v.y * scale, v.z);
}

/* --------------------------------------------------------------
   4️⃣  GRID CREATION (snap points)
   -------------------------------------------------------------- */
function createGrid(size=5, step=1){
  snapPoints = [];
  for(let x=-size; x<=size; x+=step){
    for(let y=-size; y<=size; y+=step){
      for(let z=-size; z<=size; z+=step){
        snapPoints.push({pos: new Vec3(x,y,z)});
      }
    }
  }
}
createGrid(5,1); // 11³ = 1331 snap points – small enough for a demo

/* --------------------------------------------------------------
   5️⃣  UTILS – mouse → 3D ray, nearest snap point
   -------------------------------------------------------------- */
function getMouseRay(x,y){
  const rect = canvas.getBoundingClientRect();
  const mx = ((x - rect.left) / rect.width) * 2 - 1;
  const my = -((y - rect.top) / rect.height) * 2 + 1;

  // reverse projection (ignore perspective distortion for the pick ray)
  const invScale = camDist / (camDist - 0);
  const dir = new Vec3(mx*invScale, my*invScale, -1).normalize();
  // rotate the direction the same way the scene is rotated
  const rotM = Mat4.multiply(
      Mat4.rotationY(state.rotY),
      Mat4.rotationX(state.rotX)
  );
  const worldDir = Mat4.transformVec(rotM, dir);
  const origin = new Vec3(0,0,camDist);
  return {origin, dir: worldDir};
}
function nearestSnapIdx(mouseX, mouseY){
  // brute‑force search – acceptable for a few thousand points
  const ray = getMouseRay(mouseX, mouseY);
  const maxDist = 0.2; // tolerance – how close a point must be to the ray
  let bestIdx = null;
  let bestSq = Infinity;
  snapPoints.forEach((pt, idx)=>{
    const v = pt.pos.sub(ray.origin);
    const projLen = v.dot(ray.dir);
    const closest = ray.origin.add(ray.dir.mul(projLen));
    const sq = pt.pos.sub(closest).length()**2;
    if(sq < maxDist*maxDist && sq < bestSq){
      bestSq = sq;
      bestIdx = idx;
    }
  });
