}

/* --------------------------------------------------------------
   6️⃣  VMC MENU (hover menu)
   -------------------------------------------------------------- */
const vmcMenu = document.getElementById('vmcMenu');
const addLineBtn = document.getElementById('addLineBtn');

function showVmcMenu(idx, screenX, screenY){
  vmcMenu.style.left = screenX + 'px';
  vmcMenu.style.top  = screenY + 'px';
  vmcMenu.style.opacity = 1;
  state.snapIdx = idx;
}
function hideVmcMenu(){
  vmcMenu.style.opacity = 0;
  state.snapIdx = null;
}

/* --------------------------------------------------------------
   7️⃣  EVENT LISTENERS – mouse move / down / up / wheel
   -------------------------------------------------------------- */
canvas.addEventListener('mousedown', e=>{
