  }else{
    hideVmcMenu();
  }
});
canvas.addEventListener('wheel', e=>{
  e.preventDefault();
  state.zoom *= e.deltaY>0 ? 0.9 : 1.1;
});
addLineBtn.addEventListener('click', e=>{
  // start / finish a line
  if(state.drawingFrom===null && state.snapIdx!==null){
    state.drawingFrom = state.snapIdx;
    // create a temporary line that follows the mouse (we'll update it in render)
    drawLines = [{from:snapPoints[state.drawingFrom].pos, to:snapPoints[state.drawingFrom].pos}];
