});

/* --------------------------------------------------------------
   8️⃣  APPLY SCENE TRANSFORM (rotation + zoom)
   -------------------------------------------------------------- */
function applySceneTransform(v){
  // build the model matrix: rotation * scale (zoom)
  const rotY = Mat4.rotationY(state.rotY);
  const rotX = Mat4.rotationX(state.rotX);
  const rot = Mat4.multiply(rotY, rotX);
  const scale = Mat4.scale(new Vec3(state.zoom, state.zoom, state.zoom));
  const model = Mat4.multiply(rot, scale);
  return Mat4.transformVec(model, v);
}

/* --------------------------------------------------------------
   9️⃣  RENDER LOOP
   -------------------------------------------------------------- */
function resizeCanvas(){
  canvas.width = window.innerWidth;
  canvas.height = window.innerHeight;
}
window.addEventListener('resize', resizeCanvas);
resizeCanvas();

function render(){
  ctx.clearRect(0,0,canvas.width,canvas.height);
  ctx.lineWidth = 1;
  ctx.strokeStyle = '#555';

  // ----- draw grid (as faint lines connecting nearest neighbours) -----
  // For a demo we only draw lines between points that differ by exactly 1 step
  const step = 1;
  const size = 5;
  const gridColor = 'rgba(80,80,120,0.15)';
  ctx.strokeStyle = gridColor;

  // helper to draw a single edge if both ends are inside the visible frustum
  function drawEdge(p0, p1){
    const v0 = applySceneTransform(p0);
    const v1 = applySceneTransform(p1);
    const proj0 = project(v0);
    const proj1 = project(v1);
    // simple clip – ignore points behind the camera
    if(proj0.z<0 && proj1.z<0) return;
    const sx0 = (proj0.x+1)*canvas.width/2;
    const sy0 = (-proj0.y+1)*canvas.height/2;
    const sx1 = (proj1.x+1)*canvas.width/2;
    const sy1 = (-proj1.y+1)*canvas.height/2;
    ctx.beginPath();
    ctx.moveTo(sx0, sy0);
    ctx.lineTo(sx1, sy1);
    ctx.stroke();
  }

  // iterate over the lattice – draw only lines along X/Y/Z axes
  for(let x=-size; x<=size; x+=step){
    for(let y=-size; y<=size; y+=step){
      for(let z=-size; z<=size; z+=step){
        const p = new Vec3(x,y,z);
        // X‑edge
        if(x+step<=size) drawEdge(p, new Vec3(x+step, y, z));
        // Y‑edge
        if(y+step<=size) drawEdge(p, new Vec3(x, y+step, z));
        // Z‑edge
        if(z+step<=size) drawEdge(p, new Vec3(x, y, z+step));
      }
    }
  }

  // ----- draw permanent wireframe model -----
  ctx.strokeStyle = '#0ef';
  wireframeModel.forEach(seg=>{
    const v0 = applySceneTransform(seg.from);
    const v1 = applySceneTransform(seg.to);
    const proj0 = project(v0);
    const proj1 = project(v1);
    if(proj0.z<0 && proj1.z<0) return;
    const sx0 = (proj0.x+1)*canvas.width/2;
    const sy0 = (-proj0.y+1)*canvas.height/2;
    const sx1 = (proj1.x+1)*canvas.width/2;
    const sy1 = (-proj1.y+1)*canvas.height/2;
    ctx.beginPath();
    ctx.moveTo(sx0, sy0);
    ctx.lineTo(sx1, sy1);
    ctx.stroke();
  });

  // ----- draw temporary line (while user is dragging) -----
  if(drawLines.length){
    const seg = drawLines[0];
    // endpoint follows the mouse – we recompute it each frame
    const mouseIdx = state.snapIdx !== null ? state.snapIdx : state.drawingFrom;
    const endPos = mouseIdx !== null ? snapPoints[mouseIdx].pos : seg.from;
    const v0 = applySceneTransform(seg.from);
    const v1 = applySceneTransform(endPos);
    const proj0 = project(v0);
    const proj1 = project(v1);
    ctx.strokeStyle = '#ff0';
    ctx.beginPath();
    ctx.moveTo((proj0.x+1)*canvas.width/2, (-proj0.y+1)*canvas.height/2);
    ctx.lineTo((proj1.x+1)*canvas.width/2, (-proj1.y+1)*canvas.height/2);
    ctx.stroke();
  }

  // ----- highlight hovered snap point -----
  if(state.snapIdx!==null){
    const pt = snapPoints[state.snapIdx].pos;
    const v = applySceneTransform(pt);
    const proj = project(v);
    if(proj.z>0){
      const sx = (proj.x+1)*canvas.width/2;
      const sy = (-proj.y+1)*canvas.height/2;
      ctx.fillStyle = '#f44';
      ctx.beginPath();
      ctx.arc(sx, sy, 4, 0, Math.PI*2);
      ctx.fill();
    }
  }

  requestAnimationFrame(render);
}
requestAnimationFrame(render);
</script>
</body>
</html>
```

---  

### 3️⃣  How it works (step‑by‑step)

| Action | What happens internally |
|--------|--------------------------|
| **Mouse moves** | The script casts a ray from the virtual camera through the mouse pixel, then finds the closest snap‑point (within a small tolerance). If a point is found, the **VMC menu** is positioned next to its projected screen coordinate. |
| **Click “Add line”** | *If we aren’t already drawing* → the index of the hovered snap‑point is stored in `state.drawingFrom` and a *temporary* line object is pushed into `drawLines`. The line’s start point stays fixed, its end point follows the mouse (updated each frame). |
| **Click another snap‑point** (while a temporary line exists) | The line is **committed**: a copy of both endpoint vectors is pushed into `wireframeModel`. The temporary line and `state.drawingFrom` are cleared, the VMC menu hides again. |
| **Rotate (left‑drag)** | `state.rotX` and `state.rotY` are changed; every frame `applySceneTransform()` multiplies the model matrix by the corresponding rotation matrices. |
| **Zoom (mouse‑wheel)** | `state.zoom` is multiplied by a factor; the same matrix is applied before projection. |
| **Render loop** | 1. Clear canvas  2. Draw faint grid lines (the “matrix”) 3. Draw all *permanent* segments (`wireframeModel`) 4. Draw the *temporary* segment while it’s being created 5. Paint a small coloured disc over the currently‑hovered snap‑point. |


---  

### 4️⃣  Extending the demo  

* **More sophisticated snapping** – increase `maxDist` or snap to the nearest integer coordinate after applying the current rotation.  
* **Undo / redo** – keep a history stack of `wireframeModel` changes.  
* **Export** – serialize `wireframeModel` (e.g. JSON) and download it as a file.  
* **Different projection** – replace the simple perspective with an orthographic view or a true camera matrix.  
* **Edge detection** – instead of brute‑force nearest‑point search, build a 3‑D spatial hash for large grids.  

Feel free to copy the code, experiment, and adapt it to your own research or teaching needs. Happy hacking!

