    const existing = await User.findOne({ email });
    if (existing) {
      return res.status(409).json({ message: 'Użytkownik istnieje' });
    }

    // 3️⃣ Haszowanie hasła
    const salt = await bcrypt.genSalt(12);
    const hash = await bcrypt.hash(password, salt);

    // 4️⃣ Generowanie tokenu weryfikacji
    const rawToken = uuidv4(); // np. "a3f0c2e5-..."
    const expires = new Date(Date.now() + 24 * 60 * 60 * 1000); // 24h

    // 5️⃣ Tworzenie rekordu
    const user = new User({
      email,
      passwordHash: hash,
      name,
      verification: {
        token: rawToken,
        expiresAt: expires,
        used: false
      }
    });

    await user.save();

    // 6️⃣ Wysłanie e‑maila
    const verificationLink = `${process.env.FRONTEND_URL}/verify?token=${rawToken}`;
    await sendVerificationEmail(email, verificationLink);

    return res.status(201).json({ message: 'Zarejestrowano – sprawdź e‑mail' });
  } catch (err) {
    console.error('register error', err);
    return res.status(500).json({ message: 'Błąd serwera' });
  }
});

module.exports = router;
```

#### `sendVerificationEmail` – prosty wrapper nad **nodemailer**

