### b) Weryfikacja linku (`GET /api/verify`)

```js
router.get('/verify', async (req, res) => {
  const { token } = req.query;
  if (!token) {
    return res.status(400).send('Brak tokenu');
  }

  try {
    // 1️⃣ Znajdź użytkownika z danym tokenem, który nie wygasł i nie został użyty
    const user = await User.findOne({
      'verification.token': token,
      'verification.expiresAt': { $gt: new Date() },
      'verification.used': false
    });

    if (!user) {
      return res.status(400).send('Nieprawidłowy lub przeterminowany token');
    }

    // 2️⃣ Aktualizuj status
    user.isVerified = true;
    user.verification.used = true; // żeby nie można było ponownie użyć
    await user.save();

    // 3️⃣ (opcjonalnie) automatyczne logowanie – generujemy JWT
    const jwt = require('jsonwebtoken');
    const payload = {
      sub: user._id,
      email: user.email,
      verified: true // przydatne w tokenie
    };
    const tokenJwt = jwt.sign(payload, process.env.JWT_SECRET, { expiresIn: '7d' });

    // 4️⃣ Przekierowanie do front‑endu z tokenem w query (lub w ciasteczku http‑only)
    const redirectUrl = `${process.env.FRONTEND_URL}/login?verified=1&jwt=${tokenJwt}`;
    return res.redirect(302, redirectUrl);
  } catch (err) {
    console.error('verify error', err);
    return res.status(500).send('Błąd serwera');
  }
});
```

> **Dlaczego nie zapisujemy `isVerified = true` od razu w `POST /register`?**  
> Bo dopiero po kliknięciu w link potwierdzamy, że adres e‑mail faktycznie należy do właściciela konta. W tym momencie zmieniamy **status** w bazie.

### c) Logowanie (`POST /api/login`)

```js
router.post('/login', async (req, res) => {
  const { email, password } = req.body;
  const user = await User.findOne({ email });

  if (!user) {
    return res.status(401).json({ message: 'Niepoprawny login lub hasło' });
  }

  const match = await bcrypt.compare(password, user.passwordHash);
  if (!match) {
    return res.status(401).json({ message: 'Niepoprawny login lub hasło' });
  }

  if (!user.isVerified) {
    return res.status(403).json({ message: 'Konto nie jest zweryfikowane – sprawdź e‑mail' });
  }

  const jwt = require('jsonwebtoken');
  const payload = {
    sub: user._id,
    email: user.email,
    verified: true
  };
  const tokenJwt = jwt.sign(payload, process.env.JWT_SECRET, { expiresIn: '7d' });

  // Najlepiej wysyłać token w http‑only cookie, ale dla prostoty:
  return res.json({ token: tokenJwt });
});
```

