## 2️⃣  `authProvider.ts` – safe token handling

```ts
// src/api/authProvider.ts
/**
 * Minimal in‑memory token store.
 *  • When the backend sets an httpOnly cookie for the access token,
 *    we never see it – Axios just sends it automatically.
 *  • If you prefer a JWT in a header, keep it in a JS variable only.
 *  • Refresh tokens *must* be httpOnly + SameSite=Strict on the server.
 */

type Tokens = {
  accessToken: string | null;   // optional: only if you use Bearer header
};

class AuthProvider {
  private tokens: Tokens = { accessToken: null };

  /** Called by login flow – store token only in memory */
  setAccessToken(token: string) {
    this.tokens.accessToken = token;
  }

  /** Retrieve token for the request interceptor */
  getAccessToken(): string | null {
    return this.tokens.accessToken;
  }

  /** Clears the token – e.g. on logout or refresh failure */
  clear() {
    this.tokens.accessToken = null;
  }
}

/**
 * Export a singleton – all parts of the app share the same memory store.
 */
export const authProvider = new AuthProvider();
```

