## 3️⃣  `axiosClient.ts` – the secure Axios wrapper

```ts
// src/api/axiosClient.ts
import axios, {
  AxiosInstance,
  AxiosRequestConfig,
  AxiosError,
  InternalAxiosRequestConfig,
} from "axios";
import { authProvider } from "./authProvider";

/**
 * ---------------------------------------------------------------
 *  Configuration – keep secrets out of source code
 * ---------------------------------------------------------------
 */
const API_BASE_URL = process.env.REACT_APP_API_BASE_URL; // e.g. https://api.myapp.com
if (!API_BASE_URL) {
  console.error("[axiosClient] REACT_APP_API_BASE_URL is not defined");
}

/**
 * ---------------------------------------------------------------
 *  Create a pre‑configured Axios instance
 * ---------------------------------------------------------------
 */
const client: AxiosInstance = axios.create({
  baseURL: API_BASE_URL,
  // All requests must be sent over HTTPS – browsers enforce this if baseURL is https.
  timeout: 15000, // 15 s – short enough to avoid hanging connections
  // Force JSON for both request & response – reduces content‑type sniffing attacks.
  headers: {
    "Content-Type": "application/json",
    Accept: "application/json",
  },
  // WithCredentials makes Axios include httpOnly cookies (session, refresh, CSRF)
  withCredentials: true,
});

/**
 * ---------------------------------------------------------------
 *  Request Interceptor – inject token & security headers
 * ---------------------------------------------------------------
 */
client.interceptors.request.use(
  (config: InternalAxiosRequestConfig) => {
    // ---- 1️⃣ Add Authorization if we have a bearer token -----------------
    const token = authProvider.getAccessToken();
    if (token) {
      // Never log the token!
      config.headers = {
        ...config.headers,
        Authorization: `Bearer ${token}`,
      };
    }

    // ---- 2️⃣ Add Anti‑CSRF Header (double‑submit cookie) -----------------
    // The server must set a cookie named `XSRF-TOKEN` – we read it from document.cookie.
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    const xsrfToken = (document.cookie.match(/XSRF-TOKEN=([^;]+)/) ?? [])[1];
    if (xsrfToken) {
      config.headers["X-XSRF-TOKEN"] = xsrfToken;
    }

    // ---- 3️⃣ Sanitize outgoing data (prevent XSS injection) ---------------
    if (config.data && typeof config.data === "object") {
      // Simple deep‑clone + strip any `<script>` tags. For deeper sanitisation you can plug DOMPurify.
      const sanitized = JSON.parse(JSON.stringify(config.data));
      // Example: remove any keys that start with '_' (often used by attackers)
      Object.keys(sanitized).forEach((k) => {
        if (k.startsWith("_")) delete (sanitized as any)[k];
      });
      config.data = sanitized;
    }

    return config;
  },
  (error) => Promise.reject(error),
);

/**
 * ---------------------------------------------------------------
 *  Response Interceptor – centralized error handling & token refresh
 * ---------------------------------------------------------------
 */
client.interceptors.response.use(
  (response) => response, // success passes through unchanged
  async (error: AxiosError) => {
    // ==== 1️⃣ 401 – try silent token refresh ==============================
    if (error.response?.status === 401 && !error.config?.__isRetryRequest) {
      try {
        // Mark request as a retry to avoid infinite loops
        (error.config as any).__isRetryRequest = true;

        // Call the refresh endpoint (must be httpOnly + same‑site)
        const refreshResponse = await axios.post(
          `${API_BASE_URL}/auth/refresh-token`,
          {}, // body can be empty; server reads refresh token from httpOnly cookie
          { withCredentials: true },
        );

        const newAccessToken = refreshResponse.data.accessToken;
        authProvider.setAccessToken(newAccessToken);

        // Retry the original request with the new token
        const retryConfig = {
          ...error.config,
          headers: {
            ...error.config.headers,
            Authorization: `Bearer ${newAccessToken}`,
          },
        };
        return client.request(retryConfig);
      } catch (refreshErr) {
        // Refresh failed → force logout
        authProvider.clear();
        // Optional: emit a global event or use a notification system
        console.warn("[axiosClient] Refresh token failed – logging out");
        // You may redirect to login page here:
        // window.location.href = "/login";
        return Promise.reject(refreshErr);
      }
    }

    // ==== 2️⃣ 4xx/5xx – mask error details before bubbling up ============
    const maskedError = {
      // A generic but useful code for UI layer
      code: error.response?.status ?? "NETWORK_ERROR",
      // Message stripped of any backend stack traces
      message:
        error.response?.data?.message ||
        error.message ||
        "An unexpected error occurred",
      // Attach the original request config for debugging (but NEVER expose it to the UI)
      // You can log it here (server side) or send to a monitoring service.
    };

    // Log the error securely (e.g., to Sentry, LogRocket) – don’t log credentials.
    // console.error("[axiosClient] API error:", {
    //   url: error.config?.url,
    //   method: error.config?.method,
    //   status: error.response?.status,
    //   data: error.response?.data,
    // });

    return Promise.reject(maskedError);
  },
);

/**
 * ---------------------------------------------------------------
 *  Helper: typed request wrapper (optional but handy)
 * ---------------------------------------------------------------
 */
export async function apiRequest<T = any>(
  config: AxiosRequestConfig,
): Promise<T> {
  const response = await client.request<T>(config);
  return response.data;
}

/**
 * Export the raw Axios instance for advanced use‑cases (e.g., websockets)
 */
export default client;
```

### Key Security Features Highlighted in the Code

| Feature | Why it matters | Implementation |
|---------|----------------|----------------|
| **HTTPS only** | Prevents man‑in‑the‑middle eavesdropping. | `baseURL` must be `https://…`. |
| **`withCredentials:true`** | Sends httpOnly cookies (session & refresh) but they’re never exposed to JavaScript. | Axios global config. |
| **In‑memory access token** | Avoids XSS theft from `localStorage`. | `authProvider` stores token only in RAM. |
| **Double‑submit CSRF token** | Protects state‑changing endpoints that rely on cookies. | Reads `XSRF‑TOKEN` cookie, sets `X‑XSRF‑TOKEN` header. |
| **Automatic token refresh** | Keeps the user logged in without prompting for re‑auth. | 401 interceptor → `/auth/refresh-token`. |
| **Error masking** | Prevents leaking backend internals (stack traces, DB info). | Interceptor rewrites error objects. |
| **Sanitisation of outgoing payloads** | Stops reflected XSS or JSON injection on badly‑coded APIs. | Simple clean‑up; you can plug `DOMPurify`. |
| **Strict timeout** | Avoids resource exhaustion attacks. | `timeout: 15000`. |
| **Centralised logging** | Easier to feed into a SIEM / Sentry without leaking secrets. | Comment‑out `console.error` and replace with real logger. |
| **Typed API wrapper** | Reduces runtime errors → fewer crash‑related DoS vectors. | `apiRequest<T>()`. |

