## 4️⃣  Using the client in a React component / hook

```tsx
// src/hooks/useApi.ts
import { useCallback } from "react";
import client, { apiRequest } from "../api/axiosClient";

type UseApiReturn = {
  get<T>(url: string, params?: any): Promise<T>;
  post<T>(url: string, data?: any): Promise<T>;
  put<T>(url: string, data?: any): Promise<T>;
  del<T>(url: string): Promise<T>;
};

export function useApi(): UseApiReturn {
  const get = useCallback(
    async <T,>(url: string, params?: any) =>
      apiRequest<T>({ method: "GET", url, params }),
    [],
  );

  const post = useCallback(
    async <T,>(url: string, data?: any) =>
      apiRequest<T>({ method: "POST", url, data }),
    [],
  );

  const put = useCallback(
    async <T,>(url: string, data?: any) =>
      apiRequest<T>({ method: "PUT", url, data }),
    [],
  );

  const del = useCallback(
    async <T,>(url: string) => apiRequest<T>({ method: "DELETE", url }),
    [],
  );

  return { get, post, put, del };
}
```

**Example component**

```tsx
// src/components/Profile.tsx
import React, { useEffect, useState } from "react";
import { useApi } from "../hooks/useApi";

type Profile = {
  id: string;
  name: string;
  email: string;
};

export default function Profile() {
  const { get } = useApi();
  const [profile, setProfile] = useState<Profile | null>(null);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    get<Profile>("/users/me")
      .then(setProfile)
      .catch((e) => setError(e.message));
  }, [get]);

  if (error) return <div className="error">⚠️ {error}</div>;
  if (!profile) return <div>Loading…</div>;

  return (
    <section>
      <h2>{profile.name}</h2>
      <p>{profile.email}</p>
    </section>
  );
}
```

