## 5️⃣  Auth flow sketch (login / logout)

```tsx
// src/contexts/AuthContext.tsx
import React, { createContext, useContext, ReactNode, useState } from "react";
import client from "../api/axiosClient";
import { authProvider } from "../api/authProvider";

type AuthContextProps = {
  isAuthenticated: boolean;
  login: (email: string, password: string) => Promise<void>;
  logout: () => void;
};

const AuthContext = createContext<AuthContextProps | undefined>(undefined);

export const AuthProvider: React.FC<{ children: ReactNode }> = ({ children }) => {
  const [isAuthenticated, setAuth] = useState<boolean>(false);

  const login = async (email: string, password: string) => {
    // The backend should set an httpOnly refresh cookie + return a short‑lived access JWT.
    const { data } = await client.post("/auth/login", { email, password });
    authProvider.setAccessToken(data.accessToken);
    setAuth(true);
  };

  const logout = () => {
    // Invalidate the refresh cookie on the server side
    client.post("/auth/logout").finally(() => {
      authProvider.clear();
      setAuth(false);
    });
  };

  return (
    <AuthContext.Provider value={{ isAuthenticated, login, logout }}>
      {children}
    </AuthContext.Provider>
  );
};

export const useAuth = () => {
  const ctx = useContext(AuthContext);
  if (!ctx) throw new Error("useAuth must be used within AuthProvider");
  return ctx;
};
```

Wrap your app with `<AuthProvider>` at the top level and you now have a **centralised, secure HTTP client** accessible from any component via `useApi()` or `useAuth()`.

