import { rest } from "msw";
import { setupServer } from "msw/node";
import client, { apiRequest } from "../src/api/axiosClient";
import { authProvider } from "../src/api/authProvider";

const server = setupServer(
  rest.get("https://api.test.com/users/me", (req, res, ctx) => {
    const auth = req.headers.get("Authorization");
    if (auth === "Bearer valid-token") {
      return res(ctx.json({ id: "1", name: "Alice", email: "alice@example.com" }));
    }
    return res(ctx.status(401));
  }),

  rest.post("https://api.test.com/auth/refresh-token", (req, res, ctx) => {
    // Return a new token
    return res(ctx.json({ accessToken: "new-token" }));
  }),
);

beforeAll(() => server.listen());
afterEach(() => server.resetHandlers());
afterAll(() => server.close());

test("auto‑refresh on 401", async () => {
  // Simulate a stale token
  authProvider.setAccessToken("expired-token");

  const data = await apiRequest<{ name: string }>({ method: "GET", url: "/users/me" });
  expect(data.name).toBe("Alice");

  // Ensure the new token is stored
  expect(authProvider.getAccessToken()).toBe("new-token");
});
```

> The mock server (`msw`) mimics the real API, letting you assert that the **refresh‑token flow** works without hitting a real endpoint.

