## 4. (Optional) Expose the helper globally – cleaner EJS

Instead of embedding the helper in every view, you can register it once in `app.js`:

```js
app.locals.soundcloudEmbedSrc = function (url) {
    if (!url) return '';
    const clean = url.split('?')[0].trim();
    const encoded = encodeURIComponent(clean);
    return `https://w.soundcloud.com/player/?url=${encoded}` +
           `&color=%23ff5500&auto_play=false&hide_related=false` +
           `&show_comments=true&show_user=true&show_reposts=false` +
           `&show_teaser=true&visual=true`;
};

app.locals.isValidSoundCloudUrl = function (url) {
    return typeof url === 'string' && url.startsWith('https://soundcloud.com/');
};
```

Now in **any** EJS file you can directly write:

