 * Updates the progress‑bar UI.
 *
 * Security‑focused version: uses textContent to avoid XSS,
 * treats emojis as whole grapheme clusters, and supports
 * a configurable "splittage" (visual width per emoji).
 */
function handleProgressBar() {
    const progressBarFilled = document.querySelector('.progress-bar-filled');
    const now = Date.now();

    // -----------------------------------------------------------------
    // 1️⃣  General timing calculations (unchanged)
    // -----------------------------------------------------------------
    const secondsPassed = ((now - overallStartTime) / 1000 - 1.5).toFixed(0);

    // -----------------------------------------------------------------
    // 2️⃣  If we are still generating, build the animated dot pattern
    // -----------------------------------------------------------------
    if (isGenerating) {
        const activeTime = ((now - startTime) / 1000).toFixed(0);

        // -------------------------------------------------------------
        // Emoji palette – you can keep this as‑is; duplicated entries
        // are intentional to make the cycle feel longer.
        // -------------------------------------------------------------
        const emojiDots = [
            '🍔','🍕','🍟','🍩','🍦','🍹','🥗','🤖','💻','🔬','📡',
            // repeat the same block several times (kept from original)
            '🍔','🍕','🍟','🍩','🍦','🍹','🥗','🤖','💻','🔬','📡',
            '🍔','🍕','🍟','🍩','🍦','🍹','🥗','🤖','💻','🔬','📡',
            '🍔','🍕','🍟','🍩','🍦','🍹','🥗','🤖','💻','🔬','📡',
            '🍔','🍕','🍟','🍩','🍦','🍹','🥗','🤖','💻','🔬','📡',
            '🍔','🍕','🍟','🍩','🍦','🍹','🥗','🤖','💻','🔬','📡',
            '🍔','🍕','🍟','🍩','🍦','🍹','🥗','🤖','💻','🔬','📡',
            '🍔','🍕','🍟','🍩','🍦','🍹','🥗','🤖','💻','🔬','📡'
        ];
        const numDots = emojiDots.length;

        // -------------------------------------------------------------
        // User‑configurable visual width per emoji
        // -------------------------------------------------------------
        const SPLITTAGE = 3;                 // <‑‑ change this to 1,2,3,… as needed
        const MAX_DOT_COUNT = 3;             // number of slots that can be “filled”

        // -------------------------------------------------------------
        // Compute which emojis belong to the current slice
        // -------------------------------------------------------------
        // `indexOffset` allows the whole set to rotate slowly over time.
        const indexOffset = Math.floor(activeTime / (numDots * MAX_DOT_COUNT));

        // `remainingTime` tells us how many of the three slots are currently filled.
        const remainingTime = activeTime % (numDots * MAX_DOT_COUNT);

        // -------------------------------------------------------------
        // Build the *raw* pattern (still a plain string) – each slot
        // gets either an emoji (if it should be “on”) or a space (if it
        // should be “off”).  We use Array.from on each emoji to guarantee
        // we never split a surrogate pair.
        // -------------------------------------------------------------
