        // Expand the raw pattern according to SPLITTAGE.
        //   - `Array.from(rawPattern)` gives us an array of grapheme clusters.
        //   - `' '.repeat(SPLITTAGE)` creates the needed spacer between them.
        // -------------------------------------------------------------
        const visualPattern = Array.from(rawPattern).join(' '.repeat(SPLITTAGE));

        // -------------------------------------------------------------
        // 3️⃣  Render – we use `textContent` to avoid accidental XSS.
        // -------------------------------------------------------------
        const msg = `processing ${visualPattern} ${activeTime} sec`;
        progressBarFilled.textContent = msg;   // safer than innerHTML
    } else {
        // -------------------------------------------------------------
        // Generation finished – show total elapsed time.
        // -------------------------------------------------------------
        const msg = `done: ${secondsPassed} sec`;
        progressBarFilled.textContent = msg;
    }
}
