const { logger } = require('./services/logger');

const server = http.createServer(app);
const PORT = process.env.PORT || 3000;

server.listen(PORT, () => logger.info(`🚀 Server listening on ${PORT}`));

// Graceful shutdown
const shutdown = async (signal) => {
  logger.info(`Received ${signal}. Closing HTTP server…`);
  server.close(async (err) => {
    if (err) logger.error('Error during server.close()', err);
    // Close DB, caches, etc.
    await require('./services/db').close(); // <-- implement .close()
    logger.info('Graceful shutdown complete.');
    process.exit(err ? 1 : 0);
  });
};

process.on('SIGINT',  () => shutdown('SIGINT'));
process.on('SIGTERM', () => shutdown('SIGTERM'));
```

**Why this helps**

* No lock file race conditions.  
* A process manager (PM2, systemd, Docker) can automatically restart the node process if it dies.  
