| **Body‑size** | `express.json({ limit: '5mb' })` (tune per use‑case) | Stops massive payload abuse. |
| **Input validation** | `celebrate` (Joi) or `zod` | Guarantees data shape before hitting business logic. |
| **Sanitisation** | `express-mongo-sanitize` | Removes `$`/`.` operators that could trigger NoSQL injection. |
| **Authentication** | `passport`/`express-jwt`/`@fastify/jwt` | Handles token verification and attaches `req.user`. |
| **Logging** | `winston` (JSON output) | Structured logs, easy ingestion into ELK/Datadog. |
| **Error handling** | Central error class hierarchy (e.g., `HttpError`) | Consistent API responses, no stack traces exposed. |

Below is a **minimal secure middleware stack** that you can paste right after creating the `app` instance.

```js
// src/app.js
const express = require('express');
const helmet = require('helmet');
const cors = require('cors');
const rateLimit = require('express-rate-limit');
const mongoSanitize = require('express-mongo-sanitize');
const { logger } = require('./services/logger');
const config = require('./config');

const app = express();

// ---- 1️⃣ Secure HTTP headers
app.use(helmet());

// ---- 2️⃣ CORS – whitelist only
const corsOptions = {
  origin: (origin, cb) => {
    // Allow requests with no origin (like curl, Postman) if you want
    if (!origin) return cb(null, true);
    if (config.corsOrigins.includes(origin)) return cb(null, true);
    cb(new Error('Not allowed by CORS'));
  },
  credentials: true, // only if you use cookies or auth headers cross‑origin
};
app.use(cors(corsOptions));

// ---- 3️⃣ Rate limiting
app.use(
  rateLimit({
    windowMs: config.rateLimit.windowMs,
    max: config.rateLimit.max,
    standardHeaders: true, // Return rate limit info in the `RateLimit-*` headers
    legacyHeaders: false,
  })
);

// ---- 4️⃣ Body parsers (size limits)
app.use(express.json({ limit: '5mb' }));
app.use(express.urlencoded({ extended: true, limit: '5mb' }));

// ---- 5️⃣ NoSQL injection sanitiser
app.use(mongoSanitize());

// ---- 6️⃣ Request logging (structured)
app.use((req, res, next) => {
  const start = Date.now();
  res.on('finish', () => {
    const duration = Date.now() - start;
    logger.info('request', {
      method: req.method,
      url: req.originalUrl,
      status: res.statusCode,
      duration,
      // Attach an identifier if you have auth (e.g., req.user?.id)
    });
  });
  next();
});

// ---- 7️⃣ Central error handler (must be after all routes)
app.use((err, req, res, next) => {
  // Known HTTP errors
  if (err.status && err.expose) {
    return res.status(err.status).json({ message: err.message });
  }

  // JWT errors, validation errors, etc.
  if (err.name === 'UnauthorizedError') {
    return res.status(401).json({ message: 'Invalid token' });
  }

  // Unknown errors – never leak stack trace
  logger.error('Unhandled error', { err });
  return res.status(500).json({ message: 'Internal Server Error' });
});

module.exports = app;
```

### 2.1 Logger – Structured JSON

```js
// src/services/logger.js
const { createLogger, format, transports } = require('winston');
const config = require('../config');

const logger = createLogger({
  level: config.logLevel,
  format: format.combine(
    format.timestamp(),
    format.errors({ stack: true }), // capture stack trace
    format.json()
  ),
  transports: [
    new transports.Console(),
    // Add file transport in prod if needed:
    // new transports.File({ filename: 'logs/combined.log' })
  ],
});

module.exports = { logger };
```

*Benefits*: JSON logs are parsable by **ELK**, **Datadog**, **Splunk**, etc. Sensitive data can be omitted via a custom format or by not logging `req.body` (unless you know it’s safe).

