## 4️⃣ Routing & Validation

### 4.1 Dynamic Route Loader (safe)

Your current approach (`_.each(routes…)`) works, but you should **validate** each exported controller:

```js
// src/routes/index.js
module.exports = (app) => {
  const routes = require('./routes'); // { '/users': usersController, … }

  for (const [path, controllerFactory] of Object.entries(routes)) {
    if (typeof controllerFactory !== 'function') {
      logger.warn(`Route ${path} does not export a factory function`);
      continue;
    }

    const router = controllerFactory(app, path);
    if (!router || typeof router.use !== 'function') {
      logger.warn(`Route ${path} did not return a valid router`);
      continue;
    }

    app.use(path, router);
    logger.info(`Mounted route ${path}`);
  }
};
```

### 4.2 Validation per Route (example)

```js
// src/routes/users.js
const { celebrate, Joi, Segments } = require('celebrate');

module.exports = (app) => {
  const router = require('express').Router();

  router.post(
    '/',
    celebrate({
      [Segments.BODY]: Joi.object({
        email: Joi.string().email().required(),
        password: Joi.string().min(8).required(),
        // ... more fields
      }),
    }),
    async (req, res, next) => {
      try {
        const { email, password } = req.body;
        // Business logic, call DB, etc.
        const user = await app.locals.db.collection('users').insertOne({ email, password });
        res.status(201).json({ id: user.insertedId });
      } catch (e) {
        next(e);
      }
    }
  );

  return router;
};
```

**Why?** The `celebrate` middleware intercepts malformed payloads **before** they touch your DB layer, returning a **400 Bad Request** with a clear error body.

