## 🧑‍💻 8. Controller de skills (`src/controllers/skillsController.js`)

```js
// src/controllers/skillsController.js
import pool from '../config/db.js';

/**
 * GET /api/skills
 * Lista **TODAS** las combinaciones userID‑skill (paginado)
 * Parámetros opcionales:
 *   - page (default 1)
 *   - limit (default 20, max 100)
 *   - userId (filtra por usuario)
 */
export const listSkills = async (req, res, next) => {
  try {
    const { page = 1, limit = 20, userId } = req.query;

    // Validaciones de rangos (evita DoS con limit enorme)
    const safeLimit = Math.min(parseInt(limit, 10) || 20, 100);
    const offset = (Math.max(parseInt(page, 10), 1) - 1) * safeLimit;

    // Construcción segura de la query usando placeholders
    let sql = `SELECT userID, skill FROM ExpertSkills`;
    const params = [];

    if (userId) {
      sql += ` WHERE userID = ?`;
      params.push(userId);
    }

    sql += ` ORDER BY skill ASC LIMIT ? OFFSET ?`;
    params.push(safeLimit, offset);

    const [rows] = await pool.execute(sql, params);

    // Total rows (para paginación) – se hace con una segunda query ligera
    let total = 0;
    if (!userId) {
      const [[{ cnt }]] = await pool.query(`SELECT COUNT(*) AS cnt FROM ExpertSkills`);
      total = cnt;
    } else {
      const [[{ cnt }]] = await pool.query(
        `SELECT COUNT(*) AS cnt FROM ExpertSkills WHERE userID = ?`,
        [userId]
      );
      total = cnt;
    }

    res.json({
      page: parseInt(page, 10),
      limit: safeLimit,
      total,
      results: rows,
    });
  } catch (err) {
    // Enviar al middleware de error
    next(err);
  }
};
```

### Comentarios de seguridad

| Acción | Por qué es importante |
|--------|-----------------------|
| `LIMIT`/`OFFSET` con **máximo 100** | Evita que un atacante solicite millones de filas y consuma recursos. |
| **Prepared statements** (`pool.execute`) | Impide inyección SQL, aunque el campo `skill` no proviene del cliente en este caso. |
| **Validación de `userId`** (en route) | Asegura que sea un entero y que el usuario sólo acceda a sus propios datos (en un caso real, comparar con `req.user.id`). |
| **Ordenamiento consistente** (`ORDER BY skill`) | Evita “order‑by injection”. |
| **Separar conteo total** | Evita `SQL_CALC_FOUND_ROWS` (obsoleto y costoso). |

