### 3.2 Podstawowy skrypt

```js
const fs = require('fs');
const acorn = require('acorn');

/**
 * Czy dany węzeł jest liczbą zapisaną w notacji heksadecymalnej (0x…)
 */
function isHexNumber(node) {
  // literal typu NumericLiteral o wartości zapisanej w source code jako 0x...
  return node && node.type === 'Literal' && typeof node.value === 'number' &&
         node.raw && /^0x[0-9a-fA-F]+$/.test(node.raw);
}

/**
 * Przeszukuje AST i zwraca wszystkie deklaracje funkcji spełniające warunek:
 *  - dokładnie dwa parametry,
 *  - przynajmniej jeden parametr jest liczbą (literal lub wyrażenie, które ocenia się do liczby)
 */
function findTargetFunctions(ast) {
  const results = [];

  // proste DFS po drzewie
  function walk(node, parent) {
    if (!node) return;

    // obsługa różnych form deklaracji funkcji
    const isFunction =
      node.type === 'FunctionDeclaration' ||
      node.type === 'FunctionExpression' ||
      (node.type === 'VariableDeclarator' && node.init && (node.init.type === 'FunctionExpression' || node.init.type === 'ArrowFunctionExpression'));

    if (isFunction) {
      // pobierz faktyczną funkcję (może być w VariableDeclarator)
      const fnNode = node.type === 'VariableDeclarator' ? node.init : node;

      // liczba parametrów
      if (fnNode.params.length === 2) {
        // Sprawdź, czy w ciele funkcji znajduje się *literal* liczbowy.
        // Liczbę możemy szukać w argumentach wywołań wewnątrz ciała.
        let hasNumber = false;
        acorn.walk.simple(fnNode.body, {
          Literal(lit) {
            if (isHexNumber(lit)) hasNumber = true;
          },
          // Obsługa wywołań typu: _0xabc(0x1df, …)
          CallExpression(call) {
            call.arguments.forEach(arg => {
              if (isHexNumber(arg)) hasNumber = true;
            });
          }
        });

        if (hasNumber) {
          // Nazwa funkcji (jeśli istnieje)
          const name = fnNode.id ? fnNode.id.name :
                       (node.type === 'VariableDeclarator' ? node.id.name : 'anonymous');

          results.push({
            name,
            node: fnNode,
            source: sourceCode.slice(node.start, node.end) // przydatne do debugowania
          });
        }
      }
    }

    // rekurencja po wszystkich własnościach obiektu AST
    for (const key of Object.keys(node)) {
      const child = node[key];
      if (Array.isArray(child)) {
        child.forEach(c => typeof c === 'object' && c !== null && walk(c, node));
      } else if (typeof child === 'object' && child !== null && child.type) {
        walk(child, node);
      }
    }
  }

  walk(ast, null);
  return results;
}

