### 2.1 创建统一的 Axios 实例

```ts
// src/utils/http.ts
import axios, { AxiosError, AxiosRequestConfig, AxiosResponse } from 'axios';
import { ElMessage, ElLoading } from 'element-plus';
import router from '@/router';
import { useAuthStore } from '@/stores/auth';

const http = axios.create({
  baseURL: import.meta.env.VITE_API_BASE, // 环境变量
  timeout: 12000,
  // 只接受 JSON，防止 content‑type 走向 XSS
  headers: { 'Content-Type': 'application/json' },
});

/* ------------------ 请求拦截器（统一注入 token） ------------------ */
http.interceptors.request.use(
  (config: AxiosRequestConfig) => {
    const token = useAuthStore().accessToken;
    if (token) {
      config.headers = config.headers ?? {};
      config.headers.Authorization = `Bearer ${token}`;
    }
    // 防止浏览器缓存 GET 请求（尤其是敏感数据）
    if (config.method === 'get') {
      config.params = { ...config.params, _t: Date.now() };
    }
    return config;
  },
  (error) => Promise.reject(error)
);

/* ------------------ 响应拦截器（统一错误处理） ------------------ */
http.interceptors.response.use(
  (resp: AxiosResponse) => {
    // 业务层面成功码统一判断（约定 0 为成功，其他为错误）
    if (resp.data?.code !== 0) {
      ElMessage.error(resp.data?.msg || '未知错误');
      return Promise.reject(resp);
    }
    return resp;
  },
  (error: AxiosError) => {
    // 统一错误提示，避免后端异常信息泄漏
    const status = error.response?.status;
    if (status === 401) {
      // token 失效或未登录，统一跳转登录页
      ElMessage.warning('登录已失效，请重新登录');
      router.replace({ name: 'Login' });
    } else if (status >= 500) {
      ElMessage.error('服务器错误，请稍后重试');
    } else {
      ElMessage.error(error.message || '网络异常');
    }
    return Promise.reject(error);
  }
);

export default http;
```

#### 安全要点
| 目的 | 具体措施 |
|------|----------|
| **身份认证** | 在请求拦截器统一注入 `Bearer` token，防止业务代码忘记带。 |
| **防缓存** | 给 GET 请求追加时间戳，防止浏览器缓存导致陈旧数据泄露。 |
| **统一错误** | 响应拦截器中不把后端异常栈直接返回前端，避免信息泄露。 |
| **HTTPS** | `baseURL` 必须是 `https://`，在 CI/CD 中强制检查。 |
| **CORS** | 只允许受信任域名 `Access-Control-Allow-Origin`，后端配合。 |

---

### 2.2 业务层封装（A → B、C）

> **思路**  
> 1. 调用 A 接口，**只要业务返回成功（code==0）**，才继续调用 B、C。  
> 2. B、C 可以并行（`Promise.all`）或串行，根据业务需求。  
> 3. 全程使用 **Loading** 组件防止 UI 失去响应，**Message** 统一提示成功/失败。  

```ts
// src/api/flow.ts
import http from '@/utils/http';
import { ElMessage, ElLoading } from 'element-plus';
import type { AxiosResponse } from 'axios';

/* ----- 接口返回基本结构 ----- */
interface ApiResult<T = any> {
  code: number;      // 0 为成功，其他为业务错误
  msg: string;
  data: T;
}

/* ----- A 接口 ----- */
function fetchA(): Promise<ApiResult<{ canProceed: boolean }>> {
  return http.get('/api/a').then((res) => res.data);
}

/* ----- B 接口 ----- */
function fetchB(): Promise<ApiResult<{ resultB: string }>> {
  return http.get('/api/b').then((res) => res.data);
}

/* ----- C 接口 ----- */
function fetchC(): Promise<ApiResult<{ resultC: number }>> {
  return http.post('/api/c', { foo: 'bar' }).then((res) => res.data);
}

/* ----- 主流程（A → B、C） ----- */
export async function runSequentialFlow(): Promise<void> {
  // 1️⃣ 打开全局 Loading
  const loading = ElLoading.service({
    lock: true,
    text: '正在处理，请稍候...',
    background: 'rgba(0,0,0,0.3)',
  });

  try {
    // 2️⃣ 调用 A
    const aResp = await fetchA();

    // 业务校验：只有当 canProceed 为 true 才继续
    if (!aResp.data?.canProceed) {
      throw new Error(aResp.msg || 'A 接口校验未通过');
    }

    // 3️⃣ 并行调用 B、C（如果业务必须顺序，可改为 await fetchB(); await fetchC();）
    const [bResp, cResp] = await Promise.all([fetchB(), fetchC()]);

    // 4️⃣ 业务成功提示（可以根据业务返回的具体数据做更细致的 UI 更新）
    ElMessage.success('全部接口调用成功！');
    console.log('B 返回：', bResp.data);
    console.log('C 返回：', cResp.data);
  } catch (err: any) {
    // 统一错误提示，避免泄露细节
    ElMessage.error(err?.message ?? '流程执行出错');
    // 这里如果需要，可以额外上报错误（如 Sentry、Feishu Bot 等）
    // reportError(err);
  } finally {
    // 5️⃣ 关闭 Loading
    loading.close();
  }
}
```

#### 关键安全点
| 环节 | 防护措施 |
|------|----------|
| **Loading** | 防止 UI 交互导致 **多次重复请求**（点击按钮产生并发），只要 `runSequentialFlow` 正在进行就禁用按钮。 |
| **业务校验** | 在调用 B、C 前**必须检查 A 的业务字段**（如 `canProceed`），避免**业务越权**或**状态失效**的请求。 |
| **异常捕获** | 使用 `try/catch` 包裹整个链路，确保即使 B、C 其中之一失败也能 **回滚 UI 状态**，并不把后端错误原文暴露给用户。 |
| **日志审计** | 在 `catch` 中统一上报错误到后台审计系统（如 ELK），帮助后期 **安全事件追踪**。 |
| **防止重放** | 如果 A 返回的是一次性 **nonce**、**时间戳**，在调用 B、C 时需在请求体带上，后端再校验，防止 **重放攻击**。 |

