## 5. Как безопасно заменить `express.basicAuth`

### 5.1 Принцип «Не использовать Basic Auth для публичных API»

| Сценарий | Рекомендация |
|----------|--------------|
| **Внутренние сервисы** (внутри закрытой сети) | Можно использовать **TLS + Basic Auth**, но только если пароль хранится в виде **хеша** (bcrypt) и ограничен по числу попыток. |
| **Публичные веб‑приложения** | **OAuth 2.0 / OpenID Connect** + JWT, либо обычный логин/сессия с `express-session`. |
| **API‑ключи / токены** | **Bearer Token** в заголовке `Authorization: Bearer <jwt|apikey>`. |

### 5.2 Пример безопасного middleware на основе bcrypt

```javascript
const express = require('express');
const bcrypt   = require('bcrypt');
const app      = express();

// Список пользователей в БД (пример)
const users = {
  // username: { passwordHash: <bcrypt hash> }
  alice: { passwordHash: '$2b$10$K9c...R2DQ' }, // hash от 's3cr3t'
};

// Middleware
function basicAuthSecure(realm = 'Restricted') {
  return async function (req, res, next) {
    const authHeader = req.headers.authorization;
    if (!authHeader) return unauthorized(res, realm);

    const [scheme, encoded] = authHeader.split(' ');
    if (scheme !== 'Basic' || !encoded) return unauthorized(res, realm);

    const decoded = Buffer.from(encoded, 'base64').toString('utf8');
    const sepIdx  = decoded.indexOf(':');
    if (sepIdx === -1) return unauthorized(res, realm);

    const username = decoded.slice(0, sepIdx);
    const password = decoded.slice(sepIdx + 1);

    const record = users[username];
    if (!record) return unauthorized(res, realm);

    const match = await bcrypt.compare(password, record.passwordHash);
    if (!match) return unauthorized(res, realm);

    // Успешно аутентифицировано
    req.user = username;
    next();
  };
}

// Выдаём 401 + WWW-Authenticate
function unauthorized(res, realm) {
  res.set('WWW-Authenticate', `Basic realm="${realm}"`);
  return res.status(401).send('Access denied');
}

// Применяем
app.use(basicAuthSecure('My Secure API'));

app.get('/', (req, res) => res.send(`Hello, ${req.user}!`));
```

**Что изменилось?**  

- **bcrypt**: пароли хранятся в виде хеша, а не в открытом виде.  
- **Асинхронный `compare`**: замедление атаки перебором (bcrypt генерирует сложные вычисления).  
- **Подключение к реальной БД**: вместо локального объекта.  
- **Лимитирование**: добавить `express-rate-limit` или `brute-express` для блокировки после N‑неудач.

### 5.3 Добавление rate‑limiting

```javascript
const rateLimit = require('express-rate-limit');

const authLimiter = rateLimit({
  windowMs: 5 * 60 * 1000,   // 5 минут
  max: 10,                  // не более 10 попыток аутентификации
  message: 'Too many login attempts, try later',
  keyGenerator: (req) => req.ip, // можно добавить user‑name
});

app.use('/protected', authLimiter, basicAuthSecure('Secure'));
```

### 5.4 Принудительное HTTPS

```javascript
app.use((req, res, next) => {
  if (req.headers['x-forwarded-proto'] !== 'https') {
    // Перенаправляем на HTTPS
    return res.redirect(`https://${req.headers.host}${req.url}`);
  }
  next();
});
```

