        // Successful login → hide login UI, start WS
        document.getElementById('loginSection').style.display = 'none';
        document.getElementById('chatSection').style.display = 'block';
        startWebSocket(user);
    } catch (e) {
        loginMsg.textContent = e.message;
    }
});

// -------------------------------------------------------------
// WebSocket – we embed the JWT as a sub‑protocol “token‑<jwt>”
// -------------------------------------------------------------
let ws;
function startWebSocket(username) {
    // Pull the JWT cookie (the browser automatically sends it; we just read the value for the protocol)
    const token = document.cookie.split('; ').find(row => row.startsWith('token='));
    if (!token) {
        alert('Missing auth token. Refresh and try again.');
        return;
    }
    const jwt = token.split('=')[1];

    const protocol = `token-${jwt}, json`;
    const scheme = location.protocol === 'https:' ? 'wss' : 'ws';
    ws = new WebSocket(`${scheme}://${location.host}/ws`, protocol);

    ws.addEventListener('open', () => {
        console.log('WebSocket connected');
    });

    ws.addEventListener('message', event => {
        const data = JSON.parse(event.data);
        const messagesDiv = document.getElementById('messages');

        if (data.type === 'welcome') {
            const el = document.createElement('div');
            el.className = 'msg system';
            el.innerHTML = `Welcome, ${esc(data.user)}!`;
            messagesDiv.appendChild(el);
        } else if (data.type === 'status') {
            const el = document.createElement('div');
            el.className = 'msg system';
            el.innerHTML = esc(data.text);
            messagesDiv.appendChild(el);
        } else if (data.type === 'chat') {
            const el = document.createElement('div');
            el.className = 'msg' + (data.from === username ? ' me' : '');
            el.innerHTML = `<strong>${esc(data.from)}:</strong> ${esc(data.text)}`;
            messagesDiv.appendChild(el);
        } else if (data.type === 'error') {
            alert('Server error: ' + data.text);
        }

        // Auto‑scroll
        messagesDiv.scrollTop = messagesDiv.scrollHeight;
    });

    ws.addEventListener('close', () => {
        console.warn('WebSocket closed');
        // Simple reconnect logic (exponential back‑off could be added)
        setTimeout(() => startWebSocket(username), 2000);
    });

    // ---------------------------------------------------------
    // Sending messages
    // ---------------------------------------------------------
    const form = document.getElementById('msgForm');
    form.addEventListener('submit', ev => {
        ev.preventDefault();
        const txt = document.getElementById('msgInput').value.trim();
        if (!txt) return;
        ws.send(JSON.stringify({ type: 'chat', text: txt }));
        document.getElementById('msgInput').value = '';
    });
}
</script>
</body>
</html>
```

**Explanation of the client’s security decisions**

| Decision | Reason |
|----------|--------|
| **POST `/api/login` with `credentials: "include"`** – the JWT is stored in an HttpOnly cookie, unavailable to XSS. |
| **WebSocket sub‑protocol carries the token** – this avoids query‑string leakage (browsers may log URLs). |
| **Escaping output (`esc()`)** – prevents injected markup from being rendered. |
| **Automatic reconnect** – simple back‑off ensures the UI recovers from transient network stops without asking the user to reload. |

---

## 5️⃣ Running the demo locally

```bash
# 1️⃣ Clone / create the folder structure
git clone https://github.com/your‑org/express-ws-chat.git
cd express-ws-chat

# 2️⃣ Install deps
npm install

# 3️⃣ (Optional) generate a self‑signed cert for HTTPS testing
#    OpenSSL command – replace "localhost" with the host you’ll use.
openssl req -nodes -new -x509 -keyout cert/server.key -out cert/server.crt -days 365 -subj "/CN=localhost"

# 4️⃣ Start the server (by default it uses HTTP)
npm start

# 5️⃣ Open your browser:
#    http://localhost:3000   → login with user "alice" / password "wonderland"
#    If you set USE_HTTPS=true, open https://localhost:3000 (accept the self‑signed cert).
```

**Environment variables you may want to export**

```bash
export PORT=8443            # custom port
export USE_HTTPS=true      # enable TLS (requires cert files)
export JWT_SECRET='super‑strong‑random‑value'
```

---

## 6️⃣ Security‑Researcher Checklist (What to verify / harden before production)

| # | Item | Why / Test |
|---|------|------------|
| **1** | **TLS termination** – Do you have a valid cert from a reputable CA? Check that `Strict‑Transport‑Security` header is set (`helmet` does this). | Use Qualys SSL Labs to scan. |
| **2** | **JWT secret** – Must be >= 256‑bit random string; rotate periodically. | Verify with `openssl rand -hex 32`. |
| **3** | **Token expiration & revocation** – Short‑lived JWTs (`2h` in demo) plus a server‑side blacklist for logout or compromise. | Attempt replay attacks after expiry. |
| **4** | **Origin validation** – Ensure only your front‑end domains are whitelisted. Test with a rogue origin header. |
| **5** | **Sub‑protocol token leakage** – Verify the token is **not** logged by any reverse proxy or load balancer (some may log `Sec-WebSocket-Protocol`). |
| **6** | **Rate‑limit testing** – Attempt to flood the WS endpoint (e.g., via `websocat`) and verify the per‑socket token bucket stops us after 5 msg/s. |
| **7** | **Message size limits** – Send an oversized payload (>1 KB). Server must drop/close connection. |
| **8** | **XSS/HTML injection** – Try `"<script>alert(1)</script>"`. Ensure it never renders as script in the UI (both server and client sanitise). |
| **9** | **CSRF** – Because we rely on HttpOnly cookies for JWT, ensure that any state‑changing endpoint (e.g., `/api/login`) is protected against CSRF. A simple way is **SameSite=Strict** (already set) + checking a custom header (`X-CSRF-Token`) for any non‑GET APIs. |
| **10** | **DoS via connection storm** – Simulate many simultaneous WebSocket upgrades (e.g., `ab -n 1000 -c 200`). Monitor CPU / memory. The `noServer` handshake & auth check should reject unauthenticated attempts early. |
| **11** | **Replay of old JWT** – Capture a token with a network sniffer, then try to reuse it after you’ve logged out / revoked. Expect `401`. |
| **12** | **Information disclosure** – Verify error messages do **not** leak stack traces or secret keys. Adjust Express error handler if needed (`app.use((err, req, res, next) => {...})`). |
| **13** | **Dependency hygiene** – Run `npm audit` and `npm outdated`. Keep `ws`, `express`, `helmet`, and `jsonwebtoken` up‑to‑date. |
| **14** | **Logging & monitoring** – Add a proper logger (winston, pino) that captures connection events, authentication failures, and rate‑limit hits. Integrate with SIEM or CloudWatch. |
| **15** | **Graceful shutdown** – Ensure `process.on('SIGTERM')` closes the HTTP/HTTPS server *and* `wss.clients.forEach(c=>c.terminate())`. Prevent orphan sockets. |
| **16** | **Compliance** – If you store personal data (usernames, chat transcripts), make sure you meet GDPR/CCPA requirements (data‑subject rights, encryption at rest). |
| **17** | **Pen‑test** – Run OWASP ZAP/SQLMap‑style scans while the WS is active to verify there are no hidden REST endpoints. |

---

## 7️⃣ Extending the demo (quick ideas)

| Feature | How to add (high‑level) |
|---------|------------------------|
| **Persist chat history** | Hook a lightweight DB (SQLite, PostgreSQL, or even a JSON file) and broadcast the last *N* messages on each new connection. |
| **Private rooms** | Include `roomId` in the JWT payload or as part of the WebSocket sub‑protocol; maintain a map `roomId → Set<ws>`. |
| **User presence** | Broadcast `online`/`offline` events; use `ws.isAlive` ping/pong to detect stale sockets. |
| **File upload** | Create a separate `/api/upload` endpoint protected by the same JWT and then send a message containing a signed URL. |
| **End‑to‑end encryption (E2EE)** | Generate a per‑room Diffie‑Hellman key on the client, exchange public keys via the server, then encrypt chat payloads client‑side only. Server merely brokers ciphertext. |
| **Rate‑limit per IP globally** | Use `express-rate-limit` on the upgrade path (`server.on('upgrade', ...)`). |
| **WebSocket sub‑protocol versioning** | Keep `json` as fallback and add `v2` where you change message schema. |


---

## 🎉 TL;DR

You now have a **complete, runnable Express + WebSocket chat server** that:

* Serves a tiny HTML UI.
* Authenticates users via **JWT** (stored in HttpOnly cookies).
* Checks **origin** & **token** *before* upgrading to WebSocket.
* Enforces **rate‑limits**, **message size caps**, and **per‑socket throttling**.
* **Sanitises** inbound chat text to prevent XSS.
* Optionally runs over **TLS**.
* Includes a **security checklist** for a researcher/pen‑tester.

Feel free to fork, add persistence, rooms, or end‑to‑end encryption – but **always revisit the checklist** before you expose the service to the wild! 🚀

