## 🛠️  3. Refaktoryzacja kodu (ES6+, czyste funkcje)

### 3.1. Konfiguracja (ukrywanie klucza)

```js
// config.js – w twoim systemie budowania (Webpack/Vite) wstrzykuj zmienną środowiskową
export const API_ENDPOINT = '/api/quiz';   // nasz własny proxy
```

### 3.2. API‑layer (fetch zamiast axios, by uniknąć dodatkowej zależności)

```js
/**
 * Pobiera [limit] pytań z naszego backendu.
 * Backend doda klucz API i zwróci już przefiltrowane pytania.
 */
export async function loadQuestions(limit = 5) {
    const resp = await fetch(`${API_ENDPOINT}?limit=${limit}`);
    if (!resp.ok) throw new Error('Nie udało się pobrać pytań');
    const data = await resp.json();
    return data;               // -> tablica pytań
}
```

### 3.3. State‑manager

```js
export const state = {
    questions: [],          // tablica obiektów pytania
    currentIdx: 0,
    score: 0,
    selected: null,         // element DOM wybranej odpowiedzi
};
```

### 3.4. Helper – jak wyciągnąć prawidłową odpowiedź z API

API `quizapi.io` zwraca:

```json
{
  "question": "...",
  "answers": {
    "answer_a": "A",
    "answer_b": "B",
    "answer_c": null,
    "answer_d": "D"
  },
  "correct_answers": {
    "answer_a_correct": "true",
    "answer_b_correct": "false",
    "answer_c_correct": "false",
    "answer_d_correct": "false"
  }
}
```

Musimy dopasować **klucz** (`answer_a`, `answer_b`, …) do **wartości** (`A`, `B`, …). Poniżej mini‑helper:

```js
/**
 * Zwraca obiekt { key: "answer_a", text: "A" } dla prawidłowej odpowiedzi.
 */
export function getCorrectAnswer(question) {
    const correctKey = Object.entries(question.correct_answers)
        .find(([, v]) => v === "true")?.[0];               // np. "answer_a_correct"
    if (!correctKey) return null;
    const answerKey = correctKey.replace('_correct', ''); // "answer_a"
    const answerText = question.answers[answerKey];
    return { key: answerKey, text: answerText };
}
```

### 3.5. Renderer

```js
import { state } from './state.js';
import { getCorrectAnswer } from './helpers.js';

/**
 * Czyści i renderuje pytanie + odpowiedzi.
 */
export function renderQuestion() {
    const { question, answers } = state.questions[state.currentIdx];
    const qBox = document.querySelector('.quiz__question__box');
    const aBox = document.querySelector('.quiz__answers');
    const scoreBox = document.querySelector('.quiz__score');

    // ---- pytanie -------------------------------------------------
    qBox.textContent = '';                           // wyczyść
    const p = document.createElement('p');
    p.className = 'quiz__question';
    p.textContent = question;                        // safe – textContent
    qBox.appendChild(p);

    // ---- odpowiedzi -----------------------------------------------
    aBox.innerHTML = '';                             // reset
    Object.entries(answers)
        .filter(([, v]) => v !== null)               // usuń puste
        .forEach(([key, txt]) => {
            const div = document.createElement('div');
            div.className = 'quiz__answer';
            div.dataset.answerKey = key;            // przydatne później
            div.textContent = txt;                  // safe
            div.addEventListener('click', onSelectAnswer);
            aBox.appendChild(div);
        });

    // ---- licznik --------------------------------------------------
    scoreBox.textContent = `${state.currentIdx + 1}/${state.questions.length}`;
}

/**
 * Zaznacza jedną odpowiedź jako aktywną.
 */
function onSelectAnswer(e) {
    // usuwamy zaznaczenia z innych elementów
    document.querySelectorAll('.quiz__answer.checked')
        .forEach(el => el.classList.remove('checked'));

    // zaznaczamy klikniętą
    e.currentTarget.classList.add('checked');
    state.selected = e.currentTarget;
}

/**
 * Po sprawdzeniu odpowiedzi podświetla prawidłową i błędną.
 */
export function renderResult(correctAnswer) {
    // -- zaznaczamy wynik --
    const selected = document.querySelector('.quiz__answer.checked');

    if (!selected) return; // nie wybrano nic – nie powinno się zdarzyć

    // prawidłowa odpowiedź – zielona
    const correctDiv = Array.from(document.querySelectorAll('.quiz__answer'))
        .find(el => el.dataset.answerKey === correctAnswer.key);

    if (selected.dataset.answerKey === correctAnswer.key) {
        selected.classList.add('correct');    // zielone tło (CSS)
        state.score++;
    } else {
        selected.classList.add('incorrect');  // czerwone tło
        if (correctDiv) correctDiv.classList.add('correct');
    }

    // ukryj przycisk „Sprawdź”, pokaż „Następne”
    toggleButtons('next');
}

/**
 * Pokazuje podsumowanie po zakończeniu quizu.
 */
export function renderSummary() {
    const qBox = document.querySelector('.quiz__question__box');
    qBox.innerHTML = `<p class="quiz__result">
        Ukończyłeś! <strong>${state.score}/${state.questions.length}</strong>
    </p>`;

    document.querySelector('.quiz__answers').innerHTML = '';
    document.querySelector('.btn').style.display = 'none'; // ukryj przycisk
}
```

### 3.6. Kontroler (obsługa przycisków)

```js
import { state } from './state.js';
import { loadQuestions } from './api.js';
import { renderQuestion, renderResult, renderSummary } from './renderer.js';
import { getCorrectAnswer } from './helpers.js';

const btn = document.querySelector('.btn'); // będzie używany jako "Sprawdź"/"Następne"

async function init() {
    try {
        state.questions = await loadQuestions(5); // pobieramy 5 pytań
        renderQuestion();
        btn.textContent = 'Sprawdź';
        btn.addEventListener('click', onSubmit);
    } catch (err) {
        console.error(err);
        alert('Nie udało się wczytać pytań. Spróbuj ponownie później.');
    }
}

/**
 * Obsługa przycisku „Sprawdź”.
 */
function onSubmit() {
    const selected = document.querySelector('.quiz__answer.checked');
    if (!selected) {
        alert('Wybierz odpowiedź przed sprawdzeniem.');
        return;
    }

    const current = state.questions[state.currentIdx];
    const correct = getCorrectAnswer(current);
    renderResult(correct);

    // po krótkiej przerwie (opcjonalnie) umożliwiamy przejście dalej
    // ale przycisk już zmienił tryb na "Następne"
}

/**
 * Przełącza przycisk pomiędzy trybem "Sprawdź" a "Następne".
 */
function toggleButtons(mode) {
    if (mode === 'next') {
        btn.textContent = 'Następne';
        btn.removeEventListener('click', onSubmit);
        btn.addEventListener('click', onNext);
    } else {
        btn.textContent = 'Sprawdź';
        btn.removeEventListener('click', onNext);
        btn.addEventListener('click', onSubmit);
    }
}

/**
 * Obsługa przycisku „Następne”.
 */
function onNext() {
    // przygotowujemy kolejny cykl
    state.currentIdx++;

    // jeżeli skończyły się pobrane pytania – kończymy quiz
    if (state.currentIdx >= state.questions.length) {
        renderSummary();
        return;
    }

    // resetujemy zaznaczenia i przywracamy przycisk "Sprawdź"
    state.selected = null;
