<body>

<div class="quiz">
  <div class="quiz__question__box"></div>
  <div class="quiz__answers"></div>
  <div class="quiz__score"></div>
  <button class="btn">Sprawdź</button>
</div>

<script type="module">
/* ------------ CONFIG -------------- */
const API_ENDPOINT = '/api/quiz';   // <-- Twój własny proxy

/* ------------ STATE --------------- */
const state = {
    questions: [],
    currentIdx: 0,
    score: 0,
    selected: null,
};

/* ------------ HELPERS ------------ */
function getCorrectAnswer(question) {
    const correctKey = Object.entries(question.correct_answers)
        .find(([, v]) => v === "true")?.[0];
    if (!correctKey) return null;
    const answerKey = correctKey.replace('_correct', '');
    return { key: answerKey, text: question.answers[answerKey] };
}

/* ------------ API ----------------- */
async function loadQuestions(limit = 5) {
    const resp = await fetch(`${API_ENDPOINT}?limit=${limit}`);
    if (!resp.ok) throw new Error('API error');
    return await resp.json();
}

/* ------------ RENDER ------------- */
function renderQuestion() {
    const { question, answers } = state.questions[state.currentIdx];
    const qBox = document.querySelector('.quiz__question__box');
    const aBox = document.querySelector('.quiz__answers');
    const scoreBox = document.querySelector('.quiz__score');

    qBox.textContent = '';
    const p = document.createElement('p');
    p.className = 'quiz__question';
    p.textContent = question;                     // safe
    qBox.appendChild(p);

    aBox.innerHTML = '';
    Object.entries(answers)
        .filter(([, v]) => v !== null)
        .forEach(([key, txt]) => {
            const div = document.createElement('div');
            div.className = 'quiz__answer';
            div.dataset.key = key;
            div.textContent = txt;
            div.addEventListener('click', onSelect);
            aBox.appendChild(div);
        });

    scoreBox.textContent = `${state.currentIdx + 1}/${state.questions.length}`;
}

function onSelect(e) {
    document.querySelectorAll('.quiz__answer.checked')
        .forEach(el => el.classList.remove('checked'));
    e.currentTarget.classList.add('checked');
    state.selected = e.currentTarget;
}

function renderResult(correct) {
    const selected = document.querySelector('.quiz__answer.checked');
    const correctDiv = document.querySelector(`.quiz__answer[data-key="${correct.key}"]`);

    if (selected.dataset.key === correct.key) {
        selected.classList.add('correct');
        state.score++;
    } else {
        selected.classList.add('incorrect');
        if (correctDiv) correctDiv.classList.add('correct');
    }

    toggleBtn('next');
}

function renderSummary() {
    const qBox = document.querySelector('.quiz__question__box');
    qBox.innerHTML = `<p class="quiz__result">
        Ukończyłeś! <strong>${state.score}/${state.questions.length}</strong>
    </p>`;
    document.querySelector('.quiz__answers').innerHTML = '';
    document.querySelector('.btn').style.display = 'none';
}

/* ------------ BUTTON LOGIC ------- */
const btn = document.querySelector('.btn');

function toggleBtn(mode) {
    if (mode === 'next') {
        btn.textContent = 'Następne';
        btn.removeEventListener('click', onSubmit);
        btn.addEventListener('click', onNext);
    } else {
        btn.textContent = 'Sprawdź';
        btn.removeEventListener('click', onNext);
        btn.addEventListener('click', onSubmit);
    }
}

function onSubmit() {
    const selected = document.querySelector('.quiz__answer.checked');
    if (!selected) {
        alert('Wybierz odpowiedź.');
        return;
    }
    const correct = getCorrectAnswer(state.questions[state.currentIdx]);
    renderResult(correct);
}

function onNext() {
    state.currentIdx++;
    if (state.currentIdx >= state.questions.length) {
        renderSummary();
        return;
    }
    state.selected = null;
    document.querySelectorAll('.quiz__answer')
        .forEach(el => el.classList.remove('checked', 'correct', 'incorrect'));
    renderQuestion();
    toggleBtn('submit');
}

/* ------------ INIT --------------- */
async function init() {
    try {
        state.questions = await loadQuestions(5);
        renderQuestion();
        toggleBtn('submit');
    } catch (e) {
        console.error(e);
        alert('Nie udało się wczytać pytań.');
    }
}
init();
</script>
</body>
</html>
```

