# 1. initialise a node project (once)
npm init -y

# 2. install Express
npm install express

# 3. start the server
node index.js
```

Open `http://localhost:3000` in a modern Chrome/Edge/Firefox (desktop) – mobile browsers work as long as they support Web Audio and `getUserMedia`.

---

## 2️⃣ `index.html` – Web page + client‑side BPM detector

```html
<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<title>Live BPM Detector</title>
<style>
  body {font-family:Arial,Helvetica,sans-serif; text-align:center; padding-top:50px; background:#fafafa;}
  #bpm {font-size:3rem; margin-top:20px; color:#222;}
  button {font-size:1.2rem; padding:10px 20px; margin-top:20px;}
</style>
</head>
<body>

<h1>Live BPM Detector</h1>
<button id="startBtn">Start Listening</button>
<div id="bpm">–‑ BPM</div>

<script>
/* -------------------------------------------------------------
   LIVE BPM DETECTOR (client side)
   ------------------------------------------------------------- */
(async () => {
  // UI elements
  const startBtn = document.getElementById('startBtn');
  const bpmEl   = document.getElementById('bpm');

  // ---- Configuration ------------------------------------------------
  const BUFFER_SIZE = 1024;          // size of each analysis chunk
  const ENERGY_HISTORY = 43;         // number of past energies for moving average
  const MIN_BPM = 30, MAX_BPM = 240; // clamp output
  const BEAT_HOLD_TIME = 300;        // ms to wait after a beat before next detection
  const PEAK_THRESHOLD = 1.5;        // multiplier over avg energy to consider a peak
  // -------------------------------------------------------------------

  // State
  let audioCtx, analyser, scriptNode;
  let energyHistory = new Array(ENERGY_HISTORY).fill(0);
  let historyPos = 0;
  let lastBeatTime = 0;
  const beatTimes = []; // timestamps (ms) of recent beats (max ~10)

  // Helper to update displayed BPM
  function updateBPM(bpm) {
    bpmEl.textContent = isNaN(bpm) ? '–‑ BPM' : `${Math.round(bpm)} BPM`;
  }

  // Main processing function – called for every audio buffer
  function processAudio(event) {
    const input = event.inputBuffer.getChannelData(0); // mono
    // Compute instantaneous energy (sum of squares)
    let sum = 0;
    for (let i = 0; i < input.length; i++) sum += input[i] * input[i];
    const instantEnergy = sum;

    // Update moving‑average energy history
    energyHistory[historyPos] = instantEnergy;
    historyPos = (historyPos + 1) % ENERGY_HISTORY;
    const avgEnergy = energyHistory.reduce((a, b) => a + b, 0) / ENERGY_HISTORY;

    // Simple peak detection
    const now = performance.now();
    if (
      instantEnergy > avgEnergy * PEAK_THRESHOLD && // above threshold
      now - lastBeatTime > BEAT_HOLD_TIME           // respect hold time
    ) {
      // Register a beat
      lastBeatTime = now;
      beatTimes.push(now);
      // Keep only recent beats (last ~10 seconds)
      while (beatTimes.length > 0 && now - beatTimes[0] > 10000) beatTimes.shift();

      // Compute BPM from inter‑beat intervals
      if (beatTimes.length >= 2) {
        const intervals = [];
        for (let i = 1; i < beatTimes.length; i++) {
          intervals.push(beatTimes[i] - beatTimes[i - 1]); // ms
        }
        const avgIBI = intervals.reduce((a, b) => a + b, 0) / intervals.length;
        const bpm = (60 * 1000) / avgIBI;
        // Clamp to reasonable range
        updateBPM(Math.max(MIN_BPM, Math.min(MAX_BPM, bpm)));
      }
    }
  }

  // ---------------------------------------------------------------
  // Start button handler – asks for mic and starts the audio pipeline
  // ---------------------------------------------------------------
  startBtn.onclick = async () => {
    startBtn.disabled = true;
    startBtn.textContent = 'Listening…';

    try {
      const stream = await navigator.mediaDevices.getUserMedia({ audio: true, video: false });
      audioCtx = new (window.AudioContext || window.webkitAudioContext)();
      const source = audioCtx.createMediaStreamSource(stream);

      // ScriptProcessorNode is deprecated but still widely supported.
      // For a future‑proof solution replace with AudioWorkletNode.
      scriptNode = audioCtx.createScriptProcessor(BUFFER_SIZE, 1, 1);
      scriptNode.onaudioprocess = processAudio;

      // Connect the graph: mic -> analyser (optional) -> scriptNode -> destination (muted)
      analyser = audioCtx.createAnalyser();
      analyser.fftSize = 2048;

      source.connect(analyser);
      analyser.connect(scriptNode);
      scriptNode.connect(audioCtx.destination); // we don't output sound, but we need a destination

    } catch (e) {
      console.error('Mic access denied / error:', e);
      alert('Could not get microphone access. Please allow the site to use the mic.');
      startBtn.disabled = false;
      startBtn.textContent = 'Start Listening';
    }
  };
})();
</script>
</body>
</html>
```

### How to test

1. **Start the server** (`node index.js`).  
2. Open `http://localhost:3000` in a browser.  
3. Click **“Start Listening”** – the browser will prompt for microphone permission.  
4. Play a steady percussive sound into the mic (e.g., a metronome app, a drum beat, a click track, or even tapping a pencil rhythmically).  
5. The BPM value should appear and update in real‑time.  

### Things to keep in mind

| Issue | Why it happens | Quick fix / tip |
|-------|----------------|-----------------|
| **No BPM appears** | The input may be too quiet or not rhythmic. | Increase microphone gain, or use a clearer percussive source. |
| **BPM fluctuates a lot** | The simple energy‑threshold detector is sensitive to dynamics. | Try adjusting `PEAK_THRESHOLD` (lower = more beats, higher = stricter) or `ENERGY_HISTORY`. |
| **High latency** | `ScriptProcessorNode` processes in chunks (~23 ms for 1024 samples). | For sub‑10 ms latency, replace the processor with an `AudioWorkletNode` (requires extra boilerplate). |
| **Mobile browsers** | Some mobile browsers need a user‑gesture before creating `AudioContext`. | The “Start Listening” button already satisfies that requirement. |

---

## 🎯 What you have now

- **A single‑file web front‑end** (`index.html`) that runs entirely in the browser – no extra libraries needed.  
- **A tiny Node.js server** (`index.js`) to host the page locally or on any host that can run Express.  
- A **live BPM read‑out** based on a straightforward energy‑peak detection algorithm.  

Feel free to extend it:

- Add a **visualizer** (draw the waveform or energy histogram on a `<canvas>`).  
- Replace the `ScriptProcessorNode` with an **AudioWorklet** for better performance.  
- Store the BPM history and show a rolling average or confidence indicator.  

Happy hacking, and may the beats be ever in your favor! 🚀

