### 2.6 Auth Routes (`src/routes/auth.js`)

```js
// src/routes/auth.js
const express = require('express');
const bcrypt = require('bcryptjs');
const jwt = require('jsonwebtoken');
const db = require('../db');
require('dotenv').config();

const router = express.Router();
const SALT_ROUNDS = Number(process.env.BCRYPT_SALT_ROUNDS) || 12;

// ---------- REGISTER ----------
router.post('/register', async (req, res) => {
  const { username, password } = req.body;
  if (!username || !password) return res.status(400).json({ error: 'Missing fields' });

  try {
    // 1️⃣ Check username availability
    const { rows } = await db.query('SELECT id FROM users WHERE username = $1', [username]);
    if (rows.length) return res.status(409).json({ error: 'Username taken' });

    // 2️⃣ Hash the password (bcrypt with per‑user salt)
    const hash = await bcrypt.hash(password, SALT_ROUNDS);

    // 3️⃣ Store user
    const insert = await db.query(
      'INSERT INTO users (username, password_hash) VALUES ($1, $2) RETURNING id, username, created_at',
      [username, hash]
    );

    const user = insert.rows[0];
    // 4️⃣ Issue JWT (access token only – keep short)
    const token = jwt.sign(
      { sub: user.id, username: user.username },
      process.env.JWT_SECRET,
      { expiresIn: process.env.JWT_EXPIRES_IN || '15m' }
    );

    // 5️⃣ Return token via HttpOnly cookie **or** JSON (client decides)
    // Res option A (recommended for SPAs) – HttpOnly cookie:
    // res.cookie('token', token, { httpOnly: true, sameSite: 'lax', secure: true });
    // Res option B – JSON payload (store in memory; never localStorage for XSS risk)
    return res.status(201).json({ token, user: { id: user.id, username: user.username } });
  } catch (err) {
    console.error(err);
    return res.sendStatus(500);
  }
});

// ---------- LOGIN ----------
router.post('/login', async (req, res) => {
  const { username, password } = req.body;
  if (!username || !password) return res.status(400).json({ error: 'Missing fields' });

  try {
    const { rows } = await db.query('SELECT id, password_hash FROM users WHERE username = $1', [username]);
    if (!rows.length) return res.status(401).json({ error: 'Invalid credentials' });

    const user = rows[0];
    const match = await bcrypt.compare(password, user.password_hash);
    if (!match) return res.status(401).json({ error: 'Invalid credentials' });

    // Issue JWT
    const token = jwt.sign(
      { sub: user.id, username },
      process.env.JWT_SECRET,
      { expiresIn: process.env.JWT_EXPIRES_IN || '15m' }
    );

    return res.json({ token, user: { id: user.id, username } });
  } catch (err) {
    console.error(err);
    return res.sendStatus(500);
  }
});

module.exports = router;
```

### 2.7 Entry Routes (`src/routes/entries.js`)

```js
// src/routes/entries.js
const express = require('express');
const db = require('../db');
const { verifyToken } = require('../middleware/auth');

const router = express.Router();

// All routes below require a verified JWT
router.use(verifyToken);

// ---------- GET ALL entries for the current user ----------
router.get('/', async (req, res) => {
  const userId = req.user.id;
  try {
    const { rows } = await db.query(
      'SELECT id, title, body, created_at FROM entries WHERE user_id = $1 ORDER BY created_at DESC',
      [userId]
    );
    return res.json(rows);
  } catch (err) {
    console.error(err);
    return res.sendStatus(500);
  }
});

// ---------- CREATE a new entry ----------
router.post('/', async (req, res) => {
  const { title, body } = req.body;
  if (!title) return res.status(400).json({ error: 'Title required' });

  const userId = req.user.id;
  try {
    const { rows } = await db.query(
      `INSERT INTO entries (user_id, title, body) 
       VALUES ($1, $2, $3) 
       RETURNING id, title, body, created_at`,
      [userId, title, body || null]
    );
    return res.status(201).json(rows[0]);
  } catch (err) {
    console.error(err);
    return res.sendStatus(500);
  }
});

// ---------- GET ONE entry ----------
router.get('/:id', async (req, res) => {
  const entryId = Number(req.params.id);
  const userId = req.user.id;

  try {
    const { rows } = await db.query(
      `SELECT id, title, body, created_at 
       FROM entries 
       WHERE id = $1 AND user_id = $2`,
      [entryId, userId]
    );
    if (!rows.length) return res.sendStatus(404);
    return res.json(rows[0]);
  } catch (err) {
    console.error(err);
    return res.sendStatus(500);
  }
});

// ---------- UPDATE ----------
router.patch('/:id', async (req, res) => {
  const entryId = Number(req.params.id);
  const { title, body } = req.body;
  const userId = req.user.id;

  // Prevent empty updates
  if (!title && body === undefined) return res.status(400).json({ error: 'Nothing to update' });

  const fields = [];
  const values = [userId, entryId];
  let idx = 3;

  if (title) {
    fields.push(`title = $${idx++}`);
    values.push(title);
  }
  if (body !== undefined) {
    fields.push(`body = $${idx++}`);
    values.push(body);
  }

  const setClause = fields.join(', ');
  const sql = `UPDATE entries SET ${setClause} WHERE user_id = $1 AND id = $2 RETURNING id, title, body, created_at`;

  try {
    const { rows } = await db.query(sql, values);
    if (!rows.length) return res.sendStatus(404);
    return res.json(rows[0]);
  } catch (err) {
    console.error(err);
    return res.sendStatus(500);
  }
});

// ---------- DELETE ----------
router.delete('/:id', async (req, res) => {
  const entryId = Number(req.params.id);
  const userId = req.user.id;

  try {
    const result = await db.query(
      'DELETE FROM entries WHERE id = $1 AND user_id = $2',
      [entryId, userId]
    );
    if (result.rowCount === 0) return res.sendStatus(404);
    return res.sendStatus(204);
  } catch (err) {
    console.error(err);
    return res.sendStatus(500);
  }
});

module.exports = router;
```

### 2.8 Application Entrypoint (`src/app.js`)

```js
// src/app.js
require('dotenv').config();
const express = require('express');
const cors = require('cors');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');

const authRouter = require('./routes/auth');
const entriesRouter = require('./routes/entries');

const app = express();
const PORT = process.env.PORT || 4000;

/* ---------- Security Middlewares ---------- */
// Helmet sets a sane collection of HTTP headers (CSP, HSTS, X‑Frame‑Options, …)
app.use(helmet());

// CORS – only allow your front‑end origin (adjust in production)
app.use(cors({
  origin: process.env.FRONTEND_URL || 'http://localhost:3000',
  credentials: true, // if you use HttpOnly cookie for the JWT
}));

// Body parser (JSON)
app.use(express.json());

// Global rate limiter (basic DoS protection)
const apiLimiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 min
  max: 200, // limit each IP to 200 requests per windowMs
  standardHeaders: true,
  legacyHeaders: false,
});
app.use('/api/', apiLimiter);

/* ---------- Routes ---------- */
app.use('/api/auth', authRouter);
app.use('/api/entries', entriesRouter);

/* ---------- Fallback ---------- */
app.use((req, res) => {
  res.status(404).json({ error: 'Not found' });
});

/* ---------- Server ---------- */
app.listen(PORT, () => {
  console.log(`🔒 Secure API listening on http://localhost:${PORT}`);
});
```

