## 3️⃣ Front‑End – React (the “client”)

> **Never** store the JWT in `localStorage` or `sessionStorage`. Those storages are **readable by any script** on the page – a XSS bug would instantly leak the token.  
> Use **memory only** (e.g., React context) or **httpOnly cookies** (preferred for SPAs).

Below are two common patterns:

| Pattern | Where token lives | XSS risk | CSRF defence |
|--------|-------------------|----------|--------------|
| **HttpOnly Secure Cookie** (recommended) | Browser automatically sends cookie with each request (no JS access). | None (JS can’t read cookie). | Use `SameSite=Lax` or `Strict` + CSRF‑double‑submit token for state‑changing ops. |
| **In‑memory (React context) + Authorization Header** | Kept in a React state variable, lost on page refresh. | Medium – if XSS, attacker can read state. | No CSRF (auth header not sent automatically). |

### 3.1 Install Dependencies

```bash
npx create-react-app client   # or use Vite, Next.js, etc.
cd client
npm i axios jwt-decode   # optional: for decoding expiry
```

### 3.2 API Wrapper (`src/api.js`)

```js
// src/api.js
import axios from 'axios';

const api = axios.create({
  baseURL: process.env.REACT_APP_API_URL || 'http://localhost:4000/api',
  // If you decide to use cookies for auth:
  // withCredentials: true,
});

/* Interceptor to inject the JWT automatically (if you store it in memory) */
let accessToken = null;
export const setAccessToken = (token) => {
  accessToken = token;
};

api.interceptors.request.use((config) => {
  if (accessToken) {
    config.headers.Authorization = `Bearer ${accessToken}`;
  }
  return config;
});

export default api;
```

### 3.3 Auth Context (in‑memory token)

```tsx
// src/context/AuthContext.tsx  (or .js)
import React, { createContext, useState, useEffect, useContext } from 'react';
import api, { setAccessToken } from '../api';
import jwtDecode from 'jwt-decode';

type User = { id: number; username: string };
type AuthContextProps = {
  user: User | null;
  login: (username: string, password: string) => Promise<void>;
  register: (username: string, password: string) => Promise<void>;
  logout: () => void;
};

const AuthContext = createContext<AuthContextProps>(null!);

export const useAuth = () => useContext(AuthContext);

export const AuthProvider: React.FC = ({ children }) => {
  const [user, setUser] = useState<User | null>(null);

  // Restore token from sessionStorage (optional – beware of XSS)
  useEffect(() => {
    const stored = sessionStorage.getItem('accessToken');
    if (stored) {
      setAccessToken(stored);
      const payload: any = jwtDecode(stored);
      setUser({ id: payload.sub, username: payload.username });
    }
  }, []);

  const login = async (username: string, password: string) => {
    const { data } = await api.post('/auth/login', { username, password });
    setAccessToken(data.token);
    sessionStorage.setItem('accessToken', data.token);
    setUser({ id: data.user.id, username: data.user.username });
  };

  const register = async (username: string, password: string) => {
    const { data } = await api.post('/auth/register', { username, password });
    setAccessToken(data.token);
    sessionStorage.setItem('accessToken', data.token);
    setUser({ id: data.user.id, username: data.user.username });
  };

  const logout = () => {
    setAccessToken(null);
    sessionStorage.removeItem('accessToken');
    setUser(null);
  };

  return (
    <AuthContext.Provider value={{ user, login, register, logout }}>
      {children}
    </AuthContext.Provider>
  );
};
```

Wrap your app in `<AuthProvider>` (typically in `src/index.tsx`).

### 3.4 Using the API – CRUD for “entries”

```tsx
// src/components/EntryList.tsx
import React, { useEffect, useState } from 'react';
import api from '../api';

type Entry = {
  id: number;
  title: string;
  body?: string;
  created_at: string;
};

export const EntryList: React.FC = () => {
  const [entries, setEntries] = useState<Entry[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    api.get('/entries')
      .then(r => setEntries(r.data))
      .catch(err => setError(err?.response?.data?.error || 'Failed'))
      .finally(() => setLoading(false));
  }, []);

  if (loading) return <p>Loading …</p>;
  if (error) return <p style={{ color: 'red' }}>{error}</p>;

  return (
    <ul>
      {entries.map(e => (
        <li key={e.id}>
          <strong>{e.title}</strong> – {e.body}
          <br />
          <small>{new Date(e.created_at).toLocaleString()}</small>
        </li>
      ))}
    </ul>
  );
};
```

**Adding an entry**

```tsx
// src/components/NewEntryForm.tsx
import React, { useState } from 'react';
import api from '../api';

export const NewEntryForm: React.FC<{ onAdded: () => void }> = ({ onAdded }) => {
  const [title, setTitle] = useState('');
  const [body, setBody] = useState('');
  const [busy, setBusy] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const submit = async (e: React.FormEvent) => {
    e.preventDefault();
    setBusy(true);
    setError(null);
    try {
      await api.post('/entries', { title, body });
      setTitle('');
      setBody('');
      onAdded();
    } catch (err) {
      setError(err?.response?.data?.error || 'Failed');
    } finally {
      setBusy(false);
    }
  };

  return (
    <form onSubmit={submit}>
      <input value={title} onChange={e => setTitle(e.target.value)} placeholder="Title" required />
      <textarea value={body} onChange={e => setBody(e.target.value)} placeholder="Body" />
      <button type="submit" disabled={busy}>Add</button>
      {error && <p style={{ color: 'red' }}>{error}</p>}
    </form>
  );
};
```

