Below is a **minimal, but functional** example of a MMORPG‑style server + client written in **Node JS**.  
The goal is to show the core building blocks:

| Feature | Implementation |
|---------|-----------------|
| **Authentication** | JSON‑Web‑Token (JWT) + bcrypt password hashing |
| **Persistence** | MongoDB (via the official `mongodb` driver) |
| **Realtime gameplay** | `socket.io` for player movement, skill use and inventory updates |
| **Client** | Plain HTML + JS that talks to the REST API (for login/registration) and to the Socket.io server (for realtime actions) |

> **NOTE** – This is **starter code**. A production‑ready MMORPG would require many more safeguards (rate limiting, DDoS protection, cheat‑prevention, authoritative server logic, sharding, load‑balancing, encryption, etc.). Treat this as a learning scaffold, not a finished product.

---

## 1. Project Layout

```
mmorpg/
│
├─ server/
│   ├─ index.js          # entry point
│   ├─ config.js         # config + MongoDB URL
│   ├─ routes/
│   │   ├─ auth.js
│   │   └─ player.js
│   ├─ models/
│   │   └─ user.js
│   └─ services/
│       └─ authService.js
│
└─ client/
    ├─ index.html
    └─ client.js
```

---

## 2. Server – `server/index.js`

```js
// server/index.js
require('dotenv').config();
const http = require('http');
const express = require('express');
const cors = require('cors');
const { MongoClient, ObjectId } = require('mongodb');
const jwt = require('jsonwebtoken');
const bcrypt = require('bcrypt');
const socketIo = require('socket.io');

const { MONGO_URI, JWT_SECRET, PORT = 3000 } = process.env;

// ---- Express app ---------------------------------------------------------
const app = express();
app.use(cors());
app.use(express.json());

// ---- MongoDB connection ---------------------------------------------------
let db, Users, Players;
MongoClient.connect(MONGO_URI, { useUnifiedTopology: true })
  .then(client => {
    db = client.db('mmorpg');
    Users = db.collection('users');       // auth + permanent data
    Players = db.collection('players');   // live player state (can also be in‑memory)
    console.log('✅ MongoDB connected');
  })
  .catch(err => console.error('Mongo error', err));

// ---- Helper: auth middleware -----------------------------------------------
function authMiddleware(req, res, next) {
  const token = req.headers.authorization?.split(' ')[1];
  if (!token) return res.status(401).json({ error: 'Missing token' });
  try {
    const payload = jwt.verify(token, JWT_SECRET);
    req.userId = payload.id;
    next();
  } catch (e) {
    res.status(403).json({ error: 'Invalid token' });
  }
}

// ---- Routes ---------------------------------------------------------------
app.post('/api/register', async (req, res) => {
  const { username, password } = req.body;
  if (!username || !password) return res.status(400).json({ error: 'Missing fields' });

  const exists = await Users.findOne({ username });
  if (exists) return res.status(409).json({ error: 'User already exists' });

  const hash = await bcrypt.hash(password, 10);
  const result = await Users.insertOne({ username, password: hash });

  // create a fresh player document (position, inventory, etc.)
  await Players.insertOne({
    userId: result.insertedId,
    position: { x: 0, y: 0 },
    inventory: [],
    hp: 100,
    mana: 100
  });

  const token = jwt.sign({ id: result.insertedId }, JWT_SECRET, { expiresIn: '7d' });
  res.json({ token });
});

app.post('/api/login', async (req, res) => {
  const { username, password } = req.body;
  const user = await Users.findOne({ username });
  if (!user) return res.status(401).json({ error: 'Invalid credentials' });

  const ok = await bcrypt.compare(password, user.password);
  if (!ok) return res.status(401).json({ error: 'Invalid credentials' });

  const token = jwt.sign({ id: user._id }, JWT_SECRET, { expiresIn: '7d' });
  res.json({ token });
});

// Fetch current player state
app.get('/api/me', authMiddleware, async (req, res) => {
  const player = await Players.findOne({ userId: ObjectId(req.userId) });
  if (!player) return res.status(404).json({ error: 'Player not found' });
  res.json({ player });
});

// --------------------------------------------------------------------------
// ---- Socket.io (real‑time) -------------------------------------------------
const server = http.createServer(app);
const io = socketIo(server, {
  cors: { origin: '*' }
});

// Keep an in‑memory map of socketId → userId (helps when a socket disconnects)
const socketUserMap = new Map();

io.use(async (socket, next) => {
  // JWT token must be sent as query param: ?token=...
  const token = socket.handshake.query?.token;
  if (!token) return next(new Error('Authentication error'));

  try {
    const payload = jwt.verify(token, JWT_SECRET);
    socket.userId = payload.id;
    next();
  } catch (e) {
    next(new Error('Authentication error'));
  }
});

io.on('connection', async socket => {
  const userId = socket.userId;
  socketUserMap.set(socket.id, userId);
  console.log(`🟢 User ${userId} connected (socket ${socket.id})`);

  // Load player state and push to client
  const player = await Players.findOne({ userId: ObjectId(userId) });
  socket.emit('init', player);

  // ---------- Movement ----------
  // client: {dx, dy}
  socket.on('move', async ({ dx, dy }) => {
    const result = await Players.findOneAndUpdate(
      { userId: ObjectId(userId) },
      { $inc: { 'position.x': dx, 'position.y': dy } },
      { returnDocument: 'after' }
    );
    const updated = result.value;
    // broadcast to everybody (or only nearby players in a real game)
    io.emit('playerMoved', { userId, position: updated.position });
  });

  // ---------- Skills ----------
  // Example skill: "fireball" consumes mana and deals damage.
  socket.on('useSkill', async ({ skillId, targetUserId }) => {
    // Basic validation – in real games you’d have cooldowns, range checks, etc.
    const skillDB = {
      fireball: { manaCost: 20, damage: 30 },
      heal:    { manaCost: 15, heal: 25 }
    };
    const skill = skillDB[skillId];
    if (!skill) return socket.emit('error', { msg: 'Unknown skill' });

    const player = await Players.findOne({ userId: ObjectId(userId) });
    if (player.mana < skill.manaCost) return socket.emit('error', { msg: 'Not enough mana' });

    // Deduct mana
    await Players.updateOne(
      { userId: ObjectId(userId) },
      { $inc: { mana: -skill.manaCost } }
    );

    // Apply effect
    if (skill.damage) {
      await Players.updateOne(
        { userId: ObjectId(targetUserId) },
        { $inc: { hp: -skill.damage } }
      );
      io.emit('skillHit', { from: userId, to: targetUserId, skillId, damage: skill.damage });
    } else if (skill.heal) {
      await Players.updateOne(
        { userId: ObjectId(userId) },
        { $inc: { hp: skill.heal } }
      );
      socket.emit('skillCast', { skillId, healed: skill.heal });
    }
  });

  // ---------- Inventory ----------
  socket.on('addItem', async ({ item }) => {
    await Players.updateOne(
      { userId: ObjectId(userId) },
      { $push: { inventory: item } }
    );
    const updated = await Players.findOne({ userId: ObjectId(userId) });
    socket.emit('inventoryUpdated', updated.inventory);
  });

  socket.on('removeItem', async ({ itemId }) => {
    await Players.updateOne(
      { userId: ObjectId(userId) },
      { $pull: { inventory: { id: itemId } } }
    );
    const updated = await Players.findOne({ userId: ObjectId(userId) });
    socket.emit('inventoryUpdated', updated.inventory);
  });

  // ---------- Disconnect ----------
  socket.on('disconnect', () => {
    console.log(`🔴 User ${userId} disconnected`);
    socketUserMap.delete(socket.id);
  });
});

// --------------------------------------------------------------------------
// ---- Start server ---------------------------------------------------------
server.listen(PORT, () => {
  console.log(`🚀 Server listening on http://localhost:${PORT}`);
});
```

