// client/client.js
// ---------------------------------------------------------------
// Configuration
const API_URL = 'http://localhost:3000/api';
let token = null;               // JWT after login/register

// ---------------------------------------------------------------
// Utility: simple prompt based auth (replace with proper UI)
async function auth() {
  const mode = prompt('Enter "r" to register, "l" to login');
  const username = prompt('Username:');
  const password = prompt('Password:');

  const endpoint = mode === 'r' ? '/register' : '/login';
  const resp = await fetch(API_URL + endpoint, {
    method: 'POST',
    headers: {'Content-Type': 'application/json'},
    body: JSON.stringify({username, password})
  });
  const data = await resp.json();
  if (data.error) throw new Error(data.error);
  token = data.token;
}

// ---------------------------------------------------------------
async function fetchPlayerState() {
  const resp = await fetch(API_URL + '/me', {
    headers: { Authorization: `Bearer ${token}` }
  });
  const data = await resp.json();
  if (data.error) throw new Error(data.error);
  return data.player;
}

// ---------------------------------------------------------------
