## 2. `game.js`

```javascript
/* ------------------------------------------------------------------
   Mini Military Game – vanilla JavaScript + Canvas
   ---------------------------------------------------------------
   Controls
   ---------------------------------------------------------------
   • Move:   W A S D (or Arrow keys)
   • Aim:    Move mouse – tank turret points at cursor
   • Fire:   Left mouse button
   ------------------------------------------------------------------ */

const canvas = document.getElementById('game');
const ctx = canvas.getContext('2d');

// Resize to full window
function resize() {
  canvas.width = window.innerWidth;
  canvas.height = window.innerHeight;
}
window.addEventListener('resize', resize);
resize();

/* ---------------------------- Utility ---------------------------- */

function clamp(v, min, max) { return Math.max(min, Math.min(max, v)); }
function dist(ax, ay, bx, by) { return Math.hypot(ax - bx, ay - by); }

/* --------------------------- Game State -------------------------- */

let score = 0;
const scoreSpan = document.getElementById('score');

const player = {
  x: canvas.width / 2,
  y: canvas.height / 2,
  radius: 20,
  speed: 3,
  angle: 0,          // body angle (optional)
  turretAngle: 0,    // points toward mouse
  color: '#0af',
};

const bullets = [];   // {x,y,dx,dy,life}
const enemies = [];   // {x,y,dx,dy,spd,radius}

// Input handling
const keys = {};
window.addEventListener('keydown', e => keys[e.key.toLowerCase()] = true);
window.addEventListener('keyup',   e => keys[e.key.toLowerCase()] = false);

let mouse = {x: 0, y: 0, down: false};
canvas.addEventListener('mousemove', e => {
  const rect = canvas.getBoundingClientRect();
  mouse.x = e.clientX - rect.left;
  mouse.y = e.clientY - rect.top;
});
canvas.addEventListener('mousedown', e => mouse.down = true);
canvas.addEventListener('mouseup',   e => mouse.down = false);

/* ---------------------------- Entities --------------------------- */

// Player movement
function updatePlayer() {
  let vx = 0, vy = 0;
  if (keys['w'] || keys['arrowup'])    vy -= 1;
  if (keys['s'] || keys['arrowdown'])  vy += 1;
  if (keys['a'] || keys['arrowleft'])  vx -= 1;
  if (keys['d'] || keys['arrowright']) vx += 1;
  if (vx || vy) {
    const len = Math.hypot(vx, vy);
    vx = (vx / len) * player.speed;
    vy = (vy / len) * player.speed;
    player.x = clamp(player.x + vx, player.radius, canvas.width - player.radius);
    player.y = clamp(player.y + vy, player.radius, canvas.height - player.radius);
  }

  // Turret points at mouse
  player.turretAngle = Math.atan2(mouse.y - player.y, mouse.x - player.x);
}

// Fire bullets
function shoot() {
  const speed = 6;
  const angle = player.turretAngle;
  const bullet = {
    x: player.x + Math.cos(angle) * player.radius,
    y: player.y + Math.sin(angle) * player.radius,
    dx: Math.cos(angle) * speed,
    dy: Math.sin(angle) * speed,
    radius: 4,
    life: 100,   // frames
    color: '#ff0'
  };
  bullets.push(bullet);
}

// Create a new enemy at a random edge
function spawnEnemy() {
  const side = Math.floor(Math.random() * 4);
  let x, y;
  const margin = 30;
  switch (side) {
    case 0: // top
      x = Math.random() * canvas.width;
      y = -margin;
      break;
    case 1: // right
      x = canvas.width + margin;
      y = Math.random() * canvas.height;
      break;
    case 2: // bottom
      x = Math.random() * canvas.width;
      y = canvas.height + margin;
      break;
    default: // left
      x = -margin;
      y = Math.random() * canvas.height;
  }
  const enemy = {
    x, y,
    dx: 0, dy: 0,
    spd: 1.2,
    radius: 18,
    color: '#f44'
  };
  enemies.push(enemy);
}

// Update bullet positions, remove expired ones
function updateBullets() {
  for (let i = bullets.length - 1; i >= 0; i--) {
    const b = bullets[i];
    b.x += b.dx;
    b.y += b.dy;
    b.life--;
    // Remove if off‑screen or dead
    if (b.life <= 0 ||
        b.x < -b.radius || b.x > canvas.width + b.radius ||
        b.y < -b.radius || b.y > canvas.height + b.radius) {
      bullets.splice(i, 1);
    }
  }
}

// Update enemy movement toward player
function updateEnemies() {
  for (let i = enemies.length - 1; i >= 0; i--) {
    const e = enemies[i];
    const angle = Math.atan2(player.y - e.y, player.x - e.x);
    e.dx = Math.cos(angle) * e.spd;
    e.dy = Math.sin(angle) * e.spd;
    e.x += e.dx;
    e.y += e.dy;

    // Simple collision with player (game over – restart)
    if (dist(e.x, e.y, player.x, player.y) < e.radius + player.radius) {
      alert('Game Over! Your score: ' + score);
      resetGame();
      return;
    }
  }
}

// Collision detection: bullet ↔ enemy
function checkCollisions() {
  for (let i = bullets.length - 1; i >= 0; i--) {
    const b = bullets[i];
    for (let j = enemies.length - 1; j >= 0; j--) {
      const e = enemies[j];
      if (dist(b.x, b.y, e.x, e.y) < b.radius + e.radius) {
        // Remove both
        bullets.splice(i, 1);
        enemies.splice(j, 1);
        score++;
        scoreSpan.textContent = score;
        break;
      }
    }
  }
}

/* -------------------------- Rendering --------------------------- */

function drawTank(t) {
  // Body
  ctx.fillStyle = t.color;
  ctx.beginPath();
  ctx.arc(t.x, t.y, t.radius, 0, Math.PI * 2);
  ctx.fill();

  // Turret
  const turretLen = t.radius * 1.4;
  const tipX = t.x + Math.cos(t.turretAngle) * turretLen;
  const tipY = t.y + Math.sin(t.turretAngle) * turretLen;
  ctx.strokeStyle = '#fff';
  ctx.lineWidth = 4;
  ctx.beginPath();
  ctx.moveTo(t.x, t.y);
  ctx.lineTo(tipX, tipY);
  ctx.stroke();
}

function drawBullet(b) {
  ctx.fillStyle = b.color;
  ctx.beginPath();
  ctx.arc(b.x, b.y, b.radius, 0, Math.PI * 2);
  ctx.fill();
}

function drawEnemy(e) {
  ctx.fillStyle = e.color;
  ctx.beginPath();
  ctx.arc(e.x, e.y, e.radius, 0, Math.PI * 2);
  ctx.fill();
}

/* --------------------------- Game Loop -------------------------- */

let enemySpawnTimer = 0;
function resetGame() {
  score = 0;
  scoreSpan.textContent = score;
  player.x = canvas.width / 2;
  player.y = canvas.height / 2;
  bullets.length = 0;
  enemies.length = 0;
  enemySpawnTimer = 0;
}

function loop() {
  // ---- UPDATE -------------------------------------------------
  updatePlayer();

  if (mouse.down) {
    // Simple fire‑rate limiter
    if (bullets.length < 5) shoot();
    mouse.down = false; // single shot per click
  }

  updateBullets();
  updateEnemies();
  checkCollisions();

  // Spawn a new enemy every ~2 seconds (adjust as you like)
  enemySpawnTimer++;
  if (enemySpawnTimer > 120) { // assuming ~60 fps
    spawnEnemy();
    enemySpawnTimer = 0;
  }

  // ---- RENDER -------------------------------------------------
  ctx.clearRect(0, 0, canvas.width, canvas.height);

  drawTank(player);
  bullets.forEach(drawBullet);
  enemies.forEach(drawEnemy);

  requestAnimationFrame(loop);
}

// Kick it off
resetGame();
requestAnimationFrame(loop);
```

---

### How it works
1. **Canvas setup** – The canvas automatically resizes to fill the viewport.
2. **Player tank** – Moves with the keyboard and rotates its turret toward the mouse pointer.
3. **Bullets** – Spawned on left‑click, travel in a straight line, and disappear after a short lifespan or when they leave the screen.
4. **Enemies** – Appear at random screen edges and homing‑move toward the player.
5. **Collisions** – Simple circle‑based checks handle bullet‑enemy hits and enemy‑player contact (the latter ends the game).
6. **Score UI** – Updated whenever an enemy is destroyed.

You can copy the two files into a folder, open `index.html` in a browser, and start playing. Feel free to add:

* different enemy types (vary speed, size, color)  
* obstacles or walls  
* sound effects (via the Web Audio API)  
* a health bar, levels, or a pause menu  

Enjoy hacking on the prototype! 🚀

