### Что нужно сделать  

1. **Определить «placeholder»** – значение, которое хранится в атрибуте `placeholder` у `<select>`.  
2. **Найти нужный `<option>`** – тот, чьё `value` совпадает с найденным placeholder.  
3. **Установить ему `selected`** (чтобы оригинальный `<select>` был корректно установлен).  
4. **Отметить соответствующий кастомный элемент** (`<span class="custom-option">`) классом `selection` – именно так ваш скрипт сейчас визуально выделяет выбранный пункт.  

Ниже – полностью готовый кусок кода, в котором всё это реализовано.  
Он полностью совместим с вашим текущим скриптом, только добавлен небольшой блок‑проверка внутри `$(".custom-select").each(...)`.

```javascript
$(".custom-select").each(function () {
	// ---------- 1. Считываем атрибуты исходного <select> ----------
	var $origSelect = $(this);
	var classes   = $origSelect.attr("class") || "";
	var id        = $origSelect.attr("id")      || "";
	var name      = $origSelect.attr("name")    || "";
	var placeholder = $origSelect.attr("placeholder") || "";   // <-- ваш placeholder

	// ---------- 2. Находим option, чей value == placeholder ----------
	var $matchedOption = $origSelect.find('option[value="' + placeholder + '"]');
	if ($matchedOption.length) {
		// Устанавливаем «selected» у настоящего option
		$matchedOption.prop("selected", true);
		// (опционально) добавляем атрибут selected, если нужен в HTML‑разметке:
		$matchedOption.attr("selected", "selected");
	}

	// ---------- 3. Формируем html кастомного селекта ----------
	var template = '<div class="' + classes + '">';

	// Текст в триггере – либо placeholder, либо текст выбранного option
	var triggerText = placeholder;
	if ($matchedOption.length) {
		triggerText = $matchedOption.text();   // показываем реальный текст
	}
	template +=
		'<span class="custom-select-trigger">' + triggerText + "</span>";
	template += '<div class="custom-options">';

	// Перебираем все option → генерируем <span class="custom-option">
	$origSelect.find("option").each(function () {
		var $opt = $(this);
		var optClass = $opt.attr("class") || "";
		var optValue = $opt.attr("value") || "";
		var optText  = $opt.html();

		// Если value совпадает с placeholder → отмечаем как выбранный
		var selectedClass = (optValue === placeholder) ? " selection" : "";

		template +=
			'<span class="custom-option' +
			selectedClass +
			" " +
			optClass +
			'" data-value="' +
			optValue +
			'">' +
			optText +
			"</span>";
	});

	template += "</div></div>";

	// ---------- 4. Оборачиваем оригинальный select и вставляем кастом ----------
	$origSelect.wrap('<div class="custom-select-wrapper"></div>');
	$origSelect.hide();                // скрываем оригинал
	$origSelect.after(template);       // вставляем готовый шаблон
});

/* ---------- Остальная часть вашего скрипта (без изменений) ---------- */
$(".custom-option:first-of-type").hover(
	function () {
		$(this).parents(".custom-options").addClass("option-hover");
	},
	function () {
		$(this).parents(".custom-options").removeClass("option-hover");
	}
);

$(".custom-select-trigger").on("click", function (event) {
	$("html").one("click", function () {
		$(".custom-select").removeClass("opened");
	});
	$(this).parents(".custom-select").toggleClass("opened");
	event.stopPropagation();
});

$(".custom-option").on("click", function () {
	$(this)
		.parents(".custom-select-wrapper")
		.find("select")
		.val($(this).data("value"));
	$(this)
		.parents(".custom-options")
		.find(".custom-option")
		.removeClass("selection");
	$(this).addClass("selection");
	$(this).parents(".custom-select").removeClass("opened");
	$(this)
		.parents(".custom-select")
		.find(".custom-select-trigger")
		.text($(this).text());
});

$(".custom-select-wrapper .custom-options .custom-option").on(
	"click",
	function () {
		var value = $(this).data("value");
		var select = $(this).closest(".custom-select-wrapper").find("select");
		select.val(value).trigger("change");
	}
);
```

### Пояснения к коду

| Шаг | Что делаем | Почему |
|-----|------------|--------|
| **1** | Считываем `placeholder` у `<select>` | Это ваш «значение‑по‑умолчанию», которое должно стать выбранным. |
| **2** | Находим `<option>` с тем же `value` | Если такой пункт существует – делаем его `selected`. |
| **3** | При генерации кастомных `<span class="custom-option">` добавляем класс `selection` *только* тем пунктам, чей `value` совпал с placeholder. | Класс `selection` уже используется в вашем скрипте для подсветки выбранного элемента. |
| **4** | Устанавливаем текст в триггере (`.custom-select-trigger`). Если найдено совпадение – берём реальный текст из `<option>`, иначе отображаем сам placeholder. | Пользователь сразу видит выбранный пункт, а не «плейсхолдер». |
| **Последующий код** | Остаётся без изменений – он отвечает за открытие/закрытие списка и синхронизацию оригинального `<select>` с кастомным представлением. |  |

### Как это работает в живом примере

```html
<select class="custom-select" placeholder="2">
    <option value="1">Один</option>
    <option value="2">Два</option>
    <option value="3">Три</option>
</select>
```

* После выполнения скрипта:  

  * `<option value="2">` получит атрибут `selected`.  
  * В кастомном контейнере первый `<span class="custom-option">` с `data-value="2"` будет иметь класс `selection`.  
  * Текст в элементе `.custom-select-trigger` будет «Два».  

Таким образом, placeholder «подталкивает» выбранный пункт, а ваш UI отображает его корректно.  

Если у вас **не стандартный** атрибут `placeholder` (например, `data-placeholder`), просто замените строку

```javascript
var placeholder = $origSelect.attr("placeholder") || "";
```

на

```javascript
var placeholder = $origSelect.data("placeholder") || "";
```

и всё будет работать аналогично.  

