// ------------------------------------------------------------------
// 5️⃣  Basic hardening (add BEFORE your routes)
// ------------------------------------------------------------------
const helmet   = require('helmet');
const rateLimit = require('express-rate-limit');
const { body, validationResult } = require('express-validator');

app.use(helmet());                     // Security‑related HTTP headers
app.use(rateLimit({                    // Global rate limiting
  windowMs: 5 * 60 * 1000,             // 5 minutes
  max: 200,                            // limit each IP to 200 requests per window
  standardHeaders: true,
  legacyHeaders: false,
}));

// Example validation middleware for /register (you can expand)
const registerValidator = [
  body('username')
    .trim()
    .isLength({ min: 3 }).withMessage('Username must be at least 3 characters')
    .escape(),
  body('email')
    .trim()
    .isEmail().withMessage('Valid e‑mail required')
    .normalizeEmail(),
  body('password')
    .isLength({ min: 8 }).withMessage('Password must be ≥ 8 chars')
];

// ------------------------------------------------------------------
// 6️⃣  Updated /register route using the validator & bcrypt
// ------------------------------------------------------------------
const bcrypt = require('bcrypt');
const SALT_ROUNDS = 12;

app.post('/register', registerValidator, async (req, res) => {
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    // Send back a simple JSON error – adjust to your UI as needed
    return res.status(400).json({ errors: errors.array() });
  }

  const { username, email, password } = req.body;
  const hashedPassword = await bcrypt.hash(password, SALT_ROUNDS);
  const userData = { username, email, password: hashedPassword };

  // ----> (same JSON file handling as before – consider swapping to a DB) <----
  // (kept unchanged for brevity)
  fs.readFile('users.json', (err, data) => {
    let json = (err || !data.length) ? [] : JSON.parse(data);
    json.push(userData);
    fs.writeFile('users.json', JSON.stringify(json, null, 2), (err) => {
      if (err) return res.status(500).send('Server error');
      res.redirect('/content');
    });
  });
});
```

> **Tip:** If you’re not ready to switch to a full database, you can still mitigate the race‑condition risk by using `fs.promises` with an atomic write helper (`write-file-atomic` npm package). That way you won’t corrupt `users.json` when two registrations happen at the *exact* same moment.

