No security‑critical logic here; just keep the stylesheet **static**.

---

## 5. JavaScript – The Heart (`script.js`)

```js
/**
 * script.js – fetches a Markdown file, converts it to HTML,
 * sanitises the result, and injects it into the page.
 *
 * Security goals:
 *   • Never execute raw markdown as script.
 *   • Sanitize every piece of generated HTML (DOMPurify).
 *   • Use the Fetch API (no XHR hijacking because CSP blocks remote origins).
 *   • No `eval`, `new Function`, or innerHTML with unsanitised content.
 */

document.addEventListener('DOMContentLoaded', () => {
  const select = document.getElementById('fileSelect');
  const contentDiv = document.getElementById('content');

  // Render the initial selection
  renderMarkdown(select.value);

  // Re‑render on user change
  select.addEventListener('change', (e) => {
    renderMarkdown(e.target.value);
  });
});

/**
 * Load a markdown file and render it safely.
 * @param {string} url – relative URL to the .md file.
 */
async function renderMarkdown(url) {
  try {
    const response = await fetch(url, { cache: "no-store" });
    // CSP disallows cross‑origin fetch unless `script-src` whitelists it.
    if (!response.ok) throw new Error(`Unable to load ${url}: ${response.status}`);

    const markdownText = await response.text();

    // 1️⃣ Parse markdown → HTML (marked is deliberately chosen for its small size).
    const rawHTML = marked.parse(markdownText, {
      // You can enable or disable features here. Avoid HTML support inside Markdown
      // because that would allow an attacker to inject HTML directly.
      gfm: true,
      breaks: true,
      sanitize: false   // Don't rely on marked's built‑in sanitisation.
    });

    // 2️⃣ Sanitize the resulting HTML using DOMPurify.
    const cleanHTML = DOMPurify.sanitize(rawHTML, {
      // Optional: forbid specific tags/attributes you never need.
      FORBID_TAGS: ['script', 'style'],
      FORBID_ATTR: ['onerror', 'onclick', 'onload', 'style'] // remove inline event handlers.
    });

    // 3️⃣ Insert the safe HTML into the DOM.
