const s3 = new S3Client({ region: process.env.AWS_REGION });
const BUCKET = process.env.S3_BUCKET;

// ---------- 1️⃣ Initiate multipart upload ----------
app.post('/multipart/init', async (req, res) => {
  const { filename, mimeType, partCount } = req.body;
  if (!filename || !mimeType || !partCount) {
    return res.status(400).json({ error: 'Missing params' });
  }

  // Create multipart upload with server‑side encryption
  const createCmd = new CreateMultipartUploadCommand({
    Bucket: BUCKET,
    Key: `uploads/${Date.now()}_${filename}`,
    ContentType: mimeType,
    ServerSideEncryption: 'AES256',
  });

  try {
    const { UploadId, Key } = await s3.send(createCmd);

    // Generate presigned URLs for each part
    const urls = await Promise.all(
      Array.from({ length: partCount }, async (_, i) => {
        const partNumber = i + 1;
        const uploadPartCmd = new PutObjectCommand({
          Bucket: BUCKET,
          Key,
          PartNumber: partNumber,
          UploadId,
        }); // PutObject for multipart part is a special request
        const url = await getSignedUrl(s3, uploadPartCmd, {
          expiresIn: 900, // 15 min validity
        });
        return { partNumber, url };
      })
    );

    // Store the upload-id + key somewhere (Redis, DB, etc.) so you can verify later.
    // Example (in‑memory for demo):
    // uploadStore.set(UploadId, { Key, parts: [] });
    res.json({ uploadId: UploadId, key: Key, urls });
  } catch (e) {
    console.error('Init multipart error:', e);
    res.status(500).json({ error: 'Failed to start upload' });
  }
});

// ---------- 2️⃣ Complete multipart upload ----------
app.post('/multipart/complete', async (req, res) => {
  const { uploadId, key, parts } = req.body; // parts = [{ PartNumber, ETag }, ...]
  if (!uploadId || !key || !Array.isArray(parts)) {
    return res.status(400).json({ error: 'Invalid payload' });
  }

  const completeCmd = new CompleteMultipartUploadCommand({
    Bucket: BUCKET,
    Key: key,
    UploadId: uploadId,
    MultipartUpload: { Parts: parts },
  });

  try {
    const result = await s3.send(completeCmd);
    console.log('✅ Multipart completed', result);
    res.json({ location: result.Location, eTag: result.ETag });
  } catch (e) {
    console.error('Complete error:', e);
    res.status(500).json({ error: 'Failed to complete upload' });
  }
});

// ---------- 3️⃣ Optional abort endpoint ----------
app.post('/multipart/abort', async (req, res) => {
  const { uploadId, key } = req.body;
  if (!uploadId || !key) {
    return res.status(400).json({ error: 'Missing params' });
  }
  try {
    await s3.send(new AbortMultipartUploadCommand({
      Bucket: BUCKET,
      Key: key,
      UploadId: uploadId,
    }));
    res.json({ aborted: true });
  } catch (e) {
    console.error('Abort error:', e);
    res.status(500).json({ error: 'Failed to abort' });
  }
});

app.listen(3000, () => console.log('🚀 API ready on :3000'));
```

