  // ... see full implementation above
}
```

### b) Client‑side direct upload (2‑step)

1. **Init** → `POST /multipart/init` → `{ uploadId, key, urls }`  
2. **PUT** each part → `fetch(url, { method: "PUT", body: partBlob })` (store ETag)  
3. **Complete** → `POST /multipart/complete` with `[{ PartNumber, ETag }]`

### c) Abort (optional)

```js
await fetch('/multipart/abort', {
  method: 'POST',
  headers: { 'Content-Type': 'application/json', Authorization: `Bearer ${jwt}` },
  body: JSON.stringify({ uploadId, key })
});
```

---

## 7. TL;DR Code Summary (Server‑Side)

```js
// Express + lib-storage
app.post('/upload', (req, res) => {
  const busboy = Busboy({ headers: req.headers });
  busboy.on('file', (field, file, name, enc, type) => {
    const upload = new Upload({
      client: s3,
      params: { Bucket, Key: `uploads/${Date.now()}_${name}`, ServerSideEncryption: 'AES256' },
      partSize: 10*1024**2,
    });
    upload.on('httpUploadProgress', p => console.log(p.loaded));
    file.pipe(upload);
    upload.done().then(r => res.json(r)).catch(e => res.status(500).json(e));
  });
  req.pipe(busboy);
