    const next = new Vec(this.pos.x+dx, this.pos.y+dy);
    if(g.isFree(next) || stash.pos.equals(next)){
      this.pos = next;
    }
    // reached stash?
    if(this.pos.equals(stash.pos)){
      g.removeEntity(stash);
      g.removeEntity(this);
    }
  }
}

/* --------------------------------------------------------------
   Game engine
-------------------------------------------------------------- */
class Game {
  readonly width = 30;   // grid dimensions
  readonly height = 15;
  readonly dayLength = 10_000; // ms
  gridEl = document.getElementById('grid') as HTMLPreElement;
  infoEl = document.getElementById('info') as HTMLDivElement;
  entities = new Set<Entity>();
  player?: Player;
  placingGold = false;
  night = false;
  lastToggle = 0;
  loopId = 0;

  constructor(){
    document.getElementById('play')!.onclick = ()=>this.start();
    document.getElementById('place')!.onclick = ()=>{ this.placingGold=!this.placingGold;
                                                      document.getElementById('place')!.textContent=
                                                      this.placingGold?'Cancel Placement':'Place Gold Stash';
                                                    };
    this.gridEl.onclick = e=>this.handleGridClick(e);
  }

  start(){
    this.reset();
    this.spawnPlayer();
    document.getElementById('place')!.disabled = false;
    this.lastToggle = performance.now();
    this.loopId = requestAnimationFrame(this.tick.bind(this));
  }

  reset(){
    this.entities.clear();
    this.player = undefined;
    this.placingGold = false;
    this.night = false;
    this.gridEl.textContent = '';
    this.infoEl.textContent = '';
  }

  spawnPlayer(){
    const p = new Player(this.randomFreePos());
    this.entities.add(p);
    this.player = p;
  }

  randomFreePos():Vec{
    let pos:Vec;
    do{ pos = Vec.rand(this.width,this.height); }while(!this.isFree(pos));
    return pos;
  }

  isFree(p:Vec):boolean{
    if(p.x<0||p.y<0||p.x>=this.width||p.y>=this.height) return false;
    for(const e of this.entities) if(e.pos.equals(p)) return false;
    return true;
  }

  /* ------- UI ------------------------------------------------- */
  render(){
    const lines = Array.from({length:this.height},()=>Array(this.width).fill('.'));
    for(const e of this.entities){
      lines[e.pos.y][e.pos.x] = e.char;
    }
    this.gridEl.textContent = lines.map(l=>l.join('')).join('\n');
    const mode = this.night? '🌙 Night' : '☀️ Day';
    const gold = [...this.entities].filter(e=>e instanceof Gold).length;
    const zombies = [...this.entities].filter(e=>e instanceof Zombie).length;
    this.infoEl.textContent = `${mode} | Gold Stashes: ${gold} | Zombies: ${zombies}`;
  }

  handleGridClick(e:MouseEvent){
    if(!this.placingGold) return;
    const rect = this.gridEl.getBoundingClientRect();
    const cellW = rect.width / this.width;
    const cellH = rect.height / this.height;
    const x = Math.floor((e.clientX-rect.left)/cellW);
    const y = Math.floor((e.clientY-rect.top)/cellH);
    const pos = new Vec(x,y);
    if(this.isFree(pos)){
      this.entities.add(new Gold(pos));
    }
    this.placingGold = false;
    document.getElementById('place')!.textContent='Place Gold Stash';
  }

  /* ------- Game logic ---------------------------------------- */
  tick(ts:number){
    // day/night toggle
    if(ts - this.lastToggle >= this.dayLength){
      this.night = !this.night;
      this.lastToggle = ts;
      if(this.night) this.spawnZombies();
    }

    // update entities
    for(const e of [...this.entities]) e.tick(this);
    this.render();
    this.loopId = requestAnimationFrame(this.tick.bind(this));
  }

  spawnZombies(){
    const golds = [...this.entities].filter(e=>e instanceof Gold) as Gold[];
    if(golds.length===0) return;
    const count = Math.max(1, Math.floor(golds.length/2));
    for(let i=0;i<count;i++){
      const edge = Math.random()<0.5 ? 'x' : 'y';
      const pos = edge==='x' ?
        new Vec(Math.random()<0.5?0:this.width-1, Math.floor(Math.random()*this.height)) :
        new Vec(Math.floor(Math.random()*this.width), Math.random()<0.5?0:this.height-1);
      this.entities.add(new Zombie(pos));
    }
  }

  nearestGold(p:Vec):Gold|undefined{
    const golds = [...this.entities].filter(e=>e instanceof Gold) as Gold[];
    if(golds.length===0) return undefined;
    golds.sort((a,b)=>p.distanceTo(a.pos)-p.distanceTo(b.pos));
    return golds[0];
  }

  removeEntity(e:Entity){
    this.entities.delete(e);
  }
}

/* --------------------------------------------------------------
   Boot
-------------------------------------------------------------- */
new Game();
</script>
</body>
</html>
```

### How it works
| Feature | Implementation |
|---------|----------------|
| **Grid** | A `<pre>` element is filled with `.` (empty), `@` (player), `G` (gold stash) and `Z` (zombie). Monospace font gives the ASCII feel. |
| **Play button** | Starts a new game, clears old state, randomly places the player and begins the animation loop. |
| **Place Gold** | Click “Place Gold Stash”, then click any free cell on the grid – a gold stash (`G`) appears. |
| **Day/Night** | A 10 s timer flips `night` flag. When night begins zombies are spawned at random edges. |
| **Zombie AI** | Each zombie moves one step each tick toward the nearest gold stash using Manhattan distance (simple, fast). |
| **Destruction** | If a zombie reaches a stash it removes both the stash and itself from the entity set. |
| **Modern JS** | `class`, arrow functions, `Map`/`Set`, optional chaining, destructuring, `requestAnimationFrame`, template literals – all supported by current Chrome. |
| **Modular** | Core concepts (vector, entities, game loop) are split into separate classes, keeping responsibilities clear. |
| **Performance** | The world is tiny (30 × 15). Using a `Set` for entities and iterating a shallow copy (`[...this.entities]`) prevents modification‑while‑iterating bugs. Rendering rebuilds a string each frame – cheap for this size. |

Open the file, press **▶ Play**, then **Place Gold Stash** to add defenses. Watch the day/night cycle, and survive the zombies! Enjoy experimenting – you can easily extend this skeleton with more tower types, health, scoring, etc.

