const user = await User.findOne({ where: { username: { [Op.iLike]: `%${req.params.username}` } } });

// 2️⃣ Grab the uploaded files from the request (express‑fileupload populates req.files)
const { avatar, background } = req.files;

// 3️⃣ Store them under <project>/uploads/<username>_avatar|_background
// 4️⃣ Update the user record with the new paths (or keep the old ones)
