```

### 3.3. Manual header handling (generic for any framework)

If you don’t want a library, you can manually add the required headers to **both** the preflight (`OPTIONS`) response and the actual request response.

#### Example in Express (Node.js)

```js
const express = require('express');
const app = express();

app.use(express.json());

// Middleware to set CORS headers
app.use((req, res, next) => {
  const allowedOrigin = 'http://localhost:3000';
  res.setHeader('Access-Control-Allow-Origin', allowedOrigin);
  res.setHeader('Vary', 'Origin'); // helps caches

  // If the request includes credentials, you cannot use '*'
  // res.setHeader('Access-Control-Allow-Credentials', 'true');

  if (req.method === 'OPTIONS') {
    // Preflight request
    res.setHeader('Access-Control-Allow-Methods', 'POST, GET, OPTIONS');
    res.setHeader('Access-Control-Allow-Headers', 'Content-Type, Authorization');
    return res.sendStatus(204); // No Content
  }

  next();
});

app.post('/generate-image', (req, res) => {
  // process the image generation
  res.json({ status: 'ok' });
});

app.listen(5000, () => console.log('API listening on :5000'));
```

#### Example in ASP.NET Core

```csharp
public void ConfigureServices(IServiceCollection services)
{
    services.AddCors(options =>
    {
        options.AddPolicy("LocalDev", builder =>
        {
            builder.WithOrigins("http://localhost:3000")
                   .AllowAnyHeader()
                   .AllowAnyMethod()
                   .AllowCredentials(); // remove if you aren't using cookies/auth
        });
    });
    services.AddControllers();
}

public void Configure(IApplicationBuilder app, IWebHostEnvironment env)
{
    app.UseCors("LocalDev");
    app.UseRouting();
    app.UseEndpoints(endpoints => endpoints.MapControllers());
}
```

### 3.4. If Using a Reverse Proxy (nginx, Apache, Caddy)

Make sure the proxy passes through `OPTIONS` requests **without** being converted to a 404 or 301.

```nginx
location /generate-image {
    if ($request_method = OPTIONS ) {
        add_header 'Access-Control-Allow-Origin'  'http://localhost:3000';
        add_header 'Access-Control-Allow-Methods' 'POST, OPTIONS';
        add_header 'Access-Control-Allow-Headers' 'Content-Type, Authorization';
        add_header 'Access-Control-Max-Age' 86400;
        return 204;
    }

    proxy_pass http://localhost:5000;
    proxy_set_header Host $host;
}
```

