var container   = document.querySelector('.container');
var editor      = document.querySelector('.editor');
var caretBlock  = document.createElement('span');
caretBlock.className = 'caret-block';
container.appendChild(caretBlock);

/* ---------- 2️⃣ Helper: position the caret ---------- */
function positionCaret() {
    // Guard: editor may be detached (e.g. page navigation)
    if (!editor || !caretBlock) { return; }

    var sel = window.getSelection();
    if (!sel.rangeCount) { return; }

    var range = sel.getRangeAt(0).cloneRange();
    // Collapse to start so we get the caret’s *insertion point*
    range.collapse(true);

    // getBoundingClientRect() returns {left, top, width, height}
    var rect = range.getBoundingClientRect();

    // When the editor is empty, getBoundingClientRect() can be 0×0.
    // In that case use the editor’s top‑left as fallback.
    if (rect.width === 0 && rect.height === 0) {
        var editorRect = editor.getBoundingClientRect();
        rect.left = editorRect.left;
        rect.top  = editorRect.top;
