const fetch = require('node-fetch');
const jwt = require('jsonwebtoken');
const token = jwt.sign({ sub: 'user-123' }, 'my-secret', { expiresIn: '1h' });

const ws = new WebSocket(`ws://localhost:3000?token=${token}`);
ws.on('open', () => console.log('WS opened'));
ws.on('message', m => console.log('WS ->', JSON.parse(m)));

(async () => {
  const res = await fetch('http://localhost:3000/api/message', {
    method: 'POST',
    headers: {
      'Content-Type': 'application/json',
      'Authorization': `Bearer ${token}`,
    },
    body: JSON.stringify({ text: 'Hello from client' })
  });
  console.log('HTTP ->', await res.json());
})();
EOF
```

Вы увидите в консоли как HTTP‑ответ, так и то же событие, полученное по WS.

