    var $origSelect = $(this);
    var classes = $origSelect.attr("class");
    var id      = $origSelect.attr("id");
    var name    = $origSelect.attr("name");
    var placeholder = $origSelect.attr("placeholder") || "";

    // -----------------------------------------------------------------
    // 1️⃣ Если placeholder совпадает с value любой option – делаем её selected
    // -----------------------------------------------------------------
    var $matchedOption = $origSelect.find('option[value="' + placeholder + '"]');
    if ($matchedOption.length) {
        // Ставим атрибут selected в оригинальном select
        $origSelect.val(placeholder);               // <select>.val() уже ставит selected
        // Запоминаем текст выбранной опции (для отображения в триггере)
        var selectedText = $matchedOption.text();
    } else {
        // Если совпадения нет – placeholder будет отображён «как есть»
        var selectedText = placeholder;
    }

    // -----------------------------------------------------------------
    // 2️⃣ Формируем кастомный шаблон
    // -----------------------------------------------------------------
    var template = '<div class="' + classes + '">';
    // Текст триггера – либо найденный текст опции, либо сам placeholder
    template += '<span class="custom-select-trigger">' + selectedText + '</span>';
