// src/services/FavoriteManager.js
export default class FavoriteManager {
  static _storageKey = 'favorites';

  /** Retourne le tableau d'IDs stockés (toujours un tableau) */
  static _load() {
    const raw = localStorage.getItem(this._storageKey);
    try {
      return raw ? JSON.parse(raw) : [];
    } catch (_) {
      // Si le JSON est corrompu on repart à zéro (défense contre le "tampering")
      localStorage.removeItem(this._storageKey);
      return [];
    }
  }

  static _save(list) {
    localStorage.setItem(this._storageKey, JSON.stringify(list));
  }

  /** true si l'ID est déjà en favoris */
  static isFavorite(id) {
    const fav = this._load();
    return fav.includes(id);
  }

  /** Ajoute l'ID (idempotent) */
  static add(id) {
    const fav = this._load();
    if (!fav.includes(id)) {
      fav.push(id);
      this._save(fav);
    }
  }

  /** Supprime l'ID (idempotent) */
  static remove(id) {
    let fav = this._load();
    fav = fav.filter(item => item !== id);
    this._save(fav);
  }

  /** Bascule l'état (add ↔ remove) et renvoie le nouvel état */
  static toggle(id) {
    if (this.isFavorite(id)) {
      this.remove(id);
      return false;
    }
    this.add(id);
    return true;
  }
}

