// worker.js
// -------------------------------
// 1. 只引用纯 JS 版的 sheetjs（xlsx.full.min.js）
// 2. 通过 postMessage 将解析结果返回主线程
// -------------------------------

// 通过 importScripts 加载库（必须是同源或 CORS 允许的）
importScripts('https://cdn.jsdelivr.net/npm/xlsx@0.19.2/dist/xlsx.full.min.js');

self.onmessage = function (e) {
  const { fileArrayBuffer } = e.data;

  try {
    // 读取 Excel 工作簿 (binary string → Uint8Array)
    const wb = XLSX.read(fileArrayBuffer, { type: 'array' });

    // 把每个 Sheet 的原始二维数组取出
    const sheets = {};
    wb.SheetNames.forEach(sheetName => {
      const ws = wb.Sheets[sheetName];
      const json = XLSX.utils.sheet_to_json(ws, { header: 1, raw: false }); // 2D array
      sheets[sheetName] = json;
    });

    self.postMessage({ success: true, sheets });
  } catch (err) {
    self.postMessage({ success: false, error: err.message });
  }
};
```

