// ---------- 3. 渲染 Sheet ----------
function renderSheets(sheets) {
  const tabList = document.getElementById('sheetTabs');
  const tabContent = document.getElementById('sheetContent');
  tabList.innerHTML = '';
  tabContent.innerHTML = '';

  const sheetNames = Object.keys(sheets);
  if (sheetNames.length === 0) {
    alert('工作簿为空或没有可读的工作表');
    return;
  }
  sheetNames.forEach((name, idx) => {
    const active = idx === 0 ? 'active' : '';
    const tabId = `sheet-${idx}`;

    // ---- Tab Nav ----
    const li = document.createElement('li');
    li.className = 'nav-item';
    li.innerHTML = `
      <button class="nav-link ${active}" id="${tabId}-tab" data-bs-toggle="tab"
              data-bs-target="#${tabId}" type="button" role="tab"
              aria-controls="${tabId}" aria-selected="${active ? 'true' : 'false'}">
        ${escapeHtml(name)}
      </button>`;
    tabList.appendChild(li);

    // ---- Tab Pane ----
    const pane = document.createElement('div');
    pane.className = `tab-pane fade ${active ? 'show active' : ''}`;
    pane.id = tabId;
    pane.setAttribute('role', 'tabpanel');
    pane.setAttribute('aria-labelledby', `${tabId}-tab`);
    pane.innerHTML = `<div class="sheet-table"><table id="${tabId}-table" class="display compact" width="100%"></table></div>`;
    tabContent.appendChild(pane);

    // ---- 用 DataTables 渲染二维数组 ----
    const data = sheets[name]; // 2D array: [[A1, B1, ...], [A2, B2, ...], ...]
    // 第一行若为标题则保留，否则自动生成列名
    const headerRow = data[0];
    const isHeader = headerRow.every(cell => typeof cell === 'string' && cell.trim() !== '');
    const columns = (isHeader ? headerRow : headerRow.map((_, i) => `列${i + 1}`))
      .map(col => ({
        title: escapeHtml(col), // 防止 XSS, DataTables 渲染的是 text
        // data: 警惕 `null` / `undefined`，统一为 ''，且转义
        render: d => d === null || d === undefined ? '' : escapeHtml(String(d))
      }));

    const rows = isHeader ? data.slice(1) : data;

    // 初始化 DataTable（在此使用 jQuery）
    $(`#${tabId}-table`).DataTable({
      data: rows,
      columns,
      paging: false,
      searching: false,
      info: false,
      autoWidth: false,
      // 为了兼容大文件，可开启 scrollX/scrollY
      scrollX: true,
      scrollY: '350px',
      scrollCollapse: true,
    });
  });
}

// ---------- 4. HTML 实体转义 ----------
function escapeHtml(str) {
  // 使用浏览器原生 TextNode 方式是最安全、最快的
  const div = document.createElement('div');
  div.appendChild(document.createTextNode(str));
  return div.innerHTML;
}
