## 5️⃣ Code

### `src/config/db.js` – MongoDB connection

```js
// src/config/db.js
const mongoose = require('mongoose');

const connectDB = async () => {
  try {
    const conn = await mongoose.connect(process.env.MONGO_URI, {
      // These options are now defaults in Mongoose 7+ but kept for clarity
      useNewUrlParser: true,
      useUnifiedTopology: true,
    });
    console.log(`MongoDB Connected: ${conn.connection.host}`);
  } catch (err) {
    console.error('MongoDB connection error:', err);
    // Crash the process if DB can't be reached – better than running insecurely
    process.exit(1);
  }
};

module.exports = connectDB;
```

### `src/models/User.js` – Mongoose schema

```js
// src/models/User.js
const mongoose = require('mongoose');
const bcrypt = require('bcryptjs');

const userSchema = new mongoose.Schema(
  {
    email: {
      type: String,
      required: [true, 'Email required'],
      unique: true,
      lowercase: true,
      trim: true,
      match: [
        /^\w+([.-]?\w+)*@\w+([.-]?\w+)*(\.\w{2,3})+$/,
        'Please provide a valid email address',
      ],
    },
    password: {
      type: String,
      required: [true, 'Password required'],
      minlength: [8, 'Password must be at least 8 characters'],
      select: false, // do not return password by default
    },
    // optional fields can go here (e.g., name, role, etc.)
  },
  { timestamps: true }
);

/**
 * Pre‑save hook: hash password if it was modified (or on create)
 */
userSchema.pre('save', async function (next) {
  if (!this.isModified('password')) return next();

  // 12 rounds is a good trade‑off between security & performance
  const salt = await bcrypt.genSalt(12);
  this.password = await bcrypt.hash(this.password, salt);
  next();
});

/**
 * Instance method to compare raw password with stored hash
 */
userSchema.methods.comparePassword = async function (candidatePassword) {
  // Explicitly include the password field (select:false)
  return bcrypt.compare(candidatePassword, this.password);
};

module.exports = mongoose.model('User', userSchema);
```

### `src/utils/generateToken.js` – JWT helper

```js
// src/utils/generateToken.js
const jwt = require('jsonwebtoken');

const generateToken = (payload) => {
  return jwt.sign(payload, process.env.JWT_SECRET, {
    expiresIn: process.env.JWT_EXPIRES_IN || '1h',
  });
};

module.exports = generateToken;
```

### `src/middleware/auth.js` – Protect routes

```js
// src/middleware/auth.js
const jwt = require('jsonwebtoken');
const User = require('../models/User');

/**
 * Express middleware that validates the JWT sent in the
 * Authorization header (Bearer <token>) and attaches the
 * user object to req.user.
 */
const protect = async (req, res, next) => {
  let token;

  // Accept token from Authorization header OR HttpOnly cookie (if you decide to use it)
  if (
    req.headers.authorization &&
    req.headers.authorization.startsWith('Bearer ')
  ) {
    token = req.headers.authorization.split(' ')[1];
  } else if (req.cookies && req.cookies.jwt) {
    token = req.cookies.jwt;
  }

  if (!token) {
    return res.status(401).json({ message: 'Not authorized, token missing' });
  }

  try {
    const decoded = jwt.verify(token, process.env.JWT_SECRET);
    // Attach the full user (excluding password) to request
    req.user = await User.findById(decoded.id).select('-password');
    if (!req.user) {
      return res.status(401).json({ message: 'User no longer exists' });
    }
    next();
  } catch (err) {
    console.warn('JWT verification failed:', err.message);
    return res.status(401).json({ message: 'Not authorized, invalid token' });
  }
};

module.exports = protect;
```

### `src/middleware/rateLimiter.js` – Brute‑force protection

```js
// src/middleware/rateLimiter.js
const rateLimit = require('express-rate-limit');

/**
 * Apply a strict rate limit on authentication endpoints.
 * Adjust "windowMs" and "max" according to your threat model.
 */
const authLimiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 20, // limit each IP to 20 requests per window
  message:
    'Too many login/register attempts from this IP, please try again later.',
  standardHeaders: true, // Return rate limit info in the RateLimit headers
  legacyHeaders: false,
});

module.exports = authLimiter;
```

### `src/routes/auth.js` – Register & Login

```js
// src/routes/auth.js
const express = require('express');
const { body, validationResult } = require('express-validator');
const User = require('../models/User');
const generateToken = require('../utils/generateToken');
const authLimiter = require('../middleware/rateLimiter');

const router = express.Router();

/**
 * @route   POST /api/auth/register
 * @desc    Register a new user
 * @access  Public
 */
router.post(
  '/register',
  authLimiter,
  [
    body('email')
      .isEmail()
      .withMessage('Enter a valid email')
      .normalizeEmail(),
    body('password')
      .isLength({ min: 8 })
      .withMessage('Password must be ≥ 8 chars')
      .matches(/[a-z]/i)
      .withMessage('Password must contain letters')
      .matches(/[0-9]/)
      .withMessage('Password must contain numbers')
      .trim(),
  ],
  async (req, res) => {
    // 1️⃣ Validate input
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      return res.status(400).json({ errors: errors.array() });
    }

    const { email, password } = req.body;

    try {
      // 2️⃣ Check if user exists already
      const existing = await User.findOne({ email });
      if (existing) {
        return res
          .status(409)
          .json({ message: 'User with that email already exists' });
      }

      // 3️⃣ Create user (password will be hashed by pre‑save hook)
      const user = await User.create({ email, password });

      // 4️⃣ Issue JWT
      const token = generateToken({ id: user._id });

      // 5️⃣ Respond (you can set HttpOnly cookie here if desired)
      res.status(201).json({
        token,
        user: {
          id: user._id,
          email: user.email,
          createdAt: user.createdAt,
        },
      });
    } catch (err) {
      console.error('Registration error:', err);
      res.status(500).json({ message: 'Server error' });
    }
  }
);

/**
 * @route   POST /api/auth/login
 * @desc    Authenticate user & return a JWT
 * @access  Public
 */
router.post(
  '/login',
  authLimiter,
  [
    body('email').isEmail().withMessage('Enter a valid email').normalizeEmail(),
    body('password')
      .exists()
      .withMessage('Password is required')
      .trim(),
  ],
  async (req, res) => {
    // 1️⃣ Validation
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      return res.status(400).json({ errors: errors.array() });
    }

    const { email, password } = req.body;

    try {
      // 2️⃣ Find user and explicitly select password field
      const user = await User.findOne({ email }).select('+password');

      // 3️⃣ Generic error to avoid revealing which field is wrong
      const genericError = { message: 'Invalid email or password' };

      if (!user) {
        return res.status(401).json(genericError);
      }

      // 4️⃣ Verify password
      const isMatch = await user.comparePassword(password);
      if (!isMatch) {
        return res.status(401).json(genericError);
      }

      // 5️⃣ Issue JWT
      const token = generateToken({ id: user._id });

      // 6️⃣ Respond (again you could set an HttpOnly cookie)
      res.json({
        token,
        user: {
          id: user._id,
          email: user.email,
          createdAt: user.createdAt,
        },
      });
    } catch (err) {
      console.error('Login error:', err);
      res.status(500).json({ message: 'Server error' });
    }
  }
);

module.exports = router;
```

### `src/server.js` – Main entry point

```js
// src/server.js
require('dotenv').config(); // load .env first
const express = require('express');
const helmet = require('helmet');
const cors = require('cors');
const cookieParser = require('cookie-parser');
const connectDB = require('./config/db');
const authRoutes = require('./routes/auth');

const app = express();

// 1️⃣ Connect to Atlas
connectDB();

// 2️⃣ Global middleware
app.use(helmet()); // security headers
app.use(express.json({ limit: '10kb' })); // limit body size
app.use(cookieParser());

// 3️⃣ CORS – lock it down!
const corsOptions = {
  origin:
    process.env.CORS_ORIGIN ||
    ['http://localhost:3000', 'https://myfrontend.example.com'],
  credentials: true, // if you decide to use HttpOnly cookies
};
app.use(cors(corsOptions));

// 4️⃣ Routes
app.use('/api/auth', authRoutes);

// 5️⃣ Test protected route (example)
const protect = require('./middleware/auth');
app.get('/api/me', protect, (req, res) => {
  res.json({ user: req.user });
});

// 6️⃣ 404 handler
app.use((req, res) => {
  res.status(404).json({ message: 'Route not found' });
});

// 7️⃣ Global error handler (optional, for async throws)
app.use((err, req, res, next) => {
  console.error('Unhandled error:', err);
  res.status(500).json({ message: 'Internal Server Error' });
});

// 8️⃣ Start server
const PORT = process.env.PORT || 5000;
app.listen(PORT, () => console.log(`Server running on :${PORT}`));
```

