## 2.  Render the image immediately, hide the description

Add a small utility that builds the markup for a given key (the `LatLng` object used as a map‑point).

```js
/**
 * Returns a DOM node that contains the image (always visible)
 * and a <span> with the caption (hidden by default).
 */
function buildStationNode(key) {
  const info = stationInfo[key];
  if (!info) return document.createTextNode(""); // safety fallback

  // --- Container ---------------------------------------------------------
  const wrapper = document.createElement("div");
  wrapper.className = "station-wrapper";

  // --- Image -------------------------------------------------------------
  const img = document.createElement("img");
  img.src = info.img;
  img.alt = info.alt;
  img.className = "station-img";
  img.width = 400;                     // keep the same size you used before
  img.style.cursor = "pointer";        // to indicate fullscreen intent
  img.addEventListener("click", () => {
    // Full‑screen on click – still safe because `requestFullscreen` works on the element itself.
    img.requestFullscreen().catch(() => {}); // swallow the promise rejection (user may cancel)
  });
