  // --- Caption (hidden) -------------------------------------------------
  const caption = document.createElement("span");
  // Use `textContent` for pure text; for the link we construct a safe element.
  const link = document.createElement("a");
  link.href = "https://www.getty.edu/art/collection/object/103RJP#full-artwork-details";
  link.target = "_blank";
  link.rel = "noopener";
  link.textContent = "Getty's Collection Online";

  // Assemble the caption – note that we *only* use safe DOM APIs.
  caption.appendChild(document.createTextNode(`${info.caption.split("'")[0]} `));
