// ------------------------------------------------------------
// 1️⃣  Imports & early environment load
// ------------------------------------------------------------
import express from "express";
import cors from "cors";
import helmet from "helmet";
import rateLimit from "express-rate-limit";
import morgan from "morgan";
import axios from "axios";
import { createRequire } from "module";
import Joi from "joi";
import pLimit from "p-limit";
import LRU from "lru-cache";
import dotenv from "dotenv-safe";

dotenv.config(); // will throw if .env or required keys missing

// ------------------------------------------------------------
// 2️⃣  Constants & configuration
// ------------------------------------------------------------
const require = createRequire(import.meta.url);
const PORT = process.env.PORT || 3000;
const API_KEY = process.env.APIKEY; // validated by dotenv-safe
const ALLOWED_ORIGINS = (process.env.CORS_ORIGINS || "").split(",").filter(Boolean);
const MAX_CITIES_PER_REQUEST = Number(process.env.MAX_CITIES) || 20;
const CONCURRENCY = Number(process.env.API_CONCURRENCY) || 5;
const CACHE_TTL_MS = Number(process.env.CACHE_TTL_MS) || 5 * 60 * 1000; // 5 min

// ------------------------------------------------------------
// 3️⃣  Axios client – single instance, defaults baked in
// ------------------------------------------------------------
const weatherClient = axios.create({
  baseURL: "https://open-weather13.p.rapidapi.com",
  timeout: 8000,
  headers: {
    "X-RapidAPI-Key": API_KEY,
    "X-RapidAPI-Host": "open-weather13.p.rapidapi.com",
    Accept: "application/json",
  },
});

// ------------------------------------------------------------
// 4️⃣  In‑memory cache (LRU) – cheap & fast, no external deps
// ------------------------------------------------------------
const cache = new LRU({
  max: 500, // max cached cities
  ttl: CACHE_TTL_MS,
});

// ------------------------------------------------------------
// 5️⃣  Express app boot – security‑first middleware stack
// ------------------------------------------------------------
const app = express();

app.use(helmet()); // security headers
app.use(express.json({ limit: "100kb" })); // body size limit
app.use(
  cors({
    origin: (origin, callback) => {
      // If no origin (e.g., curl / Postman) we still allow for dev, otherwise whitelist
      if (!origin) return callback(null, true);
      if (ALLOWED_ORIGINS.includes(origin)) return callback(null, true);
      return callback(new Error("CORS not allowed for this origin"));
    },
  })
);

// Logging – add request IDs for easier tracing later (optional)
app.use(morgan("combined"));

// Rate limiting – per IP, configurable
const apiLimiter = rateLimit({
  windowMs: 60_000, // 1 minute
  max: Number(process.env.RATE_LIMIT_MAX) || 60, // limit each IP
  standardHeaders: true,
  legacyHeaders: false,
  handler: (_, res) => {
    res.status(429).json({ error: "Too many requests – slow down" });
  },
});
app.use("/weather", apiLimiter);

// ------------------------------------------------------------
// 6️⃣  Validation schema (Joi) – early rejection of bad payloads
// ------------------------------------------------------------
const weatherRequestSchema = Joi.object({
  cities: Joi.array()
    .items(Joi.string().trim().min(1).max(100)) // max 100 chars per city name
    .min(1)
    .max(MAX_CITIES_PER_REQUEST)
    .required(),
});

// ------------------------------------------------------------
// 7️⃣  Helper: fetch a single city (with cache & error resiliency)
// ------------------------------------------------------------
async function fetchCityWeather(city) {
  // 1️⃣  Check cache first
  const cached = cache.get(city.toLowerCase());
  if (cached) return cached;

  try {
    const { data } = await weatherClient.get(`/city/${encodeURIComponent(city)}`);

    const payload = {
      city,
      temperature: data?.main?.temp ?? null,
    };
    // 2️⃣  Save to cache (store shallow copy to avoid accidental mutation)
    cache.set(city.toLowerCase(), payload);
    return payload;
  } catch (err) {
    // ---- Do NOT leak the raw error (could contain API key, stack, etc.) ----
    console.warn(`Weather fetch failed for "${city}": ${err.message}`);
    return {
      city,
      temperature: null,
      error: "unavailable",
    };
  }
}

// ------------------------------------------------------------
// 8️⃣  Route handler – concurrency‑limited, all‑settled response
// ------------------------------------------------------------
app.post("/weather", async (req, res) => {
  // ---- Input validation ----
  const { error, value } = weatherRequestSchema.validate(req.body);
  if (error) {
    return res.status(400).json({ error: error.details[0].message });
  }

  const cities = value.cities;

  // ---- Concurrency limiter (p-limit) ----
  const limit = pLimit(CONCURRENCY);
  const promises = cities.map((city) => limit(() => fetchCityWeather(city)));

  // We want *all* results even if some fail – Promise.allSettled is perfect
  const settled = await Promise.allSettled(promises);

  const results = settled.map((r, idx) => {
    if (r.status === "fulfilled") return r.value;
    // Should never hit this branch because fetchCityWeather catches its own errors,
    // but keep it for safety.
    return {
      city: cities[idx],
      temperature: null,
      error: "internal",
    };
  });

  res.json(results);
});

// ------------------------------------------------------------
// 9️⃣  Global error handling (fallback) – keep secrets out of logs
// ------------------------------------------------------------
app.use((err, _req, res, _next) => {
  // If the error was thrown from async route wrappers, err could be anything
  console.error(`Unexpected error: ${err?.message || err}`);
  res.status(500).json({ error: "Server encountered an unexpected condition" });
});

// ------------------------------------------------------------
// 🔟  Start server & graceful shutdown handling
// ------------------------------------------------------------
const server = app.listen(PORT, () => {
  console.info(`✅ Weather service listening on port ${PORT}`);
});

// Graceful shutdown (SIGINT/SIGTERM)
function shutdown(signal) {
  console.info(`🔌 Received ${signal}. Closing HTTP server...`);
  server.close(() => {
    console.info("🛑 HTTP server closed. Exiting process.");
    process.exit(0);
  });

  // Force shutdown after 10 seconds
  setTimeout(() => {
    console.error("⚠️ Graceful shutdown timed out – force exiting");
    process.exit(1);
  }, 10_000);
}

