```sql
-- 2.1 Table definition (run once)
CREATE TABLE flights (
    id          SERIAL PRIMARY KEY,
    flight_no   TEXT    NOT NULL,
    departure   TIMESTAMP WITH TIME ZONE NOT NULL,
    arrival     TIMESTAMP WITH TIME ZONE NOT NULL,
    gate        TEXT,
    status      TEXT    CHECK (status IN ('Scheduled','Boarding','Departed','Cancelled','Landed')),
    updated_at  TIMESTAMP WITH TIME ZONE DEFAULT now()
);

-- 2.2 Function that fires NOTIFY on any change
CREATE OR REPLACE FUNCTION notify_flight_change() RETURNS trigger AS $$
DECLARE
    payload JSON;
BEGIN
    -- Build a small JSON payload with the primary key of the affected row.
    IF TG_OP = 'DELETE' THEN
        payload = json_build_object('id', OLD.id, 'op', 'DELETE');
    ELSE
        payload = json_build_object('id', NEW.id, 'op', TG_OP);
    END IF;
    PERFORM pg_notify('flight_update', payload::text);
    RETURN NULL; -- AFTER trigger does not modify data
END;
$$ LANGUAGE plpgsql SECURITY DEFINER; -- runs with owner rights, safe because it does not touch external objects

-- 2.3 Attach trigger to the table (AFTER INSERT/UPDATE/DELETE)
CREATE TRIGGER trg_flight_change
AFTER INSERT OR UPDATE OR DELETE ON flights
FOR EACH ROW EXECUTE FUNCTION notify_flight_change();
```

