  // 使用 Babel Traverse 遍历节点
  traverse(ast, {
    // import 声明（包括 `import type`）
    ImportDeclaration(pathNode) {
      const source = pathNode.node.source.value;
      const isTypeOnly = pathNode.node.importKind === 'type' || pathNode.node.importKind === 'typeof';
      if (isTypeOnly) {
        typeOnlyDeps.add(source);
      } else {
        staticDeps.add(source);
      }
    },

    // export ... from 'xxx'
    ExportNamedDeclaration(pathNode) {
      if (pathNode.node.source) {
        // 例如: export { foo } from './mod';
        staticDeps.add(pathNode.node.source.value);
      }
    },

    ExportAllDeclaration(pathNode) {
      // export * from './mod';
      staticDeps.add(pathNode.node.source.value);
    },

    // require('xxx')（CommonJS）
    CallExpression(pathNode) {
      const callee = pathNode.get('callee');
      // 必须是 Identifier 且名字是 require
      if (callee.isIdentifier({ name: 'require' })) {
        const arg = pathNode.get('arguments')[0];
        if (arg && arg.isStringLiteral()) {
          staticDeps.add(arg.node.value);
        }
      }
    },

    // 动态 import()（如果需要收集）
    Import(pathNode) {
      if (!includeDynamic) return;
      const parent = pathNode.parentPath;
      if (parent.isCallExpression()) {
        const arg = parent.get('arguments')[0];
        if (arg && arg.isStringLiteral()) {
          dynamicDeps.add(arg.node.value);
        } else {
          // 非字面量的动态 import，标记为 “runtime”
          dynamicDeps.add('[dynamic]');
        }
      }
    },
  });

  // 标准化相对路径（可选）
  const normalize = (depSet) => {
    const normalized = new Set();
    for (const dep of depSet) {
      // 只对相对路径做 resolve，其他保留原样（如 npm 包名、URL）
      if (dep.startsWith('.') || dep.startsWith('/')) {
        const abs = path.resolve(path.dirname(filePath || ''), dep);
        normalized.add(abs);
      } else {
        normalized.add(dep);
      }
    }
    return normalized;
  };

  return {
    static: normalize(staticDeps),
    dynamic: normalize(dynamicDeps),
    typeOnly: normalize(typeOnlyDeps),
  };
}

/* ---------- 下面是一个简易的 CLI 演示（可选） ---------- */
if (require.main === module) {
  const [, , target] = process.argv;
  if (!target) {
    console.error('Usage: node deps-analyzer.js <path-to-.tsx>');
    process.exit(1);
  }

  try {
    const result = analyzeTsxDependencies({ filePath: target });
    console.log('=== Static dependencies ===');
    console.log([...result.static].sort().join('\n') || '(none)');

    console.log('\n=== Dynamic dependencies ===');
    console.log([...result.dynamic].sort().join('\n') || '(none)');

    console.log('\n=== Type‑only dependencies ===');
    console.log([...result.typeOnly].sort().join('\n') || '(none)');
  } catch (e) {
    console.error('Error:', e.message);
    process.exit(1);
  }
}

/* ---------- 导出供其他模块使用 ---------- */
module.exports = {
  analyzeTsxDependencies,
  readFileSafe,
};
```

### 关键点说明

| 步骤 | 目的 | 关键实现 |
|------|------|----------|
| **读取文件** | 防止读取过大的文件导致 DoS | `fs.statSync` + 大小阈值检查 |
| **Babel 解析** | 将 TSX 代码转成标准 ESTree AST | `@babel/parser` + `plugins: ['typescript', 'jsx', ...]` |
| **AST Traversal** | 把所有导入/导出节点收集到集合 | `@babel/traverse`，分别处理 `ImportDeclaration`, `Export*`, `CallExpression(require)`, `Import`（动态） |
| **类型‑only 区分** | TypeScript 中的 `import type …` 并不会在运行时产生依赖，安全审计时可忽略或单独处理 | `node.importKind === 'type' || 'typeof'` |
| **路径标准化** | 把相对路径转成绝对路径，消除 `../` 造成的混淆 | `path.resolve` |
| **返回结构** | 统一的 Set 集合便于后续过滤、排序、去重 | `{ static, dynamic, typeOnly }` |

