## 4️⃣ 在安全审计流水线中的使用方式

### 4.1 只关心 **可执行** 依赖

```js
const { analyzeTsxDependencies } = require('./deps-analyzer');

function getRuntimeDeps(file) {
  const { static: staticDeps, dynamic: dynamicDeps } = analyzeTsxDependencies({ filePath: file });
  // 合并为唯一列表
  return new Set([...staticDeps, ...dynamicDeps]);
}

// 示例：在 CI 中遍历所有 src/**/*.tsx
const glob = require('glob');
glob('src/**/*.tsx', (err, files) => {
  files.forEach(f => {
    const deps = getRuntimeDeps(f);
    // 检查是否出现禁用模块（如 child_process、eval、fs 等）
    const blackList = ['child_process', 'fs', 'vm'];
    const violations = [...deps].filter(d => blackList.includes(d));
    if (violations.length) {
      console.warn(`[SECURITY] ${f} imports black‑listed modules: ${violations.join(', ')}`);
    }
  });
});
```

### 4.2 生成 **SBOM**（软件材料清单）

```js
const sbom = {};
files.forEach(f => {
  const { static: staticDeps, dynamic: dynamicDeps } = analyzeTsxDependencies({ filePath: f });
  sbom[f] = {
    static: [...staticDeps],
    dynamic: [...dynamicDeps],
  };
});
// 将 sbom 写入 JSON 供 downstream 工具（spdx, cyclonedx）使用
fs.writeFileSync('sbom.json', JSON.stringify(sbom, null, 2));
```

