## 6️⃣ 完整的安全审计示例脚本

下面是一段完整的 **Node.js** 脚本，演示如何对项目根目录下的所有 `.tsx` 文件进行依赖审计，并把 **潜在风险**（导入了 `child_process`、`fs`、`net`、`http`、`https` 等）输出到报告文件：

```js
// audit-project.js
const { analyzeTsxDependencies } = require('./deps-analyzer');
const glob = require('glob');
const fs = require('fs');
const path = require('path');

const PROJECT_ROOT = path.resolve(__dirname, '..'); // 假设脚本放在 scripts/
const GLOB_PATTERN = `${PROJECT_ROOT}/src/**/*.tsx`;

const RISKY_MODULES = new Set([
  'child_process',
  'fs',
  'net',
  'http',
  'https',
  'vm',
  'dns',
  'worker_threads',
]);

const report = [];

glob(GLOB_PATTERN, { ignore: '**/node_modules/**' }, (err, files) => {
  if (err) throw err;

  files.forEach(file => {
    try {
      const { static: staticDeps, dynamic: dynamicDeps } = analyzeTsxDependencies({ filePath: file });
      const allDeps = new Set([...staticDeps, ...dynamicDeps]);

      const risky = [...allDeps].filter(d => RISKY_MODULES.has(d));
      if (risky.length) {
        report.push({
          file: path.relative(PROJECT_ROOT, file),
          risky,
        });
      }
    } catch (e) {
      console.error(`[WARN] Failed to analyze ${file}: ${e.message}`);
    }
  });

  // 输出报告（JSON + 人类可读）
  const outPath = path.join(PROJECT_ROOT, 'security-deps-report.json');
  fs.writeFileSync(outPath, JSON.stringify(report, null, 2));
  console.log(`✅ Report written to ${outPath}`);

  if (report.length) {
    console.warn('\n⚠️ 发现风险依赖:');
    report.forEach(r => {
      console.warn(`- ${r.file}: ${r.risky.join(', ')}`);
    });
  } else {
    console.log('\n✅ 未发现风险依赖！');
  }
});
```

> **运行**  
> ```bash
> node scripts/audit-project.js
> ```
> 生成的 `security-deps-report.json` 可直接喂给 CI 报告或漏洞管理系统（Jira、DefectDojo 等）。

