async function getDb() {
  return open({
    filename: './db/mydb.sqlite',
    driver: sqlite3.Database,
    // В режиме `READONLY` вы повышаете безопасность, если запись не нужна
    // mode: sqlite3.OPEN_READONLY,
  });
}

/**
 * Выполняет запрос и возвращает массив массивов:
 *   [ [col1, col2, …], [col1, col2, …], … ]
 *
 * @param {string} sql   – запрос с плейсхолдерами ?
 * @param {Array}  params – массив параметров (может быть пустым)
 * @returns {Promise<Array<Array<any>>>}
 */
async function fetchMatrix(sql, params = []) {
  const db = await getDb();

  // `all` возвращает массив объектов: [{c1:…, c2:…}, …]
  const rows = await db.all(sql, params);

  if (rows.length === 0) return [];

  // Преобразуем в массив массивов, сохраняем порядок колонок
  const columnNames = Object.keys(rows[0]); // гарантирует порядок, как в запросе
  const matrix = rows.map(row => columnNames.map(col => row[col]));

  return matrix;
