(async () => {
  try {
    await sql.connect({
      user: process.env.DB_USER,
      password: process.env.DB_PASSWORD,
      server: process.env.DB_SERVER,
      database: process.env.DB_NAME,
      options: { encrypt: true, trustServerCertificate: true }
    });

    const result = await sql.query`SELECT TOP 5 name FROM sys.objects`;
    console.log('Result →', result.recordset);
  } catch (err) {
    console.error('DB error:', err);
  } finally {
    await sql.close(); // закрыть пул, если скрипт завершается
  }
})();
```

Запускаете: `node server.js`. Всё будет работать в Node, а в браузере такой код выдаст ошибку `require is not defined`.

