## 2️⃣ Node.js chat server (WebSocket)

### 2.1 `package.json`

```json
{
  "name": "simple-ws-chat",
  "version": "1.0.0",
  "description": "A tiny WebSocket chat server for security‑research demos.",
  "main": "index.js",
  "scripts": {
    "start": "node index.js"
  },
  "author": "Security Researcher",
  "license": "MIT",
  "dependencies": {
    "ws": "^8.14.2"
  }
}
```

> **Why `ws`?** – It’s the most popular, lightweight WebSocket implementation for Node and has a well‑documented API, making it ideal for a short demo.

### 2.2 `index.js`

```js
/**
 * Simple WebSocket Chat Server
 * ---------------------------------
 *  • Listens on a configurable port (default 8080)
 *  • Broadcasts any received text message to all connected clients
 *  • Logs connections/disconnections & raw payloads (useful for fuzzing)
 *  • No authentication – perfect for a security‑research sandbox
 *
 *  Run:  npm install && npm start
 */

const WebSocket = require('ws');
const http = require('http');
const os = require('os');
const process = require('process');

// ----- Configuration --------------------------------------------------------
const PORT = process.env.CHAT_PORT || 8080;

// ----- Helper: simple logger (timestamp + client IP) ------------------------
function log(msg, ws) {
  const now = new Date().toISOString();
  const remote = ws && ws._socket ? ws._socket.remoteAddress : '-';
  console.log(`[${now}] [${remote}] ${msg}`);
}

// ----- Create a plain HTTP server (only to upgrade to WS) --------------------
const server = http.createServer((req, res) => {
  // Quick health‑check endpoint
  if (req.url === '/ping') {
    res.writeHead(200, { 'Content-Type': 'text/plain' });
    res.end('pong');
    return;
  }

  // Any other request gets a 404 – the real work is done via WS
  res.writeHead(404);
  res.end();
});

// ----- Attach WebSocket server -----------------------------------------------
const wss = new WebSocket.Server({ noServer: true });

wss.on('connection', (ws, request) => {
  const ip = request.socket.remoteAddress;
  log('🟢 New client connected', ws);

  // Echo back a welcome message (helps with client‑side debugging)
  ws.send(JSON.stringify({ type: 'system', text: `Welcome! You are ${ip}` }));

  ws.on('message', (data) => {
    // –‑> This is the core “chat” logic ------------------------------------
    try {
      const payload = data.toString(); // raw string (no JSON parsing yet)
      log(`📨 Received raw data: ${payload}`, ws);

      // Broadcast to *all* clients, including the sender
      wss.clients.forEach((client) => {
        if (client.readyState === WebSocket.OPEN) {
          client.send(JSON.stringify({ type: 'chat', from: ip, text: payload }));
        }
      });
    } catch (e) {
      log(`❗ Error handling message: ${e.message}`, ws);
    }
  });

  ws.on('close', (code, reason) => {
    log(`🔴 Client disconnected (code=${code}, reason=${reason})`, ws);
  });

  ws.on('error', (err) => {
    log(`⚠️ WS error: ${err.message}`, ws);
  });
});

// ----- Upgrade HTTP → WebSocket ------------------------------------------------
server.on('upgrade', (request, socket, head) => {
  // Basic sanity check: reject non‑WS upgrades early
  if (request.headers['upgrade'] !== 'websocket') {
    socket.write('HTTP/1.1 400 Bad Request\r\n\r\n');
    socket.destroy();
    return;
  }

  wss.handleUpgrade(request, socket, head, (ws) => {
    wss.emit('connection', ws, request);
  });
});

// ----- Start listening ---------------------------------------------------------
server.listen(PORT, () => {
  const interfaces = os.networkInterfaces();
  console.log(`🚀 Chat server listening on ws://0.0.0.0:${PORT}`);
  console.log('   Health‑check: http://localhost:' + PORT + '/ping');
});
```

#### What this server does

| Feature | Why it matters for a security‑research test |
|---------|---------------------------------------------|
| **Raw text broadcast** | No sanitisation → easy to insert malformed UTF‑8, control characters, or binary payloads for fuzzing. |
| **No authentication** | Perfect for testing authentication bypass, session‑hijacking, or DoS scenarios. |
| **Health‑check endpoint** | Useful when you want to demonstrate a *confused deputy* between HTTP & WS stacks. |
| **Plain HTTP upgrade** | No TLS – you can intercept traffic with tools like `mitmproxy`, `burp`, or Wireshark. |
| **Logging of connection IP & raw payload** | Gives you immediate visibility of what a fuzzer or attacker is sending. |

