## 3️⃣ PowerShell wrapper (`launch.ps1`)

The PowerShell script can:

* **Install Node.js dependencies** (if they aren’t already present).  
* **Start the chat server** in the background.  
* Optionally **run a tiny Node client** that connects, sends a test message, and prints anything it receives.  

```powershell
<# 
.SYNOPSIS
    Launches the simple Node.js WebSocket chat server (and optional test client).

.DESCRIPTION
    * Installs npm packages if needed.
    * Starts `npm start` in a new PowerShell job (so the prompt returns).
    * Optionally runs a tiny client that sends a custom message.
    * Provides a helper function `Stop-ChatServer` to clean up.

.NOTES
    Run this script from the folder that contains `server\package.json`.
    Requires Node.js (>=14) and PowerShell 5+ (or PowerShell Core).

#>

# ------------------------------- Config ------------------------------------
$ServerPort = $env:CHAT_PORT ? [int]$env:CHAT_PORT : 8080
$ServerPath = Join-Path $PSScriptRoot "server"
$ClientMessage = "Hello from PowerShell!"

# -------------------------- Helper Functions ------------------------------
function Install-Dependencies {
    Write-Host "[*] Installing npm deps (if required)..." -ForegroundColor Cyan
    Push-Location $ServerPath
    if (-Not (Test-Path "node_modules")) {
        npm install
    } else {
        Write-Host "    Already installed." -ForegroundColor DarkGray
    }
    Pop-Location
}

function Start-ChatServer {
    Write-Host "[*] Starting chat server on port $ServerPort..." -ForegroundColor Cyan
    Push-Location $ServerPath
    # Start the server as a background job (captures stdout/stderr)
    $job = Start-Job -ScriptBlock {
        param($port)
        $env:CHAT_PORT = $port
        npm start
    } -ArgumentList $ServerPort

    Pop-Location
    Write-Host "    Server Job ID: $($job.Id)" -ForegroundColor Green
    return $job
}

function Start-TestClient {
    param(
        [string]$Message = $ClientMessage
    )

    # A quick inline Node client (no external file needed)
    $clientJs = @"
const WebSocket = require('ws');
const ws = new WebSocket('ws://localhost:$ServerPort');

ws.on('open', () => {
    console.log('🟢 Connected – sending test message...');
    ws.send('$Message');
});
ws.on('message', (data) => {
    console.log('📥 Received:', data.toString());
});
ws.on('close', () => console.log('🔴 Connection closed'));
ws.on('error', (err) => console.error('⚠️ Error:', err));
"@

    # Write the client to a temporary file, run it, then delete it.
    $tmpFile = [IO.Path]::GetTempFileName() + ".js"
    $clientJs | Set-Content -Path $tmpFile -Encoding UTF8
    Write-Host "[*] Running test client..." -ForegroundColor Cyan
    node $tmpFile
    Remove-Item $tmpFile -Force
}

function Stop-ChatServer {
    param(
        [Parameter(Mandatory=$true)]
        [int]$JobId
    )
    Write-Host "[*] Stopping chat server (Job ID $JobId)..." -ForegroundColor Yellow
    Stop-Job -Id $JobId -Force
    Remove-Job -Id $JobId
}

# ------------------------------ Execution ---------------------------------
Install-Dependencies

# 1️⃣ Start server (background)
$serverJob = Start-ChatServer

# Small pause to give the server time to bind before the client runs
Start-Sleep -Seconds 2

# 2️⃣ Run optional test client (comment out if you just want the server)
Start-TestClient

Write-Host "`nServer is now running. Use `Stop-ChatServer -JobId $($serverJob.Id)` to kill it." -ForegroundColor Magenta
```

### How to run it

```powershell
