  baseURL: import.meta.env.VITE_API_URL,
  withCredentials: true,          // Include HttpOnly cookies automatically
  headers: {
    'Content-Type': 'application/json',
  },
});

/**
 * Log the user in.
 * @returns the server‐generated user profile (if any)
 */
export const login = async (email: string, password: string) => {
  const { data } = await api.post('/auth/login', { email, password });
  return data; // e.g., { user: {...} }
};

/**
 * Register a new account.
 */
export const signup = async (
  name: string,
  email: string,
  password: string
) => {
  const { data } = await api.post('/auth/register', {
    name,
    email,
    password,
  });
  return data;
};
```

> **Why Axios?**  
> * Built‑in JSON handling, timeout defaults, and easy interception for logging or adding future headers (e.g., request IDs).  
> * `withCredentials: true` ensures the **HttpOnly** JWT cookie sent by the server is automatically attached to every request.

