## 6. Shared UI component (`src/components/AuthForm.tsx`)

```tsx
// src/components/AuthForm.tsx
import {
  SubmitHandler,
  useForm,
  FieldValues,
} from 'react-hook-form';
import { yupResolver } from '@hookform/resolvers/yup';
import * as yup from 'yup';
import { ReactNode, useEffect, useRef } from 'react';
import LoadingSpinner from './LoadingSpinner';

export interface AuthFormProps<T extends FieldValues> {
  /** Title displayed above the form */
  title: string;
  /** Submit button text */
  submitLabel: string;
  /** Yup schema for validation */
  schema: yup.ObjectSchema<any>;
  /** onSubmit handler – receives validated data */
  onSubmit: SubmitHandler<T>;
  /** Optional children (e.g., “Already have an account?” link) */
  footer?: ReactNode;
}

/**
 * A generic, fully‑styled, accessible form component.
 *
 * Usage:
 *   <AuthForm<any> title="Sign up" schema={signupSchema}
 *                onSubmit={handleSignup} submitLabel="Create account"
 *                footer={<Link to="/login">Log in</Link>} />
 */
export default function AuthForm<T extends FieldValues>({
  title,
  submitLabel,
  schema,
  onSubmit,
  footer,
}: AuthFormProps<T>) {
  const {
    register,
    handleSubmit,
    formState: { errors, isSubmitting, isValid },
    setFocus,
  } = useForm<T>({
    resolver: yupResolver(schema),
    mode: 'onChange',
  });

  const firstErrorRef = useRef<HTMLDivElement>(null);

  // Focus on the first field with an error for better a11y
  useEffect(() => {
    if (Object.keys(errors).length > 0) {
      const firstKey = Object.keys(errors)[0];
      setFocus(firstKey as any);
    }
  }, [errors, setFocus]);

  // When a server‑side error occurs (e.g., 401), you can set a custom error key.
  // See the Login/Signup pages for an example.

  return (
    <section className="max-w-md mx-auto p-6 bg-white rounded-lg shadow-md">
      <h1 className="text-2xl font-bold text-center mb-6">{title}</h1>

      <form
        onSubmit={handleSubmit(onSubmit)}
        noValidate
        aria-describedby="form-errors"
      >
        {/* Children fields are injected by the specific page component */}
        {/* Example in pages/Login.tsx / pages/Signup.tsx */}
        {/** Render children via `cloneElement` in the pages – see below **/}
        {/** Or you can extract the fields into a sub‑component **/}
        {/* Placeholder – the page will render its own fields inside this component */}
        {/* @ts-ignore */}
        {/** The page spreads `register` into each input **/}
      </form>

      {/* Footer links (e.g., "Already have an account?") */}
      {footer && <div className="mt-4 text-center">{footer}</div>}
    </section>
  );
}
```

> **Explanation**  
> * The component is **generic** (`<T>`), so each page can provide its own strongly‑typed fields.  
> * Validation is performed **client‑side** by `yup`. Errors are displayed immediately.  
> * The form disables the submit button while submitting (`isSubmitting`).  
> * A small loading spinner replaces the label during the request.  

