## 8. Login page (`src/pages/Login.tsx`)

```tsx
// src/pages/Login.tsx
import { Link, useNavigate } from 'react-router-dom';
import { useForm, SubmitHandler } from 'react-hook-form';
import { yupResolver } from '@hookform/resolvers/yup';
import * as yup from 'yup';
import { login } from '../api/auth';
import LoadingSpinner from '../components/LoadingSpinner';
import { useEffect, useState } from 'react';
import useAuthRedirect from '../hooks/useAuthRedirect';

interface LoginForm {
  email: string;
  password: string;
}

/* Strong password rule is not required for login, but we make sure
   the field is non‑empty */
const loginSchema = yup.object({
  email: yup
    .string()
    .email('Please enter a valid email address')
    .required('Email is required'),
  password: yup.string().required('Password is required'),
});

export default function Login() {
  const navigate = useNavigate();
  const { register, handleSubmit, formState, setError } = useForm<LoginForm>({
    resolver: yupResolver(loginSchema),
    mode: 'onSubmit',
  });
  const [serverError, setServerError] = useState<string | null>(null);
  const { isAuthenticated } = useAuthRedirect();

  // If user is already authenticated, redirect away from login
  useEffect(() => {
    if (isAuthenticated) navigate('/');
  }, [isAuthenticated, navigate]);

  const onSubmit: SubmitHandler<LoginForm> = async (data) => {
    try {
      setServerError(null);
      await login(data.email, data.password);
      // Successful login – server should set HttpOnly cookie.
      // Redirect to the secured area.
      navigate('/');
    } catch (err: any) {
      // Centralised error handling – do **not** expose raw server messages.
      if (axios.isAxiosError(err) && err.response) {
        const status = err.response.status;
        if (status === 401) {
          setServerError('Invalid email or password');
        } else {
          setServerError('Something went wrong. Please try again later.');
        }
      } else {
        setServerError('Network error – check your connection.');
      }
    }
  };

  return (
    <section className="max-w-md mx-auto mt-20 p-6 bg-white rounded-lg shadow-md">
      <h1 className="text-2xl font-bold text-center mb-4">Log in</h1>

      {/* Server‑side error banner */}
      {serverError && (
        <div
          role="alert"
          className="bg-red-100 border border-red-400 text-red-700 p-2 rounded mb-4"
        >
          {serverError}
        </div>
      )}

      <form onSubmit={handleSubmit(onSubmit)} noValidate>
        <div className="mb-4">
          <label htmlFor="email" className="block font-medium mb-1">
            Email
          </label>
          <input
            id="email"
            type="email"
            {...register('email')}
            className={`w-full border rounded px-3 py-2 focus:outline-none focus:ring-2 ${
              formState.errors.email
                ? 'border-red-500 focus:ring-red-200'
                : 'border-gray-300 focus:ring-indigo-200'
            }`}
            autoComplete="email"
            aria-invalid={!!formState.errors.email}
            aria-describedby={formState.errors.email ? 'email-error' : undefined}
          />
          {formState.errors.email && (
            <p
              id="email-error"
              className="text-sm text-red-600 mt-1"
              role="alert"
            >
              {formState.errors.email.message}
            </p>
          )}
        </div>

        <div className="mb-4">
          <label htmlFor="password" className="block font-medium mb-1">
            Password
          </label>
          <input
            id="password"
            type="password"
            {...register('password')}
            className={`w-full border rounded px-3 py-2 focus:outline-none focus:ring-2 ${
              formState.errors.password
                ? 'border-red-500 focus:ring-red-200'
                : 'border-gray-300 focus:ring-indigo-200'
            }`}
            autoComplete="current-password"
            aria-invalid={!!formState.errors.password}
            aria-describedby={formState.errors.password ? 'password-error' : undefined}
          />
          {formState.errors.password && (
            <p
              id="password-error"
              className="text-sm text-red-600 mt-1"
              role="alert"
            >
              {formState.errors.password.message}
            </p>
          )}
        </div>

        <button
          type="submit"
          disabled={formState.isSubmitting}
          className="w-full flex items-center justify-center bg-indigo-600 text-white font-medium py-2 px-4 rounded hover:bg-indigo-700 disabled:opacity-50"
        >
          {formState.isSubmitting ? (
            <>
              <LoadingSpinner /> <span className="ml-2">Logging in…</span>
            </>
          ) : (
            'Log in'
          )}
        </button>
      </form>

      <p className="mt-4 text-center">
        Don’t have an account?{' '}
        <Link to="/signup" className="text-indigo-600 hover:underline">
          Sign up
        </Link>
      </p>
    </section>
  );
}
```

### Key Security‑focused bits

* **`withCredentials: true`** in the Axios instance makes the **HttpOnly** cookie automatically sent back.
* **Server errors** are **sanitized** – we never render raw messages.
* **ARIA attributes** (`aria-invalid`, `role="alert"`) let screen readers announce validation problems instantly.
* **`autoComplete`** attributes help browsers fill credentials securely (avoid `autocomplete="off"` unless you have a compelling reason).

