## 11. Routing (`src/App.tsx`)

```tsx
// src/App.tsx
import { BrowserRouter as Router, Routes, Route, Navigate } from 'react-router-dom';
import Login from './pages/Login';
import Signup from './pages/Signup';
import Dashboard from './pages/Dashboard'; // placeholder for a protected home page
import useAuthRedirect from './hooks/useAuthRedirect';
import { useEffect } from 'react';

function PrivateRoute({ children }: { children: JSX.Element }) {
  const { isAuthenticated, checked } = useAuthRedirect();

  // While we’re still checking auth status, keep UI blank (or show a spinner)
  if (!checked) return null;

  return isAuthenticated ? children : <Navigate to="/login" replace />;
}

export default function App() {
  return (
    <Router>
      <Routes>
        <Route path="/login" element={<Login />} />
        <Route path="/signup" element={<Signup />} />
        {/* Protected area */}
        <Route
          path="/"
          element={
            <PrivateRoute>
              {/* Replace with your real dashboard component */}
              <Dashboard />
            </PrivateRoute>
          }
        />
        {/* Catch‑all 404 */}
        <Route path="*" element={<Navigate to="/" replace />} />
      </Routes>
    </Router>
  );
}
