## 13. Full source snippet (for quick copy‑paste)

Below is a **single‑file** version that you can drop into a fresh Vite React project to get the login+signup UI up and running instantly. It omits the hook and dashboard for brevity but retains all security‑related patterns.

```tsx
// src/main.tsx
import React from 'react';
import ReactDOM from 'react-dom/client';
import {
  BrowserRouter as Router,
  Routes,
  Route,
  Navigate,
  Link,
  useNavigate,
} from 'react-router-dom';
import { useForm, SubmitHandler } from 'react-hook-form';
import { yupResolver } from '@hookform/resolvers/yup';
import * as yup from 'yup';
import axios from 'axios';
import './index.css';
import LoadingSpinner from './components/LoadingSpinner';

axios.defaults.baseURL = import.meta.env.VITE_API_URL;
axios.defaults.withCredentials = true;

// ---------- API ----------
const api = {
  login: (email: string, password: string) =>
    axios.post('/auth/login', { email, password }).then((r) => r.data),
  signup: (name: string, email: string, password: string) =>
    axios.post('/auth/register', { name, email, password }).then((r) => r.data),
};

// ---------- Forms ----------
type LoginForm = { email: string; password: string };
type SignupForm = {
  name: string;
  email: string;
  password: string;
  confirmPassword: string;
};

const loginSchema = yup.object({
  email: yup.string().email().required(),
  password: yup.string().required(),
});

const passwordRegex =
  /^(?=.*[a-z])(?=.*[A-Z])(?=.*\d)(?=.*[!@#$%^&*])[\S]{12,}$/;
const signupSchema = yup.object({
  name: yup.string().trim().required(),
  email: yup.string().email().required(),
  password: yup
    .string()
    .matches(
      passwordRegex,
      '12+ chars, upper/lower, number, special (!@#$…) required'
    )
    .required(),
  confirmPassword: yup
    .string()
    .oneOf([yup.ref('password'), null], 'Passwords must match')
    .required(),
});

// ---------- Login page ----------
function Login() {
  const navigate = useNavigate();
  const [serverError, setServerError] = React.useState<string | null>(null);
  const {
    register,
    handleSubmit,
    formState: { errors, isSubmitting },
  } = useForm<LoginForm>({
    resolver: yupResolver(loginSchema),
  });

  const onSubmit: SubmitHandler<LoginForm> = async (data) => {
    try {
      setServerError(null);
      await api.login(data.email, data.password);
      navigate('/');
    } catch (e: any) {
      if (axios.isAxiosError(e) && e.response?.status === 401) {
        setServerError('Invalid email or password');
      } else {
        setServerError('Login failed – try again later');
      }
    }
  };

  return (
    <section className="max-w-md mx-auto mt-20 p-6 bg-white rounded shadow">
      <h1 className="text-2xl font-bold text-center mb-4">Log in</h1>
      {serverError && (
        <div className="bg-red-100 text-red-700 p-2 rounded mb-4">{serverError}</div>
