router.post(
  '/chat',
  authMiddleware,
  rateLimiter,
  validatePrompt,
  async (req, res, next) => {
    try {
      const { model, messages, temperature, max_tokens } = req.body;

      logger.info({
        user: req.user.sub,
        model,
        msgCount: messages.length,
        // **Nunca registre o conteúdo completo do prompt em produção**,
        // a menos que seja estritamente necessário e devidamente criptografado.
      });

      const response = await openai.createChatCompletion({
        model,
        messages,
        temperature,
        max_tokens,
      });

      // Encaminha apenas a parte útil.
      const answer = response.data.choices?.[0]?.message?.content?.trim() ?? '';

      res.json({
        id: response.data.id,
        object: response.data.object,
        created: response.data.created,
        model: response.data.model,
        usage: response.data.usage,
        answer,
      });
    } catch (err) {
      // Tratamento de erros da OpenAI (ex.: limites, bad request)
      if (err.response) {
        logger.warn('OpenAI error', {
          status: err.response.status,
          data: err.response.data,
        });
        return res.status(err.response.status).json({
          error: err.response.data?.error?.message ?? 'OpenAI request failed',
        });
      }
      next(err);
    }
  }
);

module.exports = router;
```

