/* utils.js – small helper functions used across the site */

/**
 * Escape HTML characters – prevents XSS when injecting data into the DOM.
 * @param {string} str
 * @returns {string}
 */
export function escHTML(str) {
    return String(str).replace(/[&<>"'`=\/]/g, function (s) {
        return ({
            '&': '&amp;',
            '<': '&lt;',
            '>': '&gt;',
            '"': '&quot;',
            "'": '&#39;',
            '`': '&#x60;',
            '=': '&#x3D;',
            '/': '&#x2F;'
        })[s];
    });
}

/**
 * Load JSON data via fetch (works on static hosts too).
 * @param {string} url
 * @returns {Promise<any>}
 */
export async function loadJSON(url) {
    const resp = await fetch(url, {cache: "no-store"});
    if (!resp.ok) throw new Error(`Failed to load ${url}: ${resp.status}`);
    return resp.json();
}

/**
 * Convert rating (0‑5) into star icons.
 * @param {number} rating
 * @returns {string} HTML string
 */
export function ratingStars(rating) {
    const full = Math.floor(rating);
    const half = rating - full >= 0.5 ? 1 : 0;
    const empty = 5 - full - half;
    return [
        "★".repeat(full),
        half ? "⭑" : "",
        "☆".repeat(empty)
    ].join("");
}
```

