// catalog.js – builds the grid of cards and handles search filtering.
import { loadJSON, escHTML, ratingStars } from "./utils.js";

const catalogEl = document.getElementById("catalog");
const searchEl   = document.getElementById("searchBar");
let allItems = [];

// --------------------------------------------------------------------
// Render a single card
function renderCard(item) {
    const card = document.createElement("article");
    card.className = "card";

    // card link – goes to item.html?id=<id>
    const link = document.createElement("a");
    link.href = `item.html?id=${encodeURIComponent(item.id)}`;
    link.title = escHTML(item.name);
    link.setAttribute("aria-label", `View details for ${item.name}`);

    // image (fallback to placeholder if none)
    const img = document.createElement("img");
    img.src = item.images?.[0] ?? "https://via.placeholder.com/400x300?text=No+Image";
    img.alt = escHTML(item.name);
    link.appendChild(img);
    card.appendChild(link);

    const info = document.createElement("div");
    info.className = "info";

    const title = document.createElement("h3");
    title.textContent = escHTML(item.name);
    info.appendChild(title);

    const price = document.createElement("p");
    price.className = "price";
    price.textContent = `$${item.price.toFixed(2)}`;
    info.appendChild(price);

    const rating = document.createElement("p");
    rating.className = "rating";
    rating.innerHTML = ratingStars(item.rating) + ` (${item.rating.toFixed(1)})`;
    info.appendChild(rating);

    card.appendChild(info);
    catalogEl.appendChild(card);
}

// --------------------------------------------------------------------
// Render the whole list (used after filtering)
function renderList(list) {
    catalogEl.innerHTML = "";
    if (list.length === 0) {
        catalogEl.innerHTML = "<p>No equipment matches your search.</p>";
        return;
    }
    list.forEach(renderCard);
}

// --------------------------------------------------------------------
// Search handler – case‑insensitive match on name or description
function applySearch() {
    const term = searchEl.value.trim().toLowerCase();
    if (!term) {
        renderList(allItems);
        return;
    }
    const filtered = allItems.filter(item =>
        item.name.toLowerCase().includes(term) ||
        (item.description && item.description.toLowerCase().includes(term))
    );
    renderList(filtered);
}

// --------------------------------------------------------------------
(async function init() {
    try {
        allItems = await loadJSON("assets/data/equipment.json");
        renderList(allItems);
    } catch (e) {
        catalogEl.innerHTML = `<p class="error">❗ Unable to load catalog – ${e.message}</p>`;
        console.error(e);
    }

    // debounce search (200 ms)
    let timeout;
    searchEl.addEventListener("input", () => {
        clearTimeout(timeout);
        timeout = setTimeout(applySearch, 200);
    });
})();
```

