// item.js – builds the detailed view for a single product and handles the reservation form.
import { loadJSON, escHTML, ratingStars } from "./utils.js";

const container = document.getElementById("detailContainer");

// --------------------------------------------------------------------
// Helper – get query param
function getParam(name) {
    const url = new URL(window.location.href);
    return url.searchParams.get(name);
}

// --------------------------------------------------------------------
function renderMedia(item) {
    // Main media (first image)
    const main = document.createElement("img");
    main.src = item.images?.[0] ?? "https://via.placeholder.com/800x450?text=No+Image";
    main.alt = escHTML(item.name);
    main.className = "main-media";
    container.appendChild(main);

    // Gallery thumbnails (click to replace main image)
    if (item.images && item.images.length > 1) {
        const gallery = document.createElement("div");
        gallery.className = "gallery";

        item.images.forEach(src => {
            const thumb = document.createElement("img");
            thumb.src = src;
            thumb.alt = escHTML(item.name);
            thumb.addEventListener("click", () => {
                main.src = src;
            });
            gallery.appendChild(thumb);
        });
        container.appendChild(gallery);
    }

    // Embedded video if present
    if (item.video) {
        const iframe = document.createElement("iframe");
        iframe.src = item.video;
        iframe.width = "100%";
        iframe.height = "400";
        iframe.allow = "accelerometer; autoplay; encrypted-media; gyroscope; picture-in-picture";
        iframe.allowFullscreen = true;
        iframe.title = `${item.name} video`;
        container.appendChild(iframe);
    }
}

// --------------------------------------------------------------------
function renderInfo(item) {
    const title = document.createElement("h2");
    title.textContent = escHTML(item.name);
    container.appendChild(title);

    const rating = document.createElement("p");
    rating.innerHTML = ratingStars(item.rating) + ` (${item.rating.toFixed(1)})`;
    container.appendChild(rating);

    const price = document.createElement("p");
    price.className = "price";
    price.textContent = `$${item.price.toFixed(2)}`;
    container.appendChild(price);

    const desc = document.createElement("p");
    desc.textContent = escHTML(item.description);
    container.appendChild(desc);

    // Features list
    if (item.features && item.features.length) {
        const featTitle = document.createElement("h3");
        featTitle.textContent = "Features";
        container.appendChild(featTitle);

        const ul = document.createElement("ul");
        item.features.forEach(f => {
            const li = document.createElement("li");
            li.textContent = escHTML(f);
            ul.appendChild(li);
        });
        container.appendChild(ul);
    }
}

// --------------------------------------------------------------------
function renderReservationForm(item) {
    const form = document.createElement("form");
    form.id = "reserveForm";
    form.innerHTML = `
        <h3>Reserve this item</h3>
        <label for="name">Your name</label>
        <input type="text" id="name" name="name" required placeholder="John Doe">

        <label for="email">Email address</label>
        <input type="email" id="email" name="email" required placeholder="you@example.com">

        <label for="date">Preferred reservation date</label>
        <input type="date" id="date" name="date" required>

        <label for="notes">Additional notes (optional)</label>
        <textarea id="notes" name="notes" rows="3" placeholder="e.g. preferred delivery time"></textarea>

        <button type="submit">Reserve now</button>
        <p id="msg" role="alert" aria-live="polite"></p>
    `;
    container.appendChild(form);

    // ----------------------------------------------------------------
    form.addEventListener("submit", ev => {
        ev.preventDefault();
        const data = {
            id: item.id,
            name: form.name.value.trim(),
            email: form.email.value.trim(),
            date: form.date.value,
            notes: form.notes.value.trim(),
            timestamp: new Date().toISOString()
        };

        // Basic validation (the HTML already does it but we double‑check)
        if (!data.name || !data.email || !data.date) {
            showMsg("Please fill in all required fields.", true);
            return;
        }

        // Store reservation in localStorage (simple “backend”) keyed by item id
        const key = `reservation-${item.id}`;
        const existing = JSON.parse(localStorage.getItem(key) || "[]");
        existing.push(data);
        localStorage.setItem(key, JSON.stringify(existing));

        showMsg("✅ Reservation saved! We'll email you shortly.", false);
        form.reset();
    });

    // ----------------------------------------------------------------
    function showMsg(txt, isError) {
        const p = form.querySelector("#msg");
        p.textContent = txt;
        p.style.color = isError ? "red" : "green";
    }
}

// --------------------------------------------------------------------
(async function init() {
    const id = getParam("id");
    if (!id) {
        container.innerHTML = "<p class='error'>❗ No product ID supplied.</p>";
        return;
    }

    try {
        const items = await loadJSON("assets/data/equipment.json");
        const item = items.find(i => i.id === id);
        if (!item) {
            container.innerHTML = `<p class='error'>❗ Product with ID “${escHTML(id)}” not found.</p>`;
            return;
        }

        // Build page sections
        renderMedia(item);
        renderInfo(item);
        renderReservationForm(item);
    } catch (e) {
        container.innerHTML = `<p class='error'>❗ Failed to load data – ${e.message}</p>`;
        console.error(e);
    }
})();
