Some pages freeze the `WebSocket` prototype (e.g., via CSP “script‑src ‘nonce‑…’” or Object‑freeze). In that case you can replace the constructor with a *factory* that returns a `Proxy` around the native socket:

```js
(() => {
  const NativeWS = window.WebSocket;

  window.WebSocket = function (url, protocols) {
    const socket = new NativeWS(url, protocols);

    // Incoming interceptor (proxy `onmessage`)
    socket.addEventListener('message', ev => {
      console.log('[WS ⬇] proxy:', ev.data);
    });

    // Outgoing interceptor (wrap `send`)
    const origSend = socket.send;
    socket.send = function (data) {
      console.log('[WS ⬆] proxy:', data);
      // You could modify `data` here
      return origSend.call(this, data);
    };

    // Return a proxy that forwards everything that we didn't touch
    return new Proxy(socket, {
      get(target, prop) {
        const v = Reflect.get(target, prop);
        // Bind functions so `this` stays the socket
        return typeof v === 'function' ? v.bind(target) : v;
      },
      set(target, prop, value) {
        return Reflect.set(target, prop, value);
      }
    });
  };

  // Preserve useful static members (e.g., WebSocket.CLOSING)
  Object.assign(window.WebSocket, NativeWS);
})();
```

**Key points**

* The outer IIFE runs *immediately* (ideally as a userscript or early‑injected script).  
* By copying static members (`CLOSING`, `CLOSED`, etc.) we keep the API intact for code that checks those constants.  
* The `Proxy` approach works even when you can’t `extend` the native class (some older browsers don’t allow subclassing built‑ins).

