// walk.ts
import { Project, ts, Node } from "ts-morph";
import * as path from "path";
import * as fs from "fs";

/**
 * Helper – Load a ts‑morph Project from a directory (or a tsconfig.json).
 *
 * @param entryPath   Path to either a folder containing .ts/.tsx files or a tsconfig.json
 * @param opts        Optional ts‑morph/TS compiler options (e.g. for custom lib files)
 * @returns           A fully‑initialized Project instance
 */
function loadProject(entryPath: string, opts?: { tsConfigFilePath?: string }) {
  // Resolve the absolute entry path
  const resolved = path.resolve(entryPath);
  const isTsConfig = resolved.endsWith(".json") && fs.existsSync(resolved);

  // -------------------------------------------------------------------------
  // 1️⃣ Create the Project
  // -------------------------------------------------------------------------
  const project = new Project({
    // If we have a tsconfig, let ts‑morph read it automatically
    tsConfigFilePath: isTsConfig ? resolved : undefined,
    // Otherwise fall back to a simple glob pattern (covers a folder tree)
    skipAddingFilesFromTsConfig: !isTsConfig,
    // You can enforce strict compilation settings here – helps catch malformed code early
    compilerOptions: {
      target: ts.ScriptTarget.ESNext,
      module: ts.ModuleKind.CommonJS,
      allowJs: true,
      checkJs: false,
      // Turn on source‑map generation only if you need it for debugging
      sourceMap: false,
      // Prevent accidental access to the file system from the compiled code
      noEmitOnError: true,
      ...opts?.tsConfigFilePath ? {} : { // extra defaults for the "no‑tsconfig" case
        outDir: "tmp-ignored", // dummy output folder – we never emit
      },
    },
    // Limit the amount of memory the TypeScript language service can use
    // (this helps mitigate DoS attacks on huge projects)
    manipulationSettings: {
      // 2 × `default` is usually enough for most projects, but feel free to tune
      indentationText: ts.IndentationText.TwoSpaces,
    },
  });

  // -------------------------------------------------------------------------
  // 2️⃣ Add source files (if we didn't load a tsconfig.json)
  // -------------------------------------------------------------------------
  if (!isTsConfig) {
    // Add **all** .ts / .tsx / .js files under the folder (recursively)
    project.addSourceFilesAtPaths(`${resolved}/**/*.{ts,tsx,js,jsx}`);
  }

  // -------------------------------------------------------------------------
  // 3️⃣ Resolve the project (type‑check, diagnostics, etc.)
  // -------------------------------------------------------------------------
  const diagnostics = project.getPreEmitDiagnostics();
  if (diagnostics.length) {
    console.warn("⚠️  Project has TypeScript diagnostics:");
    console.warn(project.formatDiagnosticsWithColorAndContext(diagnostics));
    // Depending on your threat model, you may decide to abort here.
  }

  return project;
}

