import timezone from 'dayjs/plugin/timezone.js';

dayjs.extend(utc);
dayjs.extend(timezone);

/**
 * Returns the current hour **in UTC**, as an integer (0‑23).
 */
export function utcHour() {
  return dayjs().utc().hour();
}

/**
 * Returns a formatted string of the current moment in the user‑provided timezone.
 * @param {string} tz IANA timezone, e.g. "America/New_York"
 * @returns {string}
 */
export function nowInTimezone(tz) {
  return dayjs().tz(tz).format('DD/MM # hh:mm A');
}
