Poniżej znajdziesz kompletny, gotowy do uruchomienia kod, który wykorzystuje wbudowany moduł **`crypto`** do szyfrowania i odszyfrowywania dowolnych plików przy pomocy algorytmu **AES‑256‑CBC**.  
Skrypt działa w trybie linii poleceń:

```
node cryptofile.js encrypt  <ścieżka-do-pliku> <hasło>
node cryptofile.js decrypt  <ścieżka-do-pliku> <hasło>
```

> **Uwaga:**  Hasło jest przetwarzane na klucz (32 bajty) przy pomocy PBKDF2.  Nie zapisuj go w kodzie – podawaj je w momencie wywołania lub wczytuj ze zmiennej środowiskowej / menedżera sekretów.

---

## 1. Pełny kod (`cryptofile.js`)

```js
#!/usr/bin/env node
/**
 * cryptofile.js
 * ----------
 * Prosty skrypt do szyfrowania i odszyfrowywania plików w Node.js.
 * Algorytm: AES‑256‑CBC (klucz 256 bit, wektor inicjalizujący 128 bit).
 *
 * Użycie:
 *   node cryptofile.js encrypt  <inputFile> <password>
 *   node cryptofile.js decrypt  <inputFile> <password>
 *
 * Po zaszyfrowaniu powstaje plik <inputFile>.enc,
 * po odszyfrowaniu – <inputFile>.dec (lub bez rozszerzenia, jeśli podano plik .enc).
 */

const crypto = require('crypto');
const fs = require('fs');
const path = require('path');

// ---------- Konfiguracja ----------
const ALGORITHM = 'aes-256-cbc';          // Algorytm symetryczny
const KEY_LEN   = 32;                     // 256 bit
const IV_LEN    = 16;                     // 128 bit
const SALT_LEN  = 16;                     // 128 bit
const PBKDF2_ITER = 100_000;              // liczba iteracji PBKDF2
const DIGEST    = 'sha256';               // skrót używany w PBKDF2
// -----------------------------------

// Generuje losowy bufor o podanej długości
function randomBytes(len) {
    return crypto.randomBytes(len);
}

// Derive key from password + salt
function deriveKey(password, salt) {
    return crypto.pbkdf2Sync(password, salt, PBKDF2_ITER, KEY_LEN, DIGEST);
}

// Szyfruje bufor danych i zwraca Buffer:  SALT || IV || CIPHERTEXT
function encryptBuffer(dataBuf, password) {
    const salt = randomBytes(SALT_LEN);
    const key  = deriveKey(password, salt);
    const iv   = randomBytes(IV_LEN);

    const cipher = crypto.createCipheriv(ALGORITHM, key, iv);
    const encrypted = Buffer.concat([cipher.update(dataBuf), cipher.final()]);

    // struktura wyjścia: <salt><iv><ciphertext>
    return Buffer.concat([salt, iv, encrypted]);
}

// Odszyfrowuje bufor w formacie SALT||IV||CIPHERTEXT
function decryptBuffer(encBuf, password) {
    if (encBuf.length < SALT_LEN + IV_LEN) {
        throw new Error('Zbyt krótki bufor – brak danych SALT/IV.');
    }
    const salt = encBuf.slice(0, SALT_LEN);
    const iv   = encBuf.slice(SALT_LEN, SALT_LEN + IV_LEN);
    const ciphertext = encBuf.slice(SALT_LEN + IV_LEN);

    const key = deriveKey(password, salt);
    const decipher = crypto.createDecipheriv(ALGORITHM, key, iv);
    const decrypted = Buffer.concat([decipher.update(ciphertext), decipher.final()]);
    return decrypted;
}

// ---------- Obsługa plików ----------
function encryptFile(inPath, password) {
    const data = fs.readFileSync(inPath);
    const encrypted = encryptBuffer(data, password);
    const outPath = `${inPath}.enc`;
    fs.writeFileSync(outPath, encrypted);
    console.log(`✅ Zaszyfrowano → ${outPath}`);
}

function decryptFile(inPath, password) {
    const encData = fs.readFileSync(inPath);
    const decrypted = decryptBuffer(encData, password);

    // Usuwamy ".enc" jeśli istnieje, w przeciwnym wypadku dodajemy ".dec"
    let outPath;
    if (inPath.endsWith('.enc')) {
        outPath = inPath.slice(0, -4);               // usuń ".enc"
    } else {
        outPath = `${inPath}.dec`;
    }
    fs.writeFileSync(outPath, decrypted);
    console.log(`✅ Odszyfrowano → ${outPath}`);
}

// ---------- CLI ----------
function printHelp() {
    console.log(`
Użycie:
  node cryptofile.js encrypt <plik> <hasło>
  node cryptofile.js decrypt <plik> <hasło>

Przykłady:
  node cryptofile.js encrypt plik.js mySecretPassword
  node cryptofile.js decrypt plik.js.enc mySecretPassword
`);
}

function main() {
    const [, , command, filePath, password] = process.argv;

    if (!command || !filePath || !password) {
        printHelp();
        process.exit(1);
    }

    if (!fs.existsSync(filePath)) {
        console.error(`❌ Plik nie istnieje: ${filePath}`);
        process.exit(1);
    }

    try {
        if (command === 'encrypt') {
            encryptFile(filePath, password);
        } else if (command === 'decrypt') {
            decryptFile(filePath, password);
        } else {
            console.error(`❌ Nieznane polecenie: ${command}`);
            printHelp();
            process.exit(1);
        }
    } catch (err) {
        console.error(`❌ Błąd: ${err.message}`);
        process.exit(1);
    }
}

// Uruchom, jeśli skrypt jest wywołany bezpośrednio
if (require.main === module) {
    main();
}
```

---

## 2. Jak to działa (krótkie wyjaśnienie)

| Krok | Co się dzieje? |
|------|----------------|
| **Sól** (`salt`) | 16 B losowych danych, dodawana do hasła przed wyliczeniem klucza. Dzięki niej dwa pliki zaszyfrowane tym samym hasłem nie będą wyglądały tak samo. |
| **Derive key** (`pbkdf2`) | Hasło + sól → 256‑bitowy klucz. 100 000 iteracji PBKDF2 zwiększa odporność na ataki brute‑force. |
| **IV** (wektor inicjalizujący) | 16 B losowych danych, określa początkowy stan szyfru CBC. Każde szyfrowanie tego samego bloku z tym samym kluczem da inny wynik. |
| **Ciphertext** | Dane wejściowe zostają zaszyfrowane algorytmem `aes-256-cbc`. |
| **Output format** | `SALT || IV || CIPHERTEXT`. Dzięki takiej strukturze przy odszyfrowaniu nie musisz przechowywać osobnych plików z solą/IV – wszystko jest w jednym pliku `.enc`. |

---

## 3. Bezpieczeństwo – co jeszcze warto rozważyć?

1. **Bezpieczne przechowywanie hasła**  
   - Nie zapisuj hasła w skrypcie.  
   - Użyj zmiennych środowiskowych (`process.env.MY_PASSWORD`) lub menedżera sekretów (HashiCorp Vault, AWS Secrets Manager, itp.).

2. **Integralność danych**  
   - Obecny kod nie dodaje MAC‑a ani HMAC‑u, więc nie wykryje przypadkowej lub celowej modyfikacji pliku.  
   - Dla produkcyjnych zastosowań rozważ użycie **AES‑GCM** (autentykacja wbudowana) lub ręczną implementację HMAC‑SHA256 nad `SALT||IV||CIPHERTEXT`.

3. **Rozmiar pliku**  
   - Szyfrowanie nie zmienia znacząco rozmiaru pliku, ale dodaje 32 B (sol i iv). To znikome w porównaniu z typowymi plikami .js.

4. **Zarządzanie kluczami**  
   - W praktyce lepszym rozwiązaniem jest użycie klucza symetrycznego wygenerowanego losowo i zaszyfrowanie go kluczem asymetrycznym (np. RSA) przed zapisaniem. Dzięki temu nie musisz polegać na haśle.

5. **Ograniczenia**  
   - Skrypt działa na plikach, które mieszczą się w pamięci RAM (czytanie całości do bufora). Dla bardzo dużych plików użyj strumieni (`createReadStream` / `createWriteStream`) i `cipher.update` w pętli.

---

## 4. Testowanie (szybka weryfikacja)

```bash
# 1. Stwórz przykładowy plik
echo "console.log('Hello, world!');" > plik.js

# 2. Zaszyfruj
node cryptofile.js encrypt plik.js superSekretnyHaslo

# 3. Sprawdź, że powstał plik .enc
ls -l plik.js.enc

# 4. Odszyfruj
node cryptofile.js decrypt plik.js.enc superSekretnyHaslo

# 5. Porównaj (powinno być identyczne)
diff plik.js plik.js.dec   # lub po usunięciu .enc po prostu plik.js
```

Jeśli polecenia nie generują błędów i `diff` nie zgłasza różnic, wszystko działa prawidłowo.

---

### Gotowe! 🚀  
Masz teraz prosty, ale bezpieczny sposób na szyfrowanie i odszyfrowywanie dowolnych plików w Node.js. Jeśli potrzebujesz rozbudować skrypt (np. obsługa katalogów, strumieniowe szyfrowanie, integracja z kluczem asymetrycznym), daj znać — chętnie pomogę!

