```jsx
// GridWithFilters.jsx
import React, { useState, useMemo, useCallback } from 'react';
import { AgGridReact } from 'ag-grid-react';
import 'ag-grid-community/styles/ag-grid.css';
import 'ag-grid-community/styles/ag-theme-alpine.css';

export default function GridWithFilters() {
  const [rowData] = useState([
    { id: 1, name: "Alice", role: "Admin" },
    { id: 2, name: "Bob", role: "User" },
    { id: 3, name: "Charlie", role: "Guest" },
    // … fetch from API or load from props
  ]);

  // ------- Global quick filter ----------
  const [quickFilter, setQuickFilter] = useState('');
  const onQuickFilterChange = useCallback(
    (e) => setQuickFilter(e.target.value),
    []
  );

  // ------- Column definitions with built‑in text filter ----------
  const columnDefs = useMemo(() => [
    {
      headerName: "ID",
      field: "id",
      filter: "agTextColumnFilter",   // built‑in text filter
      sortable: true,
      width: 90,
    },
    {
      headerName: "Name",
      field: "name",
      filter: "agTextColumnFilter",
      sortable: true,
    },
    {
      headerName: "Role",
      field: "role",
      filter: "agSetColumnFilter",   // useful for a limited set of roles
    },
  ], []);

  // AG‑Grid exposes an API – we keep a ref to call setQuickFilter()
  const gridRef = React.useRef();

  // Update AG‑Grid's quick filter whenever the user types
  React.useEffect(() => {
    if (gridRef.current) {
      gridRef.current.api.setQuickFilter(quickFilter);
    }
  }, [quickFilter]);

  return (
    <div style={{ width: '100%', height: '100%' }}>
      <div style={{ marginBottom: 6 }}>
        <input
          type="text"
          placeholder="Global search…"
          value={quickFilter}
          onChange={onQuickFilterChange}
          style={{ width: 200, padding: 4 }}
        />
      </div>

      <div
        className="ag-theme-alpine"
        style={{ height: 400, width: '100%' }}
      >
        <AgGridReact
          ref={gridRef}
          rowData={rowData}
          columnDefs={columnDefs}
          defaultColDef={{
            flex: 1,
            minWidth: 100,
            filter: true,   // enables column filters in UI
            resizable: true,
          }}
          animateRows={true}
        />
      </div>
    </div>
  );
}
```

**Key points**

| Feature | How it works |
|---------|--------------|
| Column filters | `filter: "agTextColumnFilter"` (or `agSetColumnFilter`, `agNumberColumnFilter`, etc.). AG‑Grid automatically adds a filter icon in the header that opens a small popup. |
| Global filter | `api.setQuickFilter(value)`. It matches substrings across **all** visible columns. |
| Debounce (optional) | If you want to debounce the quick‑filter input, wrap `setQuickFilter` in a `debounce` call (e.g., lodash’s `_.debounce`). |
| Server‑side mode | If you have > 10k rows, switch to **Server‑Side Row Model** and forward filter text to the back‑end via a query string (see Security checklist below). |

