// ---------- indexeddb‑secure.js ----------
import { encrypt, decrypt } from './crypto-helper.js';
import Ajv from 'ajv';

const SCHEMAS = {
  blogPosts: {
    type: 'object',
    required: ['id', 'title', 'content', 'createdAt'],
    properties: {
      id: { type: 'string' },
      title: { type: 'string', minLength: 1, maxLength: 200 },
      content: { type: 'string' },
      createdAt: { type: 'string', format: 'date-time' },
      updatedAt: { type: 'string', format: 'date-time' },
    },
    additionalProperties: false,
  },
  // ... add more schemas for other stores
};

class SecureDB {
  constructor(dbName = 'mySiteDB', version = 1) {
    this.dbName = dbName;
    this.version = version;
    this.dbPromise = null;
    this.ajv = new Ajv();
    // compile validators once
    this.validators = Object.fromEntries(
      Object.entries(SCHEMAS).map(([store, schema]) => [
        store,
        this.ajv.compile(schema),
      ])
    );
  }

  async _open() {
    if (this.dbPromise) return this.dbPromise;
    this.dbPromise = new Promise((resolve, reject) => {
      const req = indexedDB.open(this.dbName, this.version);
      req.onupgradeneeded = e => {
        const db = e.target.result;
        // Create a store per feature, keyed by id (string)
        for (const store of Object.keys(SCHEMAS)) {
          if (!db.objectStoreNames.contains(store)) {
            db.createObjectStore(store, { keyPath: 'id' });
          }
        }
      };
      req.onsuccess = e => resolve(e.target.result);
      req.onerror = e => reject(e.target.error);
    });
    return this.dbPromise;
  }

  // ---------- Low‑level helpers ----------
  async _tx(store, mode = 'readonly') {
    const db = await this._open();
    const transaction = db.transaction(store, mode);
    const objectStore = transaction.objectStore(store);
    return { transaction, objectStore };
  }

  // ---------- Public API (encrypted) ----------
  async put(store, rawData, cryptoKey) {
    const validate = this.validators[store];
    if (!validate) throw new Error(`No validator for store ${store}`);
    if (!validate(rawData)) throw new Error(`Invalid data: ${validate.errors.map(e=>e.message).join(', ')}`);

    const encrypted = await encrypt(cryptoKey, rawData);
    const payload = { id: rawData.id, blob: encrypted, ts: Date.now() };

    const { objectStore } = await this._tx(store, 'readwrite');
    return new Promise((resolve, reject) => {
      const req = objectStore.put(payload);
      req.onsuccess = () => resolve();
      req.onerror = e => reject(e.target.error);
    });
  }

  async get(store, id, cryptoKey) {
    const { objectStore } = await this._tx(store, 'readonly');
    return new Promise((resolve, reject) => {
      const req = objectStore.get(id);
      req.onsuccess = async e => {
        const record = e.target.result;
        if (!record) return resolve(null);
        try {
          const data = await decrypt(cryptoKey, record.blob);
          // Deep clone to avoid caller mutating the returned object
          resolve(JSON.parse(JSON.stringify(data)));
        } catch (err) {
          // If decryption fails → treat as tampered / corrupted data
          console.warn('Decryption failed for', store, id);
          // Optionally wipe the bad record:
          // await this.delete(store, id);
          resolve(null);
        }
      };
      req.onerror = e => reject(e.target.error);
    });
  }

  async delete(store, id) {
    const { objectStore } = await this._tx(store, 'readwrite');
    return new Promise((resolve, reject) => {
      const req = objectStore.delete(id);
      req.onsuccess = () => resolve();
      req.onerror = e => reject(e.target.error);
    });
  }

  // ---------- Bulk read (e.g., for offline sync) ----------
  async getAll(store, cryptoKey) {
    const { objectStore } = await this._tx(store, 'readonly');
    return new Promise((resolve, reject) => {
      const req = objectStore.getAll();
      req.onsuccess = async e => {
        const raw = e.target.result;
        const out = [];
        for (const rec of raw) {
          try {
            out.push(await decrypt(cryptoKey, rec.blob));
          } catch (_) {
            console.warn('Corrupt entry in', store, rec.id);
          }
        }
        resolve(out);
      };
      req.onerror = e => reject(e.target.error);
    });
  }
}

// Export a singleton (or instantiate per‑user session)
export const db = new SecureDB();
