<html lang="ru">
<head>
  <meta charset="UTF-8">
  <title>Demo: Photo from JSON API</title>
  <style>
    img { max-width: 400px; border: 1px solid #ccc; display: block; margin: 1rem 0; }
  </style>
</head>
<body>
  <h1>Получить фото через JSON API</h1>

  <button id="load-url">Загрузить по URL</button>
  <button id="load-base64">Загрузить как base64</button>

  <img id="photo" alt="Фото">

  <script>
    const photoEl = document.getElementById('photo');

    // ---------- helper ----------
    async function fetchJSON(url) {
      const resp = await fetch(url, { credentials: 'include' }); // включаем куки, если нужны
      if (!resp.ok) throw new Error(`HTTP ${resp.status}`);
      return resp.json();
    }

    // ---------- 1. По URL ----------
    document.getElementById('load-url').addEventListener('click', async () => {
      try {
        // Предположим, у нас id = 12345
        const data = await fetchJSON('/api/photo/12345/url');
        photoEl.src = data.photoUrl;          // <img> автоматически подхватит
        console.log('URL:', data.photoUrl);
      } catch (e) {
        console.error(e);
        alert('Не удалось загрузить фото по URL');
      }
    });

    // ---------- 2. Base64 ----------
    document.getElementById('load-base64').addEventListener('click', async () => {
      try {
        const data = await fetchJSON('/api/photo/12345/base64');
        // data.photo уже data‑uri, просто назначаем src
        photoEl.src = data.photo;
        console.log('MIME:', data.mimeType, 'size:', data.size);
      } catch (e) {
