/* ------------------------------------------------------------------
   UTILITIES – always escape user‑generated text before inserting it.
------------------------------------------------------------------- */
function escapeHTML(str) {
    // Fast, safe escaping for text nodes.
    const div = document.createElement('div');
    div.appendChild(document.createTextNode(str));
    return div.innerHTML;
}

/* ------------------------------------------------------------------
   RENDER QUIZ
------------------------------------------------------------------- */
function renderQuiz() {
    const form = document.getElementById('quiz-form');

    quizData.forEach(item => {
        const wrapper = document.createElement('div');
        wrapper.className = 'question';
        wrapper.id = `q${item.id}`;

        const label = document.createElement('label');
        label.textContent = item.question + (item.required ? ' *' : '');
        label.setAttribute('for', `input-${item.id}`);
        wrapper.appendChild(label);

        // Build input based on type
        let inputElement;
        switch (item.type) {
            case 'text':
                inputElement = document.createElement('input');
                inputElement.type = 'text';
                inputElement.id = `input-${item.id}`;
                inputElement.name = `q${item.id}`;
                if (item.pattern) inputElement.pattern = item.pattern;
                break;

            case 'textarea':
                inputElement = document.createElement('textarea');
                inputElement.id = `input-${item.id}`;
                inputElement.name = `q${item.id}`;
                inputElement.rows = 4;
                break;

            case 'radio':
                inputElement = document.createElement('div');
                inputElement.className = 'options';
                item.options.forEach((opt, idx) => {
                    const optId = `q${item.id}_opt${idx}`;
                    const radio = document.createElement('input');
                    radio.type = 'radio';
                    radio.id = optId;
                    radio.name = `q${item.id}`;
                    radio.value = opt;

                    const radioLabel = document.createElement('label');
                    radioLabel.htmlFor = optId;
                    radioLabel.textContent = opt;

                    const container = document.createElement('div');
                    container.appendChild(radio);
                    container.appendChild(radioLabel);
                    inputElement.appendChild(container);
                });
                break;

            case 'checkbox':
                inputElement = document.createElement('div');
                inputElement.className = 'options';
                item.options.forEach((opt, idx) => {
                    const optId = `q${item.id}_opt${idx}`;
                    const chk = document.createElement('input');
                    chk.type = 'checkbox';
                    chk.id = optId;
                    chk.name = `q${item.id}`; // same name, treat as array later
                    chk.value = opt;

                    const chkLabel = document.createElement('label');
                    chkLabel.htmlFor = optId;
                    chkLabel.textContent = opt;

                    const container = document.createElement('div');
                    container.appendChild(chk);
                    container.appendChild(chkLabel);
                    inputElement.appendChild(container);
                });
                break;

            default:
                console.warn(`Tipo desconocido: ${item.type}`);
        }

        wrapper.appendChild(inputElement);
        form.appendChild(wrapper);
    });

    // Submit button (type="button" to avoid native form submit)
    const submitBtn = document.createElement('button');
    submitBtn.type = 'button';
    submitBtn.id = 'submitBtn';
    submitBtn.textContent = 'Enviar';
    submitBtn.addEventListener('click', handleSubmit);
    form.appendChild(submitBtn);
}

/* ------------------------------------------------------------------
   UPDATE PROGRESS BAR
------------------------------------------------------------------- */
function updateProgress() {
    const total = quizData.length;
    let answered = 0;

    quizData.forEach(item => {
        const name = `q${item.id}`;
        if (item.type === 'checkbox') {
            const checked = document.querySelectorAll(`input[name="${name}"]:checked`);
            if (checked.length > 0) answered++;
        } else {
            const value = document.querySelector(`[name="${name}"]`);
            if (value && value.value.trim() !== '') answered++;
        }
    });

    const percent = Math.round((answered / total) * 100);
    const bar = document.getElementById('progress-bar');
    bar.style.width = `${percent}%`;
}

/* ------------------------------------------------------------------
   VALIDATION + SUBMIT HANDLER
------------------------------------------------------------------- */
function handleSubmit() {
    const errors = [];

    // Simple validation loop
    quizData.forEach(item => {
        const name = `q${item.id}`;
        let value = null;

        if (item.type === 'checkbox') {
            const nodeList = document.querySelectorAll(`input[name="${name}"]:checked`);
            value = Array.from(nodeList).map(el => el.value);
            if (item.required && value.length === 0) {
                errors.push(`- ${item.question} (selecciona al menos una opción)`);
            }
        } else if (item.type === 'radio') {
            const selected = document.querySelector(`input[name="${name}"]:checked`);
            value = selected ? selected.value : null;
            if (item.required && !value) {
                errors.push(`- ${item.question} (elige una opción)`);
            }
        } else {
            const input = document.querySelector(`[name="${name}"]`);
            if (input) {
                value = input.value.trim();
                if (item.required && value === '') {
                    errors.push(`- ${item.question} (campo obligatorio)`);
                }
                if (item.pattern && value && !new RegExp(item.pattern).test(value)) {
                    errors.push(`- ${item.question} (${item.errorMsg || 'Formato incorrecto'})`);
                }
            }
        }
    });

    if (errors.length) {
        alert('Por favor corrige los siguientes errores:\n' + errors.join('\n'));
        return;
    }

    // Build a safe result object
    const result = {};

    quizData.forEach(item => {
        const name = `q${item.id}`;
        if (item.type === 'checkbox') {
            const nodeList = document.querySelectorAll(`input[name="${name}"]:checked`);
            result[item.question] = Array.from(nodeList).map(el => el.value);
        } else if (item.type === 'radio') {
            const selected = document.querySelector(`input[name="${name}"]:checked`);
            result[item.question] = selected ? selected.value : null;
        } else {
            const input = document.querySelector(`[name="${name}"]`);
            result[item.question] = input ? input.value.trim() : null;
        }
    });

    // Show result (escaped JSON for safety)
    const resultDiv = document.getElementById('result');
    resultDiv.textContent = JSON.stringify(result, null, 2);
    resultDiv.classList.remove('hidden');

    // Optionally reset the form or disable further edits
    document.getElementById('submitBtn').disabled = true;
}

/* ------------------------------------------------------------------
   INIT – render UI and bind listeners
------------------------------------------------------------------- */
document.addEventListener('DOMContentLoaded', () => {
    renderQuiz();
    // Update progress whenever an input changes
    document.getElementById('quiz-form').addEventListener('change', updateProgress);
    updateProgress(); // initial state
});
```

