## 5️⃣ `scripts/build-db.js` – DB Initialisation + Exported `db`

```js
// scripts/build-db.js
'use strict';
const path = require('path');
const sqlite3 = require('sqlite3').verbose();
const fs = require('fs');

const DB_PATH = path.join(__dirname, '..', 'db', 'blog.sqlite');

// Ensure db folder exists
if (!fs.existsSync(path.dirname(DB_PATH))) {
  fs.mkdirSync(path.dirname(DB_PATH), { recursive: true });
}

// Open (or create) the database
const db = new sqlite3.Database(DB_PATH, (err) => {
  if (err) throw err;
  console.log('📂 SQLite DB opened at', DB_PATH);
});

// Helper to run statements sequentially
function run(sql, params = []) {
  return new Promise((resolve, reject) => {
    db.run(sql, params, function (err) {
      if (err) reject(err);
      else resolve(this);
    });
  });
}

// Create tables + default settings
async function init() {
  // Settings – only one row, but easy to query/update
  await run(`
    CREATE TABLE IF NOT EXISTS settings (
      id INTEGER PRIMARY KEY CHECK (id = 1),
      blog_title TEXT NOT NULL,
      blog_subtitle TEXT NOT NULL,
      author_name TEXT NOT NULL
    );
  `);
  // Insert default row if missing
  await run(`
    INSERT OR IGNORE INTO settings (id, blog_title, blog_subtitle, author_name)
    VALUES (1, 'My Awesome Blog', 'Thoughts, stories and more', 'John Doe');
  `);

  // Articles
  await run(`
    CREATE TABLE IF NOT EXISTS articles (
      id INTEGER PRIMARY KEY AUTOINCREMENT,
      title TEXT NOT NULL,
      subtitle TEXT,
      body TEXT NOT NULL,
      created_at DATETIME NOT NULL,
      modified_at DATETIME NOT NULL,
      published_at DATETIME,
      is_published INTEGER NOT NULL DEFAULT 0,
      likes INTEGER NOT NULL DEFAULT 0
    );
  `);

  // Comments
  await run(`
    CREATE TABLE IF NOT EXISTS comments (
      id INTEGER PRIMARY KEY AUTOINCREMENT,
      article_id INTEGER NOT NULL,
      comment TEXT NOT NULL,
      created_at DATETIME NOT NULL,
      FOREIGN KEY (article_id) REFERENCES articles(id) ON DELETE CASCADE
    );
  `);

  console.log('✅ DB schema ready');
}

// If script is called directly (npm run build-db) initialise DB
if (require.main === module) {
  init()
    .then(() => db.close())
    .catch((e) => {
      console.error('❌ DB init error', e);
      process.exit(1);
    });
}

// Export the db object for use in route files
module.exports = { db, init };
```

> **Note** – `npm run build-db` simply executes `node scripts/build-db.js`, which runs the `init()` function and creates the SQLite file with default data.

