```js
/**
 * Преобразует массив вида
 *   ["DCU_DLMS","Parameters","General","Read",["Get Version","Get Date & Time"],"Write",["Alert","Get Version","Get Date & Time"]]
 * в вложенный объект.
 *
 * @param {Array} src – исходный массив
 * @param {Object} [opts] – опциональная конфигурация
 * @param {string} [opts.rootName='Load Profile'] – имя корневого уровня, если требуется (по вашему примеру)
 * @returns {Object}
