 *   • Функция использует `Object.create(null)` – без прототипа, чтобы исключить прототипную политику.
 *   • Проверка `Object.prototype.hasOwnProperty.call` предотвращает атаки prototype‑pollution.
 *   • Все входные данные строго проверяются на тип `Array` и `string`.
 */
function arrayToTree(src, opts = {}) {
    const { rootName = 'Load Profile' } = opts;

    // ----- 1. Защищённый контейнер без прототипа -----
    const result = Object.create(null);
    if (!Array.isArray(src)) {
        throw new TypeError('Input must be an array');
    }

    // Текущий указатель внутри результирующего объекта
