    // Вспомогательная функция – безопасно добавить/получить дочерний объект
    const ensureNode = (obj, key) => {
        if (!Object.prototype.hasOwnProperty.call(obj, key)) {
            obj[key] = Object.create(null);
        }
        return obj[key];
