    //   • строкой    – новый уровень вложения
    //   • чем‑то другим – ошибка
    for (let i = 0; i < src.length; i++) {
        const token = src[i];

        // Пропускаем «пустые» токены (может появиться в результате предобработки)
        if (token == null) continue;

        if (typeof token !== 'string') {
            throw new TypeError(`Expected string at position ${i}, got ${typeof token}`);
        }

        // Если следующий элемент существует и является массивом – это листовое значение
        const next = src[i + 1];
        if (Array.isArray(next)) {
            // Окончательная запись листа
            // Example: "Read", ["Get Version","Get Date & Time"]
            // Вариант с «переименованием» уровня (по примеру) – может потребоваться маппинг
