    const finalResult = Object.create(null);
    finalResult[result[Object.keys(result)[0]] ? Object.keys(result)[0] : 'ROOT'] = result; // сохраняем первый уровень (DCU_DLMS)
    if (rootName) {
        const wrapper = Object.create(null);
        wrapper[rootName] = finalResult;
        return wrapper;
    }
