   * should use the exported singleton (`websocketApi`) instead of instantiating
   * this class directly.
   *
   * @private
   */
  constructor() {
    /**
     * Internal event emitter (mitt). All public events are emitted through this
     * instance.
     *
     * @type {Mitt}
     * @private
     */
    this.emitter = mitt();
  }

  /**
   * Open a WebSocket connection to the configured endpoint.
   *
   * The method creates a `WebSocket` instance, registers a `message` listener,
   * parses incoming JSON payloads and forwards them as typed events:
   *
   * | `action`                | Emitted event name          | Payload                                          |
   * |------------------------|-----------------------------|--------------------------------------------------|
   * | `update_station`       | `update_station`            | `{ uuid: string }`                               |
   * | `update_station_list`  | `update_station_list`       | *none*                                           |
   * | `update_inventory`     | `update_inventory`          | `{ factory_uuid: string, inventory_name: string}`|
   *
   * @fires WebSocketManager#update_station
   * @fires WebSocketManager#update_station_list
   * @fires WebSocketManager#update_inventory
   *
   * @throws {Error} If the browser does not support `WebSocket`.
   */
  open() {
    // NOTE: in a production environment you probably want to make
    // the URL configurable (e.g. via environment variables) and use `wss://`
    this.socket = new WebSocket('ws://owbalancer.ddns.net:8765/site');

    const self = this;
    this.socket.addEventListener('message', (msg) => {
      let json;
      try {
        json = JSON.parse(msg.data);
      } catch (e) {
        console.warn('WebSocketManager – received malformed JSON:', msg.data);
        return; // ignore the bad message
      }

      const { action, uuid, factory, inventory } = /** @type {WSMessage} */ (json);

      switch (action) {
        case 'update_station':
          self.emitter.emit('update_station', { uuid });
          break;
        case 'update_station_list':
          self.emitter.emit('update_station_list');
          break;
        case 'update_inventory':
          self.emitter.emit('update_inventory', {
            factory_uuid: factory,
            inventory_name: inventory,
          });
          break;
        default:
          console.debug('WebSocketManager – unknown action:', action);
      }
    });
  }

  /**
   * Send a JSON‑encoded message to the server.
   *
   * @param {WSOutgoingMessage} data The payload to be stringified and sent.
   * @throws {Error} If the socket is not open (`this.socket?.readyState !== WebSocket.OPEN`).
   */
  sendMessage(data) {
    if (!this.socket || this.socket.readyState !== WebSocket.OPEN) {
      throw new Error('WebSocket is not open – cannot send message');
    }
    this.socket.send(JSON.stringify(data));
  }

