   * Register a listener for an event emitted by the internal `mitt` instance.
   *
   * @param {string} eventName The name of the event (`'update_station'`,
   *                           `'update_station_list'` or `'update_inventory'`).
   * @param {Function} handler The callback to invoke when the event occurs.
   *
   * @example
   * websocketApi.on('update_station', ({ uuid }) => {
   *   // react to the station update
   * });
   */
  on(eventName, handler) {
    this.emitter.on(eventName, handler);
  }

  /**
   * Remove a previously‑registered listener.
   *
   * @param {string} eventName
   * @param {Function} handler
   */
  off(eventName, handler) {
    this.emitter.off(eventName, handler);
  }
}

/**
 * A singleton instance of {@link WebSocketManager} that can be imported
 * anywhere in the application.
 *
 * @type {WebSocketManager}
 * @example
 * import { websocketApi } from './WebSocketManager';
 *
 * websocketApi.open();
 */
export const websocketApi = new WebSocketManager();
