  // ---- CSRF‑check -------------------------------------------------
  const sentToken = req.body.csrf_token;
  const cookieToken = req.cookies.csrf_token;
  if (!sentToken || sentToken !== cookieToken) {
    return res.status(403).json({ error: 'Invalid CSRF token' });
  }

  // ---- Параметры DataTables ---------------------------------------
  const draw   = Number(req.body.draw) || 1;
  const start  = Number(req.body.start) || 0;
  const length = Number(req.body.length) || 10;
  const search = (req.body.search?.value || '').trim().toLowerCase();

  // ---- Фильтрация (поиск) -----------------------------------------
  let filtered = USERS;
  if (search) {
    filtered = USERS.filter(u =>
      u.name.toLowerCase().includes(search) ||
      u.email.toLowerCase().includes(search) ||
      u.role.toLowerCase().includes(search)
    );
  }

  // ---- Сортировка -------------------------------------------------
  const order = req.body.order?.[0];
  if (order) {
    const colIdx = Number(order.column);
    const dir = order.dir === 'desc' ? -1 : 1;
    const columns = ['id', 'name', 'email', 'role', 'created_at'];
    const colName = columns[colIdx];
    filtered = filtered.sort((a, b) => {
      if (a[colName] < b[colName]) return -1 * dir;
      if (a[colName] > b[colName]) return 1 * dir;
      return 0;
    });
  }

  // ---- Пагинация --------------------------------------------------
  const page = filtered.slice(start, start + length);

  // ---- Ответ -------------------------------------------------------
  res.json({
    draw,
    recordsTotal: USERS.length,
    recordsFiltered: filtered.length,
    data: page
  });
});

