## 2. 后端代码（Node.js + Express）

> **依赖**：`express`（提供静态文件服务） + `cors`（防止跨域，在本地调试时非常有用）

**`server/package.json`**

```json
{
  "name": "3d-model-browser-server",
  "version": "1.0.0",
  "description": "Simple server for 3D model preview & download",
  "main": "server.js",
  "scripts": {
    "start": "node server.js"
  },
  "author": "Your Name",
  "license": "MIT",
  "dependencies": {
    "cors": "^2.8.5",
    "express": "^4.18.2"
  }
}
```

**`server/server.js`**

```js
/**
 *  3D Model Browser  -  Server
 *  功能：
 *   1. 提供 static 文件（public、models）
 *   2. 暴露 /api/models 接口返回所有模型的元信息（分类、文件路径、预览图路径）
 */
const express = require('express');
const cors = require('cors');
const path = require('path');
const fs = require('fs');

const app = express();
const PORT = process.env.PORT || 3000;

// ---------- 中间件 ----------
app.use(cors());
app.use(express.static(path.join(__dirname, '..', 'public')));   // 前端文件
app.use('/models', express.static(path.join(__dirname, '..', 'models'))); // 资源文件

// ---------- 工具函数 ----------
/**
 * 遍历 models/ 目录，收集所有模型信息
 *   - 只读取 .glb / .fbx / .obj / .gltf (你可以自行扩展)
 *   - 预览图要求同名、后缀 .jpg/.png/.jpeg
 */
function scanModels() {
  const root = path.join(__dirname, '..', 'models');
  const categories = fs.readdirSync(root, { withFileTypes: true })
    .filter(dirent => dirent.isDirectory())
    .map(dirent => dirent.name);

  const models = [];

  categories.forEach(category => {
    const catPath = path.join(root, category);
    const files = fs.readdirSync(catPath);

    // 找出所有模型文件
    const modelFiles = files.filter(f => /\.(glb|gltf|fbx|obj)$/i.test(f));

    modelFiles.forEach(file => {
      const basename = path.parse(file).name;
      // 寻找同名的预览图（支持 jpg、jpeg、png）
      const preview = files.find(img => {
        const ext = path.extname(img).toLowerCase();
        return img.startsWith(basename) && ['.jpg', '.jpeg', '.png'].includes(ext);
      });

      // 如果没有预览图，直接跳过（或你可以使用默认图）
      if (!preview) return;

      models.push({
        name: basename,
        category,
        // 下面的路径是相对于网站根的 URL
        modelUrl: `/models/${category}/${file}`,
        previewUrl: `/models/${category}/${preview}`
      });
    });
  });

  return { categories, models };
}

// ---------- API ----------
app.get('/api/models', (req, res) => {
  const data = scanModels();
  res.json(data);
});

// ---------- 启动 ----------
app.listen(PORT, () => {
  console.log(`Server started on http://localhost:${PORT}`);
  console.log('Press Ctrl+C to stop');
});
```

> **启动步骤**  
> 1. 进入 `server` 目录：`cd 3d-model-browser/server`  
> 2. 安装依赖：`npm install`  
> 3. 启动服务器：`npm start` （默认端口 3000）  
> 4. 浏览器打开 `http://localhost:3000` 即可看到前端页面。

