### 3.3 `public/app.js`

```js
/* 3D Model Browser - 前端逻辑
   1. 从 /api/models 读取全部模型信息
   2. 动态生成分类单选框（单选）
   3. 根据当前选中的分类渲染模型列表（分页 4×5 = 20）
   4. 点击预览图（缩略图）即下载对应模型文件
*/

const PAGE_SIZE = 20;        // 每页最大数量（4列 × 5行）
let allModels = [];          // 所有模型（从后端获取）
let categories = [];         // 所有分类名称
let currentCategory = null;  // 当前选中的分类
let currentPage = 1;         // 当前页码

// --- DOM 元素 ---
const categoryOptionsEl = document.getElementById('category-options');
const modelGridEl       = document.getElementById('model-grid');
const prevBtn           = document.getElementById('prev-page');
const nextBtn           = document.getElementById('next-page');
const pageInfoEl        = document.getElementById('page-info');

// --- 初始化 ---
fetchModels();

prevBtn.addEventListener('click', () => changePage(currentPage - 1));
nextBtn.addEventListener('click', () => changePage(currentPage + 1));

// --------------------------------------------------
// 1. 从服务器获取模型列表
// --------------------------------------------------
function fetchModels() {
  fetch('/api/models')
    .then(r => r.json())
    .then(data => {
      categories = data.categories;
      allModels  = data.models;
      renderCategoryRadios();
      // 默认选中第一个分类
      if (categories.length > 0) {
        document.getElementById(`cat-${categories[0]}`).checked = true;
        currentCategory = categories[0];
        renderCurrentPage();
      }
    })
    .catch(err => console.error('Failed to load models:', err));
}

// --------------------------------------------------
// 2. 生成分类单选框（单选）
// --------------------------------------------------
function renderCategoryRadios() {
  const fragment = document.createDocumentFragment();

  categories.forEach(cat => {
    const label = document.createElement('label');
    label.htmlFor = `cat-${cat}`;

    const radio = document.createElement('input');
    radio.type = 'radio';
    radio.name = 'category';
    radio.id   = `cat-${cat}`;
    radio.value= cat;
    radio.addEventListener('change', () => {
      currentCategory = cat;
      currentPage = 1;
      renderCurrentPage();
    });

    label.appendChild(radio);
    label.append(` ${cat}`);
    fragment.appendChild(label);
  });

  categoryOptionsEl.innerHTML = '';
  categoryOptionsEl.appendChild(fragment);
}

// --------------------------------------------------
// 3. 过滤、分页并渲染模型卡片
// --------------------------------------------------
function renderCurrentPage() {
  // 1️⃣ 过滤出当前分类的模型
  const filtered = allModels.filter(m => m.category === currentCategory);

  // 2️⃣ 计算分页信息
  const totalPages = Math.max(1, Math.ceil(filtered.length / PAGE_SIZE));

  // 防止页码越界
  if (currentPage > totalPages) currentPage = totalPages;
  if (currentPage < 1) currentPage = 1;

  // 3️⃣ 切片得到本页数据
  const startIdx = (currentPage - 1) * PAGE_SIZE;
  const pageData = filtered.slice(startIdx, startIdx + PAGE_SIZE);

  // 4️⃣ 渲染网格
  modelGridEl.innerHTML = '';
  if (pageData.length === 0) {
    modelGridEl.innerHTML = '<p style="grid-column:1/-1;">暂无模型</p>';
  } else {
    const frag = document.createDocumentFragment();
    pageData.forEach(m => {
      const card = document.createElement('div');
      card.className = 'model-card';
      card.title = `点击下载 ${m.name}`;

      // 预览图
      const img = document.createElement('img');
      img.src = m.previewUrl;
      img.alt = m.name;
      // 直接下载（利用 <a download>）
      img.addEventListener('click', (e) => {
        e.stopPropagation(); // 防止触发卡片的默认行为
        downloadModel(m);
      });

      // 信息栏
      const info = document.createElement('div');
      info.className = 'info';
      info.textContent = `${m.name} (${m.category})`;

      card.appendChild(img);
      card.appendChild(info);
      frag.appendChild(card);
    });
    modelGridEl.appendChild(frag);
  }

  // 5️⃣ 更新分页控件
  pageInfoEl.textContent = `第 ${currentPage} / ${totalPages} 页`;
  prevBtn.disabled = currentPage <= 1;
  nextBtn.disabled = currentPage >= totalPages;
}

// --------------------------------------------------
// 4. 切换页码
// --------------------------------------------------
function changePage(page) {
  currentPage = page;
  renderCurrentPage();
}

// --------------------------------------------------
// 5. 下载模型文件（点击缩略图触发）
// --------------------------------------------------
function downloadModel(model) {
  const a = document.createElement('a');
  a.href = model.modelUrl;
  // 给文件一个有意义的名字：<分类>_<模型名>.<后缀>
  const ext = model.modelUrl.split('.').pop();
  a.download = `${model.category}_${model.name}.${ext}`;
  document.body.appendChild(a);
  a.click();
  document.body.removeChild(a);
}
```

