### 2.3 `content.js` (runs in the page)

```js
(() => {
  // Helper to create a tooltip element (isolated world)
  const createTooltip = (quote, sourceUrl) => {
    const tooltip = document.createElement('div');
    tooltip.className = 'ems-tooltip';
    tooltip.innerHTML = `
      <p>${quote}</p>
      <a href="${sourceUrl}" target="_blank" rel="noopener">source</a>
      <button class="close">✕</button>
    `;
    document.body.appendChild(tooltip);
    return tooltip;
  };

  // Load CSS once (web_accessible_resources)
  const loadCSS = () => {
    const link = document.createElement('link');
    link.rel = 'stylesheet';
    link.href = chrome.runtime.getURL('tooltip.css');
    document.head.appendChild(link);
  };
  loadCSS();

  // -----------------------------------------------------------------
  // 1️⃣ Trigger – user selects a term and presses the extension button
  // -----------------------------------------------------------------
  chrome.runtime.onMessage.addListener((msg, sender, sendResponse) => {
    if (msg.type !== 'selection') return;
    const term = msg.term.trim();
    if (!term) return;

    // Ask background for the quote
    chrome.runtime.sendMessage({type: 'lookup', term}, resp => {
      if (!resp?.success) {
        console.warn('No quote found', resp?.error);
        return;
      }
      const tooltip = createTooltip(resp.quote, resp.sourceUrl);

      // Position tooltip close to the selection rectangle
      const range = window.getSelection().getRangeAt(0);
      const rect = range.getBoundingClientRect();
      tooltip.style.top = `${rect.bottom + window.scrollY + 5}px`;
      tooltip.style.left = `${rect.left + window.scrollX}px`;

      // Close button handling
      tooltip.querySelector('.close').addEventListener('click', () => {
        tooltip.remove();
      });
    });
  });

  // -----------------------------------------------------------------
  // 2️⃣ Optional: auto‑detect when mouse hovers over a link/term 
  // -----------------------------------------------------------------
  // (Leave this disabled for a tighter privacy stance; enable only after user opt‑in)
})();
```

