```js
// ==== app.js ====
// All DOM updates use textContent / src to avoid XSS
const form = document.getElementById('weatherForm');
const cityInput = document.getElementById('cityInput');
const resultSection = document.getElementById('result');
const errorSection = document.getElementById('error');

const cityNameEl = document.getElementById('cityName');
const descriptionEl = document.getElementById('description');
const tempEl = document.getElementById('temp');
const iconEl = document.getElementById('icon');

const API_ENDPOINT = '/api/weather'; // Proxy endpoint

form.addEventListener('submit', async (e) => {
    e.preventDefault();
    const rawCity = cityInput.value.trim();

    // Very light client‑side sanitisation (defense‑in‑depth)
    const city = rawCity.replace(/[<>]/g, '');

    if (!city) { displayError('Please provide a city name.'); return; }

    try {
        const resp = await fetch(`${API_ENDPOINT}?city=${encodeURIComponent(city)}`, {
            method: 'GET',
            credentials: 'same-origin',
            headers: {
                'Accept': 'application/json'
            }
        });

        if (!resp.ok) {
            const err = await resp.json().catch(() => ({message: resp.statusText}));
            throw new Error(err.message || 'Failed to fetch weather');
        }

        const data = await resp.json();
        renderWeather(data);
    } catch (err) {
        displayError(err.message);
    }
});

function renderWeather(data) {
    // Reset any previous error
    errorSection.hidden = true;

    cityNameEl.textContent = `${data.name}, ${data.sys.country}`;
    descriptionEl.textContent = data.weather[0].description;
    const celsius = (data.main.temp - 273.15).toFixed(1);
    tempEl.textContent = `${celsius} °C`;
    const iconCode = data.weather[0].icon;
    iconEl.src = `https://openweathermap.org/img/wn/${iconCode}@2x.png`;
    iconEl.alt = data.weather[0].description;

    resultSection.hidden = false;
}

function displayError(msg) {
    resultSection.hidden = true;
    errorSection.textContent = msg;
    errorSection.hidden = false;
}
```

*Key security points*

* **`encodeURIComponent`** prevents query‑string injection.
* **`textContent`** avoids XSS from the API response (OpenWeatherMap is trusted, but defense in depth never hurts).
* Errors are shown in a dedicated `<section>` – no stack traces leak to the UI.

