### `server/index.js`

```js
/* ==== server/index.js ==== */
require('dotenv').config();
const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const xss = require('xss-clean');
const fetch = require('node-fetch');
const path = require('path');

const app = express();

// ---------- Security Middlewares ----------
app.use(helmet({
    contentSecurityPolicy: false // CSP is enforced via meta tag in HTML
}));
app.use(express.json());
app.use(xss()); // Clean any user‑input that reaches us (defense‑in‑depth)

// Rate‑limit: 60 req/min per IP (adjust for your plan)
const limiter = rateLimit({
    windowMs: 60 * 1000,
    max: 60,
    standardHeaders: true,
    legacyHeaders: false,
    message: { error: 'Too many requests, please try later.' }
});
app.use(limiter);

// ---------- Serve static front‑end ----------
app.use(express.static(path.join(__dirname, '..', 'public')));

// ---------- Helper: Validate city name ----------
function isValidCity(city) {
    // Allow letters, spaces, hyphens, apostrophes – max 100 chars
    const re = /^[a-zA-Z\s\-\']{2,100}$/;
    return re.test(city);
}

// ---------- Proxy endpoint ----------
app.get('/api/weather', async (req, res) => {
    const city = req.query.city?.trim();

    if (!city || !isValidCity(city)) {
        return res.status(400).json({ error: 'Invalid city name' });
    }

    const apiKey = process.env.OWM_API_KEY;
    if (!apiKey) {
        console.error('OWM_API_KEY not configured');
        return res.status(500).json({ error: 'Server misconfiguration' });
    }

    const url = `https://api.openweathermap.org/data/2.5/weather?q=${encodeURIComponent(city)}&appid=${apiKey}`;
    try {
        const apiResp = await fetch(url);
        if (!apiResp.ok) {
            const errBody = await apiResp.json().catch(() => ({}));
            const msg = errBody.message || apiResp.statusText;
            return res.status(apiResp.status).json({ error: msg });
        }
        const data = await apiResp.json();

        // OPTIONAL: Strip out any fields you don't need (reduce data leakage)
        const safeData = {
            name: data.name,
            sys: { country: data.sys?.country },
            weather: data.weather?.map(w => ({
                description: w.description,
                icon: w.icon
            })) ?? [],
            main: { temp: data.main?.temp }
        };

        res.json(safeData);
    } catch (e) {
        console.error('Proxy error:', e);
        res.status(502).json({ error: 'Bad gateway' });
    }
});

// ---------- Global error handler ----------
app.use((err, req, res, next) => {
    console.error('Unhandled error:', err);
    res.status(500).json({ error: 'Internal server error' });
});

const PORT = process.env.PORT || 3000;
app.listen(PORT, () => {
    console.log(`⚡️ Weather proxy listening on http://localhost:${PORT}`);
});
```

#### Security annotations

| Feature | Why it matters |
|---------|----------------|
| `helmet` | Sets secure HTTP headers (`X‑Frame‑Options`, `X‑XSS‑Protection`, `Strict‑Transport‑Security`, etc.) |
| `express-rate-limit` | Thwarts brute‑force / DoS attacks on the proxy (especially important when the API key is tied to a limited quota) |
| `xss-clean` | Sanitises request bodies (even though we only accept GET with query params) – defense‑in‑depth |
| **Input validation** (`isValidCity`) | Prevents injection attacks against the upstream OpenWeatherMap endpoint and stops malformed requests that could waste quota |
| **Never expose the API key** | The key stays in `.env` on the server; the client only talks to `/api/weather` |
| **Error handling** – generic messages to the client, detailed logs only on server side | Avoids leaking internal information (stack traces, API key) to attackers |
| **CSP via meta** (instead of `helmet` CSP) | Allows us to keep a strict but simple policy that matches the static assets we serve |
| **HTTPS** – in production you must serve the site behind TLS (e.g., via Nginx, Heroku, Vercel, etc.) | Prevents MITM interception of API responses and user inputs |

