function searchInDB({ query = '', role = '', city = '', genre = '' }) {
  return new Promise((resolve, reject) => {
    let sql = `SELECT id, name, genre, thumbnail, soundcloud, role, city FROM users WHERE 1=1`;
    const params = [];

    if (query) {
      sql += ` AND (LOWER(name) LIKE ? OR LOWER(genre) LIKE ?)`;
      const like = `%${query.toLowerCase()}%`;
      params.push(like, like);
    }
    if (role) {
      sql += ` AND role = ?`;
      params.push(role);
    }
    if (city) {
      sql += ` AND LOWER(city) = ?`;
      params.push(city.toLowerCase());
    }
    if (genre) {
      sql += ` AND LOWER(genre) = ?`;
      params.push(genre.toLowerCase());
    }

    // Порядок сортировки аналогичен оригинальному: сначала совпадения в начале строки
    sql += ` ORDER BY 
      (CASE WHEN LOWER(name) LIKE CONCAT(?, '%') THEN 2
            WHEN LOWER(name) LIKE ? THEN 1 ELSE 0 END) DESC,
      (CASE WHEN LOWER(genre) LIKE CONCAT(?, '%') THEN 2
            WHEN LOWER(genre) LIKE ? THEN 1 ELSE 0 END) DESC,
      name ASC
    `;

    // Добавляем параметры для сортировки (нужны 2‑й и 4‑й паттерн)
    const sortPattern = query.toLowerCase() + '%';
    params.push(sortPattern, `%${query.toLowerCase()}%`, sortPattern, `%${query.toLowerCase()}%`);

    connection.query(sql, params, (err, rows) => {
      if (err) return reject(err);
      // Приводим к формату, ожидаемому шаблоном EJS
      const musicians = rows.map(m => ({
        name: m.name,
        genre: m.genre,
        originalName: m.name,
        profileLink: `/profile/${m.id}`,
        thumbnail: m.thumbnail,
        soundcloud: m.soundcloud,
        role: m.role,
        city: m.city
      }));
      resolve(musicians);
    });
  });
}
