      console.info(`🚀 Server listening on http://localhost:${PORT}`);
    });
  })
  .catch((e) => {
    console.error('❌ Failed to connect to DB:', e);
    process.exit(1);
  });
```

### 5.2 `config/db.js`

```js
const mongoose = require('mongoose');

async function connectDB() {
  const uri = process.env.MONGODB_URI;
  if (!uri) throw new Error('MONGODB_URI not defined in .env');

  await mongoose.connect(uri, {
    // Recommended options (as of Mongoose 8)
    serverSelectionTimeoutMS: 5000,
  });

  console.info('✅ Connected to MongoDB');
}

module.exports = { connectDB };
```

### 5.3 `models/Subscriber.js`

```js
const { Schema, model } = require('mongoose');

const subscriberSchema = new Schema(
  {
    email: {
      type: String,
      required: true,
      unique: true,
      lowercase: true,
      trim: true,
      // Simple regex, real‑world you may want a more strict validation
      match: [/^\S+@\S+\.\S+$/, 'Invalid email address'],
    },
    name: {
      type: String,
      trim: true,
      maxlength: 120,
    },
    // Optional: a timestamp for when they subscribed
    subscribedAt: {
      type: Date,
      default: Date.now,
    },
  },
  { versionKey: false } // we don't need __v
);

// Index for fast lookup (email unique already creates one)
subscriberSchema.index({ email: 1 });

module.exports = model('Subscriber', subscriberSchema);
```

### 5.4 `middleware/validate.js`

Reusable validation middleware using **express‑validator**.

```js
const { body, validationResult } = require('express-validator');

/**
 * Validation chain for the newsletter subscription payload.
 */
const newsletterValidator = [
  body('email')
    .exists({ checkFalsy: true })
    .withMessage('Email is required')
    .bail()
    .isEmail()
    .withMessage('Must be a valid email address')
    .normalizeEmail({ all_lowercase: true }),

  body('name')
    .optional({ checkFalsy: true })
    .isString()
    .trim()
    .isLength({ max: 120 })
    .withMessage('Name must be less than 120 characters'),

  // Middleware to convert any validation errors to a JSON response
  (req, res, next) => {
    const errors = validationResult(req);
    if (!errors.isEmpty())
      return res.status(400).json({ error: 'Invalid payload', details: errors.array() });
    next();
  },
];

module.exports = { newsletterValidator };
```

### 5.5 `routes/newsletter.js`

```js
const express = require('express');
const router = express.Router();

const Subscriber = require('../models/Subscriber');
const { newsletterValidator } = require('../middleware/validate');

/**
 * @route   POST /api/newsletter
 * @desc    Add a subscriber (email + optional name)
 * @access  Public
 */
router.post('/', newsletterValidator, async (req, res) => {
  const { email, name } = req.body;

  try {
    // Upsert – if the email already exists we do nothing (idempotent)
    const [, created] = await Subscriber.updateOne(
      { email },                 // filter
      { $setOnInsert: { name } }, // only set on first insert
      { upsert: true }           // create if missing
    );

    // If a new document was inserted, `created` will be true (Mongo 5+)
    // For older versions you can check `result.upsertedCount`.

    // Note: never send back the raw DB document (no _id, no timestamps)
    return res.json({ ok: true, created: !!created });
  } catch (err) {
    // Duplicate key error (race condition) – treat as success
    if (err.code === 11000) {
      return res.json({ ok: true, created: false });
    }
    console.error('🛑 Subscription error:', err);
    return res.status(500).json({ error: 'Could not save subscriber' });
  }
});

module.exports = router;
```

