# Duplicate (idempotent) call
curl -X POST http://localhost:3000/api/newsletter \
  -H "Content-Type: application/json" \
  -d '{"email":"alice@example.com"}'

# → {"ok":true,"created":false}

# Validation errors
curl -X POST http://localhost:3000/api/newsletter \
  -H "Content-Type: application/json" \
  -d '{"email":"not‑an‑email"}'

# → {"error":"Invalid payload","details":[...]}
