/* --------------------------------------------------------------
   Simple Express server that stores a leaderboard in scores.txt
   -------------------------------------------------------------- */
const express = require('express');
const bodyParser = require('body-parser');
const fs = require('fs');
const path = require('path');
const helmet = require('helmet'); // security headers
const cors = require('cors');

const app = express();
const PORT = 3000;

// ── Middleware ─────────────────────────────────────────────────
app.use(helmet());               // X‑XSS‑Protection, CSP, etc.
app.use(cors({ origin: '*' })); // allow any origin for demo (lock down in prod)
app.use(bodyParser.json({ limit: '10kb' })); // tiny payloads only

// Path of the flat file (outside public folder!)
const SCORES_FILE = path.join(__dirname, 'scores.txt');
const MAX_TOP = 10; // how many entries we return

// ── Helper functions ───────────────────────────────────────────
/**
 * Append a line to scores.txt in a safe, atomic way.
 * Format per line: <timestamp>|<escaped-name>|<score>
 */
function storeScore(name, score) {
  // ---- 1️⃣ Validate / sanitize inputs ---------------------------------
  if (typeof name !== 'string' || typeof score !== 'number') {
    throw new Error('Invalid payload');
  }

  // Trim whitespace, limit length, strip control chars
  name = name.trim().substring(0, 30); // max 30 chars
  if (!name) throw new Error('Name cannot be empty');

  // Remove any pipe `|` (our delimiter) and line breaks to avoid injection
  name = name.replace(/[|\r\n]/g, '');

  // ---- 2️⃣ Build line -------------------------------------------------
  const line = `${Date.now()}|${name}|${score}\n`;

  // ---- 3️⃣ Append atomically (fs.appendFile is already atomic on most OS) ----
  // Using a write lock to avoid race conditions when many users write at the same time
  const lockFile = SCORES_FILE + '.lock';
  // Simple spin lock (not the most efficient, but fine for demo)
  let attempts = 0;
  while (fs.existsSync(lockFile) && attempts < 50) {
    // wait 10 ms and try again
    Atomics.wait(new Int32Array(new SharedArrayBuffer(4)), 0, 0, 10);
    attempts++;
  }
  if (fs.existsSync(lockFile)) {
    throw new Error('Could not obtain write lock');
  }
  // Create lock file
  fs.writeFileSync(lockFile, process.pid.toString());

  try {
    fs.appendFileSync(SCORES_FILE, line, { encoding: 'utf8' });
  } finally {
    // Remove lock file
    fs.unlinkSync(lockFile);
  }
}

/**
 * Read scores.txt, sort by numeric score descending, return top N.
 */
function getTopScores() {
  if (!fs.existsSync(SCORES_FILE)) {
    return [];
  }

  const raw = fs.readFileSync(SCORES_FILE, 'utf8');
  const entries = raw
    .trim()
    .split('\n')
    .map(line => {
      const [ts, name, score] = line.split('|');
      return {
        timestamp: Number(ts),
        name: name,
        score: Number(score)
      };
    })
    .filter(e => !isNaN(e.score));

  // Sort highest score first, then most recent if tie
  entries.sort((a, b) => b.score - a.score || b.timestamp - a.timestamp);
  return entries.slice(0, MAX_TOP);
}

