```js
import sqlite3 from 'sqlite3';
import { open } from 'sqlite';
import path from 'path';
import { fileURLToPath } from 'url';
import fs from 'fs';

const __filename = fileURLToPath(import.meta.url);
const __dirname = path.dirname(__filename);

// Путь к файлу БД
const DB_PATH = path.join(__dirname, '../../data/database.sqlite');

// Если БД ещё не создана – создаём её (можно вынести в миграцию)
if (!fs.existsSync(DB_PATH)) {
  fs.mkdirSync(path.dirname(DB_PATH), { recursive: true });
}

// Открываем соединение с параметром **PRAGMA foreign_keys = ON**
export const getDB = async () => {
  const db = await open({
    filename: DB_PATH,
    driver: sqlite3.Database,
  });

  // Включаем foreign‑keys, задаём journal_mode=WAL для лучшей конкуренции
  await db.exec('PRAGMA foreign_keys = ON;');
  await db.exec('PRAGMA journal_mode = WAL;');

  // Защита от чтения/записи другими пользователями (Unix permission 600)
  fs.chmodSync(DB_PATH, 0o600);

  return db;
};
```

### Защита на уровне SQLite  

| Мера | Описание |
|------|----------|
| `PRAGMA foreign_keys = ON` | Защищает от «orphaned» записей. |
| `journal_mode = WAL` | Позволяет нескольким процессам читать/писать без блокировок. |
| `chmod 600` | Файл БД доступен только процессу, запущенному от текущего пользователя (низкий риск компрометации файловой системы). |
| **Подготовленные запросы** (в `userModel.js`) | Защищают от **SQL‑инъекций**. |

