import { getDB } from '../config/db.js';
import bcrypt from 'bcrypt';
import { SALT_ROUNDS } from '../utils/config.js'; // читаем из .env

// ---------- CREATE TABLE (один‑раз) ----------
export const initUserTable = async () => {
  const db = await getDB();
  await db.exec(`
    CREATE TABLE IF NOT EXISTS users (
      id INTEGER PRIMARY KEY AUTOINCREMENT,
      email TEXT NOT NULL UNIQUE,
      password_hash TEXT NOT NULL,
      created_at DATETIME DEFAULT CURRENT_TIMESTAMP
    );
  `);
};

// ---------- CREATE USER ----------
export const createUser = async ({ email, password }) => {
  const db = await getDB();

  // Хешируем пароль (bcrypt – adaptive, стойкий к GPU‑атакам)
  const password_hash = await bcrypt.hash(password, SALT_ROUNDS);

  // Подготовленный запрос: защита от SQL‑инъекций
  const stmt = await db.prepare(
    'INSERT INTO users (email, password_hash) VALUES (?, ?)'
  );
  try {
    const result = await stmt.run(email, password_hash);
    return { id: result.lastID, email };
  } finally {
    await stmt.finalize();
  }
};

// ---------- FIND BY EMAIL ----------
export const findUserByEmail = async (email) => {
  const db = await getDB();
  return db.get('SELECT * FROM users WHERE email = ?', email);
};

// ---------- VERIFY PASSWORD ----------
export const verifyPassword = async (password, hash) => {
  // bcrypt.compare использует безопасный constant‑time сравнение
  return bcrypt.compare(password, hash);
};
```

**Security notes**

* **bcrypt** – выбираем `SALT_ROUNDS` минимум 12 (по умолчанию 12 в `bcrypt`). При росте вычислительной мощности можно увеличить.  
* Вставка параметров через `?` заставляет SQLite использовать **prepared statements**, исключая возможность инъекции.  
* Не сохраняем plaintext‑пароль, только хеш.  

