import {
  createUser,
  findUserByEmail,
  verifyPassword,
} from '../models/userModel.js';
import { validationResult } from 'express-validator';
import jwt from 'jsonwebtoken';
import { JWT_SECRET, JWT_EXPIRES_IN } from '../utils/config.js';

// ---------- REGISTER ----------
export const register = async (req, res) => {
  // 1️⃣ Валидация входных данных
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    return res.status(400).json({ errors: errors.array() });
  }

  const { email, password } = req.body;

  // 2️⃣ Проверка, существует ли уже пользователь
  const existing = await findUserByEmail(email);
  if (existing) {
    // Не раскрываем, что именно «email уже занят», чтобы не помогать подбору
    return res
      .status(409)
      .json({ message: 'Пользователь уже существует' });
  }

  // 3️⃣ Создание записи (хешируется внутри модели)
  const user = await createUser({ email, password });

  // 4️⃣ Выдаём JWT (по желанию, можно сразу не выдавать)
  const token = jwt.sign(
    { sub: user.id, email: user.email },
    JWT_SECRET,
    { expiresIn: JWT_EXPIRES_IN }
  );

  // 5️⃣ Отправляем ответ
  res.status(201).json({
    id: user.id,
    email: user.email,
    token,
  });
};

// ---------- LOGIN ----------
export const login = async (req, res) => {
  const errors = validationResult(req);
  if (!errors.isEmpty())
    return res.status(400).json({ errors: errors.array() });

  const { email, password } = req.body;

  const user = await findUserByEmail(email);
  // Не уточняем, что именно не найдено – «Invalid credentials» одинаково для email и пароля
  if (!user) {
    await fakeDelay(); // защита от timing attacks
    return res.status(401).json({ message: 'Invalid credentials' });
  }

  const passwordOk = await verifyPassword(password, user.password_hash);
  if (!passwordOk) {
    await fakeDelay();
    return res.status(401).json({ message: 'Invalid credentials' });
  }

  const token = jwt.sign(
    { sub: user.id, email: user.email },
    JWT_SECRET,
    { expiresIn: JWT_EXPIRES_IN }
  );

  res.json({ token });
};

// ---------- HELPERS ----------
const fakeDelay = async () => {
  // Делает небольшую случайную задержку, чтобы замедлить перебор
  const ms = Math.floor(Math.random() * 30) + 70;
  await new Promise((r) => setTimeout(r, ms));
};
```

