export default rateLimit({
  windowMs: 15 * 60 * 1000, // 15 минут
  max: 20, // максимум 20 запросов к /login или /register за окно
  message:
    'Слишком много попыток. Попробуйте позже.',
  standardHeaders: true,
  legacyHeaders: false,
});
```

* **Почему ограничиваем?**  
  * Уменьшаем поверхность для **credential stuffing** и **dictionary attacks**.  
  * 20 запросов за 15 минут – достаточный лимит для реального пользователя, но сдерживает автоматические скрипты.

### 7.3. Общие HTTP‑защиты  

В `app.js` ставим **helmet**, **cors**, **express.json()**, **morgan** и **error‑handler**.

**src/app.js**

```js
import express from 'express';
import helmet from 'helmet';
import cors from 'cors';
import morgan from 'morgan';
import authRoutes from './routes/authRoutes.js';
import { initUserTable } from './models/userModel.js';
import dotenv from 'dotenv';

dotenv.config(); // .env -> process.env

const app = express();

// ---------- Middleware ----------
app.use(helmet()); // Защита от XSS, clickjacking, MIME sniffing, HSTS и т.д.
app.use(cors({
  origin: process.env.CORS_ORIGIN || '*',
  methods: ['GET', 'POST'],
}));
app.use(express.json({ limit: '10kb' })); // ограничение размера payload
app.use(morgan('combined'));

// ---------- Routes ----------
app.use('/api/auth', authRoutes);

// ---------- 404 ----------
app.use((req, res) => {
  res.status(404).json({ message: 'Not found' });
});

// ---------- Ошибки ----------
app.use((err, req, res, next) => {
  console.error(err);
  // Не раскрываем стек в продакшене
  res.status(err.status || 500).json({
    message: process.env.NODE_ENV === 'production'
      ? 'Internal Server Error'
      : err.message,
  });
});

// ---------- Инициализация ----------
const PORT = process.env.PORT || 3000;
(async () => {
  try {
    await initUserTable(); // гарантируем создание таблицы
    app.listen(PORT, () => console.log(`🚀 Server on ${PORT}`));
  } catch (e) {
    console.error('Failed to start server', e);
    process.exit(1);
  }
})();
```

