### 3.8 Post Loader (`src/lib/posts.ts`)

```ts
import fs from 'node:fs';
import path from 'node:path';
import matter from 'gray-matter';
import { remark } from 'remark';
import html from 'remark-html';

export type PostMeta = {
  slug: string;
  title: string;
  date: string;
  excerpt?: string;
  coverImage?: string;
};

export type Post = PostMeta & {
  content: string; // rendered HTML string
};

const postsDir = path.join(process.cwd(), 'posts');

/** Get all MDX files, parse front‑matter, return sorted meta data */
export async function getAllPostsMeta(): Promise<PostMeta[]> {
  const fileNames = fs.readdirSync(postsDir).filter((f) => f.endsWith('.mdx'));

  const posts = await Promise.all(
    fileNames.map(async (file) => {
      const fullPath = path.join(postsDir, file);
      const fileContents = fs.readFileSync(fullPath, 'utf8');
      const { data, content } = matter(fileContents);

      // Autogenerate excerpt if not provided
      const excerpt =
        data.excerpt ??
        content
          .replace(/[\r\n]+/g, ' ')
          .replace(/^#+\s.*$/, '') // strip headings
          .slice(0, 200) + '…';

      return {
        slug: file.replace(/\.mdx?$/, ''),
        title: data.title ?? 'Untitled',
        date: data.date ?? new Date().toISOString(),
        excerpt,
        coverImage: data.coverImage ?? null
      } as PostMeta;
    })
  );

  // Sort newest first
  return posts.sort((a, b) => (a.date < b.date ? 1 : -1));
}

/** Get a single post (HTML string) + meta */
export async function getPostBySlug(slug: string): Promise<Post> {
  const fullPath = path.join(postsDir, `${slug}.mdx`);
  const fileContents = fs.readFileSync(fullPath, 'utf8');
  const { data, content } = matter(fileContents);

  const processedContent = await remark()
    .use(html)
    .process(content);
  const htmlContent = processedContent.toString();

  return {
    slug,
    title: data.title ?? 'Untitled',
    date: data.date ?? new Date().toISOString(),
    excerpt: data.excerpt ?? '',
    coverImage: data.coverImage ?? null,
    content: htmlContent
  };
}
```

