```tsx
import { notFound } from 'next/navigation';
import { getPostBySlug, getAllPostsMeta } from '@/lib/posts';
import type { Metadata } from 'next';
import Image from 'next/image';
import { remark } from 'remark';
import rehypeRaw from 'rehype-raw';
import rehypeStringify from 'rehype-stringify';
import rehypeParse from 'rehype-parse';
import rehypeSanitize from 'rehype-sanitize';

interface Props {
  params: { slug: string };
}

/** Enable static generation + fallback */
export async function generateStaticParams() {
  const posts = await getAllPostsMeta();
  return posts.map((p) => ({ slug: p.slug }));
}

/** Get post data, 404 if missing */
export async function generateMetadata({ params }: Props): Promise<Metadata> {
  const post = await getPostBySlug(params.slug);
  if (!post) return {};

  return {
    title: post.title,
    description: post.excerpt,
    openGraph: {
      title: post.title,
      description: post.excerpt,
      type: 'article',
      publishedTime: post.date,
      url: `https://your-username.github.io/my-blog/posts/${post.slug}`
    }
  };
}

export default async function PostPage({ params }: Props) {
  const post = await getPostBySlug(params.slug);
  if (!post) notFound();

  // Sanitize rendered HTML – prevents XSS (see Security Section 5)
  const sanitizedHtml = String(
    await remark()
      .use(rehypeParse, { fragment: true })
      .use(rehypeSanitize)
      .use(rehypeStringify)
      .process(post.content)
  );

  return (
    <article className="prose lg:prose-xl mx-auto">
      <h1>{post.title}</h1>
      <p className="text-gray-600">
        {new Date(post.date).toLocaleDateString(undefined, {
          year: 'numeric',
          month: 'long',
          day: 'numeric'
        })}
      </p>

      {post.coverImage && (
        <Image
          src={post.coverImage}
          alt={post.title}
          width={1200}
          height={600}
          className="my-4 rounded"
        />
      )}

      {/* Render sanitized HTML */}
      <div
        dangerouslySetInnerHTML={{ __html: sanitizedHtml }}
        className="mt-6"
      />
    </article>
  );
}
```

> **Why the extra sanitisation?**  
> MDX can embed raw HTML. Even if you trust yourself, a compromised author, typo, or copy‑paste from the web could introduce malicious markup. `rehype-sanitize` whitelists safe elements (the default schema is OWASP‑recommended). This is a core “security researcher” hardening step.

