### 3.3 `js/app.js`

```js
/* -------------------------------------------------------------
   Markup Calculator – core logic + Chart.js rendering
   ------------------------------------------------------------- */
'use strict';

// DOM elements
const form = document.getElementById('calc-form');
const resultSection = document.getElementById('result-section');
const sellingPriceEl = document.getElementById('selling-price');
const grossProfitEl = document.getElementById('gross-profit');
const grossMarginEl = document.getElementById('gross-margin');
const ctx = document.getElementById('markupChart').getContext('2d');

// Global Chart.js instance (created lazily)
let markupChart = null;

/**
 * Compute selling price, profit and margin.
 *
 * @param {number} cost          – cost price
 * @param {number|null} pct      – markup percent (null if not used)
 * @param {number|null} amount   – markup amount (null if not used)
 * @returns {{selling: number, profit: number, margin: number}}
 */
function calculate({ cost, pct = null, amount = null }) {
  // If both pct & amount are supplied, favour the percentage.
  let markupAmount = amount;
  if (pct !== null && Number.isFinite(pct) && pct > 0) {
    markupAmount = (cost * pct) / 100;
  }

  const selling = cost + (markupAmount || 0);
  const profit = selling - cost;
  const margin = selling > 0 ? (profit / selling) * 100 : 0;

  return {
    selling,
    profit,
    margin,
  };
}

/**
 * Build a simple bar‑chart showing the values we just computed.
 *
 * @param {{selling:number, profit:number, margin:number}} data
 */
function renderChart(data) {
  const chartData = {
    labels: ['Selling Price', 'Gross Profit', 'Gross Margin %'],
    datasets: [
      {
        label: 'Result',
        data: [
          data.selling.toFixed(2),
          data.profit.toFixed(2),
          data.margin.toFixed(2),
        ],
        backgroundColor: [
          'rgba(25, 135, 84, 0.7)',   // success (green)
          'rgba(13, 110, 253, 0.7)',  // primary (blue)
          'rgba(6, 176, 224, 0.7)',   // info (cyan)
        ],
        borderColor: [
          'rgba(25,135,84,1)',
          'rgba(13,110,253,1)',
          'rgba(6,176,224,1)',
        ],
        borderWidth: 1,
      },
    ],
  };

  if (markupChart) {
    markupChart.data = chartData;
    markupChart.update();
  } else {
    markupChart = new Chart(ctx, {
      type: 'bar',
      data: chartData,
      options: {
        responsive: true,
        plugins: {
          legend: { display: false },
          tooltip: {
            callbacks: {
              label: function (ctx) {
                const label = ctx.dataset.label || '';
                const value = ctx.parsed.y;
                return `${label} ${value}`;
              },
            },
          },
        },
        scales: {
          y: {
            beginAtZero: true,
            ticks: {
              // Show a £ sign for price/profit, % for margin
              callback: function (value, index, values) {
                const label = ctx.chart.data.labels[index];
                if (label.includes('%')) return `${value}%`;
                return `£${value}`;
              },
            },
          },
        },
      },
    });
  }
}

/**
 * Helper – safely parse a numeric input.
 *
 * @param {HTMLInputElement} el
 * @returns {number|null}
 */
function parseNumber(el) {
  const val = el.value.trim();
  if (val === '') return null;
  const num = Number(val);
  return Number.isFinite(num) && num >= 0 ? num : null;
}

/**
 * Reset UI – hide result area and destroy chart.
 */
function resetUI() {
  resultSection.classList.add('d-none');
  if (markupChart) {
    markupChart.destroy();
    markupChart = null;
  }
}

/* -------------------------------------------------------------
   Form handling (Bootstrap validation + our own logic)
   ------------------------------------------------------------- */
form.addEventListener('submit', (e) => {
  e.preventDefault();
  e.stopPropagation();

  // Bootstrap's built‑in validation UI
  if (!form.checkValidity()) {
    form.classList.add('was-validated');
    return;
  }

  // Grab and validate numbers
  const cost = parseNumber(document.getElementById('cost'));
  const pct = parseNumber(document.getElementById('markupPct'));
  const amt = parseNumber(document.getElementById('markupAmt'));

  if (cost === null) {
    alert('Cost price must be a non‑negative number.');
    return;
  }

  // At least one of % or amount must be supplied
  if (pct === null && amt === null) {
    alert('Enter either a markup % or a markup amount.');
    return;
  }

  // Calculate
  const { selling, profit, margin } = calculate({
    cost,
    pct,
    amount: amt,
  });

  // Populate UI (use locale formatting for nice commas)
  const locale = navigator.language || 'en-GB';
  const curOpts = { style: 'currency', currency: 'GBP', minimumFractionDigits: 2 };
  const pctOpts = { style: 'percent', minimumFractionDigits: 2 };

  sellingPriceEl.textContent = selling.toLocaleString(locale, curOpts);
  grossProfitEl.textContent = profit.toLocaleString(locale, curOpts);
  grossMarginEl.textContent = `${margin.toFixed(2)} %`;

  // Show result area & chart
  resultSection.classList.remove('d-none');
  renderChart({ selling, profit, margin });
});

/* Reset button – clear chart and validation states */
form.addEventListener('reset', () => {
  form.classList.remove('was-validated');
  resetUI();
});
