/**
 * @param {Object|null} q         - l'objet question (null = création)
 * @param {boolean} isNew         - true = création, false = édition
 */
function afficherFormulaireQuestion(q = null, isNew = true) {
    const idQuestionnaire = q ? q.questionnaire_id : $("#currentquestionnaire #questionnaire_id").val() || null;
    const type = q ? q.questionType : "simple"; // valeur par défaut

    const $form = $('#currenttask').empty();

    // hidden fields utiles
    $form.append(`<input type="hidden" id="question_id" value="${q ? q.id : ''}">`);
    $form.append(`<input type="hidden" id="question_uri" value="${q ? q.url : ''}">`);

    // titre
    $form.append(`
        <div><label>Titre : <input type="text" id="title" value="${q ? q.title : ''}"></label></div>
    `);

    // type (radio)
    $form.append(`
        <div>
            <label>Type :
                <input type="radio" name="type" id="type_simple" ${type === "simple" ? "checked" : ""}> Simple
                <input type="radio" name="type" id="type_multiple" ${type === "multiple" ? "checked" : ""}> Multiple
            </label>
        </div>
    `);

    // champs propres au type multiple
    const isMultiple = type === "multiple";

    $form.append(`
        <div id="multiple_fields" style="display:${isMultiple ? "block" : "none"};">
            <label>Proposition 1 : <input type="text" id="prop1" value="${q && isMultiple ? q.proposition1 : ''}"></label><br>
            <label>Proposition 2 : <input type="text" id="prop2" value="${q && isMultiple ? q.proposition2 : ''}"></label><br>
            <label>Réponse (1 ou 2) : <input type="number" min="1" max="2" id="reponse_multiple" value="${q && isMultiple ? q.reponse : ''}"></label>
        </div>
    `);

    // champ simple
    $form.append(`
        <div id="simple_field" style="display:${!isMultiple ? "block" : "none"};">
            <label>Réponse texte : <input type="text" id="reponse_simple" value="${q && !isMultiple ? q.reponse : ''}"></label>
        </div>
    `);

    // boutons
    const btnLabel = isNew ? "Créer la question" : "Modifier la question";
    $form.append(`<button id="btn_save">${btnLabel}</button>`);

    // écoute du changement de type
    $form.find('input[name="type"]').on('change', () => {
        const nowMultiple = $form.find('#type_multiple').is(':checked');
        $form.find('#multiple_fields').toggle(nowMultiple);
        $form.find('#simple_field').toggle(!nowMultiple);
    });

    // sauvegarde
    $form.find('#btn_save').on('click', async e => {
        e.preventDefault();
        await sauverQuestion(isNew);
    });
}
```

