```js
async function sauverQuestion(isNew) {
    const payload = {
        title: $("#title").val().trim(),
        questionType: $("#type_multiple").is(":checked") ? "multiple" : "simple",
        questionnaire_id: parseInt($("#questionnaire_id").val() || 0, 10)
    };

    if (payload.questionType === "multiple") {
        payload.proposition1 = $("#prop1").val().trim();
        payload.proposition2 = $("#prop2").val().trim();
        payload.reponse = parseInt($("#reponse_multiple").val(), 10);
    } else {
        payload.reponse = $("#reponse_simple").val().trim();
    }

    // validation très basique côté client
    if (!payload.title) return alert("Le titre est obligatoire");
    if (payload.questionType === "multiple" && (!payload.proposition1 || !payload.proposition2)) {
        return alert("Les deux propositions sont obligatoires");
    }

    try {
        let url, method;
        if (isNew) {
            url = "http://localhost:5000/quiz/api/v1.0/questions";
            method = "POST";
        } else {
            url = $("#question_uri").val(); // ex: http://…/questions/12
            method = "PUT";
        }

        const data = await apiFetch(url, { method, body: JSON.stringify(payload) });
        alert(isNew ? "Question créée !" : "Question mise à jour !");
        // on rafraîchit la liste du questionnaire en cours
        const qId = payload.questionnaire_id;
        chargerQuestionsDeQuestionnaire(qId);
    } catch (err) {
        console.error(err);
        alert("Erreur : " + err.message);
    }
}
```

