#!/usr/bin/env python3
"""
Simple safe calculator – supports +, -, *, /, %, ** and parentheses.
Built with security in mind: no `eval`, no arbitrary code execution,
strict input validation and a clear error model.
"""

import ast
import operator as op
import sys

# ----------------------------------------------------------------------
# Mapping of allowed AST nodes to the real Python operators
# ----------------------------------------------------------------------
ALLOWED_OPERATORS = {
    ast.Add: op.add,
    ast.Sub: op.sub,
    ast.Mult: op.mul,
    ast.Div: op.truediv,
    ast.Mod: op.mod,
    ast.Pow: op.pow,
    ast.USub: op.neg,
    ast.UAdd: op.pos,
    ast.FloorDiv: op.floordiv,
}

def safe_eval(expr: str) -> float:
    """
    Evaluate a mathematical expression safely.
    Only arithmetic operations & numeric literals are allowed.
    """
    try:
        tree = ast.parse(expr, mode='eval')
    except SyntaxError as e:
        raise ValueError(f"Syntax error in expression: {e}")

    def _eval(node):
        if isinstance(node, ast.Expression):
            return _eval(node.body)

        # Numbers (int, float, complex)
        if isinstance(node, ast.Constant):
            if isinstance(node.value, (int, float)):
                return node.value
            raise ValueError("Only int/float literals are allowed")

        # Unary operations (+/-)
        if isinstance(node, ast.UnaryOp) and type(node.op) in ALLOWED_OPERATORS:
            operand = _eval(node.operand)
            return ALLOWED_OPERATORS[type(node.op)](operand)

        # Binary operations (+, -, *, /, etc.)
        if isinstance(node, ast.BinOp) and type(node.op) in ALLOWED_OPERATORS:
            left = _eval(node.left)
            right = _eval(node.right)
            return ALLOWED_OPERATORS[type(node.op)](left, right)

        # Parentheses are just grouping – represented by the AST itself
        if isinstance(node, ast.Expr):
            return _eval(node.value)

        raise ValueError(f"Unsupported expression: {ast.dump(node)}")

    result = _eval(tree)
    return result


def repl():
    """
    Simple REPL (Read‑Eval‑Print Loop) for the calculator.
    Type 'quit', 'exit' or Ctrl‑D to stop.
    """
    print("🔢 Python Safe Calculator – type an expression, or 'quit' to exit")

    while True:
        try:
            expr = input("> ").strip()
        except (EOFError, KeyboardInterrupt):
            print("\nBye!")
            break

        if expr.lower() in ("quit", "exit"):
            print("Bye!")
            break
        if not expr:
            continue

        try:
            result = safe_eval(expr)
            print("= ", result)
        except Exception as e:
