class Tokenizer {
    constructor(text) {
        this.text = text.replace(/\s+/g, ''); // strip whitespace
        this.pos = 0;
    }

    peek() { return this.text[this.pos]; }

    next() {
        return this.text[this.pos++];
    }

    eof() { return this.pos >= this.text.length; }

    number() {
        let start = this.pos;
        while (!this.eof() && /[0-9.]/.test(this.peek())) this.next();
