            } else if ('+-*/%()'.includes(ch)) {
                tokens.push({type: ch, value: this.next()});
            } else if (ch === '*') {                     // handle ** exponentiation
                this.next();
                if (this.peek() === '*') {
                    this.next();
                    tokens.push({type: '**', value: '**'});
                } else {
                    tokens.push({type: '*', value: '*'});
                }
            } else {
                throw new SyntaxError(`Unexpected character "${ch}"`);
            }
        }
        return tokens;
    }
}

/* ------------------------------------------------------------------ */
/* Recursive‑descent parser that respects operator precedence          */
/* ------------------------------------------------------------------ */
class Parser {
    constructor(tokens) {
        this.tokens = tokens;
        this.pos = 0;
    }

    peek() { return this.tokens[this.pos]; }
    consume(type) {
        const token = this.peek();
        if (!token || token.type !== type) {
            throw new SyntaxError(`Expected "${type}" but got "${token ? token.type : 'EOF'}"`);
        }
        this.pos++;
        return token;
    }

    parseExpression() { return this.parseAddSub(); }

    parseAddSub() {
        let node = this.parseMulDivMod();
        while (this.peek() && (this.peek().type === '+' || this.peek().type === '-')) {
            const op = this.consume(this.peek().type).type;
            const right = this.parseMulDivMod();
            node = {type: 'BinaryExpression', op, left: node, right};
        }
        return node;
    }

    parseMulDivMod() {
        let node = this.parseExponent();
        while (this.peek() && (this.peek().type === '*' || this.peek().type === '/' || this.peek().type === '%')) {
            const op = this.consume(this.peek().type).type;
            const right = this.parseExponent();
            node = {type: 'BinaryExpression', op, left: node, right};
        }
        return node;
    }

    parseExponent() {
        // Right‑associative ** operator
        let node = this.parseUnary();
        if (this.peek() && this.peek().type === '**') {
            this.consume('**');
            const right = this.parseExponent(); // recurse for right‑associativity
            node = {type: 'BinaryExpression', op: '**', left: node, right};
        }
        return node;
    }

    parseUnary() {
        if (this.peek() && (this.peek().type === '+' || this.peek().type === '-')) {
            const op = this.consume(this.peek().type).type;
            const argument = this.parseUnary();
            return {type: 'UnaryExpression', op, argument};
        }
        return this.parsePrimary();
    }

    parsePrimary() {
        const token = this.peek();
        if (!token) throw new SyntaxError("Unexpected end of input");

        if (token.type === 'NUMBER') {
            this.consume('NUMBER');
            return {type: 'Literal', value: token.value};
        }

        if (token.type === '(') {
            this.consume('(');
            const expr = this.parseExpression();
            this.consume(')');
            return expr;
        }

        throw new SyntaxError(`Unexpected token "${token.type}"`);
    }
}

/* ------------------------------------------------------------------ */
/* Evaluator – walks the AST and computes a numeric result              */
/* ------------------------------------------------------------------ */
function evaluate(node) {
    switch (node.type) {
        case 'Literal':
            return node.value;
        case 'UnaryExpression': {
            const val = evaluate(node.argument);
            return node.op === '+' ? +val : -val;
        }
        case 'BinaryExpression': {
            const left = evaluate(node.left);
            const right = evaluate(node.right);
            switch (node.op) {
                case '+': return left + right;
                case '-': return left - right;
                case '*': return left * right;
                case '/': return left / right;
                case '%': return left % right;
                case '**': return Math.pow(left, right);
                default:
                    throw new Error(`Unsupported operator "${node.op}"`);
            }
        }
        default:
            throw new Error(`Unsupported node type "${node.type}"`);
    }
}

/* ------------------------------------------------------------------ */
/* UI glue – read the input, evaluate, display result or error          */
/* ------------------------------------------------------------------ */
const input = document.getElementById('calc');
const out   = document.getElementById('result');

function compute() {
    const expr = input.value.trim();
    if (!expr) {
        out.textContent = '';
        return;
    }
    try {
        const tokens = new Tokenizer(expr).getTokens();
        const ast    = new Parser(tokens).parseExpression();
        const value  = evaluate(ast);
