3. 将原来从 `<textarea>` 读取 JSON 的代码抽取为 `parseCookieData(text)`，复用在自动导入以及手动导入两种路径中。  
4. 为了兼容 Chrome/Firefox，使用 `chrome`（若不存在则使用 `browser`）统一的 API。

> **注意**  
> - 此代码假设 JSON（或 Netscape）文件已经放在扩展根目录（或 `chrome.runtime.getURL('/')` 能定位到的相对路径）下。  
> - 若扩展是 **MV3**，`fetch` 读取本地文件仍然受限，但在 **MV2** 或经由 `web_accessible_resources` 声明的情况下可以正常工作。请确保 `1.json、2.json …` 已在 `manifest.json` 的 `"web_accessible_resources"` 中列出。  

```javascript
document.addEventListener('DOMContentLoaded', () => {
    // --------------------------------------------------------------
    //   1️⃣ 变量声明 & 辅助函数
    // --------------------------------------------------------------
    let disableButtons = false;
    const containerCookie = document.getElementById('container-cookie');
    const notificationElement = document.getElementById('notification');

    const storage = chrome.storage && chrome.storage.local ? chrome.storage.local : browser.storage.local;

    /**
     * 解析 textarea（或直接读取的文件）中的内容，返回 Cookie 数组
     * 支持 JSON 与 Netscape 两种格式
     */
    function parseCookieData(text) {
        if (!text) return null;

        let cookies;
        try {
            cookies = JSON.parse(text);
        } catch (jsonErr) {
            // 不是合法 JSON，尝试 Netscape 格式
            try {
                const lines = text.split('\n');
                const tmp = [];
                for (let line of lines) {
                    line = line.trim();
                    if (!line.length || line[0] === '#') continue;

                    const parts = line.split('\t');
                    if (parts.length !== 7) throw new Error('Invalid netscape format');

                    tmp.push({
                        domain: parts[0],
                        path: parts[2],
                        secure: parts[3].toLowerCase() === 'true',
                        expiration: parts[4],
                        name: parts[5],
                        value: parts[6]
                    });
                }
                cookies = tmp;
            } catch (netscapeErr) {
                return null; // 两种格式都解析失败
            }
        }

        if (!Array.isArray(cookies)) return null;
        return cookies;
    }

    /**
     * 将 Cookie 数据写入浏览器
     */
    function importCookiesArray(cookies) {
        if (!Array.isArray(cookies)) return;

        for (let cookie of cookies) {
            // 使用当前标签页的 cookie store（容器）ID
            cookie.storeId = cookieHandler.currentTab.cookieStoreId;

            // sameSite 为 "unspecified" 时转换为 null（Chrome/Firefox 要求）
            if (cookie.sameSite && cookie.sameSite === 'unspecified') {
                cookie.sameSite = null;
            }

            try {
                cookieHandler.saveCookie(cookie, getCurrentTabUrl(), (error, saved) => {
                    if (error) {
                        sendNotification(error);
                    }
                });
            } catch (e) {
                // 这里不需要再抛出，保持继续处理后面的 cookie
                console.error('saveCookie error:', e);
            }
        }

        sendNotification(`Cookies were imported`);
        showCookiesForTab();
    }

    /**
     * 自动读取下一个 JSON 文件并导入
     * 文件名形如 "1.json", "2.json" …，若找不到则回环到 "1.json"
     */
    async function importNextJson() {
        // 取得上一次导入的编号（若不存在则从 1 开始）
        const { currentImportIndex = 1 } = await storage.get('currentImportIndex');
        let indexToTry = currentImportIndex;
        let fileContent = null;

        // ---------- 读取文件 ----------
        async function tryRead(idx) {
            const fileName = `${idx}.json`;
            const url = chrome.runtime.getURL(fileName);
            try {
                const resp = await fetch(url);
                if (!resp.ok) throw new Error('Not found');
                return await resp.text();
            } catch (e) {
                return null;
            }
        }

        // 先尝试当前 index
        fileContent = await tryRead(indexToTry);

        // 若当前文件不存在，则回环到 1 并再次尝试
        if (!fileContent) {
            indexToTry = 1;
            fileContent = await tryRead(indexToTry);
            if (!fileContent) {
                sendNotification('No JSON cookie files (1.json, 2.json …) could be found');
                return;
            }
        }

        // ---------- 解析并写入 ----------
        const cookies = parseCookieData(fileContent);
        if (!cookies) {
            // 解析失败，标记错误并退出
            sendNotification(`Could not parse ${indexToTry}.json`);
            // 给按钮一个错误的视觉提示（保持原有图标切换逻辑）
            const btnIcon = document.getElementById('save-import-cookie').querySelector('use');
            btnIcon.setAttribute('href', '../sprites/solid.svg#times');
            setTimeout(() => {
                btnIcon.setAttribute('href', '../sprites/solid.svg#file-import');
            }, 1500);
            return;
        }

        importCookiesArray(cookies);

        // ---------- 更新下次的索引 ----------
        // 下次尝试的编号是当前成功读取的编号 + 1
        const nextIndex = indexToTry + 1;
        await storage.set({ currentImportIndex: nextIndex });
    }

    // --------------------------------------------------------------
    //   2️⃣ 事件绑定
    // --------------------------------------------------------------

    document.getElementById('import-cookies').addEventListener('click', async () => {
        if (disableButtons) {
            return;
        }

        setPageTitle('Cookie Editor Plus - Import Cookies');

        disableButtons = true;
        Animate.transitionPage(containerCookie, containerCookie.firstChild, createHtmlFormImport(), 'left', () => {
            disableButtons = false;
        });

        document.getElementById('button-bar-default').classList.remove('active');
        document.getElementById('button-bar-import').classList.add('active');

        document.getElementById('content-import').focus();

        // **新增**：在打开导入页面的同时自动执行一次自动导入
        await importNextJson();

        return false;
    });

    document.getElementById('return-list-add').addEventListener('click', () => {
        showCookiesForTab();
    });
    document.getElementById('return-list-import').addEventListener('click', () => {
        showCookiesForTab();
    });

    containerCookie.addEventListener('submit', e => {
        e.preventDefault();
        saveCookieForm(e.target);
        return false;
    });

    document.getElementById('save-create-cookie').addEventListener('click', () => {
        saveCookieForm(document.querySelector('form'));
    });

    // -----------------------------------------------------------------
    //   3️⃣ 手动点击 “Import” 按钮（旧的 UI）仍保留原有功能
    // -----------------------------------------------------------------
    document.getElementById('save-import-cookie').addEventListener('click', e => {
        const buttonIcon = document.getElementById('save-import-cookie').querySelector('use');
        if (buttonIcon.getAttribute("href") !== "../sprites/solid.svg#file-import") {
            return;
        }

        const json = document.querySelector('textarea').value;
        const cookies = parseCookieData(json);

        if (!cookies) {
            sendNotification("Could not parse the value");
            buttonIcon.setAttribute("href", "../sprites/solid.svg#times");
            setTimeout(() => {
                buttonIcon.setAttribute("href", "../sprites/solid.svg#file-import");
            }, 1500);
            return;
        }

        importCookiesArray(cookies);
    });

    // -----------------------------------------------------------------
    //   4️⃣ 其它已存在的 UI 逻辑
    // -----------------------------------------------------------------
    document.querySelector('#advanced-toggle-all input').addEventListener('change', function () {
        showAllAdvanced = this.checked;
        browserDetector.getApi().storage.local.set({ showAllAdvanced: showAllAdvanced });
        showCookiesForTab();
    });

    notificationElement.addEventListener('animationend', e => {
        if (notificationElement.classList.contains('fadeInUp')) {
            return;
        }

        triggerNotification();
    });

    document.getElementById('notification-dismiss').addEventListener('click', e => {
        hideNotification();
    });

    // --------------------------------------------------------------
    //   5️⃣ 初始化
    // --------------------------------------------------------------
    initWindow();
    showCookiesForTab();
    adjustWidthIfSmaller();

    if (chrome && chrome.runtime && chrome.runtime.getBrowserInfo) {
        chrome.runtime.getBrowserInfo(function (info) {
            const mainVersion = info.version.split('.')[0];
            if (mainVersion < 57) {
                containerCookie.style.height = '600px';
            }
        });
    }

    // Bugfix/hotfix for Chrome 84. Let's remove this once Chrome 90 or later is released
    if (browserDetector.isChrome()) {
        document.querySelectorAll('svg').forEach(x => { x.innerHTML = x.innerHTML });
    }
});
```

### 说明

| 位置 | 变化内容 |
|------|----------|
| `import-cookies` click handler | 在页面切换完毕后 **立即调用 `importNextJson()`**，实现自动导入。 |
| 新增函数 `parseCookieData` | 把原本在 “手动导入” 里重复出现的 JSON / Netscape 解析代码抽离，供两种路径共用。 |
| 新增函数 `importCookiesArray` | 把原本在 “手动导入” 里对每个 cookie 调 `cookieHandler.saveCookie` 的逻辑抽离。 |
| 新增函数 `importNextJson` | 负责读取 `1.json、2.json …`、解析、写入、错误提示、并把下次要使用的文件编号写回 `chrome.storage.local`。 |
| `save-import-cookie` click handler | 现在直接调用 `parseCookieData` 与 `importCookiesArray`，代码更简洁。 |
| 其余代码保持原有功能不变。 |

这样，**每次点击 “Import Cookies” 按钮** 时都会自动读取当前目录下的 `1.json、2.json …`（循环）并把其中的 cookie 导入浏览器，同时把已导入的文件编号保存下来，以便下次点击时继续导入下一个文件。祝你研究顺利！

