```js
// routes/index.js
const express = require('express');
const router = express.Router();
const Order = require('../models/Order');

// Helper middleware – protect routes
function ensureAuth(req, res, next) {
  if (req.isAuthenticated()) return next();
  res.redirect('/');
}

/* GET home – show login button or welcome */
router.get('/', (req, res) => {
  res.render('index', { user: req.user });
});

/* GET order page – only for logged‑in users */
router.get('/order', ensureAuth, (req, res) => {
  // simple static menu – you can pull this from DB later
  const menu = [
    { name: 'Pizza Margherita', price: 9.5 },
    { name: 'Cheeseburger', price: 7.0 },
    { name: 'Sushi Roll', price: 12.0 },
    { name: 'Caesar Salad', price: 6.5 },
  ];
  res.render('order', { user: req.user, menu });
});

/* POST order submission */
router.post('/order', ensureAuth, async (req, res) => {
  /*
    Expected form payload:
    items[0][name], items[0][qty], items[0][price] ...
  */
  const rawItems = req.body.items || [];
  const items = rawItems
    .filter((it) => Number(it.qty) > 0) // ignore zero qty
    .map((it) => ({
      name: it.name,
      qty: Number(it.qty),
      price: Number(it.price),
    }));

  const total = items.reduce((sum, it) => sum + it.qty * it.price, 0);

  const order = await Order.create({
    user: req.user._id,
    items,
    total,
  });

  res.render('order', {
    user: req.user,
    menu: [], // hide menu after order – optional
    success: `Your order (#${order._id}) has been placed! Total: $${total.toFixed(2)}`,
  });
});

module.exports = router;
```

### `routes/auth.js` (Google OAuth)

```js
// routes/auth.js
const express = require('express');
const router = express.Router();
const passport = require('passport');

/* GET /auth/google – start OAuth flow */
router.get(
  '/google',
  passport.authenticate('google', { scope: ['profile', 'email'] })
);

/* GET /auth/google/callback – Google redirects here */
router.get(
  '/google/callback',
  passport.authenticate('google', {
    failureRedirect: '/',
    successRedirect: '/order',
  })
);

/* GET /auth/logout – end session */
router.get('/logout', (req, res, next) => {
  req.logout((err) => {
    if (err) return next(err);
    res.redirect('/');
  });
});

module.exports = router;
```

