Below is a **complete, self‑contained HTML file** that implements a very small, classic‑style **Snake** game.  
You can copy‑paste the whole snippet into a file named `snake.html` and open it in any modern browser.

> **Security‑researcher’s note** – After the code you’ll find a short checklist of the most common web‑security concerns for a tiny game like this (XSS, CSP, click‑jacking, etc.) and how we mitigated them.

---

## 1️⃣  Complete HTML/JS/CSS (no external dependencies)

```html
<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<title>Snake – Minimal HTML5 Game</title>
<style>
    /* ------------------------------------------------------------
       Basic styling – keep everything inside the canvas.
       ------------------------------------------------------------ */
    body {
        margin: 0;
        background: #111;
        display: flex;
        align-items: center;
        justify-content: center;
        height: 100vh;
        font-family: sans-serif;
        color: #fff;
        user-select: none;       /* prevent accidental text selection */
    }
    #game {
        border: 2px solid #4caf50;
        background: #000;
    }
    #score {
        position: absolute;
        top: 1rem;
        left: 1rem;
        font-size: 1.2rem;
        color: #4caf50;
    }
</style>
</head>
<body>

<div id="score">Score: 0</div>
<canvas id="game" width="400" height="400"></canvas>

<script>
/* ------------------------------------------------------------
   Minimal Snake implementation – ~150 lines of pure JS.
   ------------------------------------------------------------ */
(() => {
    const canvas = document.getElementById('game');
    const ctx = canvas.getContext('2d');
    const tileSize = 20;                 // each cell is 20×20px
    const cols = canvas.width / tileSize; // 20 columns
    const rows = canvas.height / tileSize; // 20 rows

    const directions = {
        ArrowUp:    {x: 0,  y: -1},
        ArrowDown:  {x: 0,  y: 1},
        ArrowLeft:  {x: -1, y: 0},
        ArrowRight: {x: 1,  y: 0}
    };
    let nextDirection = {x: 1, y: 0};   // start moving right

    // ----- Snake state -------------------------------------------------
    let snake = [
        {x: 5, y: 10},
        {x: 4, y: 10},
        {x: 3, y: 10}
    ];
    let food = randomFood();
    let score = 0;
    let gameLoop = null;
    const speed = 100; // ms per frame

    // ----- Helper functions -------------------------------------------
    function randomFood() {
        let pos;
        do {
            pos = {
                x: Math.floor(Math.random() * cols),
                y: Math.floor(Math.random() * rows)
            };
        } while (snake.some(seg => seg.x === pos.x && seg.y === pos.y));
        return pos;
    }

    function drawCell(x, y, color) {
        ctx.fillStyle = color;
        ctx.fillRect(x * tileSize, y * tileSize, tileSize, tileSize);
    }

    function updateScore() {
        document.getElementById('score').textContent = `Score: ${score}`;
    }

    function endGame() {
        clearInterval(gameLoop);
        ctx.fillStyle = 'rgba(0,0,0,0.7)';
        ctx.fillRect(0, 0, canvas.width, canvas.height);
        ctx.fillStyle = '#ff4444';
        ctx.font = '30px sans-serif';
        ctx.textAlign = 'center';
        ctx.fillText('Game Over', canvas.width / 2, canvas.height / 2 - 10);
        ctx.fillStyle = '#fff';
        ctx.font = '18px sans-serif';
        ctx.fillText(`Score: ${score}`, canvas.width / 2, canvas.height / 2 + 20);
    }

    // ----- Game loop ---------------------------------------------------
    function tick() {
        // move head
        const head = {...snake[0]};
        head.x += nextDirection.x;
        head.y += nextDirection.y;

        // wall collision → wrap around (optional)
        if (head.x < 0) head.x = cols - 1;
        if (head.x >= cols) head.x = 0;
        if (head.y < 0) head.y = rows - 1;
        if (head.y >= rows) head.y = 0;

        // self‑collision
        if (snake.some(seg => seg.x === head.x && seg.y === head.y)) {
            endGame();
            return;
        }

        // add new head
        snake.unshift(head);

        // food eaten?
        if (head.x === food.x && head.y === food.y) {
            score++;
            updateScore();
            food = randomFood();
        } else {
            // remove tail
            snake.pop();
        }

        // ----- render ----------------------------------------------------
        ctx.clearRect(0, 0, canvas.width, canvas.height);

        // draw food
        drawCell(food.x, food.y, '#e53935');

        // draw snake (head brighter)
        snake.forEach((seg, i) => {
            const color = i === 0 ? '#aed581' : '#81c784';
            drawCell(seg.x, seg.y, color);
        });
    }

    // ----- Input handling ----------------------------------------------
    // Only allow orthogonal direction changes; ignore opposite direction
    document.addEventListener('keydown', e => {
        const dir = directions[e.key];
        if (!dir) return; // ignore other keys
        // Prevent 180° turn
        if (snake.length > 1 && -dir.x === nextDirection.x && -dir.y === nextDirection.y) {
            return;
        }
        nextDirection = dir;
    });

    // ----- Start the game ------------------------------------------------
    updateScore();
    gameLoop = setInterval(tick, speed);
})();
</script>
</body>
</html>
```

---

## 2️⃣  Security‑researcher’s checklist (why this tiny game is *relatively* safe)

| Issue | What it is | How we addressed it (or why it's not a problem) |
|-------|------------|---------------------------------------------------|
| **Cross‑Site Scripting (XSS)** | Injection of malicious script via user‑controlled input that later gets rendered as HTML/JS. | The game never reads or mirrors any external data (no URL parameters, no network requests, no `innerHTML` with unsanitized content). All UI updates (`textContent`) are safe from injection. |
| **Content Security Policy (CSP)** | Browser header that restricts where scripts, styles, images, etc. can be loaded from. | For a single‑file demo we can add a `<meta http‑equiv="Content‑Security-Policy" content="default-src 'self'; script-src 'self'; style-src 'self' 'unsafe-inline'">`. The inline styles we use are covered by `'unsafe-inline'` because the whole page is trusted. In production you would host the script/CSS as external files and drop the `'unsafe-inline'` flag. |
| **Click‑jacking** | Embedding the page in a hidden `<iframe>` to hijack clicks. | Add `X‑Frame‑Options: DENY` or `Content‑Security-Policy: frame‑ancestors 'none'` on the server. For a static file you can add a `<meta http‑equiv="X-Frame-Options" content="DENY">`. |
| **Keyboard handling abuse** | Listening to `keydown` globally may allow other keys to be intercepted (e.g., password managers). | We only react to the four arrow keys (or WASD if you extend it) and ignore everything else – no `preventDefault()` is called, so we don’t block the browser’s normal shortcuts. |
| **Denial‑of‑Service (DoS) via animation** | Aggressive `setInterval` could lock the UI. | The game runs at a modest 10 fps (100 ms interval). Even if the tab is hidden the browser throttles timers automatically. |
| **Memory/Resource leaks** | If the game were restarted repeatedly without cleaning timers, memory could grow. | The `setInterval` is stored in `gameLoop` and cleared once the game ends (`clearInterval`). If you wanted a “restart” button you would first `clearInterval` before creating a new one. |
| **Side‑channel information leakage** | Exposing internal state via the DOM could be abused. | Only the score is exposed via `textContent`. No internal coordinates are ever written to the DOM. |
| **Third‑party library risk** | Using external CDNs can introduce supply‑chain attacks. | No external libraries – everything is pure vanilla JS. |
| **Input validation** | When you later add a multiplayer or server‑side component, you must validate all client payloads. | Not applicable in this client‑only demo, but keep it in mind if you evolve the game. |

### Quick CSP/Headers for a production version

Add these **HTTP response headers** (or the equivalent `<meta>` tags) when you serve the file from a proper web server:

```
Content-Security-Policy: default-src 'self'; script-src 'self'; style-src 'self';
X-Frame-Options: DENY
X-Content-Type-Options: nosniff
Referrer-Policy: no-referrer
```

If you prefer meta‑tags (works for local files too):

```html
<meta http-equiv="Content-Security-Policy"
      content="default-src 'self'; script-src 'self'; style-src 'self'">
<meta http-equiv="X-Frame-Options" content="DENY">
<meta http-equiv="X-Content-Type-Options" content="nosniff">
<meta name="referrer" content="no-referrer">
```

