```

**`index.js`**

```js
// index.js
const express = require('express');
const cors = require('cors');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const jwt = require('jsonwebtoken');
const Joi = require('joi');

const app = express();
app.use(express.json());

// ---------- Security middleware ----------
app.use(cors({ origin: 'https://my-frontend.example.com' })); // tighten in prod
app.use(helmet());            // sets X‑XSS‑Protection, CSP, etc.
const apiLimiter = rateLimit({
  windowMs: 60 * 60 * 1000,   // 1 hour
  max: 120,                  // limit each IP to 120 requests per hour
  message: { error: 'Too many requests, try later.' }
});
app.use('/api/', apiLimiter);

// ---------- Simple in‑memory DB ----------
let tasks = {};
let nextId = 1;

// ---------- JWT helpers ----------
const JWT_SECRET = process.env.JWT_SECRET || 'CHANGE_ME_TO_RANDOM';
function generateToken(username) {
  return jwt.sign({ sub: username }, JWT_SECRET, { expiresIn: '1h' });
}
function verifyToken(req, res, next) {
  const auth = req.headers.authorization;
  if (!auth?.startsWith('Bearer ')) return res.status(401).json({ error: 'Missing token' });
  const token = auth.slice(7);
  try {
    req.user = jwt.verify(token, JWT_SECRET);
    next();
  } catch (_) {
    return res.status(401).json({ error: 'Invalid token' });
  }
}

// ---------- Validation schemas ----------
const loginSchema = Joi.object({
  username: Joi.string().required(),
  password: Joi.string().required()
});
const taskCreateSchema = Joi.object({
  title: Joi.string().required(),
  completed: Joi.boolean().optional()
});
const taskPatchSchema = Joi.object({
  title: Joi.string(),
  completed: Joi.boolean()
}).min(1);

// ---------- Routes ----------
app.post('/api/v1/login', (req, res) => {
  const { error, value } = loginSchema.validate(req.body);
  if (error) return res.status(400).json({ error: error.message });

  const { username, password } = value;
  // *** Demo only: replace with real DB + hashed passwords ***
  if (username !== 'admin' || password !== 'secret')
    return res.status(401).json({ error: 'Invalid credentials' });

  const token = generateToken(username);
  res.json({ access_token: token });
});

app.use('/api/v1/tasks', verifyToken); // protect all task routes

app.get('/api/v1/tasks', (req, res) => {
  res.json(Object.values(tasks));
});

app.post('/api/v1/tasks', (req, res) => {
  const { error, value } = taskCreateSchema.validate(req.body);
  if (error) return res.status(400).json({ error: error.message });

  const task = { id: nextId++, completed: false, ...value };
  tasks[task.id] = task;
  res.status(201).json(task);
});

app.get('/api/v1/tasks/:id', (req, res) => {
  const task = tasks[req.params.id];
  if (!task) return res.status(404).json({ error: 'Not found' });
  res.json(task);
});

app.patch('/api/v1/tasks/:id', (req, res) => {
  const task = tasks[req.params.id];
  if (!task) return res.status(404).json({ error: 'Not found' });

  const { error, value } = taskPatchSchema.validate(req.body);
  if (error) return res.status(400).json({ error: error.message });

  Object.assign(task, value);
  res.json(task);
});

app.delete('/api/v1/tasks/:id', (req, res) => {
  if (!tasks[req.params.id]) return res.status(404).json({ error: 'Not found' });
  delete tasks[req.params.id];
  res.sendStatus(204);
});

// ---------- Global error handler ----------
app.use((err, _req, res, _next) => {
  console.error(err);
  res.status(500).json({ error: 'Internal Server Error' });
});

const PORT = process.env.PORT || 3000;
app.listen(PORT, () => console.log(`API listening on :${PORT}`));
```

**Run it**

