## 🎮 لعبة بسيطة – “Catch the Dot” (إمساك النقطة)

هذه اللعبة تُظهر **نقطة متحركة** داخل مساحة اللعب، وعلى اللاعب النقر عليها قبل أن تختفي.  
كل ما تحتاجه هو ملف HTML واحد يحتوي على HTML + CSS + JS، ومع ذلك سأتناول بعض **نصائح الأمان** التي يجب أخذها في الاعتبار عند نشر أي تطبيق ويب.

---

## 1️⃣ ملف الـHTML (index.html)

```html
<!DOCTYPE html>
<html lang="ar" dir="rtl">
<head>
    <meta charset="UTF-8">
    <title>Catch the Dot – لعبة بسيطة</title>

    <!-- ==== سياسات الأمان (CSP) ==== -->
    <!--
        * default-src 'self'؛ يمنع التحميل من أي مصدر خارجي غير الصفحة الحالية.
        * style-src 'self' 'unsafe-inline'؛ نسمح بالـ inline‑styles فقط لأننا نكتبها داخل <style>.
        * script-src 'self' 'unsafe-inline'؛ نسمح بالـ inline‑scripts فقط (هذا مثال تعليمي؛ في الإنتاج يفضَّل وضع الـ JS في ملف خارجي.
    -->
    <meta http-equiv="Content-Security-Policy"
          content="default-src 'self'; style-src 'self' 'unsafe-inline'; script-src 'self' 'unsafe-inline'">

    <style>
        /* --------- CSS الأساسي --------- */
        body {
            font-family: Arial, Helvetica, sans-serif;
            background: #f0f4f8;
            margin: 0;
            height: 100vh;
            display: flex;
            flex-direction: column;
            align-items: center;
            justify-content: center;
        }

        #gameArea {
            position: relative;
            width: 300px;
            height: 300px;
            background: #fff;
            border: 2px solid #333;
            overflow: hidden;
        }

        .dot {
            position: absolute;
            width: 30px;
            height: 30px;
            background: #ff4757;
            border-radius: 50%;
            cursor: pointer;
            user-select: none;
        }

        #score {
            margin-top: 1rem;
            font-size: 1.2rem;
        }
    </style>
</head>

<body>
    <h1>Catch the Dot 🎯</h1>
    <div id="gameArea"></div>
    <div id="score">النتيجة: 0</div>

    <script>
        /* --------- JavaScript الأساسي --------- */
        (function () {
            'use strict';   // إلزامية لاستخدام وضع الصارم

            const gameArea = document.getElementById('gameArea');
            const scoreEl  = document.getElementById('score');
            let score = 0;
            let dot   = null;
            let timer = null;

            // ==== 1️⃣ توليد نقطة عشوائية داخل مساحة اللعب ====
            function createDot() {
                // حذف النقطة القديمة إذا وجدت
                if (dot) dot.remove();

                dot = document.createElement('div');
                dot.className = 'dot';
                // موقع عشوائي داخل الـ gameArea
                const maxX = gameArea.clientWidth  - 30; // 30 = عرض النقطة
                const maxY = gameArea.clientHeight - 30;
                const x = Math.floor(Math.random() * maxX);
                const y = Math.floor(Math.random() * maxY);
                dot.style.left = `${x}px`;
                dot.style.top  = `${y}px`;

                // ==== 2️⃣ التعامل مع النقر على النقطة ====
                dot.addEventListener('click', () => {
                    score++;
                    updateScore();
                    // خلق نقطة جديدة مباشرةً بعد النقر
                    createDot();
                });

                gameArea.appendChild(dot);
            }

            // ==== 3️⃣ تحديث العنصر النصي للنتيجة ====
            function updateScore() {
                // لا نستخدم innerHTML لتجنب XSS، نص بسيط فقط
                scoreEl.textContent = `النتيجة: ${score}`;
            }

            // ==== 4️⃣ مؤقت لتغيير الموضع كل 2 ثانية إذا لم يُنقر على النقطة ====
            function startTimer() {
