### 3.2. JavaScript library: `Commands.js`

Create a **Web‑Resource** (type **Script (JScript)**) called `new_/AttachDoc/Commands.js`.  
Add the following code (fully commented).

```javascript
/* -------------------------------------------------------------
   Commands.js – used by the List Action ribbon button
   ------------------------------------------------------------- */

var AttachDoc = (function () {
    /**
     * Called from the ribbon button.
     * Reads selected record IDs, opens the dialog Web‑Resource.
     * @param {any} primaryControl – the form/grid control passed by the ribbon
     */
    function openDialog(primaryControl) {

        // 1️⃣ Get the selected record IDs (Unified Interface)
        const gridControl = primaryControl.getControl ? primaryControl.getControl("grid") : null;
        if (!gridControl) {
            // Classic UI fallback – use the Xrm.Page context
            Xrm.Utility.alertDialog("Could not locate the grid control.");
            return;
        }

        const selectedRows = gridControl.getSelectedRows();
        if (!selectedRows || selectedRows.getLength() === 0) {
            Xrm.Utility.alertDialog("Please select at least one record.");
            return;
        }

        // Collect GUIDs into an array
        const ids = [];
        selectedRows.forEach(function (row) {
            ids.push(row.getData().entity.getId().replace(/[{}]/g, ""));
        });

        // 2️⃣ Build the dialog URL and pass the IDs as query string (JSON‑encoded)
        const encodedIds = encodeURIComponent(JSON.stringify(ids));
        const dialogUrl = "/WebResources/new_/AttachDoc/Dialog.html?ids=" + encodedIds;

        // 3️⃣ Open the dialog (modal) – Width/Height are arbitrary, adjust as needed
        const dialogOptions = {
            height: 300,
            width: 460,
            title: "Attach Document to Selected Records"
        };

        Xrm.Navigation.openWebResource(dialogUrl, dialogOptions).then(
            function (returnValue) {
                // Dialog closed – you can optionally handle a return value
                if (returnValue && returnValue.success) {
                    Xrm.Utility.showToastMessage("Document attached to " + ids.length + " record(s).");
                }
            },
            function (error) {
                console.error(error);
                Xrm.Utility.alertDialog("An error occurred while opening the dialog.");
            }
        );
    }

    /**
     * Enable rule – returns true only when at least one row is selected.
     * The function name matches the rule defined in Ribbon Workbench.
     */
    function enable(primaryControl) {
        const gridControl = primaryControl.getControl ? primaryControl.getControl("grid") : null;
        if (!gridControl) return false;
        const selectedRows = gridControl.getSelectedRows();
        return selectedRows && selectedRows.getLength() > 0;
    }

    // Expose public functions
    return {
        openDialog: openDialog,
        enable: enable
    };
})();

/* Export for Ribbon Workbench */
function new_AttachDocumentToMultiple_OpenDialog(primaryControl) {
    AttachDoc.openDialog(primaryControl);
}
function new_AttachDocumentToMultiple_Enable(primaryControl) {
    return AttachDoc.enable(primaryControl);
}
```

**Key points**

* `gridControl.getSelectedRows()` works **only in the Unified Interface**. If you must support the Classic UI, you can fall back to the legacy method:  

  ```javascript
  var selectedIds = Xrm.Page.context.getQueryStringParameters().etc; // not needed for UI‑only
  ```

* The IDs are passed to the dialog as a **JSON‑encoded, URL‑escaped** string. This keeps the dialog completely stateless – no need for a hidden global variable.

