### 3.3. Dialog Web‑Resource: `Dialog.html`

Create a **HTML Web‑Resource** at `new_/AttachDoc/Dialog.html`.  
Add the following files (HTML, CSS, JavaScript). You can embed the CSS/JS directly, or split them into separate web‑resources – the sample below keeps everything in one file for simplicity.

```html
<!DOCTYPE html>
<html>
<head>
    <meta charset="utf-8" />
    <title>Attach Document to Multiple Records</title>

    <style>
        body {font-family: "Segoe UI", Tahoma, sans-serif; margin: 0; padding: 12px;}
        .container {max-width: 420px; margin: auto;}
        .row {margin-bottom: 12px;}
        label {display: block; font-weight: 600; margin-bottom: 4px;}
        input[type="file"] {width: 100%;}
        textarea {width: 100%; height: 80px; resize: vertical;}
        .actions {text-align: right; margin-top: 20px;}
        button {min-width: 80px; padding: 6px 12px; margin-left: 6px;}
        .progress {margin-top: 8px; display:none;}
    </style>
</head>
<body>
    <div class="container">
        <div class="row">
            <label for="fileInput">Select a file</label>
            <input type="file" id="fileInput" />
        </div>

        <div class="row">
            <label for="note">Optional note / description</label>
            <textarea id="note" placeholder="Add a comment (optional)"></textarea>
        </div>

        <div class="row progress" id="progressBar">
            <span id="progressText">Uploading…</span>
        </div>

        <div class="actions">
            <button id="cancelBtn" type="button">Cancel</button>
            <button id="submitBtn" type="button" disabled>Attach</button>
        </div>
    </div>

    <script>
        // ---------------------------------------------------------
        // Dialog JavaScript – runs inside the modal window
        // ---------------------------------------------------------

        // Parse the GUID array from the querystring
        const urlParams = new URLSearchParams(window.location.search);
        const ids = JSON.parse(decodeURIComponent(urlParams.get('ids') || '[]'));

        // UI elements
        const fileInput = document.getElementById('fileInput');
        const noteInput = document.getElementById('note');
        const submitBtn = document.getElementById('submitBtn');
        const cancelBtn = document.getElementById('cancelBtn');
        const progressBar = document.getElementById('progressBar');
        const progressText = document.getElementById('progressText');

        // Enable the Attach button only after a file is selected
        fileInput.addEventListener('change', () => {
            submitBtn.disabled = !fileInput.files.length;
        });

        cancelBtn.addEventListener('click', () => {
            // Close the dialog, no return value
            Xrm.Navigation.closeAlertDialog();
        });

        submitBtn.addEventListener('click', async () => {
            const file = fileInput.files[0];
            if (!file) {
                alert('Please select a file.');
                return;
            }

            // Show progress UI
            progressBar.style.display = 'block';
            submitBtn.disabled = true;
            cancelBtn.disabled = true;

            try {
                const base64 = await readFileAsBase64(file);
                // Remove the leading "data:<mime>;base64," part
                const base64Data = base64.split(',')[1];
                const mimeType = file.type || 'application/octet-stream';

                // Loop through every selected record and create an Annotation
                for (let i = 0; i < ids.length; i++) {
                    const targetId = ids[i];
                    await createAnnotation(targetId, file.name, mimeType, base64Data, noteInput.value);
                    progressText.textContent = `Uploaded to ${i + 1} of ${ids.length} record(s)…`;
                }

                // Success – close dialog and return a flag
                Xrm.Navigation.closeAlertDialog({ success: true });
            } catch (err) {
                console.error(err);
                alert('Error while uploading: ' + err.message);
                // Keep dialog open so user can retry
                submitBtn.disabled = false;
                cancelBtn.disabled = false;
                progressBar.style.display = 'none';
            }
        });

        /**
         * Reads the selected file as a Base64‑encoded data URL.
         * @param {File} file
         * @returns {Promise<string>} - data URL (e.g., "data:application/pdf;base64,....")
         */
        function readFileAsBase64(file) {
            return new Promise((resolve, reject) => {
                const reader = new FileReader();
                reader.onload = () => resolve(reader.result);
                reader.onerror = (e) => reject(e);
                reader.readAsDataURL(file);
            });
        }

        /**
         * Calls the Dynamics Web API to create an Annotation (document).
         *
         * @param {string} targetId      GUID of the record to attach the document to.
         * @param {string} fileName      Original file name (including extension).
         * @param {string} mimeType      MIME type, e.g., "application/pdf".
         * @param {string} base64Body   Base64‑encoded file content *without* the data:… prefix.
         * @param {string} [note]        Optional description / note.
         */
        async function createAnnotation(targetId, fileName, mimeType, base64Body, note) {
            const entitySetName = "annotations"; // logical collection name
            const apiUrl = Xrm.Utility.getGlobalContext().getClientUrl() + "/api/data/v9.2/" + entitySetName;

            // Build the payload
            const payload = {
                "filename": fileName,
                "subject": fileName,
                "mimetype": mimeType,
                "documentbody": base64Body,
                "objectid_account@odata.bind": `/accounts(${targetId})` // <-- CHANGE "account" to your target entity logical name
                // If you are using a custom entity, replace with: objectid_<logicalname>@odata.bind
            };

            // Optional note: add to the annotation's "notetext" field
            if (note && note.trim().length) {
                payload["notetext"] = note.trim();
            }

            const response = await fetch(apiUrl, {
                method: "POST",
                headers: {
                    "Accept": "application/json",
                    "Content-Type": "application/json; charset=utf-8",
                    "OData-MaxVersion": "4.0",
                    "OData-Version": "4.0",
                    "Prefer": "return=representation"
                },
                body: JSON.stringify(payload)
            });

            if (!response.ok) {
                const err = await response.text();
                throw new Error(`Web API error (${response.status}): ${err}`);
            }
        }

    </script>
</body>
</html>
```

#### Important notes about the **payload**:

| Field | Meaning | Required? |
|-------|---------|-----------|
| `filename` | The file name shown in the Note. | Yes |
| `subject` | Same as filename – you can leave it blank if you like. | No |
| `documentbody` | Base‑64 string **without** the `data:*;base64,` prefix. | Yes |
| `mimetype` | MIME type of the file (e.g., `application/pdf`). | Yes |
| `objectid_<entitylogicalname>@odata.bind` | **Binding** the annotation to the target record. Replace `<entitylogicalname>` with the logical name of the entity you are attaching to (e.g., `account`, `contact`, or `new_myentity`). | Yes |
| `notetext` | Optional free‑form description that appears in the Note. | No |

> 🛠️ **If you need to support *multiple* entity types** (e.g., the button can be placed on Grid of Account **and** Contact) you can determine the entity type at runtime via the querystring `etn` (entity type name) that the grid passes. Example:  

```javascript
