/*-------------------------------------------------------------
  Funções auxiliares de segurança
-------------------------------------------------------------*/

// Escape simples de HTML (evita XSS ao inserir resultados)
function escapeHTML(str) {
    const p = document.createElement('p');
    p.appendChild(document.createTextNode(str));
    return p.innerHTML;
}

/*-------------------------------------------------------------
  Lógica da busca
-------------------------------------------------------------*/

const form = document.getElementById('searchForm');
const input = document.getElementById('searchInput');
const btn = document.getElementById('searchBtn');
const resultsContainer = document.getElementById('results');

// Impede múltiplas requisições simultâneas
let fetchInProgress = false;

form.addEventListener('submit', async (e) => {
    e.preventDefault(); // evita recarregar a página

    const query = input.value.trim();

    // Validação básica do input
    if (!query) {
        alert('Digite algo para buscar.');
        return;
    }

    // Bloqueia nova requisição enquanto a atual não termina
    if (fetchInProgress) return;

    fetchInProgress = true;
    btn.disabled = true;
    btn.textContent = '🔄 Buscando…';

    // Limpa resultados anteriores
    resultsContainer.innerHTML = '<p>Carregando...</p>';

    try {
        // **ATENÇÃO**: Substitua a URL abaixo pelo seu endpoint real.
        // É recomendável usar HTTPS e autenticação (ex.: token JWT) se necessário.
        const response = await fetch(`/search?q=${encodeURIComponent(query)}`, {
            method: 'GET',
            credentials: 'same-origin', // envia cookies de sessão, se houver
            headers: {
                'Accept': 'application/json',
                // 'Authorization': `Bearer ${TOKEN}` // se precisar de auth
            }
        });

        if (!response.ok) {
            throw new Error(`Erro HTTP ${response.status}`);
        }

        const data = await response.json();

        // Exemplo de estrutura esperada:
        // data = [{ title: "...", snippet: "...", url: "..." }, ...]
        renderResults(data);
    } catch (err) {
        console.error(err);
        resultsContainer.innerHTML = `<p class="error">Falha ao buscar: ${escapeHTML(err.message)}</p>`;
    } finally {
        fetchInProgress = false;
        btn.disabled = false;
        btn.textContent = '🔍 Buscar';
    }
});

/*-------------------------------------------------------------
  Renderização dos resultados (HTML seguro)
-------------------------------------------------------------*/

function renderResults(items) {
    if (!Array.isArray(items) || items.length === 0) {
        resultsContainer.innerHTML = '<p>Nenhum resultado encontrado.</p>';
        return;
    }

    const fragment = document.createDocumentFragment();

    items.forEach(item => {
        const div = document.createElement('div');
        div.className = 'result-item';

        // Escapando tudo que vem do back‑end
        const title = escapeHTML(item.title || 'Sem título');
        const snippet = escapeHTML(item.snippet || '');
        const url = escapeHTML(item.url || '#');

        div.innerHTML = `
            <h3><a href="${url}" target="_blank" rel="noopener noreferrer">${title}</a></h3>
            <p>${snippet}</p>
        `;

        fragment.appendChild(div);
    });

    resultsContainer.innerHTML = ''; // limpa
    resultsContainer.appendChild(fragment);
}

/*-------------------------------------------------------------
  Acessibilidade – foco no campo de busca ao carregar a página
-------------------------------------------------------------*/
window.addEventListener('load', () => input.focus());
```

