import { fromEvent, ajax, of } from 'rxjs';
import { switchMap, map, catchError, tap } from 'rxjs/operators';

// ---------------------------------------------------------------------
// 1. DOM references (type‑safety)
const showBtn   = document.getElementById('showBtn')   as HTMLButtonElement;
const removeBtn = document.getElementById('removeBtn') as HTMLButtonElement;
const tbody     = document.querySelector('#dataTable tbody') as HTMLTableSectionElement;

// ---------------------------------------------------------------------
// 2. Configuration (avoid hard‑coding URLs in code)
