// ---------------------------------------------------------------------
// 3. Helper – Safe text node creation (prevents XSS)
function safeCell(text: unknown): HTMLTableCellElement {
  const td = document.createElement('td');
  // JSON values are primitives; we stringify them, then encode as text.
  // No innerHTML → no script execution.
  td.textContent = typeof text === 'object' ? JSON.stringify(text) : String(text);
  return td;
}

// ---------------------------------------------------------------------
// 4. Observable: click → ajax → render
const showClick$ = fromEvent(showBtn, 'click').pipe(
  // Disable the button while the request is in flight (UX + prevents double‑click DoS)
  tap(() => {
    showBtn.disabled = true;
    showBtn.textContent = 'Загружается…';
  }),

  switchMap(() =>
    ajax.getJSON<any[]>(JSON_URL).pipe(
      // Defensive: ensure we got an array, otherwise treat as error.
      map(payload => {
        if (!Array.isArray(payload)) {
          throw new Error('Unexpected JSON shape – expected an array');
        }
        return payload;
      }),
      catchError(err => {
        console.error('AJAX error:', err);
        // Propagate a user‑friendly error downstream.
        return of({ __error: true, message: err instanceof Error ? err.message : String(err) });
      })
    )
  ),

  tap(result => {
    // Re‑enable UI regardless of success/failure.
    showBtn.disabled = false;
    showBtn.textContent = 'Показать данные';
  })
);

// ---------------------------------------------------------------------
// 5. Subscription – render or show error
showClick$.subscribe(result => {
  if ((result as any).__error) {
    alert(`Не удалось загрузить данные:\n${(result as any).message}`);
    return;
  }

  // **Clear previous rows** – optional, you may want to append only.
  tbody.innerHTML = '';

  result.forEach((row, idx) => {
    const tr = document.createElement('tr');

    // 1️⃣ index column
    const idxCell = document.createElement('td');
    idxCell.textContent = (idx + 1).toString();
    tr.appendChild(idxCell);

    // 2️⃣ data columns (adjust to actual structure)
