const enabled = ['vip', 'mod', 'sub'];          // oder ['vip','mod']

// Hilfsfunktion: Schlüssel→Kurzform (z. B. "isMod" → "mod")
function keyToShort(key) {
  // Entfernt das führende "is" und macht den Rest klein
  return key.replace(/^is/, '').toLowerCase();
