  return Object.entries(userdata).some(([key, value]) => {
    if (!value) return false;               // false → ignorieren
    const short = keyToShort(key);          // "mod", "sub", "vip", …
    return enabled.includes(short);         // true, wenn im Array
  });
}

// Anwendung
