    public static void set(String tenantId) { CURRENT_TENANT.set(tenantId); }
    public static String get() {
        String id = CURRENT_TENANT.get();
        if (id == null) {
            throw new IllegalStateException("Tenant not bound to thread");
        }
        return id;
    }
    public static void clear() { CURRENT_TENANT.remove(); }
}
```

### 4.2 `TenantAspect.java`（拦截所有 `@RestController`）

```java
package com.example.redis.security;

import jakarta.servlet.http.HttpServletRequest;
import lombok.RequiredArgsConstructor;
import org.aspectj.lang.annotation.*;
import org.springframework.stereotype.Component;
import org.springframework.web.context.request.*;

@Aspect
@Component
@RequiredArgsConstructor
public class TenantAspect {

    @Pointcut("@within(org.springframework.web.bind.annotation.RestController)")
    public void controller() {}

    @Before("controller()")
    public void bindTenant() {
        ServletRequestAttributes attr = (ServletRequestAttributes) RequestContextHolder.getRequestAttributes();
        HttpServletRequest request = attr.getRequest();
        String tenant = request.getHeader("X-Tenant-ID");
        // 必要的白名单校验（示例：只允许 alphanumeric，长度 ≤ 20）
        if (tenant == null || !tenant.matches("[a-zA-Z0-9]{1,20}")) {
            throw new IllegalArgumentException("Invalid or missing tenant id");
        }
        TenantContext.set(tenant);
    }

    @After("controller()")
    public void unbindTenant() {
        TenantContext.clear();
    }
}
```

### 4.3 `TenantKeyPrefixSerializer.java`

```java
package com.example.redis.config;

import com.example.redis.security.TenantContext;
import org.springframework.data.redis.serializer.RedisSerializer;
import java.nio.charset.StandardCharsets;

public class TenantKeyPrefixSerializer implements RedisSerializer<String> {
    private static final byte[] EMPTY = new byte[0];
    @Override
    public byte[] serialize(String key) {
        if (key == null) return EMPTY;
        String prefixed = TenantContext.get() + ":" + key;
        return prefixed.getBytes(StandardCharsets.UTF_8);
    }
    @Override
    public String deserialize(byte[] bytes) {
        if (bytes == null) return null;
        String full = new String(bytes, StandardCharsets.UTF_8);
        int idx = full.indexOf(':');
        return idx >= 0 ? full.substring(idx + 1) : full;
    }
}
```

### 4.4 `RedisConfig.java`（单实例 + 前缀）

```java
package com.example.redis.config;

import org.springframework.beans.factory.annotation.Value;
import org.springframework.context.annotation.*;
import org.springframework.data.redis.connection.lettuce.*;
import org.springframework.data.redis.core.*;
import org.springframework.data.redis.serializer.*;

@Configuration
public class RedisConfig {

    @Bean
    public LettuceConnectionFactory lettuceConnectionFactory(
            @Value("${spring.redis.host}") String host,
            @Value("${spring.redis.port}") int port) {
        return new LettuceConnectionFactory(host, port);
    }

    @Bean
    public RedisTemplate<String, Object> redisTemplate(LettuceConnectionFactory cf) {
        RedisTemplate<String, Object> tpl = new RedisTemplate<>();
        tpl.setConnectionFactory(cf);
        // 前缀序列化器
        tpl.setKeySerializer(new TenantKeyPrefixSerializer());
        tpl.setHashKeySerializer(new TenantKeyPrefixSerializer());
        // JSON 序列化
        tpl.setValueSerializer(new GenericJackson2JsonRedisSerializer());
        tpl.setHashValueSerializer(new GenericJackson2JsonRedisSerializer());
        tpl.afterPropertiesSet();
        return tpl;
    }
}
```

### 4.5 `CacheService.java`

```java
package com.example.redis.service;

import lombok.RequiredArgsConstructor;
import org.springframework.data.redis.core.*;
import org.springframework.stereotype.Service;
import java.time.Duration;
import java.util.Optional;

@Service
@RequiredArgsConstructor
public class CacheService {

    private final RedisTemplate<String, Object> redisTemplate;

    public void put(String key, Object value, Duration ttl) {
        redisTemplate.opsForValue().set(key, value, ttl);
    }

    public Optional<Object> get(String key) {
        return Optional.ofNullable(redisTemplate.opsForValue().get(key));
    }

    public void delete(String key) {
        redisTemplate.delete(key);
    }
}
```

