  const saltRounds = Number(process.env.BCRYPT_SALT_ROUNDS) || 12;
  this.passwordHash = await bcrypt.hash(plainPwd, saltRounds);
};

userSchema.methods.validatePassword = async function (plainPwd) {
  return await bcrypt.compare(plainPwd, this.passwordHash);
};

/**
 * Account lockout helpers
 */
userSchema.virtual('isLocked').get(function () {
  return !!(this.lockUntil && this.lockUntil > Date.now());
});

userSchema.methods.incrementLoginAttempts = async function () {
  // Simple exponential back‑off
  const lockoutThreshold = 5;
  const lockoutTimeMs = 15 * 60 * 1000; // 15 min

  if (this.isLocked && this.lockUntil > Date.now()) {
    // Already locked, no need to increment
    return;
  }

  this.failedLoginAttempts += 1;
  if (this.failedLoginAttempts >= lockoutThreshold) {
    this.lockUntil = new Date(Date.now() + lockoutTimeMs);
  }
  await this.save();
};

/**
 * Pre‑save hook – guarantee email uniqueness (case‑insensitive)
 */
userSchema.pre('save', async function (next) {
  if (!this.isModified('email')) return next();

  const exists = await mongoose.models.User.findOne({
    email: this.email,
    _id: { $ne: this._id },
  }).collation({ locale: 'en', strength: 2 }); // case‑insensitive
  if (exists) {
    return next(new Error('Email already in use'));
  }
  next();
});

const User = mongoose.model('User', userSchema);

// ---------------------------------------------------------------------
// 2️⃣  CHAT ROOM / CONVERSATION SCHEMA
// ---------------------------------------------------------------------
/**
 * A “room” can be:
 *  – a direct 1‑to‑1 conversation (type: "dm")
 *  – a group chat (type: "group")
 *  – a broadcast channel (type: "channel")
 *
 * ACL is stored as an array of user references with a role per member.
 */
const memberSchema = new mongoose.Schema(
  {
    userId: {
      type: String,
      required: true,
      ref: 'User',
    },
    // Permissions specific to this room
    role: {
      type: String,
      enum: ['owner', 'admin', 'member', 'guest'],
      default: 'member',
    },
    joinedAt: { type: Date, default: Date.now },
  },
  { _id: false }
);

const roomSchema = new mongoose.Schema(
  {
    // Human readable name (optional for DMs)
    name: {
      type: String,
      trim: true,
      maxlength: 100,
      default: '',
    },

    // Type of room
    type: {
      type: String,
      enum: ['dm', 'group', 'channel'],
      required: true,
    },

    // Owner – immutable after creation (except via admin actions)
    ownerId: {
      type: String,
      required: true,
      immutable: true,
      ref: 'User',
    },

    // Membership list (indexed for fast look‑ups)
    members: {
      type: [memberSchema],
      default: [],
    },

    // Public / private flag – private rooms require explicit invites
    isPublic: {
      type: Boolean,
      default: false,
    },

    // Optional description
    description: {
      type: String,
      trim: true,
      maxlength: 500,
    },

    // Optional avatar / image url
    avatarUrl: {
      type: String,
      trim: true,
      validate: {
        validator: validator.isURL,
        message: props => `${props.value} is not a valid URL`,
      },
    },

    // Soft‑delete flag (for GDPR “right to be forgotten”)
    deletedAt: { type: Date, default: null },
  },
  {
    timestamps: true,
    collection: 'rooms',
  }
);

/**
 * Indexes for fast permission checks:
 *   - Find all rooms a user belongs to (member.userId)
 *   - Enforce unique DM per pair of users.
 */
roomSchema.index({ 'members.userId': 1, type: 1 }, { name: 'idx_member_user_type' });
roomSchema.index(
  { type: 1, ownerId: 1, 'members.userId': 1 },
  {
    unique: true,
    partialFilterExpression: { type: 'dm' },
    name: 'unique_dm_pair',
  }
);

/**
 * Helper: is user a member with at least a given role?
 */
roomSchema.methods.hasMember = function (userId, minRole = 'member') {
  const roleHierarchy = { guest: 0, member: 1, admin: 2, owner: 3 };
  const member = this.members.find(m => m.userId === userId);
  if (!member) return false;
  return roleHierarchy[member.role] >= roleHierarchy[minRole];
};

/**
 * Helper: add a member (idempotent)
 */
roomSchema.methods.addMember = async function (userId, role = 'member') {
  if (this.members.some(m => m.userId === userId)) {
    // Update role if needed
    this.members = this.members.map(m =>
      m.userId === userId ? { ...m, role } : m
    );
  } else {
    this.members.push({ userId, role });
  }
  await this.save();
};

const Room = mongoose.model('Room', roomSchema);

// ---------------------------------------------------------------------
// 3️⃣  MESSAGE SCHEMA (append‑only, immutable)
// ---------------------------------------------------------------------
/**
 * Message fields:
 *   - content: plain text or a JSON blob (encrypted if `sensitive:true`)
 *   - attachments: optional array of file references (stored in object storage)
 *   - reactions: stored as sub‑documents (userId + emoji) – indexed for quick counts
 *   - editedAt: nullable (if you support editing)
 *
 * **Security note** – message content is stored *encrypted at rest* using
 * MongoDB client‑side field level encryption (FLE) or, for simpler setups,
 * a custom AES‑256 wrapper (`utils/crypto.js`).  The encryption key never
 * touches the DB process; it lives only in the application runtime / KMS.
 */
const reactionSchema = new mongoose.Schema(
  {
    userId: { type: String, required: true, ref: 'User' },
    emoji: {
      type: String,
      required: true,
      maxlength: 6, // allow unicode emoji, not longer than 6 chars
    },
    createdAt: { type: Date, default: Date.now },
  },
  { _id: false }
);

const messageSchema = new mongoose.Schema(
  {
    // Human readable incremental ID for UI (optional) – can be generated via a
    // separate sequence collection if you need strictly monotonic per‑room IDs.
    // Not required for security.
    roomId: { type: mongoose.Schema.Types.ObjectId, required: true, ref: 'Room' },

    // Sender – immutable
    senderId: { type: String, required: true, ref: 'User', immutable: true },

    // Content – encrypted if `sensitive` flag is true.
    // As a fallback, we store raw text but we always HTML‑escape before rendering.
    content: {
      type: String,
      required: true,
      set: v => (v ? v.trim() : v), // simple trim before encryption
    },

    // Flag to indicate that the content is sensitive (PII, health info, etc.)
    // When true we encrypt on write and decrypt on read.
    sensitive: { type: Boolean, default: false },

    // Attachments (array of file IDs stored in external object storage)
    attachments: [{ type: String }],

    // Optional edit tracking
    editedAt: { type: Date, default: null },

    // Reactions (sub‑documents)
    reactions: { type: [reactionSchema], default: [] },

    // Optional client‑side message UUID (idempotency key)
    clientMessageId: { type: String, index: true },

    // Auditing info – IP address + user‑agent (stringified)
    meta: {
      ip: { type: String, default: '' },
      userAgent: { type: String, default: '' },
    },
  },
  {
    timestamps: true, // createdAt, updatedAt (updatedAt will change on edits)
    collection: 'messages',
    // Make the document immutable after creation, except for allowed fields
    // (editedAt, reactions, meta). Mongoose does not have a built‑in “immutable
    // except X” – we implement it via a pre‑save guard.
  }
);

/**
 * Ensure ONLY allowed fields can be changed after creation.
 */
messageSchema.pre('save', function (next) {
  if (!this.isNew) {
    // Disallow changes to any fields except the whitelisted ones
    const allowedUpdates = ['editedAt', 'reactions', 'meta'];
    const modified = this.modifiedPaths().filter(p => !allowedUpdates.includes(p));
    if (modified.length) {
      return next(
        new Error(`Attempt to modify immutable fields: ${modified.join(', ')}`)
      );
    }
  }
  next();
});

/**
 * Indexes for fast retrieval
 *   - By room (most common)
 *   - By sender (for moderation / audit)
 *   - By clientMessageId (deduplication)
 */
messageSchema.index({ roomId: 1, createdAt: -1 }, { name: 'idx_room_created' });
messageSchema.index({ senderId: 1, createdAt: -1 }, { name: 'idx_sender_created' });
messageSchema.index({ clientMessageId: 1 }, { unique: true, sparse: true });

/**
 * Pre‑save encryption for `content` when `sensitive:true`.
 * Uses a thin wrapper around the native Node Crypto module.
 */
messageSchema.pre('save', async function (next) {
  if (this.sensitive && this.isModified('content')) {
    try {
      this.content = encrypt(this.content); // encrypt returns base64 string
    } catch (e) {
      return next(e);
    }
  }
  next();
});

/**
 * Decrypt `content` on read (via a virtual).  Never expose the raw cipher text.
 */
messageSchema.virtual('plainContent').get(function () {
  if (!this.sensitive) return this.content; // not encrypted
  // If you are using client‑side field‑level encryption (MongoDB FLE), this
  // virtual is unnecessary – the driver will transparently decrypt.
  try {
    return decrypt(this.content);
  } catch (e) {
    // Log and return a placeholder; never throw to caller (avoid DoS)
    console.warn('Failed to decrypt message', this._id, e);
    return '[decryption error]';
  }
});

const Message = mongoose.model('Message', messageSchema);

export { User, Room, Message };
```

### Crypto Helper (`src/utils/crypto.js`)

```js
// src/utils/crypto.js
import crypto from 'crypto';
import dotenv from 'dotenv';
dotenv.config();

/**
 * AES‑256‑GCM with a 32‑byte key loaded from environment (or a KMS).
 * The key MUST be 32 bytes (base64 or hex).  Use a separate key per
 * environment (dev/staging/prod).  Rotate keys periodically.
 */
const KEY = Buffer.from(process.env.CHAT_MESSAGE_ENC_KEY, 'base64'); // 32‑byte

if (!KEY || KEY.length !== 32) {
  throw new Error('Invalid CHAT_MESSAGE_ENC_KEY – must be 32‑byte base64');
}

/**
 * Encrypt a plain‑text string → base64(ciphertext|iv|authTag)
 */
export function encrypt(plaintext) {
  const iv = crypto.randomBytes(12); // 96‑bit nonce for GCM
  const cipher = crypto.createCipheriv('aes-256-gcm', KEY, iv);
  const ciphertext = Buffer.concat([cipher.update(plaintext, 'utf8'), cipher.final()]);
  const authTag = cipher.getAuthTag();

  // Store as iv|authTag|ciphertext (fixed order)
  return Buffer.concat([iv, authTag, ciphertext]).toString('base64');
}

/**
 * Decrypt base64 string produced by `encrypt`
 */
export function decrypt(b64) {
  const data = Buffer.from(b64, 'base64');
  const iv = data.slice(0, 12);
  const authTag = data.slice(12, 28);
  const ciphertext = data.slice(28);

  const decipher = crypto.createDecipheriv('aes-256-gcm', KEY, iv);
  decipher.setAuthTag(authTag);
  const plaintext = Buffer.concat([decipher.update(ciphertext), decipher.final()]);
  return plaintext.toString('utf8');
}
```

**Important:**  
* Store `CHAT_MESSAGE_ENC_KEY` in a secret manager (AWS Secrets Manager, HashiCorp Vault, Azure Key Vault) – never commit it to source control.  
* In production you can switch to MongoDB **Client‑Side Field Level Encryption** (FLE) which stores the encrypted values directly in the BSON document using a key store (KMIP, AWS KMS) – the wrapper above is just a portable example.

