## 3️⃣ SECURE DATA‑ACCESS LAYER (Services / Repositories)

Below we illustrate safe, permission‑checked helpers that you can expose via an Express / Fastify API.

```js
// src/services/userService.js
import { User } from '../models/index.js';
import jwt from 'jsonwebtoken';
import rateLimit from 'express-rate-limit';
import validator from 'validator';
import dotenv from 'dotenv';
dotenv.config();

/**
 * Register a new user – rate‑limited endpoint.
 */
export async function registerUser({ email, password, displayName }) {
  // Basic server‑side validation
  if (!validator.isEmail(email) || !validator.isLength(password, { min: 8 }))
    throw new Error('Invalid input');

  const user = new User({ email, displayName });
  await user.setPassword(password);
  await user.save();
  return { userId: user.userId, email: user.email };
}

/**
 * Authenticate – returns a signed JWT (short‑lived) + refresh token.
 */
export async function loginUser({ email, password, ip, userAgent }) {
  const user = await User.findOne({ email }).select('+passwordHash');
  if (!user) throw new Error('Invalid credentials');

  // Account lockout check
  if (user.isLocked) throw new Error('Account locked – try later');

  const ok = await user.validatePassword(password);
  if (!ok) {
    await user.incrementLoginAttempts();
    throw new Error('Invalid credentials');
  }

  // Reset failed attempts on success
  user.failedLoginAttempts = 0;
  user.lockUntil = null;
  await user.save();

  // Issue JWT – payload MUST be minimal
  const tokenPayload = {
    sub: user.userId,
    role: user.role,
    // Optional: short‑term scopes
  };
  const token = jwt.sign(tokenPayload, process.env.JWT_SECRET, {
    expiresIn: '15m', // short‑lived; refresh token for longer sessions
    audience: 'chat-app',
    issuer: 'my-chat-service',
  });

  // Store a refresh token (httpOnly cookie) if you need long‑term sessions.
  return { token, userId: user.userId };
}

/**
 * Middleware – verify JWT & attach `req.user`
 */
export function authenticateJWT(req, res, next) {
  const auth = req.headers.authorization;
  if (!auth?.startsWith('Bearer ')) return res.sendStatus(401);
  const token = auth.slice(7);
  try {
    const payload = jwt.verify(token, process.env.JWT_SECRET, {
      audience: 'chat-app',
      issuer: 'my-chat-service',
    });
    req.user = payload; // { sub, role }
    next();
  } catch (e) {
    return res.sendStatus(401);
  }
}

/**
 * Simple rate limiter for login/register (express middleware)
 */
export const authRateLimiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 min
  max: 10, // limit each IP to 10 requests per window
  standardHeaders: true,
  legacyHeaders: false,
  message: 'Too many attempts, please try again later.',
});
```

### Room Service (RBAC enforcement)

```js
// src/services/roomService.js
import { Room } from '../models/index.js';
import { Types } from 'mongoose';

export async function createRoom({ name, type, ownerId, isPublic = false, memberIds = [] }) {
  // Basic validation
  if (!['dm', 'group', 'channel'].includes(type))
    throw new Error('Invalid room type');

  const room = new Room({
    name,
    type,
    ownerId,
    isPublic,
    members: [{ userId: ownerId, role: 'owner' }],
  });

  // Add extra members (skip owner – already added)
  for (const uid of memberIds) {
    if (uid !== ownerId) {
      room.members.push({ userId: uid, role: type === 'dm' ? 'member' : 'member' });
    }
  }
  await room.save();
  return room;
}

/**
 * Verify that `requesterId` can read a room.
 */
export async function canReadRoom(roomId, requesterId) {
  const room = await Room.findById(roomId).lean();
  if (!room) return false;

  // Public rooms are readable by anyone
  if (room.isPublic) return true;

  // Private rooms – check membership
  return room.members.some(m => m.userId === requesterId);
}

/**
 * Verify that `requesterId` can write (post message) in a room.
 */
export async function canWriteRoom(roomId, requesterId) {
  const room = await Room.findById(roomId).lean();
  if (!room) return false;

  // Owner, admin, member can write; guests cannot.
  const member = room.members.find(m => m.userId === requesterId);
  if (!member) return false;

  const writableRoles = ['owner', 'admin', 'member'];
  return writableRoles.includes(member.role);
}
```

### Message Service (append‑only, safe writes)

```js
// src/services/messageService.js
import { Message } from '../models/index.js';
import { Types } from 'mongoose';

/**
 * Post a new message.  All validation happens here.
 *
 * `opts` contains:
 *   - roomId (ObjectId string)
 *   - senderId (userId)
 *   - content (string) – must be plain text, not HTML.
 *   - sensitive (bool) – true if PII is inside.
 *   - attachments (array of file IDs) – optional
 *   - clientMessageId (string) – provided by client for idempotency.
 *   - meta – { ip, userAgent }
 */
export async function postMessage(opts) {
  const {
    roomId,
    senderId,
    content,
    sensitive = false,
    attachments = [],
    clientMessageId,
    meta = {},
  } = opts;

  // Basic checks
  if (!Types.ObjectId.isValid(roomId)) throw new Error('Invalid roomId');
  if (!content || typeof content !== 'string') throw new Error('Content required');

  // Sanitize – strip dangerous characters, limit length
  const sanitized = content
    .trim()
    .substring(0, 2000); // 2 KB max per message

  // Ensure the user is allowed to write in the room (call the RBAC service)
  const canWrite = await import('./roomService.js').then(m => m.canWriteRoom(roomId, senderId));
  if (!canWrite) throw new Error('Forbidden: cannot write to this room');

  const msg = new Message({
    roomId,
    senderId,
    content: sanitized,
    sensitive,
    attachments,
    clientMessageId,
    meta,
  });

  // Mongoose will run its pre‑save hooks (encryption, immutability checks)
  await msg.save();
  return msg;
}

/**
 * Get paginated messages for a room.
 *
 * Parameters:
 *   - roomId (ObjectId)
 *   - cursor (ISO date or ObjectId for “after” pagination)
 *   - limit (max 100)
 *
 * Returns: { messages: [], nextCursor }
 */
export async function getMessages({ roomId, cursor = null, limit = 50 }) {
  const query = { roomId: Types.ObjectId(roomId) };
  if (cursor) {
    query.createdAt = { $lt: new Date(cursor) };
  }

  const msgs = await Message.find(query)
    .sort({ createdAt: -1 })
    .limit(Math.min(limit, 100))
    .lean();

  const nextCursor = msgs.length ? msgs[msgs.length - 1].createdAt.toISOString() : null;
  return { messages: msgs, nextCursor };
}
```

### General Security Checklist for the Service Layer

| Concern | Mitigation |
|--------|------------|
| **NoSQL injection** | Never use raw strings for field names; always rely on Mongoose schema type casting. Use `$gt`, `$lt` only on validated numbers/dates. |
| **IDOR (Insecure Direct Object References)** | Always verify the caller’s permission (see `canReadRoom`/`canWriteRoom`). |
| **Rate‑limiting** | Use `express-rate-limit` (or similar) on authentication, message posting, and file upload endpoints. |
| **Replay / duplicate messages** | `clientMessageId` + unique index prevents processing the same client‑generated UUID twice. |
| **XSS** | Never store raw HTML in `Message.content`. Store plain text, escape on rendering (e.g., use a library like `DOMPurify` on the client side). |
| **CSRF** | If you use cookies for auth, set `SameSite=Strict` and use CSRF tokens for state‑changing routes. |
| **Logging** | Never log raw passwords, JWTs, or encryption keys. Use a structured logger with PII redaction. |
| **Error handling** | Return generic messages (`Invalid credentials`) to avoid user enumeration. Log detailed errors internally. |

