/* --------------------------------------------------------------
   3. Geriye gitme mantığı
   -------------------------------------------------------------- */
function goBack() {
    // --------------------- 1) En başa gelmiş miyiz? ---------------------
    if (KullanilanQuestion === 0 && durum === 'soru') {
        // İlk sorudayız, geri gidilemez
        return;
    }

    // --------------------- 2) Son gösterilen şey konu mu? ---------------------
    if (durum === 'konu') {
        // Şu an bir konu açıklaması gösteriliyor.
        // Geri basınca o konuyla ilişkili **soru**ya dön.
