Below is a **complete, security‑hardened and production‑ready rewrite** of the back‑end that talks smoothly with the HTML / JS you already have.  I kept the same functional surface (plain‑text chat + binary file broadcast) but added:

| Area | What was missing / insecure | What we add now |
|------|-----------------------------|-----------------|
| **WebSocket library** | `nodejs‑websocket` is very lightweight and gives you almost no safety nets (no origin validation, no per‑message size limits, no automatic binary handling). | Switch to the battle‑tested **`ws`** library (the de‑facto standard). |
| **Transport security** | Plain `ws://` – anyone on the same LAN can sniff or tamper with traffic. | Support **`wss://`** (TLS) out‑of‑the‑box; the same code works for both. |
| **Origin & IP validation** | Anyone can connect from any domain or IP. | Reject connections from unknown origins, add optional IP‑whitelisting. |
| **Message sanitisation** | Client can send raw HTML/JS that will be echoed to everyone → XSS. | Escape HTML before broadcasting (or send a JSON envelope and let the front‑end render safely). |
| **Rate‑limiting / DoS protection** | Unlimited `send` from any client → easy denial‑of‑service. | Token‑bucket per‑socket, max‑size caps for text and binary frames. |
| **Graceful error handling** | `conn.on('error')` just echoes the error back to the same client (might disclose internals). | Centralised error logging, generic error messages to the client. |
| **File‑size & type checks** | No limits – a malicious user could upload a GB of data. | Enforce a configurable max‑size (default 5 MiB) and optional mime‑type whitelist. |
| **Logging & observability** | Only console logs, no timestamps or structured data. | Structured JSON logs (timestamp, level, IP, event) – easy to ship to ELK / CloudWatch. |
| **Configuration** | Host/port hard‑coded, IP address embedded in code. | Use **environment variables** (`PORT`, `HOST`, `TLS_KEY`, `TLS_CERT`, `ALLOWED_ORIGINS`, …). |
| **Code quality** | Mixed‑scope functions, spelling errors (`boardcast`). | Clean module‑scoped functions, proper naming, async/await where appropriate. |
| **Client‑side integration** | Two `socket.onmessage` handlers (the second overwrites the first). | Keep a single, robust handler that deals with both text and binary frames. |
| **Async IP retrieval** | `ip` is set asynchronously but used synchronously in `send()`. | Return a Promise to guarantee the IP is known before sending. |

---

## 1️⃣ Updated Back‑End (Node .js)

> **File:** `server.js`

```js
/**
 * WebSocket chat server (text + binary file broadcast)
 * ----------------------------------------------------
 * Dependencies:
 *   npm i ws express helmet cors pino pino-http
 *
 * env vars (example):
 *   PORT=3000
 *   HOST=0.0.0.0                 # or a specific interface like 172.16.10.34
 *   TLS_KEY=/path/to/key.pem     # optional – enables wss
 *   TLS_CERT=/path/to/cert.pem   # optional – enables wss
 *   ALLOWED_ORIGINS=https://mychat.example.com
 *   MAX_TEXT_SIZE=1024           # bytes
 *   MAX_BINARY_SIZE=5242880      # 5 MiB
 *   RATE_LIMIT=10                # msgs per second per client
 */

'use strict';

// ------------------------------------------------------------------
// 1️⃣  Imports & configuration
// ------------------------------------------------------------------
const fs = require('fs');
const http = require('http');
const https = require('https');
const { WebSocketServer } = require('ws');
const express = require('express');
const helmet = require('helmet');
const cors = require('cors');
const pino = require('pino');
const pinoHttp = require('pino-http');

// ----- Runtime config ------------------------------------------------
const {
  PORT = 3000,
  HOST = '0.0.0.0',
  TLS_KEY,
  TLS_CERT,
  ALLOWED_ORIGINS,
  MAX_TEXT_SIZE = 1024,
  MAX_BINARY_SIZE = 5 * 1024 * 1024, // 5 MiB
  RATE_LIMIT = 10, // messages per second
} = process.env;

// ----- Logging --------------------------------------------------------
const logger = pino({ level: process.env.LOG_LEVEL || 'info' });

// ------------------------------------------------------------------
// 2️⃣  HTTP(S) server – only needed to host the WS endpoint.
// ------------------------------------------------------------------
const app = express();
app.use(helmet());
app.use(cors());                 // fine‑tune in production
app.use(pinoHttp({ logger }));

// A tiny health‑check endpoint (useful for orchestration platforms)
app.get('/healthz', (req, res) => res.send('OK'));

let httpServer;
if (TLS_KEY && TLS_CERT) {
  const tlsOptions = {
    key: fs.readFileSync(TLS_KEY),
    cert: fs.readFileSync(TLS_CERT),
  };
  httpServer = https.createServer(tlsOptions, app);
  logger.info('🔐 TLS enabled – WebSocket will be wss://');
} else {
  httpServer = http.createServer(app);
  logger.info('⚠️ TLS not configured – using ws:// (insecure)');
}

// ------------------------------------------------------------------
// 3️⃣  Helper utilities
// ------------------------------------------------------------------

// Simple HTML escaping (prevents XSS when we echo raw user input)
function escapeHTML(str) {
  return str.replace(/[&<>"'`=\/]/g, (c) => ({
    '&': '&amp;',
    '<': '&lt;',
    '>': '&gt;',
    '"': '&quot;',
    "'": '&#39;',
    '`': '&#x60;',
    '=': '&#x3D;',
    '/': '&#x2F;',
  })[c]);
}

// Rate‑limiter (token bucket per socket)
class RateLimiter {
  constructor(tokensPerInterval, intervalMs) {
    this.tokens = tokensPerInterval;
    this.maxTokens = tokensPerInterval;
    this.interval = intervalMs;
    this.lastRefill = Date.now();
  }

  consume(count = 1) {
    const now = Date.now();
    const elapsed = now - this.lastRefill;
    if (elapsed > this.interval) {
      const refill = Math.floor(elapsed / this.interval) * this.maxTokens;
      this.tokens = Math.min(this.tokens + refill, this.maxTokens);
      this.lastRefill = now;
    }
    if (this.tokens >= count) {
      this.tokens -= count;
      return true;
    }
    return false;
  }
}

// ------------------------------------------------------------------
// 4️⃣  Create the WebSocket server
// ------------------------------------------------------------------
const wss = new WebSocketServer({
  server: httpServer,
  // Only accept connections that present a matching `Origin` header.
  verifyClient: (info, done) => {
    if (ALLOWED_ORIGINS) {
      const origin = info.origin;
      const allowed = ALLOWED_ORIGINS.split(',').some((o) => o.trim() === origin);
      if (!allowed) {
        logger.warn({ origin }, 'Rejected connection – origin not allowed');
        return done(false, 401, 'Origin not allowed');
      }
    }
    // You could also whitelist source IPs here using info.req.socket.remoteAddress
    done(true);
  },
});

// Keep a Set of all live connections for easy broadcast
const connections = new Set();

// ------------------------------------------------------------------
// 5️⃣  Connection lifecycle
// ------------------------------------------------------------------
wss.on('connection', (ws, req) => {
  const clientIp = req.socket.remoteAddress;
  const rateLimiter = new RateLimiter(RATE_LIMIT, 1000); // 1 s window

  // Attach some metadata for later use
  ws.isAlive = true;
  ws.clientIp = clientIp;
  ws.rateLimiter = rateLimiter;
  connections.add(ws);

  logger.info({ ip: clientIp }, '🟢 New client connected');

  // ---- Ping/pong keep‑alive (detect dead sockets) -----------------
  ws.on('pong', () => (ws.isAlive = true));

  // ---- Text messages -------------------------------------------------
  ws.on('message', (data, isBinary) => {
    // ----------------------------------------------------------------
    // 1️⃣  Rate‑limit check
    // ----------------------------------------------------------------
    if (!ws.rateLimiter.consume()) {
      ws.send('⚠️ You are sending messages too quickly. Please slow down.');
      logger.warn({ ip: clientIp }, 'Rate‑limit exceeded');
      return;
    }

    // ----------------------------------------------------------------
    // 2️⃣  Size validation
    // ----------------------------------------------------------------
    if (isBinary) {
      if (data.length > MAX_BINARY_SIZE) {
        ws.send(`❌ File too large – max ${MAX_BINARY_SIZE / (1024 * 1024)} MiB`);
        logger.warn({ ip: clientIp, size: data.length }, 'Binary payload oversize');
        return;
      }
    } else {
      if (data.length > MAX_TEXT_SIZE) {
        ws.send(`❌ Message too long – max ${MAX_TEXT_SIZE} bytes`);
        logger.warn({ ip: clientIp, size: data.length }, 'Text payload oversize');
        return;
      }
    }

    // ----------------------------------------------------------------
    // 3️⃣  Sanitise & prepare the payload
    // ----------------------------------------------------------------
    const timestamp = new Date().toLocaleString();

    let payload;
    if (isBinary) {
      // For binary we just forward the ArrayBuffer as‑is, but wrap it in a small JSON envelope
      // so the client can differentiate between "chat" and "file" messages.
      payload = JSON.stringify({
        type: 'file',
        ts: timestamp,
        from: clientIp, // you could replace this with a nickname later
        size: data.length,
      });
      // First send the envelope (text), then the raw binary.
      broadcastText(payload);
      broadcastBinary(data);
    } else {
      const safeText = escapeHTML(data.toString());
      payload = `${timestamp} ${safeText}`;
      broadcastText(payload);
    }
  });

  // ---- Close handling ------------------------------------------------
  ws.on('close', (code, reason) => {
    connections.delete(ws);
    logger.info({ ip: clientIp, code, reason: reason?.toString() }, '🔴 Client disconnected');
  });

  // ---- Error handling -------------------------------------------------
  ws.on('error', (err) => {
    logger.error({ ip: clientIp, err }, 'WebSocket error');
    // Do NOT echo the raw error back to the client – it may contain internals.
    ws.send('❗ An unexpected error occurred on the server.');
  });
});

// ------------------------------------------------------------------
// 6️⃣  Broadcast helpers
// ------------------------------------------------------------------
function broadcastText(message) {
  for (const client of connections) {
    if (client.readyState === client.OPEN && typeof message === 'string') {
      client.send(message);
    }
  }
}

function broadcastBinary(buffer) {
  for (const client of connections) {
    if (client.readyState === client.OPEN) {
      client.send(buffer);
    }
  }
}

// ------------------------------------------------------------------
// 7️⃣  Keep‑alive ping loop (detect dead sockets)
// ------------------------------------------------------------------
const interval = setInterval(() => {
  for (const ws of connections) {
    if (ws.isAlive === false) {
      logger.warn({ ip: ws.clientIp }, 'Terminating stale connection');
      return ws.terminate();
    }
    ws.isAlive = false;
    ws.ping();
  }
}, 30000); // 30 s

wss.on('close', () => clearInterval(interval));

// ------------------------------------------------------------------
// 8️⃣  Start the HTTP(S) server
// ------------------------------------------------------------------
httpServer.listen(PORT, HOST, () => {
  const protocol = TLS_KEY && TLS_CERT ? 'wss' : 'ws';
  logger.info(
    `🚀 Server listening on ${protocol}://${HOST}:${PORT} – ${connections.size} client(s) connected`
  );
});
