class Card {
  /**
   * @param {string} suit  – can be a symbol (♥) or a name (hearts, Hearts)
   * @param {string|number} rank – e.g. 'A', 10, 'K'
   */
  constructor(suit, rank) {
    // ---- normalise suit -------------------------------------------------
    const lowered = typeof suit === 'string' ? suit.toLowerCase() : '';
    const symbol = SUIT_SYMBOLS[lowered] || suit;        // keep symbol if already provided
    if (!Object.values(SUIT_SYMBOLS).includes(symbol)) {
      throw new TypeError(`Invalid suit "${suit}"`);
    }
    this.suit = symbol;                                 // always a symbol

    // ---- normalise rank -------------------------------------------------
    const rankStr = String(rank).toUpperCase();
    if (!RANK_VALUE[rankStr]) {
      throw new TypeError(`Invalid rank "${rank}"`);
    }
    this.rank = rankStr;
    this.value = RANK_VALUE[rankStr];   // numeric value for easy sorting/comparison

    // Freeze the object – prevents accidental mutation & prototype attacks
    Object.freeze(this);
  }

  toString() {
    return `${this.rank}${this.suit}`;
  }
}
