// 4.  Base Combination – only holds meta‑data
// ---------------------------------------------------------------
class Combination {
  /**
   * @param {string} name   Human‑readable name
   * @param {number} id     Small integer used for tie‑breaking
   * @param {number} rank   Poker ranking (higher = better)
   */
  constructor(name, id, rank) {
    this.name = name;
    this.id = id;
    this.rank = rank;               // the higher the rank, the stronger the hand
    Object.freeze(this);
  }

  /** Override in subclasses – must return `{combination, cards}` or `null`. */
  static test(_cards) { return null; }
}
```

---

## 5️⃣  **TwoPairs** – the only hand we need for the demo  

```js
// ---------------------------------------------------------------
// 5.  TwoPairs implementation (robust + secure)
// ---------------------------------------------------------------
class TwoPairs extends Combination {
  constructor() {
    // In poker ranking: Two‑Pairs is weaker than Three‑of‑a‑Kind (rank 3) but stronger than a Pair (rank 1)
    super('Two Pairs', 2, 2);
  }

  /**
   * Detects two distinct pairs in a 5‑card hand.
   * @param {Card[]} cards – unsorted hand (must be 5 Card objects)
   * @returns {{combination: TwoPairs, cards: Card[]} | null}
   */
  static test(cards) {
    // ----- Defensive checks -------------------------------------------------
    if (!Array.isArray(cards) || cards.length !== 5) return null;
    for (const c of cards) {
      if (!(c instanceof Card)) return null;
    }

    // ----- Sort descending by numeric value -------------------------------
    const sorted = [...cards].sort((a, b) => b.value - a.value);

    // ----- Find all pairs (value → array of cards) -------------------------
    const groups = {};
    for (const c of sorted) {
      groups[c.value] ??= [];
      groups[c.value].push(c);
    }

    // Keep only groups that are at least a pair
    const pairValues = Object.keys(groups)
      .filter(v => groups[v].length >= 2)
      .map(v => Number(v))
      .sort((a, b) => b - a);           // highest pair first

    if (pairValues.length < 2) return null;   // need *two* distinct pairs

    // Take the two highest pairs
    const firstPair  = groups[pairValues[0]].slice(0, 2);
    const secondPair = groups[pairValues[1]].slice(0, 2);

    // Determine the kicker (best single card that is not part of the pairs)
    const used = new Set([...firstPair, ...secondPair]);
    const kicker = sorted.find(c => !used.has(c));

    // The final hand must be exactly 5 cards
    const resultCards = [...firstPair, ...secondPair, kicker];

    // Return a **new instance** of the combination (not the class itself)
    return {
      combination: new TwoPairs(),
      cards: resultCards
    };
  }
}
```

> **Why a new instance?**  
> `Combination.rank` is used for sorting winners. Returning the **class** (`TwoPairs`) broke the `hand.rank` comparison (`Combination.rank` is undefined on the class). An instance carries the proper `rank` field.

---

## 6️⃣  Helper that evaluates the *best* hand (still very minimal)  

```js
// ---------------------------------------------------------------
// 6.  getBestHand – tries the combos in ranking order
// ---------------------------------------------------------------
function getBestHand(cards) {
  // The list must be ordered from strongest → weakest.
  const combos = [
    // RoyalFlush, StraightFlush, FourOfAKind, FullHouse,
    // Flush, Straight, ThreeOfAKind,
    TwoPairs,   // for this demo we only have TwoPairs + Pair
    Pair       // placeholder – not implemented in this snippet
  ];

  for (const Combo of combos) {
    const result = Combo.test(cards);
    if (result) {
      // Attach the numeric rank to the result for later comparison.
      return {
        rank: result.combination.rank,
        combination: result.combination,
        cards: result.cards
      };
    }
  }
  // No recognized combination – treat as "high card"
  return {
    rank: 0,
    combination: null,
    cards: cards.sort((a, b) => b.value - a.value).slice(0, 5)
  };
}
```

---

## 7️⃣  `determineWinners` – now works with the repaired data model  

```js
// ---------------------------------------------------------------
// 7.  Determine winners from player hands + board cards
// ---------------------------------------------------------------
function determineWinners(playerHands, boardCards) {
  // Defensive validation – do *not* trust external data.
  if (!Array.isArray(playerHands) || !Array.isArray(boardCards) ||
      boardCards.length !== 5) {
    throw new TypeError('Invalid input to determineWinners');
  }

  // Every player hand is expected to be an array of 2 Card objects.
  playerHands.forEach(hand => {
    if (!Array.isArray(hand) || hand.length !== 2) {
      throw new TypeError('Each player hand must contain exactly 2 cards');
    }
    hand.forEach(assertCard);
  });
  boardCards.forEach(assertCard);

  // 1️⃣  Build full 7‑card sets (2 hole + 5 board)
  const allHands = playerHands.map(hand => [...hand, ...boardCards]);

  // 2️⃣  Compute the *best* 5‑card poker hand for each player
  const best = allHands.map(getBestHand);

  // 3️⃣  Find the highest rank among the players
  const maxRank = Math.max(...best.map(b => b.rank));

  // 4️⃣  Return every player that shares the top rank
  return best.reduce((winners, bh, idx) => {
    if (bh.rank === maxRank) {
      winners.push({
        playerId: idx,
        winningCombinationId: bh.combination ? bh.combination.id : null,
        winningCards: bh.cards
      });
    }
    return winners;
  }, []);
}
```

