  // -----------------------------------------------------------------
  const handOne = [
    new Card('spades',   'J'),
    new Card('clubs',    'J'),
    new Card('hearts',   'K'),
    new Card('diamonds', 'K'),
    new Card('spades',   'A')
  ];

  const expectedOne = {
    combination: twoPairs,
