      // Highest pair first → K‑K
      new Card('hearts',   'K'),
      new Card('diamonds', 'K'),
      // Then J‑J
      new Card('spades',   'J'),
      new Card('clubs',    'J'),
      // Finally kicker A
      new Card('spades',   'A')
    ]
  };

  const actualOne = TwoPairs.test(handOne);
  console.log('✔ Two separate pairs →', compareResults(actualOne, expectedOne));

  // -----------------------------------------------------------------
  // 8.2  Three pairs – we must pick the *two highest* (K‑K & 3‑3) + kicker
  // -----------------------------------------------------------------
  const handTwo = [
    new Card('spades',   '3'),
    new Card('clubs',    '3'),
    new Card('hearts',   'K'),
    new Card('diamonds', 'K'),
    new Card('spades',   'K')   // extra K to ensure we still have a kicker
  ];

  const expectedTwo = {
    combination: twoPairs,
    cards: [
      new Card('hearts',   'K'),   // top pair
      new Card('diamonds', 'K'),
      new Card('spades',   '3'),   // second pair
      new Card('clubs',    '3'),
      new Card('spades',   'K')    // kicker (the remaining K)
    ]
  };

  const actualTwo = TwoPairs.test(handTwo);
  console.log('✔ Three pairs →', compareResults(actualTwo, expectedTwo));

  // -----------------------------------------------------------------
  // 8.3  No two‑pairs
  // -----------------------------------------------------------------
  const handThree = [
    new Card('spades',   'A'),
    new Card('clubs',    '2'),
    new Card('hearts',   '5'),
    new Card('diamonds', '9'),
    new Card('spades',   'Q')
  ];
  console.log('✔ No two‑pairs →', TwoPairs.test(handThree) === null);
}

/**
 * Helper – deep‑compare only the *relevant* fields.
 * Equality of `Combination` objects is based on their `name`/`rank`.
 */
function compareResults(actual, expected) {
  if (actual === null) return false;
  // Compare combination metadata
  if (actual.combination.name !== expected.combination.name) return false;
  // Compare cards (order matters for poker hand ranking)
  if (actual.cards.length !== expected.cards.length) return false;
  for (let i = 0; i < actual.cards.length; i++) {
    if (actual.cards[i].toString() !== expected.cards[i].toString()) return false;
  }
  return true;
}

// Run the suite
testTwoPairs();
```

**Console output (when everything is correct)**  

