### 3.4 `utils/promptBuilder.js`

```js
// server/utils/promptBuilder.js

/**
 * Build a prompt for OpenAI that asks it to generate radiology quiz questions
 * based on the supplied parameters.
 *
 * @param {Object} opts
 * @param {string} opts.board - e.g. "ABR"
 * @param {string} opts.type - "multiple-choice" | "short-answer" | "image-description"
 * @param {string} opts.difficulty - "easy" | "intermediate" | "hard"
 * @param {number} opts.numQuestions - how many Qs to generate
 * @param {string} [opts.context] - optional user‑provided text (max 500 words)
 * @returns {string}
 */
export function buildPrompt({ board, type, difficulty, numQuestions, context }) {
    const typeMap = {
        'multiple-choice': 'multiple‑choice',
        'short-answer': 'short‑answer',
        'image-description': 'image description'
    };

    const difficultyMap = {
        easy: 'easy',
        intermediate: 'intermediate',
        hard: 'hard'
    };

    const boardMap = {
        ABR: 'American Board of Radiology (ABR)',
        ERC: 'European Radiology Council (ERC)',
        ACR: 'American College of Radiology (ACR)'
    };

    // Core instruction
    let prompt = `You are a board‑certified radiology educator. Create **${numQuestions}** ${typeMap[type]} questions ` +
        `for the ${boardMap[board]} board exam. ` +
        `The questions should be ${difficultyMap[difficulty]} in difficulty. `;

    // If the user supplied context, inject it
    if (context && context.length > 0) {
        prompt += `Use the following context as a reference:\n"""${context}"""\n`;
    }

    // Desired output format – easy to parse later
    prompt += `
Provide the output in **Markdown** as follows:

### Question 1
**Type:** ${typeMap[type]}
**Difficulty:** ${difficultyMap[difficulty]}
**Prompt:** <question text>

${type === 'multiple-choice' ? '**Options:**\n- A) ...\n- B) ...\n- C) ...\n- D) ...\n' : ''}
**Answer:** <concise answer or key>

---
Repeat for each question up to ${numQuestions}.
`;

    return prompt.trim();
}
```

The helper guarantees a **predictable markdown** structure, making it easy to display later.

