### 3.5 `server.js`

```js
// server/server.js
import express from 'express';
import cors from 'cors';
import helmet from 'helmet';
import rateLimit from 'express-rate-limit';
import { config } from 'dotenv';
import { OpenAI } from 'openai';
import validator from 'validator';
import path from 'path';
import { fileURLToPath } from 'url';
import { buildPrompt } from './utils/promptBuilder.js';

// Load .env (must happen before we use env vars)
config();

const __filename = fileURLToPath(import.meta.url);
const __dirname = path.dirname(__filename);

const PORT = process.env.PORT || 3000;
const OPENAI_API_KEY = process.env.OPENAI_API_KEY;
const CORS_ORIGIN = process.env.CORS_ORIGIN || `http://localhost:${PORT}`;

if (!OPENAI_API_KEY) {
    console.error('❌ Missing OPENAI_API_KEY in .env');
    process.exit(1);
}

// Initialise OpenAI client – SDK handles auth securely
const openai = new OpenAI({
    apiKey: OPENAI_API_KEY,
    // optional: set a custom timeout to prevent hanging requests
    timeout: 30_000
});

const app = express();

// ---- Security middle‑wares -------------------------------------------------
app.use(helmet()); // Sets many safe HTTP headers

// CORS – only allow our own origin (adjust if you serve client elsewhere)
app.use(cors({
    origin: CORS_ORIGIN,
    methods: ['GET', 'POST'],
    credentials: false
}));

// Rate limiting – mitigate abuse & accidental cost blow‑out
const limiter = rateLimit({
    windowMs: 60_000, // 1 minute
    max: 10,          // max 10 requests per IP per minute
    standardHeaders: true,
    legacyHeaders: false,
    message: { message: 'Too many requests, please slow down.' }
});
app.use('/api/', limiter);

// Body parsers – limit size to 10 KB (tiny JSON, prevents huge payloads)
app.use(express.json({ limit: '10kb' }));

// ---- Serve static frontend ------------------------------------------------
app.use(express.static(path.join(__dirname, '../client')));

// ---- Helper: simple input validation ---------------------------------------
function validateQuizRequest(body) {
    const errors = [];

    // Board – only whitelisted values
    const boards = ['ABR', 'ERC', 'ACR'];
    if (!boards.includes(body.board)) errors.push('Invalid board.');

    // Question type
    const types = ['multiple-choice', 'short-answer', 'image-description'];
    if (!types.includes(body.type)) errors.push('Invalid question type.');

    // Difficulty
    const diffs = ['easy', 'intermediate', 'hard'];
    if (!diffs.includes(body.difficulty)) errors.push('Invalid difficulty level.');

    // Number of questions – must be integer 1‑30 (reasonable upper limit)
    if (!Number.isInteger(body.numQuestions) || body.numQuestions < 1 || body.numQuestions > 30) {
        errors.push('Number of questions must be between 1 and 30.');
    }

    // Context – optional, but must be <= 500 words (≈ 3500 characters)
    if (body.context) {
        const trimmed = body.context.trim();
        const wordCount = trimmed.split(/\s+/).length;
        if (wordCount > 500) {
            errors.push('Context exceeds 500 words.');
        }
        // Sanitize – remove any stray HTML tags that might be injected
        body.context = validator.escape(trimmed);
    }

    return errors;
}

// ---- API endpoint ---------------------------------------------------------
app.post('/api/generate-quiz', async (req, res) => {
    const payload = req.body;

    // 1️⃣ Validate input
    const validationErrors = validateQuizRequest(payload);
    if (validationErrors.length) {
        return res.status(400).json({ message: validationErrors.join(' ') });
    }

    // 2️⃣ Build prompt
    const prompt = buildPrompt(payload);

    try {
        // 3️⃣ Call OpenAI – using the chat completion endpoint (GPT‑3.5‑Turbo, cheap & fast)
        const completion = await openai.chat.completions.create({
            model: 'gpt-3.5-turbo', // change to 'gpt-4' if you have access and want higher quality
            messages: [{ role: 'user', content: prompt }],
            temperature: 0.7,
            max_tokens: Math.min(2048, payload.numQuestions * 300) // rough limit
        });

        const quiz = completion.choices[0].message.content.trim();

        // 4️⃣ Respond
        return res.json({ quiz });
    } catch (err) {
        console.error('OpenAI error →', err);
        // NB: Do not echo raw OpenAI errors to the client – they may contain internal details.
        return res.status(500).json({ message: 'Failed to generate quiz. Please try again later.' });
    }
});

// ---- Global error handler (fallback) ---------------------------------------
app.use((err, req, res, next) => {
    console.error('Unhandled error →', err);
    res.status(500).json({ message: 'Internal server error.' });
});

// ---- Start server ---------------------------------------------------------
app.listen(PORT, () => {
    console.log(`🚀 Server listening on http://localhost:${PORT}`);
    console.log(`Serving static files from /client`);
});
```

**Key security points in the server code**

| Feature | Why it matters |
|---------|----------------|
| `dotenv` + **`.env` not committed** | API keys stay out of source control |
| `helmet()` | Sets security‑oriented HTTP headers (CSP, HSTS, X‑Content‑Type‑Options, etc.) |
| CORS restricted to a single origin | Prevents malicious websites from calling your endpoint |
| `express-rate-limit` (10/min/IP) | Thwarts token‑drain attacks / accidental cost explosion |
| Input validation & sanitisation (`validator.escape`) | Stops injection attacks, keeps payloads within expected bounds |
| `express.json({ limit: '10kb' })` | Rejects overly large bodies that could lead to DoS |
| Centralised error handling (no stack traces) | Avoids leaking internal details to the client |

Feel free to tighten any of these (e.g., add `express-mongo-sanitize`, Content‑Security‑Policy via Helmet, CSRF tokens, etc.) depending on your deployment environment.

