                e.preventDefault();
                afficherQuestionsDuQuestionnaire(q.url);
            });
        $li.append($a);
        $ul.append($li);
    }
    $container.append($ul);
}
```

### 2.3  Récupérer et afficher les questions d’un questionnaire  

