async function afficherQuestionsDuQuestionnaire(urlQuestionnaire) {
    try {
        const payload = await apiFetch(urlQuestionnaire);
        // `payload.questionnaire.questions` est une liste d’URL vers les questions
        const questionUrls = payload.questionnaire.questions;
        const questions = await Promise.all(questionUrls.map(apiFetch));
        remplirQuestions(questions);
    } catch (e) {
        onError(e);
    }
}

