```php
<?php
require_once __DIR__ . '/../init.php';
$user = current_user();

if (!$user || !$user['is_admin']) {
    die('Доступ запрещён.');
}

// Handle promote / demote / delete actions
if ($_SERVER['REQUEST_METHOD'] === 'POST' && verify_csrf($_POST['csrf'] ?? '')) {
    $action = $_POST['action'] ?? '';
    $uid    = (int)($_POST['uid'] ?? 0);

    if ($uid && $uid !== $user['id']) { // never affect self
        if ($action === 'promote') {
            $pdo->prepare('UPDATE users SET is_admin = 1 WHERE id = ?')->execute([$uid]);
        } elseif ($action === 'demote') {
            $pdo->prepare('UPDATE users SET is_admin = 0 WHERE id = ?')->execute([$uid]);
        } elseif ($action === 'delete') {
            $pdo->prepare('DELETE FROM users WHERE id = ?')->execute([$uid]);
        }
    }
}

// List users
$stmt = $pdo->query('SELECT id, username, email, is_admin, created_at FROM users ORDER BY created_at DESC');
$users = $stmt->fetchAll();
?>
