```php
<?php
session_start();

/* ---------- 1️⃣ CSRF token (omitted for brevity) ---------- */
// Assume a valid token check has already run.

/* ---------- 2️⃣ Receive and sanitise ---------- */
$name          = trim($_POST['name'] ?? '');
$age           = trim($_POST['age'] ?? '');
$favoriteColor = trim($_POST['favorite_color'] ?? '');

