if ($name === '')           $errors[] = 'Name required.';
if (!ctype_digit($age))    $errors[] = 'Age must be a number.';
if ($favoriteColor === '') $errors[] = 'Favorite colour required.';

if ($errors) {
    foreach ($errors as $e) echo "<p style='color:red;'>$e</p>";
    exit;
}

/* ---------- 3️⃣ Build associative array ---------- */
$survey = [
    'Name'          => $name,
    'Age'           => (int)$age,
    'Favorite Color'=> $favoriteColor,
];

/* ---------- 4️⃣ Generate HTML table using a for‑loop ---------- */
$keys   = array_keys($survey);
$rows   = count($keys);

echo '<h3>Table built with a for‑loop</h3>';
echo '<table border="1" cellpadding="5">';
for ($i = 0; $i < $rows; $i++) {
    $k = $keys[$i];
    $v = $survey[$k];
    echo "<tr><th>" . htmlspecialchars($k) . "</th>"
       . "<td>" . htmlspecialchars($v) . "</td></tr>";
}
echo '</table>';

/* ---------- 5️⃣ Same table using a while‑loop (Iterator) ---------- */
echo '<h3>Table built with a while‑loop (Iterator)</h3>';
echo '<table border="1" cellpadding="5">';

$it = new ArrayIterator($survey);
while ($it->valid()) {
    $k = $it->key();
    $v = $it->current();
