// via XHR/fetch, you need to allow it.  Adjust the Origin as needed.
header('Access-Control-Allow-Origin: https://your-main-site.com');
header('Content-Type: application/json; charset=utf-8');

/* ---- 1. Validate incoming parameter ---------------------------- */
if (!isset($_GET['brand'])) {
    http_response_code(400);
    echo json_encode(['error' => 'Missing brand parameter']);
    exit;
}
$brand = strtolower(trim($_GET['brand']));

/* ---- 2. Whitelist of brands and their assets ------------------ */
/* In a real production system you would probably store this in a DB
   or a secure configuration file.  Here we keep it static for clarity. */
$assetsMap = [
    'brand1' => [
        'logo'     => 'https://cdn.example.com/brand1/logo.png',
        'register' => 'https://brand1.example.com/daftar',
        'banner'   => 'https://cdn.example.com/brand1/main-banner.jpg',
