        'register' => 'https://brand2.example.com/daftar',
        'banner'   => 'https://cdn.example.com/brand2/main-banner.jpg',
    ],
    // add more brands as needed …
];

/* ---- 3. Look up the brand -------------------------------------- */
if (!array_key_exists($brand, $assetsMap)) {
    http_response_code(404);
    echo json_encode(['error' => 'Brand not found']);
    exit;
}

/* ---- 4. Return the JSON payload -------------------------------- */
echo json_encode($assetsMap[$brand], JSON_UNESCAPED_SLASHES | JSON_PRETTY_PRINT);
exit;

/* -------------------------------------------------------------- */
?>
```

