        .result {font-weight: bold; color: #006400;}
        .error  {color: #B22222;}
    </style>
</head>
<body>
    <h1>Secure Number Addition</h1>
    <?php if (empty($errors)): ?>
        <p class="result"><?= $output ?></p>
    <?php else: ?>
        <p class="error"><?= $output ?></p>
    <?php endif; ?>

    <hr>
    <h2>Try it out</h2>
    <form method="GET" action="">
        <label for="a">a:</label>
