        echo '</fieldset>';
    }

    public function checkAnswer($userAnswer): bool
    {
        // $userAnswer est un tableau (ou null)
        $userAnswer = (array) $userAnswer;
        sort($userAnswer);
        $expected = $this->correctChoices;
        sort($expected);
        return $userAnswer === $expected;
    }
}
