    {
        $this->db = Database::getConnection();
    }

    /*** ---------- SIGN‑UP ---------- ***/
    public function register(string $username, string $email, string $plainPassword): void
    {
        // 1️⃣ Validate / sanitise (basic, server‑side)
        $username = trim($username);
        $email    = filter_var(trim($email), FILTER_VALIDATE_EMAIL);
        if (!$email) {
            throw new Exception('Invalid e‑mail address.');
        }
        if (!preg_match('/^[a-zA-Z0-9_]{3,30}$/', $username)) {
            throw new Exception('Invalid username.');
        }
        if (strlen($plainPassword) < 8) {
            throw new Exception('Password must be at least 8 characters.');
        }

        // 2️⃣ Check for duplicates (unique constraints will also throw)
        $stmt = $this->db->prepare('SELECT id FROM users WHERE username = :u OR email = :e');
        $stmt->execute([':u' => $username, ':e' => $email]);
        if ($stmt->fetch()) {
            throw new Exception('Username or e‑mail already in use.');
        }

        // 3️⃣ Hash password (bcrypt/argon2id)
        $hash = password_hash($plainPassword, PASSWORD_DEFAULT);
        if ($hash === false) {
            throw new Exception('Password hashing failed.');
        }

        // 4️⃣ Insert user + generate verification token
        $token = bin2hex(random_bytes(32)); // 64‑char hex string
        $sql = 'INSERT INTO users (username, email, password_hash, verification_token)
                VALUES (:u, :e, :p, :t)';
        $stmt = $this->db->prepare($sql);
        $stmt->execute([
            ':u' => $username,
            ':e' => $email,
            ':p' => $hash,
