        if (!empty($user['lock_until'])) {
            $lockedUntil = new DateTime($user['lock_until']);
            $now = new DateTime();
            if ($now < $lockedUntil) {
                throw new Exception('Account is temporarily locked. Try again later.');
            }
        }

        // 3️⃣ Verify password
        $valid = password_verify($plainPassword, $user['password_hash']);

        // 4️⃣ If password is correct → reset counters & start session
        if ($valid) {
