start_secure_session();

$errors = [];

// If user already logged in, redirect to a protected area (example: dashboard.php)
if (!empty($_SESSION['user_id'])) {
    header('Location: dashboard.php');
    exit;
}

// Process login attempt
if ($_SERVER['REQUEST_METHOD'] === 'POST') {
    // 1️⃣ CSRF check
    if (!validate_csrf()) {
        $errors[] = 'Invalid CSRF token.';
    }

    // 2️⃣ Rate‑limit per IP (basic)
    $clientIp = $_SERVER['REMOTE_ADDR'] ?? 'unknown';
    if (!login_rate_limit($clientIp)) {
        $errors[] = 'Too many login attempts. Please try again later.';
    }

    // 3️⃣ Collect inputs
    $usernameOrEmail = trim($_POST['identifier'] ?? '');
    $password        = $_POST['password'] ?? '';

    if (empty($usernameOrEmail) || empty($password)) {
        $errors[] = 'Both fields are required.';
    }

    // 4️⃣ If still clean, verify credentials
    if (empty($errors)) {
        $pdo = get_pdo();

        // Retrieve user row by username OR email –
        // note the use of **named placeholders** to guard against injection.
        $stmt = $pdo->prepare(
            'SELECT id, username, password, failed_logins, lock_until
               FROM users
              WHERE username = :id OR email = :id
              LIMIT 1'
        );
        $stmt->execute([':id' => $usernameOrEmail]);
        $user = $stmt->fetch();

        // ---------- Account‑lockout handling ----------
        $now = new DateTimeImmutable('now', new DateTimeZone('UTC'));

        if ($user) {
            // Convert DB lock time to DateTimeImmutable
            $lockedUntil = $user['lock_until']
                ? new DateTimeImmutable($user['lock_until'], new DateTimeZone('UTC'))
                : null;

            if ($lockedUntil && $now < $lockedUntil) {
                $errors[] = 'Account locked. Try again later.';
                // No increment of failed_logins – we already know it's locked.
            } else {
                // ---------- Password verification ----------
                if (password_verify($password, $user['password'])) {
                    // SUCCESS → reset counters
                    $stmt = $pdo->prepare('UPDATE users SET failed_logins = 0, lock_until = NULL WHERE id = :id');
                    $stmt->execute([':id' => $user['id']]);

                    // Regenerate session ID *after* authentication
                    session_regenerate_id(true);
                    $_SESSION['user_id']   = $user['id'];
                    $_SESSION['username'] = $user['username'];

                    // Reset per‑IP rate limit
                    reset_login_attempts($clientIp);

                    header('Location: dashboard.php');
                    exit;
                } else {
                    // WRONG PASSWORD – increment failed counter
                    $newFailed = (int)$user['failed_logins'] + 1;
                    $lockUntil = null;
                    if ($newFailed >= MAX_FAILED_LOGINS) {
                        $lockUntil = $now->modify('+' . LOCKOUT_DURATION_SECONDS . ' seconds')
                                          ->format('Y-m-d H:i:s');
                        $errors[] = 'Account locked due to too many failed attempts.';
                    } else {
                        $errors[] = 'Invalid credentials.';
                    }

                    $stmt = $pdo->prepare(
                        'UPDATE users SET failed_logins = :fl, lock_until = :lu WHERE id = :id'
                    );
                    $stmt->execute([
                        ':fl' => $newFailed,
                        ':lu' => $lockUntil,
                        ':id' => $user['id'],
                    ]);
                }
            }
        } else {
            // Username/email not found – we deliberately give the same error
            $errors[] = 'Invalid credentials.';
        }
    }
}
