message = timestamp.encode() + b'.' + payload_json.encode()

signature = hmac.new(secret, message, hashlib.sha256).hexdigest()

headers = {
    "Content-Type": "application/json",
    "X-TS": timestamp,               # timestamp
    "X-SIG": signature               # подпись
