    $profilePicPath
);
if (!$stmt->execute()) {
    error_log('Execute failed: ' . $stmt->error);
    http_response_code(500);
    exit('Internal server error.');
}
$userId = $stmt->insert_id;
$stmt->close();

/* ---------- 4. Transmit data to analytics (cURL, HMAC) ---------- */
$analyticsData = [
    'uid'        => $userId,
    'username'   => $raw['username'],
    'email'      => $raw['email'],
    'age'        => $age,
    'interests'  => $filteredInterests,
    'ts'         => time()
];
$payloadJson = json_encode($analyticsData, JSON_UNESCAPED_UNICODE);
$hmac        = hash_hmac('sha256', $payloadJson, HMAC_SECRET);

/* cURL with strict TLS verification */
$ch = curl_init(ANALYTICS_ENDPOINT);
curl_setopt_array($ch, [
    CURLOPT_RETURNTRANSFER => true,
    CURLOPT_POST           => true,
    CURLOPT_HTTPHEADER     => [
        'Content-Type: application/json',
        'X-Payload-HMAC: ' . $hmac
    ],
    CURLOPT_POSTFIELDS     => $payloadJson,
    CURLOPT_SSL_VERIFYPEER => true,
    CURLOPT_SSL_VERIFYHOST => 2,
    CURLOPT_TIMEOUT        => 5
]);
$response = curl_exec($ch);
$curlErr  = curl_error($ch);
curl_close($ch);
if ($response === false) {
    error_log('Analytics post failed: ' . $curlErr);
    // Not fatal – continue, but optionally retry or queue.
}

/* ---------- 5. Success page (escaped output) ---------- */
?>
