## 3. `upload.php`

```php
<?php
require 'config.php';

// -------------------------------------------------------------------
// Helper functions
// -------------------------------------------------------------------
function jsonError($msg, $code = 400) {
    http_response_code($code);
    echo json_encode(['success' => false, 'error' => $msg]);
    exit;
}
function jsonSuccess($data = []) {
    echo json_encode(array_merge(['success' => true], $data));
    exit;
}

// -------------------------------------------------------------------
// Simple admin check (used for delete & admin panel)
// -------------------------------------------------------------------
function isAdmin() {
    return isset($_SESSION['admin']) && $_SESSION['admin'] === true;
}
function requireAdmin() {
    if (!isAdmin()) {
        jsonError('Authentication required', 401);
    }
}

// -------------------------------------------------------------------
// Routing based on "action" POST field
// -------------------------------------------------------------------
$action = $_POST['action'] ?? '';

switch ($action) {
    case 'upload':
        // 1️⃣  Validate upload
        if (!isset($_FILES['file'])) {
            jsonError('No file sent');
        }

        $file   = $_FILES['file'];
        $name   = basename($file['name']);
        $size   = $file['size'];
        $tmp    = $file['tmp_name'];
        $error  = $file['error'];

        if ($error !== UPLOAD_ERR_OK) {
            jsonError('Upload error (code '.$error.')');
        }

        // 2️⃣  Size check
        if ($size > $maxFileSize) {
            jsonError('File exceeds allowed size ('.($maxFileSize/1024/1024).' MiB)');
        }

        // 3️⃣  Extension whitelist
        $ext = strtolower(pathinfo($name, PATHINFO_EXTENSION));
        if (!in_array($ext, $allowedExtensions, true)) {
            jsonError('Extension not allowed');
        }

        // 4️⃣  Create a unique filename to avoid clashes & path traversal
        $unique = bin2hex(random_bytes(12));
        $newName = $unique . '.' . $ext;
        $dest = UPLOAD_DIR . '/' . $newName;

        if (!move_uploaded_file($tmp, $dest)) {
            jsonError('Failed to move uploaded file');
        }

        // 5️⃣  Store meta‑info (original name, expiry timestamp) in a simple JSON file
        $meta = [
            'original' => $name,
            'uploaded' => time(),
            'expires'  => time() + (int)($_POST['retention'] ?? DEFAULT_RETENTION_DAYS) * 86400,
        ];
        file_put_contents(UPLOAD_DIR . '/' . $unique . '.json', json_encode($meta));

        jsonSuccess(['filename' => $newName, 'original' => $name]);

        break;

    case 'delete':
        requireAdmin();               // only admins may delete via API
        $id = $_POST['id'] ?? '';
        if (!preg_match('/^[a-f0-9]{24}$/', $id)) {
            jsonError('Invalid identifier');
        }

        $filePath = UPLOAD_DIR . '/' . $id . '.' . pathinfo($id, PATHINFO_EXTENSION);
        $metaPath = UPLOAD_DIR . '/' . $id . '.json';

        // Files may have any allowed extension – we look for the real file by globbing
        $matches = glob(UPLOAD_DIR . '/' . $id . '.*');
        foreach ($matches as $match) {
            if (is_file($match)) {
                unlink($match);
            }
        }
        if (file_exists($metaPath)) {
            unlink($metaPath);
        }

        jsonSuccess(['deleted' => $id]);
        break;

    default:
        jsonError('Invalid action', 400);
}
?>
```

