            $tableBody.empty();
            $.each(data.files, function (_, f) {
                const row = $('<tr>');
                row.append($('<td>').text(f.original));
                row.append($('<td>').text(f.expires));
                row.append($('<td>').html(
                    `<a class="btn btn-sm btn-outline-primary" href="download.php?id=${f.id}">Download</a>`
                ));
                $tableBody.append(row);
            });
        });
    }

    // -----------------------------------------------------------------
    // Submit upload via AJAX
    // -----------------------------------------------------------------
    $form.on('submit', function (e) {
        e.preventDefault();
        const formData = new FormData(this);
        formData.append('action', 'upload');
        $status.text('Uploading...');

        $.ajax({
            url: 'upload.php',
            type: 'POST',
            data: formData,
            processData: false,
            contentType: false,
            dataType: 'json',
            success: function (resp) {
                if (resp.success) {
