 * Cron job: delete files whose retention period has elapsed.
 *
 * Add to crontab, e.g.:
 *   0 3 * * * /usr/bin/php /path/to/filehost/retention.php
 */
require 'config.php';

foreach (glob(UPLOAD_DIR . '/*.json') as $metaPath) {
    $id = basename($metaPath, '.json');
    $meta = json_decode(file_get_contents($metaPath), true);
    if (isset($meta['expires']) && time() > $meta['expires']) {
        // Remove the data file(s)
        foreach (glob(UPLOAD_DIR . '/' . $id . '.*') as $f) {
            @unlink($f);
        }
        // Remove the meta file (already done by the loop)
        @unlink($metaPath);
        // (Optional) log the deletion
        error_log("Deleted expired file $id");
    }
}
