declare(strict_types=1);
session_start();
require_once __DIR__ . '/csrf_token.php';

/* ------------------- 1️⃣ Input sanity checks ------------------- */
$required = ['operand1', 'operand2', 'operator', 'csrf_token'];
foreach ($required as $key) {
    if (!isset($_POST[$key])) {
        http_response_code(400);
        exit('Missing required field: '.$key);
    }
}

/* Validate CSRF token */
if (!verify_csrf_token($_POST['csrf_token'])) {
    http_response_code(403);
    exit('Invalid CSRF token.');
}

/* Whitelist allowed operators – this prevents injection attacks */
$allowedOps = ['+', '-', '*', '/', '^', 'sqrt'];
$operator = $_POST['operator'];
if (!in_array($operator, $allowedOps, true)) {
    http_response_code(400);
    exit('Unsupported operator.');
}

/* Sanitize numbers – we cast to float, which rejects non‑numeric strings */
$operand1 = filter_var($_POST['operand1'], FILTER_VALIDATE_FLOAT);
$operand2 = filter_var($_POST['operand2'], FILTER_VALIDATE_FLOAT);
if ($operand1 === false || $operand2 === false) {
    http_response_code(400);
    exit('Operands must be numeric.');
}

/* ------------------- 2️⃣ Perform the calculation ------------------- */
function calculate(float $a, float $b, string $op): float {
    switch ($op) {
        case '+':  return $a + $b;
        case '-':  return $a - $b;
        case '*':  return $a * $b;
        case '/':  
            if ($b == 0.0) {
                throw new DivisionByZeroError('Division by zero');
            }
            return $a / $b;
        case '^':  return pow($a, $b);
        case 'sqrt':
            // sqrt(a) where b is the index (e.g., 2 = square root)
            if ($b == 0) {
                throw new InvalidArgumentException('Root index cannot be zero');
            }
            // Use pow with 1/b to get the b‑th root
            return pow($a, 1 / $b);
        default:
            // This is *theoretically* unreachable because of the whitelist.
            throw new UnexpectedValueException('Operator not allowed');
    }
}

try {
    $result = calculate((float)$operand1, (float)$operand2, $operator);
} catch (Throwable $e) {
    // Log the error – never expose stack traces to the client.
    error_log('Calculator error: '.$e->getMessage());
    http_response_code(400);
    exit('Invalid mathematical operation.');
}

/* ------------------- 3️⃣ Safe output handling ------------------- */
/* We use a PRG (Post‑Redirect‑Get) pattern to avoid form resubmission. */
$escapedResult = rawurlencode((string)$result);   // safe for query string
header('Location: index.html?result=' . $escapedResult);
exit;
```

