    die('❌ Could not fetch the video.');
}

// Choose a safe filename
$filename = basename(parse_url($remoteUrl, PHP_URL_PATH));
$localPath = __DIR__ . '/downloads/' . $filename;

// Write to disk
if (file_put_contents($localPath, $videoData) === false) {
    die('❌ Failed to write the file.');
}

echo "✅ Video saved to $localPath\n";
