    <!-- OPTIONAL: CSP that only allows images & links from the assets host -->
    <meta http‑equiv="Content‑Security‑Policy"
          content="default-src 'self'; img-src https://assets.example.com; a href https://assets.example.com;">
</head>
<body>
    <h1>Welcome to the <?= htmlspecialchars($brand) ?> page</h1>

    <!-- Logo -->
    <section id="logo">
        <img src="<?= htmlspecialchars($logoUrl) ?>" alt="<?= htmlspecialchars($brand) ?> Logo"
             style="max-width:200px;">
    </section>

    <!-- Main Banner -->
    <section id="banner">
        <img src="<?= htmlspecialchars($bannerUrl) ?>" alt="<?= htmlspecialchars($brand) ?> Banner"
             style="width:100%; max-height:300px; object-fit:cover;">
    </section>

