```javascript
// client/main.js
(() => {
  const API_BASE = 'http://localhost:3000'; // 后端地址（请保证与 CORS 配置匹配）
  const REFRESH_INTERVAL = 5000; // 5 秒轮询一次

  /** 读取 CSRF token 并写入请求头 */
  async function fetchCsrfToken() {
    const resp = await fetch(`${API_BASE}/api/csrf-token`, {
      credentials: 'include' // 必须发送 Cookie，才能拿到 XSRF-TOKEN
    });
    if (!resp.ok) throw new Error('Failed to get CSRF token');
    const data = await resp.json();
    // 我们把 token 同时存入全局变量，后面请求时使用自定义 Header
    return data.csrfToken;
  }

  /** 执行一次获取状态的 Ajax 调用 */
  async function fetchStatus(csrfToken) {
    const resp = await fetch(`${API_BASE}/api/status`, {
      method: 'GET',
      credentials: 'include', // 发送 Cookie（包括 XSRF-TOKEN）
      headers: {
        'X-XSRF-TOKEN': csrfToken // 双重提交的 Header
      }
    });
    if (!resp.ok) {
      const err = await resp.json().catch(() => ({}));
      throw new Error(err.error || `HTTP ${resp.status}`);
    }
    return resp.json(); // { temperature: '23.5', timestamp: '2024-06-01T12:34:56.789Z' }
  }

  /** 更新页面 DOM（使用 textContent 防止 XSS） */
  function render(data) {
    document.getElementById('temp').textContent = data.temperature;
    // 将 ISO 时间转成本地可读格式
    const local = new Date(data.timestamp).toLocaleString();
    document.getElementById('time').textContent = local;
    document.getElementById('error').textContent = '';
  }

  /** 主循环 */
  async function startPolling() {
    try {
      const csrfToken = await fetchCsrfToken(); // 第一次获取 CSRF
      // 初次渲染
      const first = await fetchStatus(csrfToken);
      render(first);
      // 设置轮询
      setInterval(async () => {
        try {
          const data = await fetchStatus(csrfToken);
          render(data);
        } catch (e) {
          console.error('Polling error:', e);
          document.getElementById('error').textContent = `轮询错误：${e.message}`;
        }
      }, REFRESH_INTERVAL);
    } catch (e) {
      console.error('Init error:', e);
      document.getElementById('error').textContent = `初始化错误：${e.message}`;
    }
  }

  // 页面加载完成后启动
  window.addEventListener('DOMContentLoaded', startPolling);
})();
```

