## 4. Script PHP complet  

```php
#!/usr/bin/env php
<?php
/**
 * backup.php – backup automatisé d'une base MySQL
 *
 * 1. Charge la configuration sécurisée.
 * 2. Construit la commande mysqldump.
 * 3. Exécute la commande via exec().
 * 4. Compresse, chiffre (optionnel) et stocke le dump.
 * 5. Gère la rotation des fichiers.
 *
 * @author  VotreNom
 * @date    2024‑06‑xx
 */

declare(strict_types=1);

error_reporting(E_ALL);
ini_set('display_errors', '0');

// ------------------------------------------------------------
// 1. Chargement configuration
// ------------------------------------------------------------
$configFile = __DIR__ . '/config/db_credentials.php';
if (!file_exists($configFile)) {
    fwrite(STDERR, "FICHIER DE CONFIGURATION INEXISTANT : $configFile\n");
    exit(1);
}
$db = require $configFile;

// ------------------------------------------------------------
// 2. Paramètres du backup
// ------------------------------------------------------------
$backupDir   = '/var/backups/mysql';                 // À sécuriser (chmod 750, owned www-data)
$rotateDays  = 30;                                   // Nombre de jours à conserver
$dateSuffix  = (new DateTime('now', new DateTimeZone('UTC')))->format('Ymd_His');
$filename    = sprintf('%s_%s.sql', $db['database'], $dateSuffix);
$filepath    = "$backupDir/$filename";
$gzFilepath  = $filepath . '.gz';                    // Après compression

// ------------------------------------------------------------
// 3. Construction de la commande mysqldump
// ------------------------------------------------------------
$command = sprintf(
    'mysqldump --host=%s --port=%d --user=%s --password=%s %s --single-transaction --quick --skip-lock-tables 2>/dev/null',
    escapeshellarg($db['host']),
    (int)$db['port'],
    escapeshellarg($db['user']),
    escapeshellarg($db['password']),
    escapeshellarg($db['database'])
);

// ------------------------------------------------------------
// 4. Exécution et capture du dump
// ------------------------------------------------------------
$dump = null;
exec($command, $output, $returnVar);
if ($returnVar !== 0) {
    fwrite(STDERR, "Erreur mysqldump (code $returnVar)\n");
    exit(2);
}
$dump = implode("\n", $output);

// ------------------------------------------------------------
// 5. Écriture du dump dans un fichier temporaire
// ------------------------------------------------------------
$tempFile = tempnam(sys_get_temp_dir(), 'mysqldump_');
if ($tempFile === false) {
    fwrite(STDERR, "Impossible de créer un fichier temporaire\n");
    exit(3);
}
file_put_contents($tempFile, $dump);

// ------------------------------------------------------------
// 6. Compression (gzip) – on préfère la compression système
// ------------------------------------------------------------
$gzCommand = sprintf('gzip -c %s > %s', escapeshellarg($tempFile), escapeshellarg($gzFilepath));
exec($gzCommand, $gzOut, $gzRet);
unlink($tempFile);   // nettoie le fichier brut
if ($gzRet !== 0) {
    fwrite(STDERR, "Erreur during gzip compression (code $gzRet)\n");
    exit(4);
}

// ------------------------------------------------------------
// 7. (Optionnel) Chiffrement du fichier compressé
// ------------------------------------------------------------
$useEncryption = true;   // passer à false si vous ne voulez pas chiffrer
if ($useEncryption) {
    $key    = getenv('BACKUP_ENC_KEY');          // 256‑bit key (base64)
    if ($key === false) {
        fwrite(STDERR, "Variable d'environnement BACKUP_ENC_KEY non définie\n");
        exit(5);
    }
    $key    = base64_decode($key, true);
    if ($key === false || strlen($key) !== 32) {
        fwrite(STDERR, "Clé de chiffrement invalide (doit être 32 bytes base64)\n");
        exit(5);
    }

    $encryptedFile = $gzFilepath . '.enc';
    $iv = random_bytes(openssl_cipher_iv_length('aes-256-gcm'));

    $ciphertext = openssl_encrypt(
        file_get_contents($gzFilepath),
        'aes-256-gcm',
        $key,
        OPENSSL_RAW_DATA,
        $iv,
        $tag,
        '',
        16
    );
    if ($ciphertext === false) {
        fwrite(STDERR, "Erreur openssl_encrypt\n");
        exit(5);
    }

    // Format du fichier : IV (12B) | TAG (16B) | CIPHERTEXT
    $payload = $iv . $tag . $ciphertext;
    file_put_contents($encryptedFile, $payload);
    // On supprime le .gz non chiffré
    unlink($gzFilepath);
    $gzFilepath = $encryptedFile;
}

// ------------------------------------------------------------
// 8. Upload vers un stockage distant (ex. S3) – optionnel
// ------------------------------------------------------------
$uploadToS3 = false;
if ($uploadToS3) {
    // Exemple minimal avec AWS SDK for PHP v3
    require '/path/to/vendor/autoload.php';
    use Aws\S3\S3Client;

    $s3 = new S3Client([
        'region'  => 'eu-west-1',
        'version' => 'latest',
        'credentials' => [
            'key'    => getenv('AWS_ACCESS_KEY_ID'),
            'secret' => getenv('AWS_SECRET_ACCESS_KEY')
        ]
    ]);

    $bucket = 'my-mysql-backups';
    $key    = basename($gzFilepath);
    try {
        $s3->putObject([
            'Bucket' => $bucket,
            'Key'    => $key,
            'SourceFile' => $gzFilepath,
            'ServerSideEncryption' => 'AES256',
        ]);
    } catch (Exception $e) {
        fwrite(STDERR, "Erreur d'upload S3 : " . $e->getMessage() . "\n");
        // On ne sort pas forcément, le fichier local reste disponible.
    }
}

// ------------------------------------------------------------
// 9. Rotation – suppression des backups > $rotateDays
// ------------------------------------------------------------
$files = glob("$backupDir/*");
$now   = time();
foreach ($files as $file) {
    if (!is_file($file)) {
        continue;
    }
    $age = $now - filemtime($file);
    if ($age > ($rotateDays * 86400)) {
        unlink($file);
        // Optionnel : log de suppression
    }
}

// ------------------------------------------------------------
// 10. Fin
// ------------------------------------------------------------
echo "Backup terminé : $gzFilepath\n";
exit(0);
